pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than linearly.
    // A gap that cannot hold even the smallest future item (<=100) is "dead";
    // gaps in the mid-range (1..=30) are the worst offenders.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual <= 30 {
            // unusable dead space: heavy quadratic penalty
            score += (31.0 - pr) * (31.0 - pr) * 1.5;
        } else if post_residual <= 60 {
            // partially usable gap: mild penalty scaled by fill quality
            score += (60.0 - pr) * 0.3;
        } else {
            // large residual: slight bonus for keeping bins roomy
            score -= 5.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Prefer bins that are already well-filled (low bin_residual relative to capacity).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 4.0;

    // Last-chance bin: strongly reward using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item would leave a terrible gap everywhere.
    if bin_residual == bin_capacity {
        let gap_bad = post_residual > 0 && post_residual <= 30;
        if fitting_bins_count == 0 || (gap_bad && next_item_size > post_residual) {
            score -= 35.0; // opening a new bin is justified
        } else {
            score += 30.0 + pressure * 6.0; // discourage proliferation
        }
    }

    // Lookahead coupling: reward leaving a gap that fits the next item,
    // penalize gaps that almost-but-don't fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size.saturating_sub(10) {
            score += 10.0; // near-miss gap is wasted potential
        }
    }

    // Slight preference for bins with residual close to mean (avoid fragmenting outliers)
    score -= (mean_residual - bin_residual as f64).abs() * -0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit preference (smaller post-residual = tighter fit = lower score).
    // Squared coupling emphasizes tight fits, but only when the leftover stays usable.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = pr / cap;

    // Dead-space penalty: leftover that is too small to reliably host a future item
    // is wasted capacity. Penalize quadratically as post_residual approaches 0.
    if post_residual < 10 {
        score += (10.0 - pr) * 40.0;
    } else if post_residual < 20 {
        score += (20.0 - pr) * 8.0;
    }

    // Lookahead reward: if the next item fits exactly-ish in the leftover,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 + 20.0 * (1.0 - slack / cap);
    }
    // Lookahead penalty: next item is large and would NOT fit here,
    // meaning this bin may become stranded; mildly penalize near-full bins.
    if next_item_size > post_residual && post_residual < 15 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item, using it
    // avoids opening a new bin — reward strongly unless it creates dead space.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 35.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidating into existing bins (avoid bin proliferation).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation = (mean_residual - pr) * 0.15 * (1.0 + open_bins_count as f64 / 20.0);
    score += consolidation;

    // Time horizon: late in the stream, avoid opening new bins and squeeze
    // items into existing space more aggressively.
    score -= t * 10.0 * (1.0 - frac);

    // Mild preference for bins whose residual was already moderate
    // (avoid burning large empty bins on small items early).
    if bin_residual as f64 > mean_residual + 30.0 && item_size < 40 {
        score += 12.0;
    }

    // New-bin candidate guard: an empty bin (residual == capacity) must NOT
    // win when a reasonable fit exists in an open bin. Its base score is
    // already high (large post_residual); add extra deterrence unless the
    // item is huge relative to what open bins could absorb.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let waste = (bin_capacity - item_size) as f64;
        score += 15.0 + 0.2 * waste;
        // But if the item would leave near-zero dead space anywhere, the
        // dead-space penalty above already dominates — no extra guard needed.
        if item_size >= 90 {
            score -= 40.0; // huge items: a fresh bin is often genuinely best
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse if it falls in
    // "unusable" classes (smaller than the smallest plausible item).
    let min_item = 1u32.max(item_size.min(80)).min(20);
    if post_residual > 0 && post_residual < min_item {
        score += 500.0; // unusable sliver: heavy penalty
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 are more reusable
    // (items drawn on a 1..100 grid often cluster on round sizes).
    let r10 = post_residual % 10;
    score -= (10 - r10) as f64 * 2.0; // reward residuals near a multiple of 10

    // Integer-division thresholds on post_residual: classify leftover size.
    let class = post_residual / 25; // 0..4 harmonic quarters
    score += class as f64 * 1.5;    // prefer bins leaving small leftovers

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chained tight packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 30.0;
            // harmonic match: post_residual and next item share a divisor class
            let combined = post_residual - next_item_size;
            if combined % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; slight penalty for stranded residual
            score += 10.0 + (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
        if post_residual <= 15 {
            score -= 100.0; // tight last-chance fit is great
        }
    }

    // New-bin candidate handling: penalize opening a new bin when the stream is
    // young or few bins are open; relax later when open bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 120.0
            - 60.0 * progress
            + 40.0 * fragmentation
            + (open_bins_count as f64).sqrt() * 5.0;
        if fitting_bins_count == 0 {
            score -= 300.0; // no open bin fits: opening is mandatory
        }
    }

    // Mild preference for filling fuller bins (relative fill ratio coupling).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Tie-breaker noise-free harmonic dither on bin index proxy (open_bins_count).
    score += (open_bins_count % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 bins capture "small leftover" structure.
    let post_class = (post_residual % 10) as f64;
    score += 0.35 * post_class;

    // Dead-space penalty: residuals too small for typical items (<=10) are nearly worthless.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Fractional fill ratio coupling: reward tight fits via integer-division threshold.
    let fill_ratio = (bin_residual - post_residual) as f64 / cap;
    if fill_ratio > 0.9 {
        score -= 25.0;
    } else if fill_ratio > 0.7 {
        score -= 10.0;
    }

    // Lookahead harmony: if next item divides evenly into post_residual (harmonic class match),
    // this bin is extra valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack % 10 == 0 {
            score -= 12.0;
        }
        if slack < 10 {
            score += 8.0; // leaves near-dead space for the item after next
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post residual cannot host next item; mildly penalize if it is stranded small space
        if post_residual < next_item_size / 2 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should lose unless current bins are crowded
    // or the fit here is bad.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * mean_residual - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 15.0; // big next item: keep fresh bins available
        }
    }

    // Stream progression: late in the stream, consolidate harder (avoid opening bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that land in
    // "friendly" classes (multiples of small divisors) which future items
    // are likely to fill exactly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class bonuses via integer division thresholds.
        if post_residual % 10 == 0 { score -= 18.0; }
        if post_residual % 5 == 0 { score -= 7.0; }
        if post_residual % 25 == 0 { score -= 12.0; }
        if post_residual % 50 == 0 { score -= 20.0; }

        // Dead-space penalty for tiny unusable leftovers.
        if post_residual < 10 {
            score += 60.0 * (10 - post_residual) as f64;
        } else if post_residual < 20 {
            score += 15.0 * (20 - post_residual) as f64;
        }

        // Sweet spot: residual close to half capacity is highly reusable.
        let half = cap * 0.5;
        let dist_half = (pr - half).abs();
        score += 0.25 * dist_half;

        // Coupling with lookahead: if next item fits the post-residual
        // exactly or nearly, reward strongly.
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if next_item_size == post_residual {
                score -= 400.0;
            } else if next_item_size < post_residual {
                let rem2 = post_residual - next_item_size;
                score -= 60.0 - 2.0 * rem2.min(30) as f64;
                if rem2 % 10 == 0 { score -= 10.0; }
            } else {
                // Next item won't fit here: penalize large leftover waste.
                score += 0.3 * pr;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 90.0;
        }

        // New-bin candidate: only attractive when the item is large relative
        // to capacity (poor fit candidates elsewhere) or stream is early.
        if bin_residual == bin_capacity {
            let large_item = (item_size as f64) / cap;
            let progress = step_index as f64 / (total_items.max(1) as f64);
            let new_bin_bias = 40.0 - 30.0 * large_item - 20.0 * (1.0 - progress);
            score += new_bin_bias;
            // Opening a bin for a small item is wasteful.
            if item_size <= 25 { score += 80.0; }
        }

        // Prefer tighter bins among equals: compare against mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }

        // Mild dispersion penalty: keep residuals diverse, not all tiny.
        if open_bins_count > 0 && frac < 0.15 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual <= 15 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements in bins when many bins are open,
    // pushing toward consolidation into fewer bins.
    score += 0.35 * open_bins_count as f64;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item would leave another dead gap, penalize slightly.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
        score += 6.0;
    }

    // New-bin candidate: neutral baseline with mild pressure term so that
    // opening a new bin is chosen only when existing bins score poorly.
    if bin_residual == bin_capacity {
        score = 15.0 + 0.35 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable
    // (min item size is 1, but tiny gaps waste capacity); penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward using a nearly-full bin (tight packing pressure).
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if post_residual is small but nonzero and next item can't use it.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 10.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, prefer filling existing.
    score += (open_bins_count as f64) * 0.5;

    // Mean residual coupling: if this bin's residual is far below mean, it's an outlier
    // worth filling; if above mean, mild penalty.
    let residual_f = bin_residual as f64;
    score += 0.3 * (residual_f - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    // Give it a moderate baseline so it loses against good fits but wins
    // when all open bins would create dead space.
    if bin_residual == bin_capacity {
        score = 35.0 + (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large gaps.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0; // tiny gap = wasted space forever
        } else if post_residual <= 20 {
            score += 18.0;
        } else if post_residual <= 30 {
            score += 6.0;
        } else {
            score -= 5.0; // large residual remains usable
        }
    } else {
        score -= 60.0; // perfect fit, close the bin
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Last-chance bonus: only one bin fits the item, use it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins with below-mean residual (consolidate emptier bins? prefer fuller bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit in post_residual, small penalty for stranding it.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: empty bin is a fallback, only attractive when
    // no good fit exists (large item relative to residuals).
    if bin_residual == bin_capacity {
        let desperation = (item_size as f64 / bin_capacity as f64).powi(2);
        score = 55.0 - 45.0 * desperation;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // new bin leaves room for lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // next item could also fit here; mild penalty for wasting that chance
            score -= 50.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // dead space below next item size: penalize small unusable leftovers
            score += 30.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when residuals across open bins are small.
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        score -= 80.0 * avg_tightness;
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 60.0; // nothing open can hold the future well
        }
    }

    // Late-stream consolidation: prefer reusing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harshly (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual > 60 {
        score += 8.0; // wasteful large leftover
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin bonus: avoid opening new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open bin pressure: with many open bins, prefer packing into existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 - mean_residual / 10.0) * (0.3 + 0.5 * progress);

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 && (post_residual as u32) < next_item_size {
        score += 10.0; // blocks next item
    }

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 5.0;
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item (1) are pure waste,
    // but gaps too small for typical items are heavily penalized.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64; // unusable sliver
    }

    // Penalize mid-range gaps that likely can't fit the next item (lookahead-aware).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits: small post_residual relative to item size.
    score -= 2.0 * item_size as f64 / (post_residual as f64 + 5.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Pressure from many open bins: discourage spreading items across bins.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins with below-average residual (denser bins) when many bins are open.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: only attractive when current bin would leave a bad gap
    // or no bin fits well; an empty bin is flexible for the future.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        // Opening a new bin is cheap early, expensive late in the stream.
        score += 10.0 * (1.0 - step_index as f64 / (total_items.max(1) as f64));
        // Discourage new bin if a decent fit exists elsewhere.
        if post_residual == 0 || (next_item_size > 0 && post_residual >= next_item_size) {
            score += 30.0;
        }
        // Favor new bin when open-bin pressure is high.
        score -= 0.5 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 35.0; // don't open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward very tight fits (post_residual tiny relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.6 + 0.8 * progress);

    // If next item would fit into the post_residual, reward leaving useful space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post_residual too small for next item: penalize proportionally.
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // New-bin candidate: neutral baseline, slightly above good fits,
    // but attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 0.3 - mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A post_residual that is nonzero but below the minimum item size (1..100 stream,
    // treat gaps < 10 as near-unusable) is wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Medium-small gaps: moderate penalty scaled by gap size (smaller gap = worse).
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits: post_residual near zero is excellent (perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: prefer filling existing bins when many bins are open,
    // but allow opening new bins early in the stream or when few bins exist.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's already
    // tight; favor it. If far above mean, it's a loose bin; slight penalty.
    let residual_diff = bin_residual as f64 - mean_residual;
    score += residual_diff * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    // (chains items nicely). If next item is large and this bin would be left
    // with a medium gap, slight penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < 30 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer a new bin when current fit is terrible (large dead space) and
    // the item is large enough to leave a useful new-bin structure.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; overcome only if alternatives are bad.
        score += 45.0 + open_bins_count as f64 * -0.5;
        // Large items into fresh bins are fine (they define the bin's structure).
        if item_size >= 50 {
            score -= 20.0;
        }
        // If no other bin fits well, opening new is acceptable.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

