    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer filling existing ones over opening new
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Compare against mean residual: bins with less residual than average are better targets
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it moderately attractive only when item is large
    if bin_residual == bin_capacity {
        score -= 5.0 + 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

