    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Compare against mean residual of open bins: bins already tighter than average
    // should be preferred targets (their remaining space is scarce).
    let dev = mean_residual - post_residual as f64;
    score -= 0.5 * dev;

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // is a decent fit, i.e. penalize the empty-bin call mildly but reward it when
    // all open residuals are poor (large mean_residual spread vs item).
    if bin_residual == bin_capacity {
