    // Reward tight fits (small but usable post_residual is good if >= 10).
    if post_residual >= 10 && post_residual <= 20 {
        score -= 18.0;
    } else if post_residual > 20 && post_residual <= 35 {
        score -= 8.0;
    }

    // Perfect fill: zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score -= 20.0; // still better to dump here than open new bin for sliver
        }
    }

    // Open-bins pressure: with many open bins, consolidate into existing bins;
    // with few open bins, allow opening new bins for bad fits.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 5.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else if slack < 10 {
            score -= 12.0;
        }
    }
    // If next item is large and this placement leaves a gap it can't use,
    // slightly penalize creating that trap.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 30 {
        score += 6.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins) to keep a pool of large residuals available.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // New-bin candidate: neutral baseline; make it attractive only when the
    // fit into this bin would create heavy dead space.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: post_residual = capacity - item_size.
        // If existing bins would leave unusable slivers, the penalties above
        // already push them above this baseline; otherwise keep new bin costly.
        score += 30.0 - 10.0 * (open_bins_count as f64).ln().max(0.0);
        // Early in the stream, a fresh bin is cheaper to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
