        }
    } else {
        // Last item: minimize post_residual aggressively
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual far above mean are
    // "wasted capacity" holders; prefer filling them when fit is decent.
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 0.5 * (res - mean_residual) / bin_capacity as f64;
    } else {
        score += 0.3 * (mean_residual - res) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
        if post_residual as f64 > 0.4 * bin_capacity as f64 {
            score += 3.0; // poor fit -> let new-bin candidate win
        }
    }

    // New empty bin candidate: make it unattractive unless it beats a bad fit.
    if bin_residual == bin_capacity {
        score += 6.0;
        // Early in the stream, opening bins is cheaper (room to consolidate later)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Mild preference to keep many small bins consolidated late in stream
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to hold even the smallest item (<=10),
    // but exempt perfect fits.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0; // chain-fit: next item nearly fills remainder
        } else {
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual is dead for the next item: penalize proportionally.
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, mild penalty to encourage discrimination among bins.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is attractive early (many items remain) or when the
        // item fits poorly everywhere (large post_residual in any open bin).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let horizon = 1.0 - progress; // remaining fraction of stream
        // Base cost of a new bin, discounted when the stream is long.
        score = 100.0 - 55.0 * horizon.min(1.0);
        // If the item would leave a nearly-empty remainder in any open bin,
        // opening fresh is fine; otherwise make new bin slightly worse than a
        // good existing fit by anchoring against mean residual.
        if post_residual as f64 <= mean_residual * 0.5 {
            score += 10.0; // keep using existing bins with roomy residuals
        }
        // Perfect fit into an existing bin should always beat opening a new bin.
        if item_size == bin_capacity {
            score += 500.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean
        // (below-mean residual bins are "tighter", use them first).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
        // Slight preference to consolidate when many bins are open.
        score += 0.4 * open_bins_count as f64;
    }

    // Mild time modulation: late in the stream, avoid creating tiny fragments.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && post_residual > 0 && post_residual < 15 {
        score += 12.0 * (progress - 0.8) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful later
    // are heavily penalized. Threshold based on smallest plausible item.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small but usable gap) mildly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Penalize creating a gap that cannot fit the lookahead item while other
    // placements might; reward if post_residual fits next_item_size exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // wasted space relative to lookahead
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.6 * progress);

    // New-bin candidate: make it attractive only when the fit into open bins is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced when item is large or fit elsewhere is bad.
        let poor_fit_penalty = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let base_cost = 55.0 - poor_fit_penalty;
        // Large items leave little residual anyway; slight discount for big items.
        let size_discount = item_size as f64 * 0.25;
        score = base_cost - size_discount + post_residual as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Mild preference for bins below mean residual (consolidating fuller bins).
    score += ((mean_residual - bin_residual as f64) * 0.15).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect or near-perfect fit (waste minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 0.4;
        // bonus if next item then leaves near-zero residual too
        if post_residual == next_item_size {
            score -= 150.0;
        }
    } else if next_item_size > 0 {
        // penalize dead space the next item cannot use
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize opening a new bin when reasonable open bins exist
    if bin_residual == bin_capacity {
        score += 40.0;
        // but allow new bin if current fit is very poor
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 90.0;
        }
    }

    // Slight preference early in stream to keep bins open for future items
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards: excellent chaining.
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 - slack * 2.0;
            // Bonus when the chain nearly fills the bin completely.
            if post_residual == next_item_size {
                score -= 400.0;
            }
        } else {
            // Post-residual is dead space for the next item: penalize proportionally,
            // but less harshly when the leftover is small.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 3.0;
        }
        // If the next item is large, prefer conserving roomy bins for it.
        if next_item_size >= 50 && post_residual < next_item_size && post_residual > 0 {
            score += 50.0;
        }
    } else {
        // Last item: just minimize waste.
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: prefer bins that are tighter than average
    // (concentrate fill), but avoid extreme fragmentation.
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 1.5;
    } else {
        score += (resid_f - mean_residual) * 1.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless the
    // item is large and a fresh bin gives a clean layout.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count > 0 {
            score += 120.0 - 80.0 * progress;
            // A new bin is attractive for very large items (clean packing).
            if item_size >= 60 {
                score -= 100.0;
            }
        } else {
            score -= 500.0; // must open the first bin
        }
        // Fresh-bin alignment with next item: keep if next item fits with room.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer existing bins.
    score += open_bins_count as f64 * 0.5;

    // Slight preference for bins with larger residual when item is small
    // (keeps small items from wasting big-bin space is handled above;
    //  here we gently prefer filling emptier bins to close them out).
    if item_size <= 30 {
        score -= (bin_capacity - bin_residual) as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item can still fit: mild reward proportional to how tight the chain is.
        let slack = (post_residual - next_item_size) as f64;
        score -= 100.0 - slack * 0.8;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leftover dead space below next item size.
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.5;
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving this bin below-average residual concentrates waste in one bin (good).
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open bin fits
    // well (tight fit) or the current bin would leave an awkward small residual.
    if bin_residual == bin_capacity {
        // Base penalty for consuming fresh capacity.
        score += 250.0;
        // If placing here would leave a residual that matches the next item,
        // a fresh bin is actually a great chain start — forgive the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tight = (post_residual - next_item_size) as f64;
            score -= 200.0 - tight * 0.5;
        }
        // Early in the stream, fresh bins are cheaper to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 150.0 * (1.0 - progress);
    }

    // Mild penalty for very small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, prefer compacting into open bins;
    // late in the stream, tight fits matter more.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Penalize small post-residuals that create unusable dead space,
    // but only if the next item cannot use them.
    if post_residual > 0 && (next_item_size as u32) > post_residual {
        let dead = post_residual as f64;
        score += dead * (0.6 + 1.4 * progress);
    }

    // Reward perfect-ish fits (post_residual small but next item might use it).
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let fit_quality = (next_item_size as f64) / (post_residual as f64).max(1.0);
        score -= 18.0 * fit_quality * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score -= 25.0 * (1.0 - waste_ratio);
    }

    // New-bin candidate: penalize opening a new bin when decent alternatives
    // exist; allow it when the stream is early and future items are large,
    // or when this bin would otherwise be a poor fit.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 + 20.0 * progress;
        let lookahead_bonus = if next_item_size > item_size { 10.0 } else { 0.0 };
        score += base_penalty - lookahead_bonus;
        // If no open bin fits well, opening a new bin is less bad.
        if post_residual > (bin_capacity as u32 / 2) {
            score -= 15.0;
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // favor bins below mean residual (consolidation pressure).
    let dev = mean_residual - bin_residual as f64;
    score += 0.35 * dev * (1.0 + (open_bins_count as f64).ln().max(0.0)) * (1.0 - progress);

    // Mild reward for exact capacity utilization.
    let util = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * util * util;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "useless"
    // (small, non-representable by typical item sizes) get penalized.
    let pr = post_residual;
    if pr > 0 {
        // dead-space penalty grows steeply for tiny residuals
        if pr < 10 {
            score += 60.0 * (10 - pr) as f64;
        }
        // modulo classes: residuals divisible by 10 are friendlier
        let m10 = pr % 10;
        score -= 8.0 * (10 - m10) as f64 * 0.0; // placeholder harmonic anchor
        score += 4.0 * m10 as f64;

        // integer division thresholds: big buckets of residual are good
        let bucket = pr / 20; // 0..5
        score -= 6.0 * bucket as f64;
    } else {
        // perfect fit: reward strongly
        score -= 100.0;
    }

    // Fullness fraction: favor bins whose residual fraction is a "harmonic" of capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac * frac;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if next item fits the post-residual exactly or nearly, reward
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack < 10 {
            score -= 40.0; // near-perfect chain
        } else {
            score -= 15.0 * (slack as f64 / bin_capacity as f64);
        }
        // harmonic class match: both divisible by 10
        if pr % 10 == 0 && next_item_size % 10 == 0 && (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here; penalize leaving awkward space
        score += 8.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the current
    // fit is truly terrible (large post-residual waste) and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base cost of a new bin, discounted early in the stream
        score = 55.0 + 60.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big next item justifies fresh space
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64;
    score += 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in low classes
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < quarter {
        score -= 25.0; // tight residue, likely usable by small items
    } else if post_residual <= half {
        score += 5.0; // moderate residue
    } else {
        score += 15.0; // large residue: wasteful placement
    }

    // Modulo classes: residues congruent to small multiples of 10 pair well
    let m = post_residual % 10;
    if m == 0 {
        score -= 10.0;
    } else if m >= 7 {
        score += 8.0; // awkward residue class
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack = (post_residual - next_item_size) as f64;
            score -= (slack / cap) * 10.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    } else {
        // last item: prefer perfect closure
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > cap * 0.5
            || (next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1);
        score = if poor_fit { -5.0 } else { 40.0 + 20.0 * (1.0 - progress) };
    }

    // Mild pressure toward consolidating bins
    score += open_bins_count as f64 * 0.05;
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the residual: strong reward, scaled by how tight the fit is
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 0.5;
    }
    // Next item cannot use the residual: penalize proportionally to dead space
    else if next_item_size > 0 {
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Penalize bins whose residual deviates from the mean (encourage balanced packing)
    score += ((post_residual as f64) - mean_residual).abs() * 0.4;

    // Penalize opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
        // Early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 100.0;
    }

    // Prefer filling bins tightly overall
    score -= (item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 12.0 * fit_frac * fit_frac * cap
        - 20.0 * fit_frac * fit_frac * fit_frac * cap;

    // Perfect fit reward (smooth, non-piecewise)
    let perfect = (pr / cap).powi(4);
    score -= 60.0 * perfect * cap;

    // Stream-progress coupling: tighten later in the stream
    let tighten = progress * progress * (1.0 - progress);
