        let gap = (pr - nxt).abs() / cap;
        score -= 25.0 * (1.0 - gap) * (1.0 - gap) * (1.0 - progress);
        // penalize leaving space that neither fits next item nor is tiny
        score += 10.0 * gap * gap * cap * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins deviating from mean residual (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev * cap * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless residual is empty
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
