    let norm_item = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (0.5 + 2.0 * progress) - norm_post * (1.0 + progress);

    // Penalize dead space more as stream advances (less time to fill gaps)
    let dead_penalty = norm_post * norm_post * (1.0 + 3.0 * progress * progress);

    // Reward tight fits: low post residual relative to item size
    let tightness = (norm_item / (norm_item + norm_post + 1e-9)) * (1.0 - progress);

