    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -2.0 * (1.0 - norm_post)
    } else {
        0.0
    };

    // Lookahead: if next item fits exactly into post_residual, reward
    let lookahead_bonus = if next_item_size > 0 && (next_item_size as f64) <= post {
        -0.5 * (next_item_size as f64 / cap)
    } else if next_item_size > 0 {
        0.3 * (next_item_size as f64 / cap) * norm_post
    } else {
