    };

    // New-bin candidate handling: mildly penalize opening new bins early
    let new_bin_penalty = if bin_residual == bin_capacity {
        0.6 + 1.5 * progress - 0.02 * open_bins_count as f64
    } else {
        0.0
    };

    // Divergence from mean residual: prefer bins below mean residual (tighter)
    let mean_coupling = (mean_residual - post) / cap * (0.3 + 0.7 * progress);

    let mut score = post
        + 10.0 * poly
        + 15.0 * dead_penalty
        - 8.0 * tightness
        + last_chance
        + lookahead_bonus
        + new_bin_penalty * cap * 0.1
        + 5.0 * mean_coupling;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
