        // Early in stream, keep flexibility; late, consolidate.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - t);
    }

    // Penalize bins far from mean residual (fragmentation control),
    // but only when many bins are open.
    if open_bins_count > 2 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev * (open_bins_count as f64).ln();
    }

    // Slight preference for fuller bins overall.
    score -= 0.05 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with smooth polynomial shaping
    let mut score = pr;

    // Non-linear coupling: post_residual weighted by stream progress.
    // Late in the stream, small residuals matter more (fewer wasted bins overall).
    let progress_weight = 1.0 + 0.8 * progress * progress;
    score += 2.0 * (norm_pr - norm_pr * norm_pr) * progress_weight;

    // Penalize residuals that are too small to ever be useful (dead space),
    // smoothly via a quadratic bowl around half-capacity.
    let dead = (norm_pr - 0.5) * (norm_pr - 0.5);
    score -= 6.0 * (1.0 - dead) * (1.0 - dead);

    // Lookahead: reward if next item could fit into post_residual (smooth coupling)
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64) / cap;
        score -= 4.0 * fits.max(-1.0) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins whose residual deviates favorably from mean (balance packing)
    score -= 0.3 * (mean_residual - pr) / cap;

    // Mild preference to reuse existing bins over opening new ones
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item
    // denominators (10, 20, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 {
            score -= 12.0;
        } else if pr % 25 == 0 {
            score -= 9.0;
        } else if pr % 20 == 0 {
            score -= 8.0;
        } else if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        } else {
            // awkward non-harmonic residual: penalize proportionally
            score += (pr % 5) as f64 * 1.5;
        }
    }

    // Perfect fit is ideal
    if pr == 0 {
        score -= 40.0;
    }

    // Coupling: does the lookahead item fit harmonically into post_residual?
    if next_item_size > 0 && pr >= next_item_size {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 25.0; // lookahead perfect fit
        } else if gap % 10 == 0 {
            score -= 10.0;
        } else if gap % 5 == 0 {
            score -= 4.0;
        } else {
            score += (gap % 5) as f64;
        }
    } else if next_item_size > 0 && pr < next_item_size && pr > 0 {
        // post_residual too small for lookahead: dead space unless reusable
        score += 4.0;
    }

    // Integer-division threshold on post_residual: small slivers are bad
    if pr > 0 && pr / 10 == 0 {
        score += 8.0; // residual < 10 nearly unusable (min item size 10)
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a new bin is a last resort.
    if bin_residual == bin_capacity {
        // base penalty grows with number of open bins and stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + open_bins_count as f64 * 0.8 + progress * 6.0;
        // but if no open bin fits well, allow opening: compare against mean residual
        if fitting_bins_count == 0 {
            score -= 22.0;
        }
        // if mean residual across open bins is large, prefer reusing them
        score += (mean_residual / bin_capacity as f64) * 10.0;
    } else {
        // mild preference for tighter existing bins
        score += (bin_residual as f64 - post_residual as f64) * 0.0; // no-op guard
        score -= (bin_capacity - bin_residual) as f64 * 0.05; // fuller bins slightly favored
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins that can also fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 10.0; // penalize killing the next item's options
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: penalize creating new bins when many are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (tighter bins first).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, tighten further: waste is less recoverable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits within the post residual (good chaining).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.5;
    }
    // Next item does not fit: dead space penalty scaled by wasted potential.
    else if next_item_size > 0 {
        let dead = next_item_size.min(post_residual) as f64;
        score += dead * 0.3;
    }

    // Reward tight fits relative to bin capacity (low post residual is good).
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 10.0;

    // Compare against mean residual: placing in a below-average bin balances load.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when other bins can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 30.0
                + (post_residual as f64) * 0.2
                - (fitting_bins_count as f64) * 2.0;
        } else {
            score -= 15.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring post_residual penalizes large leftover space.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Strongly reward using a bin when it is the only fitting option (avoid new bin).
    if fitting_bins_count == 1 {
        score -= 60.0 + 20.0 * t;
    }

    // Mild preference for bins with smaller residual among fitting bins.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.3;

    // Penalize bins whose residual deviates above mean (fragmented bins).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 {
        // Penalize creating dead space unusable by the next item.
        score += (post_residual as f64).min(next_item_size as f64) * 0.25;
    }

    // Discourage opening new bins when many bins are open and could absorb the item.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { 25.0 + 15.0 * (1.0 - t) } else { -10.0 };
        score += pressure;
        // New bin more attractive late in stream when residuals are small overall.
        score += mean_residual * 0.1;
    }

    // Early stream: consolidate; late stream: prefer exact fills.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    score += open_bins_count as f64 * 0.05 * (bin_residual == bin_capacity as u32) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, bounded [0,1])
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / cap;

    // Non-linear polynomial coupling: post-residual penalized more strongly
    // as the stream progresses (late stream -> waste is more costly).
    let poly = pr * pr * (1.0 + progress) + pr * progress * progress;
    score += 40.0 * poly;

    // Smooth reward for tight fits, amplified by progress
    let tightness = 1.0 - pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize bins whose residual deviates from mean residual (encourage balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = pr - ni / cap;
        if gap >= 0.0 {
            score -= 15.0 * gap * (1.0 - gap) * (0.5 + progress);
        } else {
            score += 8.0 * gap * gap * cap / 100.0;
        }
    }

    // Mild penalty for opening new bins when many bins are open and stream is early
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item sizes) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        // Reward post-residuals divisible by small harmonic denominators.
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        else if pr % 2 == 0 { score -= 2.0; }
        else { score += 4.0; } // odd leftovers pair poorly

        // Integer-division thresholds: leftover in [1..=9] is near-worthless
        // dead space; leftover >= 50 is a "half bin" and reusable.
        if pr <= 9 {
            score += 15.0;
        } else if pr >= 50 {
            score -= 8.0;
        } else if pr >= 25 {
            score -= 3.0;
        }
    } else {
        // Perfect closure of the bin is ideal.
        score -= 40.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Harmonic match: leftover is at least next item, extra reward if
            // post_residual - next_item_size is again a small residue class.
            let follow = pr - next_item_size;
            score -= 10.0;
            if follow % 10 == 0 { score -= 6.0; }
            else if follow % 5 == 0 { score -= 3.0; }
            if follow == 0 { score -= 10.0; } // chains two perfect fits
        } else {
            // Leftover cannot host the next item: penalize proportionally
            // to how close-but-failed the fit is (near-miss dead space).
            let gap = next_item_size - pr;
            if gap <= 10 { score += (11 - gap) as f64 * 1.5; }
        }
    } else {
        // Last item: only perfect closure matters, leftovers worthless.
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, slightly discourage hoarding many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 && progress < 0.5 {
        score += 1.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual == capacity here means empty bin).
    if bin_residual == bin_capacity {
        // Empty bin baseline: a fresh bin scores as its full residual,
        // which beats only badly-fitting placements due to the bonuses above.
        score += 5.0;
        if fitting_bins_count == 0 { score -= 20.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item (>=1) can
    // still exploit well are penalized super-linearly. Small gaps (1..=9)
    // are almost dead; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fill is highly desirable.
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Prefer bins whose residual is already small relative to mean residual
    // (consolidating space into fewer bins).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 0.4 * next_item_size as f64;
        } else {
            // Next item won't fit here: this residual may become dead space.
            let waste = post_residual as f64;
            if waste > 0.0 && waste < next_item_size as f64 {
                score += 0.8 * (next_item_size as f64 - waste);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // opening a new bin wastes the residual here entirely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with number of open bins.
        score = 100.0 + 2.0 * open_bins_count as f64;
        // If current item nearly fills a fresh bin, opening is reasonable.
        if fill_ratio > 0.7 {
            score -= 30.0 * fill_ratio;
        }
        // If the item fits poorly everywhere (large dead space would result),
        // opening a new bin becomes preferable.
        if post_residual < 10 && post_residual > 0 {
            score -= 45.0;
        }
        // Late in the stream, prefer closing out bins rather than opening.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Open-bin pressure: with many open bins, favor placements that reduce
    // fragmentation in existing bins rather than spreading further.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual (chained fit)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item also fits here -> excellent chaining
            let chain_left = post_residual - next_item_size;
            score -= 40.0 + chain_left as f64 * 0.2;
            // double-perfect chain
            if chain_left == 0 {
                score -= 500.0;
            }
        } else if next_item_size > 0 && next_item_size <= bin_residual {
            // next item would fit the bin now but not after this placement:
            // penalize wasting space the future item needs
            score += 30.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
        // penalize leftover dead space that nothing can use
        if post_residual > 0 && next_item_size > post_residual {
            score += post_residual as f64 * 0.3;
        }
    } else {
        // last item: prefer minimal residual
        score += 0.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        // discourage opening new bins early; allow when many bins open and fit is poor
        score += 120.0 + openness * 3.0;
        // if next item is large, a fresh bin is more useful
        if next_item_size >= 50 {
            score -= 20.0;
        }
        // near end of stream, avoid opening bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // mild penalty for very tight bins that barely fit (avoid over-fragmenting)
    if bin_residual - item_size <= 5 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins with small post residual.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: small but nonzero residuals that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Pair-fill: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer bins below mean residual (more free space used efficiently).
    score += 0.4 * (mean_residual - bin_residual as f64).abs();

    // Penalize leaving a residual larger than the max item size (100 cap) — unusable space.
    if post_residual > 80 {
        score += 0.3 * (post_residual as f64 - 80.0);
    }

    // New-bin candidate handling: empty bin.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when no good fits exist or item is large.
        if item_size > 60 || (fitting_bins_count <= 1 && fitting_bins_count > 0) {
            score -= 20.0;
        } else {
            score += 15.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild crowding pressure: many open bins -> prefer consolidation into existing bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tightest fit preferred, normalized and squared for smooth non-linearity
    let mut score = (post / cap).powi(2) * 100.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; later, dead space is heavily penalized.
    let coupling = post / cap * (1.0 + progress * progress * 3.0);
    score += coupling * 50.0;

    // Cubic interaction: penalize mid-range residuals (awkward gaps) more strongly
    let r = post / cap;
    score += 30.0 * r * (1.0 - r) * r * (1.0 + progress);

    // Lookahead: reward if next item fits exactly into post_residual (smooth reward)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - ((post - nxt) / cap).abs();
            score -= 40.0 * fit_quality * fit_quality;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 10.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / cap).powi(2) * 60.0;
        let crowd_penalty = open_bins_count as f64 * 0.5;
        score += 70.0 - large_item_bonus + crowd_penalty;
    }

    // Mild preference for bins below mean residual (keeps large gaps distributed)
    score += 0.1 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic classes: classify post_residual into residue classes mod 10 ---
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space classes: residuals that are hard to fill with typical items
    match class {
        0 => score -= 8.0,                       // perfectly round residual, very reusable
        1 | 2 | 8 | 9 => score += 6.0,           // awkward slivers
        3 | 7 => score += 2.0,
        4 | 5 | 6 => score -= 3.0,               // mid-range residuals are decent targets
        _ => {}
    }

    // Integer-division thresholds: very small post_residual means near-perfect fit
    if pr == 0 {
        score -= 30.0;
    } else if pr <= 5 {
        score -= 15.0;
    } else if pr <= 10 {
        score -= 7.0;
    } else if pr > 50 {
        score += (pr as f64 - 50.0) * 0.25;      // wasting more than half a bin
    }

    // Capacity-fraction coupling: reward placing big items into small residuals
    let item_frac = item_size as f64 / cap;
    let resid_frac = bin_residual as f64 / cap;
    score -= item_frac * resid_frac * 12.0;      // big item into tight bin is valuable

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when the item is huge relative
    // to residual or no real bin fits well
    if bin_residual == bin_capacity {
        let mut new_bin_score = 25.0 + (100.0 - item_size as f64) * 0.6;
        // Lookahead: if next item would also want this fresh bin, opening is better
        if next_item_size > 0 && next_item_size <= pr {
            new_bin_score -= 10.0;
        }
        if open_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        // Harmonic check: does the item leave a "good class" residual in a fresh bin?
        let fresh_pr = bin_capacity - item_size;
        if fresh_pr % 10 == 0 {
            new_bin_score -= 6.0;
        }
        score = score.max(new_bin_score);
        return score;
    }

    // Lookahead synergy: if next item exactly fills this bin's post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr && (pr - next_item_size) <= 10 {
            score -= 10.0;
        } else if next_item_size > pr {
            // next item can't use this bin's leftover; slightly penalize large leftovers
            score += (pr as f64) * 0.05;
        }
    }

    // Mean-residual coupling: if this bin is far below the mean residual, it is a
    // "harmonically low" bin — filling it balances the open-bin distribution.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.1;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum item size (1..=10) are pure waste.
    let dead_zone: f64 = if post_residual < 10 {
        60.0 + (10 - post_residual) as f64 * 8.0
    } else if post_residual < 20 {
        18.0 + (20 - post_residual) as f64 * 2.0
    } else {
        0.0
    };
    score += dead_zone;

    // Perfect or near-perfect fits get rewarded (post_residual close to 0
    // already low, add bonus subtraction for exact packing).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // (penalize spreading); a new empty bin gets residual == capacity, so
    // add explicit pressure proportional to open_bins_count for it.
    if bin_residual == bin_capacity {
        // New bin candidate: only attractive when current bins are congested
        // or the fit would leave dead space.
        score += open_bins_count as f64 * 4.0
            + (post_residual as f64) * 0.5;
        // If this bin is the last chance, strongly discourage opening new.
        if fitting_bins_count == 1 && post_residual < 10 {
            score += 200.0;
        }
    } else {
        // Existing bin: reward using it, especially when many bins are open.
        score -= open_bins_count as f64 * 1.5;
        // Last-chance bin: strongly favor using it before it dies.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Lookahead: if next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap < 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use leftover: leftover is likely dead space.
        score += (post_residual as f64).min(15.0) * 1.2;
    }

    // Mean residual coupling: if this bin's post-residual deviates favorably
    // from the mean (smaller leftover than average), reward it.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Early stream: slight preference for tight packing to build good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: scale waste by relative fill achieved.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 0.35 * fill_ratio * (bin_capacity - bin_residual) as f64;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            score -= 2.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here: slight penalty for blocking perfect fit
            score += 1.5 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last chance: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Prefer bins below mean residual (larger residual than average keeps big holes open).
    if (bin_residual as f64) > mean_residual {
        score += 0.10 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: early in stream, be more willing to open new bins (preserve flexibility);
    // late in stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize early, reward late slightly less
        score += 4.0 * (1.0 - progress) - 1.0 * progress;
    } else {
        score -= 1.0 * progress;
    }

    // Mild penalty when many bins are already open: encourage consolidation.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: post_residual shaped by stream progress
    let progress_coupling = norm_pr * (1.0 + 2.0 * progress * norm_pr);
    score -= 0.5 * pr * progress_coupling;

    // Penalize dead space quadratically, weighted by progress
    score += 0.3 * norm_pr * norm_pr * cap * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item)
    score -= 20.0 * norm_item * (1.0 - norm_pr).powi(2);

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * norm_next * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 5.0 * norm_next * norm_pr;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Penalize spreading residual far from mean (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * cap;

    // New-bin candidate: neutral-ish baseline, slightly penalized early, less late
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress + 10.0 * norm_item;
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes by capacity fraction
    let frac = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 25.0; // tiny dead space, unusable
    } else if post_residual <= 20 {
        score -= 5.0; // still fits smallest items
    } else if post_residual <= 50 {
        score += 8.0; // awkward middle class
    }

    // Next item lookahead: reward bins whose residual can host the next item too
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.15 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves bad residue
    if bin_residual == bin_capacity {
        // new bin attractive when item is large or many bins already open
        score += 40.0 - 0.2 * item_size as f64 + 0.5 * open_bins_count as f64;
        if item_size >= 50 {
            score -= 25.0; // large items fine in fresh bin
        }
    }

    // Prefer filling bins below mean residual (tighter bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Progression: late in stream, be greedier about closing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (below the minimum
    // plausible item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Zero residual is a perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fits (small but usable leftover) are also good.
    if post_residual >= 10 && post_residual <= 25 {
        score -= 10.0;
    }

    // Penalize waste proportional to how much of the bin is left idle.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Lookahead: if the next item fits into post_residual, this placement
    // chains nicely -> reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item is bigger than post_residual but this bin is the only
    // fitting option, opening a new bin is preferable -> penalize.
    if next_item_size > post_residual && fitting_bins_count <= 1 {
        score += 20.0;
    }

    // Last-chance bin: using the final bin that can fit avoids opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 8.0 + pressure * 3.0;
    } else {
        score -= pressure.min(6.0);
    }

    // Prefer bins with residual close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Slight preference for bins whose residual is near the mean (keeps
    // residuals balanced, easier future fits).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits: small post_residual is already rewarded by base term.
    // Strong reward when the leftover exactly matches the next item (2-step lookahead).
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 * (1.0 - lookahead_gap / bin_capacity as f64);

        // Perfect chain: post_residual == next_item_size -> huge bonus
        if post_residual == next_item_size {
            score -= 100.0;
        }
        // Avoid leaving a dead sliver smaller than the smallest possible item
        if post_residual > 0 && post_residual < 10 {
            score += 80.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 50.0;
    }

    // Penalize bins that are far below mean residual (poor utilization candidates)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Early in the stream, prefer keeping bins tight rather than spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit preference (smaller post-residual = tighter fit = lower score).
    // Squared coupling emphasizes tight fits, but only when the leftover stays usable.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = pr / cap;

    // Dead-space penalty: leftover that is too small to reliably host a future item
    // is wasted capacity. Penalize quadratically as post_residual approaches 0.
    if post_residual < 10 {
        score += (10.0 - pr) * 40.0;
    } else if post_residual < 20 {
        score += (20.0 - pr) * 8.0;
    }

    // Lookahead reward: if the next item fits exactly-ish in the leftover,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 + 20.0 * (1.0 - slack / cap);
    }
    // Lookahead penalty: next item is large and would NOT fit here,
    // meaning this bin may become stranded; mildly penalize near-full bins.
    if next_item_size > post_residual && post_residual < 15 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item, using it
    // avoids opening a new bin — reward strongly unless it creates dead space.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 35.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidating into existing bins (avoid bin proliferation).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation = (mean_residual - pr) * 0.15 * (1.0 + open_bins_count as f64 / 20.0);
    score += consolidation;

    // Time horizon: late in the stream, avoid opening new bins and squeeze
    // items into existing space more aggressively.
    score -= t * 10.0 * (1.0 - frac);

    // Mild preference for bins whose residual was already moderate
    // (avoid burning large empty bins on small items early).
    if bin_residual as f64 > mean_residual + 30.0 && item_size < 40 {
        score += 12.0;
    }

    // New-bin candidate guard: an empty bin (residual == capacity) must NOT
    // win when a reasonable fit exists in an open bin. Its base score is
    // already high (large post_residual); add extra deterrence unless the
    // item is huge relative to what open bins could absorb.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let waste = (bin_capacity - item_size) as f64;
        score += 15.0 + 0.2 * waste;
        // But if the item would leave near-zero dead space anywhere, the
        // dead-space penalty above already dominates — no extra guard needed.
        if item_size >= 90 {
            score -= 40.0; // huge items: a fresh bin is often genuinely best
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on leftover space (waste grows super-linearly).
    let mut score = norm_post * norm_post * cap;

    // Cubic coupling with stream progress: early on, waste is cheaper;
    // later, large residuals become increasingly costly.
    score += 0.6 * norm_post.powi(3) * cap * (0.5 + progress);

    // Reward tight fits: subtract when post_residual is small relative to capacity.
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post);

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // Next item too big for this residual: penalize proportionally to gap.
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalize bins that are far from the mean residual (fragmentation signal),
    // smoothly scaled by number of open bins.
    let dev = (post - mean_residual).abs() / cap;
    score += 3.0 * dev * dev * (1.0 + open_bins_count as f64).ln();

    // Mild progress-based tilt: late in the stream, prefer filling existing bins.
    score -= 2.0 * progress * (1.0 - norm_post);

    // Slight preference for keeping fewer open bins when residuals are small.
    score += (open_bins_count as f64).ln() * 0.5 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space is worse when it
    // falls into a "useless" residue class (too small for typical items).
    let r = post_residual;
    let cls = r / 10; // integer-division class: 0..10
    match cls {
        0 => { score -= 25.0; }           // near-perfect fit, tiny waste
        1 => { score -= 15.0; }           // excellent fit
        2 => { score -= 6.0; }            // good fit
        3 => { score -= 1.0; }            // acceptable
        4 => { score += 2.0; }            // mediocre dead space
        5 => { score += 5.0; }            // half-empty bin
        6 => { score += 7.0; }
        7 => { score += 9.0; }
        8 => { score += 10.0; }
        _ => { score += 12.0; }           // nearly untouched bin used wastefully
    }

    // Modulo-10 fine structure: residuals congruent to small values mod 10
    // are hard to fill later (items >= 10).
    let m = r % 10;
    if r > 0 && r < 10 { score += 8.0; } // guaranteed dead space < smallest item
    if m == 0 { score -= 2.0; }          // round residual is easier to reuse

    // Lookahead: reward if the next item fits into the post residual,
    // extra reward when it fits snugly (harmonic chain).
    if next_item_size > 0 {
        if next_item_size <= r {
            score -= 6.0;
            let gap = r - next_item_size;
            if gap < 10 { score -= 6.0; } // next item then closes the bin almost perfectly
            else if gap > 50 { score += 2.0; }
        } else {
            // next item won't fit here: slightly penalize hoarding space
            score += 1.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; tuned so tight fits (cls 0/1) still beat it.
        score = 55.0;
        if fitting_bins_count == 0 { score -= 30.0; }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 2.0;
        }
        // Late in the stream, be slightly more conservative about new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 3.0;
    }

    // Mild pressure against leaving many bins nearly empty.
    if open_bins_count > 4 && post_residual > 70 && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (<=10)
    // are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    }

    // Penalize residuals too small for the lookahead item (k=2 lookahead):
    // if next item can't fit here, this gap risks becoming dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.15 * next_item_size as f64;
    }

    // Reward leaving exactly a usable gap (post_residual fits next item well)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Perfect fit reward: tight packing is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones;
    // few open bins -> tolerate opening a new bin (empty-bin candidate wins ties).
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate handling: only attractive when existing bins would leave
    // large dead space or few bins are open.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        let penalty = 15.0 + 1.2 * open_bins_count as f64 + 0.25 * avg_waste;
        score += penalty;
        // If all fitting bins are poor (high mean residual wasted), new bin is better
        if post_residual >= 10 && mean_residual < 25.0 {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual is close to item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * tightness;

    // Stream progression: later in the stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(2) as f64);
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: exact match of post_residual with next item is ideal
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item packing
        } else if post_residual > next_item_size {
            // leftover after next item: penalize proportional to waste
            let waste = post_residual - next_item_size;
            score += (waste as f64) * 0.6;
        } else {
            // next item doesn't fit here; penalize based on gap size
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.9;
        }
        // prefer bins whose residual is near the mean (keeps bin sizes balanced)
        let dev = post_residual as f64 - mean_residual;
        score += 0.15 * dev.abs();
    } else {
        // last item: just minimize residual
        score = post_residual as f64;
    }

    // last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // new-bin candidate: only attractive when no good fit exists among open bins
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0
            && open_bins_count > 0
            && fitting_bins_count > 0
            && (post_residual == 0
                || (next_item_size as f64 - post_residual as f64).abs() < 5.0);
        if good_fit_exists {
            score += 100.0; // keep using existing bins
        } else {
            score -= 5.0; // opening a fresh bin is reasonable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize low post-residual (nonzero) more strongly.
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64) * 12.0;
    } else {
        score -= 25.0; // perfect fill
    }

    // Lookahead: if the next item fits exactly into the post-residual, favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item won't fit here; penalize large dead space slightly
            score += (post_residual as f64) * 0.05;
        }
    } else {
        // Last item: strongly prefer zero waste
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a good fit. Make the empty bin costly by default.
    if bin_residual == bin_capacity {
        // Scale cost with how "full" the stream is and how many bins are open.
        score += 20.0 + 0.3 * (open_bins_count as f64);
        // If mean residual across open bins is large, opening a new bin is worse.
        score += mean_residual * 0.2;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // Exception: if next item is huge and post_residual here is 0 anyway,
        // the empty bin is fine — soften the penalty.
        if next_item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Mild preference toward filling already-open bins when many are open.
    score += (open_bins_count as f64) * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is close to item fit.
    score += ((bin_residual as f64 - item_size as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling: residual normalized by capacity, raised to powers,
    // interacting with stream progress. Large residuals early are fine; late in the
    // stream large residual = wasted space, penalize more aggressively.
    let r_norm = pr / cap;
    let r2 = r_norm * r_norm;
    let r3 = r2 * r_norm;
    score += progress * (r2 * 40.0 + r3 * 60.0);

    // Perfect fit reward: quadratic bonus approaching zero residual
    score -= 25.0 * (1.0 - r_norm) * (1.0 - r_norm) * (1.0 - progress * 0.5);

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 15.0 * (1.0 - slack / cap) * (1.0 + progress);
        } else {
            // next item won't fit here; slight penalty if we leave awkward residual
            score += 5.0 * r_norm * progress;
        }
    }

    // Prefer bins whose residual is near the mean (keeps residual profile balanced)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless current residuals are hopeless
    if bin_residual == bin_capacity {
        let mean_fill = cap - mean_residual;
        let desperation = (mean_residual / cap).powi(2) * 50.0;
        score += 60.0 + open_bins_count as f64 * 2.0 - desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-residual: which "band" of dead space do we land in? ----
    // Class residual into deciles of capacity (harmonic fractions 1/2, 1/3, 1/4, 1/5).
    let cap = bin_capacity as f64;
    let half = cap * 0.5;
    let third = cap / 3.0;
    let quarter = cap * 0.25;
    let fifth = cap * 0.2;

    let pr = post_residual as f64;

    // Integer-division harmonic class of post_residual (bucket size = capacity/10).
    let class = post_residual / (bin_capacity / 10).max(1);
    score += (class as f64) * 0.7; // prefer finer (smaller) harmonic classes

    // Dead-space penalties by harmonic fraction thresholds.
    if pr > 0.0 && pr < fifth {
        score -= 6.0; // tiny sliver: near-perfect packing, great
    } else if pr < quarter {
        score -= 3.0; // small residue still useful
    } else if pr < third {
        score += 1.5; // moderate residue
    } else if pr < half {
        score += 3.0; // large residue: wasteful unless bin was big
    }

    // Exact-fill / modulo harmony: post_residual divisible by small integers is more reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.5;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        } else {
            score += 0.8; // awkward non-aligned residue
        }
    } else {
        score -= 12.0; // perfect fill: best possible
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // Next item fits in the resulting residual: strong reward, scaled by tightness.
            let tight = 1.0 - (pr - nx) / cap;
            score -= 5.0 + 4.0 * tight;
        } else {
            // Next item will NOT fit here: penalize proportionally to how close we were.
            let miss = (nx - pr) / cap;
            score += 2.0 + 5.0 * miss;
        }
        // Harmonic class match between next item and post-residual (integer division agreement).
        let bucket = (bin_capacity / 10).max(1);
        if next_item_size / bucket == post_residual / bucket && post_residual > 0 {
            score -= 3.0; // same harmonic class: likely exact pairing
        }
    } else {
        // Last item: only exact fills matter.
        if post_residual > 0 {
            score += 4.0;
        }
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 {
        // This is the only bin that fits: strongly prefer using it over opening a new bin.
        score -= 8.0;
    } else if fitting_bins_count == 0 {
        score += 50.0; // shouldn't happen for candidates, but guard
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Empty bin: baseline cost of opening a new bin. Attractive early or when
        // no open bin offers a good fit; discouraged when many bins are open already.
        score = cap * 0.55 + (open_bins_count as f64) * 1.2;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 2.0; // fresh bin always fits the next item too
        }
        if fitting_bins_count == 1 {
            score += 10.0; // a real fitting bin exists: don't open a new one
        }
        // Early in the stream, opening bins is cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // ---- Mean-residual coupling: avoid worsening an already-fragmented state ----
    let dev = pr - mean_residual;
    score += 0.15 * dev; // prefer residuals below the mean (tighter bins)

    // Mild preference to fill bins with more content when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 25.0;
    }
    // Perfect fit is extremely rewarded.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // post_residual becomes dead space relative to the next item.
            score += (post_residual as f64) * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Prefer bins tighter than the average residual (good fits).
    score -= (mean_residual - bin_residual as f64) * 0.8;

    // New-bin candidate: baseline cost so it's only chosen when open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * progress + open_bins_count as f64 * 0.5;
        // Opening a bin is fine if the next item is large and nothing fits well.
        if next_item_size > 60 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a perfect two-item match.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect fit for the next item: bin becomes exactly full.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement; reward the
            // tightness of the two-step combination.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            // Extra bonus if the chain could continue (slack >= 10).
            if slack >= 10.0 {
                score -= 5.0;
            }
        } else {
            // Next item will NOT fit here: penalize proportionally to
            // how much dead space this leaves relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    } else {
        // Last item in stream: just prefer minimal residual.
        score -= 10.0;
    }

    // Penalize creating residuals that are far below the mean residual
    // of open bins (fragmenting small slivers), unless it was a perfect fit.
    if post_residual > 0 {
        let dev = mean_residual - post_residual as f64;
        if dev > 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.1 * dev; // slightly reward larger-than-mean residuals
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when few bins are open or the stream is early; otherwise discourage.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Mild preference for tighter fits overall.
    score += 0.2 * (bin_residual - item_size) as f64 * 0.0; // neutralized
    score += 0.05 * item_size as f64 * 0.0; // neutralized

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Reward tight fits (high fill ratio of the bin's current residual)
    let fill_ratio = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 18.0 * fill_ratio;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - 0.3 * progress);
    }

    // Lookahead (k=2): reward if the next item can also fit in the leftover space
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // Penalize creating dead space that the next item cannot use
            score += 0.15 * post_residual as f64;
        }
    }

    // Non-linear dead-space penalty for very small leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Coupling with global state: prefer bins whose residual deviates from the mean
    // (draining already-small bins keeps the pool of open bins healthier)
    score += 0.08 * (mean_residual - post_residual as f64);

    // New-bin candidate: usually discouraged, but more acceptable late in the stream
    if bin_residual == bin_capacity {
        score += 22.0 - 12.0 * progress;
        // If many bins are open and congested, opening a fresh bin is less bad
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress, smooth in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress = progress.clamp(0.0, 1.0);

    // Tightness of fit: fraction of the bin consumed by this item
    let fill = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Smooth non-linear reward for tight fits: quadratic coupling of fill
    // with a progress-modulated gain (later in stream => reward tight fits more)
    let tight_gain = 8.0 + 24.0 * progress * progress;
    score -= tight_gain * fill * fill;

    // Penalize dead space non-linearly: small residuals that can't fit
    // typical future items are quadratically bad, modulated by progress
    let dead = (post_frac * (1.0 - post_frac)).max(0.0); // peaks mid-range residual
    score += 12.0 * progress * (1.0 - progress) * dead * 4.0;

    // Smooth interaction: post_residual vs mean residual across open bins.
    // Prefer bins whose residual is close to the mean (balanced depletion).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Lookahead coupling: smooth reward if the next item fits the post residual
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let next_frac = next_item_size as f64 / cap;
        // reward grows as next item is large (hard to place later)
        score -= 10.0 * fits_next * next_frac * (0.5 + 0.5 * progress);
        // smooth penalty if post residual is just barely too small for next item
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0) / cap;
        score += 8.0 * gap * (1.0 - gap) * next_frac;
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate (empty bin): penalize opening new bins smoothly,
    // penalty relaxes as stream progresses and open bins are crowded with waste
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / cap).clamp(0.0, 1.0);
        let penalty = 18.0 * (1.0 - 0.4 * progress) * (1.0 - 0.5 * crowding);
        score += penalty;
        // mild bonus when many bins already open and mean residual is low
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * crowding * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual (mod 10 / integer-division tiers) ----
    // Class A: post_residual in {0} -> perfect fit, huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Class B: post_residual < 10 -> nearly perfect, dead space unusable by any item.
    else if post_residual < 10 {
        score -= 200.0;
    }
    // Class C: 10 <= post_residual < 25 -> residual still usable by small items.
    else if post_residual < 25 {
        score -= 60.0;
    }
    // Class D: 25 <= post_residual < 50 -> mediocre leftover.
    else if post_residual < 50 {
        score -= 15.0;
    }
    // Class E: post_residual >= 50 -> wasteful split of a big hole.
    else {
        score += 25.0;
    }

    // Fine harmonic bonus: post_residual divisible by 10 aligns with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    }

    // ---- Lookahead coupling: does next_item_size fit the post_residual? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chainability: strongly reward leaving a hole for the next item.
            score -= 40.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space relative to the next item: penalize proportionally.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // ---- Last-chance bin: if this is the only bin that fits, avoid opening a new one ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when many bins are open and mean residual is low
        // (existing bins are fragmented). Base penalty keeps it from winning on easy fits.
        score += 150.0
            - 0.4 * open_bins_count as f64
            - 0.5 * (mean_residual - item_size as f64).max(0.0);
        // Late in the stream, consolidation matters more: extra penalty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 50.0 * progress;
    }

    // ---- Fragmentation pressure: prefer bins whose residual is below mean (tight packing) ----
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // ---- Small tie-breaker on exact fill ratio ----
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever host the
    // minimum item size (1) are pure waste; residuals below ~15 are
    // practically unusable for most items. Penalize quadratically.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: best possible outcome
    } else if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0; // dead space penalty
    } else if post_residual < 20 {
        score += 8.0; // marginal gap
    }

    // Reward tight fits relative to residual (fill ratio of the used space).
    if bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fill * fill;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chains items perfectly).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 15.0; // placing here would strand space below next item
        } else if post_residual >= next_item_size {
            score -= 5.0; // next item still fits after this placement
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current bin fit is poor. Penalize the fresh bin mildly, more when
    // many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 1.5;
        // But if the item is large relative to capacity, a fresh bin
        // preserves flexibility for future big items.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: prefer placing into existing bins when many are
    // open, to keep the active set small.
    score += open_bins_count as f64 * 0.8;

    // Slight preference for bins whose residual deviates favorably from
    // the mean (below-mean residual = tighter bin, prefer filling it).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream consolidation: as the stream progresses, tighten up
    // and avoid opening new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.84;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Penalize leaving residuals that are too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0; // moderately awkward residual
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bin fits poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // cheaper to open new bin when few bins open or mean residual is low
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        score -= mean_residual * 0.3;
        // if next item is large, fresh bin is valuable
        if next_item_size >= 50 {
            score -= (next_item_size as f64 - 50.0) * 0.5;
        }
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 12.0 - slack; // near-perfect chaining
        }
    } else if next_item_size > 0 {
        // penalize residuals that cannot host the next item
        score += (next_item_size as f64 - post_residual as f64) * 0.15;
    }

    // Mild pressure to consolidate into fewer bins as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (item_size as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to item size (best-fit flavor)
    let fit_gap = (bin_residual - item_size) as f64;
    score += fit_gap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), smoothed by progress
    let mut score = pr * (1.0 + progress * norm_pr);

    // Non-linear coupling: residual vs mean residual across open bins.
    // Prefer bins whose residual deviates favorably (tighter than average).
    let mr = mean_residual / cap;
    score += (norm_pr - mr).abs() * cap * (0.5 + 0.5 * progress);

    // Lookahead: reward if next item fits in post residual (smooth bell via squared term)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx) / cap;
        if gap >= 0.0 {
            score -= (1.0 - gap * gap) * (6.0 + 8.0 * progress);
        } else {
            score += (-gap) * cap * 0.8;
        }
    }

    // Last chance: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless residual would be near full
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress - 0.15 * item_size as f64;
    }

    // Mild penalty for too many open bins relative to progress
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (small gaps that few future items can fill) are heavily penalized.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 25.0;

    // Penalize wasting a large residual on a small item (poor utilization).
    if (item_size as f64) < 0.35 * bin_residual as f64 {
        score += (bin_residual as f64 - item_size as f64) * 0.6;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway: mild penalty for stranding space.
        score += 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new one is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = open_bins_count as f64 * (1.0 + 0.5 * progress) * 3.0;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: baseline cost plus open-bin pressure.
        score = new_bin_penalty + 20.0;
        // A new bin is attractive if the item is large relative to mean residual
        // (poor fit anywhere else).
        if (item_size as f64) > mean_residual * 0.9 {
            score -= 15.0;
        }
        return score;
    }

    // Slight bonus for choosing bins with below-average residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Aggressive 2-step lookahead: reward when next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: fill completely with next item
        } else if next_item_size < post_residual {
            let nr = post_residual as f64;
            let slack = nr - next_item_size as f64;
            // favor small slack after chaining; penalize large unusable remainder
            score += slack * 0.3;
            if slack <= 10.0 {
                score -= 15.0;
            }
        } else {
            // next item cannot follow into this bin
            score += 12.0;
        }
        // Coupling with mean residual: if bin is above average fullness, encourage using it
        let dev = mean_residual - post_residual as f64;
        score += dev * 0.2;
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer the tightest ones more strongly
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // opening a new bin: penalize mildly, more if open bins are quite empty
        score += 35.0;
        if mean_residual > 60.0 {
            score -= 20.0; // existing bins are crowded -> new bin is reasonable
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
    }

    // Penalize creating very small dead space (<10) that nothing (min size 1..100) may use well
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (low post_residual already does this).
    // Reward near-perfect fits extra.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    } else {
        // penalize dead space non-linearly: large leftovers are hard to reuse
        let dead = post_residual as f64;
        score += 0.05 * dead * dead;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if the next item is bigger than post residual, penalize slightly less.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            let gap = pr - nx;
            if gap == 0.0 {
                score -= 80.0; // perfect chain
            } else {
                score -= 20.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            score += 10.0 + 0.1 * (nx - pr);
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 150.0;
        // If this bin is the only option or fits poorly elsewhere, allow opening.
        if fitting_bins_count == 0 {
            score -= 400.0;
        } else if fitting_bins_count == 1 {
            // compare: opening new bin vs last-chance bin; keep last-chance favored
            score -= 60.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 80.0 * (1.0 - progress);
        // Many open bins with large mean residual: prefer reusing them.
        score += 0.5 * mean_residual;
        score += 5.0 * open_bins_count as f64;
    }

    // Slight preference for bins with less residual than average (consolidate).
    if bin_residual < bin_capacity {
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Normalized post-residual, base term: prefer tight fits.
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, waste is cheap-ish; late, waste is heavily penalized.
    let pr2 = pr * pr / (cap * cap);
    let pr3 = pr2 * pr / cap;
    score += (0.4 + 1.6 * progress) * pr2;
    score += (0.1 + 0.9 * progress * progress) * pr3;

    // Interaction with mean residual: bins far below mean residual are
    // attractive sinks; bins above mean residual get penalized.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.5 * dev * dev * (0.5 + progress);
    score -= 0.3 * dev * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // (smoothly scaled by how well the item fills the bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 + 3.0 * (1.0 - pr / cap);
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or stream is early and residuals are large.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 0.6 + 0.5 * progress;
        score -= 1.2 * fill * fill;
        if fitting_bins_count <= 1 {
            score -= 0.8;
        }
        // lookahead: if next item is big, a fresh bin is valuable
        let nx = next_item_size as f64 / cap;
        score -= 0.5 * nx * nx;
    }

    // Lookahead synergy: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 0.4 * (1.0 - gap) * (1.0 - gap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: partition post_residual into residue classes mod 10
    // (smallest item granularity). Residuals that are "too small to be useful"
    // (1..=9) are dead space -> penalize; residuals that are multiples of 10
    // remain reusable by small items -> reward mildly.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0 + (10 - pr) as f64 * 3.0; // dead space penalty
    } else if pr % 10 == 0 && pr > 0 {
        score -= 8.0; // clean class, reusable
    } else if pr >= 10 {
        // fractional-class penalty: awkward remainder reduces usability
        let rem = pr % 10;
        score += rem as f64 * 0.8;
    }

    // Integer-division thresholds: classify post_residual into capacity fractions
    let frac = pr as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 15.0; // bin still more than half open: very attractive
    } else if frac > 0.25 {
        score -= 5.0;
    } else if pr > 0 {
        score += 10.0; // less than quarter left: near-closed bin
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size <= pr {
            score -= 20.0;
        } else {
            // next item won't fit here; small residual becomes dead sooner
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large relative to capacity and no good fit exists.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 40.0;
        if item_size >= bin_capacity / 2 {
            score -= 55.0; // large items: fresh bin fine
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing fits anywhere: must open
        }
        // late in stream, fewer open bins => prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Prefer tighter existing bins: compare with mean residual
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    // Mild preference to keep number of open bins from exploding
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small gaps that only tiny items could use are near-dead space.
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> penalize opening new ones,
    // reward consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / 20.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + open_pressure * 30.0;
    } else {
        score -= open_pressure * 5.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        // This placement blocks the next item's smallest usable gap.
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is above average
    // when the average is high (spread items), below average when low (tighten).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Late in stream: be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match of post_residual with next item -> chain fill.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward, better if residual stays small
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the residual: penalize dead space
            score += 30.0;
        }
    }

    // Penalize residuals too small to be useful (dead space below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 2.0;

    // New empty bin candidate: penalize opening unless it enables a perfect/lookahead fit
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && (next_item_size == post_residual || post_residual == 0) {
            score -= 600.0;
        }
        // late in stream, opening new bins is less attractive
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Prefer filling bins that are already mostly full (small residual before placement)
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tight * tight;
    }

    // Penalize dead space that no future item could plausibly fill:
    // smallest plausible item is ~1, but typical items are larger; penalize
    // residuals that are small but nonzero (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // next item can still fit here: mild reward proportional to fit quality
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving a residual close to
            // but smaller than the next item (wasted opportunity).
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 0.8 * (15.0 - gap);
            }
        }
    }

    // Global pressure: many open bins with high mean residual -> favor
    // consolidating into existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when existing bins are underutilized.
        score += 15.0 + 3.0 * pressure;
        // Early in the stream a new bin is cheaper; late in the stream prefer reuse.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        score -= 2.0 * pressure.min(10.0);
    }

    // Prefer bins whose residual is already close to the item (best-fit core),
    // scaled by how full the bin already is.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill;

    // Mild penalty for very large items going into nearly-empty bins when
    // other bins could take them (keep big bins flexible).
    if item_size >= 60 && bin_residual >= 90 && fitting_bins_count > 1 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * (0.5 - progress * progress);

    // Penalize large dead space more aggressively as the stream progresses.
    let dead = norm_pr * norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Reward tight fits (small post_residual) with mild nonlinearity.
    let tight = -norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    let last_chance = if fitting_bins_count == 1 { -1.5 * (1.0 + progress) } else { 0.0 };

    // Lookahead: reward bins whose post_residual can host the next item.
    let nxt = next_item_size as f64;
    let lookahead = if nxt > 0.0 {
        if pr >= nxt { -0.8 * (pr / cap) * (1.0 - nxt / cap) }
        else { 0.6 * (nxt - pr) / cap }
    } else { 0.0 };

    // Mild penalty for proliferating bins relative to mean residual.
    let spread = (pr - mean_residual) / cap;
    let spread_term = 0.3 * spread * spread.abs();

    // New-bin candidate: prefer opening a fresh bin only when existing fits are poor.
    let new_bin = if bin_residual == bin_capacity {
        0.5 + 1.2 * progress + 0.5 * (item_size as f64 / cap)
    } else { 0.0 };

    pr + poly + dead + tight + last_chance + lookahead + spread_term + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
