pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals below the minimum item size (1..100 unknown,
    // so treat < 20 as likely dead) are heavily punished, scaled by how dead they are.
    if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 12.0;
    } else if post_residual < 40 {
        score += (40.0 - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // If the next item fits exactly in the post residual, this placement chains perfectly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 25.0;
    }
    // Penalize if next item cannot fit in the post residual but could have fit elsewhere:
    // creating a gap that strands the lookahead.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over opening new.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Prefer bins whose residual is close to the mean (balanced packing) slightly.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    // New-bin candidate: an empty bin should only win for large items that would
    // leave open bins fragmented, or early in the stream. Make empty bin expensive otherwise.
    if bin_residual == bin_capacity {
        let large_item = item_size > bin_capacity / 2;
        let early = progress < 0.15;
        if large_item {
            score -= 10.0; // large items pack cleanly into fresh bins
        } else if early {
            score += 5.0;
        } else {
            score += 60.0 + open_bins_count as f64 * 2.0;
        }
        // If no open bin can even fit the item, the new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // (or nearly) matches the next item's size, i.e. the leftover space is
    // immediately usable by the following item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item fills this bin exactly -> big reward.
        if gap == 0.0 {
            score -= 60.0;
        } else {
            // Penalize leftover space that the next item cannot use.
            score += gap * 0.5;
            // If next item fits into post_residual, mild bonus for tight chain.
            if post_residual >= next_item_size {
                score -= 8.0 * (1.0 - gap / (post_residual as f64 + 1.0));
            } else {
                // Dead space the next item can't use: extra penalty.
                score += gap * 0.3;
            }
        }
    }

    // Compare post_residual against the mean residual: leaving this bin far
    // above the mean wastes capacity relative to the fleet average.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.25;
    } else {
        score += dev * 0.15; // slightly reward going below mean residual
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and would leave a very awkward residual elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 {
            score -= 20.0; // large items are fine to start fresh bins
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin supports the lookahead chain
        }
    }

    // Tight fits are good: reward small post_residual (with lookahead already
    // handled above, this reinforces compact packing).
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Late in the stream, consolidate harder (fewer residual fragments).
    let progress = step_index as f64 / total_items as f64;
    score += dev.abs() * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever be useful again.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits (within 10), mild reward.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity unless
    // the item is large and no open bin gives a tight fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Large items pack well into fresh bins; small items should use open bins.
        score += 45.0 * (1.0 - fit_quality);
        // Early in stream, opening bins is fine; late, avoid fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If many bins already open, discourage another.
        score += 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean: a bin with
    // residual below mean is scarcer space; using it up is fine, but bins far
    // above mean are good dumping grounds for small items.
    let dev = bin_residual as f64 - mean_residual;
    if item_size >= 50 {
        score -= 0.15 * dev;
    } else {
        score += 0.10 * dev;
    }

    // Mild preference for using existing bins as stream progresses.
    if !is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * progress;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, with non-linear (quadratic) dead-space term
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = (1.0 - progress) * pr + progress * pr * pr / cap;
    score += 0.5 * coupling;

    // Tight fits are desirable; reward quadratically as post_residual approaches 0
    score -= 60.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1e-9 {
        score -= 25.0;
    } else if next_item_size as f64 > pr && pr > 0.0 {
        // next item cannot use leftover space; penalize proportionally
        score += 10.0 * (1.0 - pr / cap);
    }

    // Mean residual context: prefer bins near the mean (smooth Gaussian-like term)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by coarse capacity fractions.
    // Small post_residual = tight fit (good), but too-small leftover is dead space.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Class 0: post_residual == 0 -> perfect closure, strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Class 1: tiny dead space (<= 10) -> almost perfect, reward heavily.
    else if post_residual <= 10 {
        score -= 40.0;
    }
    // Class 2: medium leftover (11..=30) -> still usable by typical items, mild reward.
    else if post_residual <= 30 {
        score -= 12.0;
    }
    // Class 3: awkward leftover (31..=49) -> too big to ignore, too small for big items; penalize.
    else if post_residual <= 49 {
        score += 8.0;
    }
    // Class 4: half-bin leftover (50..=70) -> good buffer for medium items.
    else if post_residual <= 70 {
        score -= 5.0;
    }
    // Class 5: large leftover (>70) -> nearly empty bin, wasteful for small item.
    else {
        score += 15.0;
    }

    // Integer-division harmonic: reward when post_residual falls on common divisor lattice
    // (multiples of 10 align with typical item sizes), penalize off-lattice values.
    let lattice = post_residual % 10 == 0;
    if lattice {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Lookahead coupling: if next item can exactly fill post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // Next item fits: leftover remains usable, reward proportional to closeness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use this leftover: penalize proportionally to waste.
            let over = (next_item_size - post_residual) as f64;
            score += 10.0 * (over / bin_capacity as f64).min(1.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only when
    // no open bin offers a good harmonic fit (i.e., when its raw score is competitive).
    if bin_residual == bin_capacity {
        // Neutral baseline with mild penalty so tight fits in open bins win,
        // but poor fits (high scores above) lose to the fresh bin.
        score = 45.0 + 0.5 * (open_bins_count as f64);

        // If the current item is large relative to capacity, fresh bin is attractive.
        if item_size >= 60 {
            score -= 15.0;
        }
        // If many bins are open with low mean residual, avoid spreading.
        if open_bins_count > 3 && mean_residual < 35.0 {
            score += 10.0;
        }
        // Late in the stream, consolidation matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * progress;
    }

    // Mild global pressure: more open bins -> encourage filling existing ones.
    score += 0.3 * (open_bins_count as f64);

    // Mean-residual alignment: prefer bins whose residual is near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // A residual gap is "dead" if it's too small for the smallest plausible item.
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual < dead_threshold {
        // Perfectly tight fit is great; a 1-8 unit gap is wasted capacity.
        score += 60.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 80.0;
    }

    // Non-linear dead-space risk: gaps that no typical item (10..80) can use
    // given the lookahead item are doubly penalized.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This gap cannot host the next item either -> likely permanent dead space.
        score += 25.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap can host the lookahead item: reward chaining.
        score -= 15.0 + 0.3 * (post_residual - next_item_size) as f64;
    }

    // Reward using bins that would otherwise be wasted (last-chance bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation into
    // existing bins; when few bins are open, tolerate spreading.
    let pressure = (open_bins_count as f64).ln() * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure,
        // but allow opening when mean residual of open bins is already low
        // (i.e., existing bins are nearly full and poor hosts).
        score += 45.0 + pressure - mean_residual * 0.8;
    } else {
        // Existing bin: mild reward scaled by pressure to keep bins closed.
        score -= pressure * 0.4;
    }

    // Slight preference for fuller bins overall (best-fit flavor with bite).
    score -= 0.6 * (bin_capacity - bin_residual) as f64;

    // Late in the stream, tighten up: avoid leaving any gap that could
    // have been used, since fewer items remain to exploit large residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
