pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Exact-fill jackpot.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + (next_item_size as f64) * 0.25;
        } else {
            // Creating a gap the next item cannot use is waste.
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins (larger item relative to residual) to compact state.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    // Mild penalty proportional to how far this bin's residual is below the
    // mean residual: keep a diverse residual portfolio.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev.abs();

    // Late in the stream, consolidate aggressively into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (open_bins_count as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 25.0 + 20.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        let scarcity_relief = if fitting_bins_count == 0 { 45.0 } else { 0.0 };
        score += base_penalty - scarcity_relief;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit), polynomially amplified
    let mut score = pr as f64;
    score += 12.0 * norm_pr * norm_pr;

    // Dead-space penalty: residual too small for any plausible item (sizes >= 1)
    let dead = ((22.0 - pr).max(0.0)) / 22.0;
    score += 30.0 * dead * dead;

    // Stream-progress coupling: later in the stream, be greedier about tight fits
    score -= 8.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: reward residual that can still host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 10.0 * (1.0 - (n / cap)) * progress;
        } else {
            score += 6.0 * ((n - pr) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure against proliferating bins with large residuals
    score += 0.05 * (open_bins_count as f64) * norm_pr;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 18.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition dead space into capacity-eighth classes.
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // 0..=8 harmonic class
    // Reward tight fits: lower class (smaller post_residual) gets bigger subtraction.
    score -= (8 - class as f64) * 6.0;

    // Penalize dead space that cannot host the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // post_residual is reusable by lookahead -> strong reward
        } else {
            // Dead space penalty grows as gap to next item grows.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Exact modulo harmony: post_residual == next_item_size mod small classes
        if post_residual == next_item_size {
            score -= 10.0;
        }
        if post_residual % 10 == 0 && next_item_size % 10 == 0 {
            score -= 2.0; // same decimal harmonic class, likely future compatibility
        }
    } else {
        // Last item: minimize waste entirely.
        score += post_residual as f64 * 0.5;
    }

    // Integer-division thresholds on post_residual: unusable slivers (< 10) are worthless.
    if post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if item is large relative to capacity and mean residual is tight, opening is fine.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 && mean_residual < frac * bin_capacity as f64 * 0.5 {
            score -= 30.0;
        }
    }

    // Stream progression: late in stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.4;

    // Spread control: prefer bins whose residual deviates productively from mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    // Prefer filling more full bins when many bins are open (bin consolidation).
    if open_bins_count > 4 && post_residual < item_size {
        score += 3.0; // leaving a bin nearly empty is worse than spreading
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted forever.
    if post_residual < 10 && post_residual > 0 {
        score += 200.0;
    } else if post_residual < 20 {
        score += 40.0;
    } else if post_residual < 30 {
        score += 12.0;
    } else {
        score -= 5.0; // reward leaving a usable gap
    }

    // Perfect or near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack.min(25.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item cannot use this bin's leftover anyway
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
        if post_residual < 10 && post_residual > 0 {
            score -= 40.0; // still better than wasting a fresh bin
        }
    }

    // Open-bin pressure: penalize creating more bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are nearly full on average
        // and the item is large (poor fit candidates elsewhere).
        let pressure = (open_bins_count as f64) * 25.0
            + (mean_residual / bin_capacity as f64) * 40.0
            + (item_size as f64) * 0.8;
        score += pressure;
        // Late in the stream, be more conservative about opening bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 30.0;
        }
    } else {
        // Reward using existing bins, more so when many are open.
        score -= (open_bins_count as f64).ln().max(0.0) * 6.0;
    }

    // Mild preference for tighter bins overall.
    score += (bin_capacity as f64 - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when next item fits perfectly into the post-residual (2-step lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: this bin will be exactly filled next step
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64); // next item fits, reward tight fits
        } else {
            // next item does NOT fit: post_residual becomes dead space until something smaller arrives
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 * (waste / bin_capacity as f64) * 10.0;
        }
    }

    // Penalize post-residuals that are too small to ever be useful (dead space below min item size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Prefer bins whose residual is close to the mean residual (balanced packing),
    // penalize outliers relative to mean_residual.
    let mean_dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 - 15.0 * progress + 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can absorb the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residuals too small for likely future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0 * (next_item_size as f64 - post_residual as f64).sqrt();
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer reuse
    let pressure = mean_residual / bin_capacity as f64;
    score -= pressure * (open_bins_count as f64).ln().max(1.0) * 4.0;

    // Time horizon: early on, prefer opening new bins (spread items); late, pack tightly
    if bin_residual == bin_capacity {
        // new-bin candidate
        let early_bonus = (1.0 - t) * 10.0;
        score -= 20.0 - early_bonus;
        if next_item_size > 0 && next_item_size > post_residual {
            score += 8.0; // fresh bin won't fit next item either
        }
    } else {
        score += t * 5.0; // late stream: favor existing bins slightly more
    }

    // Small coupling: prefer bins whose residual is close to item size (perfect fill)
    let diff = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 8.0 * diff * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Base cost: residual left after placement, weighted to matter more early.
    let w = 1.0 + 0.5 * (1.0 - progress) * (1.0 - progress);
    let mut score = w * post;

    // Smooth quartic penalty on waste relative to capacity.
    let waste_frac = post / cap;
    score += 40.0 * waste_frac * waste_frac * waste_frac * waste_frac * cap * 0.01;

    // Reward tight fits: item filling most of the residual (smooth via product term).
    let fill = item / bin_residual.max(1) as f64;
    score -= 30.0 * fill * fill * (1.0 + progress);

    // Reward exact/near-exact closure of the bin (post_residual near 0).
    let closeness = (cap - post) / cap; // fraction of capacity used
    score -= 20.0 * closeness * closeness * closeness;

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let nfrac = next_item_size as f64 / cap;
        score -= 15.0 * nfrac * (1.0 - progress * 0.5);
    }
    // Penalize leaving residual too small for the lookahead item (dead space).
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        let gap = (next_item_size as f64 - post) / cap;
        score += 12.0 * gap * gap * cap * 0.01;
    }

    // Last-chance bonus: only bin that fits -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for spreading across many bins early (encourage consolidation later).
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize slightly so open bins with decent fit win,
    // but allow opening when residual is badly fragmented.
    if bin_residual == bin_capacity {
        score += 8.0 - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post_residual (tight fit)
    let mut score = post_residual as f64;

    // Harmonic class of the residual: dead space is worse when it cannot
    // accommodate typical future items. Penalize residuals in "useless"
    // classes (small leftovers that no item in 1..=100 fits well).
    let r = post_residual;
    if r > 0 {
        let class = r / 10; // integer division threshold on residual
        match class {
            0 => score += 30.0,        // 1..=9 : nearly dead space
            1 => score += 12.0,        // 10..=19 : only tiny items fit
            2 => score += 4.0,         // 20..=29 : moderately useful
            3 => score += 0.0,         // 30..=39 : useful
            4 => score += 2.0,         // 40..=49 : fine
            _ => score -= 1.0,         // >=50 : very reusable
        }
    }

    // Lookahead coupling: reward if the next item fits the post_residual,
    // penalize if post_residual is just barely too small for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else if post_residual > 0 && next_item_size - post_residual <= 10 {
            score += 6.0; // agonizing near-miss: dead space for the known next item
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // no open bin offers a decent fit. Give the empty bin a penalty that
    // shrinks when many bins are open and mean residual is large.
    if bin_residual == bin_capacity {
        score += 15.0
            + 0.3 * open_bins_count as f64
            + (mean_residual / 10.0).min(10.0);
        // But if the item is huge relative to capacity, a fresh bin is fine
        if item_size * 2 >= bin_capacity {
            score -= 20.0;
        }
    }

    // Progress modulation: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // Prefer bins whose residual is close to the mean (balance spreading),
    // slightly penalize outliers.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical items (1..=10 minimum) are wasted space; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving residuals that can host the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for next item: mild dead-space penalty.
        score += 8.0;
    }

    // Tight fit reward: item fills a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins, but
    // relax pressure late in the stream when consolidation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (3.0 - 1.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin is expensive unless the item
    // is large relative to remaining space in open bins.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
        // But allow fresh bin if item is big and fits poorly elsewhere.
        if item_size >= 60 && post_residual < 40 {
            score -= 45.0;
        }
    }

    // Prefer bins whose residual is close to item size (best-fit coupling).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    score = post_residual as f64 * 1.5;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chaining bonus: next item consumes all remaining space.
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            // Penalize residuals that neither fit next item nor stay useful.
            if post_residual < next_item_size {
                // Dead space relative to lookahead item.
                score += gap * 0.6;
            } else {
                // Next item fits but leaves another residual; mild penalty by gap.
                score += gap * 0.25;
            }
        }
        // If next item can't fit anywhere else well, favor bins leaving it room.
        let next_fits = post_residual >= next_item_size;
        if next_fits {
            score -= 8.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 5.0;
    }

    // Compare post_residual against mean residual: leaving less than average
    // means this bin was used efficiently relative to fleet.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(50.0) * 0.35;
    } else {
        score += (pr - mean_residual).min(50.0) * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 12.0;
        // But if the fit creates a huge dead zone, soften the bonus.
        if pr > 40.0 {
            score += (pr - 40.0) as f64 * 0.4;
        }
    }

    // New-bin candidate handling: opening a new bin wastes capacity when a
    // decent fit exists. Penalize the empty bin unless all fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If many bins fit the item, definitely prefer an existing bin.
        if fitting_bins_count >= 2 {
            score += 25.0;
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If lookahead suggests a perfect chain elsewhere is impossible,
        // opening fresh is more acceptable when existing residuals are small.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight reward for using bins with more open bins already (consolidation),
    // keeps bin count low.
    score += open_bins_count as f64 * 0.05;

    // Tiny tie-break noise-free deterministic jitter based on residual parity.
    if post_residual % 2 == 0 {
        score -= 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize residual that is too small to ever be useful again (< 10).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual > 60 {
        // Large leftover is fine only if it matches likely future items.
        score += 6.0;
    }

    // Lookahead coupling: reward bins whose post-residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let chain_tight = 1.0 - (post_residual - next_item_size as u32) as f64 / cap;
            score -= 8.0 * chain_tight;
        } else {
            // Penalize leaving a residual that cannot host the next item.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Competition pressure: with many open bins, prefer consolidating into existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.5 * pressure * (post_residual as f64 / cap);

    // Global mean residual alignment: prefer bins near the mean residual
    // (keeps residual distribution balanced, avoids stranding outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // later, accept decent fits more readily since fewer items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 8.0 * (post_residual as f64 / cap);

    // New-bin candidate: only attractive when no open bin fits well or
    // the item is large enough that a fresh bin is the natural home.
    if bin_residual == bin_capacity {
        let no_good_fit = fitting_bins_count == 0
            || (item_size as f64 / cap > 0.7 && next_item_size as f64 / cap > 0.7);
        if no_good_fit {
            score -= 20.0;
        } else {
            score += 15.0 + 10.0 * pressure;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.8 * progress * norm_pr);

    // Reward tight fits: quadratic bonus shrinking with post_residual
    let tightness = (1.0 - norm_pr).powi(2);
    let mut score = base - 30.0 * tightness;

    // Penalize dead space that is too small for likely future items
    let next = next_item_size as f64;
    if next > 0.0 && pr < next {
        score += (next - pr) * (0.5 + progress);
    } else if next > 0.0 && pr >= next && pr < next * 2.0 {
        score -= 10.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Slight pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Mean residual alignment: prefer bins near the mean residual (smooth)
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Class residuals into buckets of size 10 (classic bin-packing granularity).
    let bucket = post_residual / 10;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small residuals, but with a harmonic (modular) twist:
        // residuals that are exactly usable by typical item sizes (multiples of 10, 20)
        // are less dead than awkward residuals (e.g. 1..9 slivers).
        let awkward = post_residual % 10;
        if awkward > 0 && post_residual < 10 {
            // tiny unusable sliver: strong penalty (dead space)
            score += 40.0;
        }
        // Reward residuals that could fit common future items (multiples of 5/10 classes)
        if post_residual % 10 == 0 {
            score -= 15.0;
        } else if post_residual % 5 == 0 {
            score -= 7.0;
        }
        // Harmonic ladder on bucket: bigger buckets are better (more reusable space)
        score -= (bucket as f64) * 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // penalize by leftover gap after chaining, modulated harmonically
            score -= 30.0 - ((gap % 10) as f64) * 2.0;
        } else {
            // next item cannot follow here; mild penalty scaled by overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += (overflow * 0.15).min(25.0);
        }
    } else {
        // last item: just minimize residual
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins fit badly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = 100.0 + post_residual as f64;
        // cheaper to open a new bin when many bins are already open and mean residual is high (fragmented)
        if open_bins_count > 3 && mean_residual > 30.0 {
            score -= (mean_residual - 30.0) * 0.5;
        }
        // if the item is large relative to capacity, a fresh bin gives clean packing
        if item_size * 2 >= bin_capacity {
            score -= 20.0;
        }
        // if no open bin fits well (post residual would be tiny sliver), new bin is attractive
        if fitting_bins_count >= 1 {
            // neutral: comparison against open-bin scores decides
            score -= 10.0;
        }
    } else {
        // prefer fuller bins: reward low residual relative to capacity
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 30.0;
    }

    // Progress modulation: late in the stream, be more conservative about new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 25.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward residuals that can still host a typical future item.
    if post_residual >= 10 && post_residual <= 80 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 25.0;
    }
    // Penalize if next item could have fit here but placement leaves it stranded.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it unattractive unless the item barely fits
    // anywhere else or existing bins have tiny residuals.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count > 0 {
            score += 25.0 * (fitting_bins_count as f64).min(3.0);
        }
        // If item is small, new bin wastes lots of space potential.
        score += (100 - item_size.min(100)) as f64 * 0.2;
    }

    // Slight preference for tighter bins overall (small residual = good fit).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Late-stream consolidation bias.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += (post_residual as f64) * 0.1 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect-fit bonus: waste nothing.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward when the next item exactly fills
    // the post residual, mildly reward small gaps, penalize large unusable ones.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) == nxt {
            score -= 500.0; // chain placement: next item seals this bin
        } else if next_item_size <= post_residual {
            let gap = post_residual as f64 - nxt;
            score -= 150.0 * (1.0 - gap / cap); // next item still fits well
        } else {
            // next item cannot use the residual: dead-space penalty grows
            // with how much of the bin's remaining space is stranded.
            let stranded = post_residual as f64 / cap;
            score += 80.0 * stranded * stranded;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is already below
    // average (denser bins), penalize dumping into very roomy bins.
    let res = post_residual as f64;
    score += 0.5 * (res - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: a fresh empty bin is only attractive when
    // no good fit exists among open bins (large item relative to mean residual).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        let pressure = if mean_residual > 0.0 { item_size as f64 / mean_residual } else { 0.0 };
        // penalize default new bin; discount when stream is late or item is large
        score += 300.0 - 200.0 * tightness - 50.0 * pressure.min(3.0)
                 - 100.0 * (step_index as f64 / total_items.max(1) as f64);
        // if next item is huge and would need a fresh bin anyway, opening now is fine
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 60.0;
        }
    }

    // Mild crowding penalty: too many open bins -> prefer consolidation.
    score += 3.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 8.0 + 6.0 * (1.0 - slack_after_next / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty scaled by how far off
        let gap = (next_item_size - post_residual) as f64;
        score += 2.0 * (gap / bin_capacity as f64).min(1.0);
    }

    // Reward near-perfect packing (small post_residual) with a non-linear boost
    let pr = post_residual as f64;
    score -= 10.0 * (-pr / 15.0).exp();

    // Penalize leaving a residual that is hard to fill later (in the awkward 1..=9 zone)
    if post_residual >= 1 && post_residual <= 9 {
        score += 6.0 - (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins with high mean residual: encourage consolidating into fuller bins
    if open_bins_count > 2 && mean_residual > 0.0 {
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 4.0 * fullness * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // Late in the stream: prefer tighter placements, discourage opening new bins
    score += progress * (pr * 0.15);

    // New-bin candidate: penalize unless item is large relative to capacity and
    // no good consolidation incentive exists
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        let early = 1.0 - progress;
        score += 15.0 - 10.0 * size_frac - 5.0 * early;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0; // fresh bin that can also host next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, non-linearly scaled by stream progress
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Polynomial coupling: dead space penalty grows quadratically late in the stream
    let dead = norm_pr * norm_pr;
    score += 60.0 * dead * (0.5 + progress);

    // Cubic interaction of post-residual with progress
    score += 20.0 * norm_pr * norm_pr * norm_pr * (1.0 - progress);

    // Reward near-perfect fits smoothly (smooth inverse coupling)
    let fit_quality = 1.0 - (pr / cap).powf(2.0);
    score -= 15.0 * fit_quality * fit_quality;

    // Last-chance bonus: penalize leaving this bin unused when it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * (1.0 - norm_pr);
    }

    // Lookahead: smooth reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 6.0 * fits_next * (1.0 - gap / cap);
    }

    // Mean residual coupling: penalize bins far from the fleet mean, smoothly
    score += 0.05 * (pr - mean_residual).abs();

    // Crowding penalty: many open bins -> favor consolidation
    score += 0.3 * (open_bins_count as f64).sqrt() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "small" classes (<=10) are dead
    // space; reward reaching them, penalize landing in awkward mid classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class via integer division thresholds (harmonic bands: 0-10, 11-25, 26-50, 51-100)
    let class = post_residual / 25; // 0,1,2,3,4
    match class {
        0 => score -= 30.0,                       // near-perfect fill
        1 => score -= 5.0,                        // small leftover, still usable
        2 => score += 0.0,                        // mid leftover
        3 => score += 8.0,                        // half-ish leftover, wasteful for small item
        _ => score -= 100.0,                      // empty/new bin class handled below
    }

    // New-bin candidate: neutral baseline; open a fresh bin when fits are bad.
    if bin_residual == bin_capacity {
        score = 45.0;
        // If this is the only fitting option, new bin is attractive.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // Early in stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post-residual exactly or closely,
    // reward this placement (harmonic pairing of item classes).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 5.0 {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item cannot fit here; leftover becomes pure dead space
            score += 0.5 * (next_item_size as f64 - post) ;
        }
    }

    // Prefer bins below the mean residual (tighter bins get filled first),
    // keeping looser bins available for larger future items.
    let dev = mean_residual - post;
    score += 0.15 * dev;

    // Modulo-style penalty: residuals that waste more than a quarter capacity
    // relative to item class granularity (items 10..80) are penalized.
    if post_residual > 0 && post_residual % 10 != 0 {
        score += 2.0;
    }

    // Tie-break: spread placements across bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual that can never fit another item (assuming min size 1..100 unknown,
    // use a conservative "dead zone" around very small residuals) is wasted space.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Non-linear penalty on post_residual in the "awkward" mid-small range:
    // gaps of 1..30 are hard to fill for typical item sizes.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // next item fits: leftover after that placement is the real dead space
            let chain_dead = post_residual - next_item_size;
            if chain_dead < 10 {
                score += chain_dead as f64 * 2.0;
            }
        } else {
            // next item cannot use this bin's leftover: dead space likely permanent
            score += post_residual as f64 * 0.3;
        }
    }

    // Open bins pressure: discourage spreading across many open bins;
    // prefer filling existing bins when open_bins_count is high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the current fit would create large dead space.
    if bin_residual == bin_capacity {
        // Neutral baseline; the dead-space penalties above on real bins will
        // make a new bin preferable when fits are poor.
        score += 20.0;
    }

    // Mild alignment with mean residual: prefer bins below mean (tighter bins)
    // to keep average slack concentrated.
    if (post_residual as f64) > mean_residual {
        score += ((post_residual as f64 - mean_residual) * 0.2).min(10.0);
    } else {
        score -= (mean_residual - post_residual as f64).min(10.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-match: next item fits with small slack left over.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.5;
    }

    // Penalize leaving dead space that can't fit the next item (below min size ~1..10).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += post_residual as f64 * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin's post-fit is wasteful
    // relative to mean residual (i.e., this bin would become dead space).
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 && post_residual as f64 > mean_residual + 10.0 {
            score -= 25.0;
        }
        if next_item_size == 0 {
            score += 30.0;
        }
    }

    // Tighten fit preference: reward small post_residual relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Early stream: keep bins tight; late stream: consolidate to avoid many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 - (open_bins_count as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else {
            score += 6.0;
        }
        // Bonus if bin currently also fits next item (keeps pair together).
        if bin_residual >= item_size + next_item_size {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: discourage opening a new bin unless it
    // produces a much better global configuration than any open bin.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base cost of opening a new bin, decaying with stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0 - 20.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            new_bin_cost += 30.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If item is large, a fresh bin may be genuinely useful.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_cost -= 25.0;
        }
        score += new_bin_cost;
    }

    // Global state coupling: prefer filling bins with high residual when
    // mean residual across open bins is large (fragmentation danger).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for bins among many open bins (consolidation).
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, keep bins flexible (favor mid-size
    // post residuals); late in stream, squeeze maximally.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let ideal_post = (1.0 - progress) * 30.0 + progress * 2.0;
    score += 0.3 * (post_residual as f64 - ideal_post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping
    let mut score = 3.0 * norm_pr - 2.0 * norm_pr * norm_pr + 1.5 * norm_pr.powi(3);

    // Smooth coupling of post_residual with stream progress:
    // late in stream, tighten more aggressively (weight dead space higher)
    let tightness = 1.0 + 2.0 * progress * progress;
    score *= tightness;

    // Penalize bins whose post residual is far below mean residual (wasted potential)
    let mean_norm = mean_residual / cap;
    score += 0.8 * (norm_pr - mean_norm).abs() * (0.5 + progress);

    // Last-chance bonus: only one fitting bin -> strong reward for using it
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward if next item fits smoothly into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 2.5 * (1.0 - (nxt / cap)) * (1.0 - progress * 0.3);
        } else {
            score += 1.2 * ((nxt - pr) / cap) * (0.5 + progress);
        }
    }

    // Mild penalty for proliferating bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: make empty bin moderately attractive only when fit is bad
    if bin_residual == bin_capacity {
        score = 2.0 + 4.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (integer division thresholds) ---
    // Class = post_residual / 10; lower classes (tighter packing) are favored.
    let class = (post_residual / 10) as f64;
    score += class * 1.5;

    // Sub-class alignment: residues near a multiple of 10 are "harmonic" and
    // statistically easier to fill later; penalize awkward offsets.
    score += (post_residual % 10) as f64 * 0.35;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // --- Dead-space penalty: bin becomes unusable for the lookahead item ---
    if next_item_size > 0 && post_residual < next_item_size {
        score += 22.0;
        // Extra penalty for truly tiny dead space (worst harmonic class).
        if post_residual < 10 {
            score += 8.0;
        }
    } else if next_item_size > 0 {
        // Post-residual can host the next item; reward harmonic compatibility.
        let compat = post_residual - next_item_size;
        if compat % 10 == 0 {
            score -= 6.0;
        }
        score -= 4.0;
    }

    // --- Last-chance bin: avoid opening a new bin when only this one fits ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base hesitation: prefer reusing open bins by default.
        score += 6.0;
        // Early in the stream, opening bins is cheap and builds diversity.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If open bins are fragmented (low mean residual relative to item),
        // a fresh bin is attractive.
        if mean_residual < item_size as f64 {
            score -= 9.0;
        }
        // Many open bins with poor fits -> new bin helps spread load.
        if fitting_bins_count == 0 {
            score -= 5.0;
        }
    }

    // --- Mild global pressure: many open bins -> prefer consolidation ---
    score += (open_bins_count as f64) * 0.15;

    // Small nudge toward filling bins with larger residuals less eagerly
    // when mean residual is already low (avoid hoarding empty space).
    if (post_residual as f64) > mean_residual {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (size 1..10
    // region) are pure waste; penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leaves a gap just below the next item: potential dead space.
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; discourage opening
    // it when a decent fit exists, encourage it when open bins are congested.
    if bin_residual == bin_capacity {
        // Base penalty so we only open when necessary.
        score += 15.0;
        // Pressure from number of open bins: with many open bins, prefer filling them.
        score += open_bins_count as f64 * 3.0;
        // If no open bin fits well (this is the only "fitting" candidate being empty),
        // relieve the penalty.
        if fitting_bins_count == 1 {
            score -= 45.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Filling existing bins slightly reduces open-bin pressure; reward tight fills.
        let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * tightness;
        // Mild penalty proportional to how much worse this bin's residual is vs mean.
        if (post_residual as f64) > mean_residual {
            score += 0.05 * (post_residual as f64 - mean_residual);
        }
    }

    // Prefer using bins with smaller residual first (best-fit core), scaled.
    score += 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), but not exactly zero-ish
    // dead space unless it's a perfect closure.
    if post_residual == 0 {
        // Perfect fit: bin closed, ideal outcome.
        score -= 500.0;
    }

    // 2-step lookahead: strongly reward bins where the next item also fits
    // the post_residual (chained placement).
    let next_fits = next_item_size > 0 && next_item_size <= post_residual;
    if next_fits {
        // Reward proportional to how snugly the next item fits the remainder.
        let slack_after_next = post_residual as f64 - next_item_size as f64;
        score -= 120.0 - slack_after_next * 0.8;
    } else if next_item_size > 0 {
        // Penalize leaving a remainder too small for the next item:
        // it becomes dead space unless the bin is nearly closed.
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += (next_item_size as f64 - dead) * 1.5;
        }
    }

    // Relative-to-mean coupling: a bin with residual far below the mean is
    // already "cramped"; filling it tightly is good, but leaving it with a
    // large remainder wastes its scarce capacity.
    let post_f = post_residual as f64;
    let mean_gap = post_f - mean_residual;
    score += mean_gap * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current item is large relative to capacity and no open bin offers a
    // decent fit. Penalize the empty-bin candidate mildly so it is chosen
    // only when genuinely better.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if the item is huge, starting fresh is reasonable.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 90.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer closing
    // bins tightly rather than spreading items across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.2;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Bonus if post_residual exactly matches next item (chained perfect fit).
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred unless they're bad.
        score += 20.0;
        // If few bins fit the item, opening a new bin becomes more attractive.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Late in the stream, prefer closing out open bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If open bins have large mean residual, prefer using them.
        score += (mean_residual / bin_capacity as f64) * 25.0;
    }

    // Mild preference for bins below mean residual (balance load across bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight penalty for too many open bins (encourage consolidation early).
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64 - 4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: normalized post-residual polynomial
    let x = pr / cap; // in [0,1]
    score += 30.0 * x * x - 20.0 * x * x * x;

    // Tight fits rewarded more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 40.0 * progress);

    // Penalize dead space relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - progress);
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.05 * (open_bins_count as f64) * progress;

    // New-bin candidate: penalize opening a new bin unless stream is early
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i32; // 0..7 harmonic band

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward post_residuals that are "harmonic" — divisible by common item sizes.
        let mut harmony = 0.0;
        for m in [5u32, 10, 20, 25, 50].iter() {
            if post_residual % m == 0 && post_residual > 0 {
                harmony += 6.0;
            }
        }
        score -= harmony;

        // Penalize awkward bands: tiny slivers (<10) are dead space.
        if post_residual < 10 {
            score += 25.0;
        }
        // Band-based coupling: mid-range residuals are most reusable.
        match class {
            0 => score -= 8.0,          // <=12.5% : near-full bin, good
            1 => score -= 4.0,
            2 => score -= 1.0,
            3 => score += 3.0,
            4 => score += 5.0,
            5 => score += 7.0,
            6 => score += 6.0,
            _ => score += 2.0,
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // reward proportional closeness of fit for next item
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 { score -= 18.0; }
            else if gap <= 25.0 { score -= 8.0; }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening fresh is only good for large items
    // relative to the best available residual, or early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize opening new bins normally...
        score += 40.0;
        // ...unless item is large and mean residual is fragmented.
        if item_frac > 0.6 && mean_residual < item_size as f64 * 0.9 {
            score -= 55.0;
        }
        if progress < 0.05 && open_bins_count == 0 {
            score -= 100.0;
        }
        // Prefer new bin if it would leave a harmonic residual (item divides capacity)
        if bin_capacity % item_size == 0 {
            score -= 20.0;
        }
    }

    // Mild congestion penalty: many open bins with high mean residual suggests
    // we should consolidate, not spread.
    if open_bins_count > 4 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-perfect fit: dead space below smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score -= 60.0;
    }

    // 2-step lookahead: strongly reward bins whose residual exactly hosts next item,
    // or at least fits it snugly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // residual too small for next item: penalize proportional to waste
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the fleet average.
    score += 0.7 * (post_residual as f64 - mean_residual);

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when it enables a great 2-step chain.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 120.0;
        } else {
            score += 50.0;
        }
    }

    // Late in the stream: consolidate harder, discourage proliferation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Dead-space penalty: residuals too small to ever fit typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next < 10 {
            score -= 30.0; // perfect chain placement
        } else {
            score -= 10.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This placement strands space the next item could have used elsewhere.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * (post_residual as f64);
    }

    // New-bin candidate handling: an empty bin is attractive only when the item
    // is large (poor fit elsewhere) or when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).powi(2)
        } else {
            1.0
        };
        // Penalize opening a new bin generally, but discount when item is big
        // or existing bins are too fragmented to hold future items.
        score += 20.0
            - 0.3 * item_size as f64
            - 15.0 * fragmentation
            - 10.0 * (1.0 - progress);
    } else {
        // Mild preference for filling bins that are already well-used.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
        // Early in the stream, slightly prefer consolidating into fewer bins.
        if open_bins_count > 4 {
            score += 2.0 * (open_bins_count as f64).ln();
        }
    }

    // Small time-horizon modulation: late in the stream, prioritize exact fills.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic waste penalty on post-residual (dead space grows super-linearly)
    let mut score = norm_post * (1.0 + norm_post * norm_post * 2.5);

    // Smooth coupling: waste matters less late in the stream (commit to open bins)
    let late_relief = 1.0 - 0.6 * progress * progress;
    score *= late_relief;

    // Reward tight fits: interaction between item size and post-residual
    score -= 0.35 * norm_item * (1.0 - norm_post) * (1.0 - norm_post);

    // Penalize bins whose residual deviates from the mean (keeps residuals homogeneous)
    let dev = (pr - mean_residual) / cap;
    score += 0.25 * dev * dev;

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else {
        // More competing bins -> mild penalty for spreading items too thin
        score += 0.05 * (fitting_bins_count as f64).sqrt();
    }

    // Lookahead: if next item fits exactly in post-residual, big reward
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        score += 0.8 * diff * diff - 0.6 * (1.0 - diff);
    }

    // Mild pressure against keeping many open bins early
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: empty bin gets a moderate default cost, overcome only
    // when open-bin scores are poor (their penalties above)
    if bin_residual == bin_capacity {
        score += 0.9;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal, strongly reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic classes of post_residual: classify dead space into buckets
    // by integer division thresholds on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Class boundaries: 0, <=10, <=25, <=50, >50
    if post_residual > 0 && post_residual <= 10 {
        score -= 40.0; // near-perfect: tiny dead space, good
    } else if post_residual <= 25 {
        score -= 10.0;
    } else if post_residual <= 50 {
        score += 15.0;
    } else {
        score += 35.0; // large leftover wastes the bin
    }

    // Modulo arithmetic: items that exactly divide residual classes.
    // Reward when next item fits the post residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic bonus scaled by how tightly next item fits.
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / cap);
        // Extra bonus if next item exactly fills the bin after this one.
        if next_item_size == post_residual {
            score -= 60.0;
        }
    } else if next_item_size > post_residual {
        // Next item can't use this leftover; penalize proportional to leftover size.
        score += 0.25 * pr;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless post residual is huge).
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate (empty bin): penalize unless current bin is very tight
    // or leftover would be badly fragmented.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if mean residual across open
        // bins is small (open bins nearly full) or many bins exist.
        let pressure = mean_residual / cap;
        score = cap as f64; // base cost of a fresh bin
        score += 30.0 * pressure; // more open residual -> less attractive
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If item is small relative to capacity, fresh bin is fine.
        if (item_size as f64) > 0.7 * cap {
            score -= 20.0;
        }
    }

    // Progression coupling: late in stream, prefer filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - pr / cap);

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Harmonic modulo bonus: residual that is a multiple of common item classes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual below the minimum item size (1) is impossible, but gaps that
    // cannot fit a "typical" next item are dead space. Treat gaps below a
    // usable threshold as quadratic dead weight.
    let dead_threshold: f64 = 20.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * (dead_threshold - pr) * 0.5;
    }

    // Perfect fit bonus: strongly reward filling a bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if pr >= 1.0 && (pr as u32) >= next_item_size && next_item_size > 0 {
        // Reward leaving room that exactly accommodates the lookahead item.
        if (pr as u32) == next_item_size {
            score -= 200.0;
        } else {
            score -= 30.0;
        }
    }

    // Open-bins pressure: penalize spreading across many bins slightly,
    // encouraging consolidation into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e. tighter bins get priority to be filled).
    score += (pr - mean_residual) * 0.8;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline cost so it is
    // chosen only when existing bins would create dead space.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Early in the stream, opening bins is cheaper; later, avoid it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 60.0;
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size > bin_capacity / 2 {
            score -= 40.0;
        }
    }

    // Waste ratio term: fraction of the bin left empty after placement,
    // weighted more strongly as it approaches unusability.
    let waste_ratio = pr / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead fit: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward: next item fits tightly (small gap)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize residuals too small for typical future items (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Prefer bins below mean residual (consume the emptiest useful space)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Slight preference for opening new bins late in stream when current bins are tight
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral baseline with mild late-stream penalty
        score += 10.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            0.0
        } else {
            (post_residual as f64).powf(1.35)
        };
        score += 0.05 * dead;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot follow; penalize proportionally to how much space is stranded.
        score += 8.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.6 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Relative to mean residual: bins with more-than-average space are better hosts.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin unless current residual is badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        score += 30.0 - 0.2 * fragmentation - 10.0 * (1.0 - progress);
        // If nothing open can fit, opening is necessary: soften the penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linear scaling.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = pr / cap; // normalized post residual in [0,1]
    let coupling = x * x * (1.0 - progress) + x * x * x * progress;
    score += 40.0 * coupling;

    // Reward near-perfect fits (post_residual close to zero) increasingly over time.
    let tightness = 1.0 - x;
    score -= 15.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let waste = pr - nxt;
            score -= 20.0 * (1.0 - waste / cap);
        } else {
            // Next item won't fit here: penalize leaving a large unusable gap.
            score += 10.0 * x;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild penalty when this bin's residual is far above the mean (fragmentation).
    score += 0.1 * (pr - mean_residual).abs();

    // Slight preference for consolidating into fewer bins as stream matures.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: reward residuals in useful "fillable" classes.
    // Class A: post_residual == 0 (perfect closure) -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Class B: post_residual small enough that small items (1..=12) can fill it later.
    let small_item_ceiling = 12u32;
    if post_residual > 0 && post_residual <= small_item_ceiling {
        score -= 25.0 - (post_residual as f64);
    }
    // Class C: dead zone — residual in (12, 30] is hard to fill; penalize via modulo buckets.
    if post_residual > small_item_ceiling && post_residual <= 30 {
        score += 15.0 + ((post_residual % 7) as f64);
    }
    // Class D: mid residuals (31..60): moderately useful, graded by quarter-capacity fraction.
    if post_residual > 30 && post_residual < 60 {
        score += (post_residual as f64) * 0.35;
    }

    // Integer-division thresholds: residual >= next_item_size means lookahead item fits.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // lookahead fits: reward proportionally, stronger if it would nearly close the bin
            score -= 12.0 + (nxt / cap) * 20.0;
            if post_residual == next_item_size {
                score -= 40.0; // lookahead closes bin exactly: excellent
            }
        } else {
            // lookahead cannot use this residual: penalize dead-space risk
            score += 8.0 + (nxt - post as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 55.0;
        // soften when many items remain and few open bins (future capacity useful)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if open_bins_count <= 2 && progress < 0.5 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from the mean.
    let dev = (bin_residual as f64) - mean_residual;
    score -= dev * 0.10;

    // Mild tie-break: tighter fit (smaller wasted fraction) preferred.
    score += (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are waste.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 50.0; // tiny unusable gap is nearly as bad as a full bin
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fit: fully consumed bin
    }

    // Reward tight fits: fraction of residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is excellent.
    score += 0.8 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Deviation from mean residual: prefer bins whose residual is close to item
    // size (tight packing) rather than outliers.
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward keeping this bin.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    }
    // If next item would leave this bin with an unusable gap anyway, slightly penalize.
    if next_item_size > post_residual && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 3.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the empty-bin candidate mildly; strong fits
    // in open bins will beat it, but poor fits (large post_residual, no lookahead
    // benefit) will lose to it.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, opening new bins is less useful; make empty bins
        // slightly more attractive early when open bins are few.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress) * (1.0 / (1.0 + open_bins_count as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post-residual, this placement is a chained perfect fit.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item can still fit afterwards: mildly reward tight-but-viable bins.
        score -= (next_item_size as f64 / 100.0) * 10.0;
    } else if next_item_size > 0 {
        // Next item will NOT fit here: penalize wasted residual that is
        // smaller than the next item (dead space).
        let dead = post_residual as f64;
        score += dead * 0.3;
        if dead < 10.0 {
            score += 5.0; // tiny unusable slivers
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is already below
    // average (denser bins), penalize bins above mean residual.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins
    // would leave bad fits. Make the empty bin slightly costly by default.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If nothing else fits well (no open-bin competition), allow opening.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early in the stream, allow more aggressive bin opening to build
    // structure; late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    // Mild penalty for leaving residual in the awkward 1..=9 dead zone.
    if post_residual >= 1 && post_residual <= 9 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: square the post-residual so near-perfect fits win strongly.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item fills the remainder almost exactly.
        let chain_gap = post_residual - next_item_size;
        score -= (bin_capacity as f64 - chain_gap as f64) / (bin_capacity as f64) * 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins already below mean residual (consolidate emptiness into few bins).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Penalize opening new bins as the stream matures; early phase allows exploration.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // Opening a new bin is justified if it would create an exact slot for the next item.
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64) == next_item_size as i64 {
            score -= 45.0;
        }
    }

    // Mild reward for filling bins past half capacity.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.5 { score -= 5.0 * fill; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: minimize post residual, with non-linear sharpening so very tight fits are strongly favored.
    let mut score = post + 12.0 * (post / cap).powi(3);

    // Smooth polynomial coupling of tightness with stream progress:
    // early on, prefer filling bins aggressively; late, tolerate looser fits slightly.
    let tightness = 1.0 - post / cap;
    score -= 10.0 * tightness * (1.0 + 2.0 * progress * (1.0 - progress) * 4.0);

    // Penalize post residual relative to mean residual: creating below-average slack is bad.
    score += 0.15 * (post - mean_residual).max(0.0);
    score -= 0.05 * (mean_residual - post).max(0.0);

    // Reward last-chance placements (only one fitting bin) with smooth urgency.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * (1.0 - post / cap);
    }

    // Lookahead: if next item fits into post_residual, bonus (smooth quadratic in fit quality).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let slack = post - next_item_size as f64;
        score -= 6.0 * (1.0 - slack / cap).powi(2);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by how far off it is.
        let gap = (next_item_size as f64 - post) / cap;
        score += 4.0 * gap * gap;
    }

    // Mild penalty for proliferating bins early in the stream.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate adjustment: empty bin has post = cap - item; penalize unless the item
    // is large (small post), via a smooth function of post already handled above; add a
    // fixed opening cost so new bins are only chosen when fit elsewhere is poor.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * post;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via squared dead-space penalty
    let pr = post_residual as f64;
    score += 0.6 * (pr * pr) / bin_capacity as f64;

    // Harmonic classes of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = (post_residual / quarter) as f64;
    score += class * 8.0;

    // Perfect-fit harmonic bonus: post_residual divisible by small integers
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 5 == 0 { score -= 1.5; }
    } else {
        score -= 30.0; // exact fill
    }

    // Lookahead coupling: favor residual classes matching next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score += diff as f64 * 0.35;
        if next_item_size <= post_residual {
            score -= 3.0; // chain placement possible
        }
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless item is large (poor fit elsewhere)
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 40.0 * (1.0 - fill_ratio);
        if fill_ratio > 0.7 { score -= 25.0; }
        if fitting_bins_count == 0 { score -= 60.0; }
    }

    // Late-stream consolidation: fewer open bins preferred
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 0.05;

    // Residual fragmentation penalty relative to mean
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.2;
    } else {
        score -= (mean_residual - pr) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: prefer compacting when many bins are open.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great pair.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 45.0;
        }
    }

    // Lookahead: favor leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Late-stream compaction pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    // Perfect match with lookahead item: strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff;
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // next item fits exactly into remaining space chain
        if post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 15.0;
        }
    }
    // Penalize tiny unusable residuals (dead space) relative to item range
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Favor bins tighter than average residual (good packing)
    score -= 0.3 * (mean_residual - post_residual as f64);
    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Penalize opening a new bin when other bins fit reasonably
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64);
        }
    }
    // Late in stream, prefer consolidating into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize dead space relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 50.0;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0;
            // bonus scaled by how well next item fills the remainder
            let nxt_fill = post_residual as f64 - next_item_size as f64;
            score -= 30.0 * (1.0 - nxt_fill / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large leftover gaps
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Many fitting bins: mild penalty for spreading too thin
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global residual state: if mean residual is high, prefer compacting full bins
    let mean_r = mean_residual / bin_capacity as f64;
    score += 40.0 * (post_residual as f64 / bin_capacity as f64 - mean_r).max(0.0);
    score -= 20.0 * mean_r;

    // Time horizon: early in stream, be more conservative about leaving gaps;
    // late in stream, prefer closing bins out
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 30.0;
    score -= progress * 15.0;

    // New-bin candidate handling: only open a new bin when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 250.0;
        // cheaper to open new bin if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else if post_residual > bin_capacity - item_size {
            // new bin leaves maximal usable space; discount when item is large
            score -= (item_size as f64 / bin_capacity as f64) * 120.0;
        }
        // discourage new bins when open bins have plenty of room
        if mean_r > 0.5 && fitting_bins_count > 0 {
            score += 80.0;
        }
        // late in stream, prefer reusing existing bins
        score += progress * 60.0;
    }

    // Penalize bins whose residual after placement is awkward (between 11 and 30)
    if post_residual > 10 && post_residual < 30 {
        score += 25.0;
    }

    // Open bins count pressure: many open bins favor consolidation
    if open_bins_count > 5 {
        score -= 8.0 * open_bins_count.min(20) as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, with non-linear penalty on very small residuals
    let mut score = pr as f64;
    score += 30.0 * norm_pr * norm_pr * (1.0 - progress);

    // Smooth coupling: prefer tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Dead-space term: residual too small for typical future items
    let mean_item = if total_items > 0 { 0.5 * cap } else { 50.0 };
    let dead = ((pr as f64 - 10.0) / cap).max(0.0);
    score += 15.0 * dead * dead * (1.0 - progress);

    // Last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // New-bin candidate: mildly discouraged unless current bin would leave bad waste
    if bin_residual == bin_capacity {
        let bad_fit = (pr as f64 / cap - 0.5).abs();
        score += 8.0 - 6.0 * bad_fit - 5.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            score -= 12.0 * (1.0 - (pr as f64 - nxt) / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 6.0 * (nxt - pr as f64) / cap;
        }
    }

    // Spread pressure: many open bins -> consolidate
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    // Mean residual alignment: prefer bins near the mean residual
    score += 3.0 * ((pr as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space below 10 is unusable waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit reward: post_residual is an exact divisor-class of capacity.
    if post_residual == 0 {
        score -= 40.0;
    } else if bin_capacity % post_residual == 0 && post_residual <= 50 {
        score -= 12.0; // residual can be tiled by future harmonic items
    }

    // Modulo-class coupling: residual congruent to common item sizes (10..80 in steps of 5)
    let r = post_residual % 10;
    if r == 0 {
        score -= 6.0;
    } else if r >= 5 {
        score += 3.0;
    }

    // Integer-division threshold: residual large enough for another mid-size item
    if post_residual / 10 >= 5 {
        score -= 4.0;
    }

    // Lookahead: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 5.0; // next item won't fit here; keep this bin's residual small anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual > 60 {
            score -= 25.0; // large item deserves a fresh bin
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 18.0; // open bins are nearly full; fresh bin is fine
        }
    }

    // Progression-aware tightening: late in stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * 0.15 * progress;

    // Coupling with mean residual: prefer bins deviating favorably from mean
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit a future item
    // (min item size 1, but practical dead zone below ~10) are heavily penalized.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits (post_residual near zero) with a superlinear bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= tightness * tightness * 6.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual can't host next item: mild penalty scaled by gap size.
        score += ((next_item_size - post_residual) as f64) * 0.15;
    }

    // Open-bin pressure: discourage scattering across many bins unless the fit is good.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: a fresh empty bin is attractive only when this
    // placement would leave a large awkward residual in an existing bin, or when
    // the item fits poorly everywhere. Give the fresh bin a moderate base score
    // so it wins only against bad fits.
    if bin_residual == bin_capacity {
        score += 4.0; // slight default cost to prefer existing bins
        if post_residual as f64 <= mean_residual {
            score -= 10.0; // fresh bin leaves less residual than average -> good
        }
        if fitting_bins_count == 0 {
            score -= 15.0; // no open bin truly fits well
        }
    } else {
        // Penalize placing into an existing bin when the resulting residual is
        // much larger than the mean residual (wasteful fit).
        if (post_residual as f64) > mean_residual + 15.0 {
            score += ((post_residual as f64) - mean_residual) * 0.5;
        }
    }

    // Mild stream-position adaptation: later in the stream, consolidation matters
    // more, so tighten the dead-space penalty further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: if the next item exactly fills the post-residual,
    // strongly reward this bin (chain two items into one bin).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 1000.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits after this one: reward proportional to how snugly
        // it nests into the remaining space.
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow: penalize if we leave a gap that the next
        // item just barely misses (dead space likely).
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 20.0 {
            score += 40.0 * (1.0 - miss / 20.0);
        }
    }

    // Tight fits are good: reward small post residuals.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Penalize leaving residuals that no plausible item (1..=100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill, excellent
    } else if post_residual > 50 {
        score += 10.0; // half-empty bin wasted on a small item
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only prefer it when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; a fresh bin has residual 100.
        score += 55.0;
        // If the next item can chain into a fresh bin too, soften the penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 25.0;
        }
    }

    // Contextual coupling: when open bins are on average roomy (mean_residual
    // high), discourage stuffing a small item into a tight bin and prefer
    // spreading load; when mean residual is low, favor tight fills anywhere.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.3 * mean_gap;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins that already have contents (avoid bin churn).
    if bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize creating dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // next item won't fit here
        }
        // If next item fits perfectly, big bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many options, prefer the tightest; small extra shaping.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: as the stream nears its end, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    // Open-bin pressure: many open bins -> discourage new bins, encourage filling existing.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (10.0 + 2.0 * open_bins_count as f64);
    score -= (1.0 - new_bin) * (open_bins_count as f64 * 0.5);

    // Mean residual coupling: if this bin's residual is far below mean, it's already
    // "fragmented"; prefer packing into bins with residual near/below mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Mild preference for larger items in emptier bins.
    score += 0.1 * (item_size as f64 / 100.0) * (post_residual as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: penalize leftover space, with mild non-linear growth (dead space quadratic cost)
    let mut score = pr + 0.015 * pr * pr / cap;

    // Reward tight fits: smooth Gaussian-like bonus centered at near-zero residual
    let tightness = (-pr / (0.35 * cap)).exp();
    score -= 12.0 * tightness;

    // Lookahead coupling: reward if next item fits into post_residual (smooth sigmoid)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = 1.0 / (1.0 + (-(pr - nx) / (0.25 * cap)).exp());
        score -= 8.0 * fits_next * (nx / cap);
        // Penalize if post_residual is just barely too small for next item (wasted gap)
        let gap = pr - nx;
        if gap < 0.0 && gap > -20.0 {
            score += 4.0 * (1.0 + gap / 20.0);
        }
    }

    // Stream progress: later in stream, prefer filling existing bins more aggressively
    score -= 6.0 * progress * fit_ratio;
    score += 3.0 * progress * (pr / cap);

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Many open bins: penalize spreading, favor consolidation (smooth in open_bins_count)
    let spread = 1.0 - 1.0 / (1.0 + open_bins_count as f64);
    score += 4.0 * spread * (pr / cap);

    // Mean residual coupling: if this bin's residual is far below mean, slight bonus (diversity of fill)
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev - 1.5 * dev;

    // New-bin candidate: keep neutral-ish but slightly penalized so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (capacity fractions) ---
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // fraction of capacity left after placement

    // Reward placements leaving residuals in "useful" harmonic bands:
    // residuals near 0 (perfect fit), near 1/2, near 1/3, near 1/4 are
    // reusable by typical item sizes via integer-division classes.
    let bands: [f64; 4] = [0.0, 1.0 / 2.0, 1.0 / 3.0, 1.0 / 4.0];
    let mut band_bonus = 0.0f64;
    for (k, b) in bands.iter().enumerate() {
        let dist = (frac - b).abs();
        let width = 0.06 + 0.02 * k as f64;
        if dist < width {
            band_bonus += (width - dist) / width * (4.0 - k as f64) * 3.0;
        }
    }
    score -= band_bonus;

    // --- Integer division thresholds: which future item classes fit exactly ---
    // A residual r can exactly host items of size C/j (j = 1..4) or multiples.
    let r = post_residual;
    for j in 1..=4u32 {
        let class = bin_capacity / j;
        if r >= class && r < class + 4 {
            score -= 5.0; // residual matches a harmonic class almost exactly
        }
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 && next_item_size <= r {
        // next item fits here: strong reward, scaled by how snugly
        let snug = (r - next_item_size as u32) as f64;
        score -= 8.0 - 0.15 * snug;
        // exact harmonic match with next item: extra reward
        if r == next_item_size {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize large dead space
        score += 0.05 * (pr - (next_item_size as f64)).max(0.0);
    }

    // --- Dead space penalty (quadratic beyond small residuals) ---
    if pr > 0 {
        score += 0.01 * pr * pr / c;
    }

    // --- Last-chance bin: strongly prefer using it over opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing bins fit poorly.
        // Base cost of a fresh bin grows with how many bins already fit.
        let mut nb = 18.0 + 6.0 * fitting_bins_count as f64;
        // If the item fits an open bin leaving a harmonic residual, never open.
        for j in 1..=4u32 {
            let class = bin_capacity / j;
            if post_residual <= class {
                nb += 10.0;
            }
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += 8.0 * progress;
        // If mean residual across open bins is large, avoid new bins.
        if mean_residual > item_size as f64 {
            nb += 6.0;
        }
        score += nb;
    }

    // --- Mild pressure against bin sprawl ---
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Gaps below the smallest item size (1..100 unknown, assume min ~10) are unusable.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 25.0;
    }

    // Reward tight fits (waste fraction penalty).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 8.0; // next item won't fit here; residual likely dead
        }
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score += 0.5 * open_bins_count as f64;
    }

    // Mild normalization toward mean residual state.
    score += 0.1 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is best.
    score += 0.5 * (post_residual as f64 / cap);

    // 2-step lookahead: if next item exactly matches post_residual, big reward.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills remainder
            let fill = nr / (post_residual as f64);
            score -= 10.0 * fill;
        } else {
            // next item won't fit here: penalize leaving a residual that's too small
            let waste = (post_residual as f64) / nr;
            score += 5.0 * (1.0 - waste.min(1.0));
        }
        // chain: post_residual - next leaves room for a third item
        if next_item_size < post_residual {
            let rem2 = post_residual as f64 - nr;
            if rem2 >= 10.0 {
                score -= 2.0 * (rem2 / cap);
            } else if rem2 > 0.0 {
                score += 3.0 * (1.0 - rem2 / 10.0); // tiny dead space penalty
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let tightness = if next_item_size > 0 {
            (post_residual as f64 / next_item_size.max(1) as f64).min(1.0)
        } else { 0.0 };
        let pressure = if fitting_bins_count == 0 { 25.0 } else { 0.0 };
        score = score.max(0.0) + 20.0 - pressure - 10.0 * tightness;
        // late in stream, prefer closing out open bins rather than opening new ones
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // leftover can host the next item: reward proportionally
            score -= 0.15 * (post_residual as f64 - next_item_size as f64).min(20.0);
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: only attractive when current fit is very poor or stream is early
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64 / bin_capacity as f64;
        let poor_fit = fit_quality > 0.6;
        if poor_fit && progress < 0.8 {
            score -= 15.0 * (fit_quality - 0.6) * 10.0 * (1.0 - progress);
        } else {
            score += 40.0 + 30.0 * (1.0 - progress);
        }
    }

    // Mild penalty when many bins are open with high mean residual (fragmentation pressure)
    if bin_residual < bin_capacity {
        score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / bin_capacity as f64);
    }

    // Prefer bins whose residual is closest to the item (best-fit flavor)
    score += 0.2 * ((bin_residual - item_size) as f64 / bin_capacity as f64).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: reward small post-residual, but with a smooth non-linear coupling
    // so that tiny residuals are disproportionately penalized (dead space).
    let post_norm = post / cap;
    let mut score = post * (1.0 + 0.35 * post_norm * post_norm);

    // Smooth waste penalty: quadratic in post_residual relative to capacity.
    score += 0.5 * post_norm * post * 0.01;

    // Stream-progress coupling: later in the stream, tight fits matter more.
    // Interact progress with post_residual via a smooth cubic progress term.
    let prog3 = progress * progress * progress;
    score += 6.0 * prog3 * post_norm * cap * 0.1;

    // Lookahead coupling: if the next item fits in the post-residual, reward;
    // smooth sigmoid-like transition rather than hard threshold.
    if next > 0.0 {
        let fits_margin = (post - next) / cap;
        let smooth = fits_margin / (1.0 + (-3.0 * fits_margin).exp());
        score -= 4.0 * smooth;
        // Penalize leaving just-enough space that next item barely misses.
        let miss = (next - post).max(0.0) / cap;
        score += 3.0 * miss * miss * cap * 0.05;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * (1.0 - post_norm);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation risk).
    let open_norm = open_bins_count as f64;
    score += 0.05 * open_norm * post_norm;

    // Mean-residual deviation: prefer bins whose residual is below the mean
    // (tighter bins get used first), smooth quadratic coupling.
    let dev = (post - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate handling: empty bin gets a smooth adaptive barrier that
    // shrinks as the stream progresses or when current bin fits poorly.
    if bin_residual == bin_capacity {
        let barrier = 10.0 * (1.0 - progress) + 0.4 * item;
        score += barrier;
        // Allow new bin if existing fits are very poor (large post residual).
        score -= 0.15 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into residue classes mod 10
    let post_class = post_residual % 10;
    // Dead-space classes: leftovers like 1..9 are hard to fill later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    } else if post_class == 0 {
        score -= 8.0; // perfectly harmonic leftover (multiple of 10) is reusable
    }

    // Integer-division thresholds on post_residual
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 12.0; // bin remains highly usable
    } else if post_residual >= quarter {
        score -= 4.0;
    } else if post_residual > 0 {
        score += 6.0; // low residual, near-closed bin
    }

    // Perfect fit rewards
    if post_residual == 0 {
        score -= 60.0;
    }

    // Coupling with next item: if next item exactly fits the post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let leftover_after_next = post_residual - next_item_size;
            if leftover_after_next % 10 == 0 {
                score -= 15.0; // harmonic chain continues
            }
            score -= (leftover_after_next as f64).sqrt() * 2.0;
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin logic
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        score += 2.0; // plenty of alternatives, mild penalty for this bin
    }

    // New-bin candidate handling: opening fresh is only good when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins more when mean residual across open bins is still large
        score += 30.0 + mean_residual * 0.5 + progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere, must open
        }
    }

    // Prefer filling bins tighter than the average residual
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score -= 25.0; // tiny gap is fine (near-perfect fit)
    } else if post_residual < item_size.min(30) {
        score += 15.0; // small but not tiny gap is wasted space
    }

    // Reward exact-ish fits strongly
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new bin has bin_residual == bin_capacity, so post_residual is large;
    // add extra penalty scaled by open bins count for the new-bin candidate)
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 4.0;
    }

    // Mild mean-residual coupling: prefer bins deviating below mean residual
    // (tighter bins get used first, keeping roomier bins flexible)
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Slight progression bias: late in stream, be more frugal with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Stream progression: be more aggressive with lookahead matching later on.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let lookahead_scale = 1.0 + progress;

    // Perfect fit: zero waste, overwhelmingly preferred.
    if post_residual == 0 {
        return score - 10000.0;
    }

    // Mild bias against opening a brand-new bin when open bins could fit.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            // Aggressive 2-step match: current item AND next item fit here.
            // Reward heavily; tighter leftover after the chain is even better.
            let leftover_after_next = post - next;
            score -= lookahead_scale * (40.0 + 1.5 * next) - 0.3 * leftover_after_next;
        } else {
            // Dead space relative to the lookahead: penalize the unusable gap
            // so a roomier bin that can host the next item wins instead.
            score += lookahead_scale * 1.2 * (next - post);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one,
    // especially early in the stream when bin economy matters most.
    if fitting_bins_count == 1 {
        score -= 200.0 + 100.0 * (1.0 - progress);
    }

    // Relative-to-mean coupling: reward leaving this bin below the mean
    // residual (concentrate filling into already-committed bins).
    score -= 0.4 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 6.0 * (1.0 - gap * gap);
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }
    // Penalize leaving a residual that the next item cannot use if gap is awkwardly small.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins (penalize filling
    // existing bins with loose fits); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tight;

    // Many open bins with high mean residual: encourage consolidating into existing bins.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0 * (mean_residual / bin_capacity as f64);
    }

    // Penalize creating dead space relative to the mean residual of the system.
    let dead = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dead;

    // New-bin candidate adjustment: only prefer a fresh bin when no tight option exists.
    if bin_residual == bin_capacity {
        score += 18.0 - 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * norm_pr * (0.35 + 0.45 * progress + 0.25 * p2)
                 + norm_pr * p3 * 0.30
                 - norm_pr * (0.10 * p2);
    score += coupling * cap;

    // Tight fits are rewarded smoothly (quadratic dead-space penalty)
    let dead = (norm_pr * cap / (cap * cap)) * pr;
    score += dead * 0.02;

    // Lookahead: bonus if post_residual fits next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= (1.0 - slack * slack) * 6.0 * (1.0 - progress * 0.5);
        } else {
            score += (nx - pr) / cap * 4.0;
        }
    }

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + p2);
    }

    // Mild pressure toward consolidation when many bins are open
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += norm_pr * open_pressure * 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // coarse buckets via integer division thresholds.
    let class = post_residual / 10; // 0..=10 harmonic class
    // Dead space penalty grows superlinearly for small (unusable) residuals.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo arithmetic coupling: residuals that are multiples of common
    // item-size classes are more likely reusable.
    if post_residual > 0 {
        let r = post_residual;
        if r % 20 == 0 {
            score -= 6.0;
        } else if r % 10 == 0 {
            score -= 3.0;
        } else if r % 5 == 0 {
            score -= 1.5;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly prefer this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits: leftover after next placement (harmonic class again)
            let post2 = post_residual - next_item_size;
            score -= 8.0 - (post2 as f64) * 0.15;
        } else {
            // Next item will NOT fit here: mild penalty for tight bins
            score += 3.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitter.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins with good fits; only open a new bin when
        // the item is large relative to mean residual (poor fits elsewhere)
        // or late in the stream when many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 0.6;
        if poor_fit_elsewhere || open_bins_count == 0 {
            score -= 10.0; // opening a new bin is fine
        } else {
            score += 25.0 + 15.0 * (1.0 - progress); // discourage new bins early
        }
        // Large items pack cleanly into fresh bins
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Prefer bins with residual close to item size (tight packing) using
    // a ratio term.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Mild preference for using bins with larger residuals overall
    // (keeps small residuals from multiplying).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Harmonic class bonus: bins whose class matches item's class-of-10
    let _ = class;
    if post_residual >= 10 && (post_residual / 10) == (item_size / 10) {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits in general (post_residual small relative to capacity).
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin, unless it enables a great
    // future fit (lookahead) or the current placement would leave dead space.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // new bin will also host the next item well
        }
    } else {
        // Using an existing bin keeps open_bins_count low: reward.
        score -= 5.0;
        // If the next item exactly fills the remaining residual, bonus.
        if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
            score -= 30.0;
        }
        // Penalize if the next item cannot use the leftover gap (dead space chain).
        if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Mild pressure: when many bins are open, prefer consolidating into them.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late in the stream, avoid leaving any residual at all.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not zero-waste obsession.
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post_residual as f64 - nx).abs();
        // Perfect match for the next item is heavily rewarded.
        if post_residual as f64 >= nx {
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize dead space.
            score += 10.0 + diff * 0.5;
        }
        // Exact match bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 5.0;
    }

    // Coupling with mean residual: bins far from the mean residual are less flexible.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        if post_residual as f64 <= 20.0 {
            score -= 15.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if next item is huge and post_residual (full capacity) can host it, ease penalty.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 25.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for fuller bins among equals.
    score -= 0.05 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residuals that are too small to be useful later.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste — mild reward scaled by fill
            score -= 8.0 * (nx / (post_residual as f64));
        } else {
            // next item won't fit here: penalize more if this bin was a good general host
            score += 5.0 * (nx / cap);
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_pressure = (open_bins_count as f64) / 8.0;
    score -= 4.0 * open_pressure * (1.0 - (post_residual as f64) / cap);

    // Deviation from mean residual: prefer bins whose residual is near/below the mean
    // (concentrate waste in few bins rather than spreading it).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.08 * dev;

    // Time horizon: early in the stream, be pickier (keep flexibility); later, just fill.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 6.0 * (post_residual as f64) / cap;
    score -= t * 10.0 * tightness;

    // New-bin candidate: only attractive when current fit is terrible or item is huge
    // and would leave an awkward residual in an existing bin.
    if bin_residual == bin_capacity {
        let awkward = (post_residual as f64) / cap;
        let bad_fit = if bin_residual >= item_size { (bin_residual - item_size) as f64 / cap } else { 1.0 };
        // Base penalty so new bins aren't opened frivolously.
        score += 45.0;
        // Discount the penalty when the item would leave a large awkward residual anyway.
        score -= 40.0 * awkward * bad_fit;
        // Late in the stream, avoid opening new bins even more.
        score += t * 20.0;
        // If only one bin fits the item, opening a new bin is wasteful.
        if fitting_bins_count <= 1 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: penalize wasted space, with non-linear (quadratic/cubic) shaping
    let mut score = pr - 0.9 * pr_norm * (cap - pr_norm * cap);

    // Smooth progress coupling: later in stream, prefer tighter fits more strongly
    score += 20.0 * progress * pr_norm * pr_norm * cap;

    // Interaction: post_residual vs mean residual (favor bins below mean residual -> tight bins)
    score += 3.0 * (mean_residual - pr) * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item can fit into post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if pr >= next {
            score -= 6.0 * (1.0 - (next / cap)) * (1.0 + progress);
        } else {
            score += 4.0 * (next - pr) / cap;
        }
    }

    // Mild penalty for many open bins to discourage bin sprawl
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Perfect-fit reward (smooth, non-piecewise)
    score -= 8.0 * (-pr_norm * pr_norm * 40.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic classes: post_residual divisible by common size classes is more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 10.0; }
        // Small unusable dead space penalty (nonlinear).
        if pr < 10 {
            score += (10 - pr) as f64 * 6.0;
        }
        // Integer division thresholds: reward residuals that can host medium items.
        let q = pr / 20;
        score -= q as f64 * 2.5;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score -= 30.0 - (slack as f64).min(30.0);
            if slack < 10 { score += 10.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if item is large and fits a fresh bin well, mild discount.
        if item_size >= bin_capacity * 3 / 4 { score -= 40.0; }
        // Early stream: opening bins is fine.
        if step_index as f64 / (total_items.max(1) as f64) < 0.2 { score -= 30.0; }
    }

    // Prefer filling bins tighter than the current mean residual.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Slight preference for bins with lower residual overall (tighter bins first).
    score += bin_residual as f64 * 0.1;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (<= 10) are almost unusable, penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Reward bins whose residual was large (use up big gaps first).
    score -= 0.05 * bin_residual as f64;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage consolidation.
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: if open bins are mostly empty, prefer filling them
    // (i.e. penalize the new-bin candidate more via mean residual reward on real bins).
    if bin_residual < bin_capacity {
        score -= 0.15 * mean_residual;
    }

    // New-bin candidate handling: only attractive when item barely fits nowhere well
    // (large item, small residuals elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins when a decent fitting bin exists.
        if fitting_bins_count >= 1 {
            let min_needed = item_size as f64;
            let avg_fit_gap = (mean_residual - min_needed).max(0.0);
            score += 25.0 + 0.5 * avg_fit_gap - 10.0 * (1.0 - progress);
        } else {
            score -= 20.0;
        }
        // Lookahead: if next item is huge, opening a fresh bin now preserves space.
        if next_item_size >= 70 {
            score -= 15.0;
        }
    } else {
        // Lookahead synergy: placing here is better if post residual can host next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 10.0;
            } else if post_residual > 0 && post_residual < next_item_size {
                score += 5.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional to how well next item nests in leftover space.
            score -= 30.0 * (1.0 - slack / (post_residual as f64));
        } else {
            // Next item cannot fit: penalize leaving a gap that may become dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 100.0);
        }
    }

    // Penalize residual far below mean residual (wasting a roomy bin on a tight fit).
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutral-to-slightly-high score; only chosen if fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Prefer opening a new bin late in the stream is fine; early on discourage spreading.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead * dead;

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Penalize leaving residual too small for the next item (wasted space).
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: close bins out aggressively.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty for spreading across many fitting bins; prefer tightest.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: if mean residual is high, prefer filling existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > item_size as f64 {
        score -= 8.0 * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: late in stream, consolidate into open bins rather than opening new ones.
    score -= 12.0 * progress;

    // Penalize opening new bins when several bins already fit the item.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // new bin is fine if next item also fits well here
        }
    }

    // Small stochastic-free tie-breaker favoring bins with residual close to item+next.
    let combo = item_size as f64 + next_item_size as f64;
    if combo > 0.0 && bin_residual as f64 >= combo {
        score -= 6.0 * (1.0 - (bin_residual as f64 - combo) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr_norm * (1.0 + 2.0 * progress * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (pr as u32) < next_item_size {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 8.0 * gap * gap * (0.5 + progress);
    } else if next_item_size > 0 {
        // Reward leaving space that exactly suits the next item
        let fit = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 3.0 * fit * fit * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 4.0 + 2.0 * (1.0 - pr_norm);
    }

    // Mild penalty for scattering across many open bins
    score += (open_bins_count as f64).ln() * 0.3 * pr_norm;

    // Reward tight fits (small post_residual) with smooth decay
    score -= (1.0 - pr_norm).powi(3) * 1.5;

    // New-bin candidate handling: penalize opening a new bin when item fits elsewhere
    if bin_residual == bin_capacity {
        let open_bonus = if open_bins_count > 0 && fitting_bins_count > 0 { 6.0 * (1.0 - progress) } else { 0.0 };
        score += cap * 0.5 + open_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // residue classes (multiples of common item sizes) are more valuable.
    // Class A: post_residual % 10 == 0  -> highly reusable
    // Class B: post_residual % 5 == 0   -> moderately reusable
    // Class C: otherwise -> dead space, penalize
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 25.0 + (pr as f64) * 0.6;
    } else if pr % 5 == 0 {
        score -= 10.0 + (pr as f64) * 0.3;
    } else {
        score += 15.0; // dead-space penalty
    }

    // Integer-division threshold on post_residual: leftover below half the
    // smallest plausible item is nearly worthless.
    if pr < 20 && pr > 0 {
        score += 30.0;
    } else if pr >= 20 && pr <= 50 {
        // sweet spot: can host mid-size items
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits the post_residual exactly or well,
    // reward strongly; if next item cannot ever fit it, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let next_waste = pr - next_item_size;
            if next_waste % 10 == 0 {
                score -= 40.0;
            } else {
                score -= (next_waste as f64) * 0.5;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: only fitting bin -> strong reward to avoid new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer filling bins that are already relatively full (residual close to
    // item) — measured by bin_residual relative to capacity.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Spread pressure: when many bins are open, encourage closing them out
    // (use mean_residual as reference).
    if open_bins_count > 3 {
        let dev = (mean_residual - bin_residual as f64).abs();
        score += dev * 0.15;
    }

    // New-bin candidate: empty bin. Only attractive when no open bin is a
    // good harmonic fit; penalize otherwise so open bins get used.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count <= 1 {
            score -= 50.0; // opening a bin is fine when nothing fits well
        }
        if next_item_size > 60 {
            score -= 20.0; // big lookahead item justifies fresh capacity
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (< 10) heavily; they are dead space.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead-space penalty scales with how unusable the gap is relative to typical item sizes.
    let gap_uselessness = if post_residual < item_size {
        (item_size - post_residual) as f64 / 100.0
    } else {
        0.0
    };
    score += 15.0 * gap_uselessness;

    // Pressure on number of open bins: fewer open bins -> favor reusing them.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual is below mean (tighter packing).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit post residual but could fit a fresh bin, penalize slightly.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // New-bin candidate: discourage opening a new bin unless current bin leaves a bad gap.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if no open bin fits well, allow opening: soften when fitting bins is scarce.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strong reward.
        if diff == 0.0 {
            score -= 40.0;
        } else if diff <= 5.0 {
            score -= 25.0 - 3.0 * diff;
        } else {
            // Penalize residuals that are slightly too big to fit next item well.
            score += diff * 0.35;
        }

        // If this bin cannot host the next item after placement, mild penalty
        // proportional to wasted potential, unless it's a near-perfect fill.
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: prefer tightest fit (post_residual already drives this).
        score += 0.0;
    }

    // Compare post_residual relative to mean residual: avoid leaving much more
    // space than typical, but also avoid extreme fragmentation below mean.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += (rel - 1.0).abs() * 6.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large and
    // no open bin fits well (residual stays high otherwise).
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size >= 70 && next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 45.0; // big item unlikely to pair: new bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open new bin
        }
    }

    // Reward filling bins nearly completely.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Late in the stream, tighten packing (fewer chances to consolidate).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    // Slight preference to spread load when many bins are open and mean residual is high.
    if open_bins_count > 3 && mean_residual > 40.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: square the post-residual to punish wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Reward filling a bin nearly exactly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: penalize leaving a residual that is awkward for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual > 0 {
            let gap = (post_residual as f64 - nx).abs();
            // If next item fits exactly or well into post_residual, reward.
            if (post_residual as f64) >= nx {
                score -= (1.0 - gap / bin_capacity as f64) * 10.0;
            } else {
                // Dead space the next item can't use: penalize proportionally.
                score += gap / bin_capacity as f64 * 8.0;
            }
        }
    }

    // Compare against mean residual across open bins: prefer bins tighter than average
    // (consolidate waste into few bins).
    let mean_gap = mean_residual - bin_residual as f64;
    score += mean_gap * 0.3;

    // Mild penalty for opening new bins when many bins are already open and
    // mean residual could still absorb the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 18.0;
        // Late in the stream, opening new bins is less costly (fewer future items to place).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
        // If mean residual is large, opening a new bin wastes existing capacity.
        score += (mean_residual / bin_capacity as f64) * 12.0;
    }

    // Slight preference for bins with less residual overall to drive consolidation.
    score += bin_residual as f64 * 0.02;

    // Small time-dependent scaling to keep scores comparable across the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits, but with non-linear (quartic) penalty on waste.
    let mut score = pr as f64;
    score += 40.0 * x * x * (1.0 - x) * (1.0 - x);

    // Smooth progress coupling: waste tolerance decreases as stream advances.
    let waste_penalty = pr * pr / cap;
    score += waste_penalty * (0.5 + 1.5 * progress * progress);

    // Mean-residual coupling: penalize deviating from mean residual state (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 25.0 * dev * dev * (1.0 + progress);

    // Lookahead: reward leaving room for the next item with a smooth cosine-shaped bonus.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_gap = (pr - n).abs() / cap;
        score -= 30.0 * (-20.0 * fit_gap * fit_gap).exp();
        // Exact room for next item is ideal.
        if pr >= n {
            score -= 10.0 * (1.0 - (pr - n) / cap);
        }
    } else {
        // Last item: strongly prefer filling bins as tightly as possible.
        score -= 50.0 * (1.0 - x);
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - x * x);
    }

    // Mild penalty on bin proliferation, decaying with progress.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: make it attractive only when item barely fits nowhere well.
    if bin_residual == bin_capacity {
        score += 15.0 + 35.0 * progress;
        if next_item_size > 0 {
            // Opening a fresh bin is good if the item is small enough to pair with the next one.
            let pair = item_size as f64 + next_item_size as f64;
            if pair <= cap {
                score -= 45.0 * (1.0 - pair / cap);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small usable" classes (mod 10) are preferred over awkward dead space.
    let pr = post_residual as i64;
    let class = pr % 10;
    match class {
        0 => score -= 6.0,           // perfectly divisible leftover
        1 | 2 | 3 | 4 => score -= 2.0,
        8 | 9 => score += 1.0,
        _ => {}
    }

    // Integer-division thresholds: reward residuals that can still host
    // common item sizes (multiples of 10 up to 80).
    if post_residual >= 10 { score -= 3.0; }
    if post_residual >= 20 { score -= 2.0; }
    if post_residual >= 30 { score -= 1.0; }
    if post_residual > 80 { score += 4.0; } // huge waste kept in a nearly full bin

    // Next-item lookahead: if the next item fits exactly into the post
    // residual, strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; mildly penalize tight leftovers
            if post_residual < next_item_size && post_residual < 10 {
                score += 3.0;
            }
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score = post_residual as f64 * 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Capacity fraction coupling: bins already > 60% full are attractive targets.
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * fill_frac;

    // Late in the stream, consolidation matters more: tighten selection.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Prefer bins below mean residual slightly (balance), but not for new bins.
    if bin_residual < bin_capacity {
        score += 0.05 * ((bin_residual as f64) - mean_residual);
    } else {
        // New empty bin: penalize unless the item is large relative to capacity
        // and few bins fit it (avoid fragmenting when a good fit exists).
        score += 10.0 - 6.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count > 0 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps (1..=10) are nearly unusable
    // for future items (min item size >= 1, but small gaps fragment capacity).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0; // heavy penalty for creating a dead sliver
    } else if post_residual == 0 {
        score -= 80.0; // perfect fit: strongly reward
    }

    // Reward tight fits relative to the bin: the fuller the bin becomes, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and penalize spreading; the new-bin candidate (residual == capacity) suffers here.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus pressure, softened when few bins are open.
        score += 25.0 + 40.0 * pressure;
        // Opening a new bin is attractive if the item would leave a bad gap elsewhere
        // and no other bin fits well; lookahead helps decide.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 15.0; // fresh bin can host the next item
        }
    } else {
        score -= 12.0 * pressure; // existing bins get a consolidation bonus
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean (already tight),
    // finishing it off is good; a near-empty bin among full ones is a poor choice.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.15 * (mean_residual - res);
    } else {
        score += 0.10 * (res - mean_residual);
    }

    // Lookahead: bonus if the post placement can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Late-stream tightening: as the stream progresses, be greedier about filling bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual >= next_item_size {
            // Penalize leftover that does NOT match next item (dead space after next placement).
            let after_next = post_residual - next_item_size;
            let mismatch = if after_next == 0 {
                -30.0 // perfect chain: item now, next item exactly fills bin
            } else {
                (after_next as f64) * 0.55
            };
            score += mismatch;
            // Slight bonus for tight fit now (post_residual small but still fits next).
            score -= (bin_capacity as f64 - post) * 0.05;
        } else {
            // Next item cannot follow into this bin: penalize proportional to wasted capacity.
            score += next * 0.35;
        }
    }

    // Prefer bins that are already the "last chance" (few fitting bins) to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Compare against mean residual: favor bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Early in the stream, slightly discourage opening new bins (consolidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * (1.0 - progress);
    }

    // Mild penalty for very large dead space that no item (min 1) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is the base, but amplify waste.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.4) * 0.15;
    } else {
        score -= 40.0; // perfect fit
    }

    // Penalize bins that cannot host a plausible follow-up item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.25;
        } else {
            score -= 6.0; // bin remains usable for the lookahead item
        }
        // Bonus if lookahead item fits snugly after this placement.
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 && gap < 15.0 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate logic: only attractive when the fit is bad elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // Cheaper to open a bin early when many items remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If open bins are crowded (low mean residual), a new bin is fine.
        score -= (mean_residual / 10.0).min(30.0);
        // Large items leave big residuals; opening fresh is natural.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    } else {
        // Slight preference for emptier bins among open bins.
        score -= bin_residual as f64 * 0.05;
    }

    // Mild preference for reducing bin count pressure.
    score += open_bins_count as f64 * 0.3;

    // Penalize creating dead space that nothing (10..80) can use well.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // near-perfect packing
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 3.0; // awkward small gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_pr = pr / cap;

    // Base: prefer minimal post-residual, with non-linear (quadratic) shaping
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Stream-progress coupling: as the stream progresses, dead space becomes
    // increasingly costly (fewer future chances to reuse it).
    score += 60.0 * progress * norm_pr * norm_pr;

    // Interaction of post-residual with mean residual: if this bin's leftover
    // is far below the mean, we are compacting well; reward it.
    let dev = (mean_residual - pr) / cap;
    score -= 25.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement strongly (perfect pairing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let tightness = 1.0 - ((pr - nxt) / cap).abs();
            score -= 15.0 * tightness * tightness;
        } else {
            // Next item cannot fit here; slight penalty proportional to overflow gap
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for spreading across too many open bins when a tight fit exists
    score += 0.5 * (open_bins_count as f64) * (1.0 - norm_pr);

    // New-bin candidate (bin_residual == bin_capacity): make it unattractive
    // unless the fit in open bins would be terrible (large post_residual).
    if bin_residual == bin_capacity {
        score += 45.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into decile buckets.
    let class = post_residual / 10;
    // Perfect-fit classes (post_residual near 0) are excellent; large dead space is bad.
    match class {
        0 => score -= 40.0,                    // near-perfect fill
        1 => score -= 22.0,
        2 => score -= 10.0,
        3 | 4 => score -= 2.0,                 // awkward mid-range dead space
        5 | 6 => score += 6.0,                 // half-empty: poor
        7 | 8 => score += 12.0,
        _ => score += 20.0,                    // mostly empty bin: wasteful placement
    }

    // Modulo coupling: residuals that form "nice" future fits (multiples of 10) are valuable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0);
        } else {
            // next item cannot fit here; penalize slightly more the tighter we are
            score += 3.0;
        }
    } else {
        // last item: prefer filling as much as possible
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge relative to capacity
    // or stream is early and we have few bins.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 * (1.0 - frac)      // small items in fresh bins are wasteful
               + 10.0 * open_bins_count as f64
               - 30.0 * progress;          // later in stream, reusing bins matters more
        if frac > 0.8 {
            score -= 40.0;                 // huge item: fresh bin is fine
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins first).
    score += 0.35 * (mean_residual - post_residual as f64).max(0.0);

    // Small tie-break on exact fit.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible future item are heavily penalized.
    let min_useful_gap = 12.0;
    if (post_residual as f64) < min_useful_gap {
        score += 45.0 * (min_useful_gap - post_residual as f64);
    }

    // Reward perfect / near-perfect packing.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Tightness reward: larger item relative to capacity is a better use.
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Lookahead (k=2): if the next item also fits this bin's post-residual,
    // strongly favor this bin (chain-filling).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 14.0;
        } else if next_item_size <= bin_residual {
            // next item would only fit here, not in the leftover -> slight penalty
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only open bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful when other
    // bins fit, so apply pressure proportional to open_bins_count.
    if bin_residual == bin_capacity {
        score += 35.0 + 3.0 * open_bins_count as f64;
        // No open bin can fit the item -> opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
        // Only one fitting bin and it's not this one -> keep the pressure
        // unless the fit would be terrible (handled by dead-space terms above).
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Mild coupling with mean residual: prefer bins close to the mean
    // (balanced depletion across bins).
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        let next_fits = next_item_size as f64;
        if (post_residual as f64 - next_fits).abs() < 1e-9 {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual as i64 >= next_item_size as i64 {
            score -= 25.0; // next item also fits here
            // tighter leftover after the pair is better
            score -= 0.3 * (post_residual as f64 - next_fits);
        } else {
            // next item won't fit: penalize large dead space
            score += 0.5 * (post_residual as f64 - next_fits).max(0.0);
        }
    } else {
        // last item: just prefer tightest fit
        score += 0.1 * post_residual as f64;
    }

    // Relative to mean residual: bins with residuals near mean are "normal",
    // prefer placing into below-mean-residual (fuller) bins
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity && fitting_bins_count > 0 && post_residual as f64 > 0.5 * bin_capacity as f64 {
        score += 30.0;
    }

    // Small bonus for tight fits overall
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact or near-exact packing is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 8.0;
    }

    // Penalize dead space: residuals too small to hold the smallest items (1..100 stream).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            // Next item won't fit here; slight penalty proportional to wasted opportunity.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item fits
    // poorly everywhere else. Make the empty bin moderately attractive by default but
    // discourage it when the item would leave a large residual that other bins avoid.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0; // fresh bin keeps future options open
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Later in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Global state: if mean residual is high, prefer using bins with small residuals
    // (balance the pool); if mean residual is low, tightening fits matters more.
    let diff = (bin_residual as f64) - mean_residual;
    score += diff * 0.25;

    // Mild preference for bins whose residual is slightly above item size (snug fit).
    let snug = (bin_residual as f64) - (item_size as f64);
    if snug > 0.0 && snug < 15.0 {
        score -= 6.0;
    }

    // Time horizon: early in the stream, slightly favor opening bins to keep flexibility.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= (1.0 - progress) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits; non-linear polynomial coupling with progress.
    let mut score = pr as f64;
    score += 30.0 * x * x * (1.0 - progress);
    score -= 25.0 * x * (1.0 - x) * progress;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if pr < next_item_size as f64 {
            score += 18.0 * (nx - x) * (1.0 - progress);
        } else {
            score -= 8.0 * x * (1.0 - nx);
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly discouraged early, allowed late.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 6.0 * x;
    }

    // Spread awareness: penalize bins far from mean residual.
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small residuals that are "clean"
    // fractions of capacity are less wasteful than awkward leftovers.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else {
        let class_penalty = match pr {
            0..=5 => -30.0,
            6..=15 => -10.0,
            16..=30 => 5.0,
            31..=50 => 12.0,
            _ => 20.0,
        };
        score += class_penalty;

        // Modulo arithmetic: residuals divisible by small integers are
        // more likely to be exactly filled by future small items.
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 5 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: does the next item fit harmonically into the
    // post residual? Reward exact/near matches.
    if next_item_size > 0 {
        let ni = next_item_size;
        if ni == pr {
            score -= 45.0; // exact chain
        } else if ni <= pr {
            let slack = (pr - ni) as f64;
            score -= 20.0 * (1.0 - slack / cap);
            // harmonic divisibility between next item and residual
            if pr % ni == 0 { score -= 10.0; }
        } else {
            // next item cannot use this residual: penalize small residuals more
            let waste = (ni - pr) as f64;
            score += 8.0 * (waste / cap);
        }
    } else {
        // last item: prefer tightest packing
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when current item
    // is large and residuals elsewhere are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        // Opening a new bin for a big item leaves item_frac residual that
        // is highly usable; penalize opening for small items.
        let open_cost = 55.0 - 35.0 * item_frac + 20.0 * progress;
        score += open_cost;
        // If many bins are open already, discourage opening more.
        score += 3.0 * (open_bins_count as f64).sqrt();
        // But if mean residual across open bins is small (fragmented),
        // a fresh bin is relatively better.
        score -= (mean_residual / cap).min(1.0) * 30.0;
    }

    // Prefer filling bins whose residual deviates below mean (tightening
    // the most fragmented bins first keeps the pool of large residuals).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.05 * dev; // bin already tighter than average -> mild penalty for using it
    } else {
        score += 0.03 * (-dev); // looser than average -> slight reward
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward exact closure of the bin.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible items (<= 10) are effectively unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Tight-fit bonus: leaving a small-but-usable gap is still better than
    // wasting a large bin on a small item; reward near-full packing.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.6 && post_residual >= 10 {
        score -= 8.0 * fill_ratio;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement chains perfectly; reward it heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual can't host the next item while other slack could.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only open bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another
    // one; make the new-bin candidate less attractive.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 5.0 + 2.0 * pressure.sqrt();
        // But if all open bins would leave terrible dead space, allow new bin.
        let worst_gap = mean_residual - item_size as f64;
        if worst_gap < 0.0 || (worst_gap > 0.0 && worst_gap < 10.0) {
            score -= 20.0;
        }
    } else {
        // Placing into an existing bin reduces fragmentation slightly as the
        // stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves a gap: penalize proportional to leftover
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this residual: dead-space penalty
            score += post_residual as f64 * 0.3;
        }
    }

    // Favor tight fits relative to mean residual
    let tightness = post_residual as f64 - mean_residual;
    score += tightness * 0.4;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening new bins when good open bins exist
    if bin_residual == bin_capacity {
        score += 20.0;
        // but opening a new bin is fine if this is the last item
        if next_item_size == 0 {
            score -= 20.0;
        }
    }

    // Late in the stream, prefer closing bins tightly (less future flexibility needed)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else if post_residual >= next_item_size {
            score -= 5.0; // next item can still fit here
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless residuals are very fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        score = 70.0 + fragmentation * 0.5;
        if open_bins_count == 0 {
            score = 0.0;
        }
    }

    // Prefer fullest bins (smallest residual) slightly
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild time-decay: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - tightness);

    // Many open bins -> encourage closing them out
    score += open_bins_count as f64 * 0.5 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual and its smooth polynomial shaping.
    let post_norm = post / cap;
    let post2 = post_norm * post_norm;
    let post3 = post2 * post_norm;

    // Base: quadratic in post-residual (favor tight fits, penalize dead space).
    let mut score = post + 40.0 * post2 + 60.0 * post3;

    // Smooth stream-progress coupling: early on, tolerate slack; later, tighten.
    let progress_coupling = progress * (1.0 - progress);
    score += 30.0 * post_norm * (0.5 + progress) - 50.0 * progress_coupling * post_norm;

    // Lookahead: if next item fits into post-residual, reward strongly (smooth gate).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let fits_next = (post - nxt).max(0.0) / cap;
        let gate = 1.0 / (1.0 + (post - nxt).abs() / cap);
        score -= 45.0 * gate * (1.0 - fits_next);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mean residual coupling: penalize bins deviating from mean residual (balance load).
    score += 0.3 * (post - mean_residual).abs();

    // New-bin candidate: mild penalty so open bins are preferred unless very poor fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "dead" (small, unusable)
    // get penalized; residues divisible into nice fractions get rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Dead-space penalty: post_residual in (0, 10) is nearly unusable for
    // items >= 1 but wastes capacity; heavier penalty the smaller it is.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.5;
    }

    // Reward post_residuals that are multiples of common item sizes (harmonic classes)
    for m in [10u32, 20, 25, 50].iter() {
        if pr >= *m && pr % m == 0 {
            score -= *m as f64 * 0.3;
        }
    }

    // Modulo-10 harmonic band: residues near multiples of 10 fit typical sizes
    let r10 = pr % 10;
    if r10 == 0 {
        score -= 6.0;
    } else if r10 <= 3 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // reward proportionally to how well next item fills the leftover
            let fill = next_item_size as f64 / prf;
            if fill > 0.7 {
                score -= 12.0 * fill;
            } else if fill > 0.4 {
                score -= 5.0 * fill;
            } else {
                // next item would leave another tiny residue: mild penalty
                score += (pr - next_item_size) as f64 * 0.05;
            }
        } else {
            // next item cannot use this residue at all: penalize proportionally
            score += next_item_size as f64 * 0.08;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish score based on capacity; only choose new bin
    // when residual fit would be terrible. Base score = capacity minus lookahead
    // room so a fresh bin is attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        score = cap - 8.0;
        if next_item_size > 0 {
            score -= (100 - next_item_size.min(100)) as f64 * 0.1;
        }
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        // discourage opening new bins early in the stream when few bins open
        if open_bins_count < 3 {
            score += 25.0;
        }
    }

    // Slight global pressure: prefer bins with residual far from mean (tight fit)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    // Mild time decay: as stream progresses, pack tighter (favor low post_residual more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += prf * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item {
            score += 1000.0;
        }
        // Non-linear penalty: small residuals are nearly unusable.
        let gap = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * (1.0 - gap).powi(6);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: penalize placements that leave bins fragmented
    // when many bins are open; encourage filling existing bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Lookahead: reward residual that can fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Slight preference for tighter fits overall.
    score += (bin_residual - item_size) as f64 * 0.05;

    // Prefer bins whose residual is below mean (denser bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New-bin candidate: penalize mildly so existing bins are preferred
    // unless their scores are bad; also scale with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward when post_residual exactly matches next item,
    // penalize when post_residual is nonzero but too small for next item (dead space).
    if next_item_size > 0 {
        if post_residual as u64 == next_item_size as u64 {
            score -= 500.0;
        } else if post_residual > 0 && (post_residual as u64) < next_item_size as u64 {
            score += 150.0;
        } else if post_residual as u64 > next_item_size as u64 {
            // slack remaining still usable: mild reward proportional to closeness
            let gap = post_residual as f64 - next_item_size as f64;
            score -= (50.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        }
    }

    // Tightness relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin when other bins fit,
    // unless it's early in the stream or many bins are open (spread load).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 400.0 + 200.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += base + open_bins_count as f64 * 5.0;
        } else {
            score -= 100.0;
        }
    }

    // Mild preference for filling fuller bins (small residual before placement).
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, with slight super-linear penalty on waste.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (pr / cap) * cap;

    // Reward tight fits (post_residual small relative to item).
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving residual that is awkwardly small but nonzero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Zero residual (perfect fit) is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: reward residual that can host the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = pr - ni;
            score -= 10.0 * (1.0 - slack / cap);
            // Bonus if residual exactly matches next item or leaves another useful chunk.
            if slack == 0.0 { score -= 20.0; }
            if slack >= 10.0 && slack <= 40.0 { score -= 6.0; }
        } else {
            // Next item won't fit here: penalize more if leftover is tiny.
            score += 8.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin when good fits exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 55.0;
        // But if no open bin fits well (all fits are loose), opening is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 2 && !is_new_bin {
        let mr = mean_residual.max(0.0);
        score -= 5.0 * (mr / cap);
    }
    // Few open bins: be less picky, allow moderate waste.
    if open_bins_count <= 2 && !is_new_bin {
        score -= 4.0;
    }

    // Time horizon: late in stream, avoid opening new bins; squeeze existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && !is_new_bin {
        score -= 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear reward for tight fits (small post_residual), scaled by capacity.
    let tightness = 1.0 - pr / cap; // in (0,1], higher = tighter fit
    score -= 18.0 * tightness * tightness;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space is more costly.
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += pr * (0.35 * prog2 + 0.25 * prog3);

    // Interaction: tight fit matters more as stream progresses.
    score -= 12.0 * tightness * (0.5 * progress + 0.5 * prog2);

    // Penalize new empty bin candidate smoothly, unless it is the only option.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 14.0 * scarcity * (1.0 + 0.5 * progress) * (1.0 - tightness);
    }

    // Last-chance bonus: only fitting bin left, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let compat = 1.0 - gap / cap;
        score -= 8.0 * compat * compat;
        // Penalize wasting space much larger than the next item needs.
        if pr > nxt {
            score += 0.15 * (pr - nxt) * (0.3 + 0.7 * progress);
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.4 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residues are "dead space"
    // Class residuals into buckets relative to capacity fractions
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize unusable dead space: post_residual smaller than min plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver is nearly useless
    }

    // Reward post_residuals that are multiples of common item sizes (harmonic classes)
    // Residuals divisible by 10 are more likely reusable
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // reward proportional to how well next item fills leftover
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 30.0 * fill;
            // harmonic: post_residual - next_item_size small => chain fit
            let chain = post_residual - next_item_size;
            if chain % 10 == 0 && chain > 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here: penalize more if leftover is dead
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor
    if bin_residual == bin_capacity {
        // opening a new bin: base cost, grows with number of open bins
        score = cap_f * 0.9 + (open_bins_count as f64) * 12.0;
        // but if next item is huge and current fit would leave big dead space, allow opening
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 40.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates from mean (consolidate fullness)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer more-filled bins (smaller residual) mildly
    score += 0.2 * (bin_residual as f64 / cap_f);

    // Harmonic threshold: integer-division classes of post_residual
    let class = post_residual / 10;
    match class {
        0 => score += 20.0,   // 0..9 dead
        1 => score += 0.0,    // 10..19 awkward
        2 => score -= 4.0,    // 20..29 decent
        3 => score -= 6.0,    // 30..39 good
        4 => score -= 8.0,    // 40..49 very good
        _ => score -= 10.0,   // 50+ flexible
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item are "dead space". Penalize them super-linearly.
    let dead_threshold = 10u32; // smallest item size
    if post_residual > 0 && post_residual < dead_threshold {
        let dead = (dead_threshold - post_residual) as f64;
        score += 12.0 + 3.0 * dead;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post-residual,
    // this is a chain fit; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement: mild penalty.
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += 0.15 * pressure;

    // Compare against mean residual: bins with residual well below mean are
    // already tight; placing here keeps fragmentation concentrated.
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when no open
    // bin offers a genuinely tight fit. Make the empty-bin score depend on how
    // badly the item fits open bins (large item => prefer new bin).
    if bin_residual == bin_capacity {
        // Baseline: new bin leaves full capacity; penalize mildly so tight fits win.
        score += 5.0;
        // Large items relative to capacity benefit from a fresh bin.
        let size_ratio = item_size as f64 / bin_capacity as f64;
        if size_ratio > 0.5 {
            score -= 10.0 * size_ratio;
        }
        // Many open bins with high mean residual => fragmentation; new bin is fine.
        if mean_residual > 30.0 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness;

    // 2-step lookahead: reward post_residual that exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain placement
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item cannot fit here; penalize small unusable leftovers
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
        // reward leaving room for next item at all
        if post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Relative to mean residual: prefer bins with residual close to or above mean
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity && bin_capacity - item_size < 100 {
        // new bin candidate: only attractive if it yields a perfect-ish fit
        let new_post = bin_capacity - item_size;
        score = new_post as f64;
        if next_item_size > 0 && new_post >= next_item_size {
            score -= 15.0;
        }
        if next_item_size > 0 && new_post == next_item_size {
            score -= 40.0;
        }
        // discourage new bin when many bins already fit the item
        score += 8.0 * (fitting_bins_count as f64);
        // discourage new bin late in the stream when open bins exist
        if open_bins_count > 0 {
            score += 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }
        // encourage new bin if its post-residual is small (tight new fit)
        score -= 10.0 * (1.0 - new_post as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this), sharpen it
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio; // reward filling bins proportionally tight

    // Penalize tiny dead space less than medium dead space (dead space < next item is reusable)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual can host the next item: strong reward
            score -= 6.0;
            score -= 0.05 * (post_residual - next_item_size) as f64;
        } else {
            // dead space unusable by next item: penalize proportionally
            score += 0.10 * post_residual as f64;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size == post_residual && post_residual > 0 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // or there are no open bins. Penalize new bins when mean_residual is large.
        score += 8.0 + 0.25 * mean_residual;
        if open_bins_count == 0 {
            score -= 20.0; // must open a bin
        }
        if fitting_bins_count == 0 {
            score -= 15.0; // nothing else fits
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global pressure: many open bins with small mean residual -> consolidate
    if open_bins_count > 2 && mean_residual < 25.0 {
        score -= 4.0;
    }

    // Mild preference for bins whose residual deviates from mean (keep homogeneity)
    score += 0.03 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste coupling, modulated by stream progress
    let mut score = pr * (1.0 + 2.0 * norm_pr * (1.0 + progress));

    // Smooth non-linear interaction: tight fits rewarded more as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness.powi(3) * (0.5 + progress);

    // Penalize leaving residual close to small-item sizes (unusable dead space)
    let dead = (norm_pr * 10.0).powi(2);
    score += 6.0 * dead * (1.0 - progress);

    // Lookahead coupling: reward residuals that can fit the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0) / cap;
        let match_bonus = 1.0 - ((pr - nxt) / cap).abs();
        score -= 12.0 * match_bonus.max(0.0) * (1.0 - progress);
        score += 4.0 * (1.0 - fits_next);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins early
    score += 1.5 * open_bins_count as f64 * (1.0 - progress) / (1.0 + progress);

    // New-bin candidate: penalize unless current residuals are badly fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).abs();
        score += 30.0 - 25.0 * frag;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Class index via integer division thresholds on post_residual (harmonic classes 1..=8)
    let class = post_residual / (bin_capacity / 8).max(1); // 0..=8 harmonic class
    // Penalize low classes (tiny unusable remainders) super-linearly
    match class {
        0 => score += 40.0,
        1 => score += 12.0,
        2 => score += 4.0,
        3 => score -= 2.0,
        _ => {}
    }

    // Reward residuals that are multiples of common item sizes (harmonic divisibility)
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 6.0;
            break;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does post_residual admit the next item (modulo class)?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra reward if next item exactly fills the remainder (harmonic pair)
            if next_item_size == post_residual {
                score -= 25.0;
            }
            // reward if next item divides the remainder evenly
            if post_residual % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residue: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only when
    // current fit is poor (large dead space) or few bins fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a bin
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative
        } else if frac > 0.5 {
            score -= 20.0 * frac; // poor fits invite a fresh bin
        }
    }

    // Progress-based tightening: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - frac) * progress * 5.0;

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    // Nudge toward balanced residuals relative to mean
    score += (pr - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item
    // (size 1) are worthless; residuals below typical item sizes are risky.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, strongly reward
    } else if post_residual < 10 {
        score += 25.0; // unusable tiny gap
    } else if post_residual < 25 {
        score += 10.0; // likely dead space
    } else if post_residual < 45 {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += pressure * 5.0;

    // New-bin candidate: penalize mildly so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * mean_residual;
    }

    // Prefer bins already tighter than average (better fit).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (minimize wasted space).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - waste_ratio) * (1.0 - waste_ratio);

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain: this bin will be exactly filled next step
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward proportional to how well it fills remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill * fill;
        } else {
            // next item cannot use the remainder: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 30.0 * (1.0 - waste_ratio);
    }

    // Relative to mean residual: prefer bins with residual close to item (good fit),
    // penalize bins that are much emptier than average (wasting big space on small item).
    let slack = bin_residual as f64 - item_size as f64;
    if slack > mean_residual {
        score += 0.08 * (slack - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - slack);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin when other bins can fit,
    // unless the item is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        let base_penalty = 20.0;
        let fragmentation = if open_bins_count > 0 { (mean_residual / bin_capacity as f64).abs() } else { 0.0 };
        // If open bins are very fragmented (high mean residual, poor fit prospects),
        // reduce the penalty so a fresh bin becomes attractive for large items.
        let relief = if item_size as f64 > mean_residual { 18.0 * (item_size as f64 / bin_capacity as f64) } else { 0.0 };
        score += base_penalty + 0.5 * open_bins_count as f64 - relief - 5.0 * fragmentation;
    }

    // Mild progression term: later in stream, be slightly more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good; penalize large dead space quadratically.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * bin_capacity as f64;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item fits but leaves more slack — mild penalty proportional to leftover.
            let l = (post_residual - next_item_size) as f64;
            score += 0.15 * l;
        } else {
            // Next item won't fit here; small bonus if this placement wastes little.
            score += 0.05 * (next_item_size as f64 - pr).min(40.0);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit_gap = (mean_residual - item_size as f64).max(0.0);
        // If existing bins leave lots of slack, opening a new bin is less costly.
        score += 20.0 + (fitting_bins_count as f64) * 5.0 - avg_fit_gap * 0.3;
    }

    // Prefer bins whose residual is far below the mean residual (they are "tight" already);
    // placing into looser bins keeps flexibility? Conversely, prefer filling looser bins.
    // Use deviation from mean residual: favor bins with larger residual (loose bins) for
    // big items, tighter bins for small items.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.1 * dev * (item_size as f64 / 100.0);

    // Time horizon: late in the stream, be more conservative about opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Many open bins: encourage closing them out (prefer bins with small residual).
    score += 0.08 * (open_bins_count as f64) * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping over progress
    let poly = 1.0 + 0.6 * progress * progress + 0.4 * (1.0 - progress) * (1.0 - progress);
    let mut score = pr * poly;

    // Reward tight fits: quadratic coupling of post_residual with item fill ratio
    let fill = item_size as f64 / cap;
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * fill;

    // Penalize wasted space relative to mean residual (smooth interaction)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev.abs();

    // Lookahead coupling: penalize leaving residual that can't fit next item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        if gap > 0.0 {
            score += 25.0 * gap * gap;
        } else {
            score -= 8.0 * (-gap);
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: mild penalty early, growing late (prefer consolidation)
    if bin_residual == bin_capacity {
        score += 15.0 * progress + 5.0;
    }

    // Slight penalty for too many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common item
    // granularity (e.g. 10) are more reusable than awkward leftovers.
    let granularity = 10u32;
    let harmonic_bonus = if post_residual == 0 {
        -60.0 // perfect fill, best possible outcome
    } else if post_residual % granularity == 0 {
        -25.0 // lands on a "clean" class, likely reusable by future items
    } else if post_residual < granularity {
        30.0 // dead space below the smallest item size
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division threshold on post_residual: classify into capacity
    // fraction buckets. Residuals in the upper half of the bin are valuable.
    let quarter = bin_capacity / 4;
    if post_residual >= 2 * quarter {
        score -= 12.0;
    } else if post_residual < quarter {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (perfect two-item packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // harmonic class of the double residual
            let r2 = post_residual - next_item_size;
            if r2 % granularity == 0 {
                score -= 18.0;
            }
            score -= (r2 as f64) * 0.15;
        } else {
            // next item cannot follow here; penalize slightly more for
            // small awkward leftovers
            if post_residual < granularity {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a new bin wastes the residual mass of all
    // open bins. Make it costly unless current bins are nearly full.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 45.0;
        // cheaper to open a new bin late in the stream? No: opening early
        // amortizes better; penalize more as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
        // if many open bins have plenty of room, prefer using them
        if mean_residual > 30.0 {
            score += 20.0;
        }
        // if almost nothing fits anywhere, allow the new bin
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer tighter fits overall: reward small post_residual relative to
    // the item size (packing density coupling).
    score -= (item_size as f64) / (bin_capacity as f64) * 8.0;

    // Mild penalty for spreading across too many open bins when residuals
    // are fragmented (mean residual low relative to item size).
    if mean_residual < (item_size as f64) && open_bins_count > 2 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold a future
    // item (min size 1, but practically gaps < ~15 are hard to reuse) are
    // heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (post_residual small relative to bin size).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0; // chains perfectly
        } else {
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        }
    }
    // Penalize if next item cannot fit in the residual (dead end risk),
    // unless residual is already unusable anyway.
    if next_item_size > post_residual && post_residual >= 15 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize the new-bin candidate (residual == capacity)
    // proportionally to how many bins are already open.
    if bin_residual == bin_capacity {
        score += 18.0 + 4.0 * open_bins_count as f64;
    } else {
        // Mild reward for keeping bins busy / consolidating.
        score += 0.5 * (mean_residual - post_residual as f64).abs();
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Perfect chain: item fits now, next item fits the remainder exactly
        if post_residual == next_item_size {
            score -= 150.0;
        }
        // Penalize leaving a remainder just barely too small for the next item
        if post_residual > 0 && (post_residual as i64) < (next_item_size as i64) {
            score += 0.3 * post_residual as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && post_residual as f64 <= mean_residual;
        if good_fit_exists || next_item_size == 0 {
            score += 250.0;
        } else {
            score += 40.0;
        }
    }

    // Slight early-stream preference for consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // Reward leaving room exactly for the next item.
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 {
            (post_residual as f64 / bin_capacity as f64) + (mean_residual / bin_capacity as f64) * 0.5
        } else {
            -10.0
        };
        // Penalize opening bins early in the stream; relax later.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += pressure * 30.0 - progress * 8.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (item_size as f64 / bin_capacity as f64) * 5.0;

    // Penalize bins whose residual deviates far above mean (fragmentation).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = (post_residual as f64 / cap).clamp(0.0, 1.0);

    // Core: quadratic penalty on wasted residual, sharpened by stream progress
    let mut score = pr * pr / cap;

    // Smooth non-linear interaction: residual waste weighted more as stream progresses
    score += (pr / cap).powi(3) * 60.0 * (0.3 + progress);

    // Reward tight fits (small post_residual) with smooth coupling to item size
    let tightness = 1.0 - fit_norm;
    score -= tightness * tightness * (item_size as f64) * 0.4;

    // Lookahead: bonus if next item can fit into post_residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let snug = 1.0 - (pr - nx) / cap;
            score -= snug * snug * 25.0;
        } else {
            // penalize leaving residual that next item cannot use
            score += (nx - pr).min(cap) * 0.5 * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // mild preference spread among many fitting bins
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate: penalize mildly, more when open bins have large mean residual
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.35 + (open_bins_count as f64) * 1.5;
    } else {
        // favor bins with residual close to item (best-fit flavor) via smooth coupling
        score += (mean_residual - bin_residual as f64).abs() * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * fill_ratio * fill_ratio;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class logic: partition post_residual into residue classes modulo 10.
    // Residuals that are small or "friendly" (multiples of 10, i.e. class 0) are
    // easier to fill later; penalize awkward classes more.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => 0.0,
        1 => 12.0,
        2 => 9.0,
        3 => 6.0,
        4 => 4.0,
        5 => 2.0,
        6 => 4.0,
        7 => 6.0,
        8 => 9.0,
        _ => 12.0,
    };
    score += class_penalty;

    // Integer division thresholds: dead space grows super-linearly once post_residual
    // exceeds small thresholds (a residual of 1..9 is nearly unusable for items >= 10,
    // but with sizes 1..100 keep moderate residuals usable).
    let dead_blocks = post_residual / 15;
    score += 3.0 * dead_blocks as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward if the next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let next_tightness = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 40.0 * next_tightness;
        } else {
            // Next item cannot use this residual: slight penalty proportional to leftover.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.5 * open_bins_count as f64;

    // Progress coupling: late in the stream, prefer tighter fills even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * fill_ratio;

    // Deviation from mean residual: prefer bins whose residual is close to item needs
    // (i.e. below mean residual is fine; above mean is wasteful).
    if (bin_residual as f64) > mean_residual {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // New-bin candidate: make an empty bin moderately attractive only when the item
    // is large relative to capacity and no good fit exists; otherwise discourage it.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score += 20.0; // base cost of opening a new bin
        score -= 25.0 * large_item; // large items justify fresh bins
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are wasted capacity.
    let min_gap = 1u32.min(bin_capacity); // items can be as small as 1
    if post_residual > 0 && post_residual < min_gap.max(1) {
        score += 1000.0;
    }
    // Penalize gaps too small for typical items (below the smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use this gap: mild penalty proportional to wasted potential
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a good fit exists
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is close to the mean (balance load)
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    // New-bin candidate: make it attractive only when current fits are poor
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; offset by item size (bigger items justify new bins)
        score = 45.0 - (item_size as f64 - 1.0) * 0.4 + open_bins_count as f64 * 0.3;
        if fitting_bins_count == 1 {
            score += 60.0; // do not abandon the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot fit: penalize large dead space
            score += 0.3 * post_residual as f64;
        }
    }

    // Compare against mean residual across open bins
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0 * ((post_residual as f64) - mean_residual).min(20.0);
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // fewer open bins -> cheaper to open a new one early
        score -= 2.0 * open_bins_count as f64;
    }

    // Tightness reward: bins that become nearly full are good
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor bins whose leftover is small.
    let tightness = 1.0 - (post / cap);
    score -= 30.0 * tightness * tightness;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: leftover should pair with the next item if possible.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // Reward leaving room exactly sized for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            // Penalize leftovers that are too small for the next item (dead space).
            score += 8.0 + 0.1 * (post - nxt).abs();
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: many open bins -> discourage new bins, encourage consolidation.
    let crowding = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless it enables a much better fit.
        score += 15.0 + 2.0 * crowding;
        // Allow new bin late in stream when residuals are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 25.0 && progress > 0.5 {
            score -= 20.0;
        }
    } else {
        // Existing bins get a mild preference over opening new bins.
        score -= 5.0;
        // Prefer bins with below-average residual (more filled bins).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Waste penalty: oversized leftovers that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Core: waste after placement, non-linearly amplified.
    let pr = post_residual as f64;
    let mut score = pr * (1.0 + 0.9 * progress) + 0.003 * pr * pr / cap;

    // Reward near-perfect fits (small post_residual) strongly.
    let tightness = 1.0 - pr / cap;
    score -= 25.0 * tightness * tightness * tightness;

    // Lookahead coupling: reward residuals that exactly accommodate next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let gap = pr - n;
            score -= 12.0 * (-gap / 8.0).exp();
        } else {
            // Dead space the next item cannot use.
            score += 0.15 * (n - pr);
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize spreading across many open bins when residuals are large.
    let mr = mean_residual / cap;
    score += 4.0 * (open_bins_count as f64).ln() * (1.0 - mr) * (0.5 + 0.5 * progress);

    // New-bin candidate: acceptable early or when it beats very poor fits,
    // but discouraged as stream progresses.
    if bin_residual == bin_capacity {
        score += 10.0 * progress * (1.0 + 0.5 * (open_bins_count as f64).ln());
        if next_item_size > 0 {
            score += 0.05 * next_item_size as f64 * progress;
        }
    }

    // Mild preference for bins whose residual matches item well (minimal slack).
    let slack = (bin_residual as f64 - item_size as f64) / cap;
    score += 6.0 * slack * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division tiers
    let tier = post_residual / 10;
    let residue = post_residual % 10;

    // Reward exact/near-exact fits heavily
    if post_residual == 0 {
        score -= 1000.0;
    } else if residue == 0 {
        score -= 60.0; // clean multiple of 10 residual
    } else {
        // penalize awkward residues (dead space less reusable)
        score += (10 - residue) as f64 * 2.5;
    }

    // Tier coupling: small tiers (tight bins) are good
    score -= (20 - tier.min(20)) as f64 * 1.5;

    // Lookahead: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0; // chain placement possible
            let next_res = post_residual - next_item_size;
            if next_res % 10 == 0 {
                score -= 25.0; // harmonic chain
            }
        } else {
            // next item won't fit: penalize proportionally to wasted residual
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    } else {
        // last item: only exact fit matters
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins where fit is tighter than the field
        score += (fitting_bins_count as f64 - 1.0) * 3.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor
    if bin_residual == bin_capacity {
        // neutral base: its score is just post_residual (= capacity - item)
        // penalize opening new bins while many open bins exist
        score += open_bins_count as f64 * 4.0;
        // but bonus late in the stream when consolidation matters less
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 30.0;
        // if next item is large, a fresh bin is flexible
        if next_item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        // existing bin: reward keeping mean residual balanced
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.6;
    }

    // Mild pressure to reduce open bin count
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that no future item (min size 1..=10)
    // can realistically use are heavily penalized.
    let dead = if post_residual > 0 && post_residual <= 10 { true } else { false };
    if dead {
        score += 60.0 + 4.0 * (11 - post_residual) as f64;
    } else if post_residual > 10 && post_residual <= 20 {
        // Moderately awkward gap: mild penalty that decays with usable size.
        score += 0.35 * (20 - post_residual) as f64;
    }

    // Reward bins whose residual tightly matches the item (good fill ratio).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Open-bin pressure: with many open bins, prefer consolidating into bins
    // that already exist; opening new bins is penalized via empty-bin residual.
    if open_bins_count > 0 {
        let pressure = (open_bins_count as f64).ln() * 3.0;
        // If this bin is the ONLY fitting bin, strongly favor using it.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 25.0 + pressure;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial credit proportional to how well next item fills the gap.
        score -= 0.5 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the gap at all: penalize proportionally.
        score += 0.3 * post_residual as f64;
    }

    // Mild preference to fill bins with low mean residual (nearly full bins)
    // to close them out, when the stream is progressing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - mean_residual / bin_capacity as f64);

    // New-bin candidate: keep its baseline near post_residual (== capacity),
    // but add a fixed opening cost so it only wins when fits are truly bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 500.0;
    } else if post_residual < 15 {
        score -= 150.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            let slack = pr - nx;
            if slack == 0.0 {
                score -= 800.0; // perfect chain: item then next item fills bin exactly
            } else if slack < 10.0 {
                score -= 300.0;
            } else {
                score -= 60.0 / (1.0 + slack / 20.0);
            }
        } else {
            // next item cannot fit here; penalize leaving large unusable gaps
            let gap = pr;
            score += 0.5 * gap;
            // slightly less harsh if gap could still combine with later items (small gap)
            if gap < 10.0 {
                score -= 20.0;
            }
        }
    }

    // Compare post_residual relative to mean residual across open bins:
    // prefer bins that end tighter than average (packing efficiency).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are usually preferred.
        score += 120.0;
        // If many open bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 80.0 * fitting_bins_count as f64;
        }
        // But if this is the last item, a fresh bin is fine (no future to serve).
        if next_item_size == 0 {
            score -= 400.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 100.0 * (1.0 - progress);
        // If the next item is large, a fresh bin has room for it; slightly favor opening.
        if next_item_size > 50 {
            score -= 40.0;
        }
    }

    // Mild penalty for leaving residual in a size range that is hard to fill
    // (residuals just below typical small-item sizes tend to become dead space).
    if pr > 0.0 && pr < 10.0 && next_item_size > pr as u32 {
        score += 15.0;
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: penalize wasted residual with a non-linear (quadratic) waste term
    let mut score = pr * (1.0 + 0.015 * pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress
    // Early: tolerate larger residuals; Late: strongly penalize them
    let late_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late_weight * 12.0 * (pr / cap);

    // Reward high fill ratio non-linearly
    score -= 8.0 * fill * fill;

    // Dead-space penalty: residual too small for the smallest plausible item (1..100)
    if pr > 0.0 && pr < 10.0 {
        score += 20.0 * (10.0 - pr) / 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let tight = 1.0 - (pr - nx) / cap;
            score -= 10.0 * tight;
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * (1.0 - late_weight) - 8.0 * (1.0 - fill);
    }

    // Mean residual dispersion: prefer bins below mean residual (tighter bins)
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common item sizes / small residues) are rewarded.
    let pr = post_residual;
    let cls = pr % 10; // decimal harmonic class
    // Penalize awkward residues (1..9 away from a multiple of 10)
    let residue_penalty = if cls == 0 {
        0.0
    } else {
        (10 - cls as f64).min(cls as f64) * 0.8
    };
    score += residue_penalty;

    // Reward exact tight fits strongly
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 10 {
        score -= 15.0;
    }

    // Dead-zone: leftover space too small for the smallest plausible item (<=10)
    if pr > 0 && pr < 10 {
        score += 30.0; // unusable dead space penalty
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mildly reward larger leftover anyway
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Integer-division threshold on post_residual: leftover in [25,50) or [50,75)
    // classes are more reusable than [10,25)
    let quarter = pr / 25;
    match quarter {
        0 => score += 5.0,        // small leftover, less useful
        1 => score += 0.0,        // mid leftover
        2 => score -= 3.0,        // large-ish leftover
        _ => score -= 5.0,        // half-full leftover after placement
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave awkward dead space, or when bin population is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_penalty = (mean_residual - item_size as f64).abs();
        // Opening a new bin is penalized by default, discounted late in stream
        score += 20.0 - 10.0 * progress;
        // If mean residual across open bins is far from item size, new bin less bad
        score -= avg_fit_penalty * 0.3;
        if open_bins_count > 8 {
            score += 5.0; // discourage bin proliferation
        }
    }

    // Mild preference for bins already below mean residual (consolidation)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Penalize medium awkward gaps more softly.
    else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    }

    // Prefer bins whose residual is close to item size (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is almost a fit, mild penalty for leaving a near-miss gap.
    else if next_item_size > post_residual && next_item_size - post_residual <= 8 && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another;
    // make the new-bin candidate (residual == capacity) less attractive.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 3.0;
    }

    // Prefer fuller bins relative to the fleet's mean residual.
    score += (mean_residual - post_residual as f64) * 0.5;

    // Slight late-stream conservatism: keep bins tight as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let exact = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += exact * 0.5;                 // penalize mismatch
        if post_residual == next_item_size {
            score -= 40.0;                    // perfect pairing bonus
        }
        // If next item fits exactly, strongly prefer this bin
        if bin_residual >= item_size + next_item_size {
            score -= 10.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    }

    // Relative to mean residual: prefer bins with residual near mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Prefer tighter bins generally (small post_residual is good)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        if post_residual > 60 {
            score -= 40.0; // large item, fresh bin is fine
        }
    }

    // Late in stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus for small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fill is extremely desirable.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this placement is ideal; if next item barely misses, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 6.0;
        }
        // If next item is huge and this bin's residual is small, prefer dumping here.
        if next_item_size >= 60 && post_residual < next_item_size {
            score -= 3.0;
        }
    }

    // Global state: many open bins -> prefer filling existing ones, avoid opening new.
    let open_pressure = (open_bins_count as f64).ln().max(1.0);
    score += 0.8 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: placing into a bin whose residual is near the mean
    // keeps balance; deviating bins get slight penalty.
    let dev = ((bin_residual as f64) - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in the stream, be pickier about creating small residuals;
    // late in the stream, just fill anything.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.05;
    score -= progress * 2.0;

    // New-bin candidate: only attractive when no bin fits well and residual
    // of existing bins is small relative to the item.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let avg_tight = if item_size > 0 { item_size as f64 / bin_capacity as f64 } else { 1.0 };
        score = bin_capacity as f64 * 0.9
            + scarcity * 12.0
            - (1.0 - avg_tight) * 10.0
            - open_pressure * 3.0
            + progress * 5.0;
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 8.0; // big next item: fresh bin is useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-style weight
    score += poly * norm_pr * norm_pr * 40.0;
    score -= (1.0 - poly) * norm_pr * 15.0;
    // Reward tight fits non-linearly
    let tight = 1.0 - norm_pr;
    score -= tight * tight * 25.0;
    // Lookahead coupling: penalize leaving residual that neither fits next item well nor is tiny
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        score += (1.0 - (-gap / 30.0).exp()) * 10.0;
        score -= (pr >= n) as f64 * 6.0 * (1.0 - poly);
    }
    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    // Mean residual drift penalty
    score += (mean_residual - norm_pr * cap).abs() * 0.05;
    // New-bin candidate: mildly discouraged early, more acceptable late
    if bin_residual == bin_capacity {
        score += 12.0 - poly * 20.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (modulo arithmetic on capacity) ---
    // Residuals divisible by 10 (harmonic with typical sizes) are more reusable.
    let class = post_residual % 10;
    if class == 0 {
        score -= 12.0; // perfectly harmonic residual
    } else if class <= 3 || class >= 7 {
        score += 8.0; // awkward sliver classes
    }

    // Integer-division thresholds: residual buckets by quarter capacity
    let quarter = bin_capacity / 4;
    if post_residual < quarter / 2 {
        score += 15.0; // near-dead space
    } else if post_residual >= quarter * 3 {
        score -= 6.0; // roomy bin still
    }

    // --- Perfect / near-perfect fit reward ---
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // --- Last-chance bin: strongly prefer using it before opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early, but wasteful late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 60.0 * progress + 2.0 * open_bins_count as f64;
        // If a future item matches a harmonic class of this fresh bin, mild bonus
        if next_item_size > 0 && next_item_size % 10 == 0 {
            score -= 10.0;
        }
    }

    // --- Lookahead: does the next item fit into the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic chaining: reward proportional to how well next item divides residual
            let chain_class = post_residual % next_item_size.max(1);
            score -= 25.0 - (chain_class as f64) * 0.5;
        } else {
            score += 10.0; // next item won't chain here
        }
    }

    // --- Mean residual coupling: avoid bins far from the fleet average ---
    score += ((post_residual as f64) - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (1..=10) are pure waste; punish them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + (10 - post_residual as i32) as f64 * 4.0;
    }
    // Medium gaps (11..=25) are only usable by small items; mild penalty.
    if post_residual > 10 && post_residual <= 25 {
        score += 8.0 + (25 - post_residual as i32) as f64 * 0.4;
    }

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual <= 15 {
        score -= (15 - post_residual) as f64 * 2.5;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into this bin's post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot host the next item: extra penalty scaled by gap size.
        score += (post_residual as f64).min(20.0) * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items;
    // with few open bins, opening a new bin is cheaper so raise open-bin scores.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 3.0 * (0.5 + progress);
    score += pressure;

    // New-bin candidate: make it attractive when fits are poor, unattractive otherwise.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 25 { 30.0 } else { 0.0 };
        score = 55.0 + pressure * 0.5 + poor_fit
            - if next_item_size > 0 && post_residual >= next_item_size { 10.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but scale relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: strongly reward when the NEXT item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect chain match (post_residual == next_item_size) is ideal.
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item cannot follow here: penalize dead space created.
        score += 15.0;
    }

    // Coupling with mean residual: prefer bins whose residual stays near the mean
    // (balanced packing); penalize stragglers.
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score.
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged when other bins fit decently,
        // but encouraged when the current item would leave large dead space.
        let dead = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score = 30.0 + dead * 50.0;
        // Late in the stream, keep bins consolidated.
        if total_items > 0 {
            score += (step_index as f64 / total_items as f64) * 20.0;
        }
    }

    // Tiny tie-breaker toward fuller bins.
    score += (bin_residual as f64 / bin_capacity as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Penalize dead space that cannot fit typical future items
        let dead = post_residual as f64;
        score += dead * (dead / cap) * 0.3;
    }

    // Best-fit flavor: prefer tightest fit
    score += (bin_residual - item_size) as f64 * 0.05;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + (next_item_size as f64 / cap) * 6.0;
        } else {
            score += 2.0;
        }
    }

    // New-bin candidate handling: only attractive when item is large
    // or no open bin is a good fit, otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        if fill_ratio > 0.6 {
            score -= 10.0 * (fill_ratio - 0.6) / 0.4;
        }
        score += 12.0; // base penalty for opening a new bin
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 6.0; // extra penalty when existing bins fit
        }
        // Early stream: allow opening bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 4.0;
    }

    // Global fragmentation pressure: if mean residual is high, prefer
    // consolidating into fuller bins.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Slight bonus for packing into bins that are already well-filled
    let used_ratio = 1.0 - bin_residual as f64 / cap;
    score -= used_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = post * (1.0 + 0.5 * x * x);

    // Stream-progress coupling: late in the stream, penalize large residuals more strongly
    score += 20.0 * progress * x * x * x;

    // Early stream: mild preference for tight fits to build good structure
    score -= 5.0 * (1.0 - progress) * (1.0 - x) * (1.0 - x);

    // Mean residual coupling: if open bins are already slack, discourage creating more slack
    let mean_norm = mean_residual / cap;
    score += 8.0 * mean_norm * x;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - progress) * (nxt / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately unattractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Quadratic dead-space penalty: leftover space is wasted potential.
    score += 0.35 * (post_residual as f64).powi(2) / cap;

    // Harmonic classes on post_residual (integer division thresholds).
    let class = post_residual / 10;
    match class {
        0 => score -= 8.0,      // near-perfect fit class
        1 => score -= 3.0,      // good fit class
        2..=4 => score += 2.0,  // mediocre classes
        _ => score += 6.0,      // large dead-space class
    }

    // Tight-fit bonus thresholds.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead coupling: does the next item fit into the leftover?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin before opening a new one.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 15.0;
    }

    if is_new_bin {
        // Generally prefer existing bins, but allow new bins for big items
        // or late in the stream when residual fragmentation is high.
        score += 20.0 + 10.0 * progress;
        if item_size >= 50 {
            score -= 8.0;
        }
        if mean_residual < 20.0 {
            score -= 6.0;
        }
    } else {
        score -= 5.0;
        // Favor bins with above-average residual (they need filling most).
        if bin_residual as f64 > mean_residual {
            score -= 3.0;
        }
    }

    // Mild pressure to reuse bins rather than proliferate.
    score += 0.005 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 60.0 * (10.0 - dead) / 10.0; // tiny gap = wasted space forever
    } else if dead == 0.0 {
        score -= 40.0; // perfect fit is always great
    }

    // Penalize post_residual relative to typical item sizes (unknown range 1..100):
    // a residual that is too small for the smallest plausible item is dead.
    if dead > 0.0 && dead < item_size as f64 {
        score += 0.6 * (item_size as f64 - dead);
    }

    // Reward filling bins tightly when many bins are open (bin pressure).
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score += pressure * 3.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        if (dead - nd).abs() < 0.5 {
            score -= 20.0;
        } else if dead >= nd && dead - nd < 10.0 {
            score += 15.0; // leaves another tiny dead gap for the next item
        }
    }

    // Slight preference toward bins with below-average residual (tighter bins first),
    // keeping loose bins flexible for larger future items.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: keep it neutral-to-slightly-costly so we only open
    // a new bin when existing bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if the item is large and would leave a big residual anyway, opening
        // a fresh bin is fine.
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= bin_capacity {
        if post_residual >= next_item_size {
            // Excellent: leaves room for the lookahead item (chained fit).
            let tightness = (post_residual - next_item_size) as f64;
            score -= 300.0 - tightness * 0.5;
            if tightness == 0.0 {
                score -= 500.0; // exact 2-item chain fill
            }
        } else {
            // Lookahead won't fit here: penalize wasted leftover space
            // proportionally to how much of the next item is stranded.
            let waste = post_residual as f64;
            score += waste * 0.4;
            // Small residuals (<10) are nearly dead space for items >= 10.
            if post_residual < 10 {
                score += 150.0;
            }
        }
    }

    // Relative to mean residual: prefer bins that are already partially filled
    // (below-mean residual means this bin is fuller than average).
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / mean_residual;
        score += rel * 40.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it's chosen only
    // when no open bin offers a decent fit (its base score is bin_capacity,
    // which is already high, plus lookahead waste terms).
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if the item is large relative to capacity, opening a fresh bin
        // is less costly in fragmentation terms.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 80.0;
        }
    }

    // Late in the stream: consolidate more aggressively to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: favor filling existing ones rather than spreading.
    score += open_bins_count as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit reward (waste minimization core).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        // Non-linear penalty on dead space: small residuals are cheap, large ones costly.
        score += (pr / cap).powi(3) * 300.0;

        // Lookahead: penalize residuals that are just barely too small for the next item
        // (unusable wedge), reward residuals that can host the next item.
        if next_item_size > 0 {
            let n = next_item_size as f64;
            if pr >= n && n >= 1.0 {
                score -= 40.0 * (n / cap); // residual reusable by lookahead item
            } else if pr > 0.0 && pr < n {
                let wedge = pr / n;
                score += 60.0 * (1.0 - wedge).powi(2); // near-miss dead space
            }
        }

        // Reward pairing when the next item exactly fills this bin afterwards.
        if next_item_size > 0 && post_residual as u32 == next_item_size {
            score -= 120.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Fragmentation pressure: many open bins with high mean residual -> discourage
    // spreading; few open bins -> encourage filling existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_f = open_bins_count as f64;
    score += open_f * (2.0 + 6.0 * progress);

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when existing bins are too full/fragmented to absorb the item well.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // Base cost of opening a new bin, cheaper early, expensive late.
        let new_bin_cost = 180.0 + 220.0 * progress + 12.0 * open_f;
        // If current item is large, opening a fresh bin is relatively safer.
        score = new_bin_cost - 80.0 * item_frac;
        // If mean residual across open bins is large, prefer reusing them instead.
        score += 0.8 * mean_residual;
        // If almost nothing fits anywhere, opening a bin is fine.
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    } else {
        // Reward tighter fits relative to current bin residual.
        let fit_quality = 1.0 - (post_residual as f64 / bin_residual as f64);
        score -= 50.0 * fit_quality * fit_quality;
        // Slight preference for bins whose residual is close to mean (balance load).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 15.0 * dev;
    }

    // Mild stochastic-free tie-break by bin residual to keep deterministic ordering.
    score += bin_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);

    // Base: prefer small post-residual, with smooth non-linear coupling to progress.
    // Early in the stream, waste matters less (bins get reused); later, tight fits dominate.
    let pr_norm = pr / cap;
    let base = pr * (1.0 + 0.8 * progress) + 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Dead-space penalty: residuals too small to fit typical items are wasted.
    let dead = if pr < it { (it - pr as u32 as f64) * 0.5 } else { 0.0 };

    // Perfect-fit reward: smooth polynomial dip near zero residual.
    let perfect = -30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + 0.5 * progress);

    // Lookahead: reward leaving room for the next item (smooth quadratic coupling).
    let nx = next_item_size as f64;
    let lookahead = if nx > 0.0 {
        let gap = (pr - nx).abs();
        -20.0 * (1.0 - (gap / cap).min(1.0)) * (1.0 - (gap / cap).min(1.0))
    } else {
        0.0
    };

    // Last-chance bin: strongly favor using the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Congestion: many open bins with high mean residual -> favor consolidating into this bin.
    let congestion = -0.15 * (open_bins_count as f64) * (mean_residual / cap).max(0.0);

    // New-bin candidate: penalize opening a new bin unless it's genuinely better.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    let new_penalty = if is_new {
        15.0 + 60.0 * progress + 0.3 * (open_bins_count as f64)
    } else {
        0.0
    };

    base + dead + perfect + lookahead + last_chance + congestion + new_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual: classify dead-space quality ----
    // Class 0: post_residual == 0 (perfect closure) -> strong reward.
    // Class 1: post_residual in "small but reusable" band (1..=10) -> penalty (dead space).
    // Class 2: post_residual in mid band (11..=33) -> mild penalty unless next item fits.
    // Class 3: post_residual in large band (>33) -> mild reward (bin stays flexible).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        // Dead space: nothing of size >=10 can ever use it.
        score += 45.0;
    } else if post_residual <= 33 {
        // Mid band: only useful if the lookahead item can land here.
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if next_fits {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Harmonic sub-class: reward residuals that are "round" fractions of capacity.
        let q = post_residual / 10; // integer division class
        score -= 3.0 * q as f64;
    } else {
        // Large residual: flexible bin.
        score -= 6.0;
        // Penalize if residual is awkwardly just above typical item sizes.
        if post_residual % 10 == 0 {
            score -= 4.0; // divisible-by-10 residuals pair well with decimal-sized items
        }
    }

    // ---- Exact-fit coupling: item divides capacity harmonically ----
    if bin_capacity % item_size == 0 && post_residual == bin_capacity % (2 * item_size) {
        score -= 5.0;
    }

    // ---- Last-chance logic: if this is the only fitting bin, avoid forcing a new bin ----
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // ---- New-bin candidate handling: an empty bin is flexible but wasteful ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin offers a tight fit
        // and the current open-bin pool is congested.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 30.0 + 10.0 * congestion - 10.0 * progress;
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // ---- Lookahead pairing reward: post_residual exactly matches next item ----
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Pairing where post_residual can host next item with small slack.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size <= 10 {
        score -= 8.0;
    }

    // ---- Mild pressure toward bins below mean residual (balance the pool) ----
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Larger leftover gaps scale sublinearly (mild penalty).
        score += (post_residual as f64).sqrt() * 1.5;
    }

    // Open-bins pressure: penalize spreading across many bins slightly,
    // encouraging consolidation when open_bins_count is high.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad gap
    // and the next item could use a fresh full bin better.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let gap_penalty = if post_residual < 20 { 30.0 } else { 0.0 };
        score += 10.0 - gap_penalty - progress * 5.0;
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 15.0;
        }
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item can still fit: mild reward proportional to how tight the chain is.
        let slack = (post_residual - next_item_size) as f64;
        score -= 100.0 - slack * 0.8;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leftover dead space below next item size.
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.5;
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving this bin below-average residual concentrates waste in one bin (good).
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open bin fits
    // well (tight fit) or the current bin would leave an awkward small residual.
    if bin_residual == bin_capacity {
        // Base penalty for consuming fresh capacity.
        score += 250.0;
        // If placing here would leave a residual that matches the next item,
        // a fresh bin is actually a great chain start — forgive the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            let tight = (post_residual - next_item_size) as f64;
            score -= 200.0 - tight * 0.5;
        }
        // Early in the stream, fresh bins are cheaper to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 150.0 * (1.0 - progress);
    }

    // Mild penalty for very small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly: post_residual near zero is best.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable gaps (dead space) that few items can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // New-bin candidate handling: strongly discourage opening a new bin
    // unless no decent alternative exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 60.0;
        // If many bins can fit the item, opening a new bin is clearly bad.
        if fitting_bins_count > 1 {
            score += 40.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Last-chance bin exists: opening new bin is very wasteful.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
        // If no open bin fits (fitting_bins_count == 0 handled implicitly:
        // new bin is the only option), reduce penalty.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        // Early in the stream, having few bins, opening is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If mean residual of open bins is high but none fit, a new bin
        // is fine (fragmentation elsewhere).
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 5.0;
    } else {
        // Reward using existing bins, especially when they are the only fit.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Prefer bins with lower residual relative to mean (fill fuller bins first).
        score += (bin_residual as f64 - mean_residual) * 0.3;

        // Lookahead: if next item fits into post_residual, bonus for this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // If next item would NOT fit after this placement but would fit
        // before (i.e., this placement blocks the next item), penalize slightly
        // unless the current fit is very tight.
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 6.0 * (1.0 - fit_ratio);
        }
        // Late in the stream, consolidate aggressively: favor fullest bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (bin_residual as f64 / bin_capacity as f64) * 10.0 * progress;
    }

    // Mild global pressure: more open bins -> prefer consolidation into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of post_residual
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: as stream advances, penalize large residuals more
    score += 8.0 * progress * norm_pr * norm_pr * cap * 0.1;

    // Reward nearly-empty post residual (perfect fit) with smooth quadratic term
    score -= 4.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (pr / (1.0 + pr));

    // Dead-space penalty: residual too small for typical future items
    let dead = (norm_pr * (1.0 - norm_pr)).max(0.0);
    score += 6.0 * (1.0 - 4.0 * dead) * norm_pr;

    // Lookahead: reward if next item can fit into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for many open bins relative to progress
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    // Mean residual coupling: prefer bins near the mean (balanced packing)
    let diff = (pr - mean_residual) / cap;
    score += 3.0 * diff * diff;

    // New-bin candidate: make empty bins moderately attractive only for large items
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 3.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in quarters of capacity
    let quarter = cap / 4.0;
    let post_f = post_residual as f64;
    if post_f > 0.0 {
        let class = (post_f / quarter).floor(); // 0..4
        // Penalize small unusable dead space (class 0 and 1) heavily
        score += match class {
            0.0 => 18.0,
            1.0 => 10.0,
            2.0 => 4.0,
            3.0 => 1.0,
            _ => 0.0,
        };
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic compatibility: does post_residual modulo next_item_size leave little waste?
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as u32;
        let rem = post_residual % nxt;
        let waste = rem as f64 / cap;
        score += waste * 12.0;
        // If next item divides post_residual nearly evenly, reward
        if rem == 0 {
            score -= 6.0;
        } else if rem as f64 > nxt as f64 as f64 * 0.8 {
            score -= 3.0;
        }
        // If next item cannot even fit this bin's post_residual, slight penalty
        if next_item_size as u32 > post_residual {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are quite full / poor fits
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // low pressure = open bins nearly full
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, allow opening bins more freely; later, prefer filling
        let openness = 1.0 - progress * 0.5;
        score = score.max(0.0);
        score += 8.0 * openness;
        score -= pressure * 20.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild crowding bonus for tight bins relative to mean
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are unusable.
    let min_item = 1.0f64;
    let dead_zone = 10.0f64;
    if (post_residual as f64) < dead_zone {
        // Unusable sliver: heavy penalty proportional to wasted capacity.
        score += 40.0 + (dead_zone - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if (post_residual as f64) <= dead_zone {
        score += 20.0; // extra penalty inside dead zone
    }

    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 && (post_residual as f64) >= (next_item_size as f64) {
        score -= 8.0; // gap remains useful for lookahead item
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins when tight fits exist.
    let pressure = (open_bins_count as f64).powf(1.3) * 0.05;
    score += pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        // Neutral base; dead-zone penalty above already discourages bad fits elsewhere.
        score += (mean_residual / bin_capacity as f64) * 5.0;
    }

    // Slight phase adaptation: later in stream, prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Partial lookahead credit: reward leftover space that still fits the next item.
        score -= 0.5 * (post_residual as f64 - next_item_size as f64).min(30.0);
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize unusable sliver.
        score += 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Compare post_residual to mean residual: leaving more than average is wasteful.
    score += 0.2 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: prefer it only when current bin would leave a tight unusable sliver.
    if bin_residual == bin_capacity {
        let tight = post_residual > 0 && post_residual < 10;
        if tight {
            score -= 40.0;
        } else {
            score += 20.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Slight preference for tighter fills as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead coupling: if next item fits into the post residual, reward this bin strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 14.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space that cannot serve the next item: penalize proportionally.
        score += 6.0 + 0.10 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64)).abs();
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the fullest (smallest residual) — already via post_residual.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: discourage opening a new bin unless the item fits poorly elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; modulated by stream position and global congestion.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let congestion = (open_bins_count as f64).ln().max(0.0);
        score += 30.0 + 10.0 * congestion - 8.0 * progress;
        // If next item is large and this new bin would be empty, slight relief.
        if next_item_size > 60 {
            score -= 6.0;
        }
    }

    // Global state nudges: prefer bins deviating favorably from mean residual.
    score += 0.08 * (bin_residual as f64 - mean_residual);

    // Late-stream conservatism: as the stream ends, minimize fragmentation harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let fit = item_size as f64 / cap;

    // Smooth polynomial coupling: post_residual penalized non-linearly,
    // modulated by stream progress.
    let mut score = post * (1.0 + 0.8 * progress * norm_post);

    // Dead-space penalty: residual below typical item size becomes waste.
    let dead = (fit - norm_post).max(0.0);
    score += 40.0 * dead * dead * (0.5 + progress);

    // Reward tight fits smoothly (quadratic in fill ratio).
    let fill = 1.0 - norm_post;
    score -= 25.0 * fill * fill * fill;

    // Last-chance bonus: few fitting bins -> prefer using this bin.
    if fitting_bins_count <= 1 {
        score -= 15.0;
    } else {
        score -= 5.0 / fitting_bins_count as f64;
    }

    // Lookahead coupling: reward leaving space for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs();
        score += 0.3 * gap * gap / cap;
        if post >= nx {
            score -= 8.0 * (nx / cap);
        }
    }

    // Slight preference for consolidating into few bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) * norm_post;

    // Dampen preference toward mean residual (avoid fragmented residuals).
    score += 0.2 * (post - mean_residual).abs() * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class on post_residual: perfect fits strongly favored
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 align with
    // typical item granularity, leaving more usable space
    let cls = (post_residual % 10) as f64;
    score += 0.15 * cls;

    // Lookahead coupling: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 0.08 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate: penalize by default, but open a fresh bin when no
    // open bin fits or when all fits would be terrible (huge post_residual waste)
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else {
            // if the best alternative would leave big dead space, prefer new bin
            if post_residual > bin_capacity / 2 && fitting_bins_count <= 2 {
                score -= 20.0;
            }
        }
    }

    // Last-chance bin: avoid opening a new bin when only one bin fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Deviation from mean residual: prefer bins tighter than the average
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Stream progression: late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // Item size class: large items waste more if misplaced
    if item_size > 60 {
        score += 0.05 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // future item (min size 1..100 unknown, but treat < 10 as likely dead)
    // are heavily penalized; a perfect (zero) fit is strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual < 10 {
        score += 200.0; // unusable dead space
    } else if post_residual <= 20 {
        score += 60.0;
    } else if post_residual <= 40 {
        score -= 10.0;
    } else {
        score -= 25.0; // large residual still useful
    }

    // Reward bins whose post_residual exactly accommodates the lookahead item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 30.0; // lookahead cannot use this bin afterwards
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64 * 3.0;
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        // Penalize new bins generally, less so when mean residual is tight.
        score += 150.0 + open_pressure - mean_gap * 2.0 - progress * 20.0;
        // A fresh bin is fine for very large items (poor fits elsewhere).
        if item_size >= 60 {
            score -= 100.0;
        }
    }

    // Mild pressure against accumulating many open bins: prefer filling
    // existing bins over spreading out.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins tighter than the mean residual (better packing density).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a post-placement residual that
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strong reward.
        if gap == 0.0 {
            score -= 60.0;
        } else {
            // Penalize deviation from the next item's size, scaled.
            score += gap * 0.35;
            // Dead space that can't fit the next item is wasted unless tiny.
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.25;
            }
        }
        // If the next item still fits after placement, mild bonus.
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: simply minimize leftover waste strongly.
        score += post_residual as f64 * 0.5;
    }

    // Penalize post residuals that are unusably small (dead space) but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Perfect closure of the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: bins with residual below mean are
    // "tighter" and preferred for filling.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large relative to a typical residual or no good
    // fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of opening a new bin.
        score += 55.0;
        // Large items benefit from a fresh bin more often.
        score -= (item_size as f64 - 40.0).max(0.0) * 0.4;
        // Late in the stream, avoid proliferating bins.
        score += progress * 20.0;
        // If many bins are open, discourage another.
        score += open_bins_count as f64 * 1.5;
        // But if lookahead shows the next item is large, a fresh bin is
        // a reasonable hedge.
        if next_item_size >= 60 {
            score -= 18.0;
        }
    }

    // Mild preference for bins with less residual overall (tighter fit).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let cap = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 25.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: small unusable leftover (nothing else can use it later).
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        score += 15.0 * (10.0 - post_residual as f64);
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 30.0;
        } else {
            score -= 12.0 * (1.0 - slack / cap);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual blocks next item: mild penalty scaled by how much it blocks.
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / cap;
    }

    // Last-chance bin: only bin that fits item — prefer using it over opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when current fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Waste of a fresh bin on a tiny item is bad; small items prefer existing bins.
        let fill_ratio = item_size as f64 / cap;
        score += 30.0 * (1.0 - fill_ratio);
        // During early stream, opening bins is cheaper (spread items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many open bins with large mean residual, prefer existing bins.
        score += 0.5 * mean_residual;
        // If no open bin fits well (post_residual large across alternatives implied by fitting count),
        // allow new bin: reward when item is big.
        if item_size >= 70 {
            score -= 25.0;
        }
    } else {
        // Prefer fuller bins slightly when many bins are open (consolidation).
        let fill = 1.0 - (bin_residual as f64 / cap);
        score -= 5.0 * fill * (open_bins_count.min(50) as f64 / 50.0);
    }

    // Mild global pressure: later in stream, be more conservative (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic coupling of fill ratio with stream progress
    let fill = 1.0 - post_residual as f64 / cap;
    score -= 18.0 * fill * fill * (0.5 + progress);

    // Penalize post-residual dead space that cannot fit the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) < ni {
            let waste = ni - post_residual as f64;
            score += 6.0 + 0.35 * waste * (1.0 + progress);
        } else {
            // reward bins that can also host the lookahead item snugly
            let slack = post_residual as f64 - ni;
            score -= 4.0 * (1.0 - slack / cap).max(0.0);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Dampen preference for nearly-full bins when many bins are open and mean residual is high
    score += 0.15 * (open_bins_count as f64).sqrt() * (mean_residual / cap);

    // New-bin candidate: mild penalty so it is chosen only when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 3.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
