            1 => score += 20.0,               // 10..19
            2 => score += 8.0,                // 20..29
            3 | 4 => score -= 2.0,            // 30..49 usable
            5 | 6 => score -= 6.0,            // 50..69 good
            _ => score -= 10.0,               // 70+: excellent
        }
        // modulo structure: residuals divisible by 10 pair well with typical item sizes
        if pr % 10 == 0 {
            score -= 3.0;
        } else if pr % 5 == 0 {
            score -= 1.5;
        }
    } else {
        score -= 50.0; // perfect closure
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / 40.0).max(0.0);
        } else {
            // next item won't fit here; penalize wasting large residual on small item
            let waste = (pr as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += 4.0 * (waste / 100.0);
        }
        // harmonic coupling: next_item_size in mid classes pairs with post_residual bands
        let ncls = next_item_size / 20;
        if ncls == 2 && pr >= 40 && pr < 70 {
            score -= 5.0;
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into tighter bins
    if open_bins_count > 3 {
        score += (mean_residual - post_residual as f64).abs() * 0.15;
    }

    // New-bin candidate tuning: empty bin should only win when existing fit is terrible
    if bin_residual == bin_capacity {
        score = 60.0 - 10.0 * (step_index as f64 / (total_items.max(1) as f64).max(1.0));
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if it is too small to fit even the smallest plausible item.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item * 8.0 {
        score += 60.0; // unusable sliver gap
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill is excellent
    }

    // Non-linear dead-space penalty: gaps that cannot fit the next item are risky.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0; // gap remains usable for lookahead item
    }

    // Reward last-chance bins (avoid opening a new bin when only one fits).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bins pressure: many open bins -> favor filling existing ones,
    // discourage spreading across bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bins moderately attractive only when
    // current item is large relative to residuals or no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tight_fit = (item_size as f64 / bin_capacity as f64) > 0.7;
        if tight_fit || fitting_bins_count == 0 {
            score -= 18.0; // prefer a fresh bin for large items / no fits
        } else {
            score += 12.0; // discourage wasting a fresh bin on small items
        }
    }

    // Mean residual coupling: if average residual is small, conserve bin space.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Progression: late in the stream, prefer tighter packing (lower post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: bin whose post_residual exactly matches the
    // next item is extremely valuable (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits here too, but leave reasonable slack.
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space, more so when small.
            let waste = post_residual as f64;
            score += 0.5 * waste * waste / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Slight penalty when many bins compete (spread placements poorly).
        score += 0.3 * (fitting_bins_count as f64).min(10.0);
    }

    // Prefer bins tighter than average (best-fit style relative matching).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Reward near-full packing of the current bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Early in stream: encourage consolidation; late: keep flexibility less critical.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty normalized by capacity.
    let pr = post_residual as f64;
    score += (pr * pr) / cap;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits in the post-residual (chain packing).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 0.5 * (next_item_size as f64);
    }
    // Penalize leaving a gap that nearly but not quite fits the next item (dead space trap).
    if next_item_size > 0 && pr > 0 && (next_item_size as u32) > post_residual && (next_item_size as u32) - post_residual <= 15 {
        score += 6.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a new bin.
        score += 25.0;
        // Attractive if current item leaves huge residual in any bin anyway,
        // or if item is large (large items pair well with future small ones).
        if item_size >= 60 {
            score -= 10.0;
        }
        if pr > 40.0 {
            score -= 5.0;
        }
        // Discourage new bins early in the stream when open bins exist.
        if open_bins_count > 0 && step_index < total_items / 4 {
            score += 15.0;
        }
    } else {
        // Prefer fuller bins: compare residual to mean residual.
        let res = bin_residual as f64;
        if res < mean_residual {
            score -= (mean_residual - res).min(20.0) * 0.5;
        } else {
            score += (res - mean_residual).min(20.0) * 0.3;
        }
    }

    // Late in the stream, consolidate: favor bins with small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) shaping
    let mut score = post + 40.0 * norm_post * norm_post * (1.0 + progress);

    // Dead-space penalty: residuals too small to ever be useful (smooth via tanh-like term)
    let unusable = (norm_post * 12.5 - 1.0).tanh(); // ~ -1 for tiny residual, ~ +1 for large
    score -= 15.0 * unusable;

    // Reward tight fits strongly (post_residual near 0 gets extra subtraction)
    score -= 20.0 * (-post / 8.0).exp();

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 18.0 * (-gap / 10.0).exp();
        // penalize if post_residual is large but next item can't fit
        if next_item_size as f64 > post {
            score += 8.0 * progress;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: make empty bin less attractive unless residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score += 30.0 - 40.0 * fragmentation * progress;
    }

    // Mild penalty for spreading across many bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "nice" residue classes (multiples of 10 / 25) are reusable by common
    // item sizes, so reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward residuals divisible by 10 (harmonic with the 10..80 item grid)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Reward residuals divisible by 25
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Penalize tiny dead space: residual < 10 is unusable for any item
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Penalize residuals in awkward bands via integer-division thresholds
    let band = post_residual / 10; // 0..=10
    let band_penalty = match band {
        0 => 20.0,                 // 1..9 dead space
        1 => -2.0,                 // 10..19 usable for small items
        2 => 1.0,
        3 => -3.0,                 // 30..39 good for mid items
        4 => 0.5,
        5 => -2.0,
        6 => 0.5,
        7 => -1.0,
        _ => 0.0,
    };
    score += band_penalty;

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            score -= 10.0;
            // extra reward if chained residual stays harmonic
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large and no open bin offers a tight fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tightness = (bin_residual as f64 - item_size as f64) / cap;
        // base penalty for wasting a fresh bin
        score += 40.0;
        // but if the new bin would be left very tight, allow it
        score -= tightness * 90.0;
        // if many open bins are highly fragmented, prefer fresh capacity
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 15.0 && open_bins_count > 3 {
            score -= 20.0 * progress;
        }
    } else {
        // favor bins tighter than the current average fill
        let avg = mean_residual;
        if (bin_residual as f64) < avg {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harder than large residuals (dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Favor bins whose residual tightly matches the item (small waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // rather than spreading items; with few bins, slightly favor consolidation.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64 * 10.0);
    score += 0.05 * open_bins_count as f64 * (1.0 - waste_ratio);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: make empty bins less attractive unless item is large
    // relative to typical residuals (avoid needless bin opening).
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size > 70 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the residual left behind,
    // this is an ideal chaining placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement: good chaining.
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Placement creates dead space the next item cannot use.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize leaving tiny unusable slivers (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New empty bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > (bin_capacity as f64) * 0.5;
        if poor_fit && open_bins_count > 0 {
            score -= 40.0;
        } else if open_bins_count > 0 {
            // Keep items in existing bins otherwise.
            score += 120.0;
        }
    }

    // Prefer tighter bins relative to the mean residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Early in the stream, be slightly more willing to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0 + (5 - post_residual) as f64 * 20.0;
    }

    // Penalize dead space: small post-residuals that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Tightness ratio: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Last-chance bonus: only bin that fits, avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + next_item_size as f64 * 0.2;
        } else {
            // Penalize creating residual that the next item cannot use,
            // unless the leftover is large enough to be reusable later.
            let waste = post_residual as f64 - (next_item_size as f64 * 0.0);
            if post_residual < next_item_size as f64 && post_residual < 20.0 {
                score += waste * 0.5;
            }
        }
    }

    // Prefer bins with residuals close to the item (best-fit flavor)
    // relative to the mean residual across open bins.
    let diff = (bin_residual as f64 - item_size as f64) - (mean_residual - item_size as f64);
    score += diff.max(0.0) * 0.3;

    // New-bin candidate handling: only attractive when existing fits are poor
    // or there are no open bins that fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            // competing with the last-chance bin: slightly discourage
            score += 10.0;
        } else {
            // many bins fit: opening a new bin is wasteful
            score += 30.0 + 5.0 * open_bins_count as f64;
        }
        // early in the stream, opening bins is cheap and flexible
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Mild pressure to consolidate: prefer bins below mean residual
    // (keeps large-residual bins available for larger future items).
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: minimize wasted space, with non-linear polynomial shaping of small residuals
    let mut score = pr as f64;
    score += 18.0 * x * x * (1.0 - x);          // penalize tiny dead space (waste) smoothly
    score -= 12.0 * x * (1.0 - x) * (1.0 - x);  // reward near-full fills

    // Stream-progress coupling: late in the stream, prefer tighter packing more aggressively
    let late = progress * progress;
    score += 25.0 * late * x * x;               // late: extra penalty on residual
    score -= 10.0 * progress * x * (1.0 - x);   // late: extra reward for good fits

    // Dead-space term: residual too small for any plausible future item
    let dead = (cap - pr) / cap; // fraction of bin used
    score -= 8.0 * dead * dead * (1.0 - progress);

    // Lookahead: reward if next item fits in the post residual
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (pr - n) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 6.0 * (n / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - 0.5 * progress);
    }

    // Mean residual interaction: if this bin is far from the mean, mild penalty
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: make empty bins less attractive unless residual is hopeless
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded,
    // small dead-space classes penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0;
    } else {
        // dead-space penalty grows steeply for unusable slivers (<10)
        if pr < 10 {
            score += (10 - pr) as f64 * 40.0;
        }
        // harmonic classes via modulo 10: residuals divisible by 10 are
        // "clean" and reusable by typical item sizes
        if pr % 10 == 0 {
            score -= 25.0;
        } else {
            score += (pr % 10) as f64 * 3.0;
        }
        // class of residual relative to capacity fractions
        let frac = pr as f64 / bin_capacity as f64;
        if frac < 0.25 {
            score += 30.0; // near-full bin, little future use
        } else if frac > 0.5 {
            score -= 15.0; // keeps bin versatile
        }
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 45.0;
            // harmonic match: next item exactly consumes residual class
            if pr % 10 == next_item_size % 10 {
                score -= 20.0;
            }
        } else {
            // next item would overflow this bin; penalize tight residuals
            score += (next_item_size - pr) as f64 * 0.5;
        }
    } else {
        // last item: prefer fullest packing
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // base cost of opening a bin
        score += 60.0;
        // if current item leaves a large clean residual, new bin is fine
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.7 {
            score -= 70.0;
        }
        // with many open bins and high mean residual, prefer reusing
        if mean_residual > 40.0 && open_bins_count > 2 {
            score += 50.0;
        }
        // late in stream, discourage proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // mild preference for tighter existing bins among equals
    score += (bin_residual as f64 - pr as f64) * 0.1;

    // small tie-break toward fewer open bins
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item
    // (assume ~10) or smaller than the lookahead item when it would otherwise fit.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    if post_residual < 10 {
        // Perfect-ish fit: reward strongly (dead space is zero-ish anyway).
        score -= 25.0 + 10.0 * (1.0 - progress);
    } else if post_residual < 20 {
        // Small gap: mostly dead space, penalize.
        score += 12.0;
    } else if post_residual < 35 {
        // Medium-small gap: risky, mild penalty.
        score += 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this bin strongly (perfect chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward proportional to tightness.
        score -= 3.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item would not fit here: the post_residual becomes dead space
        // for the lookahead; penalize proportionally to wasted space.
        score += 0.15 * (post_residual as f64);
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate handling: the empty bin has post_residual == bin_capacity.
    // Make it attractive only when the current item is large relative to
    // residual and no good existing option exists; otherwise keep it mildly
    // penalized so existing tight fits win.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins are open.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If the item is large (>= 60), a fresh bin is often better.
        if item_size >= 60 {
            score -= 20.0;
        }
        // Late in the stream, prefer closing out existing bins.
        if progress > 0.7 {
            score += 8.0 * progress;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is tighter than average — prefer it (subtracts score).
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 0.10 * diff;
    } else {
        score += 0.05 * (-diff);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits in the post residual -> reward proportional to tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * tight;
    }

    // Dead space: post_residual too small for next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Prefer bins with residual below mean (denser bins) for tight fits
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New empty bin candidate: penalize opening a new bin unless residuals are all poor
    if bin_residual == bin_capacity {
        let mut penalty = 55.0;
        if next_item_size > 0 && post_residual == next_item_size {
            penalty -= 90.0; // fresh bin perfectly reserved for next item
        }
        if open_bins_count == 0 {
            penalty = -10.0;
        }
        score += penalty;
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving exactly zero (or tiny) residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize dead space relative to the smallest plausible future item (size 1..100 unknown,
    // so use current item size as a proxy for "smallest useful chunk").
    let dead = post_residual as f64;
    if dead > 0.0 {
        // Waste that cannot hold even the current item size again is worse.
        if dead < item_size as f64 {
            score += 0.5 * dead;
        }
        // Large leftover is good if it can host the lookahead item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 0.6 * (next_item_size as f64);
            } else {
                // Lookahead won't fit here: penalize proportionally to the gap.
                score += 0.4 * ((next_item_size - post_residual) as f64);
            }
        }
    }

    // New-bin candidate handling: an empty bin is only attractive when the item is huge
    // (near-capacity) or no open bin gives a decent fit. Otherwise strongly discourage.
    if bin_residual == bin_capacity {
        let tight_fit = item_size as f64 >= 0.8 * bin_capacity as f64;
        let no_good_fit = fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.5;
        if tight_fit || no_good_fit {
            score -= 50.0;
        } else {
            score += 300.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Time-horizon modulation: early in the stream, be more conservative with tight fits
    // (keep flexibility); late in the stream, exploit tight fits harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 0.3 * (bin_capacity - post_residual) as f64;

    // Slight preference for consolidating into bins below mean residual (balance residuals).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x); // peaks at x=0.5, vanishes at extremes
    let mut score = pr + 12.0 * poly * (0.5 + progress);

    // Tight fits reward: smooth cubic in item_size relative to capacity
    let tight = (item_size as f64 / cap).powi(3);
    score -= 20.0 * tight;

    // Penalize dead space near-zero residual quadratically (unusable slivers)
    if x > 0.0 && x < 0.1 {
        score += 30.0 * (0.1 - x) * (0.1 - x);
    }

    // Last-chance bonus (smoothly damped by progress)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward if next item fits the post residual (smooth Gaussian-like)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-gap * gap / 200.0).exp();
    }

    // Coupling with mean residual: prefer bins below mean (consolidation)
    score += 0.3 * (pr as f64 - mean_residual).tanh() * 5.0;

    // Mild preference for fewer open bins early, more aggressive late
    score += open_bins_count as f64 * (0.1 + 0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1 fraction of capacity left

    // Dead-space penalty: residuals that are too small to be useful get heavily penalized.
    // Harmonic class thresholds via integer division on post_residual.
    let class = post_residual / 10; // classes 0..10
    match class {
        0 => score += 40.0,          // 0-9: near-perfect fill, but risk: unusable sliver
        1 => score += 15.0,          // 10-19: small but reusable by tiny items
        2 => score += 6.0,
        3 | 4 => score -= 4.0,       // 30-49: sweet spot for mid-size items
        5 | 6 => score -= 8.0,       // 50-69: very reusable
        7 | 8 => score -= 5.0,       // 70-89: decent
        _ => score += 2.0,           // 90-99: item barely dented the bin
    }

    // Reward exact harmonic alignment: next item fits perfectly into the leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_left = post_residual - next_item_size;
        if next_left == 0 {
            score -= 25.0; // chain completion: perfect two-item fill
        } else if next_left <= 5 {
            score -= 12.0;
        } else {
            score -= 4.0 * (next_left as f64 / cap);
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportionally to wasted capacity.
        score += 0.5 * (next_item_size as f64) * (1.0 - frac);
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes are more reusable.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0) {
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when it offers long-term value.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when decent fitting bins exist.
        score = cap + 10.0;
        // But if the current bin landscape is fragmented (high mean residual, many bins),
        // a fresh bin is attractive for large items.
        if item_size as f64 > 0.6 * cap && mean_residual < 0.35 * cap {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 1000.0; // no open bin fits: must open new bin
        }
    }

    // Tight-fit reward: item fills most of the bin.
    if frac < 0.1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    // Mild penalty for spreading across too many open bins.
    score += 0.3 * open_bins_count as f64 * frac;

    // Distance from mean residual: prefer bins whose leftover is near the average (typical fit).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted.
    // Items in [1,100] unknown distribution; treat gaps < ~15 as likely dead.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 - post_residual as f64 * 2.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else if post_residual <= item_size {
        // Gap still usable by same-size future items: mild reward.
        score -= 10.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that keep flexible residuals.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening new bins is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress) * 1.5;

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item would NOT fit here, slightly penalize hoarding a big gap.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Prefer bins with below-mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make empty bins attractive only when the item is
    // large or open bins are already numerous.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * large - open_bins_count as f64 * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit (dead-space elimination)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chain fill: perfect pairing
        } else if next_item_size <= post_residual {
            // next item fits here; reward proportional to how well it matches
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 2.0;
        } else {
            // next item cannot follow into this bin: penalize large leftovers
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Prefer tighter bins relative to mean residual (best-fit bias)
    score += (bin_residual as f64 - mean_residual).max(-50.0) * 0.8;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize choosing a fresh empty bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 120.0;
        // opening a new bin is attractive only if the item is large relative to capacity
        score -= (item_size as f64 / bin_capacity as f64) * 100.0;
    }

    // Late in the stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity)
    let tight_fit = (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * (1.0 - tight_fit) * (1.0 - tight_fit);

    // Penalize dead space that no future item can plausibly use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
            // extra reward for near-perfect two-item chain
            let chain = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - chain / bin_capacity as f64);
        } else {
            score += 12.0; // breaks the chain
        }
    } else {
        // Last item: just minimize waste
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 20.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, but allow late when fit is poor elsewhere
        score += new_bin_bias;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can chain next item
        }
    }

    // Global state: many open bins with high mean residual -> discourage fragmenting further
    if open_bins_count > 4 {
        score += 0.4 * (open_bins_count as f64 - 4.0);
    }
    if mean_residual > 40.0 && bin_residual < bin_capacity {
        score -= 8.0; // plenty of slack exists elsewhere; use this bin
    }

    // Mild preference for filling larger-residual bins first (best-fit-ish tiebreak)
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer minimal post residual, with a smooth non-linear penalty
    // that grows super-linearly as post_residual approaches capacity (waste).
    let mut score = post + 40.0 * norm_post * norm_post * (0.5 + progress);

    // Tight fit reward: strong non-linear coupling of post_residual with item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: reward if next item fits into the resulting residual
    // (smooth interaction rather than piecewise branch).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let covers_next = if post >= nxt { 1.0 } else { 0.0 };
        score += 12.0 * (gap / cap) * (1.0 - covers_next) * (1.0 - progress);
        score -= 10.0 * covers_next * (1.0 - gap / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (a fresh bin is only attractive for big items).
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / cap;
        score += 45.0 * (1.0 - size_ratio) * (1.0 - size_ratio) * (1.0 + 0.5 * progress);
        score -= 15.0 * size_ratio * size_ratio;
    }

    // Mild penalty for proliferating bins relative to mean residual state.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    score -= 0.1 * (mean_residual / cap) * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Harmonic class logic: classify post_residual by integer division thresholds.
    // Dead-space classes: 0 (perfect), 1-10 (near-perfect), 11-30 (usable), >30 (waste).
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 30 {
        score -= 5.0;
    } else {
        score += 15.0; // large dead space penalty
    }

    // Modulo-class harmony: if next item fits into post_residual, reward.
    if next_item_size > 0 && next_item_size <= pr {
        // Reward more if next item exactly fills remaining space (perfect chaining)
        if next_item_size == pr {
            score -= 40.0;
        } else {
            let next_post = pr - next_item_size;
            // harmonic class of the chained residual
            if next_post <= 10 {
                score -= 20.0;
            } else if next_post <= 30 {
                score -= 8.0;
            } else {
                score += 5.0;
            }
        }
    } else if next_item_size > 0 {
        // next item can't use this residual: penalize proportionally
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalty scaled by how many alternatives exist (crowded choice => be picky).
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // New-bin candidate handling: only attractive when residuals across bins are large.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        if mean_r < (item_size as f64) * 1.2 {
            // open bins are all tight; a fresh bin is reasonable
            score -= 10.0;
        } else {
            // plenty of room in existing bins; discourage new bin
            score += 40.0;
        }
    }

    // Mild time-entropy: later in stream, be slightly more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (open_bins_count as f64).ln().max(0.0);

    // Small bonus for using bins with residual close to item size (best-fit coupling).
    let gap = (bin_residual as f64) - (item_size as f64);
    score += gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are dead space -> heavy penalty.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 1000.0;
    }
    // Penalize very small gaps (unusable for most items) more than large gaps.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        score += (20.0 - pr) * 4.0;
    }

    // Reward tight fits (small post residual relative to item size).
    score -= (item_size as f64) * 0.5;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (handled implicitly: new bin has large residual -> high base score),
    // but with few open bins, slightly encourage consolidation.
    score += (open_bins_count as f64) * 0.3 * (pr / bin_capacity as f64);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - pr) * 0.2;

    // New-bin candidate: make it unattractive unless current bins are hopeless.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent chaining: next item plugs the remaining hole.
            let chain_tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * (1.0 - chain_tightness);
        } else {
            // Next item won't fit here: penalize leaving a hole that is
            // too small to be useful relative to the next item.
            let dead_gap = (next_item_size - post_residual) as f64;
            score += 0.08 * dead_gap;
        }
    }

    // Relative to mean residual: prefer bins that are already low
    // (consolidating) rather than near-average fresh bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins mildly unattractive
    // unless the item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > bin_capacity / 2 { 6.0 } else { 0.0 };
        score += 18.0 - large_item_bonus;
    }

    // Late in the stream: consolidate harder, discourage opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tight) * (1.0 - tight);

    // Perfect fit gets a strong extra reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0; // small dead space is acceptable
    } else {
        // Penalize dead space relative to the smallest plausible future item.
        if post_residual < 10 {
            score += 0.0;
        }
        // Dead space in (10..post_residual) is only usable if next item fits it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0; // lookahead: this residual is immediately reusable
        } else if next_item_size > post_residual {
            score += 6.0; // dead space likely wasted
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive for large items or when open bins are crowded.
        let crowding = mean_residual / (bin_capacity as f64);
        score += 10.0 * crowding; // penalize new bin when existing bins have room
        if item_size >= 50 {
            score -= 15.0; // large items pair well in fresh bins
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // next item can follow into the fresh bin
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Prefer filling bins that are already relatively empty (consolidate fragments).
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    // Mild time-varying pressure: late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - tight);

    // Slight preference to spread load when many bins are open with high mean residual.
    if open_bins_count > 3 && mean_residual > 40.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly warped by stream progress
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Smooth polynomial coupling: residual squared term penalizes large dead space,
    // but less so early in the stream when flexibility matters
    let dead_penalty = norm_pr * norm_pr * cap * (0.3 + 0.9 * progress);
    score += dead_penalty;

    // Cubic interaction of residual with progress: later, tight fits matter more
    score += norm_pr.powi(3) * cap * (1.5 * progress);

    // Lookahead: reward bins whose post residual can still hold the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 6.0 * progress;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Mean residual divergence: prefer bins near the mean (balanced packing)
    score += (pr - mean_residual).abs() * (0.2 + 0.4 * progress);

    // Slight penalty for too many open bins, scaled by progress
    score += open_bins_count as f64 * (0.5 * progress);

    // New-bin candidate: penalize mildly so it is chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of 10) are more likely to accept
    // future items, so reward them.
    let cap10 = bin_capacity / 10;
    let post_class = (post_residual / 10) as f64;
    let post_mod = (post_residual % 10) as f64;
    // Penalize non-aligned dead space (mod != 0) proportionally.
    score += post_mod * 0.6;

    // Reward bins whose post_residual is a multiple of 10 (harmonic alignment).
    if post_mod == 0.0 {
        score -= 2.0 + post_class * 0.1;
    }

    // Tight fit reward: post_residual small but nonzero is fine; exact fill is best.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    } else if post_residual <= 20 {
        score -= 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained exact fills).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Reward only if the chain leaves a harmonic leftover.
            if next_post % 10 == 0 {
                score -= 4.0 + (next_post / 10) as f64 * 0.2;
            } else {
                score += (next_post % 10) as f64 * 0.3;
            }
        } else {
            // Next item cannot follow in this bin: mild penalty proportional
            // to wasted harmonic slot.
            score += 1.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins are poor fits. Give it a baseline penalty that shrinks as the
    // stream progresses (early on, opening bins is cheap and useful).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 25.0 + 20.0 * (1.0 - progress);
        // If item leaves a harmonic residual in the fresh bin, soften slightly.
        let fresh_post = bin_capacity - item_size;
        if fresh_post % 10 == 0 {
            score -= 3.0;
        }
        return score;
    }

    // Prefer bins whose residual is far below the mean (consolidating
    // fragmented space), but only when the fit is harmonic.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.15;
    } else {
        score += (-dev) * 0.05;
    }

    // Integer-division threshold: bins whose residual class (residual / 10)
    // equals the item's size class get a small cohesion bonus.
    let item_class = item_size / 10;
    let res_class = bin_residual / 10;
    if item_class == res_class {
        score -= 1.0;
    }

    // Mild pressure to reduce open bin count late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range,
    // min item 1) are pure waste; residual < 10 is nearly unusable.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 120.0; // hard penalty: tiny dead gap
    } else if post_residual < 20 {
        score += 40.0;
    } else {
        // mild superlinear penalty on larger leftover space
        score += (post_residual as f64 / bin_capacity as f64).powf(1.5) * 30.0;
    }

    // Reward tight fits: fraction of bin filled by this item
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow and stream progresses
        score += 15.0 + pressure * 8.0 + progress * 10.0;
    } else {
        score += pressure * 0.5;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 12.0; // next item can't use this gap
        }
    }

    // Prefer bins with residual above the mean (keeps flexibility)
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= (res - mean_residual) * 0.15;
    } else {
        score += (mean_residual - res) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize wasted space non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        // Perfect two-item fill is excellent; small gaps are still good.
        score -= 30.0 * (1.0 - (gap as f64 / bin_capacity as f64));
        // Exact match: next item fills the bin completely.
        if gap == 0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize dead space creation.
        score += 12.0;
        // Extra penalty if the dead space is small (unusable sliver).
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Relative to mean residual: prefer bins that are more filled than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately unattractive unless residuals elsewhere are hopeless.
    if bin_residual == bin_capacity {
        score += 55.0 * (1.0 - step_index as f64 / total_items.max(1) as f64).max(0.0) + 15.0;
        // Late in the stream, opening new bins is fine; early, prefer filling existing ones.
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for bins whose remaining space stays "usable" (> half of typical item).
    if post_residual >= 50 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual) with a nonlinear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
            // Extra reward if next item fills the bin almost exactly.
            let combo_waste = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score -= 5.0 * (1.0 - combo_waste / bin_capacity as f64);
        } else {
            // Post residual too small for next item: penalize proportionally to dead space.
            score += 3.0 * fit_ratio;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when other bins can fit the item.
        if fitting_bins_count > 0 {
            score += 15.0 + 2.0 * fitting_bins_count as f64;
            // But if all fitting bins have terrible residual (large mean residual mismatch),
            // soften the penalty so opening a fresh bin can win.
            let mean_fit_gap = (mean_residual - item_size as f64).abs();
            if mean_fit_gap > 0.6 * bin_capacity as f64 {
                score -= 10.0;
            }
        } else {
            // No existing bin fits: new bin is the only option; slight reward.
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream, be more conservative about fragmenting bins
    // (many items remain); later, allow more flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - progress);

    // Global state: many open bins with high mean residual -> penalize adding to
    // fragmented state, encourage consolidating into existing space.
    if open_bins_count > 0 {
        let frag = mean_residual / bin_capacity as f64;
        if frag > 0.5 && bin_residual < bin_capacity {
            score -= 2.0 * frag;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;

    // Base: prefer bins with small post residual (tight fit).
    let mut score = post;

    // Smooth non-linear reward for tight fits: post_residual^2 normalized.
    score += (post * post) / cap;

    // Reward filling bins well as the stream progresses: interaction of fill ratio with progress.
    let fill = (residual - post) / cap; // fraction of bin consumed by this item
    let fill_ratio = residual / cap;
    score -= progress * fill * cap * (1.0 - fill_ratio);

    // Penalize large dead space quadratically, more so late in the stream.
    score += (1.0 + progress) * (post / cap) * (post / cap) * cap * 0.5;

    // Last-chance bonus: strongly favor the only bin that fits when alternatives are scarce.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 30.0 * progress;
    }

    // Lookahead: if next item could use the post residual, reward leaving exactly that much space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
        // Penalize creating space too small for next item (dead space).
        if post < nxt {
            score += 6.0 * (1.0 - post / nxt.max(1.0)) * (0.5 + 0.5 * progress);
        }
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    score += (open_bins_count as f64).ln() * 0.3 * (mean_residual / cap);

    // New-bin candidate handling: empty bin gets a moderate baseline that decreases
    // if current bins are congested (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let congestion = (mean_residual / cap).max(0.0);
        score = cap * (0.55 - 0.25 * progress) - 25.0 * (1.0 - congestion);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 create
    // "usable classes" of leftover space. Small non-zero residues that are
    // far from any plausible item size are dead space -> penalize.
    let r = post_residual;
    let class = r % 10;
    if r > 0 && r < 10 {
        // tiny sliver: dead space
        score += (10 - r) as f64 * 3.0;
    } else if class <= 2 && r < 40 {
        // awkward small class in a partly-used bin
        score += class as f64 * 1.5;
    }

    // Exact fit reward: harmonic class 0 (perfect fill)
    if r == 0 {
        score -= 60.0;
    }

    // Reward leaving a residual that belongs to a "harmonic band" matching
    // the lookahead item size (post_residual divisible / near-divisible).
    if next_item_size > 0 {
        let n = next_item_size;
        if r >= n {
            // lookahead fits here too -> strong reward scaled by tightness
            let tight = (r - n) as f64 / bin_capacity as f64;
            score -= 25.0 * (1.0 - tight);
            // bonus if residual is an exact multiple of the next item size
            if r % n == 0 {
                score -= 12.0;
            }
        } else {
            // lookahead cannot use this bin's leftover: penalize by gap size
            score += ((n - r) as f64) * 0.4;
        }
        // residue class match: post_residual and next item in same class mod 10
        if r >= n && (r - n) % 10 <= 3 {
            score -= 6.0;
        }
    } else {
        // last item: prefer tightest fill
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        if post_residual <= 15 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // less attractive than good fits but attractive over bad fits.
    if bin_residual == bin_capacity {
        score += 18.0;
        // early in stream, opening bins is cheap; later, reuse is precious
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (placing into below-average-residual bins consolidates usage).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    // Integer-division threshold: bins with residual in [50,99] are the
    // most flexible targets; slight reward to keep them balanced.
    let half = r / 2;
    if half >= 25 && half < 50 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

