    }

    // Open-bin pressure: fewer open bins is better; discourage spreading.
    score += 5.0 * open_bins_count as f64;

    // Prefer bins tighter than average (best-fit flavor).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Stream progression: late in stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // Perfect match for next item: strong reward
        if diff < 0.5 {
            score -= 25.0;
        } else if post >= nxt {
            // Next item fits: reward proportional to tightness of the two-step chain
            let tightness = 1.0 - (diff / bin_capacity as f64);
            score -= 12.0 * tightness;
        } else {
            // Next item won't fit: penalize dead space, worse if post_residual is small
            score += 8.0 * (1.0 - post / bin_capacity as f64);
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than the fleet average
    let post = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (post - mean_residual) / mean_residual;
        score += 3.0 * rel;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize very small post-residuals that become dead space (< 10 unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it's chosen only
    // when no open bin offers a good (2-step) fit
    if bin_residual == bin_capacity {
        score += 6.0;
    }

    // Late-stream conservatism: as stream progresses, prefer tighter fills
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose residual is close to the item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize large dead space after placement, especially if it is too small
    // for typical future items (dead-space trap).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0; // tiny unusable sliver
        } else {
            score += (dead / 100.0).powi(2) * 40.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 20.0 - (chain_waste as f64).min(20.0);
        } else {
            // Next item cannot follow into this bin: mild penalty proportional
            // to how much space would be stranded.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be more liberal about opening new bins
    // to build a diverse pool; later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_bonus = 60.0 * (1.0 - progress); // applied when comparing to new bin
    if bin_residual < bin_capacity {
        score -= new_bin_bonus * 0.5;
    } else {
        // This is the new-bin candidate: penalize opening new bins as stream matures
        // or when many bins are already open, unless mean residual is low (pool is full).
        score += 40.0 * progress + open_bins_count as f64 * 2.0;
        if mean_residual < item_size as f64 {
            // Existing bins are mostly full; opening a fresh bin is reasonable.
            score -= 30.0;
        }
    }

    // Mild preference for filling bins that are already more depleted
    // (keeps larger residuals available for larger future items).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Small global-state coupling: many open bins -> discourage spreading items thin.
    if open_bins_count > 5 && bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 40.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress)
        - 25.0 * norm_pr * (1.0 - progress);

    // Reward tight fits, stronger as stream progresses
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);

    // Penalize creating dead space smaller than typical next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 15.0 * (ns - pr) / cap * (0.5 + progress);
        } else {
            score -= 6.0 * (1.0 - (pr - ns) / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins
    score += 0.5 * (open_bins_count as f64 / (total_items as f64).sqrt());

    // Bias against opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress) + 8.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward large, efficient placements (tight fills).
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * 20.0;

    // Penalize unusable dead space: tiny post_residual that no item (min size 1..10) can use well.
    if post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling (k=2): does the next item fit into the leftover space?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can slot in: strong bonus scaled by how snugly it fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 8.0 + 6.0 * snug;
        } else {
            // Next item won't fit: penalize by the gap size.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Harmonic class logic: modulo-10 class of post_residual. Residuals that are
    // multiples of 10 are "harmonic" (likely reusable by typical item sizes).
    let harm = (post_residual % 10) as f64;
    score -= (10.0 - harm) * 0.3; // multiples of 10 get max discount

    // Integer-division threshold: residual in the 20..=40 band is prime real estate
    // for mid-size items; keep it flexible, slight bonus.
    let band = post_residual / 20;
    match band {
        1 => score -= 3.0,          // 20..39: flexible zone
        2 => score -= 1.5,          // 40..59
        _ => {}
    }

    // Progress-aware pressure: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - pr).max(0.0) * 0.2;

    // New-bin candidate: baseline cost. Only chosen when all open bins score worse
    // (i.e., they'd create dead space or break lookahead compatibility).
    if bin_residual == bin_capacity {
        score = 55.0 + pr * 0.1 - fill_ratio * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual below the minimum item size (1..100 interface => treat <10 as near-dead,
    // but keep generic) is worthless; penalize proportionally to how close to dead it is.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 8.0; // tiny gap = wasted space, big penalty
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 12.0;

    // Penalize medium dead space that can't fit typical items (gap in [10, 30) is awkward).
    if pr >= 10.0 && pr < 30.0 {
        score += (30.0 - pr) * 0.6;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones;
    // when few are open, allow new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; subtract if no good fits exist.
        score += 18.0 + bin_pressure * 2.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        } else if fitting_bins_count == 1 {
            // only one fitting bin: last chance — prefer using it unless fit is terrible
            score += 25.0;
        }
    } else if fitting_bins_count == 1 {
        // This is the only bin that fits: strong reward to use it.
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap_after_next = post_residual as f64 - next_item_size as f64;
        if gap_after_next < 5.0 {
            score -= 20.0; // perfect two-item packing
        } else {
            score -= 6.0;
        }
    }

    // Mild attraction toward bins with residuals near the mean (balanced packing).
    score += (pr - mean_residual).abs() * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
