pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic decay of post-residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual - next_item_size < 10 {
                score -= 8.0; // next item nearly fills remainder: great chain
            }
        } else {
            // post-residual too small for next item: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Global state: many open bins -> discourage spreading, favor filling existing.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * 0.5;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: late in stream, be more conservative (avoid waste).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += fit_ratio * progress * 10.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0
            || (fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual - item_size > 40);
        if desperate {
            score -= 5.0; // allow opening new bin
        } else {
            score += 25.0 + mean_residual * 0.2; // prefer reusing open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual (tight fit), non-linearly amplified
    let mut score = pr as f64;
    score += 12.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Smooth interaction: residual vs stream progress (waste matters more later)
    score += 8.0 * norm_pr * progress * (1.0 - progress) * 4.0;

    // Penalize bins far from the mean residual (dispersion penalty, smooth)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        if pr >= ns {
            // next item fits: mild reward, smoother for near-exact fits
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            // next item won't fit: penalize proportionally to overshoot
            score += 5.0 * (gap / cap) * (gap / cap) * cap * 0.1;
        }
    } else {
        // last item: strongly minimize waste
        score += 3.0 * norm_pr * cap * 0.5;
    }

    // Mild pressure against scattering across too many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: make empty bins less attractive unless residual after
    // placement is large enough to be useful, with progress-dependent threshold
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes.
    let post_mod = post_residual % 10;
    // Dead-space classes: small non-zero post-residuals are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // unusable sliver
    } else if post_mod == 0 {
        score -= 4.0; // perfectly divisible residual, likely reusable
    } else if post_mod >= 5 {
        score -= 1.5; // half-class residual, moderately useful
    } else {
        score += 1.0; // awkward small class
    }

    // Integer-division threshold: residual / item ratio
    if item_size > 0 {
        let fits_left = post_residual / item_size;
        score -= (fits_left.min(3)) as f64 * 3.0;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect harmonic match with lookahead
        } else if post_residual >= next_item_size {
            let next_mod = (post_residual - next_item_size) % 10;
            score -= 2.0;
            if next_mod == 0 { score -= 2.5; }
        } else {
            score += 2.0; // lookahead cannot follow here
        }
    }

    // Last-chance bonus: sole fitting bin — avoid opening a new bin unless residual is tiny.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
        if post_residual < 10 { score += 5.0; } // but not if it creates a sliver
    }

    // New-bin candidate handling: prefer opening a new bin when open bins are fragmented.
    if bin_residual == bin_capacity {
        score = (bin_capacity / 2) as f64 - 2.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual > 35.0 && fitting_bins_count > 2 {
            score += 10.0; // plenty of room out there, don't open
        }
        if next_item_size > 0 && next_item_size >= 60 && progress < 0.5 {
            score -= 3.0; // big item coming, fresh bin is valuable
        }
    }

    // Mild packing tightness: reward filling large fractions of capacity.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 2.0;

    // Harmonic tie-break on residual class pairs (residual/10 integer division threshold).
    let decile = post_residual / 10;
    score += (decile as f64) * 0.4;

    // Spread penalty when many bins are open and this one is far from mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03 * (open_bins_count.min(20) as f64) / 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

