        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 5.0; // creates dead space for the known next item
        }
    }

    // Mild coupling with mean residual: prefer bins below mean (keep big gaps available).
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
