    }

    // Penalize opening a brand-new bin when decent fits exist, unless current
    // open bins would leave large fragmented residual.
    if bin_residual == bin_capacity {
        // New bin candidate: neutral-ish base, penalized if item is small.
        score += 60.0;
        if item_size > 50 {
            score -= 30.0; // large items pack well into fresh bins
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0; // fresh bin supports the lookahead chain
        }
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
