            score -= 20.0;
        }
        // Penalize leaving residual that is dead space (too small for the smallest plausible item).
        if post_residual > 0 && post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 0.25 * dead;
        }
    }

    // Last chance: this is the only bin that fits; strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about slack.
        score += 0.15 * (post_residual as f64);
    }

    // Penalize bins with large residuals when the mean residual is high (spread items evenly
    // when there is slack overall); reward using big-residual bins when mean residual is low.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.2 * residual_gap;

    // Early in the stream: encourage opening fresh bins to build a diverse pool.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let open_penalty = 6.0 + 30.0 * progress;
        // A new bin is attractive only if current bin leaves a bad residual.
        score += open_penalty;
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Late in the stream: consolidate aggressively, avoid opening new bins.
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 40.0;
    }

    // Mild pressure to prefer bins with more remaining usable space when many bins are open.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = r;

    // Non-linear coupling: small residuals become progressively more valuable as the stream advances
    let tightness = (1.0 - rn).powi(3);
    score -= tightness * (20.0 + 40.0 * progress * progress);

    // Penalize large dead space quadratically, amplified with progress
    score += rn * rn * 30.0 * (0.5 + progress);

    // Last-chance bonus: strongly reward using a bin that is the only fitting one
    if fitting_bins_count == 1 && is_new < 0.5 {
        score -= 25.0;
    }

    // Lookahead: reward residual that can fit the next item (smooth kernel)
    if next_item_size > 0 {
        let fits_next = (rn * cap >= next_item_size as f64) as f64;
        let proximity = 1.0 - ((rn * cap - next_item_size as f64).abs() / cap).min(1.0);
        score -= fits_next * proximity * 15.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: penalize opening a bin when good fits exist, more so early on
    score += is_new * (15.0 + 20.0 * (1.0 - progress));

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.3 * rn;

    // Mean residual coupling: prefer bins below mean residual (tighter than average)
    score += (mean_residual - r) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post-residual (tight fit), scaled
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score = post * (1.0 + 0.5 * (post_residual as f64 / cap));

    // Harmonic class: bins whose residual lands on "nice" divisors of capacity
    // are more reusable for common item sizes. Penalize residuals that are
    // awkward (not divisible by small integers 2..6).
    if post_residual > 0 {
        let mut awkward = 0.0;
        for d in 2..=6u32 {
            if post_residual % d != 0 {
                awkward += 1.0;
            }
        }
        score += 6.0 * awkward;
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Dead-space penalty: post residual too small for minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.3 * slack;
            // harmonic check on resulting chain residual
            if (post_residual - next_item_size) % 5 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here regardless; mild bonus for tight current fit
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when the item is large relative to capacity or current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let big_item = (item_size as f64 / cap) > 0.6;
        let mut new_bin_score = 55.0;
        if big_item { new_bin_score -= 15.0; }
        if crowding > 3.0 { new_bin_score -= 10.0; }
        if progress > 0.5 { new_bin_score -= 5.0; }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual == bin_capacity - item_size {
            // fresh bin leaves room for the next item too
            new_bin_score -= 12.0;
        }
        score = score.min(new_bin_score) + new_bin_score * 0.5;
    }

    // Slight preference to fill bins with lower-than-mean residual (consolidate)
    let res_f = bin_residual as f64;
    if res_f < mean_residual && bin_residual < bin_capacity {
        score -= 2.0 * (mean_residual - res_f) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Larger leftover space is more reusable; reward proportionally.
        score -= 0.25 * post_residual as f64;
    }

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 20.0 * fill_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: penalize adding to already crowded bin sets mildly,
    // encouraging consolidation into existing bins.
    score += 0.8 * open_bins_count as f64;

    // If the next item could use the post_residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 35.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: dead space penalty.
        score += 15.0;
    }

    // New empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 25.0 + 5.0 * pressure;
    }

    // Progress-based mild adjustment: late in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: squash small post residuals aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins where the next item fits the new residual exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let slack = post_residual as f64 - next;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // Next item cannot fit here after placement: penalize wasted lookahead.
            let overshoot = next - post_residual as f64;
            score += 40.0 * (overshoot / bin_capacity as f64).min(1.0);
        }
    }

    // Relative-to-mean residual coupling: prefer bins whose post residual
    // is below the mean residual (packing tighter than average).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (pr - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: mildly penalize so we only open when placements look bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * mean_residual;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 500.0; // next item can't fit anywhere else anyway
        }
    }

    // Slight pressure to close out stream with tight packing late in the sequence.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional waste of the bin's space.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin when open bins fit,
    // unless the current item leaves a large usable residual for the next item.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > (item_size as f64 + post_residual as f64) * 0.5 {
        score -= 6.0;
    }

    // Penalize creating dead space that nothing typical can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post-residual, with a non-linear (quadratic) dead-space penalty.
    let mut score = pr + 0.6 * (pr * pr) / cap;

    // Perfect-fit reward (smooth bump near zero residual).
    let fit_quality = 1.0 - (pr / cap);
    score -= 12.0 * fit_quality * fit_quality * fit_quality;

    // Stream progress coupling: late in the stream, waste matters more (fewer future items to fill gaps).
    let urgency = progress * progress;
    score += urgency * (pr / cap) * 18.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * urgency;
    } else if fitting_bins_count > 1 {
        // Mild competition bonus scaled by how many alternatives exist.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item could exactly fill this bin's post-residual, big reward.
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1e-9 {
        score -= 30.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        // Next item fits here anyway: mild reward for preserving that option.
        score -= 4.0;
    } else if next_item_size > 0 {
        // Next item won't fit in the post-residual: penalize large leftover chunks.
        score += 0.35 * pr * (pr / cap);
    }

    // New-bin candidate handling: opening a new bin is only attractive early
    // or when the current item is large relative to capacity and no tight fit exists.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        // Penalize new bins, less so early in the stream.
        score += 20.0 + 30.0 * urgency;
        // Large items tolerate a fresh bin better.
        score -= 10.0 * (item_size as f64 / cap);
        // If many bins are open, prefer consolidation.
        score += 0.8 * (open_bins_count as f64).powf(0.9);
        // If the mean residual of open bins is large, opening new bins is wasteful.
        score += 0.15 * mean_residual;
    }

    // Mild penalty for bins already far below mean residual (avoid fragmenting very full bins oddly).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i64; // 8 harmonic classes of residual capacity

    // Penalize per class: dead space in higher classes is more wasteful than tiny leftovers.
    score += 6.0 * (class as f64 * (class as f64 + 1.0) / 2.0);

    // Modulo arithmetic: residuals divisible by small item granularities are reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 4.0; // perfectly reusable residue (common item granularity)
        } else if post_residual % 5 == 0 {
            score -= 2.0;
        }
        // Odd, prime-ish residues are dead space.
        if post_residual % 2 == 1 && post_residual < 10 {
            score += 3.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does post_residual fit the next item's harmonic class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus scaled by how tightly the next item would fit afterwards.
            let next_post = post_residual - next_item_size;
            score -= 8.0 * (1.0 - next_post as f64 / bin_capacity as f64);
            if next_post % 10 == 0 {
                score -= 3.0; // chains cleanly
            }
        } else {
            // Leftover smaller than next item: penalize by how much it misses.
            score += 2.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when existing bins are congested
    // or the fit would leave a large unusable residue.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        let tight_fit_exists = fitting_bins_count > 0
            && (bin_residual as i64 - item_size as i64 - (bin_capacity - item_size)) <= 0;
        let poor_fit = post_residual > 0 && post_residual < 10;
        if tight_fit_exists && !poor_fit {
            score += 25.0; // an open bin fits well; don't open a new one
        } else {
            score -= 5.0 + congestion * 2.0;
        }
    }

    // Slight stream-phase modulation: later in the stream, be greedier about tight fits.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - frac) * (1.0 + phase);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize mid-range dead space that likely cannot absorb the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from too many open bins: discourage opening new ones
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
        // Early stream: allow new bins more freely
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    } else {
        score -= 5.0;
    }

    // Slight preference for bins below mean residual (consolidating emptier bins)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // exactly host the next item (chain fit), penalize near-miss waste.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Small slack after next item is good (tight two-step packing).
            score -= (20.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
        } else {
            // Next item cannot fit here; dead space relative to next item.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }
    }

    // Penalize tiny unusable residuals (dead space) more than linear.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Favor tight fits relative to mean residual of open bins.
    let diff = post_residual as f64 - mean_residual;
    if diff < 0.0 {
        score += 0.25 * diff; // below-mean residual is desirable
    } else {
        score += 0.15 * diff; // above-mean residual is wasteful
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early in the stream, discourage hoarding many open bins; late,
    // allow tighter consolidation pressure to relax.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 4 {
        score -= 8.0 * (1.0 - progress);
    }

    // Slight preference for opening a new bin when item is huge and no bin is tight.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits perfectly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make it attractive
    // only when no open bin fits well (large post_residual everywhere) or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_waste = (mean_residual - item_size as f64).max(0.0);
        // New bin base cost; cheaper if existing bins are all badly filled.
        let mut new_bin_score = 120.0
            - 0.5 * mean_waste
            - 20.0 * progress
            - 2.0 * open_bins_count as f64;
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 70 {
            new_bin_score -= 15.0;
        }
        score = score.max(new_bin_score);
        score = new_bin_score.max(post_residual as f64 * 0.5 + new_bin_score * 0.5);
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation).
    score += 0.15 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Mild time pressure: as stream progresses, avoid leaving many half-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + progress);

    let mut score = pr + 20.0 * poly;

    // Penalize dead space more as the stream progresses
    score += progress * (norm_pr * cap).powi(2) * 0.01;

    // Reward using the last fitting bin (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward residual that can fit the next item smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_gap = (pr - ns).abs();
        score -= 8.0 * (1.0 - fit_gap / cap).max(0.0);
    }

    // Mild pressure from crowded bin pool
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * progress;

    // Deviation from mean residual (smooth quadratic)
    score += 0.05 * (pr - mean_residual) * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by common item sizes
    // (10,20,25,50) is "reusable" dead space; odd/prime-ish residuals are wasteful.
    let reusable = |r: u32| -> f64 {
        let mut v = 0.0;
        if r % 10 == 0 { v += 6.0; }
        if r % 20 == 0 { v += 4.0; }
        if r % 25 == 0 { v += 4.0; }
        if r % 50 == 0 { v += 6.0; }
        v
    };
    score -= reusable(post_residual);
    score -= reusable(bin_residual) * 0.3;

    // Integer-division threshold: post_residual bucketed in quarters of capacity.
    let quarter = bin_capacity / 4;
    let bucket = post_residual / quarter;
    score -= bucket as f64 * 2.0;

    // Penalize tiny unusable slivers (dead space), especially if next item can't use them.
    if post_residual > 0 && next_item_size > post_residual {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Perfect lookahead fit: strong reward
        score -= 10.0;
        if post_residual - next_item_size <= 5 {
            score -= 5.0; // near-exact two-item packing
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }
    // Many fitting bins: prefer tighter ones implicitly via post_residual, but
    // discourage scattering across many open bins.
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64) * 0.5;
    }

    // Empty new-bin candidate: neutral-ish baseline; only attractive when no open bin
    // fits well or open-bin residuals are heavily fragmented.
    if bin_residual == bin_capacity {
        score = 45.0
            - mean_residual * 0.4
            + (open_bins_count as f64) * 1.5
            + (item_size as f64) * 0.1;
        if next_item_size > 0 && next_item_size >= bin_capacity - 10 {
            score -= 5.0; // big next item: fresh bin is fine
        }
        return score;
    }

    // Progress-coupled tightening: late in the stream, prefer near-full bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64) * 0.3;

    // Coupling with mean residual: bins far from mean residual get slight tie-break.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // plausible future item are heavily penalized (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving space for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap is dead for the next item too: extra penalty.
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps the fleet balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: make it unattractive unless existing bins would create
    // severe dead space (handled above) or it's early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 10.0 * progress;
        // A fresh bin is fine if the item is large relative to capacity.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual super-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this is a perfect chain placement — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here: mild reward scaled by how well it uses leftover.
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * next_fill * next_fill;
        } else {
            // Next item cannot use the leftover: penalize dead space, worse when
            // the dead space is small (unusable sliver).
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 12.0 * (1.0 - dead / next_item_size as f64);
            }
        }
    }

    // Compare against mean residual: prefer bins that will end up below average
    // residual (consolidating space into fewer bins).
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.35 * (post_f - mean_residual);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so we only open a new bin when no open bin
    // gives a reasonable fit (i.e. current bin is a bad / loose fit).
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is large and nothing fits well, opening fresh is fine:
        if fit_ratio < 0.5 {
            score += 10.0 * (0.5 - fit_ratio);
        }
    }

    // Early in the stream, allow slightly more freedom to open bins; late in
    // the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fit_ratio;

    // Mild pressure to reduce number of open bins.
    score += 0.6 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Perfect fit gets a strong extra reward
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Extra reward if next item nearly fills the remaining space
        let next_gap = post_residual - next_item_size;
        if next_gap < 10 {
            score -= 6.0;
        }
    }
    // Penalize if next item would fit this bin only if we DON'T place here
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize creating dead space below the minimum plausible item size when many bins are open
    if post_residual > 0 && post_residual < 10 && open_bins_count > 2 {
        score += 5.0;
    }

    // Global state coupling: prefer filling bins that are below the mean residual
    // (balances residual distribution, keeps many medium-fit bins alive)
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 2.0 * (mean_residual - resid_f) / bin_capacity as f64;
    } else {
        score += 1.5 * (resid_f - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: late in the stream, be more conservative about opening new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        // existing bin: increasingly favored late in the stream
        score -= 5.0 * progress;
    }

    // New-bin candidate: penalize unless item is large relative to capacity or
    // no good existing option exists (many fitting bins means we can afford a new bin less)
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        score += 12.0;
        score -= 10.0 * size_ratio;
        score += 3.0 * fitting_bins_count as f64;
        // late stream: new bins are costly
        score += 8.0 * progress;
        // if the item is huge, a fresh bin is actually good
        if item_size >= 70 {
            score -= 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a non-linear polynomial shaping of post-residual
    let mut score = norm_pr * norm_pr * 40.0 + norm_pr * 20.0;

    // Smooth stream-progress coupling: later in the stream, dead space matters more
    score += progress * norm_pr * 30.0;

    // Reward using nearly-full bins via cubic term in (1 - norm_pr)
    let fullness = 1.0 - norm_pr;
    score -= fullness * fullness * fullness * 15.0;

    // Penalize leaving residual that cannot fit the lookahead item (smooth logistic-ish)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (ns - pr).max(0.0) / cap;
        score += gap * gap * 25.0;
        // Reward residuals that exactly accommodate the next item
        let match_f = 1.0 - ((pr - ns).abs() / cap).min(1.0);
        score -= match_f * match_f * 10.0;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Mild pressure against hoarding many open bins
    score += open_bins_count as f64 * 0.35;

    // Deviation from mean residual: prefer bins tighter than average
    score += (pr - mean_residual) / cap * 8.0;

    // New-bin candidate: penalize slightly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 12.0 + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: post_residual bucketed by integer division.
    // Small leftovers (post_residual < 10) are near-perfect fits -> reward strongly.
    if post_residual == 0 {
        score -= 500.0; // perfect closure
    } else if post_residual < 10 {
        score -= 40.0;
    } else {
        // class = post_residual / 10 : larger class = more usable leftover
        let class = post_residual / 10;
        score -= class as f64 * 3.0;
    }

    // Dead-space penalty: leftover that NO plausible future item can use.
    // Items are 1..=100; leftover < some small threshold is hard to fill exactly.
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly into this bin -> strong reward
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 120.0;
            } else {
                score -= 30.0 + (slack as f64).sqrt() * 2.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to overflow gap
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.8;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item fits badly everywhere else. Penalize fresh bins mildly.
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if the item is huge relative to capacity, a fresh bin is fine
        if item_size * 5 >= bin_capacity * 4 {
            score -= 55.0;
        }
        // early stream: opening bins is cheaper (many future items to fill them)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 20.0;
    }

    // Prefer filling bins whose residual deviates below the mean (compact the set).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.5;
    } else {
        score += (-dev) * 0.2;
    }

    // Modulo-arithmetic tiebreaker on residual classes (harmonic alignment):
    // bins whose residual is congruent to item_size mod 20 tend to close cleanly.
    if bin_residual % 20 == item_size % 20 && post_residual < 20 {
        score -= 15.0;
    }

    // Mild pressure to keep the number of open bins from exploding.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but tiny gaps are still hard to fill) get a heavy penalty.
    if post_residual == 0 {
        score -= 500.0; // perfect fit is always best
    } else if post_residual < 10 {
        score += 300.0; // unusable dead space
    } else if post_residual < 20 {
        score += 80.0;
    } else if post_residual < 35 {
        score += 20.0;
    }

    // Tightness reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * tightness;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if the next item fits the post residual exactly or well,
    // reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else if next_item_size <= bin_residual {
            // next item could have used this bin's full residual instead
            score += 30.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins rather than leaving many partially empty.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 + progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin that should be closed out soon -> favor filling it.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 0.4 * residual_gap;

    // New-bin candidate: only attractive when existing fits are very poor
    // (large dead space would be created) or no real bin fits well.
    if bin_residual == bin_capacity {
        let waste_if_placed = (bin_capacity - item_size) as f64;
        score = 250.0 + 0.5 * waste_if_placed - 20.0 * tightness;
        // late in the stream, avoid opening bins unless truly needed
        score += 100.0 * progress;
        if fitting_bins_count == 0 {
            score -= 400.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let match_gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            25.0 + (next_item_size - post_residual) as f64 * 0.5
        };
        // Perfect match (post_residual == next_item_size) gets a big bonus.
        score += match_gap * 0.8;
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // If next item cannot fit anywhere after this placement, penalize.
        if post_residual < next_item_size {
            score += 10.0;
        }
    } else {
        // Last item: minimize waste directly.
        score = post_residual as f64 * 1.5;
    }

    // Penalize dead space that likely can't be used (relative to smallest possible item ~1).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * (1.0 + progress);
    }

    // Compare against mean residual: prefer tightening bins above average fill.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it unattractive unless all open bins are nearly full
    // or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        if open_bins_count == 0 {
            score -= 40.0;
        }
        // If mean residual across open bins is small, opening new bin is reasonable.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 25.0;
        }
    }

    // Prefer filling bins that are already partially used (avoid bin proliferation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream: early on, be more exploratory (favor reuse less strongly);
    // late in stream, pack tightly.
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Reward tight fits: penalize large post_residual quadratically.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // partial reward proportional to how well next item fills leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // next item won't fit: penalize dead space a bit
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits (avoid opening new bins).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0 + 20.0 * progress;
    }

    // Penalize bins that are outliers vs mean residual (prefer balanced residual usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else (large post_residual in all fits) or few bins open.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; cheaper early, expensive late
        let new_bin_cost = 55.0 - 25.0 * progress + 2.0 * (open_bins_count as f64).ln();
        // if item is large, it will fill a fresh bin well -> slightly cheaper
        let fill = item_size as f64 / bin_capacity as f64;
        score = new_bin_cost + 20.0 * (1.0 - fill);
    }

    // Small reward for bins that would become "perfect" (zero residual).
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth interaction: as the stream progresses, dead space becomes more costly.
    let progress_penalty = progress * 20.0 * norm_pr * norm_pr;
    score += progress_penalty;

    // Reward tight fits non-linearly: quadratic bonus when post_residual is small.
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Lookahead: penalize if next item cannot use the resulting residual.
    if next_item_size > 0 {
        if (next_item_size as f64) > pr {
            score += 6.0 + 4.0 * progress;
        } else {
            let waste = pr - next_item_size as f64;
            score -= 3.0 * (1.0 - waste / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Discourage fragmenting bins when many bins are open and residual is large.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins when
    // open bins have genuinely poor fits (large post_residual).
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and small dead zones are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: residuals that can never be filled by typical items.
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        }
        // Harmonic division thresholds: classify post_residual by integer division into
        // capacity-fraction buckets. Buckets near half/full capacity are reusable.
        let bucket = post_residual / (bin_capacity / 4); // 0..4 classes
        let bucket_bonus = match bucket {
            0 => 25.0,                       // tiny residual: likely dead space
            1 => 0.0,                        // quarter-class
            2 => -15.0,                      // half-class: very reusable
            _ => -8.0,                       // large residual: flexible
        };
        score += bucket_bonus;

        // Modulo-10 harmonic class: residuals divisible into common item sizes (10,20,...)
        // are more likely to host a future item exactly.
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        }

        // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 200.0;
            } else if next_item_size <= post_residual {
                // next item fits: residual after that would be a second-order dead space
                let second = post_residual - next_item_size;
                if second == 0 {
                    score -= 90.0;
                } else if second < 10 {
                    score += 20.0;
                }
            } else {
                // next item cannot use this residual: residual value drops
                score += 10.0 + (next_item_size - post_residual) as f64 * 0.2;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer tight fits relative to residual (waste fraction penalty).
    let waste_frac = pr / cap;
    score += waste_frac * waste_frac * 30.0;

    // Early in stream: keep bins balanced; late: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0 * (1.0 - waste_frac);

    // Slight preference for bins below mean residual (keeps flexibility spread).
    score += (mean_residual - pr) * 0.15;

    // New-bin candidate: only attractive when item is large and no tight open fit exists.
    if bin_residual == bin_capacity {
        if item_size >= 50 && (fitting_bins_count == 0 || post_residual as f64 > cap * 0.5) {
            score -= 30.0;
        } else {
            score += 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Gap too small for the minimum item size: pure dead space.
            score += 40.0;
        } else {
            // Smoothly penalize small gaps that are unlikely to be filled.
            let gap_ratio = post_residual as f64 / bin_capacity as f64;
            score += 25.0 * (1.0 - gap_ratio).powi(6);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits relative to item size (small waste per item).
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
    } else {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose residual can still fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Mean residual coupling: prefer bins deviating below mean residual
    // (fill the emptier bins first, keep tight bins for small items).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Stream progression: as the stream ends, avoid leaving many tiny gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual closely matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = (post_residual as u32 - next_item_size) as f64;
        score -= 60.0 / (1.0 + match_gap);
    }

    // Penalize dead space that cannot fit the next item (wasted residual)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Penalize deviation from mean residual (prefer balanced residual usage)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight preference for filling bins tighter as the stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (item_size as f64);

    // Discourage opening a new bin when a decent fit exists in an open bin
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual dominates, but shrink penalty for very small leftovers.
    if post_residual > 0 {
        let tight = (post_residual as f64 / bin_capacity as f64).powf(2.0);
        score += tight * 30.0;
    } else {
        score -= 60.0; // perfect fill
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= (bin_capacity as f64 - gap) * 0.4;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here; penalize slightly more if post_residual is dead-ish.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it over new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        score += 40.0 + waste * 0.5 - progress * 10.0;
        // Allow new bin when open bins are crowded (few fitting bins relative to open bins).
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    // Prefer bins with residual close to mean (balanced usage) when mean is small.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild preference for fuller bins as stream progresses.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * (step_index as f64 / (total_items.max(1) as f64)) * 8.0;

    // Penalize many open bins slightly to encourage consolidation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;
    // smooth polynomial coupling of post-residual with stream progress
    score += 12.0 * (x * x) * (1.0 - progress);
    score -= 8.0 * x * progress;
    // penalize very tight fills slightly less when few bins fit the item
    let tight = (it / r).max(0.0);
    score += 6.0 * tight * tight * (1.0 - progress);
    // last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }
    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            let slack = ((pr as u32 - next_item_size) as f64) / cap;
            score -= 5.0 * (1.0 - slack * slack);
        } else {
            score += 4.0 * (nx / cap);
        }
    }
    // mean residual coupling: prefer bins near the mean residual
    score += 2.0 * ((r - mean_residual) / cap).abs();
    // new-bin candidate: make empty bins moderately attractive early, less late
    if bin_residual == bin_capacity {
        score -= 3.0 * (1.0 - progress) - 2.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes relative to the smallest item quantum are valuable.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Penalize dead space that no typical item can fill: leftover in (0,10)
    // is nearly unusable for small items; strongly penalize.
    if post > 0 && post < 10 {
        score += 40.0;
    }

    // Harmonic classes: post_residual divisible by small quanta (5, 10, 20)
    // is more reusable — reward modularity of the leftover.
    if post % 10 == 0 && post > 0 {
        score -= 12.0;
    } else if post % 5 == 0 && post > 0 {
        score -= 6.0;
    }

    // Perfect fit reward.
    if post == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual as u32 {
            score -= 60.0;
        } else if next_item_size <= post_residual as u32 {
            score -= 15.0;
            // Harmonic check: next item leaves a modular leftover too.
            let nxt_post = post - next_item_size as i64;
            if nxt_post % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how much dead space would be stranded.
            score += 0.1 * (post as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin has high raw residual; make it
    // attractive only when existing bins would strand bad leftovers.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decreasing as stream progresses
        // (amortization) and when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap as f64 + 20.0 - 10.0 * progress - 2.0 * (open_bins_count as f64).min(10.0);
        // If the item is huge relative to capacity, opening fresh is natural.
        if item_size * 4 >= bin_capacity {
            score -= 15.0;
        }
    }

    // Tie-break toward bins with residual near mean (keep bin load balanced),
    // but only mildly so harmonic classes above dominate.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are "dead space" — penalize them sharply.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable gap: nearly guaranteed waste.
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 10.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 80.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= 40.0 * (item_size as f64 / bin_capacity as f64);

    // Open-bins pressure: when many bins are open, prefer packing into
    // existing bins over spreading; when few bins are open, allow spread.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * 30.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open-bin pressure is high,
        // reward slightly when very few bins exist (early stream spread).
        score += 15.0 + pressure;
        if open_bins_count <= 1 {
            score -= 20.0;
        }
    } else {
        // Existing bin: reward it more when pressure is high.
        score -= pressure * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: mild bonus proportional to how well it uses the gap.
        score -= 20.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap: mild penalty for leaving it.
        score += 8.0;
    }

    // Mean-residual coupling: if this bin's post-residual deviates upward
    // from the mean, it fragments the space distribution — penalize.
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Late-stream tightening: as the stream progresses, be more frugal
    // with dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (chained perfect fit).
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs();
        if lookahead_gap == 0 {
            score -= 500.0;
        } else {
            // Penalize post_residuals that waste space relative to the next item.
            score += lookahead_gap as f64 * 0.6;
            // Bonus if the next item can still fit (keeps chain going).
            if post_residual >= next_item_size {
                score -= 80.0;
            }
        }
    }

    // Penalize tiny unusable dead space (< 10, minimum item size analog).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: make opening a fresh bin costly unless the current
    // fit is terrible. A fresh bin has large residual but wastes the item
    // ordering; penalize relative to mean residual of open bins.
    if bin_residual == bin_capacity {
        score += 150.0 + mean_residual * 0.5;
        // If many open bins exist, opening yet another is worse.
        score += open_bins_count as f64 * 5.0;
    } else {
        // Reward bins tighter than the mean residual (good fits).
        if (bin_residual as f64) < mean_residual {
            score -= 40.0;
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (waste-aware).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
        // Extra reward if next item fits perfectly after this placement.
        if post_residual as u32 == next_item_size {
            score -= 20.0;
        }
    }
    // Penalize if next item would fit better elsewhere: leaving a residual
    // just barely below next_item_size creates near-useless space.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) >= next_item_size - 5 {
        score += 12.0;
    }

    // Time-horizon scaling: early in the stream, be conservative with open bins;
    // later, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Compare residual against the mean residual of open bins:
    // placing into a bin with residual far below mean preserves large spaces.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.08 * rel;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Favor it when the fit into any open bin would be poor (large post_residual
    // relative to capacity) or when the item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Neutral-ish baseline: slight penalty so tight fits in open bins win,
        // but bonus when the item is large or open-bin fit is bad.
        score += 20.0;
        score -= 0.5 * item_size as f64;
        if post_residual as f64 > 0.4 * bin_capacity as f64 {
            score -= 15.0; // poor fit into open bins anyway; fresh bin is fine
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else {
        // Slight reward for keeping bin count low when many bins are open.
        score -= 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic dead-space penalty coupled with stream progress
    let mut score = pr * (1.0 + progress * norm_pr);

    // Smooth non-linear coupling: cubic interaction of normalized residual with progress
    score += norm_pr * norm_pr * norm_pr * cap * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Lookahead: penalize if next item cannot fit the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.5 + progress);
        } else {
            // reward leaving room for the next item, smoothly
            score -= (1.0 - (pr - nxt) / cap) * 5.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty proportional to number of open bins (discourage bin sprawl early)
    score += open_bins_count as f64 * (2.0 * (1.0 - progress));

    // Pull toward mean residual: avoid creating outliers of dead space
    score += (pr - mean_residual).abs() * 0.3;

    // New-bin candidate: make empty bins less attractive unless post_residual is large
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize residual that is too small to be useful (dead space) more strongly
    // than moderately small residual. Harmonic weighting: 1/(frac + eps).
    if pr > 0.0 * cap as f64 {
        let harmonic = 1.0 / (frac + 0.05);
        score += 0.3 * harmonic;
    }

    // Reward very tight fits (post_residual in lowest classes).
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Modulo-10 class of post_residual: residuals that are multiples of 10
    // (or of 5) are more likely reusable by future items.
    let cls = post_residual % 10;
    if cls == 0 {
        score -= 6.0;
    } else if cls == 5 {
        score -= 3.0;
    } else if cls >= 8 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 12.0;
            } else {
                score += (slack as f64) * 0.15;
            }
        } else {
            // next item cannot use this residual: mild penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // current fits are poor. Score for empty bin is cap; adjust by stream position.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress); // early on, opening bins is cheap
        // penalize opening new bins when many already open and mean residual is large
        score += 0.05 * open_bins_count as f64;
        score += 0.1 * (mean_residual - cap * 0.5).max(0.0);
    }

    // Prefer bins whose residual is far below mean residual (filling emptier bins first
    // keeps large residuals consolidated).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Small tie-break noise via integer division class to diversify selection.
    score += ((bin_residual / 7) % 3) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += 1000.0; // unusable gap
    }

    // Penalize small-but-unusable gaps harder than large gaps (non-linear dead-space cost).
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 20.0 {
            score += (20.0 - gap) * 3.0;
        }
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or bins are scarce.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win.
        score += 35.0;
        // Pressure from number of open bins: many open bins -> prefer filling them.
        score += open_bins_count as f64 * 2.0;
        // If this bin is the only fitting option, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 15.0;
        }
        // Late in stream, avoid spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Prefer bins whose residual is close to the item (tight fit relative to mean).
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += tightness * 0.1;
        // Reward placing into bins below mean residual (consolidating emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Lookahead synergy: if next item fits the post residual exactly, big reward.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), but dead space below
    // next_item_size is useless for the immediate future -> heavy penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            // Dead space w.r.t. lookahead item: penalize proportional to gap
            score += 3.0 * (nxt - post_residual as f64);
        } else {
            // Reward bins whose leftover exactly hosts the next item
            score -= 2.5 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }

        // Perfect two-item packing bonus: item + next fill bin exactly
        if item_size + next_item_size == bin_residual {
            score -= 10.0;
        }
    } else {
        // Last item: minimize post_residual aggressively
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual far above mean are
    // "wasted capacity" holders; prefer filling them when fit is decent.
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 0.5 * (res - mean_residual) / bin_capacity as f64;
    } else {
        score += 0.3 * (mean_residual - res) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
        if post_residual as f64 > 0.4 * bin_capacity as f64 {
            score += 3.0; // poor fit -> let new-bin candidate win
        }
    }

    // New empty bin candidate: make it unattractive unless it beats a bad fit.
    if bin_residual == bin_capacity {
        score += 6.0;
        // Early in the stream, opening bins is cheaper (room to consolidate later)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Mild preference to keep many small bins consolidated late in stream
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: post residuals that are too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward; else penalize
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            let waste = post_residual as f64;
            score += 0.35 * waste;
        }
        // If next item exactly fits post-residual, big bonus
        if post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // New-bin candidate handling: prefer new bin only when open bins fit poorly
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // Cheaper to open a new bin early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If many open bins with high mean residual, opening new bin is wasteful
        score += 0.15 * mean_residual;
        // If this bin is the only fitting bin, new bin is expensive
        if fitting_bins_count <= 1 {
            score += 90.0;
        }
        // Large items relative to mean residual: new bin may be reasonable
        if (item_size as f64) > mean_residual {
            score -= 20.0;
        }
    }

    // Mild penalty scaled by number of open bins to encourage consolidation
    score += 0.08 * open_bins_count as f64;

    // Small time-horizon modulation on residual weight: later in stream, pack tighter
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 8.0 * coupling * cap * 0.01;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that is too small to be useful later
    let dead = (pr as f64 - 10.0) / cap;
    if dead < 0.0 {
        score += 6.0 * (-dead) * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Slight preference to keep many open bins consolidated
    score += 0.05 * open_bins_count as f64 * progress;

    // Mean residual smoothing term
    score += 0.1 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // --- Dead-space detection (residual too small for any future item, min size 1..100) ---
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) {
        // residual can't host the lookahead item: penalize proportional to the gap
        let gap = if next_item_size > 0 { next_item_size - post_residual } else { 10 };
        score += gap as f64 * 0.8;
    }

    // --- Harmonic (decade) class logic on post_residual ---
    // Perfect decade residuals (0 mod 10) are maximally reusable; odd/prime-ish tails are worse.
    let class = post_residual % 10;
    match class {
        0 => score -= 10.0,
        1 | 3 | 7 | 9 => score += 4.0, // awkward tails
        5 => score -= 3.0,             // half-decade, decent
        _ => {}                        // 2,4,6,8 neutral
    }

    // Integer-division threshold: residual buckets of 20+ are highly flexible
    if post_residual / 20 >= 2 {
        score -= 6.0;
    } else if post_residual / 20 == 1 {
        score -= 2.0;
    }

    // --- Last-chance bonus: only bin that fits; avoid opening a new bin unnecessarily ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base new-bin score: leftover room after placing item.
        // Prefer opening a new bin for large items whose fit elsewhere leaves <10 dead space
        // (dead-space penalty above already pushes those open bins up; give new bin a fair shot).
        score += 8.0; // mild default reluctance to open new bins
        if item_size >= 60 {
            score -= 12.0; // big items pack cleanly into fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // lookahead could pair with this item in the fresh bin
            score -= 6.0;
        }
    }

    // --- Coupling with mean residual state ---
    // If open bins are on average roomy, prefer tightening the tightest fits less aggressively;
    // if bins are nearly full, reward minimal post_residual even more.
    let tightness = 1.0 + (mean_residual / bin_capacity as f64);
    score *= 0.85 + 0.3 * tightness;

    // Late-stream consolidation: favor filling existing bins as stream ends
    if progress > 0.8 {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (low post_residual).
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals that are too small for any
    // plausible future item (<= 10, the minimum size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Non-linear dead-space pressure: gaps in [1, 25] are hard to fill,
    // penalize quadratically relative to capacity.
    if post_residual < 25 {
        score += ((25 - post_residual) as f64).powi(2) * 0.15;
    }

    // Reward near-perfect fits (waste <= 5) with a strong bonus.
    if post_residual <= 5 {
        score -= 20.0;
    }

    // Perfect fit: overwhelming preference.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: dead space likely, penalize
        // proportionally to how stranded the gap is.
        score += (post_residual as f64) * 0.3;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over opening new ones; discourage spreading items thinly.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when the stream is early
    // or open bins have large mean residuals (space is abundant elsewhere).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let abundance = mean_residual / bin_capacity as f64;
        // Penalize new bins more as bins accumulate and stream progresses.
        score += 10.0 + (open_bins_count as f64) * 2.0 + progress * 20.0
                 - abundance * 10.0;
        // A new bin is fine for very large items that fit nowhere tightly.
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight tie-break: prefer bins with residuals below the mean
    // (consolidate small leftovers into fewer bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Reward tight fits strongly (waste ratio penalization).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how much of the post residual the next item uses
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 35.0 * use_ratio;
        } else {
            // next item won't fit here: penalize leaving mid-range residuals
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual of all open bins.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual * open_bins_count as f64;
        // Prefer new bin only when existing residuals are large and item is big.
        let pressure = (item_size as f64 / bin_capacity as f64) * mean_residual;
        score += 20.0 + 0.5 * avg_waste - pressure;
    } else {
        // Slight preference for using already-open bins over opening new ones.
        score -= 3.0;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, prioritize closing out bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * waste_ratio;
    score -= 10.0 * progress * fill;

    // Coupling: bins whose residual deviates from the mean residual are less attractive
    // unless the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 - fill);

    // Penalize leaving residuals smaller than the minimum plausible item (dead space),
    // scaled by how many other bins could still take items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr) + 60.0 * norm_pr * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tight fits matter more; late, keep residuals flexible.
    let tightness = 1.0 - norm_pr;
    score += 40.0 * progress * tightness * tightness * pr / cap;
    score -= 30.0 * (1.0 - progress) * norm_pr * (1.0 - norm_pr);

    // Lookahead: reward residual that can still fit the next item (smoothly)
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let slack = pr - next_item_size as f64;
        score += fits_next * (-25.0 - 0.3 * slack);
        score += (1.0 - fits_next) * (10.0 + 0.2 * next_item_size as f64 * (0.5 + progress));
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0 + 20.0 * (1.0 - progress);
    }

    // Mean residual context: placing into a bin far from the mean residual
    // creates fragmentation; penalize deviation smoothly.
    let dev = (pr - mean_residual).abs() / cap;
    score += 15.0 * dev * dev;

    // Slight preference for fuller bins among many open bins
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: only attractive when no good fits exist
    if bin_residual == bin_capacity {
        score = pr + 55.0 + 40.0 * (1.0 - progress) - 10.0 * (fitting_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 1 { score += 30.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: partition into capacity fractions (k/8 of capacity)
    let cap = bin_capacity as f64;
    let eighth = cap / 8.0;
    let post_f = post_residual as f64;
    let class = (post_f / eighth).floor() as i32; // 0..=8

    // Reward tight fits: lower class = tighter fit
    let class_bonus = match class {
        0 => -60.0,                       // near-perfect fit
        1 => -40.0,
        2 => -25.0,
        3 => -12.0,
        4 => 0.0,                         // half-full: neutral
        5 => 8.0,
        6 => 16.0,
        7 => 24.0,
        _ => 35.0,                        // bin stays nearly empty after placement
    };
    score += class_bonus;

    // Modulo arithmetic on post_residual: divisible residuals are "harmonic" with common item sizes
    let pr = post_residual;
    if pr > 0 {
        let harmonic = if pr % 10 == 0 {
            -18.0
        } else if pr % 5 == 0 {
            -9.0
        } else if pr % 20 == 0 {
            -22.0
        } else {
            0.0
        };
        score += harmonic;
    }

    // Lookahead: if next item fits exactly in post residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0;
        } else if next_item_size < pr && (pr - next_item_size) <= 10 {
            score -= 35.0;
        } else if next_item_size > pr {
            score += 10.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bin would leave large dead space
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // early stream: prefer opening bins; late: consolidate
        let new_bin_penalty = 45.0 + 40.0 * progress;
        score += new_bin_penalty;
        // opening a new bin is attractive if item is large and leaves a useful residual
        if item_size >= 50 && item_size % 10 == 0 {
            score -= 25.0;
        }
    }

    // Coupling with mean residual: placing into a bin far below mean residual is wasteful
    let dev = post_f - mean_residual;
    score += 0.15 * dev;

    // Integer division threshold: bins whose residual after placement is below capacity/4 are prime
    if post_f < cap / 4.0 {
        score -= 10.0;
    }

    // Mild consolidation pressure with many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1) are pure waste; residuals below the next item's
    // size are even worse (can't serve lookahead).
    if post_residual < next_item_size && next_item_size > 0 {
        score += 60.0 + (next_item_size - post_residual) as f64 * 1.5;
    }
    if post_residual < item_size {
        // gap can't take a same-size item again
        score += 20.0;
    }

    // Nonlinear penalty: small nonzero residuals are the worst dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 80.0 - (post_residual as f64) * 4.0;
    } else if post_residual <= 25 {
        score += 25.0 - (post_residual as f64) * 0.5;
    }

    // Reward using nearly-full bins (tight packing pressure).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * fill * 30.0;

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    score += open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when nothing fits well
        // or this is a last-resort situation.
        if fitting_bins_count == 0 {
            score -= 500.0;
        } else {
            score += 150.0 + open_bins_count as f64 * 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * fill;

    // Mean-residual coupling: if this bin is below-average residual,
    // it's relatively full -> favor it.
    score -= (mean_residual - post_residual as f64) * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post-residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Slacker: leftover can still host next item; reward closeness to exact match.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize unusable dead space,
            // worse when the dead space is small (nearly-fit but wasted).
            let dead = post_residual as f64;
            score += 20.0 * (1.0 - dead / bin_capacity as f64);
        }

        // Bonus if after placing next item too, residual becomes tiny (tight 2-step packing).
        let two_step = post_residual as i64 - next_item_size as i64;
        if two_step >= 0 && two_step <= 5 {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual is already small relative to the mean (fill tight bins first).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;
    score -= (bin_residual as f64 - mean_residual).max(0.0) * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are all poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && post_residual as i64 - next_item_size as i64 == 0 {
            score -= 70.0; // fresh bin perfectly set up for the lookahead item
        }
    }

    // Early in the stream, allow more bins; late, squeeze hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual (subtract), but punish exact-zero leftovers only mildly.
    let tightness = 1.0 - (post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Lookahead: if next item fits into post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // scaled by how much would remain after chaining
            let chain_left = post_residual - next_item_size;
            score -= 25.0 * (1.0 - (chain_left as f64) / bin_capacity as f64);
        } else {
            // next item cannot chain here; penalize wasted residual it could have used elsewhere
            score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Dead-space penalty: residual that is too small for typical items (below min size 1, but
    // practically below half the mean residual band) is likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins harder.
    let pressure = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * 10.0);
    score -= 6.0 * pressure.min(2.0);

    // Time horizon: late in the stream, consolidate aggressively (favor existing bins over new).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 25.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mild preference for bins already below-average residual (denser bins first).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fill = 1.0 - pr / cap;

    // Smooth non-linear coupling: reward high fill quadratically, modulated by stream progress
    score -= (1.0 + 2.0 * progress) * fill * fill * 12.0;

    // Cubic dead-space penalty for small residuals
    let dead = (pr / cap).powi(3);
    score += dead * 20.0;

    // Lookahead: reward if next item fits post-residual (smooth ramp)
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_q = next_item_size as f64 / pr.max(1.0);
        score -= 6.0 * fit_q * (1.0 - fit_q);
    } else if next_item_size > post_residual {
        score += 3.0;
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize opening new bins unless residual is large
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress) - 0.5 * open_bins_count as f64;
    } else {
        // Prefer bins below mean residual (tighter bins first)
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable" classes
    // (multiples of common small item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are divisible into useful chunks (mod arithmetic)
        let harmony = if pr % 10 == 0 {
            8.0
        } else if pr % 5 == 0 {
            4.0
        } else if pr % 20 == 0 {
            6.0
        } else if pr % 25 == 0 {
            5.0
        } else {
            0.0
        };
        score -= harmony;

        // Penalize small dead-space: residual below the minimum item size (1..10 band)
        if pr < 10 {
            score += 15.0;
        } else if pr < 20 {
            score += 6.0;
        }

        // Integer-division threshold coupling: residual / 10 class
        let class = pr / 10;
        score -= (class as f64) * 0.5;
    } else {
        // Perfect fill: strong reward
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // Harmonic bonus depending on resulting slack class
            if slack % 10 == 0 {
                score -= 10.0;
            } else if slack < 10 {
                score += 8.0; // creates dead space for next item
            } else {
                score -= (slack as f64) * 0.15;
            }
        } else {
            // next item cannot fit here; slight penalty for wasting the fit
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make it moderately attractive only when
    // existing bins would create bad fits, or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base handicap so open bins are usually preferred
        score += 12.0;
        // But if item leaves a very poor residual in any open bin, new bin wins
        if pr < 10 && pr > 0 {
            score -= 10.0;
        }
        // Early in the stream with few bins, fresh bins are cheap
        if open_bins_count < 3 && progress < 0.3 {
            score -= 8.0;
        }
        // If mean residual across open bins is small, opening fresh is better
        if mean_residual < item_size as f64 {
            score -= 6.0;
        }
    } else {
        // Prefer tighter existing bins: reward small post_residual non-linearly
        score += (mean_residual - post_residual as f64).abs() * 0.05;
        // Congestion: many open bins -> prefer filling existing ones
        if open_bins_count > 6 {
            score -= (open_bins_count as f64).min(20.0) * 0.3;
        }
    }

    // Fraction-of-capacity coupling: bins with residual near capacity fractions
    let frac = bin_residual as f64 / cap;
    if (frac - 0.5).abs() < 0.05 {
        score -= 2.0; // half-full bins are versatile
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible item
    // (<= 10 units) are nearly worthless -> heavy penalty pushing them onto the score.
    if post_residual < 10 {
        // Unusable sliver: dead space forever. Penalize quadratically.
        score += (10.0 - post_residual as f64) * 40.0;
    } else if post_residual < 25 {
        // Small gap: only usable by tiny items; moderate penalty scaled by stream position.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (25.0 - post_residual as f64) * (6.0 + 14.0 * progress);
    }

    // Reward tight fits (small but usable post_residual is good if >= 10).
    if post_residual >= 10 && post_residual <= 20 {
        score -= 18.0;
    } else if post_residual > 20 && post_residual <= 35 {
        score -= 8.0;
    }

    // Perfect fill: zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score -= 20.0; // still better to dump here than open new bin for sliver
        }
    }

    // Open-bins pressure: with many open bins, consolidate into existing bins;
    // with few open bins, allow opening new bins for bad fits.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 5.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else if slack < 10 {
            score -= 12.0;
        }
    }
    // If next item is large and this placement leaves a gap it can't use,
    // slightly penalize creating that trap.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 30 {
        score += 6.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins) to keep a pool of large residuals available.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // New-bin candidate: neutral baseline; make it attractive only when the
    // fit into this bin would create heavy dead space.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: post_residual = capacity - item_size.
        // If existing bins would leave unusable slivers, the penalties above
        // already push them above this baseline; otherwise keep new bin costly.
        score += 30.0 - 10.0 * (open_bins_count as f64).ln().max(0.0);
        // Early in the stream, a fresh bin is cheaper to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact or near-exact matches of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize small dead space more
            score += 5.0 + gap * 0.05;
        }
    }

    // Penalize leaving residual that no future item likely fills (dead space).
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    if post_residual < 10 {
        score -= 30.0 * (1.0 - residual_frac); // near-perfect fill bonus
    } else {
        score += residual_frac * 8.0;
    }

    // Compare against mean residual: prefer using bins with above-average residual.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor filling it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but keep it competitive when post_residual is large (fresh bin has lots of room).
    if bin_residual == bin_capacity {
        score += 12.0;
        // If current item is large relative to capacity, fresh bin more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    }

    // Slight preference to close out bins with small residuals (fewer open bins).
    score += (open_bins_count as f64).ln().max(0.0) * residual_frac * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space quadratically, but only when it's truly unusable
    // for typical items (small residuals attract future small items though).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 6.0 * dead * dead;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 7.0;
        } else {
            // Penalize creating residual that is smaller than the next item
            // (wasted space unless perfectly consumed later).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.06 * gap;
        }
    } else {
        // Last item: pure tight fit, no future to plan for.
        score -= 4.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item is large relative to capacity or open bins are few and
    // already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // Penalize new bins early / when open bins still have room on average;
        // reward when bins are nearly full or item is big.
        score += 14.0
            - 20.0 * (item_size as f64 / bin_capacity as f64)
            - 10.0 * avg_fill
            - 6.0 * progress;
        // If no open bin fits at all, the new bin must look attractive.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate: many open bins with high mean residual
    // means fragmentation; prefer filling existing bins.
    let fragmentation = mean_residual / bin_capacity as f64
        * (open_bins_count as f64).ln1p();
    score += 1.5 * fragmentation;

    // Small global progress term: later in the stream, waste matters more
    // since remaining opportunities to fix it shrink.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr) + 18.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly later in stream
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize wasted residual that exceeds likely next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.2 + progress);
        } else {
            score -= 0.25 * (pr - nxt).min(cap) * (1.0 - progress);
        }
    } else {
        score += 4.0 * norm_pr;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Coupling with mean residual: prefer bins below mean residual (denser bins)
    score += 0.15 * (mean_residual - pr);

    // New-bin candidate: penalize so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 22.0 + 18.0 * progress + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward "clean" residuals divisible by common size classes.
    let pr = post_residual;
    if pr > 0 {
        // Harmonic bonus: residual divisible by small class sizes (10/20/25/50) is more reusable.
        let mut harmony = 0.0;
        if pr % 50 == 0 { harmony += 6.0; }
        if pr % 25 == 0 { harmony += 3.0; }
        if pr % 20 == 0 { harmony += 2.0; }
        if pr % 10 == 0 { harmony += 1.5; }
        score -= harmony * (pr as f64 / cap);

        // Penalize awkward residuals: small prime-like leftovers (1..9) are dead space.
        if pr < 10 {
            score += (10.0 - pr as f64) * 2.0;
        }
        // Mid-band residual that fits neither next item nor common classes.
        if next_item_size > 0 && pr < next_item_size {
            score += (next_item_size - pr) as f64 * 0.5;
        } else if next_item_size > 0 {
            // Reward exact-fit chain: residual matches next item class via modulo.
            if pr % next_item_size == 0 {
                score -= 4.0;
            }
        }
    } else {
        // Perfect fill — strongly favored.
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But early in the stream with few bins, new bins are cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 6.0;
        if open_bins_count == 0 { score -= 20.0; }
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Fractional capacity thresholds: bins with residual in upper half are flexible.
    let frac = post_residual as f64 / cap;
    if frac > 0.5 { score -= 2.0 * frac; }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.8 { score -= 5.0 * fill; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 * (min_useful - post_residual) as f64;
    }
    // Penalize mid-range gaps that are unlikely to fit future items well.
    if post_residual >= min_useful && post_residual < 30 {
        score += 6.0 * (30 - post_residual) as f64;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Mean-residual coupling: prefer bins near the mean residual (balance).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference to fill older bins as stream progresses.
    score += 0.5 * (step_index as f64 / (total_items.max(1) as f64)) * post_residual as f64 / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already in score.

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item chain: fill bin completely next step
        } else if post_residual > next_item_size {
            // next item fits too; reward closeness of the resulting double-fill
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item does NOT fit leftover: penalize dead space proportionally
            let dead = (next_item_size - post_residual) as f64;
            score += 0.25 * dead;
        }
    }

    // Penalize residuals that are too small to ever fit the minimum item (dead space).
    if post_residual < 1 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with below-mean residual (pack fuller bins first, keep spread bins for odd items).
    if bin_residual != bin_capacity {
        score -= 0.5 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // Mild penalty so we only pick new bin when open bins are truly bad.
        score += 30.0;
        // If the item is large relative to typical residual, opening fresh is more attractive.
        if next_item_size > 0 && (post_residual as f64) < 0.5 * next_item_size as f64 {
            score -= 35.0;
        }
        // Late in the stream, avoid spawning bins for small leftovers.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Slight preference to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space (small but nonzero post_residual).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead (k=2): reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: bin becomes exactly full
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover: penalize proportionally to waste
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // residuals are large (poor fits) or few bins exist early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = mean_residual / bin_capacity as f64;
        // Cost of a fresh bin grows with progress and shrinks with global waste.
        score = 55.0 + 70.0 * progress - 45.0 * waste;
        if open_bins_count == 0 {
            score = -100.0; // must open the very first bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            // If next item is bigger, a fresh bin keeps flexibility for it.
            score -= 20.0;
        }
    } else {
        // Mild penalty for spreading across many open bins when residuals are small.
        let avg_small = mean_residual < (item_size as f64) * 1.5;
        if avg_small {
            score += 5.0;
        }
    }

    // Slight preference for filling larger-residual bins to consolidate space.
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear scaling
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late in the stream, penalize dead space more strongly
    let progress_coupling = 1.0 + 3.0 * progress * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Reward filling a bin nearly completely (post_residual near 0), smoothly
    let fill_bonus = (1.0 - norm_pr).powi(3);
    score -= 4.0 * fill_bonus;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Penalize bins with residuals far from the mean (fragmentation avoidance)
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let fit_quality = 1.0 - (pr - ns) / cap;
            score -= 3.0 * fit_quality * fit_quality;
        } else {
            // post_residual cannot host next item: mild penalty, stronger late
            score += 0.5 + 1.5 * progress;
        }
    }

    // Prefer consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make it attractive only when existing fits are poor
    if bin_residual == bin_capacity {
        score = 8.0 + 6.0 * progress - 2.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division tiers.
    let pr = post_residual;
    let residue = pr % 10;
    let tier = pr / 10; // 0..10 integer division tier

    // Penalize small awkward residues (dead space that rarely fits future items).
    score += match residue {
        0 => -8.0,          // perfect fill class
        1..=4 => 6.0,       // tiny slivers are near-useless
        5..=9 => -2.0,      // moderately reusable class
        _ => 0.0,
    };
    // Coupled tier penalty: mid tiers (residual 30-70) are the most reusable.
    score -= match tier {
        0 => 0.0,
        1..=2 => 4.0,
        3..=4 => -3.0,
        5..=7 => -5.0,
        _ => 0.0,
    } as f64;

    // Lookahead: does the next item fit exactly / well into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) == pr {
            score -= 25.0; // perfect follow-up fill
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            let gap_res = gap % 10;
            score -= 10.0 - (gap as f64) * 0.15;
            if gap_res == 0 { score -= 5.0; }
            if gap > 40 { score += 6.0; } // wasteful fit for next item
        } else {
            score += 4.0; // next item won't fit here
        }
        // Harmonic coupling: next item divisible by 10 pairs well with round residuals.
        if next_item_size % 10 == 0 && residue == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: make empty bins attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score = cap * 0.55 - crowding * cap * 0.45;
        if open_bins_count == 0 { score -= 30.0; }
        if fitting_bins_count == 0 { score -= 20.0; }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 12.0;
    }

    // Mild global regularization toward tight packing.
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // Gaps below the minimum item size (1..=3) are pure waste.
    if post_residual > 0 && post_residual < 4 {
        score += 40.0;
    }
    // Penalize gaps that cannot fit the known next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.5 * next_item_size as f64;
    }
    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Reward tight fits generally.
    score -= 0.6 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Dead-space penalty scaled by how much of the bin is left as small gap.
    let gap_ratio = post_residual as f64 / bin_capacity as f64;
    if gap_ratio > 0.0 && gap_ratio < 0.15 {
        score += 25.0 * (0.15 - gap_ratio) / 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones
    // (penalize opening new bins) by boosting the new-bin candidate score.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But allow new bin if existing residuals are large and fragmented.
        if mean_residual > 60.0 {
            score -= 8.0;
        }
    } else {
        // Mild bonus for placing into bins with residual near the item size.
        let tightness = (bin_residual - item_size) as f64;
        score += 0.1 * (tightness - post_residual as f64).abs();
    }

    // Late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let match_gap = (pr - nr).abs();
        // Perfect match: next item exactly fills this bin afterwards
        if pr == nr {
            score -= 60.0;
        } else if pr > nr {
            // next item can still fit here: reward by closeness
            score -= 40.0 * (1.0 - match_gap / 100.0);
        } else {
            // next item won't fit in the leftover: penalize dead space
            score += match_gap * 0.5;
        }
        // Bonus if after two placements bin is nearly full
        if pr <= nr && (pr - nr).abs() <= 5.0 {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize leftover
        score += 10.0;
    }

    // Compare against mean residual across open bins
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        // Filling a bin below mean residual means we're consolidating waste
        if pr < mean_residual {
            score -= (mean_residual - pr) * 0.3;
        } else {
            score += (pr - mean_residual) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        // A fresh bin starts with large residual; make it unattractive unless
        // this is a big item that fits poorly elsewhere
        let base_penalty = 55.0;
        // If item is large relative to capacity, opening new bin is more acceptable
        let size_relief = (item_size as f64 / bin_capacity as f64) * 30.0;
        score += base_penalty - size_relief;
        // Early in the stream, opening bins is cheaper (more items to come)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Mild penalty for leaving very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight preference to fill bins when many are open
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on leftover space
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space that next item cannot use: mild penalty
        score += 0.10 * (next_item_size as f64 - pr).max(0.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer new bin only when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = bin_capacity as f64 * 0.85 + crowd * 2.0 - progress * 10.0;
        // discourage new bin if a fitting bin exists that is fairly tight
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 1.8 {
            score += 35.0;
        }
    }

    // Prefer bins with residual close to item size (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * gap;

    // Late in stream: consolidate into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score -= 6.0 * progress * (mean_residual / bin_capacity as f64);
    }

    // Penalize very large leftovers that become dead space
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // awkward sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post-residual, with a non-linear convexity term
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate loose fits; late, demand tight packing
    let prog_coupling = (0.5 - progress) * 30.0 * norm_pr * (1.0 - norm_pr);
    score += prog_coupling;

    // Reward filling bins tightly: bonus for small normalized residual
    let tightness = (1.0 - norm_pr) * (1.0 - norm_pr) * 25.0;
    score -= tightness;

    // Mean residual interaction: prefer bins near the mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev * (0.3 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 * (1.0 - progress + 0.2);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_bonus = (1.0 - diff / cap).max(0.0);
        score -= 45.0 * fit_bonus * fit_bonus;
        // Penalize leaving residual that neither fits next item nor is tiny
        if next_item_size as f64 > pr {
            score += 10.0 * norm_pr * (1.0 - progress);
        }
    }

    // New-bin candidate handling: make empty bin attractive only when current
    // fits are poor (large post_residual relative to capacity)
    if bin_residual == bin_capacity {
        let threshold = 0.35 + 0.3 * progress;
        score = pr + cap * (0.5 + threshold) - 20.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    // Mild congestion effect: many open bins -> favor consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (0..10, 20..30, etc.) are more likely to be
    // completed by future items, so reward low-dead-space classes.
    let class = post_residual / 10; // integer division threshold class
    let class_bonus = match class {
        0 => 25.0,                 // near-perfect fit
        1 => 15.0,                 // small usable gap
        2 => 8.0,                  // medium gap
        3 => 3.0,                  // awkward gap
        4 => 0.0,
        5 => 2.0,
        6 => 6.0,
        7 => 10.0,
        8 => 14.0,
        _ => 18.0,                 // near-empty bin, wasteful placement
    };
    score -= class_bonus;

    // Modulo coupling: if next item exactly divides the post residual,
    // this placement sets up a perfect future fit.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual % next_item_size == 0 {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // next item cannot use this residual at all -> dead space likely
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * (item_size as f64);
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // unless this bin is nearly full and the new bin would stay flexible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = (open_bins_count as f64) * 0.5;
        score += 30.0 + congestion - 10.0 * progress;
        // If residual capacity of the system is low, opening a bin is fine.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    }

    // Prefer packing into bins with below-mean residual (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Fractional capacity tiebreak: exact fills are gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // Gap is "dead" if no plausible future item (min size ~1..20) can use it well.
    if post_residual > 0 {
        let dead_threshold = 12.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 4.0;
        }
        // Non-linear penalty: quadratic growth for large wasted residuals.
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to item size.
    score -= (item_size as f64) / (bin_residual as f64).max(1.0) * 10.0;

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but reward using existing bins when many are open (avoid bin proliferation).
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 0.5;
    } else {
        // New-bin candidate: penalize unless current fit is terrible or last chance.
        score += 25.0;
        // If this bin is the only fitting bin, opening a new bin is bad.
        if fitting_bins_count <= 1 {
            score += 60.0;
        }
        // Late in stream, prefer filling existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item would exactly fit the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item can't fit in post_residual anyway, dead space here is less costly
    // only if post_residual is small; otherwise slight penalty.
    if next_item_size > post_residual && post_residual > 0 {
        score += post_residual as f64 * 0.3;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward if next item fits into post_residual exactly/well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 25.0 - (next_waste as f64) * 0.5;
        } else {
            // next item won't fit here; penalize leaving large unusable-ish gap
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.3;
        }
        // perfect chaining bonus
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare residual to mean: favor bins with below-mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.4;

    // Penalize opening new bins when open bins exist and fit well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 35.0 + (open_bins_count as f64) * 2.0;
        // but allow new bin if item is huge relative to mean residual (poor fits elsewhere)
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 20.0;
        }
    }

    // Early stream: be slightly conservative about bin sprawl
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: fractional residual (0 = perfect fit, 1 = loose)
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 40.0;

    // Perfect fit is extremely attractive
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits the post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // extra reward when the next item nearly fills the remaining space
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // penalize leaving a residual just barely too small for the next item
            if post_residual > 0 && post_residual < next_item_size {
                score += 10.0;
            }
        }
    }

    // Global state: when many bins are open with high mean residual,
    // prefer filling existing bins over opening new ones
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.3;

    // New-bin candidate handling: an empty bin should only win when the fit
    // is poor or no open bin fits well
    if bin_residual == bin_capacity {
        score += 25.0;
        if open_bins_count > 0 {
            // opening new bins is worse late in the stream
            let progress = step_index as f64 / (total_items as f64).max(1.0);
            score += 20.0 * progress;
        }
    }

    // Slight preference for bins with smaller current residual (denser bins)
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), with smooth non-linear shaping.
    let mut score = pr as f64;

    // Smooth polynomial coupling: penalize mid-range residuals more than extremes.
    let quad = norm_pr * (1.0 - norm_pr);
    score += 12.0 * quad * (1.0 - progress);

    // Reward near-perfect fits smoothly (Gaussian-like bump around pr == 0).
    score -= 30.0 * (-pr * pr / 40.0).exp();

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_bonus = (-gap * gap / 60.0).exp();
        score -= 25.0 * fit_bonus * (1.0 - 0.5 * progress);
        // Penalize if post_residual can't fit next item (dead space risk), scaled by progress.
        if (next_item_size as f64) > pr {
            score += 8.0 * (pr / cap) * (0.5 + progress);
        }
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - 0.3 * progress);
    }

    // New-bin candidate handling: penalize opening new bins mildly when open bins fit well,
    // but allow it when open bins are crowded (few fitting bins, high mean residual usage).
    if bin_residual == bin_capacity {
        let crowding = if fitting_bins_count > 0 { 1.0 / (1.0 + fitting_bins_count as f64) } else { 1.0 };
        let spread = (mean_residual - cap * 0.5).abs() / cap;
        score = cap * (0.9 + 0.3 * progress) - 15.0 * crowding - 10.0 * spread;
    }

    // Smooth open-bin pressure: more open bins -> slight preference for filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - norm_pr);

    // Late-stream urgency: consolidate into existing bins as stream ends.
    score += 10.0 * progress * norm_pr * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize dead space in low harmonic classes (small unusable slivers)
    if post_residual > 0 {
        let class = (post_residual / 10).min(9); // integer division thresholds
        score += class as f64 * 0.5;
        // Slivers that nothing (min size 1..) can pair with later are costly
        if post_residual < 10 {
            score += 20.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap < 10 {
            score -= 10.0;
        } else {
            score -= 5.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // next item cannot use leftover: penalize proportionally to wasted class
        score += 3.0 * (1.0 - frac);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: keep it neutral-high unless open bins are fragmented
    if bin_residual == bin_capacity {
        score += 8.0;
        if open_bins_count > 0 {
            // open new bin only if mean residual is too small to be useful
            if mean_residual > item_size as f64 * 1.5 {
                score -= 10.0;
            }
        } else {
            score -= 100.0; // must open a bin when none exist
        }
    }

    // Prefer tighter bins (smaller residual before placement) mildly
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    // Progression coupling: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item are wasted space. Penalize them hard.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // pure dead space
        } else if post_residual <= 20 {
            score += 25.0; // nearly unusable gap
        } else if post_residual <= 30 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fit: strongly reward closing the bin
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Reward placing into below-average residual bins (keeps residuals uniform).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0;
        } else if slack < 25.0 {
            score -= 12.0;
        }
    }
    // If next item would be blocked by this placement, mild penalty.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 6.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 1
            || (fitting_bins_count == 1 && post_residual >= 10);
        if good_fit_exists {
            score += 45.0; // prefer existing bins
        } else {
            score -= 5.0; // allow opening a fresh bin
        }
        score += 1.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower score when item nearly fills the bin.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let match_val = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * match_val;
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            score -= 8.0; // next item still fits here
        } else {
            score += 10.0; // dead space for next item
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (pack fuller bins first), penalize bins far above mean.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize creating tiny unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // unless the fit is very poor (large post_residual makes base score win).
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if next item is large and this bin is fresh, slight bonus.
        if next_item_size > 50 {
            score -= 5.0;
        }
    }

    // Late in stream: be more conservative, prefer compacting existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to typical item scale.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill bonus
    }
    if post_residual >= 10 && post_residual < item_size.min(bin_capacity / 2) {
        score += 3.0; // awkward mid-sized gap
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // placing here leaves a gap that blocks the next item
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: only attractive when no open bin fits well
    // (i.e., this call has bin_residual == bin_capacity and item is large).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        // Prefer reusing open bins when mean residual is generous.
        if mean_residual > item_size as f64 * 1.3 {
            score += 40.0;
        }
        // Late in the stream, opening new bins wastes capacity; penalize more.
        score += 10.0 + 20.0 * progress + 2.0 * openness;
        // But if the item is huge (>= 60), a fresh bin is often the best home.
        if item_size >= 60 {
            score -= 25.0;
        }
    }

    // Mild preference for bins with residuals below average (consolidate waste).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Fragmentation guard: avoid leaving residuals in the "dead zone" 51..70
    // that few future items can use, unless the fit was very tight.
    if post_residual > 50 && post_residual < 70 && fit_ratio < 0.8 {
        score += 9.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr)) * (1.0 + 0.6 * progress);

    // Penalize large residual creation early, reward late (bins close out)
    score += 6.0 * norm_pr * norm_pr * (1.0 - progress) * cap;

    // Reward tight fits (small post residual) with smooth coupling
    score -= 8.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Lookahead: if next item fits into post-residual, strongly favor
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 10.0 * (pr - nxt) / cap;
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open new
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Coupling with mean residual: avoid scattering residual space
    score += 2.0 * (pr - mean_residual).abs() / cap;

    // Slight preference for filling existing bins as stream progresses
    score += 0.5 * open_bins_count as f64 * (0.3 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by quarter-capacity bands
    let q = (post_residual * 4 / bin_capacity.max(1)) as f64; // 0..3 integer division threshold
    score += q * 3.0;

    // Reward near-perfect fits: post_residual in small harmonic class (0..=5)
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Modulo coupling: residual divisible by small integers pairs well with future items
    if post_residual > 0 && (item_size % post_residual == 0) {
        score -= 8.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        // lookahead fits exactly into leftover
        if post_residual == next_item_size {
            score -= 20.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover too small for lookahead: penalize proportional to waste
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Harmonic fraction of capacity used
    let fill = (bin_residual as f64) / cap;
    if fill > 0.75 {
        score -= 5.0; // prefer filling nearly-full bins
    } else if fill < 0.25 {
        score += 4.0; // discourage cracking open fresh bins for small items
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current residuals are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        if mean_residual < item_size as f64 || (fitting_bins_count <= 1 && post_residual < 20) {
            score -= 30.0;
        } else {
            score += 20.0 + fragmentation * 0.3 + open_bins_count as f64 * 0.5;
        }
    }

    // Late-stream consolidation: tighten tolerance as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..100
    // interface, but conservatively treat gaps < 12 as near-dead) are heavily penalized
    // only if they are NOT a perfect fit; a residual of 0 is ideal.
    if post_residual == 0 {
        score -= 50.0; // perfect fill: strongly reward
    } else if post_residual < 12 {
        // unusable sliver of dead space -> big penalty on top of its small value
        score += (12 - post_residual) as f64 * 6.0;
    } else if post_residual < 25 {
        // moderately awkward gap
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward bins whose residual is exactly consumed well relative to item size (tight fit).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 8.0;

    // Lookahead coupling: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here: this bin's leftover becomes dead space
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is excellent.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean-residual alignment: prefer bins close to the mean residual (keeps bin profile uniform).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate handling: an empty bin has residual == capacity. It should win
    // only when the current fit is poor (large post residual / awkward gap).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        // becomes more attractive late in the stream when many bins are open and fragmented
        score -= open_bins_count as f64 * 0.5;
        // less attractive early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // next item could also fit here; mild penalty for wasting that chance
            score -= 50.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // dead space below next item size: penalize small unusable leftovers
            score += 30.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when residuals across open bins are small.
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        score -= 80.0 * avg_tightness;
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 60.0; // nothing open can hold the future well
        }
    }

    // Late-stream consolidation: prefer reusing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual is already the base).
    let perfect = post_residual as f64 / bin_capacity as f64;
    score += perfect * perfect * 20.0;

    // Penalize leaving a residual that is too small to ever be useful again
    // (dead space below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.25 * next_item_size as f64;
        } else {
            // Wasted lookahead potential: penalize proportionally to the gap.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless existing fits are truly bad.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Early in the stream, opening bins is cheaper (build a pool of bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // If open bins are already fragmented (high mean residual), a new bin is fine.
        if mean_residual < 30.0 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate into already-open bins when many are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins tighter than average (best-fit style).
    score += 2.0 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening: demand tighter fits as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, but with diminishing (quadratic) dead-space cost
    let mut score = pr - 0.5 * pr * norm_pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more; early on, waste is cheaper.
    let coupling = pr * (progress * progress) * 0.6;
    score += coupling;

    // Reward near-perfect fits smoothly via a bell-shaped term around pr==0
    let tightness = (-norm_pr * norm_pr * 8.0).exp();
    score -= 25.0 * tightness;

    // Last-chance bin: strongly favor using it (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        if gap >= 0.0 {
            score -= 12.0 * (-((pr - next_item_size as f64).abs() / 15.0).powi(2));
        } else {
            score += 6.0 * (-gap) * (1.0 + progress);
        }
    }

    // Prefer denser bins relative to the mean residual
    score -= 0.3 * (mean_residual - pr);

    // Mild penalty for many open bins early (encourage consolidation)
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when residuals are tight overall
    if bin_residual == bin_capacity {
        let mean_tight = (mean_residual / cap).max(0.0);
        score = 40.0 + 60.0 * mean_tight + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter;
    match class {
        0 => score -= 12.0,           // tiny residual: near-perfect fit
        1 => score -= 4.0,            // small residual
        2 => score += 0.0,
        _ => score += 6.0,            // large leftover: wasteful
    }

    // Reward if next item fits exactly into post_residual (perfect chaining)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next fits: penalize proportional leftover after next placement
            let chain_left = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize large residuals
            score += (post_residual as f64 - bin_residual as f64 * 0.5).max(0.0) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins when open bins exist,
    // unless residual after placement would be tiny (fresh bin is fine)
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            if post_residual < item_size {
                score -= 5.0; // fresh bin with big usable space
            } else {
                score += 20.0 + 0.5 * open_bins_count as f64;
            }
        } else {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    // Integer division threshold: penalize residuals in "dead zone" (51..=74)
    if post_residual > bin_capacity / 2 && post_residual < 3 * bin_capacity / 4 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no plausible item can use
    // (below the minimum item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 1 {
        score += 1000.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Penalize gaps too small for the known next item (wasted for lookahead).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // Reward leaving a gap that exactly accommodates the next item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
        // Reward tight fits: fraction of bin consumed by this placement.
        score -= 0.8 * item_size as f64;
        // Penalize large leftover gaps that will likely become dead space,
        // but only mildly so the tightest fit still wins.
        score += 0.3 * (post_residual as f64).powf(1.4);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate (bin_residual == bin_capacity) gets penalized here.
    if bin_residual == bin_capacity {
        score += 40.0 + 8.0 * open_bins_count as f64;
        // But if no open bin fits well, allow new bin: reduce penalty when
        // fitting_bins_count is small.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    } else {
        // Slight bonus for consolidating into bins that are already fairly full.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    // Progress-based adaptation: later in the stream, be greedier about
    // filling existing bins (closing residual gaps) since fewer items remain
    // to use leftover space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * item_size as f64 / 100.0;

    // Mean residual coupling: prefer bins below the mean residual (emptier bins
    // absorb the item, keeping tight bins for tight fits) when gap is large.
    if post_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: item then next_item seal the bin
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Reward proportionally for small leftover after the next item too.
            score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
            // Penalize gaps that are too small to ever be useful (dead space).
            if gap > 0.0 && gap < 10.0 {
                score += 15.0;
            }
        } else {
            // Next item won't fit here; leftover becomes dead space unless tiny.
            if post_residual < 10 {
                score -= 10.0; // residual is sealed waste, acceptable
            } else {
                score += 0.15 * (post_residual as f64 - mean_residual).abs();
            }
        }
    }

    // Penalize creating large unusable residuals relative to mean residual.
    if post_residual as f64 > mean_residual + 20.0 {
        score += 0.3 * (post_residual as f64 - mean_residual - 20.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are quite full.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; subtract more when existing bins are congested.
        score = 55.0 - 0.4 * mean_residual;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big upcoming item: fresh bin is valuable
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight late-stream conservatism: favor filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let mut score = post * (1.0 + 0.6 * (post / cap));

    // Reward tight fits (small dead space after placement)
    score -= 35.0 * (1.0 - post / cap);

    // Lookahead: bonus if the next item can also fit in the post residual
    if next > 0.0 && next <= post {
        score -= 18.0 * (next / cap);
    } else if next > 0.0 && next > post && next > bin_residual as f64 {
        // next item won't fit anywhere useful; keep residual flexible
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize when this bin's residual is far above mean (fragmentation signal)
    let dev = post - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score += 0.05 * dev;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score = 30.0;
        // Large items justify fresh bins (they create big residuals for future items)
        score -= 0.45 * item;
        // If next item is large too, opening a bin is more attractive
        if next > 0.0 {
            score -= 0.2 * next;
        }
        // If no open bin fits (or this is the only option), opening is clearly right
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Early in stream: be more willing to open bins
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - t);
    }

    // Mild time-horizon scaling: later in stream, tighten up (less waste tolerated)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.08 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post-residual, with non-linear growth for awkward leftovers
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in the stream, tighten more aggressively
    let progress_coupling = 1.0 + 0.9 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: subtract when post_residual is small relative to item size
    let tightness = 1.0 - norm_pr;
    score -= 0.35 * item_size as f64 * tightness * tightness;

    // Lookahead: reward leaving room for the next item, penalize near-miss leftovers
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) as f64;
            score -= 0.5 * nxt * (1.0 - (slack / cap).min(1.0));
        } else {
            let miss = (nxt - pr) as f64;
            score += 0.4 * miss * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balance preservation)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild penalty for many open bins, encouraging consolidation
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when no good fit exists (large post_residual waste elsewhere)
    if bin_residual == bin_capacity {
        score = pr + 15.0 * (1.0 - progress) + 6.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits get strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    }

    // Harmonic partition of residual space into classes of 20.
    let class = post_residual / 20; // 0..=5
    score -= match class {
        0 => 50.0,
        1 => 20.0,
        2 => 0.0,
        3 => 10.0,
        4 => 25.0,
        _ => 40.0,
    };

    // Modulo-based dead-space penalty: residuals that few item sizes can use.
    let usable = (1..=80u32).filter(|&s| s <= post_residual).count() as f64;
    score += (80.0 - usable) * 1.5;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 2.0;
        } else {
            score += 15.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 400.0
            + mean_residual * 2.0
            - (fitting_bins_count as f64) * 50.0;
    }

    // Progress coupling: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.5 + progress * 0.5);

    // Mean residual alignment: prefer bins near the mean residual.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer existing bins over new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins accumulate.
        score += 15.0 + 6.0 * open_bins_count as f64;
        // But if current bin would leave a bad dead gap and next item fits better in fresh bin, allow it.
        if post_residual < 10 && next_item_size > post_residual {
            score -= 20.0;
        }
    } else {
        // Existing bins get a mild bonus scaled by open bins count.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Lookahead: if next item exactly fills the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Prefer bins below mean residual (fill emptier bins first to balance).
    let diff = mean_residual - bin_residual as f64;
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0;
        } else if diff <= 5 {
            score -= 25.0 - diff as f64 * 3.0;
        } else {
