        // If next item cannot fit anywhere else but fits here after placement, reward
        if post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 8.0;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 10.0;
    }

    // Last-chance bin: only bin able to fit the item -> strong reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins fit well (new-bin candidate detection)
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Early in stream, new bins are cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins with low residual relative to mean (tighter packing)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Reward high fill ratio
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is just above the item.
    let fit_slack = (bin_residual - item_size) as f64;
    score -= 30.0 * (-fit_slack / 10.0).exp();

    // Penalize leaving awkward mid-range dead space (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny sliver is fine (near-perfect fit)
    } else if post_residual >= 10 && post_residual < 30 {
        score += 12.0; // awkward dead zone
    }

    // Lookahead: reward if the next item fits in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
