            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when this
    // placement would leave a lot of dead space or few bins fit the item.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let pressure = 1.0 / (fitting_bins_count as f64 + 1.0);
        score = 40.0 + waste - 15.0 * pressure;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // fresh bin can host next item too
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    if open_bins_count > 2 {
        score += 0.05 * mean_residual * (open_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, be more conservative (favor keeping
    // residuals balanced); late in the stream, just close bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.1 * (bin_capacity as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
