    // Base: tight fits are good (low post_residual preferred).
    let mut score = pr;

    // Non-linear dead-space penalty: quadratic in normalized post-residual,
    // stronger late in the stream (smooth coupling with progress).
    let pr_norm = pr / cap;
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits superlinearly (small post_residual strongly favored).
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Exact-fit bonus (smooth, sharp via power term).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let fit_ratio = it / bin_residual as f64;
        score -= 60.0 * fit_ratio * fit_ratio * fit_ratio;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 25.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Next item won't fit: penalize residuals that are "almost" usable.
            let gap = (nx - pr) / cap;
            score += 20.0 * gap * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 * (1.0 - pr_norm);
    }

    // New-bin candidate handling: mildly penalize opening new bins when open
    // bins exist, but allow it early or when current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        let pressure = (open_bins_count as f64).ln() + 1.0;
        score += 30.0 + 25.0 * fragmentation * pressure - 20.0 * (1.0 - progress) * (it / cap);
    } else {
        // Slight preference for fuller bins among open ones.
        score += 10.0 * ((mean_residual - bin_residual as f64) / cap).max(0.0);
    }

    // Smooth stream-progress interaction: become more conservative (prefer
    // tighter packing) as the stream advances.
    score *= 1.0 + 0.3 * progress * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo capacity fractions.
    // Dead space in the "hardest to fill" classes gets penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as u32;
    let eighth = (bin_capacity / 8) as u32;

    // Penalize post_residuals that fall in awkward classes (small, unusable slivers)
    if post_residual > 0 && post_residual < eighth {
        score += 18.0; // tiny sliver = wasted capacity
    } else if post_residual >= eighth && post_residual < quarter {
        score += 7.0; // moderately awkward
    }

    // Reward exact / harmonic fits: post_residual divisible by common size classes
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if post_residual % 10 == 0 {
        score -= 10.0; // round residual, likely reusable
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Lookahead coupling: reward if next item fits exactly or well into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            if gap < eighth as f64 {
                score -= 12.0;
            } else {
                score -= gap * 0.05;
            }
        } else {
            // next item won't fit here; penalize more if residual is large (trap)
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // neutral base: slightly worse than a perfect fit, better than a bad one
        score = cap * 0.6;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // many open bins => discourage opening more
        score += open_bins_count as f64 * 0.5;
    }

    // Tie-break toward bins with residuals close to the current mean (keeps balance)
    score += (mean_residual - pr).abs() * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (<= 1) are pure waste; residuals that cannot fit the
    // lookahead item are semi-dead.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual < 1 {
        score += 500.0; // unusable dead space (defensive)
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap too small for the next item: penalize proportionally.
        score += 30.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.3;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure and by how
        // badly existing bins would fit (large post_residual elsewhere).
        score += 120.0 + bin_pressure * 2.0;
        // If the best alternative leaves a large dead gap, new bin looks
        // relatively better; approximate via mean residual coupling.
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.4;
    } else {
        // Reward using bins with already-small residuals (tight packing).
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
        // Slight preference for bins below mean residual (more packed).
        score -= (mean_residual - bin_residual as f64).max(0.0) * 0.2;
    }

    // Non-linear penalty on medium-dead gaps (10..30) which rarely get used.
    if post_residual >= 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match between
    // post_residual and the next item's size (perfect chain fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        let lookahead_bonus = if diff == 0 {
            -60.0 // perfect two-step match: place here almost surely
        } else if diff <= 10 {
            -25.0 + diff as f64 * 1.5
        } else {
            -(60.0 / (diff as f64)).min(10.0)
        };
        score += lookahead_bonus;

        // Penalize creating residual too small for next item (dead space).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // Last item: just minimize waste as usual.
        score -= 5.0;
    }

    // Tightness reward: filling the bin nearly full is good.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Compare against mean residual: bins with residual close to item size
    // are precious; using them is fine, wasting them is not.
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += mean_gap * 0.05;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when all open residuals
    // would leave large unusable fragments, or stream is early with few bins.
    if bin_residual == bin_capacity {
        let waste_now = post_residual as f64;
        let open_pressure = open_bins_count as f64;
        // New bin default score is its residual (100); make it competitive
        // only when existing bins would waste heavily.
        score = 85.0
            + waste_now * 0.3
            - open_pressure * 2.0
            + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 40.0; // next item needs a fresh bin anyway
        }
    }

    // Mild preference to keep many small residuals consolidated.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny dead space is very bad
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    if post_residual == 0 {
        score -= 50.0; // perfect fit is ideal
    } else {
        let frac = post_residual as f64 / bin_capacity as f64;
        score += frac * frac * 40.0; // penalize large dead space quadratically
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty if we waste lots of space
            score += (post_residual as f64 - next_item_size as f64).abs().min(20.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // early in stream, opening bins is cheap; later, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if many open bins already, discourage more
        score += open_bins_count as f64 * 2.0;
        // if mean residual is large, open bins have room to help
        if mean_residual > item_size as f64 {
            score -= 10.0;
        }
    }

    // Mild preference for bins with residual close to mean (balance spreading).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    // Prefer fuller bins (smaller residual) slightly.
    score += (bin_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly damped as stream progresses (tighten later).
    let mut score = pr * (1.0 - 0.25 * progress);

    // Non-linear penalty for awkward dead space: residuals too small to be useful.
    let dead = (norm_pr * (1.0 - norm_pr)).sin().powi(2); // peaks mid-range, low near 0
    score -= 12.0 * dead * norm_pr;

    // Quadratic coupling: large post_residual early is fine, penalize late.
    score += 20.0 * norm_pr * norm_pr * progress;

    // Perfect fit reward (smooth, no hard threshold).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Lookahead: reward leaving space exactly matching next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let matchness = 1.0 - (pr - nx).abs() / cap;
        score -= 10.0 * matchness.max(0.0) * matchness.max(0.0);
        // Penalize blocking next item entirely.
        if pr < nx {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Prefer fuller bins when many bins are open.
    score -= 3.0 * (1.0 - norm_pr) * (open_bins_count as f64).ln().max(1.0);

    // Mean residual context: avoid bins far below mean fullness late in stream.
    let mean_norm = mean_residual / cap;
    score += 5.0 * (norm_pr - mean_norm).abs() * progress;

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * progress * (1.0 - fit_ratio.min(1.0));
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets (capacity fractions).
    let pr = post_residual as i64;
    let class = pr % 10;
    // Perfect-fit classes (post_residual in {0, 5, 10, ...} multiples of 10) are valuable.
    if class == 0 {
        score -= 18.0; // exact harmonic closure
    } else if class == 5 {
        score -= 6.0; // half-class still reusable by mid-size items
    } else {
        score += (10 - class) as f64 * 0.8; // penalize ragged dead space
    }

    // Fraction-of-capacity view of the remaining residual.
    let frac = post_residual as f64 / cap;
    if frac >= 0.5 {
        score -= 8.0; // bin still half-capable
    } else if frac < 0.1 && frac > 0.0 {
        score += 12.0; // near-dead sliver
    }

    // Lookahead coupling: does next_item_size land in a harmonic class of post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt <= pr {
            // next item fits exactly or leaves a multiple-of-10 residual
            let next_post = pr - nxt;
            if next_post % 10 == 0 {
                score -= 14.0;
            } else if next_post % 5 == 0 {
                score -= 5.0;
            }
            // integer-division threshold: next item uses >= half of residual
            if nxt * 2 >= pr {
                score -= 6.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 7.0 + (nxt - pr).min(20) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Stream progression: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0;

    // Prefer bins below mean residual (tighter packing) slightly.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: only attractive when no good harmonic fit exists.
    if bin_residual == bin_capacity {
        score = 55.0 - progress * 8.0;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (post_residual in (0, 10))
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize moderately small gaps too
    if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Reward very tight fits (small but zero-ish waste)
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance: if this is the only fitting bin, prefer using it
    // over opening a new bin (unless post_residual is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new bin is relatively cheap.
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 0.3;

    // New-bin candidate handling: an empty bin has post_residual == capacity - item.
    // Make the new-bin option attractive only when the current fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we only open when fits are bad
        score += 20.0;
        // Cheaper to open early in stream / when few bins open
        score -= open_pressure * 0.5;
        // Lookahead: if next item is small, new bin's large residual is useful
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 5.0;
        }
    }

    // Favor bins whose residual is close to mean (avoid fragmentation outliers)
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    // Lookahead coupling: if next item fits exactly in post_residual, reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    }
    // If next item is large and post_residual too small for it, mild penalty
    if next_item_size > post_residual && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits; penalize leftover after two placements
            let after_two = post_residual - next_item_size;
            score -= 100.0 - (after_two as f64) * 0.5;
        } else {
            // next item won't fit here; penalize large dead space
            score += post_residual as f64 * 0.3;
        }
    }

    // Compare against mean residual: bins tighter than mean are preferred targets
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if item is large relative to capacity
        score += 150.0 - (item_size as f64) * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Tight-fit preference: smaller post_residual relative to item is better
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Early stream: be slightly more conservative about dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic in wasted space
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Many fitting bins: penalize slightly to prefer scarce options
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize unless it enables a great future fit
    if bin_residual == bin_capacity {
        let mut nb = 25.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= item_size {
            let future_waste = bin_capacity - item_size - next_item_size;
            if future_waste <= 5 {
                nb -= 40.0; // perfect pair packing justifies new bin
            } else if future_waste > 30 {
                nb += 15.0; // poor pairing, keep filling open bins
            }
        }
        score += nb;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Global state coupling: prefer balanced residuals early, tight packing late
    let t = step_index as f64 / total_items.max(1) as f64;
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (1.0 - t) * 0.15 * dev;
    score += t * 0.1 * (open_bins_count as f64);

    // Prefer bins that are already fairly full
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly coupled with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0 * norm_pr);

    // Penalize large dead space quadratically, weighted by progress
    score += 60.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth exponential-ish term
    score -= 25.0 * (-pr / (0.25 * cap)).exp() * (1.0 - progress);

    // Lookahead coupling: reward if next item fits into post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > post_residual {
        score += 10.0 * progress;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening bins early, less so late
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
    }

    // Mild mean-residual alignment term
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" is the leftover space?
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class by modulo 10: leftovers divisible by 10 align with common item sizes.
    let post = post_residual;
    if post == 0 {
        score -= 60.0;
    } else {
        let m = post % 10;
        // Dead-space penalty grows when leftover is small but unusable.
        if post < 10 {
            score += 25.0; // tiny useless sliver
        } else {
            // Harmonic alignment: leftover divisible by 10 is more reusable.
            let alignment = if m == 0 { 0.0 } else { (10 - m) as f64 * 1.5 };
            score += alignment;
        }
    }

    // Integer-division thresholds: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Next item chains nicely: reward proportional to how tightly it fits.
            let slack = (post - next_item_size) as f64;
            score -= 20.0 + slack * 0.1;
            if slack == 0.0 {
                score -= 30.0; // perfect chain
            }
        } else {
            // Next item won't fit here: penalize proportionally to overshoot.
            let over = (next_item_size - post) as f64;
            score += over * 0.25;
        }
    }

    // Fractional capacity classes: reward filling large fractions of the bin.
    let fill_frac = (item_size as f64) / (bin_capacity as f64);
    score -= fill_frac * 15.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when open bins are crowded
    // or mean residual can't accommodate the item.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (step_index as f64 + 1.0).max(1.0);
        let mean_can_fit = mean_residual >= item_size as f64;
        if mean_can_fit || fitting_bins_count >= 1 {
            score += 80.0; // discourage new bin when existing bins suffice
        } else if crowd > 2.0 {
            score += 40.0;
        } else {
            score -= 5.0;
        }
    }

    // Mild exploration bias across stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to hold anything useful are heavily penalized.
    let min_useful = 10u32; // smallest conceivable item
    if post_residual < min_useful {
        // Perfect fit: zero dead space -> strong reward.
        score -= 60.0;
    } else if post_residual <= 20 {
        // Tiny unusable gap: strong penalty proportional to how "wasted" it is.
        score += 25.0 + (20.0 - post_residual as f64) * 2.0;
    } else if post_residual < 40 {
        // Moderately small gap: mild penalty, scaled by stream progress
        // (dead space matters more as the stream matures).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (40.0 - post_residual as f64) * (0.4 + 0.6 * progress);
    }

    // --- Tight fit reward ---
    // Reward bins whose residual is only slightly larger than the item.
    let slack = (bin_residual as f64 - item_size as f64).max(0.0);
    let tightness = 1.0 - slack / bin_capacity as f64;
    score -= 30.0 * tightness;

    // --- Last-chance pressure ---
    // If this is the only bin that fits, avoid opening a new bin unless
    // the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual >= 40 {
            score -= 10.0; // still leaves a large usable gap
        }
    } else if fitting_bins_count > 1 {
        // Encourage spreading across bins: prefer bins that keep more bins viable.
        score -= 2.0 * (fitting_bins_count as f64).min(5.0);
    }

    // --- Open-bins pressure ---
    // Many open bins: discourage opening new ones, encourage filling existing.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // --- Mean residual coupling ---
    // Prefer bins whose post-residual stays close to the fleet mean residual
    // (keeps the bin pool homogeneous and future-item compatible).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // --- Lookahead (k=2) ---
    if next_item_size > 0 {
        // Reward leaving a gap that can exactly host the next item.
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0; // next item nearly fills the remainder
        } else if next_item_size > post_residual {
            // Next item cannot use this bin's remainder; slight penalty if
            // remainder is small (dead space likely).
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // --- New-bin candidate handling ---
    // A brand-new empty bin is called with bin_residual == bin_capacity.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // Opening a new bin is worthwhile only when no open bin fits well:
        // penalize the empty bin by default, but reduce the penalty when
        // alternatives are scarce or the current fit is bad.
        let mut new_bin_score = 45.0 + bin_pressure * 5.0;
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // no alternative: new bin is mandatory
        } else if fitting_bins_count == 1 {
            // Only one candidate bin; if its post-residual would be dead space,
            // allow a new bin.
            if post_residual < 10 {
                new_bin_score -= 60.0;
            }
        }
        return new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize leaving a residual that is too small for the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * post_residual as f64;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early or residuals are all tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 200.0 + 150.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 120.0; // new bin useful for upcoming large item
        }
    }

    // Relative to mean residual: prefer bins with residual close to item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;
    score -= 0.2 * (mean_residual - post_residual as f64).abs();

    // Prefer filling bins that are already partially used when many bins are open.
    score += 0.1 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more strongly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that cannot fit any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits the post-residual exactly well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Time horizon: early in the stream, prefer keeping residuals flexible;
    // later, prefer consolidation into existing bins.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= t * 15.0 * (1.0 - fit_ratio);

    // Many open bins: penalize spreading, reward filling existing bins.
    score += 2.0 * open_bins_count as f64 * fit_ratio;

    // Compare against mean residual: bins below-mean residual are worth filling.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio > 0.5 && (fitting_bins_count == 0 || next_item_size > post_residual && next_item_size > 0);
        if poor_fit {
            score -= 12.0;
        } else {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, tolerate larger residuals (bins stay flexible);
    // late in the stream, penalize wasted space more aggressively.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let waste_weight = 0.5 + 1.5 * p2 + 1.0 * p3; // smooth ramp 0.5 -> 3.0
    let normalized_waste = (pr / cap) * (pr / cap); // quadratic in fill fraction
    score += waste_weight * normalized_waste * cap * 0.5;

    // Reward tight fits: post_residual near zero gets a strong bonus.
    let tightness = 1.0 - pr / cap;
    score -= 4.0 * tightness * tightness * tightness;

    // If the leftover space exactly accommodates the next item, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 3.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that cannot host the next item: penalize smoothly.
        let dead = 1.0 - post_residual as f64 / next_item_size.max(1) as f64;
        score += 2.0 * dead.abs().min(1.0) * (1.0 + p2);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // are open and mean residual is still usable.
    if bin_residual == bin_capacity {
        let mean_usable = (mean_residual / cap).clamp(0.0, 1.0);
        score += 6.0 + 2.0 * (open_bins_count as f64).ln().max(0.0) + 4.0 * mean_usable;
    } else {
        // Slight preference for bins with residuals close to the mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 0.5 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small residue" classes (dead space) get penalized.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Class A: post_residual in [0,10) -> perfect fit, strong reward
    if post_residual < 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Class B: harmonic band 10..=20 -> still usable by small items (min size 10)
    else if post_residual <= 20 {
        score -= 15.0;
    }
    // Class C: dead zone 21..=49 -> likely unusable, penalize via modulo structure
    else if post_residual < 50 {
        let dead = (post_residual % 10) as f64;
        score += 25.0 + dead * 1.5;
    }
    // Class D: 50..=79 -> half-bin harmonic, mildly good
    else if post_residual < 80 {
        score -= 8.0;
    }

    // Integer-division threshold: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain bonus scaled by how snugly next item fits
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 20.0 + 30.0 * snug;
        } else {
            // next item won't chain here; penalize if post residual is wasteful
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    } else {
        // last item: any placement is fine, prefer tightest
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // have poor fits. Penalize new bin by open_bins pressure and stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 30.0 + 40.0 * (1.0 - progress) + 5.0 * pressure;
        // if mean residual is large, opening new bin is wasteful
        score += mean_residual * 0.5;
    } else {
        // Prefer bins tighter than the mean residual (harmonic balance)
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.2;
    }

    // Modulo tie-break on post_residual classes: favor multiples of 10
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that cannot fit the next item (or a small item) is dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;

    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Gap too small for the lookahead item -> dead space penalty,
            // scaled by how close the gap is to being "wasted" (small gap = worse).
            let dead = (next_item_size - post_residual) as f64;
            score += 2.5 * dead;
        } else {
            // Reward gaps that exactly or near-exactly fit the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 1.5 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Penalize mid-range unusable residuals (too small for typical items 1..100
    // means post_residual < min useful threshold ~10), but treat exact fits well.
    if post_residual == 0 {
        score -= 20.0; // perfect fit: excellent
    } else if post_residual < 10 {
        score += 30.0 * (1.0 - post_residual as f64 / 10.0); // tiny dead gap
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // (favor bins with low residual relative to mean), discouraging sprawl.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Early in the stream, be more willing to open fresh bins for large items;
    // later, tighten up and avoid waste.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure against opening when
        // existing bins fit well (post_residual small for existing bins).
        let base = 40.0 + 10.0 * progress;
        score = base + open_pressure * 2.0;
        if fitting_bins_count > 0 && next_item_size > 0 {
            // discourage new bin if lookahead can't use a big residual anyway
            if bin_capacity - item_size >= next_item_size {
                score += 5.0;
            }
        }
    } else {
        // Slight reward for bins whose residual is far below mean (tight bins).
        let tightness = (mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64;
        score -= 5.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Extra bonus for exact match
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize post_residual that is unusable for the next item (too small but nonzero)
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 20.0;
    }

    // Reward bins that are tighter than the mean residual (good packing), penalize loose ones.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual == bin_capacity - item_size is large otherwise).
    if bin_residual == bin_capacity {
        // Mild penalty so open bins with decent fits win; scales with stream progress.
        score += 10.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Penalize creating very small dead space (< 10, likely unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to hold any future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mildly penalize leaving large awkward gaps
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: penalize opening a new bin when decent fits exist,
    // but allow it when the best alternative would leave large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // New bins are cheaper early (more future to use them) — scale penalty by progress.
        let new_bin_penalty = 10.0 + 30.0 * progress;
        score += new_bin_penalty;
        // If item is large, filling a fresh bin is attractive.
        score -= 0.15 * item_size as f64;
        // If many open bins already, discourage proliferation.
        score += 1.5 * open_bins_count as f64;
    } else {
        // Reward using existing bins, especially those below mean residual (fragments consolidation).
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
        // Slight reward for reducing open-bin count pressure on fuller bins.
        score -= 0.03 * (bin_capacity - bin_residual) as f64;
    }

    // Mild time-varying exploration pressure: early on, encourage diverse placements.
    let t = step_index as f64 / (total_items as f64).max(1.0);
    score -= 3.0 * (1.0 - t) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: post_residual penalized more as stream progresses
    score += 12.0 * (norm_pr * norm_pr) * (0.5 + progress);

    // Tight fits (small post_residual relative to item) are valuable early, less late
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (1.0 - progress);

    // Penalize residual that fails to fit the next item (lookahead waste), smooth gate
    let fits_next = (next_item_size as f64) <= pr;
    let gate = if fits_next { 0.0 } else { 1.0 };
    score += 10.0 * gate * (1.0 - progress * 0.5);

    // Last-chance bin bonus: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure toward consolidating into fewer bins
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Reward bins whose residual deviates favorably from the mean residual
    score -= 0.3 * (mean_residual - pr);

    // Small smooth nudge toward new-bin usage when residuals are large and stream is late
    score += 6.0 * norm_pr * progress * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes of 10
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are multiples of 10 are "harmonic" — likely reusable by future items
    if class == 0 && pr > 0 {
        score -= 6.0;
    } else if class <= 2 || class >= 8 {
        // near-harmonic residuals also mildly favored
        score -= 2.0;
    } else {
        // mid-class dead space penalized, worse for tiny residuals
        score += 3.0 + (5 - class.min(5)) as f64;
    }

    // Perfect fit reward (post_residual == 0)
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            let next_class = (pr - next_item_size) % 10;
            if next_class == 0 {
                score -= 10.0;
            }
            score -= (pr - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; penalize large post_residual slightly
            score += (pr as f64) * 0.05;
        }
    }

    // Integer-division threshold on residual thirds
    let third = bin_capacity / 3;
    if pr < third {
        score += 5.0; // small residual bin: low value
    } else if pr >= 2 * third {
        score -= 4.0; // large residual bin: valuable
    }

    // Last-chance bin bonus: only fitting bin => avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: neutral base, penalize early-stream waste
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 2.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // if next item is large and no open bin can hold both, new bin attractive
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first)
    score -= (mean_residual - post_residual as f64).max(-20.0).min(20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // gap is "dead" if smaller than the smallest plausible item (assume ~10)
        let dead = (post_residual as f64) < 10.0;
        if dead {
            score += 60.0; // heavy penalty for creating a tiny useless gap
        }
        // nonlinear penalty on leftover gap, worse when gap is small but nonzero
        let g = post_residual as f64;
        score += 40.0 / (1.0 + g / 15.0);
    } else {
        // perfect fit: strong reward
        score -= 80.0;
    }

    // Reward tight fits: fraction of residual consumed
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bin pressure: prefer filling existing bins when many are open,
    // but allow new bin when open count is low.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin gets a base cost so it's only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * (open_bins_count as f64);
        // if next item is large and this item is small, opening fresh bin is safer
        if next_item_size > 60 && item_size < 30 {
            score -= 35.0;
        }
    } else {
        // lookahead: reward leaving room for the next item
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 20.0;
        }
        // penalize if post_residual is just barely below next item (near-miss dead space)
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 15.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // mean residual coupling: if open bins are already slack, prefer filling them
    if bin_residual != bin_capacity {
        score -= 10.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = (post_residual - next_item_size) as f64;
        // Strong reward proportional to how well the next item fills the leftover space.
        score -= 40.0 * (1.0 - match_gap / bin_capacity as f64);
        // Perfect match: post_residual == next_item_size gets maximal bonus.
        if match_gap == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: penalize dead space creation.
        score += 30.0 + 0.5 * (post_residual as f64);
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from the mean.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless current bin fit is very poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening new bins is cheaper than leaving many tiny residuals.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual as f64 > 0.35 * bin_capacity as f64 {
            score -= 20.0 * progress;
        }
    }

    // Prefer tighter fits generally (small post_residual).
    score += 0.1 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Slight preference to fill bins when many bins are open (consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: penalize small post_residual quadratically relative to capacity.
    let tightness = post / cap;
    score -= (1.0 - tightness) * (1.0 - tightness) * 30.0 * (1.0 - 0.3 * progress);

    // Penalize dead space that no plausible future item can use (smooth coupling with progress).
    let dead_zone = (post / cap).powi(3);
    score += dead_zone * 40.0 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving post_residual close to next item size (smooth kernel).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let diff = (post - next_item_size as f64) / cap;
        score -= (1.0 - diff) * (1.0 - diff) * 15.0;
    } else if next_item_size as f64 > post {
        // Penalize blocking the next item's best fit.
        score += 8.0 * ((next_item_size as f64 - post) / cap);
    }

    // New-bin candidate: only attractive when open bins are quite full or scarce fits exist.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap);
        score = cap * 0.6 + cap * 0.8 * (1.0 - avg_fill).powi(2) - 20.0 * (fitting_bins_count as f64).min(3.0) / 3.0;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Early in stream, new bins are cheap; later, prefer consolidation.
        score += 15.0 * progress;
    }

    // Mild penalty when many bins are open: encourage filling existing ones.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    // Slight preference to balance residuals toward mean early on.
    score += 3.0 * (1.0 - progress) * ((post - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: dead space classification by capacity fraction
    let pr = post_residual as f64;
    let frac = pr / cap;
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    } else if frac < 0.05 {
        score -= 18.0;
    } else if frac < 0.15 {
        score -= 6.0;
    } else if frac < 0.35 {
        score += 4.0;
    } else {
        score += 10.0; // large leftover is valuable, mild penalty for wasting it on a big item
    }

    // Integer-division harmonic classes: post_residual bucketed by 10s
    let bucket = post_residual / 10;
    score += (bucket % 5) as f64 * 1.5;

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + slack * 0.15;
        } else {
            // next item won't fit here; penalize if the gap is just barely too small
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.25;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: prefer fuller bins when many bins are open
    score -= (bin_residual as f64 / cap) * (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean residual coupling: if this bin is much emptier than average, slight penalty
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0).min(50.0) * 0.1;

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // base new-bin cost, reduced late in stream or when no bin fits
        score = cap * 0.9 + 20.0 * desperation - 15.0 * progress;
        if fitting_bins_count == 0 {
            score = 5.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    if is_new_bin {
        // Brand-new empty bin candidate.
        // Strongly prefer it when nothing is open yet.
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Opening a new bin is more attractive when few bins fit the item
        // (poor fits elsewhere) or when many bins are already open and
        // consolidation pressure is low.
        score += 18.0 + 6.0 * fitting_bins_count as f64;
        // Late in the stream, avoid proliferating bins with leftover space.
        score -= 10.0 * (1.0 - progress);
    } else {
        // Existing bin: strict dead-space avoidance.
        if post_residual == 0 {
            // Perfect fill: heavily rewarded.
            score -= 80.0;
        } else if post_residual < 10 {
            // Tiny unusable gap: penalize hard.
            score += 60.0;
        } else if (post_residual as f64) < item_size as f64 {
            // Residual can't hold another item of this size: moderate penalty.
            score += 25.0;
        } else {
            // Residual remains usable: reward.
            score -= 15.0;
        }

        // Last-chance bin: strongly favor using it to avoid opening a bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Open-bin pressure: mild consolidation bias toward reusing bins
        // when many are open.
        score += 0.5 * open_bins_count as f64;

        // Reward bins whose residual aligns with the mean (balanced packing).
        score += 0.1 * ((post_residual as f64) - mean_residual).abs();

        // Lookahead: if the next known item fits in the resulting residual,
        // this placement is extra valuable.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if next item fits exactly into post_residual (2-step lookahead match).
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward decays as slack grows; near-perfect matches favored
            score -= 40.0 * (1.0 - slack / 40.0).max(0.0);
        } else {
            // next item won't fit: penalize proportionally to wasted post space
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.3 * overflow.min(60.0);
        }
    }

    // Penalize large dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += 0.25 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * open_bins_count as f64;
    }

    // Mild late-stream tightening: consolidate as stream progresses.
    score -= 5.0 * (step_index as f64 / total_items.max(1) as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; penalize unless no open bin fits,
        // or unless current open bins are nearly full / fragmented.
        let mut new_bin_score = bin_capacity as f64 * 1.35;
        if fitting_bins_count == 0 {
            new_bin_score -= 300.0; // must open a bin
        } else {
            // If other fitting bins exist, discourage opening a new one,
            // but soften if open bins are highly fragmented (mean residual low).
            let fragmentation = mean_residual / bin_capacity as f64;
            new_bin_score -= 120.0 * fragmentation.max(0.0);
        }
        // Late in the stream, prefer reusing existing bins even more.
        new_bin_score += 80.0 * progress;
        return new_bin_score;
    }

    // ---- Reward tight fits ----
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 55.0 * tightness * tightness;

    // ---- Penalize dead space: residual too small for the smallest plausible item ----
    let min_item = 1.0;
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 40.0;
    }
    // Dead space that no future item of typical size can use
    let dead_zone = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += 35.0 * dead_zone;

    // ---- Lookahead: reward residuals that can still fit the next item ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect pairing: this bin can absorb the next item too
            let pair_eff = (next_item_size as f64) / (post_residual as f64);
            score -= 45.0 * pair_eff.min(1.0);
        } else {
            // Post residual cannot host next item: penalize proportionally
            score += 25.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).min(bin_capacity as f64)).max(0.0);
        }
    } else {
        // Last item: fill as tightly as possible
        score -= 70.0 * tightness;
    }

    // ---- Last-chance bin: if this is the only fitting bin, strongly prefer it ----
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // ---- Global state coupling ----
    // Many open bins: encourage consolidation into low-residual bins.
    let open_pressure = (open_bins_count as f64 / 20.0).min(3.0);
    score -= 8.0 * open_pressure * tightness;

    // Bins far below mean residual are "wasteful" targets when many bins are open
    let residual_gap = (bin_residual as f64) - mean_residual;
    score += 0.15 * residual_gap * (1.0 + open_pressure * 0.5);

    // ---- Time horizon adaptation ----
    // Early: be exploratory, mildly favor spreading (larger post residuals OK).
    // Late: be greedy, heavily favor minimal post residual.
    let greed = progress * progress;
    score += 30.0 * (1.0 - greed) * (post_residual as f64 / bin_capacity as f64);
    score -= 50.0 * greed * tightness;

    // Small tie-break: prefer bins with less residual overall
    score += 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer bins leaving small residuals (tight fits);
    // later, tolerate larger residuals as new bins become cheaper.
    let pr = post_residual as f64 / bin_capacity as f64;
    let coupling = pr * pr * (1.0 - progress) * 40.0 - pr * progress * 20.0;
    score += coupling;

    // Reward near-perfect fits strongly (dead-space elimination).
    if post_residual <= 10 {
        score -= 25.0 * (1.0 - post_residual as f64 / 11.0);
    }

    // Last-chance bin: strong bonus to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize residuals that are too small to be useful.
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer keeping residual spread tight relative to mean residual.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Mild penalty for accumulating many open bins early (encourage consolidation).
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // New-bin candidate: penalize slightly unless open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
        if fitting_bins_count > 0 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core)
    score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: quantize post_residual into capacity-fraction bands.
    // Dead space that cannot hold the smallest plausible item (>=1) is waste;
    // classify residuals by which harmonic slot they fall into.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c / 4.0;
    let eighth = c / 8.0;
    let sixteenth = c / 16.0;

    // Penalize residuals that are "just barely" above a useful threshold
    // (wasted sliver), reward residuals landing exactly on harmonic multiples.
    if post_residual > 0 {
        let mod16 = post_residual % 16;
        if mod16 == 0 {
            score -= 5.0; // clean harmonic slot
        } else {
            score += (16 - mod16) as f64 * 0.5; // sliver penalty
        }
        // Fractional dead-space penalty: residual too small to be useful
        if pr < sixteenth {
            score += 30.0;
        } else if pr < eighth {
            score += 10.0;
        } else if pr < quarter {
            score += 3.0;
        }
    }

    // Lookahead coupling: reward if next item fits the post_residual exactly
    // or harmonically (integer-division class match).
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let exact = post_residual % next_item_size.max(1) == 0;
        if post_residual == next_item_size {
            score -= 60.0;
        } else if exact {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this leftover: penalize proportionally
        score += (next_item_size as f64 - pr).max(0.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: neutral-ish baseline; only prefer a new bin
    // when current bins are crowded (mean residual low) and fit is poor.
    if bin_residual == bin_capacity {
        score = c * 0.6 + mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
        if post_residual as f64 > mean_residual && mean_residual < quarter {
            score += 20.0; // opening fresh bin better than fragmenting
        }
    }

    // Late-stream consolidation: as stream progresses, favor tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (pr / c) * 10.0;

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Moderate gaps (10..=19) are partially wasted since min item is 10; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, prefer filling existing.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= pressure * 3.0;
    } else {
        // New bin: penalize by open-bin pressure and by how well next item could use residual.
        score += pressure * 4.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0;
        }
    }

    // Lookahead: if the post_residual exactly fits the next item, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // If post_residual is too small for next item but nonzero, slight penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Deviation from mean residual: prefer bins whose residual deviates less (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Early stream: be more permissive about tight fits; late stream: tighten dead-space penalty.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // Base: prefer tight fits (low post residual).
    let mut score = post;

    // Strong 2-step lookahead: reward if the next item fits exactly or well into post_residual.
    if next_item_size > 0 && nxt <= post {
        let slack_after_next = post - nxt;
        score -= 25.0 * (1.0 - slack_after_next / cap);
        // Perfect chain: post_residual == next_item_size.
        if slack_after_next == 0.0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow: penalize dead space created.
        score += 8.0 * (1.0 - post / cap);
    }

    // Penalize wasting a near-empty bin's flexibility when other bins fit.
    if fitting_bins_count > 1 && post > 0.0 {
        score += 3.0 * (post / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    // (large post_residual relative to capacity) or nothing chains well.
    if bin_residual == bin_capacity {
        score = post + 12.0;
        if next_item_size > 0 && nxt <= post {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        }
        if fitting_bins_count == 1 {
            // A fresh bin beats a forced last-chance squeeze only rarely.
            score += 5.0;
        }
    }

    // Mild phase-awareness: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post / cap);

    // Slight preference toward bins with residuals near the mean (balance).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - tightness).powi(6);

    // Penalize dead space that cannot hold the next item
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0 + 0.5 * post_residual as f64;
        } else if post_residual >= next_item_size {
            // reward bins that can also host the lookahead item
            score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Penalize wasting a nearly-full bin on a small item
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.25 && bin_residual < bin_capacity {
        score += 30.0 * (1.0 - fill_ratio);
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 0.6 * bin_capacity as f64;
        if poor_fit && open_bins_count > 0 {
            score -= 35.0 + 20.0 * progress;
        } else {
            // discourage opening new bins when decent fits exist
            score += 60.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> consolidate
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.15 * consolidation;
        score -= 0.05 * open_bins_count as f64 * (1.0 - tightness);
    }

    // Mild time-horizon term: early on, prefer balanced residual spread
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 12.0 * fit_frac * fit_frac * cap
        - 20.0 * fit_frac * fit_frac * fit_frac * cap;

    // Perfect fit reward (smooth, non-piecewise)
    let perfect = (pr / cap).powi(4);
    score -= 60.0 * perfect * cap;

    // Stream-progress coupling: tighten later in the stream
    let tighten = progress * progress * (1.0 - progress);
    score += 30.0 * tighten * fit_frac * cap;
    score -= 15.0 * progress * (1.0 - fit_frac);

    // Lookahead coupling: reward if next item fits smoothly into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score -= 25.0 * (1.0 - gap) * (1.0 - gap) * (1.0 - progress);
        // penalize leaving space that neither fits next item nor is tiny
        score += 10.0 * gap * gap * cap * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins deviating from mean residual (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev * cap * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless residual is empty
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // but allow new bins when item is large relative to mean residual
        score -= 20.0 * (item_size as f64 / cap) * progress;
    }

    // Small penalty for many open bins to encourage consolidation
    score += 0.3 * open_bins_count as f64 * fit_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it decomposes into
    // "nice" capacity fractions (quarters, thirds, halves).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional position of post_residual within the bin.
    let frac = post / cap;

    // Reward post residuals close to harmonic fractions (0, 1/4, 1/3, 1/2, 2/3, 3/4, 1)
    let harmonics = [0.0, 0.25, 1.0 / 3.0, 0.5, 2.0 / 3.0, 0.75, 1.0];
    let mut harmony = f64::INFINITY;
    for &h in &harmonics {
        let d = (frac - h).abs();
        if d < harmony { harmony = d; }
    }
    score -= 12.0 * (1.0 - harmony * 4.0).max(0.0);

    // Modulo classes: post residuals that are multiples of small divisors
    // tile better with typical item sizes.
    let pr = post_residual;
    let mod_bonus = if pr != 0 {
        let mut b = 0.0;
        for &m in &[10u32, 20, 25, 50] {
            if pr % m == 0 { b += 6.0; }
        }
        b
    } else {
        15.0 // perfect fit
    };
    score -= mod_bonus;

    // Dead-space penalty: residuals too small for the minimum item (1 here,
    // but use a practical threshold of 10 based on typical stream granularity).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score += slack as f64 * 0.5;
        } else {
            // next item won't fit here; mildly penalize wasting large residual
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full on average
    // or this bin is brand new anyway; penalize fresh-bin escape hatches otherwise.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 18.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 25.0; // no alternative
        }
    }

    // Prefer consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Slight preference for bins below mean residual (balance load).
    score += 0.3 * (post - mean_residual).abs().signum() * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Dead zone: residual < 10 (min item size).
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading items into
    // new/partial bins; prefer consolidating into existing bins.
    score += (open_bins_count as f64) * 1.5;

    // If placing here leaves room for the lookahead item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so it's only chosen when open bins
    // have very poor fits (large dead-space penalties above dominate).
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 2.0;
    }

    // Progress-based tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but reward exact/exact-ish matches
    // with the next item (2-step lookahead): post_residual == next_item_size is ideal.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying with distance.
        let match_bonus = 60.0 * (-gap / 12.0).exp();
        score -= match_bonus;

        // Penalize leaving residual that neither fits next item nor is tiny:
        // "dead zone" waste between 1 and 9 (too small for min item size 10... but
        // sizes go down to 1, so weight by how small the leftover is relative to next).
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Reward last-chance bins: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Compare post_residual against mean residual of open bins: leaving a residual
    // near the mean keeps the pool of bins balanced and usable.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Penalize new-bin opening unless the fit into existing bins is bad.
    if bin_residual == bin_capacity {
        // New bin baseline: full residual as dead space unless lookahead matches well.
        score += 20.0;
        if next_item_size > 0 {
            // A fresh bin with residual == capacity is great if next item is large
            // relative to remaining open-bin residuals.
            let avg_after = if open_bins_count > 0 { mean_residual } else { 0.0 };
            if (next_item_size as f64) > avg_after + 10.0 {
                score -= 30.0;
            }
        }
        // Early in the stream, opening bins is cheap and gives flexibility.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    } else {
        // Existing bin: reward using bins with smaller residuals first (best-fit flavor).
        score += 0.05 * bin_residual as f64;
    }

    // Slight penalty when many bins are open and we'd create a tiny unusable leftover.
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always excellent.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tight fits preferred: reward small post-residual non-linearly.
    let tight = (post_residual as f64 / bin_capacity as f64).powi(3);
    score -= 40.0 * (1.0 - tight) * (1.0 - tight);

    // Lookahead: if the next item fits into post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = (post_residual - next_item_size) as f64;
        score -= 30.0 - 0.15 * chain;
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards; penalize leaving awkward gaps
        // unless this bin is nearly full anyway.
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Compare against the average residual: placing into a bin that is
    // already below-average residual (fuller bin) is good.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Time horizon: early in the stream, be conservative about creating
    // many tiny gaps; late in the stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - tight);

    // Discourage spreading across too many open bins when residuals are large.
    if open_bins_count > 1 && bin_residual as f64 > mean_residual + 20.0 {
        score += 6.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // A fresh bin wastes nothing now but costs a bin; make it attractive
        // only when post_residual of alternatives would be large or few bins fit.
        let alt_bad = (post_residual as f64) * 0.5 + (fitting_bins_count as f64) * 5.0;
        score = 100.0 + alt_bad;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 80.0; // last chance elsewhere failed: open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic waste coupling with stream progress
    let mut score = pr as f64 * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0);
    score += 60.0 * x * x * (0.5 + 0.5 * progress);

    // Reward tight fits (small post residual) with smooth exponential bonus
    score -= 30.0 * (-8.0 * x).exp();

    // Lookahead: if next item fits the post residual, reward strongly (smooth)
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as i32 as f64;
        let slack = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 25.0 * fits_next * (1.0 - slack);
        // penalize post residual that nearly fits next item (tempting but wasteful)
        score += 12.0 * (1.0 - fits_next) * (-((pr - next_item_size as f64).abs() / 10.0)).exp();
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - x);
    }

    // Mean residual coupling: prefer bins near mean residual (smooth)
    score += 0.15 * (pr - mean_residual).abs();

    // Slight penalty when many bins open (encourage consolidation)
    score += 0.5 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals divisible by 8 or 16 are more reusable
    let pr = post_residual as u32;
    if pr > 0 {
        if pr % 16 == 0 {
            score -= 6.0;
        } else if pr % 8 == 0 {
            score -= 3.0;
        } else if pr % 4 == 0 {
            score -= 1.0;
        } else {
            score += 2.0; // odd residuals tend to be dead space
        }
    }

    // Capacity-fraction classes: post_residual in useful small bands
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.09 {
        score += 8.0; // tiny unusable sliver penalty
    } else if frac >= 0.09 && frac <= 0.35 {
        score -= 4.0; // sweet band for medium items
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next fits and leaves class-aligned residual
            let pr2 = post_residual - next_item_size;
            if pr2 % 8 == 0 {
                score -= 5.0;
            }
            score -= next / cap * 3.0;
        } else {
            score += 3.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Many open bins: discourage spreading, favor tight fills
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * (frac * 4.0);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.05;

    // New-bin candidate: only attractive when this item is large relative to capacity
    // and no open bin is a good home (handled via base score); penalize mildly.
    if bin_residual == bin_capacity {
        score += 15.0 - (item_size as f64 / cap) * 10.0;
    }

    // Late-stream preference for closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible future item (items >= 1, but small gaps < ~10 are dead)
    // are heavily penalized. Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual < 10 {
        score += 60.0; // dead space: unusable gap
    } else if post_residual <= 20 {
        score += 15.0; // marginal gap
    } else if post_residual <= 30 {
        score -= 5.0; // still usable for small items
    }

    // Reward tight fits: fraction of bin used by this placement
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins would create bad fits
    if bin_residual == bin_capacity {
        // base cost of opening a bin, scaled by stream progression (waste matters early)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 - 40.0 * progress;
        // if the next item could exactly fill this new bin after this one, encourage it
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 150.0;
        }
        // discourage new bin when many bins already open and mean residual is large
        score += 0.5 * open_bins_count as f64 + 0.3 * mean_residual;
    } else {
        // pressure to consolidate into fewer bins
        score += 0.2 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by mean residual context.
    let mean_r = if mean_residual.is_finite() && mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
    score += (post_residual as f64 / mean_r) * 15.0;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item => strong reward.
        if diff < 0.5 {
            score -= 60.0;
        } else {
            score += diff * 0.8;
        }
        // If next item fits exactly in current residual (before placement), mild bonus.
        if bin_residual as i64 - item_size as i64 == next_item_size as i64 {
            score -= 10.0;
        }
        // Penalize leaving post_residual too small for the (typical) next item.
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating large dead space relative to capacity (waste metric).
    let waste = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += waste * 30.0;

    // New-bin candidate handling: neutral-ish baseline; only attractive when
    // open bins would create big waste or none fit well.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If many open bins are highly fragmented, opening a fresh bin is fine.
        if mean_r < 20.0 {
            score -= 20.0;
        }
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 25.0;
    }

    // Slight preference for bins with residual close to item (best-fit flavor).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize large dead space: post_residual that is small but unusable.
    if post_residual > 0 {
        score += 12.0 * (post_residual as f64 / bin_capacity as f64).exp() - 12.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * (1.0 - next_tight);
    } else if next_item_size > 0 {
        // Penalize leaving residual that cannot host the next item.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a fresh bin is not chosen for good fits.
        score += 40.0;
        // More attractive when few bins can fit the item or open bins are crowded.
        score -= 20.0 * (1.0 / (fitting_bins_count as f64 + 1.0));
        score += 0.5 * open_bins_count as f64;
        // Early in the stream, opening bins is cheap and flexible.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 15.0 * (1.0 - progress);
    }

    // Global state coupling: prefer filling bins with above-average residual
    // (drain large-residual bins) mildly.
    score -= 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Late in stream, prefer closing out bins: reward near-full placements.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if post_residual <= 10 {
        score -= 10.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize leftover space, with non-linear (quadratic) growth
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Smooth stream-progress coupling: leftover space costs more as the stream matures
    score *= 1.0 + 0.8 * progress * (1.0 - progress * 0.5);

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize post_residual that is too small to ever be useful again
    // (smooth dead-space penalty peaking near tiny residuals)
    if post_residual > 0 {
        let dead = ((post_residual as f64) / 20.0).exp().recip();
        score += 8.0 * (1.0 - dead);
    }

    // Consider next item: reward residuals that can still host the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // bin will be nearly dead for the next item
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Dampen when many bins are open (prefer consolidating into existing bins)
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins closer to the mean (balance)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: make it attractive only when it beats poor fits
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        // Dead space: residual too small to be useful for typical items
        score += 14.0;
    }

    // Harmonic class logic: mod-10 classes of post_residual.
    // Residuals that are multiples of 10 pair better with the 10..100 item grid.
    let class = post_residual % 10;
    score += class as f64 * 0.35;
    // Bonus for residuals in "useful" integer-division bands (>= half-capacity halves)
    if post_residual >= bin_capacity / 2 {
        score -= 4.0;
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit quality: tighter leftover after chaining is better
            let chain_left = post_residual - next_item_size;
            score -= 6.0 + (chain_left as f64) * 0.05;
        } else {
            // next item won't chain here; penalize proportionally to wasted space
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer it
    // over opening a new bin (but don't override a brand-new-bin candidate itself).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Brand-new empty bin candidate: mild penalty so it is chosen only when
    // existing fits are poor (their dead-space penalties will dominate).
    if bin_residual == bin_capacity {
        score += 8.0 + 0.15 * open_bins_count as f64;
    }

    // Prefer bins whose current residual is close to the item size (tight fit)
    score += 0.06 * (bin_residual as f64 - item_size as f64).abs();

    // Late in the stream, consolidate more aggressively into open bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

    // Slight preference for bins below the mean residual (fill emptier bins first)
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

