pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that cannot fit the next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }
    // Reward residuals that exactly accommodate the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    score -= 3.0 * pressure * (open_bins_count as f64).ln().max(0.0);

    // Time horizon: early in stream, slightly favor new bins to build flexible residuals;
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0 * pressure;
    score -= progress * 1.5;

    // Prefer bins whose residual is close to the item (best-fit style).
    score += 0.1 * ((bin_residual as i64 - item_size as i64).abs() as f64);

    // Discourage leaving residuals in the awkward 1..10 zone.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 12.0 * norm_pr * norm_pr * (1.0 + progress);
    score += 20.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);
    score -= 15.0 * norm_pr * (1.0 - progress) * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post residual, reward
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let gap = (pr - n) / cap;
            score -= 6.0 * (1.0 - gap * gap);
        } else {
            score += 3.0 * ((n - pr) / cap);
        }
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - norm_pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: decile buckets (capacity fraction classes)
    let class = post_residual / (bin_capacity / 10).max(1); // 0..=10
    let class_bonus = match class {
        0 => 60.0,                       // perfect fit -> strongly favored
        1 => 30.0,                       // tiny dead space
        2 => 12.0,
        3 => 0.0,
        4 => -6.0,                       // mid-range residual: mildly acceptable
        5 => -10.0,
        6 => -4.0,
        7 => 6.0,
        8 => 14.0,
        9 => 22.0,
        _ => 0.0,                        // untouched bin (new-bin candidate)
    };
    score -= class_bonus;

    // Dead-space penalty if residual can't fit even the smallest plausible item
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: reward leaving space that next item can use
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // harmonic match: next item fits leaving another small class
            let next_post = post_residual - next_item_size;
            if next_post < 10 {
                score -= 10.0;
            }
        } else {
            // post_residual is pure dead space relative to next item
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin leaves big waste
    if bin_residual == bin_capacity {
        score = cap * 0.75 - post * 0.1;
        if fitting_bins_count <= 1 {
            score -= 20.0; // nothing else fits well -> allow new bin
        }
        if post_residual >= 0 && next_item_size > 0 && next_item_size >= item_size * 2 {
            score -= 8.0; // big item coming later, fresh bin useful
        }
    }

    // Mild pressure toward consolidating when many bins are open
    score += (open_bins_count as f64) * 0.05 + (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are waste.
    let dead_threshold = 20u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 3.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tight = (item_size as f64) / (bin_residual as f64);
    score -= 2.0 * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 5.0 {
            score -= 8.0;
        } else {
            score -= 1.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize if leftover is too small to matter.
        score += 1.5;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Deviation from mean residual: prefer bins that reduce spread.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // New-bin candidate: make it attractive only when item is large and fit elsewhere is poor.
    if bin_residual == bin_capacity {
        score = (post_residual as f64) + 8.0 - 0.03 * open_bins_count as f64;
        if item_size >= 70 {
            score -= 6.0;
        }
        if item_size <= 30 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize small dead space that is hard to fill (below min item size ~1..100 unknown, use 10).
        if post_residual < 10 {
            score += 60.0;
        }
        // 2-step lookahead: reward if next item fits exactly or well into post_residual.
        if next_item_size > 0 && next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 + (slack_after_next as f64).min(30.0);
            if slack_after_next == 0 {
                score -= 120.0;
            }
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item won't fit here: penalize proportionally to wasted lookahead potential.
            score += 15.0 + 0.25 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Favor bins tighter than the mean (best-fit flavor).
    score += 0.5 * (mean_residual - bin_residual as f64).max(-40.0).min(40.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Late in stream: prefer closing bins, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * open_bins_count as f64;

    // New-bin candidate: only attractive when current item is huge or no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize post_residual that is small but nonzero and cannot
    // fit the next item (dead space); reward residual that fits next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // dead space relative to next item
            let dead = post_residual as f64 / next_item_size as f64;
            score += 10.0 * (1.0 - dead);
        }
    }

    // Last chance: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are poor fits (high mean residual fragmentation) or few bins open.
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin, softened when bins are fragmented
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 20.0 * fragmentation - 10.0 * (1.0 - progress);
    } else {
        // Slight preference for bins with residual close to mean (keep pool balanced)
        score += 0.05 * ((bin_residual as f64 - mean_residual).abs());
    }

    // Prefer filling more-open bins when many are open (consolidation pressure).
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    // Early stream: be greedy with big items, fill big holes first.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        score -= 0.2 * (item_size as f64);
    }

    // Penalize leaving residuals in the awkward 1..=9 range (unusable for min-size items).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, dead space is cheap; later, it becomes quadratically penalized.
    let dead_space_weight = 1.0 + 2.0 * progress * progress;
    score += dead_space_weight * norm_pr * norm_pr * cap * 0.5;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= (1.0 + progress) * tightness * tightness * item_size as f64 * 0.3;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Discourage spreading across many open bins relative to mean residual.
    score += 0.1 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() * 0.01;

    // Lookahead coupling: smooth interaction with next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        // Smooth version of fit: how close post_residual is to next item.
        let smooth_fit = 1.0 / (1.0 + ((pr - nx) / cap).abs() * 10.0);
        if fit_next > 0.0 {
            score -= smooth_fit * nx * 0.15 * (1.0 + progress);
        } else {
            score += 5.0 * (nx / cap) * (1.0 - progress);
        }
    }

    // Mild penalty for opening a new bin when others fit, growing with progress.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 8.0 + 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify by half-capacity bands.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Post-residual in the "small dead space" band: penalize heavily unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Residual classes: a residual that exactly admits a common class is good.
    // Class boundaries: multiples of 10 (item granularity) and 1/4, 1/2 capacity.
    if post_residual == half {
        score -= 15.0; // half-capacity residual is highly reusable
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0; // aligns with typical item granularity
    } else if post_residual > half {
        score -= 5.0; // roomy bin, still flexible
    } else if post_residual < quarter && post_residual > 0 {
        score += 10.0; // cramped leftover, likely dead space
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder: mild penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: compete with post_residual of real bins.
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 500.0; // forced open
        } else if fitting_bins_count == 1 {
            score += 60.0; // prefer the last-chance existing bin
        }
        // Early in the stream, opening bins is cheaper (more future use).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is far below the mean (tight bins get filled first),
    // keeping loose bins available for awkward future items.
    score -= 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Slight preference for bins that already hold larger items (tighter packing),
    // approximated by smaller residual relative to capacity.
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item are waste.
    let dead_threshold = 10.0; // smallest possible item size
    if (post_residual as f64) < dead_threshold {
        score += 50.0; // unusable gap penalty
    } else if (post_residual as f64) < 20.0 {
        score += 20.0; // near-dead gap penalty
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) * (1.0 - (post_residual as f64) / (bin_residual.max(1) as f64)) * 2.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // If this bin can fit the next item too, reward keeping that option alive.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // We destroy the ability to host the lookahead item: penalize.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening another.
    // New-bin candidate has bin_residual == bin_capacity; make it unattractive under pressure.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 8.0;
        // Early in the stream or when existing bins are badly fragmented, allow new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.1 && open_bins_count < 3 {
            score -= 25.0;
        }
        if mean_residual > 40.0 {
            score -= 20.0; // existing bins have room; new bin less needed actually -> keep penalty
        }
    }

    // Mild preference to fill bins below mean residual (balance consolidation).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (low post_residual)
    score -= (cap - post) / cap * 10.0;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post).abs() < f64::EPSILON {
            score -= 40.0;
        } else if next <= post {
            // next item fits: reward proportional to how well it fills remainder
            score -= (1.0 - (post - next) / cap) * 15.0;
        } else {
            // next item won't fit here: penalize leftover that likely becomes dead space
            score += (next - post).min(30.0) * 0.5;
        }
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins)
    score += (post - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 2.0;
        // but allow new bin if mean residual is very tight (fragmented bins)
        if mean_residual < 15.0 {
            score -= 12.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer placements that leave little waste relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward strongly;
    // if next item cannot use the post-residual, penalize creating dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 35.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            score += 0.35 * (post_residual as f64) * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits more aggressively.
        score += 6.0 * (fitting_bins_count as f64).ln().max(0.0) * (1.0 - tightness);
    }

    // Global state: when many bins are open with large mean residual, discourage
    // spreading waste; encourage filling bins with above-average residual.
    let residual_gap = post_residual as f64 - mean_residual;
    score += 0.25 * residual_gap * (open_bins_count as f64).sqrt();

    // Time horizon: early in the stream, be conservative with new bins (favor existing);
    // late in the stream, allow fresh-bin exploration since future payoff shrinks.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later; also penalize when
        // many bins are already open and underfilled.
        score += 70.0 * (1.0 - progress) + 4.0 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 && item_size >= bin_capacity / 2 {
            score -= 30.0; // two large items pair well in one fresh bin
        }
    } else {
        // Existing bin: mild late-stream bonus to consolidate.
        score -= 10.0 * progress;
    }

    // Small stability nudge based on item size ratio.
    score += 0.05 * (item_size as f64) * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), non-linearly.
    let mut score = post * (1.0 + norm_post * norm_post);

    // Stream-progress coupling: later in stream, penalize residual more strongly
    // (consolidate as stream ends), early stream is more lenient.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * norm_post * cap * 0.3;

    // Dead-space penalty: residuals too small to be useful later.
    let dead_threshold = cap * 0.15;
    if post < dead_threshold {
        score += (dead_threshold - post) * (1.0 + 2.0 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= cap * 0.5 * (0.5 + progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= next_item_size as f64 * 0.4 * (1.0 + progress);
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - post).max(0.0) * 0.1;
    }

    // Mean-residual coupling: if this bin's residual is below mean, it's a good fit;
    // reward placing into below-average-residual bins (tightening them).
    let mean_norm = mean_residual / cap;
    score += (norm_post - mean_norm) * cap * 0.2;

    // Slight penalty for proliferating bins when many are open with slack.
    if norm_post > mean_norm + 0.3 {
        score += cap * 0.1 * (open_bins_count as f64).sqrt() * (0.3 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tight = 1.0 - (post_residual as f64) / cap_f;
    score -= 45.0 * tight * tight;

    // Harmonic class logic: classify post_residual into residue classes mod 10.
    // Residuals that are "dead zones" (too small for typical items, 1..9) are penalized hard.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr < 10 {
        score += 25.0; // unusable sliver
    } else {
        let class = pr % 10;
        match class {
            0 => score -= 12.0,           // round residual, likely reusable
            1..=3 => score += 6.0,        // awkward small class
            4..=7 => score -= 3.0,        // decent class
            _ => score += 1.0,            // near-round, mildly ok
        }
    }

    // Lookahead coupling: prefer bins whose post_residual either fits next item
    // exactly-ish or is too small to bother.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            // residual can host next item: reward, more if slack is small
            let slack = post_residual as f64 - nx;
            score -= 18.0 * (1.0 - slack / cap_f);
        } else if post_residual < 10 {
            // dead residual, next item goes elsewhere: neutral-ish
            score += 2.0;
        } else {
            // residual stranded: cannot fit next item but not negligible
            score += 10.0 * (post_residual as f64) / cap_f;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is a dead sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if pr >= 10 && next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual >= 10 {
            score += 15.0; // would strand a usable residual anyway
        }
    }

    // New-bin candidate handling: opening a new bin should be discouraged when
    // a decent fit exists, encouraged when all fits are terrible.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its post_residual equals capacity - item_size
        let fresh_waste = post_residual as f64 / cap_f;
        score = 20.0 + 30.0 * fresh_waste;
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0; // fresh bin can chain the next item
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative
        }
    }

    // Mild pressure against bin proliferation as open bins grow.
    score += 0.4 * open_bins_count as f64;

    // Slight progression awareness: late in the stream, prefer closing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are pure waste — penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately for small-but-usable gaps to prefer tighter fits.
    if post_residual > 0 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this bin heavily; if the gap is useless for the next item, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Open-bins pressure: discourage spreading across many bins; prefer filling
    // existing bins, especially when many are already open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., mean residual across open bins is low relative to the item).
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64 + 15.0;
        if decent_fit_exists {
            score += 120.0; // discourage opening a new bin when fits are decent
        } else {
            score -= 20.0; // mildly encourage a fresh bin when fits are poor
        }
    }

    // Mean-residual coupling: placing into a bin whose residual is far below
    // the mean wastes the larger gaps elsewhere; slight penalty.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.4;

    // Stream progression: early on, be more selective about dead space;
    // later, prioritize closing out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item
    if next_item_size > 0 && post_residual == next_item_size {
