    // Next item fits in the residual: strong reward, scaled by how tight the fit is
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 0.5;
    }
    // Next item cannot use the residual: penalize proportionally to dead space
    else if next_item_size > 0 {
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Penalize bins whose residual deviates from the mean (encourage balanced packing)
    score += ((post_residual as f64) - mean_residual).abs() * 0.4;

    // Penalize opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
        // Early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 100.0;
    }

    // Prefer filling bins tightly overall
    score -= (item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for wasted post-residual (dead space), superlinear.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * waste * waste;

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 25.0 / (1.0 + tightness);
    }

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 5 {
        score -= 40.0;
    }

    // Lookahead: if next item fits into the post_residual, reward this bin;
    // otherwise penalize leaving residual that matches nothing.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // extra reward if next item nearly fills the leftover
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 15.0;
            }
        } else {
            score += 10.0;
        }
    } else {
        // Last item: strongly prefer filling a bin as much as possible.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current open bins are mostly full (low mean residual) or few exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_res_norm = mean_residual / bin_capacity as f64;
        // Penalize new bins when open bins still have plenty of room.
        score += 55.0 * mean_res_norm;
        // Slightly favor new bins later in the stream (consolidation phase).
        score += 10.0 * progress;
        // Penalize proliferation of bins.
        score += 2.0 * open_bins_count as f64;
        // If this is the only fitting option, soften the new-bin penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Existing bins: prefer bins with less residual (fill fuller bins first).
        score += 0.15 * (bin_residual as f64 - mean_residual);
        // Mild bonus for reusing bins to keep open_bins_count low.
        score -= 1.5;
    }

    // Progress-aware exploration: early in the stream, allow slightly looser fits
    // to keep options open; later, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate moderate residuals; late in the stream, penalize waste quadratically.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * norm_pr * norm_pr * cap * 0.3;

    // Smooth reward for tight fits (post_residual near zero), stronger as stream progresses.
    let tightness = (-norm_pr * 4.0).exp();
    score -= tightness * (8.0 + 12.0 * progress);

    // Penalize residuals that are awkwardly sized relative to capacity (dead space basin).
    let dead = (norm_pr - 0.35) * (norm_pr - 0.35);
    score += dead * cap * (0.4 + 0.6 * progress);

    // Lookahead coupling: if the next item fits the post-residual, reward smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score -= (-gap * 3.0).exp() * 6.0;
        // If next item won't fit, gently penalize leaving a mid-size hole.
        if nxt > pr {
            score += (nxt - pr) as f64 * 0.05 * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Prefer filling bins when many are open; mild smooth coupling.
    score -= (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // Align with mean residual state: bins below mean residual are "fuller", favor them.
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "harmonic" classes (small
    // fractions of capacity) are good; large awkward remainders are bad.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Integer-division thresholds on post_residual: 10-wide harmonic classes.
    let class = post_residual / 10; // 0..10
    // Penalize mid-range classes (dead space ~ 30..70 is hard to fill),
    // reward near-zero and small residuals.
    let class_penalty = match class {
        0 | 1 => -8.0,
        2 => -3.0,
        3 | 4 | 5 => 6.0,
        6 | 7 => 10.0,
        8 | 9 => 4.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Modulo arithmetic: residuals divisible by small harmonics (5, 10, 20)
    // are more likely to be exactly filled by future items.
    if post_residual % 5 == 0 { score -= 2.0; }
    if post_residual % 10 == 0 { score -= 1.5; }
    if post_residual % 20 == 0 { score -= 1.0; }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item would leave a tiny remainder, also good.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let after2 = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - after2 / cap);
            if after2 > 0.0 && after2 <= 10.0 { score -= 4.0; }
        } else {
            // next item won't fit here: residual becomes temporarily dead
            score += 5.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin gives
    // a tight fit, or when many bins are open and spreading load is fine.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Perfect-fit item into empty bin is great.
        if item_size as f64 / cap > 0.9 { score -= 10.0; }
        // Penalize new bins more when few bins open and residual is small item.
        let tightness = (item_size as f64) / cap;
        score += 14.0 * (1.0 - tightness) * (1.0 - 0.5 * progress);
        // If existing bins are all fragmented (mean residual high relative to item),
        // opening a new bin becomes more attractive.
        if mean_residual > item_size as f64 * 2.0 { score -= 5.0; }
    }

    // Prefer bins whose residual is close to the item (tight fit).
    score -= 4.0 * (1.0 - ((bin_residual - item_size) as f64 / cap).abs());

    // Mild load balancing across many open bins.
    score += 0.3 * ((mean_residual - pr).abs() / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Dead-space avoidance: small unusable gaps are the enemy ---
    // A post_residual that is tiny (but nonzero) is wasted capacity.
    if post_residual > 0 {
        // treat gaps <= 10 (min item size) as fully dead
        if post_residual <= 10 {
            score += 40.0 + (10 - post_residual) as f64 * 3.0;
        } else {
            // smooth dead-space pressure: gaps just above 10 are risky
            score += 15.0 * (10.0_f64 / post_residual as f64);
        }
    }

    // --- Reward tight fits (small post_residual relative to item) ---
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // --- Last chance bin: strongly prefer using it over opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- Lookahead: if the next item fits exactly in post_residual, big reward ---
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot use this gap -> mild penalty for large leftover
            score += 4.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // --- Open bins pressure: discourage hoarding many open bins ---
    score += open_bins_count as f64 * 0.8;

    // --- Mean residual coupling: prefer bins whose residual is below average
    // (concentrate filling into fuller bins, keep larger residuals fresh) ---
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // --- Empty-bin (new bin) candidate handling ---
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 18.0;
        // opening a new bin is more attractive early in the stream or
        // when few bins exist; less attractive when many bins are open
        score -= 6.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        if fitting_bins_count <= 1 {
            // no real alternative exists anyway
            score -= 30.0;
        }
        // if existing bins have large residuals, prefer them over a new bin
        score += 0.3 * mean_residual;
    }

    // --- Perfect fit is unbeatable ---
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportional to wasted space after that
            let waste = post_residual - next_item_size;
            score -= 50.0 * (1.0 - waste as f64 / bin_capacity as f64);
        } else {
            // next item does not fit here; penalize leaving residual smaller than next item
            score += 30.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: leaving less than mean is good (tight packing)
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    score -= (mr - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize large dead space that is hard to fill (residual just below common small sizes)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Mild preference for keeping many bins busy early vs late in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 0 {
        score += progress * 5.0;
    }

    // Prefer filling bins that are already relatively full
    score += (bin_capacity - bin_residual) as f64 * 0.3;

    // New-bin candidate: make it moderately attractive only when current fit is bad
    if bin_residual == bin_capacity {
        // a fresh bin starts with a neutral score of capacity; adjust based on fit quality elsewhere
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty.
    score += (post_residual as f64 / cap).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item could fill this bin's post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / cap);
    }
    // Penalize if next item cannot use the leftover space well.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / cap;
    }

    // Time horizon: early in the stream, be more liberal about opening new bins
    // (keep bins tidy); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (30.0 - 60.0 * progress);

    // If many open bins with slack, prefer filling existing ones over new bins.
    if open_bins_count > 3 {
        score += new_bin * 10.0;
        score -= 3.0 * (mean_residual / cap);
    }

    // Penalize leaving residuals that are too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Core: non-linear polynomial in post_residual, modulated by stream progress
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth progress coupling: late in stream, penalize residual waste more strongly
    score += pr_norm * (0.5 + 1.5 * progress * progress) * 10.0;

    // Reward tight fits (small post_residual) with a smooth quadratic bonus
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (5.0 + 10.0 * progress);

    // Coupling with next item: favor residuals that can host the lookahead item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 4.0 * (1.0 - gap / cap) * (1.0 + next_ratio);
        } else {
            score += 0.02 * gap * gap / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Prefer bins below mean residual (keeps open bins balanced)
    score += 0.03 * (mean_residual - pr) * (1.0 + 0.5 * progress);

    // Mild penalty for spreading across many open bins
    score += 0.1 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: prefer it only when item is large and fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio * fit_ratio;
        score += 12.0 - 10.0 * poor_fit * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let item = item_size as f64;
    let resid = bin_residual as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let horizon = 1.2 - 0.4 * progress; // lookahead matters more early in the stream

    let mut score = post;

    // Harmonic class of the leftover via integer division into eighths of capacity
    let h = (post_residual * 8) / bin_capacity; // 0..=7

    // Class 0: exact / near-exact closure of the bin
    if post_residual == 0 {
        score -= 60.0;
    } else if h == 0 {
        score -= 8.0; // leftover < C/8 : bin practically sealed, excellent packing
    }

    // Awkward harmonic wedges: leftovers just under a half or just under a quarter
    // of capacity are poor building blocks for harmonic pairing
    if h == 3 { score += 3.0; }
    if h == 1 { score += 1.5; }

    // Lookahead chaining: the next item fits into the leftover of this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 14.0 * (1.0 - chain_waste / c) * horizon;
    }

    // Spoiling: this placement destroys room the lookahead item needed, and the
    // next item is large relative to the average open capacity (scarce fit)
    if next_item_size > 0 && !is_new_bin
        && bin_residual >= next_item_size
        && post_residual < next_item_size
        && nxt > mean_residual {
        let scarcity = ((nxt - mean_residual) / c).clamp(0.0, 1.0);
        score += (35.0 + 30.0 * scarcity) * (item / c) * horizon;
    }

    // Last-chance: this is the only open bin that fits; strongly avoid opening a new bin
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: mild tax when open alternatives exist
    if is_new_bin && fitting_bins_count >= 1 {
        score += 6.0;
    }
    // Opening a fresh bin is natural for big harmonic classes (item >= C/2)
    if is_new_bin && item >= c / 2.0 {
        score -= 5.0;
    }

    // Mean-residual pull: reward tighter-than-average fits (order-preserving shrink)
    if !is_new_bin {
        score += 0.25 * (mean_residual - post).max(-20.0).min(20.0);
    }

    // Deterministic harmonic tie-break jitter (harmless)
    score += ((post_residual % 7) as f64) * 0.01 + ((step_index % 5) as f64) * 0.001;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest possible item are pure waste.
    let min_item = 1u32; // unknown distribution: any residual < next plausible size risks waste
    if post_residual < min_item.max(1) {
        score -= 1000.0; // perfect fill
    }

    // Penalize "unusable" gaps relative to the lookahead item: a gap smaller than next_item_size
    // is dead space for the next step (unless it equals 0).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 4.0 * dead;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward gaps that still accommodate the lookahead item exactly-ish
        let slack = (post_residual - next_item_size) as f64;
        score -= 1.5 * (next_item_size as f64) / (1.0 + slack);
    }

    // Tight-fit reward: the closer post_residual is to 0, the better (nonlinear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // New-bin candidate handling: opening a new bin wastes all residual of this fresh bin
    // relative to existing open space; discourage unless all alternatives are poor fits.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: its residual is 100, but it starts clean.
        score = (bin_capacity as f64) + 25.0;
        // Pressure: many open bins already -> prefer reusing them.
        score += 3.0 * open_bins_count as f64;
        // If only this new bin fits (fitting_bins_count == 0 among open bins), allow it.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer bins below mean residual
    // (consolidate space into fewer bins).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.3 * dev;

    // Mild penalty for leaving exactly-mean gaps (avoid fragmentation homogeneity).
    if (post_residual as f64 - mean_residual).abs() < 2.0 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: penalize leaving residuals that cannot host the next item
    // when the leftover is small (dead space), reward if next item fits.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) > post_residual && post_residual < 10 {
            score += 25.0; // tiny dead space
        } else if (next_item_size as u32) <= post_residual {
            score -= 8.0 + 0.1 * nxt; // chain-friendly placement
        }
        // Penalize residuals just below the next item size (worst dead zone).
        if (next_item_size as u32) > post_residual && post_residual >= 10 {
            score += 0.5 * (nxt - post_residual as f64);
        }
    }

    // Prefer filling bins when many bins are open (reduce bin count pressure).
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Reward bins whose residual deviates favorably from the mean (consolidation).
    if !is_new_bin {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Early in stream: be more willing to open new bins for large items
    // (keep flexibility); late: squeeze into existing bins.
    if is_new_bin {
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * fill; // large items justify a new bin
        score += 50.0 * (1.0 - progress); // early stream: new-bin cost higher? invert:
        // Actually early: allow new bins => reduce penalty late; keep moderate.
        score -= 20.0 * progress;
        // Penalize opening a new bin when good alternatives exist.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
    }

    // Slight penalty for near-half residuals (classic awkward waste zone).
    if post_residual >= 40 && post_residual <= 60 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) + 2.0 * norm_pr * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits (small post_residual) with a smooth superlinear term
    score -= 25.0 * (1.0 - norm_pr).powi(3);

    // Penalize opening a new bin when other bins can fit the item
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 35.0 + 20.0 * (fitting_bins_count as f64).ln();
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: prefer residuals that can host the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 12.0 * (ns / cap) * (1.0 + progress);
        } else {
            score += 8.0 * (ns / cap) * (1.0 - norm_pr);
        }
    }

    // Slight preference for fuller bins relative to mean residual of open bins
    score -= 5.0 * ((mean_residual - pr) / cap);

    // Mild consolidation pressure as stream progresses
    score += 10.0 * progress * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits strongly (quadratic penalty on wasted space).
    let waste = post_residual as f64;
    score += 1.2 * waste * waste / bin_capacity as f64;

    // Harmonic class of post_residual: residues that pair well with common
    // small items (multiples of 5/10) are more reusable than odd residues.
    let r = post_residual % 10;
    let residue_bonus: f64 = match r {
        0 => -6.0,
        5 => -3.0,
        1 | 9 => 2.0,
        2 | 8 => 1.0,
        4 | 6 => -0.5,
        _ => 0.5, // 3 | 7
    };
    score += residue_bonus;

    // Integer-division thresholds: a residual that can hold exactly one more
    // "medium chunk" (>=20) is valuable; a residual that can hold nothing
    // usable (< 10) is dead space.
    let usable_chunks = post_residual / 20;
    score -= 2.5 * usable_chunks as f64;
    if post_residual < 10 {
        score += 8.0; // dead space penalty
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here regardless; slight reward for leaving
            // a residue in a harmonic class the future may use.
            score += 1.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // fit is terrible and the item is large (little future flexibility).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (bin_residual - item_size) as f64;
        let threshold = 55.0 - 25.0 * progress;
        if poor_fit > threshold {
            score -= 12.0;
        } else {
            score += 20.0; // prefer existing bins for decent fits
        }
        // Crowding: fewer open bins -> opening one is cheaper.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Mean-residual context: if this bin is far below mean residual, it is
    // already "cramped" — finishing it off is good.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 1.5 * (dev / bin_capacity as f64);
    }

    // Prefer filling bins with high residual first (best-fit-like pressure).
    score += 0.02 * (bin_residual as f64 - post_residual as f64) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps after placement.
    // A residual that is too small to hold any plausible item is pure dead space.
    if post_residual > 0 {
        if post_residual < 10 {
            // Complete dead space: gap smaller than the minimum possible item.
            score += 40.0;
        } else if post_residual <= 20 {
            // Likely dead space: only tiny items (rare) could use it.
            score += 18.0;
        } else if post_residual <= 30 {
            // Marginal gap: useful only for small items.
            score += 7.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 35.0;
    }

    // Reward tight fits relative to the item size: small post_residual
    // compared to item_size means efficient packing.
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += fit_ratio * 12.0;

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // rather than spreading; penalize less when this bin is tight.
    let obp = open_bins_count as f64;
    score += (obp / 20.0) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward leaving that gap; if the gap is awkward for the next item, penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64 - n).abs() < 1.0 {
            score -= 20.0;
        } else if (post_residual as f64) < n && post_residual > 0 {
            // Gap too small for the next item: partial dead space risk.
            score += 8.0;
        } else {
            // Reward leaving a gap that matches the next item reasonably.
            let slack = post_residual as f64 - n;
            if slack <= 20.0 {
                score -= 6.0;
            }
        }
    }

    // Progress-based tuning: later in the stream, be more aggressive about
    // avoiding new dead space since remaining slack matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already tight — favor placing here to close it out.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev.min(50.0) * 0.3;
    }

    // New-bin candidate handling: an empty bin has zero dead space now, but
    // opening new bins should be discouraged unless the current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by open-bin pressure.
        score += 30.0 + obp * 2.0;
        // But if the item is huge and no good fit exists elsewhere, the
        // comparison against tight fits will still favor a new bin when needed.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strongly reward exact fit.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward proportionally to tightness of the pair.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - pair_waste / bin_capacity as f64);
        } else {
            // Next item cannot fit in the residual: penalize dead space,
            // worse when the leftover is tiny (unusable).
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 60.0;
            } else {
                score += 0.5 * dead;
            }
        }
    }

    // Reward tight fits relative to residual (small post_residual is good,
    // unless it's a small dead fragment).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 80.0 * tightness * tightness;

    // Compare against mean residual: bins already tight are precious,
    // prefer to fill loose bins with large items.
    let loose = mean_residual - bin_residual as f64;
    score += 0.3 * loose;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): penalize unless it's a genuinely
    // good anchor for a future pair (large item + large lookahead).
    if bin_residual == bin_capacity {
        score += 90.0;
        if item_size >= 50 && next_item_size >= 30 && post_residual >= next_item_size {
            score -= 250.0;
        }
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 * (1.0 - progress);
    }

    // Mild pressure to keep the number of open bins low.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fit quality: fraction of the bin consumed by this placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill * fill;

    // Perfect/near-perfect fits get a strong bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual < 10 + item_size / 2 {
        score -= 6.0;
    }

    // Dead space penalty: residuals too small for any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // wasted residual relative to the known next demand
            score += 4.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
        // If next item cannot fit anywhere else anyway, mild bonus for this bin
        if post_residual >= next_item_size && next_item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits via post_residual (already)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: penalize placements into bins far from mean residual
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early on, be conservative (keep bins balanced);
    // later, be greedy about tight fits
    score += 6.0 * (1.0 - t) * dev / bin_capacity as f64;
    score -= 10.0 * t * fill;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        let mut new_bin_score = 60.0;
        // More open bins -> opening another is costlier
        new_bin_score += 3.0 * (open_bins_count as f64).ln().max(0.0);
        // Early in the stream, opening new bins is fine (spread load)
        new_bin_score -= 25.0 * (1.0 - t);
        // If existing fit is poor (large post_residual), new bin is attractive
        let worst_fit = post_residual as f64 / bin_capacity as f64; // 1.0 for new bin
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // must open
        } else if post_residual > bin_capacity / 2 && item_size <= bin_capacity / 2 {
            // item leaves lots of usable space in a fresh bin
            new_bin_score -= 15.0;
        }
        // Lookahead: fresh bin accommodates next item comfortably
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 5.0;
        }
        // Late in stream, avoid spawning bins
        new_bin_score += 20.0 * t;
        return new_bin_score;
    }

    // Slight preference for fuller bins among equals
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer minimal post residual, with non-linear reward for tight fits.
    let mut score = post * (1.0 + 0.5 * progress);

    // Smooth quadratic penalty on dead space relative to capacity.
    let dead = post / cap;
    score += 20.0 * dead * dead * cap * 0.01;

    // Reward bins whose residual is close to the item (good fit), smooth coupling.
    let fit_quality = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= 15.0 * fit_quality * fit_quality;

    // If next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new {
        score -= 25.0;
    }

    // Penalize spreading across many open bins mildly as stream progresses.
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize early, allow late when residuals are fragmented.
    if is_new {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap as f64 * (1.2 - 0.4 * progress) - 30.0 * fragmentation * progress;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let post = post_residual as f64;
    let frac = post / cap_f; // fraction of bin left after placement

    // Dead-space penalty: residuals that are tiny are "dead" — waste of capacity
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic reward: residuals that are perfect fractions of capacity
    // (50, 25, 20, 10, 5, 100) are reusable by small items — reward them.
    let harmonics: [u32; 6] = [50, 25, 20, 10, 5, 100];
    for &h in &harmonics {
        if post_residual == h {
            score -= 25.0;
        }
    }

    // Integer division thresholds: post_residual bucketed by divisors of capacity
    let bucket = post_residual / 10; // 0..10 harmonic classes
    score -= 3.0 * (bucket as f64); // larger usable residual preferred (baseline already favors big post_residual)

    // Perfect fit: zero residual is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: penalize small residuals more
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.1;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it's clearly needed
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // cheaper to open when few bins fit the item or item is large
        score -= 20.0 * (fitting_bins_count as f64).min(3.0);
        if item_size >= 50 {
            score -= 15.0;
        }
        // early in stream, opening bins is fine
        if step_index as f64 / (total_items.max(1) as f64) < 0.1 {
            score -= 10.0;
        }
    }

    // Prefer filling bins that are already quite full (small bin_residual)
    score += (bin_residual as f64 - post) * 0.05;

    // Mean residual alignment: placing into bins below mean residual tightens spread
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Modulo class penalty: residuals congruent to awkward classes mod 10
    let m = post_residual % 10;
    if m != 0 {
        score += m as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward very small post_residual.
    if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Strict dead-space avoidance: gaps too small for typical future items
    // are "dead space". Penalize unusable small-but-nonzero gaps.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // If lookahead item can use the post_residual exactly, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    }
    // Post_residual can't hold the lookahead item: it is likely dead space
    // unless it's zero. Penalize proportionally to how small it is.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Open-bin pressure: prefer spreading load when few bins are open,
    // prefer filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when no open bin is a decent fit
        // (poor fits leave large dead space) or when bins are saturated.
        let mean_fit_quality = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open new bin
        } else if mean_fit_quality > 0.5 || open_bins_count > 12 {
            score -= 5.0;
        } else {
            score += 10.0; // keep using existing bins when fits are decent
        }
    }

    // Mild alignment with mean residual: bins far from mean residual are
    // either nearly full (good) or oddly empty; nudge toward fullness.
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's post-residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
        // Extra reward if this was the only bin able to host the current item anyway.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }
    }

    // Near-match: post-residual can hold next item with small slack -> good chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.6 * slack.min(60.0);
    }

    // Penalize dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        score += 0.5 * dead;
    }

    // Tight fit reward: small post-residual is generally good.
    score -= 0.3 * (bin_capacity - post_residual) as f64;

    // Last-chance bonus: only bin that fits the item; avoid opening new bins unnecessarily.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: opening a new bin is only attractive when existing residuals are large
    // and the current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > (bin_capacity as f64 * 0.5);
        if poor_fit || fitting_bins_count == 0 {
            score -= 40.0 + mean_residual * 0.2;
        } else {
            score += 150.0 + mean_residual * 0.5;
        }
    }

    // Mild pressure toward consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Penalize leaving residual smaller than the smallest plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize blocking the next item if its size is small enough that residual could have held it.
        if post_residual > 0 && next_item_size <= bin_residual {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins are already open and mean residual is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_fit_waste = (mean_residual - item_size as f64).abs();
        score += 10.0 + 20.0 * progress + 0.5 * open_bins_count as f64 + 0.3 * mean_fit_waste;
    }

    // Mild preference for bins with residual close to mean (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste coupling: quadratic penalty on residual, amplified by stream progress.
    let norm_post = post / cap;
    score += 18.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth saturating term.
    score -= 25.0 * (-norm_post * 6.0).exp();

    // Lookahead: if next item fits the post residual, strongly reward.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fill = next_item_size as f64 / post.max(1.0);
        score -= 14.0 * fill * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Penalize residuals that cannot host the next item (dead space risk).
        let gap = (next_item_size as f64 - post) / cap;
        score += 10.0 * gap * gap;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Discourage spreading across too many open bins late in the stream.
    score += (open_bins_count as f64).ln() * 2.0 * progress;

    // Prefer bins below mean residual (keeps balance) with smooth coupling.
    score += 3.0 * (mean_residual - post) / cap;

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score = cap - 30.0 * tightness * (1.0 - progress) + 12.0 * progress * (fitting_bins_count as f64);
        if fitting_bins_count > 0 {
            score += 8.0; // bias toward reusing existing bins by default
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals that are multiples of small harmonic classes (e.g. 10, 25, 50)
    // tend to pair well with common item sizes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill of the bin after placement: reward high fill.
    let fill = (cap - pr) / cap;
    score -= 30.0 * fill * fill;

    // Dead-space penalty: post_residual too small to ever host typical items.
    if post_residual < 10 {
        score -= 50.0; // perfect closure — excellent
    } else if post_residual <= 20 {
        score -= 10.0; // still usable by small items
    } else if post_residual < 40 {
        score += 5.0;  // awkward dead zone
    }

    // Harmonic class check: post_residual divisible by 10 is more reusable.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let tight = nxt / pr;
            if tight > 0.7 {
                score -= 15.0 * tight;
            } else {
                score += 4.0 * (1.0 - tight);
            }
        } else {
            // next item cannot fit here; slight penalty if this bin becomes a dead bin
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the current item
    // is large relative to capacity and existing residuals are small.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 / cap;
        // Base penalty so new bins are chosen only when justified.
        let mut nb = 20.0 + 25.0 * progress;
        if big_item > 0.6 && pressure < 0.25 {
            nb -= 30.0; // large item, no roomy bins -> open new bin
        }
        if fitting_bins_count == 0 {
            nb -= 100.0; // no alternative anyway
        }
        if post_residual % 10 == 0 {
            nb -= 2.0; // clean new-bin residual
        }
        score += nb;
    }

    // Mild tie-break by mean residual alignment: prefer bins whose residual
    // is close to the mean (keep the pool homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a minimum item (size >= 1, but practically small gaps below
    // ~10 are wasted) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Moderately awkward gap: penalize proportionally.
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward bins whose residual tightly matches the item (good fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        // Next item would leave dead space here: mild penalty.
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits and leaves usable space: reward.
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing
    // ones over opening new bins (penalize the empty new-bin candidate).
    if bin_residual == bin_capacity {
        score += 120.0 + open_bins_count as f64 * 25.0;
        // Early in stream, new bins are cheaper to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 60.0;
    }

    // Slight preference for bins below mean residual (balance load).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residuals too small for the smallest possible item are wasted.
    if post_residual < 1 {
        score += 1000.0;
    } else if post_residual < 10 {
        score += 8.0; // small dead space
    }

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; penalize it
    // unless all existing bins are poor fits (large residuals wasted).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            -100.0
        } else {
            let avg_waste = mean_residual - item_size as f64;
            // penalize new bin when open bins can reasonably absorb the item
            15.0 + 0.5 * avg_waste.max(0.0) - 2.0 * (fitting_bins_count as f64)
        };
        score += 50.0 + pressure + 0.3 * open_bins_count as f64;
    }

    // Slight preference for bins below mean residual (consolidate emptier space usage).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild time-horizon scaling: early in stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - (pr / cap).powf(2.0);
    score -= tightness * (1.0 + progress * 8.0) * (1.0 + progress * 4.0);

    // Penalize large residuals quadratically, scaled by mean residual context:
    // avoid creating dead space larger than the typical leftover.
    let excess = (pr - mean_residual).max(0.0);
    score += (excess / cap).powf(2.0) * 20.0;

    // Lookahead coupling: reward bins whose post_residual could host the next item,
    // with a smooth polynomial in the ratio of next item to post residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let ratio = n / pr;
            score -= (1.0 - (ratio - 0.5).powf(2.0) * 2.0) * (3.0 + progress * 5.0);
        } else {
            // post_residual too small for next item: mild penalty growing smoothly
            score += ((n - pr) / cap) * 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (penalize the new-bin alternative implicitly).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + progress * 6.0;
    }

    // New-bin candidate: smooth penalty that grows with stream progress and open bins,
    // so we prefer existing bins unless their fit is poor; relax slightly early on.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        score += 10.0 + progress * 10.0 - scarcity * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "small" classes (0..=10 dead space is fine)
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit
    } else if pr <= 10 {
        score -= 30.0;
    } else {
        // penalize dead space non-linearly, worse if it cannot host a small future item
        let dead = pr as f64 / cap_f;
        score += 20.0 * dead * dead;
    }

    // Modulo class: residuals that are multiples of common item sizes (10..=80 step 10) are reusable
    let harmonic = pr % 10 == 0 && pr > 0;
    if harmonic {
        score -= 12.0;
    }
    // residual matching next item size exactly is gold
    if next_item_size > 0 && pr == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && next_item_size <= pr {
        score -= 6.0; // next item still fits here
    } else if next_item_size > pr {
        score += 5.0; // next item won't fit: this bin becomes dead
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64).ln() + 1.0;
        score = cap_f * 0.5 + 25.0 * pressure * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Mild preference for tighter bins overall
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize residuals that cannot fit the next item (lookahead), rewarding bins
    // whose leftover space remains useful for the k=2 lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Tight fits are rewarded: post_residual close to zero is good.
    score -= (bin_capacity - post_residual) as f64 * 0.3;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and discourage opening new bins.
    score += open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        score += 25.0; // penalize new bin unless other signals dominate
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mean residual coupling: if mean residual across open bins is high,
    // prefer bins below mean (consolidate large gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 6.0;
    }

    // Progress coupling: later in stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            // next fits, but leftover dead space after that placement
            let dead = post_residual - next_item_size;
            score -= 100.0 - dead as f64 * 0.8;
        } else {
            // next item cannot use post_residual: dead space penalty
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // last item: minimize post_residual aggressively
        score += post_residual as f64 * 2.0;
    }

    // Penalize large post_residual relative to mean residual (wasteful placement)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    // Reward filling bins tighter than average residual
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening new bins unless current best fit is poor
    if bin_residual == bin_capacity {
        score += 150.0;
        // allow new bin if lookahead dead space in existing bins would be huge
        if next_item_size > 0 && post_residual >= bin_capacity {
            score -= 300.0;
        }
        // late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Slight penalty for scattering across many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness * tightness;

    // Penalize large dead space that can only hold tiny future items.
    if post_residual < 10 {
        score -= 25.0; // perfectly sealed bin, great outcome
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, this is a great placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > bin_capacity {
        score += 0.0; // malformed lookahead, ignore
    } else if next_item_size > 0 {
        // next item won't fit here; penalize slightly more if this bin was its only option
        let waste = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.15 * waste;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: prefer consolidation into already-open bins over opening new ones.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it's a "ragged" bin —
    // prefer filling ragged bins to keep the fleet uniform.
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev;

    // Time horizon: early in stream, be picky about perfect fits; late in stream,
    // just close out bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tightness;

    // New-bin candidate: only attractive when nothing fits well anywhere.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        let poor_alternatives = (fitting_bins_count as f64).ln().max(0.0);
        score = 45.0 + 10.0 * poor_alternatives - desperation
            + 0.3 * item_size as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, scaled by a smooth progress-dependent exponent-like factor
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Non-linear polynomial coupling of post_residual with progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 20.0 * coupling * coupling;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: penalize wasting space needed by the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).max(0.0);
        score -= 8.0 * (1.0 - gap / cap);
        if pr < nxt {
            score += 12.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty when many bins are open and residual is far above mean (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (open_bins_count as f64).sqrt() / (1.0 + progress);

    // New-bin candidate: make empty bin moderately attractive only when it beats bad fits
    if bin_residual == bin_capacity {
        score = 45.0 - 10.0 * progress - (item_size as f64) * 0.2;
        if fitting_bins_count == 1 {
            score += 60.0; // discourage opening new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" small-residue classes (divisible nicely) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // reward residuals that are multiples of common item granules
        for g in [10u32, 20, 25, 50] {
            if pr % g == 0 {
                score -= 3.0;
            }
        }
        // dead zone: residuals of 1..9 are nearly unusable
        if pr < 10 {
            score += 12.0 * (10 - pr) as f64;
        }
    } else {
        score -= 15.0; // perfect fill
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let new_res = pr - next_item_size;
            score -= 6.0;
            if new_res < 10 { score += 4.0; }
        } else {
            // next item won't fit here; slight penalty if post residual is large
            score += 0.05 * (pr as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fill * fill;

    // New-bin candidate handling: opening a new bin wastes capacity equal to
    // mean_residual of all open bins; penalize unless open bins are crowded
    // or the fit elsewhere is terrible.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let waste = mean_residual.max(0.0);
        // base cost of a fresh bin
        score = cap * 0.6 + waste * 0.5;
        // late in the stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // many open bins -> allow opening new ones
        score -= 1.5 * crowd;
        // if no open bin can fit at all, opening is mandatory
        if fitting_bins_count == 0 {
            score -= cap;
        }
        // big items justify fresh bins
        if item_size >= 50 { score -= 15.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (sizes >= 1, but small gaps < 12 are nearly unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 * (1.0 - post_residual as f64 / 12.0);
    }

    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Reward tight fits relative to capacity.
        let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 15.0 * tightness;
    }

    // If the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Exact two-item chain closure.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_capacity && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from many open bins: discourage spreading across bins when
    // the bin count is high; encourage consolidation.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when no open bin fits well or the
    // item is large enough that a fresh bin is a good home.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is required
        } else {
            // Prefer a fresh bin for large items that would leave a clean residual.
            let clean = bin_capacity - item_size;
            if clean == 0 {
                score -= 40.0;
            } else if clean < 12 {
                score += 20.0; // would create dead space immediately
            } else {
                score += 5.0 + 0.5 * open_bins_count as f64;
            }
        }
    }

    // Mild late-stream tightening: as the stream progresses, favor tighter fits.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * tightness_factor(post_residual, bin_capacity);
    }

    score
}

#[inline]
fn tightness_factor(post_residual: u32, bin_capacity: u32) -> f64 {
    1.0 - post_residual as f64 / bin_capacity as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // perfect chain: both items fill the bin
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // prefer bins whose leftover after next item is small
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow in this bin: penalize proportionally to wasted capacity
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare post_residual to mean residual: favor bins left with below-average residual
    // (tight packing) unless it creates dead space relative to typical item sizes.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    score += 0.3 * (post_residual as f64 - mean_r) * (1.0 - progress);

    // Penalize small unusable dead space (below minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual would be huge, i.e., item small relative to capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; softened if many bins already open (consolidation phase)
        score = bin_capacity as f64 - 50.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= post_residual {
            // next item can also go in a fresh bin: slightly more attractive
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: how far through the stream we are.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of the fit.
    let tightness = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits nonlinearly (dead space avoidance).
    score -= 30.0 * (1.0 - tightness).powi(3);

    // Penalize large dead space quadratically.
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; slightly penalize wasting residual.
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity - item_size) as f64;
        let global_pressure = if mean_residual > 0.0 { item_size as f64 / mean_residual } else { 1.0 };
        // Base cost of opening a new bin.
        score += 55.0;
        // If no bins fit or mean residual is far below item, opening is more attractive.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if global_pressure > 1.5 {
            score -= 30.0 * (global_pressure - 1.5).min(2.0);
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 20.0 * (1.0 - progress);
        // Discourage opening when item is small relative to capacity.
        score += 0.3 * poor_fit;
        let _ = open_bins_count;
    }

    // Mild preference for filling bins with high residual when many bins are open.
    if open_bins_count > 3 {
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, in [0,1])
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear coupling of post_residual with progress:
    // early in the stream, tolerate leftover space; late in the stream,
    // penalize residuals quadratically (dead space becomes costly).
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    score += (0.5 + 2.0 * progress) * norm_pr * norm_pr * bin_capacity as f64;

    // Smooth coupling: residual deviation from the mean residual across open bins.
    // Bins whose post-residual deviates strongly from the fleet mean create
    // fragmented, hard-to-fill space — penalize smoothly.
    let dev = (pr - mean_residual) / bin_capacity as f64;
    score += 12.0 * dev * dev * (0.5 + progress);

    // Lookahead (k=2): reward bins whose post-residual can accommodate the next item,
    // with a smooth saturating interaction term.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / bin_capacity as f64;
            score -= 18.0 * (1.0 - slack) * (0.3 + progress);
        } else {
            // Post-residual cannot fit the lookahead item: smooth penalty
            // proportional to how far short it falls.
            let miss = (n - pr) / bin_capacity as f64;
            score += 25.0 * miss * (0.5 + progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly reward using it
    // (smoothly scaled by how tight the fit is).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 30.0 * (0.5 + 0.5 * tightness);
    }

    // New-bin candidate (empty bin): penalize opening a new bin, but the penalty
    // decays smoothly with stream progress and with the number of open bins,
    // so late in the stream or with many fragmented bins, a fresh bin becomes viable.
    if bin_residual == bin_capacity {
        let decay = (-3.0 * progress).exp();
        let crowd = (open_bins_count as f64).ln_1p();
        score += 35.0 * decay / (1.0 + crowd) - 20.0 * progress;
    }

    // Mild reward for tight fits overall (smooth, non-linear in fill ratio).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals in "awkward" classes (just under half / just under capacity)
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual <= 20 {
            score += 25.0; // small dead zone
        } else if post_residual <= 30 {
            score += 8.0;
        }
    }

    // Modulo/harmonic threshold coupling with next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        // residual can host the lookahead item: reward harmonic nesting
        let nesting = (post_residual - next_item_size) as f64;
        score -= 15.0 + 0.3 * nesting;
        // extra reward if residual matches next item exactly or within harmonic class
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size >= 10 && post_residual % 10 == next_item_size % 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space relative to lookahead: penalize proportionally
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Integer-division thresholds on post_residual
    let q = post_residual / 25; // quarter classes
    match q {
        0 => score += 10.0,
        1 => score -= 4.0,
        2 => score -= 10.0,
        _ => {}
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Crowding pressure: many open bins -> prefer tighter fills
    score += 0.05 * open_bins_count as f64 * frac;

    // Progress term: late in stream, tolerate larger residuals less
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible = if fitting_bins_count > 1 { 0.0 } else { 1.0 };
        score = 100.0 - 30.0 * best_possible + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 20.0; // new bin can host pair
        }
    }

    // Mild preference for bins whose residual deviates from mean (consolidation)
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize "dead space": small unusable gaps that no typical item can use.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(60) } else { 40 };
    if post_residual > 0 && post_residual < dead_threshold {
        let severity = (dead_threshold - post_residual) as f64 / dead_threshold as f64;
        score += 25.0 * severity * severity;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0; // gap too small for next item
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // but allow it early when few bins exist.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 3.0 * (open_bins_count as f64).ln().max(0.0) * (0.4 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        score += 10.0 + pressure;
        // Opening a new bin is fine if no existing bin fits well.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        // If only poor fits exist (large dead space elsewhere), new bin competitive.
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.35 {
            score -= 8.0;
        }
    } else {
        // Reward reusing bins, scaled by how average this bin's residual is.
        let residual_gap = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * residual_gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (low post residual).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: strongly reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact chain fit is ideal.
            let slack = post_residual - next_item_size;
            score -= 40.0 + (bin_capacity as f64 - slack as f64) * 0.5;
        } else {
            // Penalize dead space that cannot host the next item,
            // scaled by how much of the bin is wasted.
            let dead = post_residual as f64;
            score += dead * 0.8;
            // Small dead spaces are especially useless.
            if dead <= next_item_size as f64 {
                score += 20.0;
            }
        }
    }

    // Compare post residual against mean residual of open bins:
    // favor bins that end up tighter than average (good consolidation),
    // penalize bins left much emptier than average.
    if open_bins_count > 0 {
        let diff = post_residual as f64 - mean_residual;
        score += diff * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New empty bin candidate: penalize opening a new bin unless the item is large
    // relative to existing residuals or we are early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 100.0 - 200.0 * large_item - 50.0 * (1.0 - progress);
        // Opening a new bin is attractive if no open bin can chain the next item well.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared residual pressure.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - chain_quality / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that cannot serve the lookahead item.
        score += 4.0 * (next_item_size as f64 - post_residual as f64).min(bin_capacity as f64) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when existing
    // residuals are fragmented (mean residual low relative to item needs).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bins normally; relax penalty when open bins are too full on average.
        let mut new_bin_penalty = 30.0 - 22.0 * (1.0 - fragmentation);
        new_bin_penalty *= 1.0 - 0.3 * progress; // slightly cheaper to open bins later
        score += new_bin_penalty.max(2.0);
        // Opening a bin is better if the item leaves a nicely reusable residual.
        score -= 8.0 * (1.0 - tightness);
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 3.0 * (open_bins_count as f64).sqrt();
    }

    // Global balance: mildly prefer bins whose residual deviates from the mean
    // (consolidate waste into fewer bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more.
    let tight = (pr / cap).powi(2);
    score += tight * (1.0 + 3.0 * progress) * 10.0;

    // Cubic penalty on wasted space normalized by capacity, damped early.
    score += (pr / cap).powi(3) * 40.0 * (0.5 + progress);

    // Reward filling a bin completely (smooth exponential reward).
    score -= (1.0 - pr / cap).exp() * 8.0;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit, more so mid/late stream.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 15.0 + 30.0 * progress * fit_pressure;
        // Allow new bin if post_residual of existing fits would be large.
        score += 0.0;
    } else {
        // Prefer bins whose residual deviates favorably from mean residual.
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // Lookahead: if next item fits exactly into this bin's post_residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            score -= (1.0 - gap / cap).exp() * 6.0;
        } else {
            score += (nxt - pr) / cap * 5.0;
        }
    }

    // Mild penalty for proliferating open bins early (encourage consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "useless"
    // (small, non-representable by typical item sizes) get penalized.
    let pr = post_residual;
    if pr > 0 {
        // dead-space penalty grows steeply for tiny residuals
        if pr < 10 {
            score += 60.0 * (10 - pr) as f64;
        }
        // modulo classes: residuals divisible by 10 are friendlier
        let m10 = pr % 10;
        score -= 8.0 * (10 - m10) as f64 * 0.0; // placeholder harmonic anchor
        score += 4.0 * m10 as f64;

        // integer division thresholds: big buckets of residual are good
        let bucket = pr / 20; // 0..5
        score -= 6.0 * bucket as f64;
    } else {
        // perfect fit: reward strongly
        score -= 100.0;
    }

    // Fullness fraction: favor bins whose residual fraction is a "harmonic" of capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac * frac;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if next item fits the post-residual exactly or nearly, reward
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack < 10 {
            score -= 40.0; // near-perfect chain
        } else {
            score -= 15.0 * (slack as f64 / bin_capacity as f64);
        }
        // harmonic class match: both divisible by 10
        if pr % 10 == 0 && next_item_size % 10 == 0 && (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here; penalize leaving awkward space
        score += 8.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the current
    // fit is truly terrible (large post-residual waste) and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base cost of a new bin, discounted early in the stream
        score = 55.0 + 60.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big next item justifies fresh space
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64;
    score += 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the closer post_residual is to 0, the better.
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(6);

    // Strict dead space avoidance: penalize small unusable gaps (1..=12).
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 + (12 - post_residual) as f64 * 4.0;
    }

    // Penalize medium gaps that are unlikely to be filled by typical items.
    if post_residual > 12 && post_residual < 25 {
        score += 8.0;
    }

    // If the next item fits exactly into the resulting residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 8 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }
    // Next item does NOT fit in the residual: penalize proportionally.
    if next_item_size > post_residual {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones
    // (handled implicitly since new-bin candidate has post_residual == capacity),
    // but also discourage spreading residual too thin.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.5;
    } else {
        // New-bin candidate: base cost of opening a new bin, modulated by
        // how poorly the item fits existing bins and stream progression.
        let mut new_bin_cost = 25.0 + (open_bins_count as f64) * 1.5;
        if fitting_bins_count == 0 {
            new_bin_cost -= 30.0; // no alternative
        }
        // Late in stream, prefer reusing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_cost += 15.0 * progress;
        // If item is large, a fresh bin is more valuable.
        new_bin_cost -= (item_size as f64) * 0.2;
        score = score.max(new_bin_cost);
    }

    // Mild alignment with mean residual: prefer bins whose residual is near mean
    // to keep balance, slight effect.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: reward post_residual that exactly matches next item ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            // Perfect 2-step fit: the next item exactly fills this bin afterwards.
            score -= 60.0 + 20.0 * progress;
        } else if post_residual > next_item_size {
            // Next item still fits: reward closeness of the resulting second residual.
            let second_residual = post - nxt;
            // Reward leaving a second residual that is either 0 or large/reusable.
            if second_residual == 0.0 {
                score -= 50.0;
            } else {
                // Penalize tiny unusable leftovers after the next item.
                if second_residual < 10.0 {
                    score += (10.0 - second_residual) * 2.5;
                }
                // Mild reward for leaving a large reusable gap.
                score -= (second_residual / bin_capacity as f64) * 10.0;
            }
        } else {
            // Next item won't fit here afterwards: penalize small dead leftovers.
            if post_residual > 0 && post_residual < 10 {
                score += (10.0 - post) * 3.0;
            }
            // Slight penalty scaling with how badly the lookahead misses.
            score += (nxt - post) * 0.15;
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual already in base score).
        score -= 5.0;
    }

    // ---- Mean-residual coupling: prefer bins whose residual deviates toward item size ----
    let residual_f = bin_residual as f64;
    let deviation = residual_f - mean_residual;
    // Bins with residual close to item_size give near-perfect fits; reward that.
    let fit_gap = (residual_f - item_size as f64).abs();
    score += fit_gap * 0.30;
    // Reward bins that are tighter than average (they need consolidation).
    if deviation < 0.0 {
        score += deviation * 0.10; // deviation negative -> subtracts score
    }

    // ---- Last-chance bonus: if this is the only fitting bin, strongly favor using it ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no good fit exists:
        // make it costly unless existing fits are terrible.
        let bad_fit_penalty = if fitting_bins_count == 0 {
            -100.0 // must open a new bin
        } else {
            // Cost of a fresh bin: proportional to wasted capacity vs. item size.
            (bin_capacity - item_size) as f64 * 0.55
        };
        score = (bin_capacity - item_size) as f64 + bad_fit_penalty;
        // Late in the stream, discourage opening extra bins even more.
        score += progress * 15.0;
    }

    // Small stabilizing term: mildly prefer bins with low residual (tight packing).
    score += residual_f * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: post_residual that cannot host the next item is dead space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.9 * waste;
        } else {
            // Bonus: bin remains usable for the lookahead item.
            score -= 6.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        }
    } else {
        // Last item: minimize post_residual aggressively.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 14.0;
    }

    // New-bin candidate handling: empty bin gets baseline penalty that shrinks
    // as stream progresses or when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1)).min(10.0);
        score = bin_capacity as f64 * (1.0 - 0.25 * progress) - 8.0 * fragmentation.min(4.0);
        // If no open bin fits well, opening a new bin is attractive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight preference for bins below mean residual (consolidate fullness).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Mild penalty for many open bins with this bin nearly empty.
    if open_bins_count > 1 && (post_residual as f64) > mean_residual {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize leftover space, but with non-linear shaping so tiny
    // residuals are strongly preferred and mid-range residuals are softened.
    let mut score = 100.0 * (x * x) - 60.0 * (x * x * x);

    // Smooth stream-progress coupling: later in the stream, tight packing
    // matters more, so amplify the residual penalty polynomially.
    let prog_coupling = 1.0 + 1.5 * progress * progress;
    score *= prog_coupling;

    // Reward using up space that matches the item size (non-linear fill term).
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * (1.0 - x) * (1.0 - x);

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if it nearly fits (small gap), penalize creating a dead sliver.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            let g = gap / cap;
            score -= 25.0 * (1.0 - g * g); // next item fits: bonus, larger for exact fit
        } else {
            let miss = (-gap) / cap;
            score += 20.0 * (1.0 - miss) * (1.0 - miss); // near-miss dead space penalty
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // mild preference for bins among many candidates with tighter fit
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Penalize bins far from the mean residual (prefer homogeneous packing),
    // with a smooth quadratic divergence term scaled by open bins count.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (open_bins_count as f64).sqrt();

    // New-bin candidate: prefer opening a new bin only when it is early in the
    // stream or residuals are large; otherwise make it unattractive.
    if bin_residual == bin_capacity {
        let openness = (1.0 - progress) * (1.0 - progress);
        score = 60.0 + 50.0 * openness - 20.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual
    let pr = post_residual as f64;
    score -= 24.0 * ((1.0 - pr / bin_capacity as f64) * (1.0 - pr / bin_capacity as f64));

    // Harmonic class of post_residual: mod-10 classes (capacity fraction buckets)
    let class = (post_residual % 10) as f64;
    score += 2.0 * class; // prefer post-residuals in low residue classes (aligns with common item sizes)

    // Integer-division threshold: post_residual >= 10 means another item could still fit
    if post_residual >= 10 {
        score -= 8.0;
    } else {
        score += 12.0; // dead space penalty: nothing in [1,100] range can be assumed small enough
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 20.0; // perfect two-item closure
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0; // next item won't fit here; slight penalty
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 40.0; // fresh bin guarantees room for the large next item
        }
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced packing)
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Late-stream consolidation: as stream progresses, prefer filling existing bins harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (pr / bin_capacity as f64);

    // Modulo threshold on item_size classes: odd/even harmonic nudges
    if item_size % 20 == 0 {
        score -= 3.0; // round-class items pack predictably; small extra reward
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // future item are "dead" — penalize them heavily and non-linearly.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.12);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit bonus: reward very tight placements.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 8.0;

    // If the next item would fit exactly in the post-residual, strongly favor
    // this bin (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't follow here; mild penalty if post_residual wasted.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidating into ones
    // with large residuals; also make new bins less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 5.0 + pressure;
        // But allow a new bin when no good fit exists (large item, small gaps).
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Slight preference for bins whose residual deviates from mean residual
    // toward being consumed (balance across bins).
    score += ((mean_residual - post_residual as f64).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward near matches: next item fits snugly into the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * snug;
    }

    // Penalize dead space that the next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.3 * waste;
    }

    // Penalize large post residuals relative to mean residual (poor compaction)
    if post_residual as f64 > mean_residual {
        score += 0.4 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent existing options exist
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 && post_residual < 20 {
            score += 15.0; // avoid wasting a fresh bin on tiny leftover
        }
        score += 10.0; // base preference for filling existing bins
    }

    // Slight early-stream bias toward keeping bins tight (build good structure)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: heavily favor placements leaving small residuals.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // penalize residuals too small for the next item (dead space risk).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward if next item would fill residual almost exactly.
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Residual likely wasted unless small enough to be negligible.
            if post_residual > 20 {
                score += 8.0;
            }
        }
    }

    // Penalize creating many small fragmented residuals when bin count is high.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    // Prefer bins below mean residual (consolidate emptier space first).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large (leaving a usable residual) or no real alternative exists.
    if bin_residual == bin_capacity {
        score += 55.0; // default penalty for opening a new bin
        // Large items leave big residuals that pair well with future items.
        if item_size >= 50 {
            score -= 30.0;
        }
        if item_size >= 80 {
            score -= 15.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to pair).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If many bins can fit, strongly discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // Late in the stream, prefer closing out existing bins.
        if progress > 0.8 {
            score += 15.0;
        }
    }

    // Mild penalty for very loose fits (wasting more than half the bin).
    if item_size * 2 < bin_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64 / bin_capacity as f64;
    let mut score = r * r * (1.0 + 2.0 * t) * bin_capacity as f64;
    // reward tight fits more strongly as stream progresses
    score -= (1.0 - r).powi(3) * (1.0 + t) * 30.0;
    // penalize last-chance bin waste lightly
    if fitting_bins_count == 1 { score -= 5.0; }
    // lookahead coupling: if next item fits post-residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= r * bin_capacity as f64 {
        score -= 8.0 * (1.0 - (next_item_size as f64 / (r * bin_capacity as f64 + 1.0))).abs();
    }
    // smooth deviation from mean residual
    score += ((r * bin_capacity as f64 - mean_residual) / bin_capacity as f64).powi(2) * 10.0 * (1.0 - t);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into
    // capacity-fraction buckets (1/8 granularity). Small classes are good.
    let class = (post_residual * 8) / bin_capacity; // 0..=8
    score += match class {
        0 => -40.0,                 // perfect fit
        1 => -25.0,                 // tiny remainder, very usable
        2 => -10.0,
        3 => 5.0,
        4 => 15.0,                  // half-empty: mediocre
        5 => 25.0,
        6 => 30.0,
        7 => 20.0,                  // almost empty bin: still flexible
        _ => 0.0,
    };

    // Exact-fit bonus via modulo arithmetic on residual.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;              // round residual likely reusable
    } else if post_residual < 10 {
        score += 10.0;              // dead space below min item size
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let snug = (post_residual - next_item_size) as f64;
            score -= 30.0 - snug * 0.5;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Harmonic pairing: item + next exactly fills bin.
        if item_size + next_item_size == bin_residual {
            score -= 45.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when the current item
    // is large relative to capacity and fits are plentiful/wasteful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (post_residual as f64) - 0.0;
        score = cap - item_size as f64; // baseline: new bin has full residual
        // Penalize opening new bins early or when many bins are open.
        score += open_bins_count as f64 * 2.0;
        score -= progress * 10.0;
        if item_size >= 60 {
            score += 25.0;          // big item: prefer existing bin if possible
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
            // pairing potential in fresh bin
            score -= 8.0;
        }
        let _ = waste;
    }

    // Slight tie-break toward consolidating into fewer bins.
    score += mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful are costly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item could exactly use the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 30.0 + 8.0 * open_bins_count as f64;
        // But if no open bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Allow new bin if mean residual is small (existing bins nearly full).
        if mean_residual < 15.0 {
            score -= 60.0;
        }
    } else {
        // Slight reward for using existing bins, scaled by open-bin pressure.
        score -= 2.0 * open_bins_count as f64;
    }

    // Mild stream progression coupling: later in stream, be more conservative.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: reward exact match of post_residual
    // to the next item size (perfect chain), scaled by lookahead value.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff < 0.5 {
            // Perfect pairing: subtract a large bonus proportional to lookahead size.
            score -= 60.0 + 0.5 * nxt;
        } else {
            // Penalize mismatch relative to lookahead; small dead space is worse
            // when it can't host the next item.
            score += diff * 0.35 + (nxt - post).max(0.0) * 0.25;
        }

        // If post_residual can still fit the item after next (3-step chain), reward.
        if post >= nxt + item_size as f64 {
            score -= 10.0;
        }
    }

    // Tight fits are good: reward small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness;

    // Compare against mean residual: filling a bin below-average residual is good.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when decent open bins exist, more so early in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64;
        score += 25.0 + 8.0 * pressure * (1.0 - progress);
    }

    // Mild penalty for large item relative to residual (near-full bin usage is fine,
    // but avoid leaving tiny unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: post_residual that cannot hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 3.0 * (next_item_size - post_residual) as f64;
        } else {
            // Reward residuals that still accommodate the lookahead item.
            score -= 1.5;
        }
        // Bonus if this placement leaves room exactly usable by next item.
        if post_residual == next_item_size {
            score -= 4.0;
        }
    } else {
        // Last item: prefer filling a bin as fully as possible.
        score -= 5.0 * tightness;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 10.0;
        // More attractive early (long horizon to amortize the bin).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 12.0 * (1.0 - progress);
        // Attractive when many open bins already exist (fragmentation).
        score -= 0.4 * open_bins_count as f64;
        // Attractive when mean residual of open bins is low (poor global fit).
        score -= 0.15 * mean_residual;
        // Large items prefer a fresh bin to avoid fragmentation elsewhere.
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
        // If next item is large, fresh bin with room is valuable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    } else {
        // Mild penalty for spreading across many bins when residuals are large.
        if (bin_residual as f64) > mean_residual + 20.0 {
            score += 2.0;
        }
    }

    // Progress-based consolidation: late in stream, prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Smooth progress coupling: late in stream, waste penalized more heavily
    score *= 1.0 + 0.25 * progress * norm_pr;

    // Reward tight fits with smooth saturating term
    let fit_quality = 1.0 - norm_pr;
    score -= 6.0 * fit_quality * fit_quality * fit_quality;

    // Lookahead: reward leaving space for the next item (smooth kernel)
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= 4.0 * (-diff / 20.0) * (-diff / 20.0);
    } else if next_item_size > post_residual {
        score += 2.5 * ((next_item_size - post_residual) as f64 / cap);
    }

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 8.0;
    }

    // Penalize opening new bins when decent fits exist, more so early
    score += is_new_bin * (5.0 + 8.0 * (1.0 - progress));

    // Slight bonus for using bins with larger residuals (consolidation)
    score -= 0.03 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are more likely to be sealed by future items.
    let pr = post_residual;
    let class = pr / 10; // integer division: 10-wide residue classes
    let class_bonus = match class {
        0 => 14.0,           // near-perfect seal (0..9)
        1 => 9.0,            // excellent
        2 => 5.0,
        3 => 2.0,
        4 => 0.0,
        5 => -2.0,           // mid-range residual, mildly wasteful
        6 => -4.0,
        7 => -6.0,
        _ => -8.0,           // large dead space
    };
    score -= class_bonus;

    // Exact-fill harmonic: modulo classes of residual vs item
    if pr == 0 {
        score -= 25.0;
    } else if bin_residual % 10 == 0 && item_size % 10 == 0 && bin_residual % item_size == 0 {
        // residual is an exact multiple of item size -> likely future exact fill
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when this bin would leave bad residue
    // or when the current bin barely fits and next item needs the space.
    if bin_residual == bin_capacity {
        // base penalty for proliferating bins
        score += 8.0 + 2.0 * open_bins_count as f64;
        // but if placing here leaves a residue in a "bad class", penalize the open bin instead
        let bad_fit = (pr > 0 && pr < 10) || (pr >= 40 && pr < 60);
        if bad_fit {
            score -= 12.0;
        }
        // lookahead: if next item is large, a fresh bin preserves flexibility
        if next_item_size > 0 && next_item_size as f64 > 0.6 * cap && pr > 0 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // chaining is perfect; if next item cannot fit, mild penalty unless residual tiny.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (n - pr as f64).abs() < 1.0 {
            score -= 20.0;
        } else if n <= pr as f64 {
            score -= 3.0;
        } else if pr > 0 && pr < 10 {
            // residual too small for anything: fine, it's sealed
            score -= 4.0;
        } else {
            score += 3.0; // stranded capacity
        }
    }

    // Prefer bins whose residual is below the mean (denser bins first).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild progression term: early on, be conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * (pr as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward tight fits (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits in post_residual, reward leaving that gap.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward if next item would fill it nearly perfectly.
        let gap_after = post_residual - next_item_size;
        if gap_after <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover gap the next item cannot use: mild penalty.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * (4.0 + 6.0 * progress);

    // Compare against mean residual: bins far below mean residual are wasteful targets.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 6.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or item is huge.
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (bin_residual - item_size) > 30);
        if poor_fits {
            score -= 20.0;
        } else {
            score += 25.0 + (open_bins_count as f64) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins where the next item fits the residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 + 0.5 * next_item_size as f64;
        } else {
            // Penalize dead space the next item cannot use.
            score += 0.3 * (post_residual as f64).powf(1.2);
        }
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 150.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a new bin when reasonable fits exist, unless current
    // fit is terrible (large post_residual) and many bins are open.
    if bin_residual == bin_capacity {
        let worst = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 40.0 + 50.0 * worst * (open_bins_count as f64).min(10.0) / 10.0;
        // But if item is large, new bin is natural.
        if item_size >= 70 {
            score -= 60.0;
        }
    }

    // Late in stream: be more conservative, keep residuals usable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 4.0 * (post_residual as f64 - next_item_size as f64).min(10.0) / 10.0;
        } else {
            // Next item won't fit here: penalize leaving residual that next item almost fits.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 2.5 * (15.0 - gap) / 15.0;
            }
        }
    }

    // Global pressure: many open bins with small mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.15 * pressure;

    // Time horizon: early in stream, be more liberal with new bins (exploration);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how badly existing bins fit
        // and how much of the stream remains.
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let waste = (bin_capacity - item_size) as f64;
        score = 45.0 + 0.4 * waste - 25.0 * poor_fit - 10.0 * (1.0 - progress);
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size > item_size {
            score -= 3.0;
        }
    } else {
        // Late in stream, extra reward for closing bins out (high fill ratio).
        score -= 8.0 * progress * (1.0 - (bin_residual as f64 / bin_capacity as f64));
        // Prefer bins whose residual deviates from mean in a useful way (keeps spread balanced).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on leftover space (tight fits preferred)
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, waste is penalized more aggressively.
    score *= 1.0 + 2.0 * progress * norm_pr;

    // Cubic interaction term: dead space becomes increasingly costly as stream advances
    score += (norm_pr * norm_pr * norm_pr) * cap * (0.5 + progress);

    // Reward bins that also leave room for the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= (1.0 - progress) * (pr - nxt).sqrt() * 2.0;
        } else {
            // post-residual too small for next item: mild penalty scaled by deficit
            score += (nxt - pr) * (0.5 + progress);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist, unless residual is very tight
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let openness = open_bins_count as f64;
        score += 40.0 + 10.0 * openness.sqrt() - 20.0 * progress;
        // allow new bin if mean residual is large (open bins fragmented)
        score -= (mean_residual / cap) * 15.0;
    } else {
        // small reward for using existing bins
        score -= 5.0;
    }

    // Mild preference for bins closer to mean residual (balance load)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer bins with small post residual
    let mut score = post;

    // Reward large items consuming a big fraction of the bin
    score -= (item / cap) * 30.0;

    // Harmonic class logic on post_residual (integer division thresholds)
    // class 0: near-perfect fit (0-9 dead space) -> strong reward
    // class 1: 10-19, awkward for typical items -> penalty
    // class 2: 20-29, still usable for small items
    // class 3: 30-39, moderately useful
    // class 4+: large residual, wasteful placement
    let cls = post_residual / 10;
    score += match cls {
        0 => -60.0,
        1 => 20.0,
        2 => 5.0,
        3 => 0.0,
        4 => 5.0,
        _ => 10.0,
    };

    // Modulo-style refinement: post_residual divisible-ish by common small sizes
    if post_residual >= 10 && (post_residual % 10 == 0) {
        score -= 8.0; // clean residual, easy to fill later
    } else if post_residual % 10 >= 8 {
        score += 4.0; // sliver-like awkward leftover
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when no existing fit is decent
    if bin_residual == bin_capacity {
        score = 55.0 + post - item * 0.2;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    // Lookahead (k=2): bonus if next item fits into the resulting residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= post {
            score -= 15.0;
        } else {
            score += 5.0;
        }
    }

    // Coupling with mean residual: placing into a bin below mean residual
    // balances the open-bin pool
    score += (mean_residual - post) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (>=1) can use well
    // are heavily penalized, especially tiny unusable gaps.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += (10.0 - pr) * 6.0; // tiny dead space: severe penalty
    } else if post_residual < 20 {
        score += (20.0 - pr) * 2.0; // moderately awkward gap
    }

    // Reward tightness: relative fill of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: prefer spreading load across fewer bins when many open
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        let decent_fit = (bin_residual - item_size) as f64;
        let avg_fit = mean_residual - item_size as f64;
        if avg_fit < 0.0 {
            score -= 20.0; // no open bin can fit: open new bin
        } else if avg_fit > 25.0 {
            score -= 8.0; // open bins waste a lot; fresh bin may be better
        } else {
            score += 15.0; // prefer existing bins when fit is reasonable
        }
        // discourage opening bins early in the stream
        score += (step_index as f64 / total_items.max(1) as f64) * -5.0;
        let _ = decent_fit;
    }

    // Lookahead: if next item fits snugly into the post residual, bonus
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let snug = (post_residual - next_item_size) as f64;
            score -= (post_residual as f64 - snug).min(20.0) * 0.4;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 3.0; // leaves a gap the next item cannot use
        }
    }

    // Mild alignment with mean residual: avoid creating outliers far below mean
    if post_residual as f64 > mean_residual + 30.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            // Exact or near-exact match for the next item -> strong reward.
            let match_gap = (post_residual as f64 - next) / bin_capacity as f64;
            score -= 40.0 * (1.0 - match_gap.min(1.0));
        } else {
            // Post-residual too small for the next item: penalize dead space,
            // scaled by how badly it misses the lookahead size.
            let miss = next - post_residual as f64;
            score += 0.5 * miss;
        }
    } else {
        // Last item: only the immediate fit matters.
        score -= 10.0;
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than average waste is good (tight packing).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.3;
    } else {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent fits exist,
    // but allow it when residuals across open bins are all tiny.
    if bin_residual == bin_capacity {
        let tight_open = if mean_residual < item_size as f64 { 1.0 } else { 0.0 };
        score += 15.0 - 30.0 * tight_open;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Mild penalty for very large leftover slivers that are hard to fill.
    if pr > 0.0 && pr < 10.0 {
        score += 8.0;
    }

    // Reward bins that are already partially filled (prefer fuller bins).
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Dead space penalty amplified if leftover is small and unusable.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 18.0;
            } else {
                score += 0.10 * dead;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize opening a new bin; stronger early when consolidation matters.
        score += 60.0 + 40.0 * (1.0 - progress);
        // If next item is huge, opening fresh space may be wise: soften penalty.
        if next_item_size >= 70 {
            score -= 20.0;
        }
        // If many bins are open with large mean residual, opening more is wasteful.
        score += 0.05 * mean_residual;
    } else {
        // Prefer tighter fits among open bins: reward small post_residual relative to item.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * tightness;
        // Mild penalty for spreading across too many open bins.
        score += 0.3 * open_bins_count as f64;
        // Prefer bins below mean residual (consolidating fuller bins).
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: late in the stream, avoid creating new fragmented bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 {
        score += 0.5 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: wasted space, non-linearly scaled by stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Penalize residuals that are unusable (too small for typical future items)
    let dead_zone = 20.0;
    if pr > 0.0 && pr < dead_zone {
        score += (dead_zone - pr) * (1.0 + 2.0 * progress);
    }

    // Smooth coupling: large post_residual with high mean_residual is wasteful
    score += 0.3 * (pr / cap) * (pr / cap) * mean_residual * (1.0 + progress);

    // Lookahead synergy: reward if next item fits into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (1.0 + progress);
        } else {
            // penalize blocking the next item
            score += 3.0 * ((nxt - pr) / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate: keep it neutral-ish, only attractive when open bins are tight
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.5 * progress) - 0.2 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 10 classes of 10
    let post_class = (post_residual / 10).min(9);
    let item_class = (item_size / 10).min(9);
    let next_class = (next_item_size / 10).min(9);

    // Reward tight fits: post_residual in low classes is good
    score -= (10 - post_class as f64) * 6.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Penalize dead space: residuals that are small but unusable for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space class
    }

    // Coupling with lookahead: reward if next item fits exactly in post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 20.0;
            // harmonic match of classes
            if post_class == next_class {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // open new bin if mean residual is large (bins are mostly empty anyway)
        if mean_residual > cap * 0.5 {
            score += 20.0;
        }
    }

    // Prefer bins with residual close to item size (best-fit sharpening)
    let fit_gap = (bin_residual - item_size) as f64;
    score += (fit_gap / cap) * 15.0;

    // Mean residual coupling: placing into a bin far below mean residual is wasteful
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.2;
    }

    // Progress-based mild pressure to consolidate late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Item class interaction: large items prefer low-residual bins
    if item_class >= 6 && post_class <= 3 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps much harder
    // than large remaining space. A residual that cannot accommodate even a
    // minimum item (1..100 unknown distribution -> assume tiny items possible,
    // but weight heavily against mid-range dead zones).
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 15 {
        // Tiny dead gap: nearly unusable, heavy penalty.
        score += 45.0;
    } else if post_residual < 35 {
        // Mid-range dead zone: moderately unusable.
        score += 18.0;
    } else {
        // Large residual still flexible: mild reward proportional to size.
        score -= 6.0;
    }

    // Tightness reward: the smaller the residual relative to capacity, the better.
    let tightness = 1.0 - pr / (bin_capacity as f64);
    score -= 10.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // bins (new bin has bin_residual == bin_capacity, so this term pushes
    // consolidation) and encourage filling existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += 12.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly (chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward scaled by how well it fills.
        let fill = next_item_size as f64 / pr.max(1.0);
        score -= 8.0 * fill;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        // Next item cannot use the tiny dead gap we'd create: extra penalty.
        score += 15.0;
    }

    // Mean residual coupling: if this bin's post residual is far below the
    // mean residual, we are compacting well; reward slightly.
    let dev = mean_residual - pr;
    score -= 0.05 * dev;

    // Stream progression: late in the stream, prefer consolidating into
    // existing bins even more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 8.0 * progress;
    } else {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Two-step lookahead coupling ---
    if next_item_size > 0 {
        // Perfect chain match: post_residual == next_item_size is ideal
        let chain_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for tight chains, scaled by lookahead value
        score -= 25.0 * (1.0 - chain_gap / bin_capacity as f64).max(0.0);
        // Penalize residuals that are too small for next item (dead space for chain)
        if (post_residual as u64) < (next_item_size as u64) {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
        // Extra reward for exact match (perfect packing chain)
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: prefer minimal residual directly
        score += 5.0;
    }

    // --- Relative-to-mean-residual coupling ---
    let dev = post_residual as f64 - mean_residual;
    // Prefer bins whose post-residual is below the mean (tighter packing)
    score += 0.15 * dev;
    // Nonlinear penalty for large positive deviation (wasteful bins)
    if dev > 0.0 {
        score += 0.10 * dev * dev / bin_capacity as f64;
    }

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early or when many open bins are fragmented;
        // costly late in the stream when consolidation matters.
        score = 55.0 + 40.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 60.0; // next item needs a fresh bin anyway
        }
        if next_item_size > 0 && (bin_capacity - next_item_size) == item_size {
            score -= 30.0; // perfect pairing in fresh bin
        }
    }

    // Mild pressure to close bins as stream progresses
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Penalize dead space that no future item can plausibly use:
    // if post_residual is smaller than the smallest plausible item (1..100, assume ~10),
    // the leftover is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // Extra reward if next item fills this bin nearly perfectly afterwards.
            let next_left = post_residual - next_item_size;
            if next_left < 10 {
                score -= 12.0;
            }
        } else {
            // Post-residual too small for the next item: dead space risk.
            score += 8.0 + 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins over emptier ones among open bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Global state: when many bins are open, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity, so its fill_ratio
    // is 0 and gets no bonus — add a mild new-bin penalty scaled by open bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
    }

    // Time horizon: early in the stream, be conservative (favor tight fits,
    // avoid fragmentation); late in the stream, just close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * (1.0 - progress);

    // Mean-residual coupling: if mean residual across open bins is low,
    // we're near saturation — prefer any fit over new bins.
    if mean_residual < 15.0 && bin_residual < bin_capacity {
        score -= 10.0;
    } else if mean_residual > 50.0 && bin_residual == bin_capacity {
        // Plenty of slack overall: opening a new bin is cheap.
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: prefer tight fits, penalized quadratically as post-residual grows
    let mut score = pr * pr / cap;

    // Smooth non-linear coupling of wasted space with stream progress:
    // late in the stream, dead space matters more (less chance to fill it)
    score += x * x * (1.0 + 3.0 * progress) * 20.0;

    // Interaction: post_residual vs mean_residual — placing into a bin
    // far from the mean residual is mildly penalized unless it's a tight fit
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev * dev * 30.0 - x * mean_residual / cap * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - x);
    }

    // Lookahead: if next item could fill this post-residual exactly, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 15.0 * fit_quality * fit_quality;
    } else if next_item_size > post_residual {
        // next item can't use this leftover; penalize dead space more
        score += 10.0 * x * (1.0 + progress);
    }

    // Many open bins: slight preference to consolidate rather than spread
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: capacity split into 5 bands.
    let fifth = bin_capacity / 5;
    let class = post_residual / fifth;
    match class {
        0 => score -= 30.0,                    // near-perfect fit
        1 => score -= 12.0,                    // good
        2 => { score += 4.0; }                 // neutral
        3 => { score += 10.0; }                // wasteful
        _ => { score += 18.0; }                // nearly empty placement
    }

    // Reward tight fits (exact fill especially).
    if post_residual == 0 { score -= 60.0; }
    else if post_residual <= 5 { score -= 25.0; }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item can fill this bin's post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.6;
        } else {
            // next item cannot use the leftover: penalize large dead space
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // New-bin candidate: default mild preference, unless existing fit is decent.
    if bin_residual == bin_capacity {
        score = 35.0 + post_residual as f64 * 0.3;
        if fitting_bins_count == 0 { score -= 50.0; } // no alternative
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 20.0; // next item won't fit the fresh bin either
        }
    }

    // Dead-space harmonic penalty: modulo-10 classes of residual.
    let r10 = post_residual % 10;
    if r10 != 0 && r10 < 3 { score += 6.0; }

    // Prefer balancing residuals across bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 - mean_residual).abs() * (1.0 - progress) * 0.25;

    // Penalize scattering across many open bins when post-residual is small.
    if open_bins_count > 4 && post_residual > 50 { score += 8.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0 + open_bins_count as f64;
        // If no existing bin fits well (post_residual here is large by definition),
        // reduce the penalty when open bins are fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fragmentation > 30.0 {
            score -= 15.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 60 {
            score -= 20.0;
        }
    } else {
        // Placing into an existing bin: penalize if it leaves a gap the next item
        // cannot use, reward if next item fits the post_residual.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 70.0;
            } else if next_item_size > post_residual {
                score += 12.0;
            }
        }
        // Mild preference to consolidate into fewer bins when many are open.
        score += open_bins_count as f64 * 0.5;
    }

    // Small bias toward bins whose residual is close to the mean (balanced packing)
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits perfectly after this one -> excellent chain.
            let chain = post_residual - next_item_size;
            score -= 150.0 - (chain as f64) * 1.5;
        } else if post_residual > 0 {
            // Dead space that next item cannot use -> penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Bonus if the pair (item + next) exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 250.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when good existing fits exist, unless current bin wastes a lot.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus dead-space avoidance.
        score += 60.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.2;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 40.0;
    }

    // Mild preference for keeping fewer open bins (consolidation).
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual to heavily penalize wasteful placements.
    score += 0.02 * (post_residual as f64).powi(2);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item exactly fits the post-residual, this placement is ideal.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 0.5 {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Post-residual can still host the next item: mild reward scaled by slack.
            score -= 10.0 * (1.0 - (post_residual - next_item_size as u32) as f64 / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 0.3 * (post_residual as f64 - nr).max(0.0);
        }
    }

    // Prefer bins whose residual is below mean residual (tighter bins get filled first).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0) - 0.25 * (bin_residual as f64 - mean_residual).max(0.0);

    // Time horizon: later in the stream, consolidation matters more; discourage new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins, more so as the stream progresses
        // and when many bins are already open.
        score += 25.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // But if item is large and would leave big dead space anywhere, new bin is fine.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 35.0;
        }
    } else {
        // Existing bin: mild reward that decreases with open bin count pressure.
        score -= 5.0 * progress;
    }

    // Prefer filling bins with small residuals completely (avoid stranding small gaps).
    if bin_residual < bin_capacity && post_residual > 0 && post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, keep residual space flexible (penalize small residuals less than raw);
    // later, reward tight fits aggressively.
    let norm_pr = pr / cap; // 0..1
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 0.5
                 + norm_pr * progress * 2.0;
    score += coupling * cap;

    // Smooth penalty for opening new bins when the stream is early,
    // reward keeping bins open as stream progresses.
    let density = (open_bins_count as f64).ln1p();
    score -= progress * density * 1.5;

    // Penalize wasteful near-full bins only if lookahead item cannot use the leftover.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) / cap;
        score += waste * waste * 20.0 * (0.5 + progress);
        // Reward bins whose leftover will fit the next item.
        if pr >= nx {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Mild preference toward tighter mean residual bins (smooth quadratic).
    let mr = mean_residual / cap;
    score += mr * mr * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by size classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        // Harmonic classes: residuals that can host common future items are valuable.
        // Class A: pr in [10..30] can host small items (10..30) -> moderately useful
        // Class B: pr in [31..60] -> hosts mid items
        // Class C: pr in [61..99] -> hosts large items, near-waste otherwise
        let class_bonus = if pr <= 10 {
            45.0 // can fit only tiny items; small residual = tight fit
        } else if pr <= 30 {
            25.0
        } else if pr <= 60 {
            10.0
        } else {
            -8.0 // large residual = loose packing, wasteful
        };
        score -= class_bonus;

        // Modulo arithmetic on residual: residuals matching multiples of common
        // item sizes (10,20,25,50) are more likely to be exactly filled later.
        let pr_u = pr;
        if pr_u % 10 == 0 { score -= 6.0; }
        if pr_u % 25 == 0 { score -= 5.0; }
        if pr_u % 50 == 0 { score -= 4.0; }

        // Integer-division thresholds: pr / 10 gives "slots" of size 10.
        let slots = pr / 10;
        score -= slots as f64 * 1.5; // more usable slots = better bin
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0;
        // Bonus if next item would leave another exact-friendly residual.
        let pr2 = pr - next_item_size;
        if pr2 % 10 == 0 { score -= 5.0; }
        if pr2 == 0 { score -= 20.0; }
    } else if next_item_size > pr {
        // Bin becomes useless for the lookahead item; penalize mildly.
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
        // But if the fit wastes a lot, soften the reward.
        if post_residual > 60 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so we only
    // open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper (build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many bins are open already, discourage spreading further.
        score += (open_bins_count as f64) * 0.8;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin — placing here consolidates space.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 3.0 * diff.min(30.0) / 10.0;
    } else {
        score += 1.5 * (-diff).min(30.0) / 10.0;
    }

    // Tightness term: reward high fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 15.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1)
    // are pure waste, but gaps too small for typical items (<= 10) are
    // nearly dead too. Penalize the "unusable sliver" zone hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }
    // Moderately small leftovers (< 20) are semi-dead: mild penalty.
    if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score += 15.0; // creates a sliver after next placement
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: the more bins already open, the more we should
    // prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure so it only wins when
        // all open bins would create dead space.
        score += 30.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Slight preference for bins tighter than average (best-fit flavor).
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_gap = (post_residual as f64 - nxt).abs();
        score -= 12.0 * (1.0 - match_gap / cap).max(0.0);
        // Perfect chain: next item fills bin exactly
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space that next item cannot use
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.6 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0 * (post_residual as f64 / cap);
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 3.0 * (mean_residual - post_residual as f64) / cap;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Discourage spreading across many bins when stream is early
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless post_residual is tiny (near-perfect) or no alternative
        score += 20.0 + 30.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 8.0;
        }
    }

    // Slight penalty for large leftover relative to capacity (dead space)
    score += 0.25 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract more when post_residual is a small fraction of residual
    let tightness = if bin_residual > 0 {
        post_residual as f64 / bin_residual as f64
    } else {
        1.0
    };
    score -= (1.0 - tightness) * 30.0;

    // Lookahead: if next item fits into post_residual, reward this bin strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize leaving awkward gaps
        score += 8.0 * (1.0 - progress);
    }

    // Penalize creating dead space: post_residual that is too small for any plausible item (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 5.0; // only tiny items can use it
    }

    // Prefer using bins that are already quite full (avoid spreading across many bins)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // If this is the only bin that fits, strongly favor it (last chance before new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 - item_size as f64;
        // As stream progresses, more willing to open new bins (keep options open)
        score -= 15.0 * progress;
        // If several bins fit, opening a new one is wasteful
        score += 18.0 * (fitting_bins_count as f64).min(4.0);
        // If mean residual is large (open bins are mostly empty), discourage new bin
        score += (mean_residual / bin_capacity as f64).max(0.0) * 10.0;
        // Lookahead synergy: fresh bin guarantees room for next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild global pressure: with many open bins, prefer consolidating into existing ones
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64).sqrt() * 1.5;
    }

    // Small time-horizon coupling: late in stream, squeeze harder (minimize final waste)
    score -= 5.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) + prn * progress * (1.0 - prn);
    score += 40.0 * poly;

    // Penalize large residuals more as stream matures (quartic smooth term)
    score += 25.0 * prn.powi(4) * progress;

    // Reward tight fits (small post residual) with smooth exponential shaping
    score -= 30.0 * (-prn * 6.0).exp() * (1.0 - progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits in post_residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill = nxt / cap;
            score -= 20.0 * fill * (1.0 - fill) * (1.0 - progress);
        } else {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild penalty when bin is far from mean residual (imbalance)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin unless nothing else is tight
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into modulo bands.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect-fit bonus: post_residual in {0} is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0; // near-perfect fill, dead space negligible
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Modulo-10 harmonic classes: residues divisible by 10 pair well with
    // typical item granularities (items often multiples of 5/10).
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 10.0; // clean class, reusable by round items
    } else if residue_class >= 7 {
        score += 8.0; // awkward residue, hard to refill
    }

    // Integer-division thresholds on post_residual: how many size-10 slots remain.
    let slots = post_residual / 10;
    match slots {
        0 => score += 5.0,          // tiny leftover, mostly dead
        1 => score -= 8.0,          // one clean slot left
        2 => score -= 6.0,
        3 => score -= 2.0,
        _ => score += 4.0,          // large leftover = poor packing so far
    }

    // Lookahead coupling: does the leftover class fit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly-ish here: strong reward.
            let slack = post_residual - next_item_size as f64;
            score -= 15.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 25.0; // chain of perfect fits
            }
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally.
            score += 6.0 + 10.0 * (next_item_size as f64 / cap);
        }
    } else {
        // Last item: any residual is pure waste; minimize it hard.
        score += 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin wastes the residual of this stream.
    if bin_residual == bin_capacity {
        // Attractive early when open bins are fragmented; costly later.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post).abs();
        score += 25.0 + 20.0 * (1.0 - progress) - 10.0 * (open_bins_count as f64 / 20.0);
        if fragmentation < 5.0 && mean_residual > 30.0 {
            score += 15.0; // open bins already roomy; don't fragment more
        }
    }

    // Mild pressure to keep mean residual low across the fleet.
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (1..10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
