    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward leaving room for the lookahead item if it fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (next_item_size as f64) * 0.2;
    }
    // Penalize if lookahead item cannot fit anywhere else either (rough proxy).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer existing bins over new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 25.0 + open_bins_count as f64 * 3.0 + progress * 30.0;
        // But allow a new bin if item is huge and mean residual is poor.
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 35.0;
        }
    } else {
        // Slight preference for bins with less residual when many bins open.
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Reward filling large items into bins proportionally tight.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item: strong reward.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how tight the fit is.
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
