    // Relative-to-mean coupling: bins with residual far below mean are tight; prefer them
    // only if they still fit, otherwise penalize fragmentation.
    let mean_gap = post_residual as f64 - mean_residual;
    if post_residual == 0 {
        score -= 30.0; // perfect closure
    } else if mean_gap < 0.0 {
        score -= 0.2 * (-mean_gap);
    } else {
        score += 0.15 * mean_gap;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fits exist among open bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        // But if the item is large and mean residual is small, a new bin is attractive.
        if item_size as f64 > mean_residual + 5.0 {
            score -= 18.0;
        }
    }

    // Late-stream tightening: as the stream progresses, prefer exact closures more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
