    // a bin left with much more space than average is a wasted asset.
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);

    // Lookahead: if the next item fits exactly (or well) in the post residual,
    // strongly favor this bin; if it would NOT fit, penalize proportionally.
    if next_item_size > 0 {
