    score += 0.8 * waste * (1.0 + progress);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly (quadratic in progress).
    score += 2.0 * progress * progress * (post / cap) * cap * 0.1;

    // Tight fit reward: small post_residual relative to item size.
    let tightness = 1.0 - post / cap;
    score -= 6.0 * tightness * tightness;

    // Lookahead: reward if the next item can still fit in the post residual.
    if next > 0.0 {
        if post >= next {
            score -= 4.0 * (1.0 - (post - next) / cap);
        } else {
            // Penalize leaving a residual that is too small for the next item,
            // scaled by how far short it falls (smooth, not piecewise).
            score += 3.0 * ((next - post) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate (empty bin): penalize mildly so it is chosen only
    // when no open bin offers a good fit; penalty grows with stream progress.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: harmonic residue class 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: how it decomposes into small items (<=10 steps).
        let cls = post_residual % 10;
        // Residues that are "friendly" (can be filled by small items 1..10 aligned) get mild reward.
        match cls {
            0 => score -= 8.0,          // multiple of 10: most fillable
            5 => score -= 4.0,          // half-class
            2 | 4 | 6 | 8 => score -= 2.0, // even class
            _ => score += 2.0,          // odd residue: harder to fill
        }
    }

    // Integer-division threshold: post_residual bucketed by capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score -= 5.0; // nearly full bin: good, seal it
    } else if frac > 0.5 {
        score += 6.0 * frac; // leaving a big hole: penalize proportionally
    }

    // Lookahead coupling: can next item exactly fill the post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // chain completion
        } else if next_item_size <= post_residual {
            score -= 3.0;
            // modulo harmony between next item and post residual
            if post_residual % next_item_size == 0 {
                score -= 4.0;
            }
        } else {
            score += 1.5; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score = 60.0 + pressure * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // future big items favor fresh space
        }
        if fitting_bins_count <= 1 {
            score -= 40.0; // no real alternative
        }
    }

    // Mild time decay: early stream, be conservative about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward placements that still leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: mild dead-space penalty scaled by tightness.
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) + 5.0 * progress;
    } else {
        // Existing-bin bonus, stronger when few fitting bins remain (last-chance).
        score -= 5.0;
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Slight preference for bins tighter than average (fill the fullest first).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Late-stream urgency to close out bins.
    score -= 4.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual).
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: perfect match with next item is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // penalize leaving a gap that next item can't fully use
            score += 0.5 * gap;
            if gap < 10.0 { score -= 10.0; }
        } else {
            // next item can't fit here after placement; residual is dead space
            score += 6.0;
        }
    }

    // Compare post_residual to mean residual across open bins: avoid outliers.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable fit.
    if bin_residual == bin_capacity {
        score += 15.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count >= 1 && post_residual as f64 > mean_residual {
            score += 25.0;
        }
    }

    // Early stream: be slightly greedy with tight fits; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Penalize opening a new bin when an existing bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0;
        // But allow new bin if this is a "last chance" mismatch elsewhere
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a new bin
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if next_item_size > post_residual as u32 && post_residual > 0 {
            // Dead space for the known next item: penalize proportionally
            score += 4.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidation into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.02 * crowd * (0.5 + progress);

    // Slight bias toward filling bins with larger residuals early, tighter bins late
    score += (1.0 - progress) * 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize wasted residual, non-linearly (quadratic dead-space pressure)
    let mut score = pr + 0.8 * (pr * pr) / cap;

    // Normalize residual by mean residual across open bins: bins with residual
    // far below the mean are "tight" -> placing here wastes less relative space.
    let tightness = if mean_residual > 0.0 { pr / mean_residual } else { 1.0 };
    score += 0.6 * (tightness - 1.0) * (tightness - 1.0) * cap * 0.1;

    // Lookahead coupling: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let match_bonus = (1.0 - gap / cap).max(0.0);
        score -= 4.0 * match_bonus * match_bonus;
        // If next item fits exactly in post_residual, strong reward
        if nx <= pr {
            score -= 2.0 * (nx / cap);
        }
    }

    // Stream progress coupling: early on, prefer compacting (penalize high residual
    // more strongly as stream progresses to close bins out).
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score *= 0.5 + 0.5 * progress_weight;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Many open bins: discourage spreading; favor tighter bins
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Slight penalty for the brand-new empty bin candidate, so it's chosen only
    // when no open bin gives a decent fit (its pr == cap is already high).
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * progress;
    }

    // Smooth sigmoidal modulation of fit quality: near-perfect fits get extra reward
    let fit_frac = 1.0 - (pr / cap);
    let sigmoid = 1.0 / (1.0 + (-8.0 * (fit_frac - 0.85)).exp());
    score -= 3.0 * sigmoid;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: how it partitions the capacity.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let post_frac = post_f / cap_f; // fraction of capacity left after placement

    // Class the post-residual into octiles of the capacity (harmonic classes).
    let class = (post_residual * 8 / bin_capacity) as i64; // 0..8
    // Reward tight fits: lower post_residual generally better, but dead space
    // that is TOO small to hold the next item is wasted -> penalize.
    let next_fits = next_item_size > 0 && post_residual >= next_item_size;
    if next_item_size > 0 {
        if next_fits {
            // Great: this bin remains usable for the lookahead item.
            score -= 6.0 + 0.25 * (next_item_size as f64);
        } else {
            // Dead space: post-residual can't host the next item.
            // Penalize proportionally to how close-but-unusable it is.
            let gap = (next_item_size as f64) - post_f;
            if gap > 0.0 && gap <= 20.0 {
                score += 8.0 + 0.6 * (20.0 - gap); // near-miss waste is worst
            } else {
                score += 3.0;
            }
        }
    } else {
        // Last item: pure tightness matters.
        score -= 4.0;
    }

    // Harmonic (modulo) structure on post_residual: residues that align with
    // common item-size classes (multiples of 10 up to 80) are more reusable.
    let residue = post_residual % 10;
    if residue == 0 && post_residual > 0 {
        score -= 2.5; // post-residual lies on the item grid -> highly reusable
    } else {
        score += 0.15 * residue as f64;
    }

    // Integer-division thresholds: classify post_residual into usable slots.
    let slots = post_residual / 10; // number of minimal item slots remaining
    if slots == 0 && post_residual > 0 {
        score += 10.0; // unusable sliver: worst outcome
    } else if slots == 1 {
        score += 4.0; // only fits the smallest class
    } else if slots >= 5 {
        score -= 1.5; // keeps a large-capacity bin flexible
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: empty bin is a fallback; make it mildly
    // attractive only when the current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        // Opening fresh: score = capacity - item_size naturally; adjust by phase.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 2.0 - 4.0 * progress; // later in stream, prefer reusing open bins
        if next_item_size > 0 && next_item_size > post_residual && item_size >= 60 {
            score -= 5.0; // big item + big next: fresh bin is reasonable
        }
    }

    // Coupling with mean residual: if this bin's post-residual deviates badly
    // from the fleet mean, penalize (keeps residual distribution harmonized).
    let dev = post_f - mean_residual;
    score += 0.05 * dev.abs();

    // Fractional-capacity coupling: reward post-residuals near "nice" fractions
    // (1/4, 1/2, 3/4 of capacity) which pair well with typical item sizes.
    for q in [0.25f64, 0.5, 0.75] {
        let d = (post_frac - q).abs();
        if d < 0.08 {
            score -= 2.0 * (0.08 - d) / 0.08;
        }
    }

    // Slight preference to fill emptier bins first when many bins are open.
    score += 0.02 * open_bins_count as f64 * (1.0 - post_frac);

    let _class = class;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fit reward
    }

    // Reward leaving a gap that fits the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // gap blocks next item
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening bins under low pressure
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64) * 1.5;
        if item_size <= 30 {
            score += 10.0; // don't waste a fresh bin on tiny items
        }
    }

    // Open-bin pressure: more open bins -> prefer consolidating into existing
    score += (open_bins_count as f64) * 0.8;

    // Slight preference for tighter bins
    score += (bin_residual as f64) * 0.05;

    // Progress-aware: later in stream, be more conservative about new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * gap;
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item fill
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0; // near-perfect chain
        }
        // Penalize residuals too small for any plausible future item (dead space)
        if post_residual < 10 {
            score += 20.0;
        }
    } else {
        // Last item: prefer tightest fill
        score += 0.1 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins with less residual than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins fit well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 10.0 * progress;
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space strongly (nonlinear waste penalty).
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.35 * (dead * dead) / bin_capacity as f64;
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward; if this
    // placement wastes space the next item could have used, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Next item can still fit here: mild reward for keeping a useful gap.
            let gap_fit = nxt / post_residual.max(1) as f64;
            score -= 8.0 * gap_fit;
        } else if (post_residual as f64) > 0.0 && nxt > post_residual as f64 {
            // Dead space too small for the next item: penalize proportionally.
            score += 6.0 * (1.0 - post_residual as f64 / nxt);
        }
    }

    // Time horizon: early in the stream be more conservative (favor spreading),
    // late in the stream be greedy about filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    // Global state: many open bins with high mean residual -> favor consolidating
    // into bins below the mean residual (tighter bins).
    if open_bins_count > 1 {
        let rel = bin_residual as f64 / bin_capacity as f64;
        score += 5.0 * (rel - mean_residual / bin_capacity as f64);
    }

    // Prefer not to leave a residual that is awkwardly small relative to typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // near-dead space penalty
    }

    // New-bin candidate: only attractive when current item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 20.0 * desperation - 10.0 * big_item * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: penalize post_residual more as stream progresses
    // (late in the stream, dead space is less likely to be recovered).
    score += norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (low post_residual) with a smooth cubic discount.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * 10.0;

    // Last-chance bonus: strongly prefer the only bin that fits (smoothly scaled).
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: if next item fits into post_residual, reward this bin smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_ratio = nxt / pr.max(1.0);
            score -= 8.0 * fit_ratio * (1.0 - fit_ratio) * 4.0;
        } else {
            // Next item cannot follow here: mild penalty, smoothed by progress.
            score += 5.0 * (0.3 + 0.7 * progress);
        }
    }

    // Discourage scattering when many bins are open and this bin is far from mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 3.0 * dev * dev * (open_bins_count as f64).sqrt().min(5.0);

    // New-bin candidate: make it slightly less attractive unless it beats real tight fits.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into octiles.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let class = (post_f / cap * 8.0).floor() as i32; // 0..7

    // Perfect fit: heavily reward zero or tiny post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Dead-space penalty: leftovers that nothing (min size 1) can use are fine,
    // but small unusable slivers are bad. Penalize classes 1 and 2 (small slivers).
    match class {
        0 => score -= 50.0,          // exact-ish fit
        1 => score += 120.0,         // sliver: likely dead space
        2 => score += 60.0,          // small leftover
        3 => score += 10.0,
        4 => score -= 20.0,          // half bin: flexible
        5 => score -= 10.0,
        6 => score += 5.0,
        _ => {}                      // near-full bin, nothing to say
    }

    // Lookahead coupling: reward if next item fits into post_residual,
    // penalize if next item exists but cannot fit any harmonic subdivision.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly: stronger reward for tighter chain
            let chain_post = post_residual - next_item_size;
            score -= 80.0 + (chain_post as f64).min(40.0);
        } else {
            // next item won't fit here; penalize proportionally to overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.5 * overflow;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when open bins are crowded or item is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowd = open_bins_count as f64;
        // Base cost of opening a bin, offset by crowding and item size.
        score = 200.0
            - 15.0 * crowd
            - 0.5 * item_size as f64
            - 50.0 * progress;
        // If next item is huge, prefer a fresh bin for the current item.
        if next_item_size > bin_capacity / 2 {
            score -= 60.0;
        }
    }

    // Mean residual coupling: when open bins are mostly full (low mean residual),
    // favor using existing bins even more.
    score += 0.3 * (mean_residual - post_f);

    // Modulo harmonic texture on post_residual: multiples of 10 are "clean"
    // capacities (likely reusable by round-sized items).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the closer post_residual is to 0, the better.
    score -= (item_size as f64 / bin_capacity as f64) * 40.0;

    // Dead space penalty: small unusable gaps (0 < post_residual < 10) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Medium dead-space penalty: gaps that most items (10..80) cannot use.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Last chance: strongly favor using the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item is large and current bins are crowded, new bin is less bad.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }

    // Prefer bins whose residual is below mean (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight superlinearity
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward exact match of post_residual with next_item_size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post_residual as f64 - nx).abs();
        // perfect 2-chain: post_residual == next_item_size -> strong reward
        score -= 25.0 * (1.0 - diff / bin_capacity as f64).max(0.0).powi(3);
        // next item fits exactly after current placement
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // dead space for the next item: penalize proportionally
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
        // coupling with mean residual: bins far below mean residual absorb variance well
        score -= 4.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        // last item: just minimize waste
        score += (post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins, discourage new-bin sprawl
    if open_bins_count > 2 {
        score -= 3.0 * (open_bins_count.min(20) as f64) / 20.0;
    }

    // New-bin candidate: penalize unless current bin residuals are all poor fits
    if bin_residual == bin_capacity {
        // a new bin is only attractive if existing bins cannot give a decent fit
        let poor_existing = if next_item_size > 0 && post_residual > 0 {
            0.0
        } else {
            0.0
        };
        score += 20.0 - poor_existing;
        // but allow new bin when stream is early and mean residual is high (fragmented state)
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 {
            score -= 22.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

