    // Lookahead: if next item fits in post_residual, reward keeping this bin usable.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; slightly penalize leaving awkward gaps.
            let gap_waste = (post_residual as f64 / next_item_size as f64).min(1.0);
            score += gap_waste * 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        // Baseline penalty for opening a new bin; scaled by how many bins already fit the item.
        score += 10.0 + (fitting_bins_count as f64) * 6.0;
        // Early in the stream, opening bins is cheaper (builds a portfolio).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 12.0;
        // If mean residual across open bins is low, existing bins are crowded; new bin is attractive.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 10.0;
    }

    // Prefer filling bins with low residual relative to the fleet average (balance consolidation).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.15;

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Discourage placing large items into already-large-residual bins when item is small (waste potential).
    if item_size < 30 && bin_residual > 70 {
        score += 6.0;
    }

    // Reward using bins whose residual is just above the item (snug placement).
    let snug = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += snug * snug * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial penalty on wasted residual (quartic, smooth).
    let x = pr / cap;
    score += 18.0 * x * x * (1.0 - t) + 30.0 * x * x * x * x * (0.5 + 0.5 * t);

    // Reward tight fits with a smooth saturating term.
    let tight = 1.0 - x;
    score -= 22.0 * tight * tight * tight;

    // Lookahead coupling: smooth Gaussian-like reward if next item fits post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let d = (pr - nxt) / cap;
        score -= 26.0 * (-18.0 * d * d).exp();
        // Penalize leaving residual just under next item (smooth hinge).
        let gap = (nxt - pr) / cap;
        if gap > 0.0 {
            score += 20.0 * gap * gap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mild penalty for spreading across many bins early.
    score += 1.5 * (open_bins_count as f64).ln() * (1.0 - t);

    // New-bin candidate: smooth neutralization, slightly favored when open bins are fragmented.
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.3 * t) + 0.4 * mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

