    } else if post_residual < 40 {
        score += 15.0;
    } else if post_residual < 60 {
        score -= 10.0;
    } else {
        score -= 20.0; // roomy bin keeps flexibility
    }

    // Modulo-10 harmonic class: residuals divisible by 10 pair well with sizes 10..80
    if post_residual % 10 == 0 {
