    } else {
        score += (post_residual % 10) as f64 * 0.7;
    }

    // Lookahead coupling: does this bin's post_residual still fit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // preserves a home for the next item
            // exact-class match: post_residual and next item share a decile
            if post_residual / 10 == next_item_size / 10 {
                score -= 6.0;
            }
        } else {
            score += 10.0; // creates dead space w.r.t. lookahead
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 25.0;
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only open when current bins are mostly full / poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = (mean_residual / bin_capacity as f64) < 0.30;
        // Penalize opening a bin mildly; relax penalty as stream progresses or bins are tight
        score += 55.0 - 25.0 * progress - if tight { 20.0 } else { 0.0 };
        // If item is large and would leave big gap anywhere, new bin is attractive
        if item_size > 70 {
            score -= 15.0;
        }
    }

    // Slight preference for concentrating load: fewer open bins favored
    score += (open_bins_count as f64) * 0.15;

    // Mean-residual drift: if this bin is above mean residual (empty-ish), favor filling it
    score -= (bin_residual as f64 - mean_residual) * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
