    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover; mildly penalize blocking.
        score += 5.0;
    }

    // Early in the stream, be slightly more willing to open bins (future flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: eliminate dead space aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly favor bins where the next item exactly fills the new residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits, but leaves another residual: mild penalty proportional to leftover.
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item does not fit this residual: penalize by the shortfall.
            score += 1.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residuals that are small but non-zero (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: prefer using bins with above-average residual
    // (keeps tight bins free for better fits), penalize draining already-tight bins.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    // and no lookahead synergy exists.
    if bin_residual == bin_capacity {
        score += 60.0;
        if post_residual < 15 || (next_item_size > 0 && next_item_size == post_residual) {
            score -= 200.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: reward small post_residual non-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score -= 40.0 * (1.0 - pr / cap).powi(3);

    // Penalize dead space that nothing typical could use (post_residual too small).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post_residual as f64 >= ns {
            let slack = post_residual as f64 - ns;
            score -= 30.0 * (1.0 - slack / cap);
        } else {
            score += 12.0; // next item won't chain into this bin
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 3 {
        score += 5.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 10.0 * (mean_residual / cap);
    }

    // Time horizon: early in the stream, be conservative (penalize fragmenting);
    // late in the stream, prefer tight packing aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * (1.0 - progress) * (pr / cap);
    score -= 15.0 * progress * (1.0 - pr / cap);

    // New-bin candidate: only attractive when current item is large and no good fit exists.
    if bin_residual == bin_capacity {
        if item_size >= 50 && post_residual as f64 >= item_size as f64 * 0.5 {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    // Slight penalty proportional to how much of the bin the item leaves unusable
    // relative to mean residual across bins (fragmentation coupling).
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = post_residual != 0;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills less aggressively; later, punish residual waste super-linearly.
    let progress_weight = t * t * (3.0 - 2.0 * t); // smoothstep in [0,1]
    score += progress_weight * (pr * pr) / c;

    // Penalize leaving residuals that are hard to fill (small relative to typical item sizes).
    let norm = pr / c;
    score += 8.0 * norm * norm * (1.0 - norm) * c * 0.1;

    // Reward using nearly-full bins (small post_residual) with a smooth saturating bonus.
    score -= 15.0 * (-pr / (0.25 * c)).exp();

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && fit {
        score -= 10.0;
    }

    // If many bins can fit the item, mildly penalize this one to spread load smoothly.
    if fitting_bins_count > 1 {
        let f = fitting_bins_count as f64;
        score += 3.0 * (f - 1.0) / (f + 1.0);
    }

    // Lookahead: smooth bonus if next item can fit into the post-residual.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / c);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / c) * (1.0 - pr / c);
    }

    // Mean-residual coupling: penalize bins far above the mean residual (smooth quadratic).
    let dev = (pr - mean_residual) / c;
    score += 5.0 * dev * dev * c * 0.1;

    // New-bin candidate handling: make empty bins attractive only when current bin would waste a lot.
    if bin_residual == bin_capacity {
        let waste_signal = (pr / c).powf(2.0);
        score = 20.0 + 30.0 * waste_signal - 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space after placement (integer division thresholds).
    let residual_class = post_residual / 10;
    score += match residual_class {
        0 => -40.0,           // perfect/near-perfect fit: strongly reward
        1 => -18.0,           // leaves 10-19: good candidate for small items
        2 => -6.0,            // 20-29: usable
        3 => 0.0,
        4 => 8.0,             // 40-59: mid-range, mildly wasteful
        5 => 12.0,
        _ => 20.0,            // large leftover: dead-space risk
    };

    // Modulo coupling: does the leftover resonate with common item-size classes?
    // Items 1..100 often cluster in multiples of 5/10; reward leftovers that are
    // multiples of 5 (likely to be exactly filled later).
    if post_residual % 5 == 0 {
        score -= 6.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has high base score already;
    // encourage opening a fresh bin when current open bins are fragmented
    // (high mean residual spread) but discourage when many bins are open.
    if bin_residual == bin_capacity {
        score -= 10.0;
        score += 0.15 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 12.0; // fragmentation: fresh bin may serve next big item
        }
    }

    // Slight preference for tighter bins (low bin_residual) to keep big holes open.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Progress bias: early in the stream, be conservative about opening bins;
    // late in the stream, exploit exact fits harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here afterwards: mild reward, scaled by tightness
            score -= 60.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // dead space relative to next item: penalize more when post_residual is small
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Tight fit reward relative to capacity
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 50.0 * tightness;

    // Penalize very small unusable residuals (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless this bin is a fresh empty bin AND
    // current fit would be very loose or no good fitting exists
    if bin_residual == bin_capacity {
        // baseline penalty so open bins are preferred, but escape hatch:
        // if the item fits poorly everywhere (loose fit), opening new bin is fine
        let loose = item_size as f64 / bin_capacity as f64;
        score = 300.0 - 250.0 * loose;
        if next_item_size > 0 && next_item_size >= item_size {
            // big item coming next: fresh bin can host both
            score -= 80.0;
        }
    }

    // Prefer filling bins with low mean residual (consolidate waste)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Slight preference for fewer open bins late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * tightness * 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward; if it
    // would leave a large unusable gap, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= (30.0 - waste as f64).max(-30.0) * 0.8;
        } else {
            // Next item won't fit here; penalize leaving awkward residual.
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.25;
        }
    }

    // New-bin candidate handling: only open a new bin when the item fits poorly
    // everywhere else or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fill = item_size as f64 / bin_capacity as f64;
        let mut penalty = 200.0; // default: discourage opening new bins
        // If item is large and mean residual is small, opening a new bin is fine.
        penalty -= fill * 120.0;
        penalty -= (100.0 - mean_residual.min(100.0)) * 1.2;
        // Late in the stream, opening a fresh bin is more acceptable.
        penalty -= progress * 40.0;
        if fitting_bins_count == 0 {
            penalty = -500.0;
        }
        score += penalty;
    }

    // Slight preference for bins with residual close to item_size (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    // Mild dispersion penalty: prefer bins below mean residual (tighter bins first)
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: post residual, with non-linear polynomial shaping by progress.
    let mut score = post * (1.0 + 0.8 * progress * (1.0 - progress));

    // Non-linear coupling: penalize large post residual more as stream progresses.
    score += 40.0 * norm_post * norm_post * progress;

    // Reward tight fits (small post residual) with smooth quadratic bonus.
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - progress);

    // Mean-residual deviation coupling: penalize bins far from mean residual.
    let dev = (post - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let fit_quality = (post - nx) / cap;
            score -= 20.0 * (1.0 - fit_quality * fit_quality);
        } else {
            score += 8.0;
        }
    }

    // Slight preference for fewer open bins late in stream (consolidation).
    score += (open_bins_count as f64) * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fraction bands.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0..1 fraction of capacity left

    // Integer-division harmonic classes of post_residual (mod arithmetic on capacity/10)
    let class_mod = post_residual % (bin_capacity / 10).max(1);
    score += class_mod as f64 * 0.35; // penalize off-class leftovers

    // Perfect fit band: tiny residual is excellent
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for typical items (1..100 unknown, use ~10 floor)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Fractional coupling: reward leaving residuals that match common size classes
    // (multiples of 10, 25, 50 of capacity)
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 22.0;
        // extra reward if next item fills it almost exactly
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to mismatch
        score += ((next_item_size - post_residual) as f64).min(30.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit. Penalize the fresh bin moderately,
    // but reduce penalty late in the stream or when mean residual is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + mean_residual * 0.15 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 70.0; // nothing else fits, must open
        }
    }

    // Mild preference for tighter bins overall (waste minimization)
    score += (bin_residual as f64 - post_f) * 0.0; // neutral placeholder
    score -= (1.0 - frac) * 5.0; // favor fuller bins slightly

    // Dampen spread across many open bins: encourage consolidation
    if open_bins_count > 8 {
        score += (open_bins_count as f64 - 8.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A residual gap is "dead" if it is smaller than the smallest conceivable item.
    // Items can be as small as 1, so treat very small gaps as pure waste, but
    // weight the penalty by how close post_residual is to the dead-zone boundary.
    let dead_threshold = 9.0_f64; // gaps <= 9 are effectively unusable for typical items
    if (post_residual as f64) < dead_threshold {
        // Heavily penalize leaving a tiny useless gap.
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Perfect fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: the smaller the post_residual relative to item size,
    // the better the packing density. Non-linear coupling.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 6.0;

    // Penalize leaving a gap that is just barely larger than the item itself
    // (a wasteful "second copy" of the item's footprint).
    if post_residual >= item_size && item_size > 0 {
        score += 8.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; penalize candidates that keep many
    // bins alive with mediocre residuals.
    let open_pressure = (open_bins_count as f64).sqrt() * 2.5;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the ONLY bin that can fit the item, using it
    // avoids opening a new bin — reward strongly unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this placement chains perfectly — reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }
    // If next item would be blocked by the post_residual gap (gap too small),
    // the dead space is confirmed wasted — extra penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a good fit. Scale its baseline
    // score so a tight existing fit beats opening a new bin, but a poor fit
    // (large post_residual in an open bin) loses to a fresh bin.
    if bin_residual == bin_capacity {
        // Fresh bin: post_residual = capacity - item_size, a clean large gap.
        // Slight penalty so tight existing fits win, but not overwhelming.
        score += 4.0;
        // When bins are few, opening fresh is cheap; when many are open, push
        // toward consolidation by penalizing new bins more.
        score += (open_bins_count as f64) * 1.5;
    } else {
        // Existing bin: mild bonus for reusing capacity.
        score -= 2.0;
    }

    // Mean-residual coupling: if this bin's post_residual is far below the mean
    // residual across open bins, we're reducing variance (good) — reward it.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score -= mean_gap * 1.2;
    } else {
        score += (-mean_gap) * 0.8;
    }

    // Mild progression term: late in the stream, prioritize closing bins out
    // (minimizing residual) since fewer items remain to fill gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.35;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness;

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover2 = post_residual - next_item_size;
        if leftover2 == 0 {
            score -= 60.0; // perfect 2-item chain fill
        } else {
            let frac = leftover2 as f64 / (bin_capacity as f64);
            score -= 30.0 * (1.0 - frac);
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize dead space
        score += 15.0 * ((post_residual as f64) / (bin_capacity as f64));
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor filling it to avoid waste
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Discourage opening a new bin when a good fit exists
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.3;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Late in stream: prefer compacting into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) nonlinearly
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if next item fits into post-residual, reward heavily
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + (next_item_size as f64 / bin_capacity as f64) * 15.0;
        } else {
            score += 8.0;
        }
        // Perfect pair packing: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // Global fragmentation pressure: many open bins with high mean residual
    let frag = mean_residual / bin_capacity as f64;
    if frag > 0.5 && open_bins_count > 3 {
        score += (frag - 0.5) * 20.0;
    }

    // Time horizon: early in stream, favor filling existing bins less aggressively
    // (keep flexibility); late in stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 6.0;

    // New-bin candidate handling: empty bin should only win when current bins fit poorly
    if bin_residual == bin_capacity {
        score += 45.0;
        // Allow new bin if all open bins would leave bad residuals
        if post_residual < 20 && fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // Early stream: opening bins is cheap, encourage it slightly
        score -= (1.0 - progress) * 10.0;
    }

    // Mild preference for bins with residual close to item size (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear penalty on mid-range residuals
    let mut score = pr as f64;
    score += 30.0 * norm_pr * (1.0 - norm_pr) * (norm_pr - 0.5).abs() * 2.0;

    // Smooth progress coupling: early on, tolerate larger residuals; later, punish them harder
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Interaction: post_residual vs next item fit (smooth sigmoid-like term)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_gap = (pr - ns) / cap;
        let bonus = 25.0 * (1.0 / (1.0 + (-fit_gap * 12.0).exp()));
        score -= bonus * (1.0 - 0.5 * progress);
    } else {
        // Last item: strongly prefer filling bins tightly
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Last-chance bin: reward using it, more so late in stream
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    }

    // Penalize bins far from mean residual (smooth dispersion term)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Mild penalty for opening new bins when many are open and item fits elsewhere
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals near multiples of
    // common item sizes (10..80 bucket classes) are "reusable", others dead.
    let cap_f = bin_capacity as f64;
    let frac = post_residual as f64 / cap_f;

    // Penalize small-but-not-zero dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward residuals that are exact harmonic multiples (likely to be
    // filled by future items drawn from modular size classes).
    let harmonic_bonus: f64 = if post_residual == 0 {
        -60.0 // perfect fit
    } else {
        let mut best = 0.0;
        for k in 1..=10u32 {
            let m = post_residual % k;
            if m == 0 {
                best += 2.0;
            }
        }
        // residual divisible by many small classes => flexible
        -best
    };
    score += harmonic_bonus;

    // Integer-division thresholds on post_residual: classify into bands.
    let band = post_residual / 20; // 0..5
    score -= match band {
        0 => 8.0,
        1 => 3.0,
        2 => 0.0,
        3 => 1.0,
        4 => 2.0,
        _ => 3.0,
    } as f64;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next fits but leaves another residual: mild reward scaled
            // by how little waste remains after the chain.
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap_f);
        } else {
            // next item cannot use this bin's remainder: penalize if the
            // remainder is in an awkward harmonic class (odd residual).
            if post_residual % 2 == 1 {
                score += 5.0;
            }
        }
    } else {
        // Last item: waste is final; minimize it hard.
        score += 0.0;
        score -= (cap_f - post_residual as f64) * 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: baseline cost of opening a fresh bin, modulated
    // by stream progress and how fragmented current bins are.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - frac * cap_f).abs();
        score = cap_f as f64 * 0.55 + 12.0 * progress + fragmentation * 0.2;
        // Don't open a new bin when a perfect-fit chain exists elsewhere.
        if next_item_size > 0 && post_residual == 0 {
            score -= 30.0;
        }
    }

    // Mild tie-breaking: prefer bins whose residual deviates below the mean
    // (tighter bins get filled first, keeping large holes open).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // (min item size 1..100 unknown, but small gaps rarely reusable) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= 2.0 * (item_size as f64 / bin_capacity as f64);

    // Penalize bins whose residual deviates from mean (avoid fragmenting many bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Pressure from number of open bins: with many open bins, prefer filling
    // existing bins over spreading; with few open bins, allow opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 5.0 + open_pressure;
    } else {
        score -= open_pressure * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.5 * next_item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item exactly fills the new residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 400.0;
    }
    // Penalize if next item can't fit into the post residual (dead space risk)
    if next_item_size > 0 && next_item_size > post_residual {
        score += 30.0;
    }
    // Reward if next item fits with small leftover (chained fit)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // Prefer bins with tighter residuals relative to mean
    score += (bin_residual as f64 - mean_residual) * 0.8;

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Mild penalty for opening a new bin
    if bin_residual == bin_capacity {
        score += 50.0 + 0.3 * (post_residual as f64);
    }

    // Penalize large unusable residuals (dead space)
    if post_residual < 10 && post_residual > 0 {
        score += 10.0;
    }

    // Slight preference for fewer open bins as stream progresses
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in fill ratio).
    let fill = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * fill * fill;

    // Penalize small dead space that nothing can ever use (post_residual < 10 threshold
    // generalized: dead space below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead: if the next item would fit exactly in the post-residual,
    // reward; if next item fits but this placement wastes space the next item
    // could have used better, penalize mildly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            score -= 2.0; // chain still possible
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 3.0; // this placement breaks the chain
        }
    }

    // New-bin candidate logic: empty bin gets a mild penalty so we only open
    // a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 4.0 + 0.5 * (open_bins_count as f64);
        // But if the item is large relative to capacity and mean residual is low,
        // opening fresh is more attractive.
        if (item_size as f64) > 0.5 * (bin_capacity as f64)
            && mean_residual < (item_size as f64) + 5.0 {
            score -= 10.0;
        }
    }

    // Global state: with many open bins, prefer consolidating into existing bins
    // (penalize spreading); scale with open_bins_count.
    score += 0.02 * (open_bins_count as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Time horizon: early in the stream, be slightly more conservative about
    // leaving fragmented residuals (long future ahead); late in stream, tight fits dominate anyway.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0 * (post_residual as f64) / (bin_capacity as f64);

    // Coupling with mean residual: bins with residual far from mean are
    // either unusually full (good) or unusually empty (bad to leave behind).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_norm = item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual)
    let mut score = post;

    // Smooth polynomial coupling: reward tightness more as stream progresses
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * (item_size as f64) * (0.5 + progress);

    // Penalize dead space that is too small to be useful (smooth trough)
    let dead_zone = (post - 20.0) / 20.0;
    score += 8.0 * dead_zone * dead_zone * (1.0 - progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post / cap);
    }

    // New-bin candidate: penalize opening bins early, allow it late or for big items
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) * (1.0 - fit_norm);
        // lookahead: opening a new bin is good if next item also large
        if next_item_size as f64 / cap + fit_norm > 1.0 {
            score -= 10.0;
        }
    } else {
        // reward keeping open-bin count low relative to mean residual
        score += (open_bins_count as f64).ln() * 0.5 * (mean_residual / cap - tightness).max(0.0);
    }

    // Lookahead smoothness: if next item fits this bin's post-residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
