pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // possible item (size 1) are pure waste; gaps below ~15 are nearly dead.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 120.0; // unusable dead space: heavy penalty
    } else if post_residual < 20 {
        score += 45.0;
    } else {
        // mild preference for compact residuals
        score += 0.1 * post_residual as f64;
    }

    // Reward bins whose residual exactly accommodates the next item (lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap just below the next item's size (near-miss waste).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 5 {
        score += 15.0;
    }

    // Open-bins pressure: with many bins open, prefer consolidating into
    // existing bins rather than fragmenting capacity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (4.0 + 6.0 * progress);
    score += pressure;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when the current fit is poor
    // (large post_residual) or few bins fit the item. Make the empty bin
    // moderately expensive so it wins only for bad fits.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open a new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin serves the lookahead well
        }
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.3 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement creates a perfect two-item chain — heavily reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits after this one; mildly reward tighter leftover.
            score -= 0.5 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // Next item won't fit here; penalize dead space relative to mean residual.
            score += 0.3 * ((post_residual as f64) - mean_residual).abs();
        }
    }

    // Penalize small unusable residuals (dead space below minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10 - post_residual) as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing open bins have large residuals
    // (encourage consolidation unless this bin is a fresh-bin candidate).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately so it is chosen only when
        // open bins offer poor fits.
        score += 20.0 + mean_residual * 0.1;
    } else {
        // Reward using bins with residuals far above mean (reduce spread).
        score -= 0.2 * ((bin_residual as f64) - mean_residual);
    }

    // Late in the stream, slightly favor tighter packs (less fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Lookahead: penalize if the next item cannot use the post-residual
    if next_item_size > 0 {
        if next_item_size as f64 > post_residual as f64 {
            // dead space relative to next item
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        } else {
            // next item fits: reward residual that closely hosts it
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 8.0 / (1.0 + gap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading, prefer filling existing bins
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 4.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (filling fuller bins first)
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Time horizon: early in stream, be conservative about wasting space; late, pack aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New-bin candidate: make it moderately attractive only when current bin would leave bad dead space
    if bin_residual == bin_capacity {
        // baseline for a fresh bin
        score += 15.0;
        if post_residual as f64 > 45.0 {
            // large item into fresh bin is fine
            score -= 20.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with a non-linear (quadratic) penalty
    // that grows for large wasted space, scaled by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress) + 25.0 * norm_pr * norm_pr;

    // Smooth interaction: post_residual squared normalized by mean residual level.
    // If mean residual is high, tight fits matter less; if low, chase tight fits.
    let mean_term = 1.0 / (mean_residual / cap + 0.15);
    score += 12.0 * norm_pr * norm_pr * mean_term;

    // Lookahead coupling: reward bins whose post-residual fits the next item
    // (smooth Gaussian-like bump rather than a hard threshold).
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        let fit_prob = (-(diff * diff) / (2.0 * 15.0 * 15.0)).exp();
        score -= 20.0 * fit_prob * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin (smooth ramp on scarcity).
    let scarcity = 1.0 / fitting_bins_count as f64;
    score -= 15.0 * scarcity;

    // Mild penalty for many open bins: encourage consolidation as stream grows.
    score += (open_bins_count as f64).ln() * 2.0 * norm_pr;

    // New-bin candidate: neutral-ish score so it is chosen only when all
    // open bins have poor fits; add slight decay over the stream.
    if bin_residual == bin_capacity {
        score = cap * 0.9 - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class decomposition of post_residual ----
    // Class = post_residual / 10 (decade band), remainder = post_residual % 10.
    let cls = post_residual / 10;
    let rem = post_residual % 10;

    // Small non-zero remainders are "awkward" dead space: penalize mildly.
    score += (rem as f64) * 0.18;

    // Class-based preference: near-full bins are great (cls 0 with rem 0 is perfect),
    // mid-range residuals (20-40) are the most reusable.
    score += match cls {
        0 => 4.0,          // tiny residual: likely dead space unless exactly 0
        1 => 1.5,
        2 => 0.0,          // sweet spot
        3 => 0.5,
        4 => 1.0,
        5 => 2.0,
        _ => 3.0,          // mostly empty bin: wasteful to use for a small item
    };

    // Perfect zero residual is the ideal outcome.
    if post_residual == 0 {
        score -= 12.0;
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // The next item exactly fills this bin after ours: extremely desirable.
            score -= 14.0;
        } else if next_item_size < post_residual {
            // Next item still fits: mild reward, scaled by how much room remains.
            score -= 3.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // Next item won't fit: this residual becomes dead space after us.
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.04;
        }
    }

    // ---- Last-chance logic ----
    if fitting_bins_count == 1 {
        // This is the only bin that can take the item; strongly prefer it
        // over opening a new bin.
        score -= 8.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Brand-new empty bin: add a fixed switching penalty so existing bins win
        // unless their fits are bad, plus pressure proportional to how many bins
        // are already open (encourage consolidation).
        score += 10.0 + (open_bins_count as f64) * 1.2;

        // Late in the stream, opening new bins is even less attractive.
        let progress = if total_items > 0 {
            step_index as f64 / total_items as f64
        } else {
            0.0
        };
        score += progress * 6.0;

        // If the current item nearly fills a fresh bin, opening one is fine.
        if post_residual <= 10 {
            score -= 9.0;
        }
    }

    // ---- Mean-residual context ----
    // If the average open residual is small (bins nearly full), reward tight fits more.
    score -= (mean_residual / bin_capacity as f64) * (bin_capacity - post_residual) as f64 * 0.02;

    // ---- Item-size harmony: reward bins whose class matches the item's decade ----
    let item_cls = item_size / 10;
    if cls == item_cls {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny gap is nearly dead space
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Penalize gaps that cannot fit the minimum plausible next item.
    if post_residual > 0 && next_item_size > post_residual {
        score += 12.0;
    }
    // Reward when this bin can also host the lookahead item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Open-bin pressure: fewer bins preferred, discourage scattering.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        // Neutral base; opening a bin is penalized mildly to prefer reuse.
        score += 15.0;
        // But if the item would leave a big hole in any existing bin, new bin ok.
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Late-stream tightening: conserve bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += post_residual as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Bonus decays with slack: good if next item leaves small remainder again.
            score -= 150.0 / (1.0 + slack * 0.15);
            if post_residual - next_item_size <= 10 {
                score -= 100.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to the wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.5;

    // Last-chance bin before opening a new bin: strong discount.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New empty bin candidate: penalize mildly so it is chosen only when
    // open bins give poor fits, but keep it viable early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 40.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 80.0;
        }
    }

    // Avoid fragmenting many open bins when a good fit exists elsewhere.
    if open_bins_count > 20 && post_residual > 40 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Penalize dead space that cannot fit typical items (very small residuals)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: reward leaving space for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
            // If next item fits exactly the leftover, big reward
            if post_residual == 0 || (next_item_size as f64 - post_residual as f64).abs() < 1.0 {
                score -= 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 35.0;
        // Late in stream, opening new bins is fine (fewer future regrets)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
        // If many open bins with large residuals, prefer new bin slightly less
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Global residual pressure: if mean residual is small, cherish every usable space
    if bin_residual as f64 > mean_residual {
        score += 4.0; // this bin is more spacious than average -> keep it for bigger items
    } else {
        score -= 4.0;
    }

    // Prefer placing large items into fuller bins
    score += (item_size as f64 / bin_capacity as f64) * 6.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: non-linear quadratic coupling of post_residual with progress
    score -= (1.0 - pr / cap) * (1.0 - pr / cap) * 12.0 * (0.5 + progress);

    // Penalize large dead space that becomes unusable (post_residual below typical item range)
    let dead = (30.0 - pr).max(0.0);
    score += dead * dead * 0.08 * (1.0 + progress);

    // Lookahead: reward leaving room for the next item exactly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            // ideal: post_residual == next_item_size (zero gap bonus)
            score -= (1.0 - (gap / cap).abs()) * 6.0;
            // also mild reward if next item fits into residual
            score -= (nxt / cap) * 4.0;
        } else {
            // post_residual too small for next item: penalize proportionally
            score += (nxt - pr) * 0.15 * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Many fitting bins: slight penalty to prefer best fit discrimination (already via pr)
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is close to mean (balanced packing),
    // with smooth non-linear deviation term
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // New-bin candidate handling: neutral-ish baseline; only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // mild cost so that open bins with decent fit win, but poor fits (large score) lose
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo-10 classes group residuals
    // into "usable slots". Small residuals (< 10) are dead space -> penalize.
    let dead = post_residual < 10;
    if dead {
        score += 40.0;
    } else {
        // Reward residuals that are harmonic with common item sizes (multiples of 10/20)
        let cls = post_residual % 10;
        if cls == 0 {
            score -= 12.0;
        } else if cls == 5 {
            score -= 4.0;
        } else {
            score += (10 - cls) as f64 * 0.6;
        }
        // Integer-division thresholds: residuals that can hold another medium item
        if post_residual >= 20 {
            score -= 6.0;
        }
        if post_residual >= 50 {
            score -= 4.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // perfect harmonic pairing: post_residual % next_item_size small
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's leftover -> mild penalty
            score += 5.0;
        }
    }

    // Capacity-fraction coupling: prefer filling large fractions of capacity.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= fill * 15.0;

    // Last-chance bin: if only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current residual is very small
    // or no good fit exists; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual * 0.5 {
            score += 25.0 + (open_bins_count as f64).sqrt() * 3.0;
        }
        // early stream: new bins are cheap-ish, late stream: expensive
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Tie-break toward tighter existing bins via mean residual deviation
        let dev = post_residual as f64 - mean_residual;
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large gaps.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0; // tiny gap = wasted space forever
        } else if post_residual <= 20 {
            score += 18.0;
        } else if post_residual <= 30 {
            score += 6.0;
        } else {
            score -= 5.0; // large residual remains usable
        }
    } else {
        score -= 60.0; // perfect fit, close the bin
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Last-chance bonus: only one bin fits the item, use it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins with below-mean residual (consolidate emptier bins? prefer fuller bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit in post_residual, small penalty for stranding it.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: empty bin is a fallback, only attractive when
    // no good fit exists (large item relative to residuals).
    if bin_residual == bin_capacity {
        let desperation = (item_size as f64 / bin_capacity as f64).powi(2);
        score = 55.0 - 45.0 * desperation;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // new bin leaves room for lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // Two-step lookahead: strongly reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 2.0;
        if post_residual as i64 == next_item_size as i64 {
            score -= 800.0;
        }
        // Penalize leaving residual too small for the next item (dead space trap)
        if next_item_size > post_residual && post_residual < 10 {
            score += 300.0;
        }
    }

    // Penalize deviation from mean residual (prefer balanced or tight bins).
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: make empty bins mildly attractive only when the item is large
    // and open bins are numerous with scattered residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + progress * 40.0;
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    // Mild reward for using bins with less remaining space overall (best-fit core).
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual penalty for large waste.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: strongly favor bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // Extra reward for chaining: next item would also leave a small residual.
            let chain = post_residual - next_item_size;
            if chain < 10 {
                score -= 12.0;
            }
        } else if post_residual < next_item_size && post_residual > 0 {
            // Dead space relative to lookahead: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // If next item won't fit anywhere else, keep this bin flexible.
        if post_residual < next_item_size && post_residual < 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when item is large relative to capacity
    // or the stream is early and there are many open bins with scattered residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_ratio = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for large items, bad for small ones.
        score += 45.0 * (1.0 - size_ratio);
        // Later in the stream, prefer consolidating into open bins.
        score += progress * 25.0;
        // Many open bins with high mean residual: discourage new bins.
        if mean_residual > item_size as f64 {
            score += 20.0;
        }
        // If no existing bin fits well (this is the only fitting option), soften the penalty.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
        // Small items in a fresh bin waste capacity.
        if item_size <= 30 {
            score += 15.0;
        }
    }

    // Mild preference for bins below mean residual (balancing across bins).
    let res = bin_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - res) * 0.05;
    }

    // Early stream: encourage keeping bins tight since many items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = post / cap;

    // Base: post residual, non-linearly warped so small dead space is tolerated
    // but large wasted residual is heavily penalized (quadratic/quartic coupling).
    let mut score = post + 120.0 * post_norm * post_norm + 60.0 * post_norm * post_norm * post_norm * post_norm;

    // Smooth stream-progress coupling: late in the stream, tighten residual preference.
    let late = progress * progress;
    score += 40.0 * late * post_norm;

    // Reward tight fits: subtract when post_residual is small relative to item size.
    let tightness = 1.0 - post_norm;
    score -= 30.0 * tightness * tightness * (item_size as f64 / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual as u32 {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 20.0 * (1.0 - gap) - 10.0 * gap * gap;
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by how much it overshoots.
        let over = (next_item_size as f64 - post) / cap;
        score += 8.0 * over.min(1.0);
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    // from the mean (below-mean residual = tighter bin, reward slightly).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev.abs();

    // Mild pressure against proliferating bins early when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that stay "usable"
    // for common item sizes. Class by integer division into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item
    // (<= 10) are wasted; penalize quadratically.
    if post_residual < 10 {
        score += (10.0 - post) * 4.0 + 15.0;
    }

    // Harmonic class reward: residual divisible into nice fractions of capacity
    // (e.g. post_residual mod 25 == 0, or mod 10 == 0) is more likely to be
    // filled by future items of typical sizes.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
        // Integer-division threshold classes on post_residual
        let class = pr / 20; // 0..=4 harmonic bucket
        score -= class as f64 * 2.0;
    } else {
        // Perfect fit: best possible outcome.
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            // next item fits, but how well? penalize large leftover after next.
            let after_next = post_residual - next_item_size;
            score -= 6.0 - (after_next as f64) * 0.15;
            if after_next % 10 == 0 && after_next > 0 {
                score -= 4.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when open bins have poor fit potential.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened frivolously.
        score += 30.0;
        // But if the item is large and residual structure of open bins is bad,
        // a fresh bin becomes competitive.
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= (frac - 0.5) * 40.0;
        }
        // If mean residual across open bins is small, new bin is reasonable.
        score -= (mean_residual / cap).max(0.0) * 10.0;
        // Late in stream, prefer closing out with existing bins less.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Prefer filling bins with tighter residuals (best-fit flavor) with
    // a non-linear squeeze.
    let tightness = 1.0 - (bin_residual as f64 / cap);
    score -= tightness * tightness * 5.0;

    // Many open bins: encourage consolidation.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than larger leftovers.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
        } else {
            // Larger leftovers are partially recoverable; mild reward for tight fits.
            score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Pressure term: discourage spreading across many open bins when residuals are already fragmented.
    score += 0.35 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if the next item can fit into the resulting residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Late in the stream, consolidation matters more; early on, allow new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized later unless current fits are terrible.
        score = 45.0 + 55.0 * progress - 30.0 * (post_residual as f64 / bin_capacity as f64);
        if fitting_bins_count == 1 {
            score += 80.0; // never open a new bin when a last-chance fit exists
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        // Exact match: post_residual equals next item's size -> perfect 2-step chain.
        if post_residual == next_item_size {
            score -= 1000.0;
        } else {
            let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
            // Reward closeness to next item size (soft matching).
            score -= (50.0 / (1.0 + diff)).max(0.0);
            // Penalize dead space that is too small for the next item.
            if post_residual < next_item_size && post_residual > 0 {
                let wasted = post_residual as f64;
                score += 3.0 * wasted * (1.0 + (next_item_size - post_residual) as f64 / 20.0);
            }
            // Reward residual large enough to hold the next item too.
            if post_residual >= next_item_size {
                score -= 5.0;
            }
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 2.0 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual near the mean are "typical";
    // prefer filling bins whose residual is below mean (tighter bins) mildly.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is a terrible dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 10.0; // still better to use it than waste the bin
        }
    }

    // New-bin candidate handling: an empty bin is a fallback. Penalize it so we
    // only open a new bin when existing bins have bad fits (large post_residual
    // relative to capacity, i.e. poor utilization of an existing bin).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * (open_bins_count as f64);
        // If the item perfectly chains with a fresh bin, allow opening it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 500.0;
        }
    }

    // Progression-aware tightness pressure: later in the stream, favor tighter packs.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * item_size as f64;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // Next item fits here: strong reward for preserving this slot.
                score -= 12.0;
            } else {
                // Next item cannot use the leftover: penalize proportional waste.
                score += 0.25 * post_residual as f64;
            }
        } else {
            // Last item: waste matters fully.
            score += 0.5 * post_residual as f64;
        }
    }

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins whose residual is below mean (consolidating fuller bins),
    // but avoid over-penalizing the emptiest bins early.
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.15 * diff;

    // Time horizon: early in stream, favor keeping large residuals flexible;
    // late in stream, favor filling bins completely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.1 * post_residual as f64;
    score -= progress * 0.2 * item_size as f64;

    // Many open bins: discourage spreading; few open bins: opening new bin ok.
    let spread_pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 10.0);
    score += spread_pressure * 0.5 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && next_item_size > post_residual && post_residual < item_size / 2);
        if poor_fit {
            score -= 5.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic) shaping
    let mut score = pr + 60.0 * pr_norm * pr_norm;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = pr_norm * (progress - 0.5) * (progress - 0.5);
    score += 80.0 * coupling;

    // Penalize leaving residuals that no plausible item fits well as stream progresses
    let dead = (pr_norm - (pr_norm * pr_norm)) * (1.0 - progress);
    score += 40.0 * dead;

    // Reward using bins when few fitting bins remain (last-chance bonus)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: bonus if next item fits into post residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            score -= 15.0 * (1.0 - (next / pr)) * (1.0 - 0.5 * progress);
        } else {
            score += 10.0 * ((next - pr) / cap);
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 5.0 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // Prefer bins below mean residual (fill emptier bins less)
    score += 8.0 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but dead space below ~20 is nearly unusable.
    if post_residual < 20 {
        score += 25.0 * (20 - post_residual) as f64;
    }

    // Harmonic class of post_residual: residue modulo 10 (capacity fractions / decile classes).
    let class = post_residual % 10;
    score += match class {
        0 => -8.0,           // perfectly aligned residual, highly reusable
        1 | 9 => 3.0,        // nearly aligned, mild penalty
        2 | 8 => 1.0,
        5 => 0.0,            // half-class, neutral
        _ => 2.0,            // awkward middle residues
    };

    // Integer-division thresholds: which "harmonic slots" can future items fill?
    // A residual is reusable if it exceeds a plausible small-item threshold.
    let slot = post_residual / 10; // 0..=10
    score -= slot as f64 * 4.0;

    // Coupling with next item: harmonic match between post_residual and next_item_size.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 60.0; // next item exactly fills this bin: perfect chaining
        } else if diff > 0 && diff < 15 {
            score -= 20.0; // next item leaves a small, class-aligned remainder
        } else if diff < 0 && (-diff) < 10 {
            score += 15.0; // next item just misses this bin
        }
        // modulo harmony: post_residual % next_item_size small => divisible structure
        if next_item_size > 0 && post_residual % next_item_size.max(1) <= 2 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: any residual is wasted; minimize it hard.
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: keep it available but not preferred unless current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score = 70.0 + fragmentation * 40.0 - (open_bins_count as f64 * 0.5);
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
    }

    // Stream progression: late in stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.5;

    // Penalize bins far from mean residual (outliers create fragmentation).
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        // Gap is "dead" if the next item can't use it.
        let gap_unusable = next_item_size > post_residual;
        // Relative dead-space ratio of the bin after placement.
        let dead_ratio = post_residual as f64 / bin_capacity as f64;

        if gap_unusable {
            // Small unusable gaps are the worst: superlinear penalty.
            if post_residual <= 10 {
                score += 25.0 + (10 - post_residual) as f64 * 3.0;
            } else {
                score += 8.0 + dead_ratio * 20.0;
            }
        } else {
            // Usable leftover: mild reward proportional to tightness of fit.
            score -= (item_size as f64 / bin_capacity as f64) * 4.0;
        }

        // Perfect fit gets a strong bonus.
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + (item_size as f64 / bin_capacity as f64) * 8.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading across bins;
    // with few open bins, mild encouragement to fill existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (10.0 + 40.0 * progress);
    score += bin_pressure * 1.5;

    // Coupling with mean residual: if this bin's post-residual is far below the
    // mean residual, we are consolidating space — reward it.
    let consolidation = mean_residual - post_residual as f64;
    if consolidation > 0.0 {
        score -= consolidation.min(40.0) * 0.15;
    } else {
        score += (-consolidation).min(40.0) * 0.05;
    }

    // New-bin candidate: baseline score so a new bin is chosen only when all
    // open bins have poor fits (their penalties would need to be lower).
    if bin_residual == bin_capacity {
        score = 60.0 + open_bins_count as f64 * 0.3;
        // Early in the stream, opening bins is cheap; later, expensive.
        score += progress * 10.0;
        // If the next item is large and this item is large, a fresh bin
        // preserves flexibility.
        if next_item_size >= item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward post_residual that exactly matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;

        // Perfect chain: this bin will be exactly filled by the next item.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Next item fits comfortably: mild reward scaled by tightness.
        if post_residual >= next_item_size && post_residual <= next_item_size + 15 {
            score -= 10.0;
        }
        // Next item cannot fit here: penalize proportionally to wasted residual.
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: strongly prefer tightest possible fit.
        score += (post_residual as f64) * 0.5;
    }

    // Tightness relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Penalize very small unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current fit is terrible.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score += 20.0 + fit_quality * 30.0;
    }

    // Slight preference to fill older/more-filled bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: reward if the next item fits exactly well into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (bin_residual - item_size) as f64 > 0.6 * bin_capacity as f64;
        if poor_fit {
            score -= 15.0 + 10.0 * (1.0 - progress);
        } else {
            score += 35.0 + open_bins_count as f64;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: prefer reusing bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening over stream progress
    let mut score = norm_pr * (1.0 + 2.0 * progress * progress);

    // Quadratic penalty for awkward mid-range dead space
    let dead = norm_pr * (1.0 - norm_pr);
    score += 4.0 * dead * (0.5 + progress);

    // Reward tight fits (post_residual near zero) more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: avoid opening new bins when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Lookahead coupling: if next item fits the post-residual exactly, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let match_quality = pr - next_item_size as f64;
        score -= 3.0 * (1.0 - match_quality / cap) * (1.0 - match_quality / cap);
    } else if next_item_size > 0 {
        score += 1.5 * progress;
    }

    // Prefer fuller bins relative to the fleet mean residual
    score += 0.5 * ((mean_residual - pr) / cap).max(-1.0);

    // Slight bias against spreading across many bins early on
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral-ish but penalized if decent open bins exist
    if bin_residual == bin_capacity {
        score += 8.0 - 4.0 * progress + 0.1 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 buckets capture
    // "how divisible the leftover space is" by common item granularities.
    let post_mod = post_residual % 10;
    // Residuals that are multiples of 10 (or 5) are reusable by typical
    // item sizes; odd/prime-ish leftovers are dead space.
    let harmonic_bonus: f64 = match post_mod {
        0 => -14.0,
        5 => -7.0,
        2 | 4 | 6 | 8 => -3.0,
        _ => 4.0, // odd, non-multiple-of-5: penalize
    };
    score += harmonic_bonus;

    // Integer-division threshold: post_residual >= 50 still fits a mid item,
    // post_residual in [30,49] fits only small items, below 20 is near-dead.
    if post_residual >= 50 {
        score -= 10.0;
    } else if post_residual >= 30 {
        score -= 4.0;
    } else if post_residual >= 20 {
        score += 2.0;
    } else if post_residual > 0 {
        score += 12.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward if the post residual can host next_item_size
    // (with a small margin), penalize if it just barely cannot.
    if next_item_size > 0 {
        if post_residual >= next_item_size + 5 {
            score -= 8.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin would be a bad fit anyway.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // or mean residual is low (existing bins nearly full).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 28.0
            - 0.15 * open_bins_count as f64
            - 10.0 * (1.0 - mean_residual / bin_capacity as f64);
        // Late in the stream, prefer consolidating into open bins.
        new_bin_score += 8.0 * progress;
        // If the item is large, a fresh bin leaves a clean harmonic residual.
        if item_size % 10 == 0 {
            new_bin_score -= 4.0;
        }
        score = score.min(new_bin_score + 40.0);
        score = new_bin_score.max(score.min(new_bin_score + 40.0));
    }

    // Mild preference for tighter fits (small post_residual relative to item).
    score += (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Harsher penalty for mid-range dead space that only fits tiny items.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (low post residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Open-bin pressure: with many open bins, discourage opening new ones,
    // but if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless
    // current item is large and fits well in an empty bin.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / 8.0).min(3.0);
        score += 10.0 + 8.0 * pressure;
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item would fit in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    }

    // Slight late-stream conservatism: keep bins consolidated as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64 / 10.0).min(1.0);

    // Mild preference toward bins with below-average residual (fill emptier bins first).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= (bin_capacity as f64) / (1.0 + gap as f64);
        // Perfect chaining bonus
        if gap == 0 {
            score -= bin_capacity as f64;
        }
    }

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += post_residual as f64;
    }

    // Relative to mean residual: prefer bins that are already "low" residual
    // (concentrate waste in few bins rather than spreading it).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: make a fresh bin only mildly attractive,
    // and only when current item is large relative to capacity or many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        score = (bin_capacity as f64) * 0.75
            - 20.0 * big_item
            - 10.0 * progress
            + 2.0 * open_bins_count as f64;
        // If next item is huge, opening a fresh bin now may chain well.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= next_item_size as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no future item (min size 1..100 unknown; use item scale) can use.
    if post_residual > 0 {
        let waste = post_residual as f64 / item_size.max(1) as f64;
        score += 8.0 * waste.min(4.0);
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item then fits almost perfectly.
            let post2 = post_residual - next_item_size;
            score -= 6.0 * (1.0 - post2 as f64 / bin_capacity as f64);
        } else {
            // Post-residual too small for lookahead item: penalize proportionally.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Time horizon: early in the stream, be more conservative (prefer spreading);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> favor consolidation.
    if open_bins_count > 2 {
        score -= 2.0 * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // New-bin candidate handling: only attractive when item is large relative to
    // capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin.
        score += 20.0;
        // Worth it for large items or when many bins already exist and fits are poor.
        score -= 25.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            // Deter opening new bins when alternatives exist, more so late in stream.
            score += 15.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: post_residual penalized more strongly as stream progresses
    let coupling = norm_pr * norm_pr * (1.0 + progress * 8.0);
    score += 12.0 * coupling;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    let tight = (-norm_pr * 6.0).exp();
    score -= 8.0 * tight;

    // Penalize wasting a last-chance bin
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_pr);
    }

    // Lookahead: favor leaving space usable by the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = ((pr - nxt).abs() as f64).min(pr) / cap;
        score += 5.0 * usable * (0.5 + progress);
    }

    // Deviation from mean residual: prefer bins near the mean to keep balance
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * dev * (1.0 + progress);

    // Slight preference to fill existing bins rather than open new ones
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += 3.0 * new_bin * (1.0 + progress * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets penalize "awkward" dead space
    let pr = post_residual as i64;
    let class = pr % 10;
    if pr > 0 {
        // dead space that is a multiple of 10 is more reusable
        score += 0.6 * (10 - class) as f64;
    } else if pr == 0 {
        score -= 12.0; // perfect fit is excellent
    }

    // Reward tight fits: fraction of bin consumed by this item
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill * fill;

    // Harmonic pairing: if next item exactly matches post_residual, huge reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            score += 3.0; // next item won't fit here anyway
        }
        // modulo-class match between next item and post residual (both multiples of same class)
        if post_residual > 0 && next_item_size % 10 == post_residual % 10 && next_item_size < post_residual {
            score -= 2.5;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins are already open and mean residual is large
    if bin_residual == bin_capacity {
        score += 10.0 + 0.15 * open_bins_count as f64 + 0.05 * mean_residual;
    } else {
        score -= 1.0;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Integer-division threshold: post_residual in 1..10 is nearly dead space
    if pr > 0 && pr / 10 == 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving space that still fits the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: penalize proportionally to wasted fraction.
        score += 8.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Pressure from number of open bins: discourage spreading when many bins are open.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless current placement would create
    // severe dead space or no bin fits well. Baseline cost of opening a bin.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 20.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            // No real alternative: opening a new bin is fine.
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin preserves room for a larger next item
        }
    }

    // Slight preference for tighter bins overall.
    score += 0.3 * (bin_capacity as f64 - bin_residual as f64).recip() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Lookahead: reward when post_residual exactly matches next item (perfect chain).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as u32 >= next_item_size {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize dead space relative to gap.
            score += 10.0 + gap * 0.3;
        }
    }

    // Relative to mean residual: bins with residual far below mean are more "spent",
    // favor filling them rather than fragmenting fresh space.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 15.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        score += 5.0; // many options: be pickier
    }

    // New-bin candidate handling: only attractive when current fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score = bin_capacity as f64 - 20.0 * poor_fit
            - if fitting_bins_count == 0 { 40.0 } else { 0.0 };
    }

    // Early stream: keep bins open/consolidated; late stream: minimize residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual closely matches item size.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= 30.0 * (1.0 - tightness / bin_capacity as f64);

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Extra reward for near-perfect two-item packing.
        if post_residual - next_item_size <= 5 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize leaving space that blocks the known next item.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 20.0;
        // If many bins can fit the item, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 40.0 * (fitting_bins_count as f64).ln();
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If mean residual across open bins is large, prefer using open bins.
        score += mean_residual * 0.3;
    }

    // Mild preference for filling bins that are already relatively full.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Penalize excessive bin sprawl: favor reusing existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, tolerate larger post_residuals; late, penalize heavily.
    let pr = post_residual as f64 / bin_capacity as f64;
    let coupling = pr * pr * (0.5 + 2.5 * progress * progress) * bin_capacity as f64;
    score += coupling;

    // Reward tight fits (small post_residual) with a smooth bonus.
    score -= (1.0 - pr).powi(3) * 10.0;

    // Penalize dead space that no plausible item can use (smoothly).
    let dead = (pr - 0.1).max(0.0);
    score += dead * dead * 30.0 * (0.3 + 0.7 * progress);

    // Lookahead: if next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (1.0 - gap / bin_capacity as f64).max(0.0) * 15.0;
        // Penalize if post_residual is too small for next item (waste potential).
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_residual as f64) * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 - 0.5 * progress);
    }

    // Crowd effect: many open bins -> encourage consolidation via mean residual alignment.
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += mean_gap * 0.3 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate handling: make empty bin attractive only when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = bin_capacity as f64 * (0.6 + 0.4 * fragmentation) - 25.0 * (1.0 - fragmentation);
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    if post_residual == 0 {
        score -= 500.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Harmonic classes: dead space classes on post_residual.
    // Residuals that cannot accommodate even the smallest future item (<=10)
    // are pure waste; residuals in "awkward" classes (11..=19) are nearly waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 11 && post_residual <= 19 {
        score += 25.0; // awkward class
    }

    // Modulo-based classes on post_residual relative to common item sizes
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 15.0; // round residual keeps future alignment options
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 250.0; // chain fill
        } else if slack <= 10 {
            score -= 80.0;
        } else {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item does NOT fit here: this bin's residual becomes dead-ish
        score += 30.0;
        if post_residual < next_item_size && post_residual >= 10 {
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: empty bin should score like a mediocre choice;
    // only open new bins when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 * 0.55; // ~55
        // Cheaper to open new bin late in stream (fewer wasted openings amortized)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // If many open bins already fit the item, opening new bin is wasteful
        if fitting_bins_count > 0 {
            score += 40.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If next item is large and current item small, new bin may be useful
        if next_item_size > 0 && next_item_size >= 60 && item_size <= 30 {
            score -= 25.0;
        }
        // Last-chance override: never open new bin if it's the only fitting bin
        if fitting_bins_count == 1 {
            score += 500.0;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64;

    // Prefer bins with residual below mean (concentrate fill)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are worthless. Penalize them heavily.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + next_item_size as f64 * 0.15;
        } else {
            // Post residual can't fit next item: mild penalty, worse if tiny gap.
            score += 6.0;
        }
        // Bonus if this placement leaves room for BOTH nothing wasted and
        // chains well: exact match with next item after placement.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (larger post_residual is worse); with few bins, tight fits matter more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.35 * (1.0 - progress * 0.5);

    // New-bin candidate: make it attractive only when it avoids dead space
    // elsewhere or no good fit exists. Base new-bin score so that it wins
    // when the best existing placement leaves a large unusable residual.
    if bin_residual == bin_capacity {
        // A fresh bin gives post_residual = capacity - item_size, which is
        // already large; add pressure so it only wins when needed.
        score += 15.0 + open_bins_count as f64 * 1.2;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin accommodates lookahead well
        }
    }

    // Slight nudge toward bins whose residual is above average (balance load).
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is good.
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this placement creates a perfect chain — strongly reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here afterwards: mild reward proportional to leftover.
            score -= 5.0;
        } else {
            // Next item won't fit in post_residual: penalize creating unusable space.
            let waste = next_item_size - post_residual;
            score += 0.35 * waste as f64;
        }
    }

    // Penalize post_residuals that are too small for the minimum item size
    // (dead space): anything below ~10 units is likely wasted.
    if post_residual < 10 {
        score += 15.0 * (10.0 - post_residual as f64);
    }

    // Compare against mean residual: placing into a bin with residual far below
    // mean keeps big-capacity bins available for larger future items.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, prefer closing bins (tight fits) over spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it moderately unattractive unless everything else is bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the next item is large and current bins are tight, opening fresh is fine.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 12.0;

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space penalty scaled by how unusable the leftover is
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += (next_item_size as f64 - dead) * 0.15;
            }
        }
    }

    // Last chance bonus: only bin that fits -> strong incentive to use it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize scattering across many open bins when mean residual is low
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 1.5 * (1.0 - mean_residual / bin_capacity as f64);
    }

    // Time horizon: late in stream, prefer compacting into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0;

    // New-bin candidate: make empty bin mildly unattractive unless leftovers are tiny
    if bin_residual == bin_capacity {
        score += 8.0 + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: residual value shrinks as stream progresses
    let decay = 1.0 - 0.6 * progress * progress;
    score -= pr * 0.3 * decay;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.5 + 2.0 * progress);
        } else {
            score -= (pr - nxt).min(30.0) * 0.4;
        }
    } else {
        score += pr * 0.2; // last item: prefer tightest fill
    }

    // Reward near-perfect fits smoothly (quadratic in normalized waste)
    let waste_norm = pr / cap;
    score += waste_norm * waste_norm * cap * (0.8 + 1.2 * progress);

    // Last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).ln();
    }

    // Slight preference for bins below mean residual (balancing)
    score += 0.1 * (pr - mean_residual);

    // New-bin candidate: mildly discouraged unless stream early and residuals fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64).ln().max(0.0);
        score += 8.0 + fragmentation * (1.0 - progress) - 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize post_residual classes that are hard to fill (small but nonzero).
    let class = post_residual % 25; // harmonic quarter-capacity classes
    match class {
        0 => { score -= 30.0; }          // perfectly aligned residual: excellent
        1..=9 => { score += 25.0; }      // tiny dead space: nearly unusable
        10..=19 => { score += 10.0; }    // awkward middle gap
        _ => { score -= 8.0; }           // >= 20/25 fraction: still reusable
    }

    // Non-linear reward for tight fits (small post_residual but not tiny gap).
    if post_residual > 0 && post_residual <= 10 {
        score -= 15.0 * (1.0 - frac * 10.0);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let nxt_class = (post_residual - next_item_size) % 25;
            if nxt_class == 0 { score -= 25.0; }
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here: penalize slightly if we waste capacity.
            score += 6.0;
        }
    }

    // Prefer filling bins with below-average residual (consolidate emptiness).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Early stream: slightly favor keeping bins open (more consolidation later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // New-bin candidate: only attractive when current bin would leave bad class.
    if bin_residual == bin_capacity {
        score = 45.0 + frac * 10.0 - (post_residual as f64 - item_size as f64).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space hard (strict dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: reward strongly to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would be blocked by this placement, penalize slightly.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 8.0;
    }

    // New-bin candidate: penalize, scaled by how much capacity would be wasted
    // and how many bins are already open (open-bin pressure).
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
    }

    // Mild pressure toward bins with tighter residuals (fill fuller bins first).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits perfectly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0); // perfect 2-step match strongly favored
    } else if next_item_size > 0 {
        // next item won't fit in this bin's remainder: penalize dead space
        score += 0.35 * post_residual as f64;
    }

    // Penalize large residual that likely becomes unusable dead space
    score += 0.15 * post_residual as f64;

    // Tight fits (small post residual) are good
    score -= 0.25 * (bin_capacity as f64 - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if this item is huge relative to mean residual, opening fresh is less bad
        score -= 0.2 * (item_size as f64 - mean_residual).max(0.0);
    }

    // Compare against mean residual: bins below mean residual are tighter, prefer them
    score += 0.1 * (post_residual as f64 - mean_residual);

    // Late in stream: conserve bins, tighten packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Small dead space bonus (non-linear)
    if post_residual > 0 && post_residual <= 10 {
        score -= 20.0 / post_residual as f64;
    }

    // Penalize large dead space quadratically
    score += (post_residual as f64).powi(2) * 0.01;

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
        } else if next_item_size == post_residual {
            score -= 80.0;
        } else {
            // next item won't fit here; penalize wasted residual relative to next item
            score += (post_residual as f64 - (next_item_size as f64)).abs() * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // More fitting bins -> this bin less special, slight penalty
    if fitting_bins_count > 1 {
        score += fitting_bins_count as f64 * 2.0;
    }

    // Time horizon: early in stream, encourage consolidation into open bins;
    // late in stream, be less picky (fewer bins matter more than fit quality)
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= progress * 15.0;

    // Global state: if many open bins with high mean residual, prefer spreading
    if mean_residual > 0.0 {
        let gap = (bin_residual as f64 - mean_residual).abs();
        score += gap * 0.3;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // and no good fit exists (residual == capacity means empty bin)
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening new bin is attractive for large items late in stream
        score += 60.0 - item_frac * 50.0 - progress * 20.0;
        // but attractive if next item is small and could share
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = pr / cap;

    // Base: prefer tight fits (small post_residual), with polynomial coupling
    // to stream progress: later in the stream, dead space becomes more costly.
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Quadratic penalty on wasted residual, amplified late in the stream.
    score += 0.8 * fit_frac * fit_frac * cap * (0.5 + progress);

    // Reward bins that are already fairly full (small relative residual).
    let fill_ratio = 1.0 - (bin_residual as f64) / cap;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, scaled by alternatives.
        score += 2.0 * ((fitting_bins_count as f64).ln());
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably from the mean (below-mean residual = tighter bin).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 4.0 * dev;

    // Lookahead (k=2): penalize leaving residual that is too small OR
    // awkwardly larger than the next item (encourage post_residual that
    // either fits next_item exactly-ish or is very small).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        // Perfect match bonus: post_residual equals next item size.
        score -= 10.0 * (-gap / 10.0f64.max(0.15 * cap)).exp();
        // Penalty if post_residual is nonzero but cannot fit next item.
        if pr > 0.0 && pr < nxt {
            score += 8.0 * (1.0 - pr / nxt);
        }
    }

    // New-bin candidate handling: an empty bin has pr == cap; make it
    // attractive only when fits are poor or late in the stream.
    if (bin_residual as u32) == bin_capacity {
        // Baseline cost of opening a new bin.
        score = cap * 0.85 + 10.0 * progress;
        // If the current item is large relative to capacity, new bin is fine.
        score -= 0.3 * item;
        // If many bins are open and residuals are fragmented, opening fresh
        // is more attractive.
        score -= 1.5 * (open_bins_count as f64);
        // If next item is huge, a fresh bin preserves room.
        if next_item_size > 0 {
            score -= 0.2 * (next_item_size as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo 10: residuals that are multiples of 10
    // are more reusable for typical item sizes.
    let mod10 = post_residual % 10;
    score += (mod10 as f64) * 0.8;

    // Small unusable dead space penalty: residuals in 1..10 are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // If next item can exactly fit the post residual, big reward (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 400.0;
        } else if slack < 10 {
            score -= 120.0;
        } else {
            score -= 20.0;
        }
    }
    // Next item cannot fit here: penalize if this bin would become dead space.
    if next_item_size > post_residual && post_residual < 15 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current item leaves a bad residue
    // or no open bin is a good harmonic match.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 120.0;
        // Cheaper to open new bin early in the stream (amortization).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 80.0 * (1.0 - progress);
        // If next item is large, a fresh bin keeps flexibility.
        if next_item_size >= 60 {
            score -= 40.0;
        }
        // If item leaves a harmonic residue (multiple of 10) in an existing bin,
        // discourage opening a new bin.
        if post_residual % 10 == 0 && post_residual < 40 {
            score += 60.0;
        }
    }

    // Prefer tighter bins among fitting ones: reward closeness of fit.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 50.0 * fit_ratio * fit_ratio;

    // Slight preference to balance bin count vs mean residual.
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, min item size) are pure waste.
    if post_residual < 10 {
        score -= 40.0; // perfect/near-perfect fill is excellent
    } else if post_residual <= 20 {
        // Small gaps that only fit the tiniest items are risky dead space.
        score += 12.0;
    }

    // Reward tight fits relative to item size (relative waste).
    let relative_waste = post_residual as f64 / (item_size.max(1) as f64);
    score += relative_waste * 3.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize creating new bins when many are already open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 60.0 + 40.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // Candidate new bin: only attractive if current bin leaves a big
        // unusable gap or open bins are congested.
        score += new_bin_penalty;
        score += open_bins_count as f64 * 2.0;
        // If next item is large and current post_residual can't hold it,
        // opening a fresh bin becomes more attractive.
        if next_item_size > post_residual && post_residual < 10 {
            score -= 45.0;
        }
    } else {
        // Slight preference to keep bins balanced: avoid dumping into the
        // emptiest bin when many bins are open.
        if (bin_residual as f64) > mean_residual * 1.5 {
            score += 8.0;
        }
        // If this placement leaves room exactly for the next item, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // If placement leaves a gap just below the next item's size (unusable
        // for the lookahead), penalize.
        if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer bins whose post-residual exactly matches the next item (2-step lookahead).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if (post_residual as f64 - next).abs() <= 5.0 {
            score -= 25.0; // near-perfect chain
        } else if post_residual >= next_item_size {
            score -= 10.0; // next item still fits here
        } else {
            // dead space: next item cannot use the leftover
            score += (next - post_residual as f64) * 0.8;
        }
    } else {
        // Last item: just minimize waste
        score += post_residual as f64 * 0.5;
    }

    // Reward tight fits relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Penalize residuals far below mean (creating unusable slivers).
    if (post_residual as f64) < mean_residual - 10.0 {
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if next item is large and current fit is poor, new bin is attractive.
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score -= 30.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 * 0.4);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to hold even the smallest item (<=10),
    // but exempt perfect fits.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0; // chain-fit: next item nearly fills remainder
        } else {
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual is dead for the next item: penalize proportionally.
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, mild penalty to encourage discrimination among bins.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is attractive early (many items remain) or when the
        // item fits poorly everywhere (large post_residual in any open bin).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let horizon = 1.0 - progress; // remaining fraction of stream
        // Base cost of a new bin, discounted when the stream is long.
        score = 100.0 - 55.0 * horizon.min(1.0);
        // If the item would leave a nearly-empty remainder in any open bin,
        // opening fresh is fine; otherwise make new bin slightly worse than a
        // good existing fit by anchoring against mean residual.
        if post_residual as f64 <= mean_residual * 0.5 {
            score += 10.0; // keep using existing bins with roomy residuals
        }
        // Perfect fit into an existing bin should always beat opening a new bin.
        if item_size == bin_capacity {
            score += 500.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean
        // (below-mean residual bins are "tighter", use them first).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
        // Slight preference to consolidate when many bins are open.
        score += 0.4 * open_bins_count as f64;
    }

    // Mild time modulation: late in the stream, avoid creating tiny fragments.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && post_residual > 0 && post_residual < 15 {
        score += 12.0 * (progress - 0.8) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Smooth coupling of residual tightness with stream progress:
    // later in the stream, tighter fits (small post residual) are rewarded more
    let tightness = 1.0 - x;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that can't fit typical future items (non-linear)
    let dead = if x > 0.0 && x < 0.1 { (0.1 - x) / 0.1 } else { 0.0 };
    score += 15.0 * dead * dead * (1.0 - progress);

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin bonus (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + progress);
    }

    // Mild preference for bins tighter than the mean residual
    score += 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize slightly so we prefer reusing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity divided into 10 classes of 10 units.
    let post_class = (post_residual / 10) as f64;
    score += post_class * 3.0;

    // Perfect fits (residual in {0}) are golden; tiny dead space (1..5) is penalized hard.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score += 25.0;
    } else if post_residual <= 9 {
        score += 12.0;
    }

    // Modulo-arithmetic dead-zone: residuals that can only be filled by items <= 9
    // (below the min item size) are dead. Items arrive in 1..=100 here.
    // A residual that no plausible future item class fills well is penalized.
    let dead_zone = post_residual > 0 && post_residual < 4;
    if dead_zone {
        score += 30.0;
    }

    // Harmonic complement: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            // Reward chains that land on nice harmonic boundaries (multiples of 10 / zero)
            if next_post == 0 {
                score -= 35.0;
            } else if next_post % 10 == 0 {
                score -= 15.0;
            } else if next_post < 5 {
                score += 10.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Integer-division threshold on bin_residual: bins with large residual are flexible.
    let big_residual = bin_residual / (bin_capacity / 2); // 0 or 1
    if big_residual == 1 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin if all open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and state.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 70.0;
        // Late in the stream, prefer packing into existing bins more strongly.
        new_bin_score += progress * 15.0;
        // If many bins are open and mean residual is large, opening a new bin is wasteful.
        if mean_residual > item_size as f64 {
            new_bin_score += 10.0;
        }
        // If no existing bin fits (fitting_bins_count == 0 among open bins),
        // opening is necessary: reduce the cost.
        if fitting_bins_count == 0 {
            new_bin_score -= 80.0;
        } else if fitting_bins_count == 1 {
            // The single fitting bin is a last chance; discourage new bin.
            new_bin_score += 25.0;
        }
        // Next item lookahead: if next item is huge and this item leaves a good
        // residual, opening a fresh bin may be smart.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 && post_residual >= next_item_size {
            new_bin_score -= 30.0;
        }
        score = new_bin_score;
    }

    // Mild coupling with mean residual: prefer bins tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 3.0 * post_residual as f64;
    } else if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Prefer bins whose residual was already tight (good packing history).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 15.0 * fill_ratio;

    // Last fitting bin: strong incentive to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate handling: only attractive when current bin would leave
    // bad dead space or no bin fits well.
    if bin_residual == bin_capacity {
        let would_waste = post_residual as f64;
        if would_waste <= 10 && would_waste > 0 {
            score += 120.0; // don't open a new bin for a tight fit elsewhere
        } else {
            score += 25.0 + 0.3 * mean_residual; // mild default penalty
        }
        if fitting_bins_count == 0 {
            score -= 150.0; // nothing fits: must open new bin
        }
    }

    // Lookahead: if next item fits the post-residual well, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 12.0; // dead space for the known next item
    }

    // Late in the stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better.
    let tight_fit = (post_residual as f64) / bin_capacity as f64;
    score += tight_fit * 10.0;

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well next item fills the leftover.
            let fill = (next_item_size as f64) / (post_residual as f64).max(1.0);
            score -= 40.0 * fill;
        } else {
            // Next item won't fit here: penalize large dead space.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Penalize bins far from mean residual (prefer balanced residual usage),
    // except reward bins with small residual (nearly full).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we only open a new bin when
    // existing fits are poor (high post_residual / dead space).
    if bin_residual == bin_capacity {
        score += 15.0;
        // If next item is large, opening a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 20.0;
        }
    }

    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here would be very poor.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        if fitting_bins_count == 0 || (crowding < 0.3 && poor_fit) {
            score -= 15.0;
        } else {
            score += 10.0 + 20.0 * (1.0 - crowding);
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (flexibility); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    // Nudge toward bins whose residual is close to the item (best-fit flavor).
    score += 0.1 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with a convex polynomial penalty on dead space.
    let mut score = pr as f64 * (1.0 + 0.9 * norm_pr * norm_pr);

    // Non-linear coupling of post-residual with stream progress:
    // early on, large residuals are tolerable; late, they become costly.
    score += 30.0 * norm_pr * norm_pr * progress * progress;

    // Reward tight fits (small post-residual) increasingly with progress.
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize bins far below mean residual (creates fragmented leftovers).
    score += 0.35 * (mean_residual - pr).abs().powf(1.5) / (cap.max(1.0));

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate (empty bin): penalize mildly so it's chosen only when
    // open bins would leave very bad residuals; the base post-residual term
    // (which is large for a fresh bin) naturally discourages it.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 0.5 * (open_bins_count as f64).sqrt();
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 12.0 * (1.0 - ((pr - ni) / cap)).powi(2);
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // Mild penalty for accumulating many open bins with poor utilization.
    score += 0.02 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residue modulo small capacity fractions
    let pr = post_residual as u32;
    let class_score = match pr {
        0 => -40.0,                     // perfect fit: reward heavily
        1..=9 => -25.0,                 // near-perfect: highly usable dead space
        10..=19 => -10.0,
        20..=39 => 5.0,
        40..=59 => 12.0,
        60..=79 => 20.0,
        _ => 28.0,                      // large leftover: less urgent to fill now
    };
    score += class_score;

    // Integer-division harmonic: post_residual / 10 classes
    let harmonic = (pr / 10) as f64;
    score += 0.8 * harmonic;

    // Modulo coupling with next item: if next item fits the post residual, reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 18.0;
        // finer: next item leaves a tiny residue again
        let next_post = pr - next_item_size;
        if next_post <= 10 { score -= 8.0; }
    } else if next_item_size > 0 {
        // next item cannot use leftover: penalize wasted space slightly
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer empty bin when open bins are bad fits
    if bin_residual == bin_capacity {
        // base penalty so we prefer existing bins, scaled by how many alternatives exist
        score += 15.0 + 2.0 * open_bins_count as f64;
        // late in stream, prefer consolidation into open bins more strongly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // if mean residual is large, opening new bins is wasteful
        score += 0.3 * mean_residual;
    }

    // Prefer bins tighter than the mean residual (better fit than average)
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Progress-scaled tightness pressure: as stream advances, demand tighter fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100)
    // are pure waste. Penalize hard, especially the "unusable gap" band.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size: severe penalty.
        score += 120.0;
    } else if post_residual <= 20 {
        // Small gap: only useful for tiny items; moderate penalty.
        score += 25.0;
    } else if post_residual < next_item_size && next_item_size > 0 {
        // Gap cannot host the lookahead item: mild penalty.
        score += 15.0;
    }

    // Reward tight fits: post_residual close to 0 relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Lookahead synergy: if next item exactly fits remaining space, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Room for lookahead: small reward.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * open_bins_count as f64 * (0.5 + progress);

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (it's a "junk" bin), slight penalty; if near mean, neutral.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: make it attractive only when current bin would
    // leave a bad gap; otherwise keep it slightly worse than a decent fit.
    if bin_residual == bin_capacity {
        if post_residual < 10 && post_residual > 0 {
            score -= 100.0; // opening fresh bin beats creating dead space
        } else {
            score += 30.0 + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize waste relative to the item itself: small items leaving big gaps.
    score += 0.35 * post_residual as f64 * (item_size as f64 / bin_capacity as f64);

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 18.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap.min(50.0);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the one with the least residual after placement.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, pack aggressively (fill whatever fits).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.4 * (1.0 - progress) * fit_ratio;
    score -= 12.0 * progress * (1.0 - fit_ratio);

    // Global state coupling: many open bins with high mean residual => prefer
    // consolidating into bins that are already partially used.
    if open_bins_count > 1 {
        let spread = (mean_residual - bin_residual as f64).abs();
        score += 0.08 * spread;
        score -= 2.0 * (open_bins_count as f64).ln().min(4.0) * (1.0 - fit_ratio);
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // everywhere (post_residual very small means perfect fit for empty bin).
    if bin_residual == bin_capacity {
        let base = 55.0
            + 0.5 * item_size as f64
            + 20.0 * (1.0 - progress);
        // If the item would leave a large hole in an existing bin, new bin is OK.
        let hole_bonus = if post_residual as f64 > 0.6 * bin_capacity as f64 { 30.0 } else { 0.0 };
        score += base + hole_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let t = progress;
    score += norm_pr * norm_pr * (1.0 + 3.0 * t) * 20.0;
    score -= norm_pr * (1.0 - t) * 15.0;
    // reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 30.0 * t);
    // lookahead: favor bins whose post-residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - t);
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + t);
    }
    // penalize deviating from mean residual (keeps bins balanced)
    score += ((pr - mean_residual) / cap).abs() * (5.0 + 10.0 * t);
    // discourage opening new bins early when many bins are open
    if bin_residual == bin_capacity {
        score += 6.0 + 25.0 * (1.0 - t) + open_bins_count as f64 * 0.5;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic classes of post_residual
    let post = post_residual as i64;
    if post == 0 {
        score -= 50.0; // perfect fit
    } else if post <= 10 {
        score -= 20.0; // near-perfect, dead space minimal
    } else if post % 20 == 0 {
        score -= 12.0; // harmonic class: divisible by 20 (fits medium items)
    } else if post % 10 == 0 {
        score -= 8.0;  // divisible by 10
    } else if post < 10 {
        score += 15.0; // unusable sliver below min item size
    }

    // Penalize residual classes that can't hold common item sizes (1..100 unknown, assume mid sizes)
    if post > 0 && post < 20 {
        score += 10.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is good if current item is large and would leave awkward residue,
        // or if no open bin is a tight fit.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // Prefer new bin when many open bins are heavily fragmented
        if mean_residual > (bin_capacity as f64) * 0.6 && open_bins_count > 2 {
            score -= 6.0;
        }
        // Discourage new bins early in the stream when a fit exists elsewhere
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward leaving post_residual that fits next item exactly or well
    if next_item_size > 0 {
        if post == next_item_size as i64 {
            score -= 18.0;
        } else if post > next_item_size as i64 {
            let rem = post - next_item_size as i64;
            if rem <= 10 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to leftover unusability
            score += 3.0;
        }
    }

    // Mild penalty for wasting a mostly-empty bin on a tiny item
    if (item_size as f64) < 0.25 * bin_capacity as f64 && bin_residual > bin_capacity / 2 && bin_residual < bin_capacity {
        score += 8.0;
    }

    // Fragmentation guard: penalize leaving residue in bins that are already small
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable
    // (min item size is 1, but tiny gaps waste capacity); penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward using a nearly-full bin (tight packing pressure).
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if post_residual is small but nonzero and next item can't use it.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 10.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, prefer filling existing.
    score += (open_bins_count as f64) * 0.5;

    // Mean residual coupling: if this bin's residual is far below mean, it's an outlier
    // worth filling; if above mean, mild penalty.
    let residual_f = bin_residual as f64;
    score += 0.3 * (residual_f - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    // Give it a moderate baseline so it loses against good fits but wins
    // when all open bins would create dead space.
    if bin_residual == bin_capacity {
        score = 35.0 + (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual to next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item chain fill
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // small slack after placing next item is good; large slack is dead space
            score -= (20.0 * (1.0 - slack / bin_capacity as f64)).max(-20.0);
            if slack < 10.0 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow into this bin; penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize leaving residuals that are likely unusable (below typical min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Prefer bins whose residual deviates from mean (consolidate space).
    score -= (mean_residual - post_residual as f64).abs() * 0.15;

    // Mild bias toward filling existing bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // Slight preference for opening fresh bins early in the stream is discouraged;
    // new-bin candidate (full residual) gets neutral treatment with small penalty.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to item size.
    if item_size > 0 {
        score -= (bin_capacity as f64 / item_size as f64) * (post_residual as f64).sqrt() * 0.8;
    }

    // Penalize large dead space that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill bonus
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // awkward dead zone
    }

    // Lookahead coupling: favor bins whose leftover fits the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).ln().max(0.0);
        } else {
            score += 5.0; // leftover won't serve next item
        }
    }

    // Last-chance bin before opening a new bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when existing bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let new_bin_cost = 100.0 + 40.0 * (1.0 - time_frac) + 10.0 * (open_bins_count as f64).ln();
        let benefit = (mean_residual - item_size as f64).max(0.0) * 2.5;
        score = new_bin_cost - benefit + 60.0 * crowding;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 10.0; // fresh bin keeps flexibility
        }
    }

    // Global state: many open bins with slack -> prefer consolidating into low-residual bins.
    let spread = (bin_residual as f64 - mean_residual).abs();
    score += spread * 0.15;

    // Mild preference for fuller bins over the stream horizon.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 12.0 * (1.0 + step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth interaction: as stream progresses, tighten residual preference
    score *= 1.0 + 0.6 * progress * (1.0 - norm_pr);

    // Penalize dead space that no plausible future item can use
    let usable = (next_item_size as f64 / cap).max(0.01);
    let waste = if pr > 0.0 && (pr as u32) < next_item_size && next_item_size > 0 {
        (1.0 - pr / (next_item_size as f64 + 1.0)) * 20.0
    } else {
        0.0
    };
    score += waste;

    // Reward near-perfect fits with smooth quadratic bonus
    score -= 15.0 * (1.0 - norm_pr).powi(2) * fit;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: smooth penalty that relaxes early / tightens late
    let is_new = bin_residual == bin_capacity && (bin_residual as f64 - item_size as f64) >= pr;
    if is_new {
        score += 10.0 + 30.0 * progress - 0.15 * mean_residual * (1.0 - progress);
    }

    // Mild preference for spreading across bins when many are open
    score += 0.02 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: post_residual mod 10 buckets
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty: leftovers in awkward classes (1,2,3,7,8,9) are hard to fill
    let awkward: u32 = match class { 1 | 2 | 3 | 7 | 8 | 9 => 1, _ => 0 };
    score += (awkward as f64) * 6.0;

    // Perfect fits are golden: post_residual 0 or exactly a small harmonic cell
    if pr == 0 {
        score -= 30.0;
    } else if pr <= 5 {
        score -= 12.0;
    }

    // Integer-division threshold: residual in [10,20) is a "small cell" worth keeping
    if pr / 10 == 1 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly
    if next_item_size > 0 && next_item_size <= pr {
        score -= 8.0 + (pr - next_item_size) as f64 * 0.15;
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot use the leftover: penalize proportional to waste
        score += (next_item_size - pr) as f64 * 0.1;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer fuller bins (relative fill fraction of the bin)
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill * 5.0;

    // Prefer bins whose residual deviates favorably from the mean (below mean residual = tighter bin)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 25.0 - (item_size as f64 / cap) * 10.0;
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item * 3 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward perfect / near-perfect fits (waste-free placement).
    if post_residual == 0 {
        score -= 40.0;
    } else if (post_residual as f64) <= item_size as f64 * 0.1 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot use the leftover -> dead space likely
            score += (post_residual as f64) * 0.3;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good; scale penalty with number of open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + 0.5 * progress);

    // Mean residual context: if this bin's residual is far below the mean
    // (already tight), it's a good target; if far above, less urgent.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.2;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a new bin attractive only when the
    // current fit is bad (large post residual or dead space).
    if bin_residual == bin_capacity {
        // neutral-ish baseline; the dead-space penalties above on real bins
        // decide whether a new bin wins.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward post_residual exactly matching next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Exact match for the next item is excellent.
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize leaving a residual too small for next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0;
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin, more when many bins fit the item.
    if bin_residual == bin_capacity {
        score += 90.0 + 15.0 * fitting_bins_count as f64;
        // If next item could combine with this one, opening a fresh bin is less bad.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 40.0;
        }
    }

    // Mild penalty for wasting a large-capacity bin on a tiny item.
    if item_size < 20 && bin_residual > 80 {
        score += 15.0;
    }

    // Late in the stream: consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // mild reward proportional to how well next item uses leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // next item cannot use leftover: penalize large dead space more
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Scarcity effect: fewer fitting bins -> more pressure to use this one.
    if fitting_bins_count >= 2 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global residual balance: prefer bins whose residual deviates from mean
    // (consolidate space into few bins early, spread later).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += if t < 0.5 { 0.1 * dev } else { -0.05 * dev };

    // Late in the stream, be conservative with new bins: penalize empty-bin choice.
    if bin_residual == bin_capacity {
        let new_bin_cost = 25.0 * (1.0 - t) + 10.0;
        // But if the item is large and mean residual is small, new bin may be fine.
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_global_fit = mean_residual < item_size as f64;
        if large_item && poor_global_fit {
            score -= new_bin_cost * 0.5;
        } else {
            score += new_bin_cost;
        }
    }

    // Reward filling large chunks of the bin.
    score -= 0.3 * item_size as f64;

    // Mild penalty for leaving residual in the awkward 1..10 dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Smooth base: reward tight fits via non-linear decay of post_residual
    let mut score = post * (1.0 + 0.5 * fit_ratio * fit_ratio);

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly (quadratic growth)
    let dead_penalty = (post / cap).powi(2) * (0.5 + 3.0 * progress * progress);
    score += dead_penalty * cap;

    // Last-chance bonus: strongly favor the only fitting bin (smooth, scaled)
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead coupling: reward bins whose post_residual could host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 3.0 * (nxt / cap) * (1.0 - (post - nxt) / cap);
        } else {
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Mild preference for consolidating into fewer bins when residuals are high
    let mean_gap = (mean_residual - post) / cap;
    score += 1.5 * mean_gap * mean_gap * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize opening a bin unless current fits are poor
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        score += 12.0 + 10.0 * progress - 0.5 * openness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into octiles.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Class 0: near-perfect fill (post_residual <= 5) -> strong reward.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else {
        // Penalize large dead space quadratically.
        score += frac * frac * 30.0;
    }

    // Integer-division thresholds on post_residual: does the leftover fit a
    // "harmonic" small class (multiples of 10)? Reward leftovers in [1,10].
    if post_residual >= 1 && post_residual <= 10 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is an ideal chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves a new leftover; mild reward scaled by
            // how much of the leftover it consumes.
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * use_ratio;
        } else {
            // Next item cannot use this bin's leftover: penalize big leftovers
            // that will strand capacity.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open
    // bins; penalize opening a fresh bin mildly so tight fits win.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.05 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Progress coupling: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 10.0 * progress;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced packing), slightly penalize outliers.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=10) are nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 && post_residual > 0 {
        score += 15.0;
    }

    // Reward exact and near-exact fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Prefer bins whose residual was already tight relative to the mean.
    score += 0.5 * (mean_residual - bin_residual as f64).abs();

    // Pressure from number of open bins: discourage spreading across many bins
    // when a good fit exists, but allow opening a new bin when the only
    // alternative creates dead space.
    if bin_residual != bin_capacity {
        // Existing bin: mild reward to keep bins consolidated.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // New-bin candidate: only attractive if it avoids a bad fit.
        // Base penalty grows with number of open bins.
        score += 8.0 + 1.5 * open_bins_count as f64;
        if post_residual >= next_item_size as u32 && next_item_size > 0 {
            // New bin can also host the lookahead item: strong reward.
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 1000.0; // forced open
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if this placement leaves room for the next item, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 10.0;
    }
    // If next item cannot fit anywhere else and this bin could host both, reward more.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack left over is still useful for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.3 * slack;
        } else {
            // Dead space for the lookahead item: penalize proportionally to waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste;
        }
    } else {
        // Last item: prefer tightest fit strongly.
        score -= 200.0;
    }

    // Relative tightness vs mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But allow opening a new bin when the current item would leave an
        // awkward fragment in an existing bin and the next item is large.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 40.0 + 0.5 * post_residual as f64;
        }
    }

    // Mild preference for consolidating into fewer bins early in the stream.
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            let waste = post_residual as f64 / next_item_size.max(1) as f64;
            score += 12.0 * waste;
        } else if post_residual >= next_item_size {
            // reward bins that can also host the lookahead item
            score -= 6.0 * (post_residual as f64 / (post_residual + next_item_size as f64));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to prefer consolidation into fewest-waste bins
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Perfect fill reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize very small leftover slivers (<10) that are likely dead space
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // existing fits are poor (post_residual small relative to capacity)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // open a new bin when existing residuals are low and stream is advanced
        score = 55.0 - 20.0 * pressure - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score += 8.0; // avoid opening bins when big item follows? keep neutral
        }
    }

    // Global state coupling: many open bins with high mean residual -> favor filling them
    score -= 0.5 * mean_residual / (open_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: quadratic dead-space penalty, mildly damped late in the stream
    // (late in the stream, leftover space matters less since fewer items remain).
    let mut score = pr * (1.0 + pr / cap) * (1.0 - 0.35 * progress);

    // Reward tight fits: subtract proportional to how much of the bin the item fills.
    score -= (item_size as f64 / cap) * 12.0;

    // Penalize residuals that are too small to be useful but nonzero:
    // smooth trough around residuals usable by typical items.
    let nr = next_item_size as f64;
    if nr > 0.0 {
        let gap = (pr - nr).abs();
        // if post residual can host the next item, reward; else penalize smoothly
        if pr >= nr {
            score -= 6.0 * (nr / cap);
        } else {
            score += 4.0 * (1.0 - pr / cap) * (nr / cap);
        }
        let _ = gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (new bin has post_residual = cap - item, large).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 8.0 * (1.0 - progress);
    }

    // Slight penalty for spreading across too many open bins relative to mean residual:
    // prefer bins that are already relatively full.
    let fullness = 1.0 - pr / cap;
    score += (mean_residual - pr) * 0.05;
    score -= fullness * 3.0;

    // Smooth stream-progress coupling: early on, encourage consolidation;
    // late, encourage packing into any fitting bin.
    score *= 1.0 + 0.1 * (1.0 - progress) * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes mod small divisors
    let pr = post_residual;
    // Residuals divisible by common item sizes (10/20/25/50) are "reusable" classes
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 || pr % 50 == 0 { score -= 5.0; }
    } else {
        // Perfect fit: heavily reward
        score -= 40.0;
    }

    // Penalize tiny unusable dead space (post_residual < 10 cannot hold any item)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Next-item lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            // fraction of post_residual consumed by next item
            let frac = next_item_size as f64 / pr as f64;
            score -= 10.0 * frac;
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when current
    // placements would waste a lot (post_residual small but nonzero) or bins are many
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // opening new bins is cheaper early, costlier late
        score = 8.0 + 20.0 * progress + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter packing)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Integer-division threshold: penalize when post_residual falls in awkward band
    if pr >= 10 && pr / 10 == 1 { // 10..19 band: hard to reuse
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1,10] is nearly unusable
    // for typical items -> heavy penalty. Larger usable gaps are fine.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + 6.0 * (11 - post_residual as i32) as f64;
    } else if post_residual > 10 && post_residual <= 20 {
        // moderately risky gap
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 25.0 * tightness;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Pressure from number of open bins: when many bins are open, prefer
    // filling existing ones rather than opening more.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost + open-bin pressure + slight
        // lookahead hedge if next item could use current gaps.
        score += 30.0 + open_pressure;
        if next_item_size > 0 && next_item_size <= mean_residual {
            score += 10.0;
        }
    } else {
        // Existing bin: mild discount when open bins are numerous.
        score -= open_pressure * 0.5;
    }

    // Lookahead: if this placement leaves a residual that exactly fits the
    // next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 12.0;
    }

    // Early in the stream, opening bins is cheaper; late in the stream,
    // consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (progress - 0.5) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: bins far below mean residual are less attractive
    // (their space is better saved for larger future items).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 200.0; // exact 2-step chain
        }
    } else if next_item_size > 0 {
        // dead space: next item cannot use this bin's remainder
        score += 20.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins early in the stream
    if bin_residual == bin_capacity {
        score += 80.0 + 50.0 * (open_bins_count as f64).ln().max(0.0);
        // but if item is large and next item is large too, new bin is fine
        if item_size >= 60 && next_item_size >= 60 {
            score -= 100.0;
        }
    }

    // Slight progression scaling to adapt behavior over stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 60.0;

    // Perfect or near-perfect fill gets strong bonus
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Penalize new-bin opening unless current bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 45.0;
        // If this bin is the last chance, opening a new bin is less bad
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Late in the stream, avoid opening new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 70.0;
        } else {
            score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual is dead space for the next item
        score += 15.0;
    }

    // Prefer bins with residuals below mean (consolidate small leftovers)
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Many open bins: prefer filling existing ones harder
    score += open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin bonus: if this is the only fitting bin, use it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post residual), with quadratic sharpening.
    let mut score = post + 0.9 * (post * post) / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight packing matters more; early, keep flexibility.
    let flex = (post / cap) * (1.0 - post / cap); // peaks at post = cap/2
    score += 14.0 * flex * (0.35 + 0.65 * progress);

    // Reward filling a bin nearly completely (smooth saturation).
    let fill = item / res.max(1.0);
    score -= 10.0 * fill * fill;

    // Lookahead: penalize if post_residual can't hold the next item but could
    // have if we packed differently; reward if it exactly accommodates lookahead.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 3.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // New-bin candidate: keep it attractive only when no open bin fits well.
    let is_new_bin = (bin_residual as u32 == bin_capacity);
    if is_new_bin {
        // Smooth penalty that grows with mean residual of open bins and progress.
        score += 6.0 + 0.05 * mean_residual + 10.0 * progress;
        if fitting_bins_count >= 1 {
            score += 5.0 * (fitting_bins_count as f64).sqrt();
        }
    }

    // Mild pressure to consolidate: fewer open bins -> favor existing bins.
    score += 0.02 * (open_bins_count as f64) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Harmonic class logic on post_residual ---
    // Dead space in "awkward" classes (not multiples of 10) is harder to fill
    // later since typical granularity is ~10; penalize non-aligned residuals.
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 0.8;

    // Integer-division threshold classes: residuals in [1,10] are near-dead,
    // [11,30] moderately usable, larger residuals are flexible.
    let class = post_residual / 10;
    match class {
        0 => score += 12.0,               // nearly dead space
        1 => score += 4.0,
        2 => score += 1.0,
        _ => {}                            // flexible space, no penalty
    }

    // --- Tight-fit reward (existing bins only) ---
    if !is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 35.0 * fill_ratio * fill_ratio * fill_ratio;
    }

    // --- Lookahead: reward bins whose leftover can host the next item ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 22.0;
        // extra reward if leftover after the hypothetical next placement is tiny
        let post2 = post_residual - next_item_size;
        if post2 <= 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // leftover useless for next item: mild penalty scaled by next size
        score += (next_item_size as f64) * 0.15;
    }

    // --- Last-chance bonus: sole fitting bin should be strongly preferred
    // over opening a new bin ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // --- New-bin candidate scoring ---
    if is_new_bin {
        // Base: opening a new bin is expensive; make it lose against any
        // reasonable existing fit.
        score = bin_capacity as f64 * 1.05;
        // But allow opening when existing fits are all poor: if the new bin's
        // own post_residual is large (small item), it's actually attractive
        // early in the stream when many items remain to fill it.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let early = 1.0 - progress;
        score -= 45.0 * (1.0 - item_frac) * early;
        // Discard new-bin opening late in the stream.
        score += 40.0 * progress;
        // If only one bin fits, opening new is wasteful.
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
        // If next item is large, a fresh bin reserves space for it nicely.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // --- Mild pressure toward consolidating into fewer bins ---
    score += open_bins_count as f64 * 0.3;

    // --- Small tie-breaker toward bins below mean residual (fill emptier bins) ---
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A post_residual that is nonzero but below the minimum item size (1..100 stream,
    // treat gaps < 10 as near-unusable) is wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Medium-small gaps: moderate penalty scaled by gap size (smaller gap = worse).
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits: post_residual near zero is excellent (perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: prefer filling existing bins when many bins are open,
    // but allow opening new bins early in the stream or when few bins exist.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's already
    // tight; favor it. If far above mean, it's a loose bin; slight penalty.
    let residual_diff = bin_residual as f64 - mean_residual;
    score += residual_diff * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    // (chains items nicely). If next item is large and this bin would be left
    // with a medium gap, slight penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < 30 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer a new bin when current fit is terrible (large dead space) and
    // the item is large enough to leave a useful new-bin structure.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; overcome only if alternatives are bad.
        score += 45.0 + open_bins_count as f64 * -0.5;
        // Large items into fresh bins are fine (they define the bin's structure).
        if item_size >= 50 {
            score -= 20.0;
        }
        // If no other bin fits well, opening new is acceptable.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly placement: subtract a bonus scaled by how snugly the
            // next item will fit into the resulting residual.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 + 0.5 * slack.min(30.0);
            // Extra reward if next item fits almost exactly (perfect chain).
            if slack <= 5.0 {
                score -= 25.0;
            }
        } else {
            // Dead space for the next item: penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.6 * shortfall.min(50.0);
        }
    }

    // Prefer tight fits relative to current residual (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Penalize opening a new bin when other bins can fit the item, unless the
    // existing fit is terrible (large post_residual) or this is the last chance.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        // New-bin candidate: compare against mean residual of open bins.
        let mean_fit_gap = (mean_residual - item_size as f64).max(0.0);
        if mean_fit_gap > 15.0 {
            // Existing bins all leave lots of room; opening a new bin is wasteful.
            score += 60.0;
        } else {
            score += 15.0;
        }
    }

    // Last-chance bin bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Slight preference to spread load when many bins are open and mean residual is high.
    if open_bins_count > 3 && mean_residual > 50.0 && bin_residual == bin_capacity {
        score -= 5.0;
    }

    // Mild stream-progression pressure: later in the stream, favor consolidating
    // into existing bins (penalize new bins slightly more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but penalize very small dead space less than medium dead space.
    let pr = post_residual as f64;
    score += 0.5 * (pr / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else (large post_residual pressure) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items early, or when few fitting bins exist.
        let new_bin_bonus = 60.0 * tightness * (0.5 + 0.5 * (1.0 - progress))
            - 15.0 * (fitting_bins_count as f64);
        score = pr + 70.0 - new_bin_bonus;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global state: spread usage across bins when many are open with slack.
    let mean_r = mean_residual;
    if bin_residual as f64 > mean_r + 20.0 {
        score += 6.0; // penalize dumping into unusually empty bins when better options exist
    } else if (bin_residual as f64 - mean_r).abs() < 10.0 {
        score -= 3.0; // reward balanced residual usage
    }

    // Mild time-horizon adaptation: early stream, conserve space; late stream, just fit it.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Tie-break: prefer bins with more residual among equals (keeps small bins for small items).
    score -= 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - 2.0 * progress);
    score += 40.0 * poly;

    // Penalize large dead space more as stream progresses
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly mid-stream
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let slack = (pr - ns) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            score += 6.0 * ((ns - pr) / cap);
        }
    }

    // Deviation from mean residual: prefer bins near the mean
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild pressure on many open bins to consolidate
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Exact fit: perfect packing, strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty: tiny unusable residuals (harmonic class 1..5) are waste.
    if post_residual > 0 && post_residual < 6 {
        score += 45.0;
    }

    // Harmonic classes on post_residual (capacity = 100, decimal-friendly classes):
    // multiples of 10 are the most reusable residual classes -> reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else if post_residual % 10 > 5 {
        // residual in (5,10) band: awkward class, mild penalty
        score += 3.0;
    }

    // Integer-division threshold: residual >= half capacity keeps bin versatile.
    if post_residual >= bin_capacity / 2 {
        score -= 6.0;
    }

    // Lookahead (k=2): reward bins whose residual can host the next item,
    // especially in clean harmonic classes.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.05 * next_item_size as f64;
            if post_residual % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // this bin becomes dead for the next item
            score += 7.0;
            // but if next item nearly fits, soften (it may pair with later items)
            if post_residual > 0 && next_item_size - post_residual <= 5 {
                score -= 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it avoids
    // opening a new bin -> strong reward (but not for the empty-bin candidate).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Baseline: expensive; opening bins should be a deliberate choice.
        score = cap * 1.6;
        // Large items justify fresh bins (they leave small residuals elsewhere).
        if item_size >= 50 {
            score -= 25.0;
        } else if item_size >= 30 {
            score -= 10.0;
        }
        // No open bin can fit this item: new bin is mandatory.
        if fitting_bins_count == 0 {
            score -= cap * 2.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Global context couplings:
    // Bins with residual well below the mean are "tight" -> mildly favored.
    score += 0.04 * (mean_residual - pr);
    // Many open bins: slight pressure to fill existing ones rather than spread.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later.
    // A residual below the minimum item size (1..100 stream => treat < 12 as dead)
    // is pure waste; penalize it heavily, scaled by how "dead" it is.
    if post_residual < 12 {
        score += 60.0 * (1.0 - post_residual as f64 / 12.0);
    } else if post_residual < 25 {
        // Marginal zone: only useful for very small items.
        score += 15.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_fit = (post_residual - next_item_size) as f64;
        if nxt_fit < 12.0 {
            score -= 20.0; // next item will nearly perfectly fill the gap
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the residual we leave behind: penalize.
        score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: when many bins are open, avoid spreading; prefer
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 8.0 + 2.0 * pressure;
    } else {
        score -= 2.0 * pressure.min(10.0);
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // mildly, to avoid extreme outlier gaps.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    }

    // 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next == pr {
            score -= 500.0;
        } else if next < pr {
            // next item fits here: penalize wasted slack relative to next item
            score -= 0.8 * (next / (pr + 1.0));
            score += 0.3 * (pr - next);
        } else {
            // next item won't fit here: penalize small post_residual (dead space)
            score += 0.5 * (next - pr);
        }
        // coupling with mean residual: prefer bins whose post residual tracks mean
        score += 0.4 * (pr - mean_residual).abs();
    }

    // Last chance: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to residual
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 120.0 * (1.0 - tightness);
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.5 {
            score -= 60.0; // large next item: fresh bin may be fine
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 * progress;
    }

    // Mild penalty for leaving awkward residuals (11..=19 typical dead zone)
    let pr = post_residual;
    if pr >= 11 && pr <= 19 {
        score += 40.0;
    }

    // Slight preference for fuller bins among open ones
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that cannot fit typical items: if post_residual
    // is small but nonzero, it is likely unusable — extra penalty.
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powf(0.5);
        score += dead * 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Prefer bins with residual below mean (denser bins) — keep sparse bins flexible.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Time horizon: late in the stream, be more conservative (favor existing bins
    // over opening new ones, since leftover capacity is less valuable).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced late in the stream only if
        // current bin fit is poor; otherwise penalize opening new bins.
        score += 10.0 + (1.0 - progress) * 20.0;
        // Opening a new bin is more attractive when many bins are already open
        // and mean residual is high (existing bins are fragmented).
        score += (open_bins_count as f64).ln() * 2.0 - mean_residual * 0.1;
    }

    // Mild preference for filling larger-residual bins early (keep tight bins
    // available for small items).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear penalty on post-residual: cubic coupling with capacity
    let mut score = pr
        + (pr * pr * pr) / (cap * cap)
        + 0.35 * (pr / cap) * (pr / cap) * pr;

    // Stream-progress coupling: waste matters more as stream advances
    score += 0.5 * progress * (pr / cap) * cap * 0.1;

    // Reward tight fits (small post residual) via smooth negative term
    let tight = 1.0 - pr / cap;
    score -= 3.0 * tight * tight * tight;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead: penalize leaving residual just below next item size (smooth)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let gap_norm = gap / cap;
        score += 2.0 * gap_norm * (1.0 - gap_norm);
        // Reward exact match for next item
        score -= 4.0 * (1.0 - gap_norm) * (1.0 - gap_norm) * (1.0 - (pr - next_item_size as f64).abs() / (next_item_size as f64 + 1.0));
    }

    // New-bin candidate: prefer keeping it closed unless open bins are very fragmented
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (mean_residual / cap);
        score += 1.5 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Favor bins whose residual is below mean (packing denser bins first)
        score += 0.3 * ((bin_residual as f64 - mean_residual) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 bins capture "small leftover" structure.
    let post_class = (post_residual % 10) as f64;
    score += 0.35 * post_class;

    // Dead-space penalty: residuals too small for typical items (<=10) are nearly worthless.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Fractional fill ratio coupling: reward tight fits via integer-division threshold.
    let fill_ratio = (bin_residual - post_residual) as f64 / cap;
    if fill_ratio > 0.9 {
        score -= 25.0;
    } else if fill_ratio > 0.7 {
        score -= 10.0;
    }

    // Lookahead harmony: if next item divides evenly into post_residual (harmonic class match),
    // this bin is extra valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack % 10 == 0 {
            score -= 12.0;
        }
        if slack < 10 {
            score += 8.0; // leaves near-dead space for the item after next
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post residual cannot host next item; mildly penalize if it is stranded small space
        if post_residual < next_item_size / 2 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should lose unless current bins are crowded
    // or the fit here is bad.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * mean_residual - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 15.0; // big next item: keep fresh bins available
        }
    }

    // Stream progression: late in the stream, consolidate harder (avoid opening bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let obc = open_bins_count as f64;

    // --- Perfect fit: overwhelmingly reward filling a bin exactly ---
    if post_residual == 0 {
        score -= 1000.0;
    }

    // --- Strict dead-space avoidance: small unusable gaps are poison ---
    // Gaps of 1..9 units are unlikely to host future items (sizes 1..100, but
    // tiny leftovers fragment capacity). Penalize the *smallest* leftovers hardest.
    if post_residual > 0 && post_residual < 10 {
        let dead = (10 - post_residual) as f64;
        // Dead space hurts more when many bins are already open (fragmentation).
        score += dead * 6.0 * (1.0 + 0.15 * obc);
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // This placement sets up a perfect fit for the next item.
            score -= 300.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // The gap cannot host the next item: likely dead space, penalize
            // more strongly early in the stream when remaining demand is high.
            score += 15.0 + 25.0 * (1.0 - progress);
        }
    }

    // --- Last-chance pressure: only one open bin fits; avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // --- Open-bins pressure: penalize leaving slack proportionally to fleet size ---
    // Consolidate when many bins are open; tolerate slack when the fleet is small.
    score += 2.0 * obc * (post_residual as f64 / bin_capacity as f64);

    // --- Relative-fit penalty: worse than the average open bin's residual? ---
    let excess = post_residual as f64 - mean_residual;
    if excess > 0.0 {
        score += 0.5 * excess;
    }

    // --- New-bin candidate tie-breaker: mildly prefer reusing an open bin ---
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards: excellent chaining.
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 - slack * 2.0;
            // Bonus when the chain nearly fills the bin completely.
            if post_residual == next_item_size {
                score -= 400.0;
            }
        } else {
            // Post-residual is dead space for the next item: penalize proportionally,
            // but less harshly when the leftover is small.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 3.0;
        }
        // If the next item is large, prefer conserving roomy bins for it.
        if next_item_size >= 50 && post_residual < next_item_size && post_residual > 0 {
            score += 50.0;
        }
    } else {
        // Last item: just minimize waste.
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: prefer bins that are tighter than average
    // (concentrate fill), but avoid extreme fragmentation.
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 1.5;
    } else {
        score += (resid_f - mean_residual) * 1.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless the
    // item is large and a fresh bin gives a clean layout.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count > 0 {
            score += 120.0 - 80.0 * progress;
            // A new bin is attractive for very large items (clean packing).
            if item_size >= 60 {
                score -= 100.0;
            }
        } else {
            score -= 500.0; // must open the first bin
        }
        // Fresh-bin alignment with next item: keep if next item fits with room.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer existing bins.
    score += open_bins_count as f64 * 0.5;

    // Slight preference for bins with larger residual when item is small
    // (keeps small items from wasting big-bin space is handled above;
    //  here we gently prefer filling emptier bins to close them out).
    if item_size <= 30 {
        score -= (bin_capacity - bin_residual) as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that no plausible future item can use
        let t = step_index as f64 / (total_items.max(1) as f64);
        let dead_penalty = (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;
        score += dead_penalty;

        // Lookahead: reward bins whose post-residual can host the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
            } else {
                score += 10.0;
            }
        }

        // Last-chance bin: strongly favor using it before opening a new one
        if fitting_bins_count == 1 && bin_residual >= item_size {
            score -= 60.0;
        }

        // Prefer bins tighter than the average residual (best-fit flavor)
        let res_f = bin_residual as f64;
        if res_f < mean_residual {
            score -= 5.0 * (mean_residual - res_f) / bin_capacity as f64;
        } else {
            score += 3.0 * (res_f - mean_residual) / bin_capacity as f64;
        }

        // Early in the stream, be willing to open new bins for large items;
        // late in the stream, pack tightly into existing bins.
        let openness = 1.0 - t;
        if bin_residual == bin_capacity {
            // New-bin candidate: only attractive when item is large or many bins fit poorly
            let large_item_bonus = (item_size as f64 / bin_capacity as f64).powi(2) * 45.0;
            score -= openness * large_item_bonus;
            score += (1.0 - openness) * 20.0;
            if fitting_bins_count > 2 {
                score += 15.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post_residual, with a smooth non-linear penalty on dead space
    let mut score = pr + (pr / cap).powi(3) * 40.0;

    // Progress coupling: later in the stream, tighten tolerance for wasted space
    score += progress * (pr * pr / cap) * 0.5;

    // Interaction: post_residual vs next item fit (smooth reward when next item fits)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0);
        score += 0.15 * gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for very full open-bin population (encourage consolidation)
    score += (open_bins_count as f64).ln() * 2.0;

    // Deviation from mean residual: prefer bins near average fill state
    score += ((pr - mean_residual) / cap).powi(2) * 20.0;

    // Prefer tighter fits: smooth coupling with item size
    score -= (item_size as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that pair well with common item sizes
    let r = post_residual;
    let class = r / 10; // integer division thresholds

    // Reward small usable residuals in a graded (harmonic) way
    score -= match class {
        0 => 40.0,                       // r < 10: near-perfect fill
        1 => 30.0,                       // 10..19: fits smallest items
        2 => 22.0,
        3 => 15.0,
        4 => 9.0,
        5 => 4.0,
        _ => 0.0,
    };

    // Modulo logic: residuals divisible by 10 pair cleanly with 10-multiple items
    if r % 10 == 0 && r > 0 {
        score -= 8.0;
    }
    // Odd residuals below 10 are dead space (min item is 1 per interface note)
    if r > 0 && r < 10 && r % 2 == 1 {
        score += 6.0;
    }

    // Lookahead coupling: does post_residual fit the next item exactly / well?
    if next_item_size > 0 {
        if next_item_size <= r {
            let slack = r - next_item_size;
            score -= 12.0 - (slack as f64).min(12.0); // exact future fit strongly rewarded
            if slack == 0 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; residual likely wasted
            score += (next_item_size - r).min(20) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving large residual when many bins are open (fragmentation risk)
    if r > 50 {
        score += (r as f64 - 50.0) * 0.3;
    }

    // New-bin candidate: only attractive when open bins are mostly full or none fit well
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score = 60.0 + pressure * 40.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0; // big next item: fresh bin useful
        }
    }

    // Stream progression: late in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: post_residual too small to be useful for future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual that is still usable)
    if post_residual >= 10 && post_residual <= 30 {
        score -= 12.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    score += open_bins_count as f64 * 0.8;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item cannot fit post_residual but post_residual is small, mild penalty
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // New bin candidate: make it moderately attractive only when open bins are many or fit is poor
    if bin_residual == bin_capacity {
        score -= 5.0;
        if open_bins_count > 4 {
            score -= 6.0;
        }
        if post_residual < item_size as f64 / 2.0 {
            score += 0.0; // neutral placeholder, new bin residual is full capacity anyway
        }
    } else {
        // Slight preference for bins whose residual is close to item size (efficient use)
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += gap * 0.15;
    }

    // Mean residual coupling: if mean residual is high, encourage consolidation into existing bins
    if mean_residual > item_size as f64 * 1.5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after that
            let after_next = post_residual - next_item_size;
            score -= 100.0 - after_next as f64 * 0.5;
        } else {
            // next item won't fit: penalize dead space relative to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.2;
    } else {
        score -= (mean_residual - pr) * 0.1;
    }

    // Last-chance bin bonus: if only this bin fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins could take the item well
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of a fresh bin
        score += 50.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 30.0; // keep fresh bins for larger upcoming items
        }
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative: new bin is fine
        }
    }

    // Small waste is bad: nonlinear penalty on tiny residuals (dead space)
    if pr > 0 && pr < 10 {
        score += (10.0 - pr) * 5.0;
    }

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to what was available,
    // the better the packing efficiency.
    if bin_residual > 0 {
        let tightness = 1.0 - post_residual as f64 / bin_residual as f64;
        score -= 12.0 * tightness;
    }

    // Last-chance bonus: if this is the only open bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling (k=2): if the next item can still fit in the leftover space,
    // this placement is extra valuable; if not, penalize proportional dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            score -= 8.0;
        } else {
            score += 6.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: it naturally has a large post_residual.
    // Give it a mild handicap so existing bins with decent fits win, but
    // relax the handicap late in the stream or when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let openness = (open_bins_count as f64 / 20.0).min(1.0);
        score += 3.0 * (1.0 - 0.5 * progress) * (1.0 - 0.5 * openness);
        // If the item is large, a fresh bin preserves a large usable residual:
        // slight reward so big items don't fragment nearly-full bins.
        score -= 0.05 * item_size as f64;
    }

    // Global state: when mean residual across open bins is small, bins are
    // nearly saturated; slightly prefer consolidating into existing space.
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap; // in [0,1]
    let poly = norm_post * norm_post * (1.0 - progress)
             + norm_post * progress * (1.0 - norm_post);
    score += 12.0 * poly;

    // Reward tight fits, stronger later in the stream
    score -= item * (0.35 + 0.4 * progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            score += (nxt - post) * (0.5 + 0.5 * progress);
        } else {
            score -= 2.0 * (1.0 - (post - nxt) / cap);
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
    }

    // Mild pressure toward consolidating with mean residual
    score -= 0.15 * (mean_residual - post);

    // New empty bin candidate: discourage unless residuals are poor
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * (1.0 - progress) * (1.0 - norm_post);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base: strong penalty so open bins are preferred by default.
        let mut score = cap * 1.5;
        // No open bin fits: must open a new bin.
        if fitting_bins_count == 0 {
            score = 0.0;
        } else {
            // Large item: opening a fresh bin preserves large residuals elsewhere.
            if item_size as f64 > 0.7 * cap {
                score = cap - pr + 10.0;
            }
            // If the lookahead item fits snugly in the fresh post-residual,
            // opening a new bin sets up a tight pairing.
            if next_item_size > 0 && (next_item_size as f64) <= pr && pr >= 0.3 * cap {
                score -= 25.0;
            }
            // Late in the stream, avoid proliferating bins with slack.
            if progress > 0.8 && pr < 0.2 * cap {
                score += 15.0;
            }
        }
        return score;
    }

    // ---- Existing bin scoring (lower = better) ----
    let mut score = pr;

    // Harmonic classes on post_residual:
    if post_residual == 0 {
        score -= 30.0; // perfect closure
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect fill, dead space negligible
    } else {
        // Modulo-10 classes: multiples of 10 are "clean" residual targets
        // for common item sizes; reward them slightly.
        let class = post_residual % 10;
        if class == 0 {
            score -= 6.0;
        } else if class <= 3 {
            score -= 2.0;
        } else if class >= 8 {
            score += 2.0; // awkward sliver class
        }
        // Integer-division threshold: residual in upper quartile = wasted space
        if post_residual > bin_capacity / 2 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead coupling (k=2): reward bins whose post-residual admits next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 5.0 * (1.0 - (pr - n) / cap); // tight two-item pairing
        } else {
            score += 3.0; // next item won't fit here; slight penalty
        }
    }

    // Prefer bins tighter than the fleet average (mild pull toward mean_residual).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is nearly worthless
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // only fits the smallest items
    }

    // Perfect fit bonus: strongly reward leaving nothing behind.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving residual that can exactly host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 18.0; // exact lookahead fit
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // residual can't host the next item: mild dead-space penalty
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let spread = open_bins_count as f64;
    score += spread * 1.5;

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling fuller bins (tighter residual before placement).
    score += (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // Early in the stream, be more willing to open bins (cheap now, useful later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * -5.0;

    // Slightly favor bins whose residual is near the mean (keeps bin profiles uniform).
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically (unusable gaps are costly).
    score += 0.02 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Two-step lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Perfect 2-item fill (post_residual == next_item_size) is ideal.
            score -= 60.0 * (1.0 - slack as f64 / bin_capacity as f64);
            // Extra reward for near-perfect match.
            if slack <= 5 {
                score -= 25.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to wasted lookahead potential.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
            // If next item would have fit perfectly before placement, this placement is bad.
            if bin_residual >= next_item_size && post_residual < next_item_size {
                score += 20.0;
            }
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates from mean
    // when placing tightens the distribution (avoid fragmenting many similar bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer filling fuller bins first (best-fit flavor) as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Mild penalty for opening a new bin when open bins exist and fit well.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But if next item is large and current item is small, new bin may be good.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Penalize leaving dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer filling bins with large residuals when many bins are open (reduce fragmentation).
    if open_bins_count > 4 {
        let spread = bin_residual as f64 - mean_residual;
        score += 0.15 * spread; // pick bins tighter than average
    }

    // Time horizon: late in the stream, be conservative; early, allow exploration.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 20.0 - 18.0 * poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = (post / cap).clamp(0.0, 1.0);

    // Smooth non-linear polynomial core: post-residual with cubic shaping
    let mut score = post * (1.0 + 0.8 * fit * fit * fit);

    // Progress coupling: later in stream, penalize waste more strongly
    score += 6.0 * post * progress * (1.0 - progress) * 0.0; // placeholder removed below
    score -= 0.0;

    // Smooth interaction: waste penalty grows with progress (quadratic ramp)
    score += 4.0 * fit * fit * progress * cap;

    // Last-chance bonus: smooth reward when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
    score -= 8.0 * scarcity * (1.0 - fit);

    // Mean-residual coupling: prefer bins deviating from mean residual (diversity of gaps)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * cap;

    // Lookahead: reward leaving room for the next item (smooth gaussian-like term)
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        let norm = gap / cap;
        score -= 10.0 * (-(norm * norm) / 0.08).exp();
    }

    // New-bin candidate: mild penalty so it only wins when open bins are truly bad
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    // Open-bin pressure: many open bins -> favor filling existing ones
    score += 0.15 * open_bins_count as f64 * fit;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // granularities stay reusable; odd leftovers become dead space.
    let post = post_residual;
    if post > 0 {
        // reward residuals that remain "harmonically clean"
        if post % 10 == 0 { score -= 12.0; }
        else if post % 5 == 0 { score -= 6.0; }
        else { score += 8.0; } // dirty residual penalty

        // tiny unusable slivers are dead space
        if post < 10 { score += 25.0 + (10 - post) as f64 * 2.0; }
        if post == 0 { score -= 20.0; } // perfect closure
    } else {
        score -= 20.0;
    }

    // Integer-division threshold classes on post_residual
    let class = post / 20; // 0..=5 coarse capacity fractions
    score += match class {
        0 => 10.0,                    // 0..19: nearly dead
        1 => -2.0,                    // 20..39: good for mid items
        2 => -5.0,                    // 40..59: sweet spot
        3 => -3.0,
        _ => 0.0,
    } as f64;

    // Lookahead coupling: does the next item fit the post-residual harmonically?
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 10.0; // bin remains useful for the next item
            if post % next_item_size.max(1) == 0 { score -= 5.0; } // exact division
        } else {
            score += 6.0; // next item won't fit here
        }
        // penalize wasting a big residual on a small item when lookahead is large
        if post as f64 > next_item_size as f64 * 2.5 && post > item_size {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open fresh bin when current bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base penalty so we prefer existing bins; relax late in stream
        score += 30.0 - 15.0 * progress;
        // if open bins are nearly full on average, new bin is fine
        if mean_residual < item_size as f64 * 1.2 { score -= 25.0; }
        if open_bins_count == 0 { score -= 50.0; }
    }

    // mild tie-break toward tighter existing bins
    score += (bin_residual as f64 - post as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space) harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits.
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // New empty bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Allow new bin if item is large and lookahead is large too (better pairing).
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 18.0;
        }
    }

    // Lookahead coupling: bonus if next item fits the post residual exactly-ish.
    if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 3.0 {
        score -= 10.0;
    } else if next_item_size > post_residual {
        score += 5.0;
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 6.0 * progress;
    }

    // Slight preference toward bins below mean residual (balance).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain match: strong bonus.
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            // Slight extra reward if post_residual equals next item exactly.
            if slack == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize proportionally to the leftover gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Compare residual against the mean residual across open bins.
    let cap = bin_capacity as f64;
    let rel = post_residual as f64 - mean_residual;
    score += 0.35 * rel;

    // Penalize large dead space that nothing (typical small item) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor
    // or lookahead suggests a big item needing fresh capacity.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can chain the next item too
        }
    }

    // Early in the stream, allow more bins; later, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // Mild preference to keep the number of open bins from exploding.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: penalize residual that is too small to be reusable.
    let min_useful = 10;
    if post_residual < min_useful {
        score -= 50.0; // dead space is fine at the very end of a bin's life
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tightness ratio: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward this bin;
    // if next item would fit better elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        }
        // If next item exactly matches post residual, huge bonus (chained perfect fit).
        if next_item_size == post_residual {
            score -= 40.0;
        }
        // Penalize leaving a residual just below the next item size (blocking).
        if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 12.0;
        }
    }

    // Prefer fuller bins among many open bins (reduce bin fragmentation).
    let capacity_f = bin_capacity as f64;
    let fullness = 1.0 - bin_residual as f64 / capacity_f;
    score -= 10.0 * fullness * (open_bins_count as f64).ln().max(1.0);

    // Global state: if mean residual is high, encourage consolidating into fuller bins.
    if mean_residual > 30.0 && bin_residual < mean_residual {
        score -= 8.0;
    }

    // Time horizon: early in the stream, be more selective (keep bins flexible);
    // late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * fill_ratio;
    if progress > 0.8 && post_residual < 25 {
        score -= 10.0;
    }

    // New-bin candidate: neutral baseline; only open a new bin when no open bin offers
    // a decent fit. Penalize slightly so existing bins win ties, but big residual in
    // an open bin with poor fit will lose anyway.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let norm_post = pr / cap;
    let norm_item = it / cap;

    // Base: post residual (bigger leftover = better fit, lower score)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, tolerate larger leftovers; late, penalize them more strongly.
    let prog_curve = 0.5 + 1.5 * progress * progress;
    score += 40.0 * prog_curve * norm_post * norm_post;

    // Smooth interaction: prefer bins whose leftover complements the next item,
    // using a smooth quadratic bump rather than piecewise logic.
    let nxt = next_item_size as f64 / cap;
    if nxt > 0.0 {
        let gap = (norm_post - nxt).abs();
        score -= 30.0 * (1.0 - gap * gap) * (1.0 - progress);
    }

    // Last-chance bonus: smooth function of fitting bins count.
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 25.0 * scarcity * (1.0 + progress);

    // Penalize bins far from mean residual (smooth dispersion term).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Mild penalty for opening a new bin relative to item size (smooth).
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * norm_item * (1.0 - progress);
    }

    // Small term coupling item size with open bins count to encourage
    // consolidation when many bins are open.
    score += (open_bins_count as f64).ln() * norm_item * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in low classes
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < quarter {
        score -= 25.0; // tight residue, likely usable by small items
    } else if post_residual <= half {
        score += 5.0; // moderate residue
    } else {
        score += 15.0; // large residue: wasteful placement
    }

    // Modulo classes: residues congruent to small multiples of 10 pair well
    let m = post_residual % 10;
    if m == 0 {
        score -= 10.0;
    } else if m >= 7 {
        score += 8.0; // awkward residue class
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack = (post_residual - next_item_size) as f64;
            score -= (slack / cap) * 10.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    } else {
        // last item: prefer perfect closure
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > cap * 0.5
            || (next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1);
        score = if poor_fit { -5.0 } else { 40.0 + 20.0 * (1.0 - progress) };
    }

    // Mild pressure toward consolidating bins
    score += open_bins_count as f64 * 0.05;
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest conceivable item (or the next item) are heavily penalized.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < min_useful && post_residual > 0 {
        // Dead space penalty grows as the gap becomes more useless.
        score += (min_useful - post_residual) as f64 * 25.0;
    }

    // Perfect fit: enormous reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward fits that leave exactly room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }

    // Tight fit bonus proportional to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones; make existing bins more attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late.
        score += open_bins_count as f64 * 8.0 + progress * 40.0;
        // But allow opening a new bin if residual would be a tiny dead gap.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 35.0;
        }
    } else {
        // Existing bins get a mild bonus, stronger with more open bins.
        score -= open_bins_count as f64 * 2.0;
    }

    // Prefer bins whose residual is close to the mean (balance load),
    // penalize outliers that hoard space.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (small dead space).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // 2-step lookahead: if the next item fits into the post-residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 + (slack_after_next as f64).min(20.0);
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: penalize dead space proportionally.
        let waste = post_residual as f64;
        let next_need = next_item_size as f64;
        score += waste * (next_need / bin_capacity as f64);
    }

    // Compare against mean residual: bins tighter than average are precious;
    // wasting them is costly. Bins looser than average absorb less harmfully.
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, especially early in the
    // stream or when many bins are already open but poorly filled.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 + 40.0 * (1.0 - progress);
        if next_item_size > 0 && item_size >= next_item_size {
            score += 10.0; // big item then small item: keep open bins usable
        }
    }

    // Mild tie-break: prefer fuller bins (smaller residual) overall.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

