            }
        }
        // Early in the stream, opening bins is cheaper (more future to use them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // Many open bins already -> discourage proliferation.
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    // Lookahead synergy: prefer placing item so that residual can host next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // residual can accommodate the next item: reward proportionally
            score -= 6.0 * (1.0 - (pr - nxt) / (bin_capacity as f64));
        } else {
            // residual too small for next item: penalize wasted potential
            score += 4.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Global state coupling: if mean residual is high, prefer bins below mean
    // (consolidate waste); if mean residual is low, prefer bins above mean.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (res - mean_residual) / (bin_capacity as f64);
        score -= 5.0 * dev;
    }

    // Mild preference for fuller bins as stream progresses (first-fit-decreasing flavor).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (1.0 - res / (bin_capacity as f64));

    // Discourage opening many bins early via slight open-bin pressure.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: quadratic in normalized post-residual, modulated by progress
    let mut score = x * x * (1.0 + 2.0 * progress) - x * (1.5 - 0.5 * progress);

    // Tight fit reward: smooth bell around small post_residual
    let tight = (-((x * 4.0 - 0.4) * (x * 4.0 - 0.4))).exp();
    score -= 6.0 * tight * (1.0 + 0.5 * progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = x - nx;
        let unusable = (-gap * gap * 12.0).exp();
        score += 3.0 * unusable * (1.0 - progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count <= 1 {
        score -= 4.0 + 3.0 * progress;
    }

    // Mild penalty when bin diverges from mean residual (smooth coupling)
    score += 0.5 * (pr - mean_residual) / cap * (pr - mean_residual) / cap;

    // New-bin candidate: discourage unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64).ln().max(0.0);
        score += 2.0 + 4.0 * (1.0 - progress) - 0.3 * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 captures "waste classes"
    let residue = post_residual % 10;
    score += residue as f64 * 0.35; // penalize residuals not aligned to decile grid

    // Integer-division thresholds: residuals in [0,9] are near-dead space
    if post_residual < 10 {
        score -= 12.0; // reward near-perfect fills
    } else if post_residual < 20 {
        score -= 4.0;
    } else if post_residual > 60 {
        score += 3.0; // leaving huge space suggests we should have opened a new bin
    }

    // Fraction-of-capacity coupling: how much of the bin is used after placement
    let used_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= used_frac * 15.0; // favor fuller bins

    // Lookahead harmonic check: can next item exactly fill post_residual class?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 6.0; // next item still fits here
        } else {
            score += 2.0; // next item won't fit; dead space likely
        }
        // modulo compatibility between next item and leftover
        let compat = (post_residual as i64 % (next_item_size.max(1) as i64)) as f64;
        score += compat * 0.2;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing bins would waste heavily
    if bin_residual == bin_capacity {
        let waste_if_old = mean_residual - item_size as f64;
        if waste_if_old > 25.0 && open_bins_count > 0 {
            score -= 8.0;
        } else {
            score += 18.0; // default: prefer reusing open bins
        }
    }

    // Stream progression: early on, be pickier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * used_frac * 5.0;

    // Mean residual coupling: when open bins are generally full, reuse is precious
    score += (mean_residual / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size 1..100, but typical small items ~10)
    // are pure waste. Penalize gaps in the "unusable zone" heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post_residual as f64) * 6.0;
    }
    // Moderately small gaps are risky if next item can't use them.
    if post_residual > 0 && post_residual < 30 {
        score += 8.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score += 12.0;
        }
    }

    // Reward very tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open bins pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64).sqrt() * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open,
        // unless this is a big item that would leave a good gap anyway.
        score += 15.0 + pressure;
        if item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Filling an existing bin is mildly rewarded, scaled by openness.
        score -= pressure * 0.5;
    }

    // Mean residual coupling: if mean residual is high (lots of slack
    // overall), be pickier about waste; if low, accept decent fits.
    let slack_ratio = mean_residual / bin_capacity as f64;
    score += slack_ratio * (post_residual as f64) * 0.3;

    // Late in the stream, closing bins out cleanly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= 15.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size < post_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff); // perfect lookahead match gets big bonus
        // Penalize leaving dead space the next item cannot use
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Penalize bins that are much tighter than average (waste potential elsewhere)
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when item is large relative to capacity
    if bin_residual == bin_capacity {
        score += (bin_capacity - item_size) as f64 * 0.5;
    }

    // Early stream: encourage filling few bins densely
    let progress = step_index as f64 / total_items as f64;
    score -= (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by how full the bin becomes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score *= 1.0 - 0.35 * fill_ratio;

    // Penalize large post_residual when it becomes dead space (small leftover).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't chain here; slight penalty proportional to wasted potential.
        score += 0.10 * (post_residual as f64 - (post_residual as f64 % next_item_size.max(1) as f64));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; penalize slightly when many bins already fit well.
        score += 8.0;
        if fitting_bins_count > 0 {
            score += 6.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Early in stream, opening bins is cheap; late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Global state: high mean residual means open bins have slack; reward using them.
    score -= 0.15 * mean_residual;

    // Prefer bins whose residual deviates favorably from mean (tighter than average).
    score += 0.10 * (bin_residual as f64 - mean_residual);

    // Many open bins: encourage consolidation.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let mean_res = mean_residual / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.6 * progress * progress);

    // Smooth dead-space penalty: quadratic in normalized post residual
    score += 8.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * progress * norm_item;

    // Penalize bins far from mean residual (prefer balanced residuals)
    let dev = (post - mean_residual).abs() / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item can fit in post residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 6.0 * (next / cap) * (1.0 - progress * 0.5);
        } else {
            score += 3.0 * (next / cap);
        }
    }

    // New-bin candidate handling: discourage opening a new bin unless existing
    // fits are poor; make empty-bin score scale with open bins and progress
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score = 0.9 * cap + 10.0 * open_bins_count as f64 * (0.5 + progress)
            - 2.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" residue classes (near-zero dead space) are strongly favored.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Reward exact / near-exact fits via harmonic residue classes.
    if post == 0 {
        score -= 1000.0; // perfect fit
    } else if post <= 10 {
        score -= 300.0 + (10 - post) as f64 * 10.0;
    } else {
        // Penalize leftovers in "dead space" classes: residues that few item
        // sizes (1..=100) can ever fill efficiently.
        let residue_class = post % 10;
        let class_penalty = match residue_class {
            0 => -50.0,             // round leftover, very reusable
            1 | 9 => 40.0,          // off-by-one leftovers are hard to fill
            2 | 8 => 10.0,
            3 | 7 => 25.0,
            _ => 0.0,
        };
        score += class_penalty;
        // Big leftovers are actually fine (many items fit); mid-size leftovers
        // (11..40) are the danger zone. Use integer-division thresholds.
        if post > 40 {
            score -= (post - 40) as f64 * 0.5;
        } else if post < 11 {
            // already rewarded above
        } else {
            score += (40 - post) as f64 * 1.5; // mid-range dead space penalty
        }
    }

    // Harmonic coupling with the next item (lookahead k=2).
    if next_item_size > 0 {
        let nx = next_item_size as i64;
        if nx == post {
            score -= 500.0; // next item exactly fills this bin
        } else if nx <= post {
            // next item fits: reward proportional to how snugly
            score -= (post - nx) as f64 * 2.0;
            // modulo harmony: next item and post_residual share a factor class
            if post % nx == 0 || nx % post.max(1) == 0 {
                score -= 30.0;
            }
        } else {
            // next item will NOT fit here: if this is the last chance bin,
            // opening a new bin may be better than wasting it
            if fitting_bins_count == 1 {
                score += 80.0;
            }
        }
    }

    // Last-chance bonus: only one bin fits the item; using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer it only when open bins have poor aggregate fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduced when many items remain or
        // existing bins are fragmented (low mean residual).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 60.0 + 120.0 * fragmentation - 40.0 * progress;
        if next_item_size > 0 && (next_item_size as i64) > post {
            // next item wouldn't fit here anyway; slight discount for new bin
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard reward for perfect fit: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps (1..10) are heavily penalized,
    // since the smallest item is 1 and gaps below typical item sizes are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }

    // Penalize leaving a gap that the lookahead item cannot use, reward gaps it can use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= next_item_size as f64 * 1.5;
        } else if post_residual > 0 {
            score += next_item_size as f64 * 0.8;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // (consolidate leftover space into fewer, larger gaps).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.15;

    // New-bin candidate: only attractive when the item is large relative to the
    // capacity and no good fit exists; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 30.0;
        if fill_ratio > 0.7 && fitting_bins_count == 0 {
            score -= 60.0;
        }
        if fill_ratio <= 0.5 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but penalize dead space more aggressively than linear.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.3) * 0.05;
    } else {
        // Perfect fill is highly desirable.
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            let gap = post_residual as f64 - nx;
            // Exact match => next item fills this bin perfectly.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Slight preference if the follow-up fit is still "snug".
            if gap <= 10.0 {
                score -= 10.0;
            }
        } else {
            // Post-residual too small for next item: dead space unless zero.
            score += 8.0 * (nx - post_residual as f64).min(30.0) / 30.0;
        }
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or stream is early and we want spread capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins when good alternatives exist.
        if fitting_bins_count > 0 {
            score += 20.0 + 15.0 * (1.0 - progress);
        }
        // Late in the stream, opening bins is almost always wasteful.
        score += 10.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 && post_residual as f64 >= next_item_size as f64 {
            score -= 12.0;
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero gets strong bonus.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize small dead space that is hard to fill (below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits in post_residual (chain packing).
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 25.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64).min(50.0) * 0.3;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 10.0;

    // Time horizon: early in stream, opening new bins is cheaper (explore);
    // late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 60.0 * progress;
    } else {
        score -= 15.0 * progress;
    }

    // Global residual balance: if this bin's residual is far below mean,
    // placing here reduces fragmentation.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    // Mild penalty for very loose fits relative to item size.
    score += (bin_residual as f64 / item_size.max(1) as f64).powi(2) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = pr / cap;
    let mut score = pr;

    // Strongly reward tight fits: post_residual squared coupling
    score += 0.8 * pr * pr / cap;

    // Smooth stream-progress coupling: late in stream, tighter packing matters more
    score -= 12.0 * (1.0 - fit) * progress * progress;
    score += 6.0 * fit * (1.0 - progress);

    // Penalize dead space relative to mean residual
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - fit);
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 10.0 * (nxt / cap) * (1.0 - fit);
        } else {
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // New-bin candidate: mild penalty so it's only chosen when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into capacity/10 classes.
    let class_width = (bin_capacity / 10).max(1);
    let post_class = (post_residual / class_width) as f64;

    // Reward small post_residual (tight fit) with a multiplicative discount.
    score *= 1.0 - 0.35 * (1.0 - post_class / 10.0);

    // Exact-fill class: zero residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (harmonic floor).
    let dead_floor = class_width;
    if post_residual > 0 && post_residual < dead_floor {
        score += 12.0;
    }

    // Modular resonance: if post_residual is an exact multiple of class_width,
    // future items in the same class can tile it perfectly.
    if post_residual % class_width == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    // (harmonic pair), penalize if next item would leave a new dead zone.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let nr = post_residual - next_item_size;
            score -= 8.0 * (1.0 - (nr as f64 / bin_capacity as f64));
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the item would leave a "harmonic" residual or when
    // current bins are crowded.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6;
        if post_residual % class_width == 0 {
            score -= 8.0;
        }
        if open_bins_count == 0 || fitting_bins_count == 0 {
            score -= 40.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Stream-phase modulation: late in the stream, prefer closing bins tightly.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Congestion pressure: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > 40.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps that can't fit the smallest item)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits
    score -= 30.0 * (item_size as f64 / bin_residual as f64);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer opening a new bin when many bins are open and the fit is loose
    let loose = post_residual as f64 / bin_capacity as f64;
    score += open_bins_count as f64 * 2.0 * loose;

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Mild pressure toward consolidation early, openness later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * (0.3 - 0.2 * progress);

    // New-bin candidate: slightly penalize so it's used only when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 - 20.0 * loose;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual matches the next item well.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post >= nxt && post - nxt <= 10.0 {
            // next item fits almost perfectly -> strong reward
            score -= 25.0 * (1.0 - (post - nxt) / 10.0);
        } else if post >= nxt {
            // next item fits, but leaves more slack -> mild reward
            score -= 6.0 * (nxt / (post + 1.0));
        } else {
            // next item does not fit: penalize residual that is close-but-too-small (dead space)
            let gap = nxt - post;
            if gap <= 10.0 {
                score += 12.0 * (1.0 - gap / 10.0);
            }
        }
    } else {
        // Last item: just prefer tightest fit (already encoded in post_residual).
    }

    // Prefer bins whose residual is below mean residual (i.e., filling fuller bins first).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit well, especially early/mid stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 30.0 + 0.5 * waste - 15.0 * progress;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Slight penalty for leaving very small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(6);

    // Penalize unusable dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 18.0;
    } else if post_residual < item_size.max(10) {
        score += 6.0;
    }

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + slack);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0; // next item won't chain here
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: when few fitting bins exist, avoid fragmenting good bins.
    if fitting_bins_count <= 2 && post_residual > 0 {
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: early in stream, be more willing to open new bins for large items;
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or for large items, unattractive late.
        score += 10.0 * progress - 6.0 * (item_size as f64 / bin_capacity as f64);
        score += 0.4 * open_bins_count as f64;
    } else {
        // Prefer fuller bins as stream progresses.
        score -= 8.0 * progress * (1.0 - fit_ratio);
    }

    // Mean-residual steering: if this bin is much emptier than average, mildly deprioritize.
    score += 0.15 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual (waste), scaled non-linearly by stream progress
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Non-linear polynomial coupling: penalize mid-range residuals more as stream progresses
    let x = norm_pr;
    score += progress * (x * (1.0 - x)) * 40.0 * (1.0 - norm_item);

    // Tight fit reward (smooth quadratic in item size)
    score -= norm_item * norm_item * 30.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if next item won't fit in post residual
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score -= 4.0;
    }

    // Crowding: mild penalty when many bins are open relative to mean residual
    score += (open_bins_count as f64).ln() * mean_residual * 0.05;

    // New-bin candidate: make empty bins moderately attractive only for large items
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.4 * norm_item) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes via integer division
    let item_class = item_size / 10;
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Reward tight fits: small post_residual is good, but dead space below
    // the smallest plausible item (<= 10) is worthless.
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual < 20 {
        score -= 12.0;
    } else if post_residual < 35 {
        score -= 4.0;
    }

    // Modulo arithmetic: residual compatible with common item sizes
    // (multiples of 5 or 10 leave room for future harmonic partners)
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else {
        score += 3.0; // awkward residual
    }

    // Class complementarity: if next item's class matches residual's
    // harmonic slot (residual / 10 >= next_class), reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0; // next item fills this bin nearly perfectly
        } else {
            score -= (10 - slack.min(10)) as f64 * 0.5;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here -> residual likely becomes dead space
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins mildly; outweighed only by terrible fits
        score += 18.0 + 10.0 * progress;
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 30.0; // large item with nowhere to go: new bin is right
        }
    }

    // Prefer bins below mean residual (denser bins) to consolidate space
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference for fewer open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Gaps too small for the smallest conceivable item are pure dead space.
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 35 {
            score += 6.0;
        }
        // Penalize gaps that cannot fit the lookahead item (k=2) but could
        // otherwise have been useful.
        if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
            score += 8.0;
        }
    }

    // Reward tight fits: post_residual near zero is excellent.
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins and
    // encourage filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open.
        score += 15.0 * pressure;
        // But allow new bin if all open residuals are small/dead-space prone.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    } else {
        // Filling existing bins reduces pressure slightly.
        score -= 2.0 * pressure.min(3.0);
    }

    // Slightly prefer bins with below-mean residual (consolidating waste).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack proportional to how well the next item will nest.
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - slack.min(40.0);
        } else {
            // Penalize dead space that cannot fit the next item.
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Prefer bins with residuals below the mean (compact bins), penalize using bins far above mean.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great 2-step chain.
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 150.0; // fresh bin can chain with next item
        }
        // Later in the stream, opening a new bin is slightly less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 40.0;
    }

    // Mild penalty for leaving large unusable gaps (> half capacity).
    if post_residual as f64 > bin_capacity as f64 * 0.5 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny sliver is wasted capacity
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: bonus if the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect two-item closure
        } else if next_item_size <= post_residual {
            score -= 3.0; // next item still fits here
        } else {
            score += 4.0; // next item won't fit; keep residual large elsewhere
        }
    }

    // Prefer bins whose residual is below the mean (consolidate fuller bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: early in the stream, be more willing to spread items;
    // late in the stream, pack tightly to close bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let crowding = if fitting_bins_count == 0 { 1.0 } else { (fitting_bins_count as f64).recip() };
        score += 30.0 * (1.0 - crowding) - 10.0 * (1.0 - progress);
    }

    // Mild penalty for proliferation of open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, minimize waste mildly; late, penalize dead space harder.
    let w = 0.5 + 1.5 * progress * progress; // quadratic ramp in progress
    score += w * (post * post) / cap;

    // Reward tight fits (small post_residual relative to item) with a smooth cubic term.
    let tightness = 1.0 - post / cap; // 1.0 = perfect fit
    score -= 6.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).ln_1p();
    }

    // Lookahead: prefer leaving post_residual that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 4.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Deviation from mean residual: prefer bins near the mean to balance load,
    // with a smooth quadratic interaction scaled by progress.
    let dev = bin_residual as f64 - mean_residual;
    score += (0.5 + 2.0 * progress) * (dev * dev) / (cap * cap) * 4.0;

    // Mild penalty for opening new bins when many bins already exist.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets reward "usable" leftovers
    let cls = post_residual % 10;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score -= 25.0; // dead space, acceptable
    } else if cls == 0 {
        score -= 15.0; // round leftover, likely reusable
    } else {
        score += cls as f64 * 0.4; // awkward leftover penalty
    }

    // Lookahead coupling: does leftover fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.3;
        } else {
            score += 12.0; // forces a new bin later
        }
    } else {
        score += post_residual as f64 * 0.1; // last item: prefer fuller bins
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening unless residuals are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + mean_residual * 0.5 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0; // next item needs a fresh bin anyway
        }
    }

    // Prefer bins whose residual is far below mean (compact usage)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1)
    // are pure waste; residuals below a "usable gap" threshold are heavily penalized.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable dead space: hard penalty proportional to wasted capacity.
        score += (10 - post_residual) as f64 * 40.0;
    } else if post_residual < 20 {
        // Marginal gap: moderate penalty scaled by remaining stream length.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (20 - post_residual) as f64 * (6.0 + 10.0 * progress);
    }

    // Reward tight fits generally (small post_residual relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64).abs() * 0.5;

    // Open-bins pressure: discourage spreading across many bins; encourage
    // filling existing bins when the count is high.
    score += open_bins_count as f64 * 3.0;

    // Prefer bins whose residual deviates below the mean (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            // Next item would create dead space here; mild penalty.
            score += 15.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            // Post residual still usable for other items; slight bonus.
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when no open bin offers a good fit, by adding
    // a fixed opening cost that tight fits elsewhere can overcome.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // If next item is large, a fresh bin is more valuable later in stream.
        if next_item_size > item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // next item can also fit here: strong reward proportional to tightness
            score -= 300.0 - diff * 2.0;
        } else {
            // next item won't fit: penalize wasted space slightly more
            score += diff * 0.5;
        }
    }

    // Compare against mean residual: prefer bins with residuals below mean (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 150.0;
        // if lookahead matches a fresh bin well, allow it
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64).abs() < 5 {
            score -= 100.0;
        }
    }

    // Late in the stream, prefer tighter packing (favor small post_residual more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fit gets strong bonus.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that can't fit typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if next_item_size > post_residual && next_item_size <= bin_capacity {
            // post residual too small for next item -> mild penalty for wasted space
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer filling bins as much as possible.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // Cheaper to open a new bin early in the stream (more future items to use it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // Opening a new bin is more attractive when existing residuals are small.
        score -= 15.0 * (mean_residual / bin_capacity as f64);
        // If item fits poorly anywhere (very large item relative to residual), new bin less bad.
        if fit_ratio > 0.9 {
            score -= 45.0;
        }
    }

    // Global state: with many open bins, encourage consolidation into existing bins.
    score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * fit_ratio;

    // Prefer bins with residual close to item size (smooth coupling).
    let slack = (bin_residual - item_size) as f64;
    score += 0.15 * slack;

    // Small time-horizon modulation: late in stream, prioritize minimizing residual.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Core waste term, non-linearly amplified by stream progress
    let mut score = pr.powf(1.3 + 0.9 * progress);

    // Tight-fit reward: small post_residual strongly discounted
    let tightness = 1.0 - (pr / cap);
    score -= 40.0 * tightness * tightness;

    // Dead-space penalty: residuals too small for typical future items
    let small_floor = 10.0_f64.min(cap * 0.1);
    if pr > 0.0 && pr < small_floor {
        score += (small_floor - pr) * (2.0 + 4.0 * progress);
    }

    // Lookahead: reward if next item can use the leftover space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 15.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline, mildly discouraged unless progress is low
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild coupling with mean residual: prefer bins deviating from mean (consolidation)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is "usable" by common
    // item sizes deserves less penalty than odd-sized slivers.
    // Class 0: post_residual % 10 == 0  -> aligns with typical item granularity
    // Class 1: post_residual % 5 == 0   -> moderately reusable
    // Class 2: everything else          -> likely dead space
    let post = post_residual;
    if post == 0 {
        score -= 25.0; // perfect fit: heavily reward
    } else if post % 10 == 0 {
        score -= 6.0;
    } else if post % 5 == 0 {
        score -= 2.0;
    } else {
        score += 4.0; // odd sliver penalty
    }

    // Dead-space threshold: residuals below the minimum item size (1) can't
    // happen, but small residuals (< 20) are hard to fill -> penalize via
    // a nonlinear squashing.
    if post > 0 && post < 20 {
        score += (20.0 - post as f64) * 0.8;
    }

    // Integer-division threshold on next_item_size: if the lookahead item
    // can fit exactly into post_residual, reward strongly (chained fit).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 18.0;
        } else if next_item_size < post {
            // next item fits but leaves a new residual; check harmonic
            // compatibility of the chain: (post - next) % 5 == 0 is good.
            let chain = post - next_item_size;
            if chain % 5 == 0 {
                score -= 5.0;
            } else {
                score += 2.0;
            }
        } else {
            // next item won't fit here; mild penalty proportional to gap class
            score += ((next_item_size - post) / 10) as f64 * 1.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, opening a new bin
    // wastes this residual entirely; reward using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Capacity-fraction coupling: favor bins whose residual is a small
    // fraction of capacity (tight packing) using integer division tiers.
    let tier = bin_residual / (bin_capacity / 4); // 0..=4
    score += tier as f64 * 1.2;

    // Mean-residual coupling: if this bin is much emptier than average,
    // penalize slightly (prefer filling fuller bins first, best-fit style).
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.05;

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (harmonic alignment matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Moderate penalty for medium dead space (hard to fill later).
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins whose residual was large (good consolidation) but keep tight fits best:
    // combine with fit ratio of item into bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are healthy.
    if bin_residual != bin_capacity {
        score += 0.8 * open_bins_count as f64;
    } else {
        // New-bin candidate: only attractive when existing bins would leave bad gaps
        // or when open bins are nearly full on average.
        score += 30.0 + 2.0 * open_bins_count as f64;
        if mean_residual > 60.0 {
            score -= 25.0;
        }
        // If the next item could use this bin's full space well, opening is fine.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Lookahead: penalize placements that leave a gap the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
