    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly or closely.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 400.0; // perfect 2-step chain
        } else if diff <= 5.0 {
            score -= 150.0;
        } else if diff <= 10.0 {
            score -= 60.0;
        } else {
            score += diff * 0.5; // penalize mismatched leftovers
        }
        // Penalize dead space the next item cannot use.
        if post_residual > 0 && (post_residual as u32) < next_item_size.min(10) {
            score += 40.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 100.0 - waste * 0.5; // new bin only attractive for tiny items
        if next_item_size > 0 && next_item_size as f64 >= waste {
            score += 50.0; // new bin wastes space for the next item too
        }
    }

    // Slight late-stream tightening: consolidate more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where item fills a large fraction of residual.
    let residual = bin_residual as f64;
    let fit_ratio = item_size as f64 / residual.max(1.0);
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space left behind (hard-to-use slivers).
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0; // tiny sliver is nearly dead space
        } else {
            score += 10.0 * (10.0 / pr); // smaller leftovers penalized more
        }
    } else {
        score -= 40.0; // perfect closure is excellent
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack = post_residual as f64 - nxt;
            if slack == 0.0 {
                score -= 35.0; // next item closes this bin perfectly
            } else {
                score -= 15.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            score += 8.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Global state: with many open bins, encourage consolidation into existing bins.
    let open_f = open_bins_count as f64;
    score += 3.0 * open_f * (1.0 - fit_ratio);

    // Mean residual coupling: if this bin is much emptier than average, it's a good host.
    let dev = mean_residual - residual;
    score += 0.5 * dev;

    // Time horizon: early in the stream, be slightly more willing to open new bins
    // (long future to exploit them); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * progress * (1.0 - fit_ratio);

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no good fit exists:
        // penalize it more when other bins fit and mean residual is large.
        score += 15.0 + 0.4 * mean_residual + 5.0 * (fitting_bins_count as f64);
        // But early in the stream, new bins are cheaper to open.
        score -= 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - norm_post);
    let coupling = poly * (0.5 + 2.0 * progress);

    let mut score = post;

    // Penalize large residuals early, reward tight fits late
    score += coupling * cap * 0.5;

    // Smooth interaction: waste relative to mean residual, scaled by progress
    let waste = (post as f64 - mean_residual).max(0.0);
    score += waste * waste / cap * (0.3 + 0.7 * progress);

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= cap * (0.6 + 0.4 * (1.0 - progress));
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        // smooth penalty if next item nearly fits (near-miss dead space)
        let miss = (next_item_size as f64 - post) / cap;
        score += miss * miss * cap * 0.25;
    }

    // Mild penalty for proliferating open bins
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by small
    // class sizes (10/20/25/50) are more reusable by typical item sizes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 8.0; }
        // Dead-space penalty grows super-linearly for tiny unusable slivers
        if pr < 10 {
            score += (10 - pr) as f64 * 4.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: the closer, the better
            score -= 15.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here: slightly penalize wasting capacity
            score += 4.0;
        }
    }

    // Fractional capacity coupling: penalize leaving less than half a bin
    let frac = pr as f64 / cap;
    if frac > 0.0 && frac < 0.5 {
        score += (0.5 - frac) * 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // baseline resistance to opening new bins
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 80.0; // forced: must open a new bin
        } else if mean_residual < item_size as f64 * 1.2 {
            score -= 20.0; // open bins are nearly full anyway
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate: prefer bins below mean residual
    // (i.e., fuller bins) when many bins are open.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 - mean_residual).max(-20.0).min(20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
