        score += 80.0 * (1.0 - tightness) + open_bins_count as f64 * 2.0;
    }

    // Early in the stream, be slightly more willing to spread items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else {
        // Penalize dead space quadratically for small leftovers.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += (10.0 - dead) * (10.0 - dead) * 2.0;
        }
    }

    // Lookahead: penalize residuals that cannot host the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64) < n {
            // Waste that can't serve next item is dead weight.
            score += (post_residual as f64) * 1.5 + n * 0.5;
        } else {
            // Residual can host next item: reward proportional to snugness.
            let snug = (post_residual as f64) - n;
            score -= 50.0 - snug * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Time horizon: early in stream, be conservative (favor tight fits,
    // avoid opening bins); late in stream, exploit remaining capacity.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let horizon = (1.0 - t) * 40.0;
    score += horizon * (post_residual as f64) / bin_capacity as f64;

    // Global state coupling: many open bins with high mean residual
    // suggests we should consolidate into existing bins.
    if open_bins_count > 3 && mean_residual > (item_size as f64) {
        score -= 30.0;
    }
    score += mean_residual * 0.05;

    // New empty bin candidate: only attractive if item is large and
    // nothing else fits well.
    if bin_residual == bin_capacity {
        score += 150.0;
        if item_size > 60 && fitting_bins_count == 1 {
            score -= 160.0;
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, leave room (prefer moderate post_residual); later, tighten fits.
    let mut score = x * x * (1.0 + 2.0 * progress) + x * (0.5 - progress);

    // Dead-space penalty: post_residual too small to fit typical future items.
    let dead = if post_residual > 0 && (next_item_size as f64) > post { 1.0 } else { 0.0 };
    score += dead * (0.3 + 0.7 * progress) * x;

    // Lookahead synergy: reward bins whose post_residual can host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - (post - next_item_size as f64) / cap;
        score -= 0.4 * fit_quality * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // New-bin candidate: penalize opening a bin when alternatives exist,
    // but allow it when open bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        let crowd = mean_residual / cap;
        score += 0.8 + 1.2 * (1.0 - crowd) - 0.5 * progress;
        if fitting_bins_count == 0 { score -= 2.0; }
    }

    // Mild penalty for wasting a large bin on a small item (fragmentation avoidance).
    score += 0.2 * (item_size as f64 / cap) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes of common item sizes
    // Dead space is worthless if no future item can fit it. Penalize residuals that
    // fall into "orphan" classes (small, hard-to-fill leftovers).
    let cap = bin_capacity as f64;

    // Fraction of capacity wasted
    let waste_frac = post_residual as f64 / cap;
    score += 20.0 * waste_frac * waste_frac;

    // Perfect / near-perfect fits get strong reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Harmonic class check: can next_item_size land exactly in the leftover?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // exact chain fit
        } else if next_item_size < post_residual {
            let chain_post = post_residual - next_item_size;
            // reward chain residuals that again fall in nice classes
            if chain_post == 0 {
                score -= 30.0;
            } else if chain_post <= 10 {
                score -= 12.0;
            } else if chain_post < 10 {
                score -= 5.0;
            } else {
                // penalize if chained leftover is an awkward orphan class
                score += 3.0;
            }
        } else {
            // next item cannot use this bin's leftover: leftover riskier
            score += 6.0;
        }
    }

    // Modulo-style harmonic classes on post_residual vs common size buckets
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 { -8.0 }
        else if pr >= 90 { -6.0 }      // big residual still very usable
        else if pr >= 50 { -2.0 }
        else if pr >= 30 { 2.0 }
        else if pr >= 20 { 4.0 }
        else { 8.0 };                  // 1..19 orphan zone
    score += class_penalty;

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer tighter bins relative to the mean residual (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, be slightly more willing to open fresh bins for large items;
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late
        score -= 10.0 * (1.0 - progress);
        score += 8.0 * progress;
        // Opening a new bin is good if the item is huge relative to capacity
        score -= 0.2 * (item_size as f64);
    } else {
        // Consolidation pressure grows with progress
        score -= 4.0 * progress;
    }

    // Too many open bins: discourage new bins
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item
    // (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 25.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 10.0; // creates a new dead gap
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (make the empty-bin candidate less attractive relative to existing bins).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean
        // residual is still usable.
        score += 40.0 + open_bins_count as f64 * 5.0 + mean_residual * 0.5;
        // But if no existing bin fits well (large post-residuals elsewhere),
        // the base post_residual (= capacity) comparison handles it.
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: new bin is mandatory
        }
    }

    // Mild stream-progression term: late in the stream, prefer consolidating
    // into fewer bins (favor bins below mean residual slightly).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.1 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty for wasted residual (dead space), amplified for tiny leftovers.
    if post_residual > 0 {
        let waste = 1.0 / (post_residual as f64 + 1.0);
        score += 40.0 * waste;
    } else {
        // Perfect fit: heavy reward.
        score -= 60.0;
    }

    // 2-step lookahead: reward if the next item fits exactly / well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // chainable perfect fit
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Reward proportional to how snugly the next item fits.
            score -= 50.0 / (gap + 1.0);
            // Penalize leaving residual slightly larger than next item (attractive but wasteful).
            if gap > 0.0 && gap < 10.0 {
                score += 0.5 * (10.0 - gap);
            }
        } else {
            // Next item cannot fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 2.0 * over;
        }
    } else {
        // Last item: just minimize post residual.
        score += 10.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins)
    // when this placement keeps them tight; penalize dumping into already-loose bins.
    let res_f = post_residual as f64;
    if res_f > mean_residual {
        score += 0.6 * (res_f - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - res_f);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a new bin costly unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But allow a new bin if the item is huge and would leave near-zero residual anyway
        if post_residual <= 5 {
            score -= 70.0;
        }
    }

    // Slight preference to fill earlier-opened bins as stream progresses (bin consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // Prefer bins among many fitting candidates that are tighter (best-fit tiebreak).
    if fitting_bins_count > 1 {
        score += 0.1 * (fitting_bins_count as f64 - 1.0) * (res_f / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual < 30 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Lookahead: bonus if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 80.0;
        } else {
            score += 20.0;
        }
    }

    // Global state coupling: prefer bins below mean residual (keeps large residuals spread).
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += (residual_f - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - residual_f) * 0.2;
    }

    // Time horizon: early in stream, be pickier (penalize mediocre fits to save space later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * fit_ratio * 50.0;

    // New-bin candidate: baseline cost of opening a bin; make it attractive only when
    // existing bins would leave bad post-residuals.
    if bin_residual == bin_capacity {
        let base = 120.0;
        // If item is large relative to capacity, opening fresh is more tempting.
        let size_frac = item_size as f64 / bin_capacity as f64;
        score = base - size_frac * 60.0 + (1.0 - progress) * 30.0;
        // If a last-chance bin exists, discourage opening a new one.
        if fitting_bins_count == 1 {
            score += 300.0;
        }
        // Many open bins with large mean residual: prefer reusing.
        if mean_residual > 40.0 {
            score += 50.0;
        }
    }

    // Slight preference to fill bins with more items already packed (denser bins first)
    // approximated by lower residual: already handled via fit_ratio.

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post_residual (tight fit)
    let mut score = pr;

    // Non-linear polynomial coupling with stream progress:
    // late in the stream, dead space becomes more costly -> amplify post_residual penalty
    let progress_coupling = pr_norm * pr_norm * (progress * (1.0 - progress) * 4.0);
    score += 20.0 * progress_coupling * cap;

    // Cubic smoothness term: penalize mid-range residuals mildly, tiny residuals strongly favored
    score += cap * (pr_norm * pr_norm * pr_norm) * (1.0 + progress);

    // Reward near-perfect fits (post_residual close to zero) with smooth exponential-like polynomial
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - slack) * (1.0 - slack);
    }

    // Penalize opening new bins when many bins exist with usable residual
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    }

    // Mild preference for bins below mean residual (balancing)
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes (multiples of small denominators) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction-of-capacity classes: reward residuals that are "reusable"
    // (>= 20 units can host typical items), penalize dead space < 20.
    if post_residual == 0 {
        score -= 60.0; // perfect fill: excellent
    } else if post_residual < 20 {
        score += 35.0; // unusable dead space: strong penalty
    } else if post_residual < 35 {
        score += 8.0; // marginal space
    } else {
        score -= 6.0; // comfortably reusable
    }

    // Modulo coupling: residuals divisible by 10 or 5 tend to pair well
    // with items drawn from coarse-grained distributions.
    if post_residual % 10 == 0 {
        score -= 7.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Integer-division harmonic class of next item vs post residual:
    // if the lookahead item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let leftover_after_next = post_residual - next_item_size;
            if leftover_after_next < 20 {
                score += 12.0; // chain creates new dead space
            } else {
                score -= 14.0; // chain remains usable
            }
        } else {
            // next item cannot go here; if this is the only fitting bin,
            // leaving a large residual is wasted opportunity
            if fitting_bins_count == 1 && post_residual > 40 {
                score += 15.0;
            }
        }
    }

    // Last-chance logic: strongly prefer using the sole fitting bin over
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are badly fragmented or the stream is young.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - pr).abs();
        score += 18.0 + 25.0 * progress + fragmentation.min(50.0);
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // big item coming: fresh bin is valuable
        }
    }

    // Mild normalization toward tight fits: penalize distance of post
    // residual from the mean residual (keeps bin population homogeneous).
    score += 0.08 * (pr - mean_residual).abs();

    // Small step-based drift: later in the stream, prefer filling existing
    // bins aggressively (compactification phase).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item (1) are pure waste,
    // but gaps too small for typical items are heavily penalized.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64; // unusable sliver
    }

    // Penalize mid-range gaps that likely can't fit the next item (lookahead-aware).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits: small post_residual relative to item size.
    score -= 2.0 * item_size as f64 / (post_residual as f64 + 5.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Pressure from many open bins: discourage spreading items across bins.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins with below-average residual (denser bins) when many bins are open.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: only attractive when current bin would leave a bad gap
    // or no bin fits well; an empty bin is flexible for the future.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        // Opening a new bin is cheap early, expensive late in the stream.
        score += 10.0 * (1.0 - step_index as f64 / (total_items.max(1) as f64));
        // Discourage new bin if a decent fit exists elsewhere.
        if post_residual == 0 || (next_item_size > 0 && post_residual >= next_item_size) {
            score += 30.0;
        }
        // Favor new bin when open-bin pressure is high.
        score -= 0.5 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 35.0; // don't open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual too small to fit any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2-step lookahead: perfect match of next item into post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain perfectly
        } else if post_residual >= next_item_size {
            score -= 15.0; // next item still fits here
        } else {
            // leftover cannot host next item: penalize proportionally to waste
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }

        // Bonus if post_residual can host next item with minimal slack
        if post_residual >= next_item_size {
            score -= 0.3 * (post_residual as f64 - next_item_size as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // but allow it if existing bins would leave huge dead space
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual dominates.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when a decent fit exists in an open bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of consuming fresh capacity.
        score += 25.0;
        // If many bins fit the item, opening a new bin is rarely good.
        if fitting_bins_count > 1 {
            score += 30.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
        }
        // Early in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 15.0;
        // If mean residual is large, open bins have slack; use them.
        score += (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Lookahead: if the next item fits perfectly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let next_waste = (post_residual - next_item_size) as f64;
            score += next_waste * 0.4;
        } else {
            // Next item won't fit here anyway; slight penalty for leaving
            // awkward gaps larger than the next item.
            let gap = post_residual as f64;
            if gap < (next_item_size as f64) * 0.5 {
                score -= gap * 0.3; // small dead space is fine
            } else {
                score += 5.0;
            }
        }
    }

    // Prefer using bins whose residual is close to the item (avoid fragmenting
    // large residuals with small items).
    let fill_ratio = (item_size as f64) / (bin_residual as f64);
    if fill_ratio > 0.8 {
        score -= 12.0;
    } else if fill_ratio < 0.3 && bin_residual != bin_capacity {
        score += 10.0;
    }

    // Mild penalty when many bins are open: encourage closing bins out.
    score += (open_bins_count as f64) * 0.3;

    // Global time pressure: late in stream, be more aggressive at filling bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: dead space penalized more as stream progresses
    score += 12.0 * norm_pr * norm_pr * (progress * (1.0 - progress) * 4.0 + 0.25);

    // Reward tight fits (post_residual near zero) increasingly over time
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (0.5 + progress);
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        score -= 10.0 * fits_next * (1.0 - pr / (cap * 2.0));
        // Penalize leaving residual just below next item size (unusable gap)
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 && gap <= 12.0 {
            score += 8.0 * (1.0 - gap / 12.0);
        }
    }

    // Mild penalty when bin residual deviates from mean residual (spread awareness)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowd = fitting_bins_count as f64 / (open_bins_count.max(1) as f64);
        score = cap * (1.2 + progress) - 20.0 * (1.0 - crowd.min(1.0));
        if fitting_bins_count <= 1 {
            score -= 60.0; // no real alternative -> new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: dead-space classification
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,                 // perfect fit
        1..=5 => 1.0,             // near-perfect
        6..=15 => 2.0,
        16..=30 => 3.0,
        31..=50 => 4.0,
        _ => 5.0,
    };
    score += class * 3.0;

    // Perfect fit bonus
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    }

    // Penalize small unusable slivers relative to capacity fraction
    let frac = pr as f64 / cap;
    if frac > 0.0 && frac < 0.06 {
        score += 12.0; // tiny sliver wasted
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer new bin only if current fit is bad (large post_residual)
        if pr >= 40 {
            score -= 20.0;
        } else {
            score += 30.0;
        }
        // Few open bins: cheap to open new
        if open_bins_count < 4 {
            score -= 10.0;
        }
    }

    // Lookahead: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0; // chain-friendly
            // harmonic alignment: next item divides residual well
            if pr % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Mean residual coupling: avoid bins far from the mean (fragmentation control)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Progress-based tightening: later in stream, prefer tighter fills
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item) are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 9 {
        score += 60.0;
    }

    // Penalize leaving a gap that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to capacity)
    score -= (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 10.0;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation over new bins
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: penalize unless current bin would leave a bad gap
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
        // Early stream: allow new bins more freely to build diversity
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Prefer bins whose residual is below mean (use up fuller bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Exact fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fills strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportionally to how well it fills again.
            let second_fill = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * second_fill;
            // Bonus if two consecutive near-perfect fills.
            if post_residual - next_item_size <= 5 {
                score -= 100.0;
            }
        } else {
            // Next item cannot fit here: penalize leaving a gap smaller than next item (dead space).
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 40.0 * (1.0 - dead / next_item_size as f64);
            }
        }
    }

    // Penalize large residuals relative to mean residual (wasted space vs. fleet average).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 80.0 * progress;

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 60.0 + 2.0 * open_bins_count as f64;
        // But if this item is huge and would leave tiny dead space anywhere else, new bin is fine.
        if post_residual <= 10 {
            score -= 150.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Penalize dead space that is too small to be useful later (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect pair
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins with below-average residual (compact full bins first).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Global pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has residual == capacity, so this raises its score).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);

        // But allow a new bin if the item is large and would leave awkward space anywhere.
        if item_size > bin_capacity / 2 && next_item_size > post_residual.min(bin_capacity) {
            score -= 6.0;
        }
    }

    // Mild time-horizon term: early on, be greedy about tight fits; later, be conservative.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // non-linear polynomial coupling of post_residual with stream progress
    let w = 0.5 + 1.5 * progress;
    score += w * cap * pr_norm * pr_norm * (1.0 - pr_norm);

    // penalize dead space relative to mean residual, scaled by progress
    score += 3.0 * progress * (pr - mean_residual).abs();

    // lookahead: reward bins whose post residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    }

    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // new-bin candidate: mildly penalized early, allowed late
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize so it's chosen only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty proportional to how many bins could already fit the item.
        score += 60.0 + 10.0 * fitting_bins_count as f64;
        // If this is the only option (no open bin fits), allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Lookahead: if next item is large, a fresh bin is more attractive.
        score -= (next_item_size as f64) * 0.15;
        return score;
    }

    // Tight fit reward: harmonic classes of post_residual.
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Classify dead space by modulo classes of capacity fractions.
        let r = post_residual;
        if r <= 10 {
            // Tiny dead space is nearly a perfect fit.
            score -= 60.0 - (r as f64) * 2.0;
        } else if r <= 20 {
            score -= 25.0 - (r as f64);
        } else if r <= 50 {
            // Mid-range residual: moderately useful.
            score -= 5.0;
        }
        // Harmonic modulo structure on residual: multiples of 10 keep space usable
        // for the common item-size classes.
        if r % 10 == 0 {
            score -= 8.0;
        } else if r % 5 == 0 {
            score -= 3.0;
        } else {
            // Awkward remainder: penalize.
            score += (r % 5) as f64 * 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead synergy: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 20.0 - slack as f64;
            }
        } else {
            // Next item won't fit here; slight penalty for leaving moderate space.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Prefer filling bins that deviate below the mean residual (consolidation).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Mild preference for fewer open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to residual and open bins are fragmented, or residuals are
    // small on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bins mildly; reduce penalty when open bins are fragmented
        // or late in the stream with large future items.
        score -= 30.0 * (fragmentation - 0.35).max(0.0) * 10.0;
        score += 55.0; // base cost of opening a new bin
        score -= 20.0 * progress * (item_size as f64 / 100.0);
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 25.0 * (next_item_size as f64 / 100.0);
        }
        // Never open a new bin when a near-perfect fit exists elsewhere.
        if fill_ratio > 0.85 && bin_residual != bin_capacity {
            score += 1000.0;
        }
    } else {
        // Lookahead synergy: reward leaving space exactly usable by next item.
        if next_item_size > 0 {
            if post_residual as i64 - next_item_size as i64 == 0 {
                score -= 40.0;
            } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
                score += 20.0; // would create dead space for next item
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits here afterwards: mild reward proportional to closeness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 - slack.min(50.0);
    } else if next_item_size > 0 {
        // Next item won't fit in the leftover: penalize dead space.
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.5;
    }

    // Reward near-perfect fills relative to capacity.
    if post_residual <= 5 {
        score -= 200.0;
    }

    // Compare residual against mean residual of open bins: prefer using
    // bins with larger residuals (keep tight bins tight).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when many bins could fit the item.
    if bin_residual == bin_capacity {
        let bias = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            40.0
        } else {
            0.0
        };
        score += 30.0 + (open_bins_count as f64) * 2.0 + bias;
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual as f64;

    // Dynamic time horizon: 0.0 at stream start, 1.0 at stream end.
    let progress = if total_items > 1 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    // Brand-new empty bin candidate (per interface contract).
    let is_new = bin_residual == bin_capacity;

    // Primary term: tightest fit (minimize leftover after placement).
    let mut score = post;

    // Global-state coupling: prefer the fullest bins (residual below the mean
    // across open bins); this consolidates packing into nearly-full bins.
    score += 0.15 * (mean_residual - resid);

    // Tiny dead-space penalty: leftovers that are probably unusable.
    // Weight grows with progress (late in the stream there is less chance
    // for a future item to fill a sliver).
    if post > 0.0 && post < 12.0 {
        score += (12.0 - post) * (0.8 + 2.2 * progress);
    }

    // Lookahead coupling (k=2): reward bins where the next item can follow,
    // with extra reward for a snug two-item chain; penalize bins whose
    // leftover cannot host the next item, softened if the mean residual
    // suggests some other bin can host it.
    if nxt > 0.0 {
        if post >= nxt {
            let snug = 1.0 - (post - nxt) / cap;
            score -= 1.2 * nxt * snug;
        } else {
            let alt = if mean_residual >= nxt { 0.55 } else { 1.0 };
            score += (nxt - post) * (1.4 + 1.4 * progress) * alt;
        }
    }

    // Last-chance discount: if this is the only open bin that fits the item,
    // strongly favor using it over opening a new bin.
    if !is_new && fitting_bins_count == 1 {
        score -= 60.0;
    }

    if is_new {
        // Regulate new-bin opening: penalize when open bins already offer
        // space (high mean residual, several fitting bins), late in the
        // stream, or when many bins are already open (fragmentation).
        score += 12.0
            + 0.3 * mean_residual
            + 2.0 * fitting_bins_count as f64
            + 10.0 * progress
            + 0.5 * open_bins_count as f64;
    } else {
        // Mild growing reward for consolidating into existing capacity
        // as the stream matures.
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear emphasis.
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: later in the stream,
    // waste is penalized more strongly (less time to recover).
    let progress_coupling = norm_pr * (0.5 + 1.5 * progress * progress);
    score += 40.0 * progress_coupling;

    // Penalize dead space that cannot fit a typical future item: smooth
    // interaction between post_residual and mean residual.
    let mr = mean_residual / cap;
    score += 10.0 * norm_pr * mr;

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_gap = (pr - n).abs();
        let kernel = (-fit_gap * fit_gap / (2.0 * cap * cap * 0.02)).exp();
        score -= 15.0 * kernel;
        // Penalize if next item cannot fit here either (wasted pairing).
        if n > pr {
            score += 5.0 * (n - pr) as f64 / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for proliferating bins relative to stream length.
    score += open_bins_count as f64 * 0.05 * (0.5 + progress);

    // New-bin candidate: neutral-ish baseline; open a new bin only when
    // existing bins would create large waste.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 2.0 * norm_pr * norm_pr) + 40.0 * (0.5 + 1.5 * progress * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: leftovers divisible by common item sizes
    // (10, 20, 25, 50) are more reusable, reward them.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 50 == 0 { bonus += 6.0; }
        else if pr % 25 == 0 { bonus += 4.0; }
        else if pr % 10 == 0 { bonus += 3.0; }
        else if pr % 20 == 0 { bonus += 3.0; }
        score -= bonus;

        // Dead-space penalty for tiny unusable leftovers relative to min item size 1..100:
        // leftover smaller than half of next item is likely waste.
        if next_item_size > 0 && (pr as u64) < (next_item_size as u64) {
            score += 4.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr < 2 * next_item_size {
            // perfect pairing: leftover exactly matches next item
            if pr == next_item_size { score -= 8.0; }
        }
    } else {
        // perfect fill
        score -= 20.0;
    }

    // Fit tightness: reward small post_residual fraction of capacity
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 5.0 * tight;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: neutral-ish baseline; prefer it only when item is huge
    // relative to typical open-bin residuals or many bins are open.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / cap.max(1.0));
        let big_item = (item_size as f64) / cap;
        score = 0.55 * cap + 10.0 * big_item - 3.0 * pressure.min(3.0);
        // if the item is huge, new bin is attractive
        if item_size >= 70 { score -= 15.0; }
    }

    // Late in stream: consolidate, penalize opening bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity { score += 10.0 * progress; }
    else { score -= 2.0 * progress; }

    // Slight preference for bins with residual above mean (balance residuals)
    if bin_residual != bin_capacity {
        score += 0.05 * ((bin_residual as f64) - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are waste.
    let dead_threshold = 9u32;
    if post_residual < dead_threshold && post_residual > 0 {
        // Unusable sliver: heavily penalize proportional to how "wasted" it is.
        score += 40.0 * (1.0 - (post_residual as f64) / dead_threshold as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward leaving room for the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap that fails the lookahead: mild penalty scaled by near-miss.
        let miss = (next_item_size - post_residual) as f64;
        score += 4.0 * (miss / 100.0);
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins when fit is mediocre.
    score += (open_bins_count as f64) * (post_residual as f64) / 200.0;

    // Prefer bins tighter than average (best-fit flavor).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(30.0) * 0.2;
    }

    // New-bin candidate: only attractive when current item is large / fits are poor.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) > 0.6 * (bin_capacity as f64);
        let poor_fits = fitting_bins_count <= 1;
        if large_item || poor_fits {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual >= next_item_size {
            // Next item can chain into this bin: reward tight match
            score -= 300.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize
            score += 60.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when a decent fit exists among open bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = post_residual as f64; // = full capacity for new bin
        // New bin is attractive only if no open bin fits or fits poorly
        let best_alternative_penalty = if fitting_bins_count == 0 { -400.0 } else { 0.0 };
        score = waste + 500.0 - 450.0 * progress + best_alternative_penalty;
        // Slight attraction to new bin if mean residual is very low (all open bins nearly full)
        if mean_residual < 15.0 && fitting_bins_count > 0 {
            score -= 120.0;
        }
    } else {
        // Prefer bins tighter than the mean residual (best-fit flavor)
        score -= 2.0 * (mean_residual - bin_residual as f64);
        // Small reward for keeping many open bins utilized
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that is too small for the next item (unusable gap)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward gaps that exactly fit the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins tighter than average residual (best-fit flavor)
    score += (mean_residual - post) * 0.3;

    // New-bin candidate handling: opening a new bin is generally penalized,
    // but becomes attractive when no open bin fits well (large item, tight state)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        let mut open_cost = 20.0 + 30.0 * (1.0 - item_frac);
        // late in the stream, avoid opening bins for small items
        open_cost += 15.0 * progress;
        // if few fitting bins and item is large, opening is less bad
        if fitting_bins_count <= 1 {
            open_cost -= 18.0;
        }
        // if mean residual across open bins is large, we should use open bins instead
        open_cost += mean_residual * 0.15;
        score = open_cost + post;
    }

    // Mild penalty for very small unusable leftovers that fit nothing typical
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: tight fits are increasingly valuable as stream progresses
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize dead space that can't fit a typical future item (non-linear in post_residual)
    let dead = norm_pr * (1.0 - norm_pr);
    score += 10.0 * dead * dead * 4.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits into resulting residual (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let fit_quality = 1.0 - ((pr - nx) / cap).abs();
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // penalize residuals just barely too small for the next item
            let miss = (nx - pr) / cap;
            score += 6.0 * miss * (1.0 - progress);
        }
    }

    // New-bin candidate handling: mildly penalize opening a new bin early,
    // but allow it late when fits are poor
    if bin_residual == bin_capacity {
        let fit_pressure = 1.0 / (fitting_bins_count.max(1) as f64);
        let tightness = (mean_residual / cap).abs();
        score += 20.0 * (1.0 - progress) * (1.0 - progress)
               + 8.0 * fit_pressure
               - 10.0 * tightness * progress;
    }

    // Mild preference for bins deviating from mean residual (balance avoidance of fragmentation)
    score += 2.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Small non-linear item-size regularization: big items want tightest fits
    score += 3.0 * norm_item * norm_item * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that no item (>=1) can reuse well
    // Items are 1..100; small residuals are only useful for tiny items.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 30.0; // tiny dead space, nearly unusable
    } else if pr < 20 {
        score += 12.0;
    }

    // Modulo-class coupling: residual divisible into common item sizes is reusable
    if pr > 0 {
        let mut reusable = 0;
        for d in [10u32, 20, 25, 50, 100].iter() {
            if pr % d == 0 { reusable += 1; }
        }
        score -= 8.0 * reusable as f64;
    }

    // Lookahead: does post_residual fit the next item?
    if next_item_size > 0 && pr >= next_item_size {
        score -= 25.0;
        // exact harmonic match with next item
        if pr == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize more if residual is dead-ish
        score += (20 - pr.min(20)) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 45.0;
        // cheaper to open new bin late in stream when many bins already open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * progress;
        // if current bin would leave awkward residual vs next item, new bin is fine
        if next_item_size > 0 && pr > 0 && pr < next_item_size {
            score -= 20.0;
        }
    }

    // Prefer tighter fits generally: reward small post_residual relative to item
    score -= (item_size as f64) * 0.3;

    // Slight preference for bins below mean residual (consolidating space)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward very tight fits (post_residual tiny relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.6 + 0.8 * progress);

    // If next item would fit into the post_residual, reward leaving useful space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post_residual too small for next item: penalize proportionally.
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // New-bin candidate: neutral baseline, slightly above good fits,
    // but attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 0.3 - mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, strongly reward this bin.
    if next_item_size > 0 {
        let post = post_residual as u32;
        if post == next_item_size {
            score -= 30.0;
        } else if post > next_item_size {
            // Next item fits but leaves a second residual; penalize by the
            // leftover after that hypothetical placement (cascading dead space).
            let second_residual = post - next_item_size;
            score += second_residual as f64 * 0.4;
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            let gap = next_item_size - post;
            score += gap as f64 * 0.3;
        }
    }

    // Relative-to-mean-residual coupling: bins tighter than the mean are
    // better candidates to fill now.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins can fit, unless the
    // item is large (poor fit everywhere justifies a fresh bin).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 10.0 * tightness;
    }

    // Late-stream pressure: near the end, prefer compacting into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Small exact-fit reward for the current item itself.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that
    // cannot fit the typical next item is wasted. Penalize residuals that
    // are nonzero but tiny (unusable slivers) less than perfect fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover still usable by next item: mild bonus proportional to fit tightness
            let chain_waste = (post_residual - next_item_size) as f64;
            score += 0.35 * chain_waste;
            score -= 6.0;
        } else {
            // leftover unusable by next item: penalize dead space more as stream matures
            score += (1.0 + 1.5 * t) * post_residual as f64 * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current bin would leave a large unusable remainder relative to
    // what a fresh bin offers, or when the item is huge (>= 2/3 capacity).
    if bin_residual == bin_capacity {
        let huge = (item_size as f64) >= (2.0 * bin_capacity as f64 / 3.0);
        let poor_fit_elsewhere = mean_residual > 0.0
            && (mean_residual - item_size as f64) < 0.35 * bin_capacity as f64;
        if huge || (poor_fit_elsewhere && open_bins_count > 2) {
            score -= 8.0;
        } else {
            // default: discourage proliferation of open bins
            score += 10.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Slight preference for filling bins with lower-than-mean residual
    // (concentrate waste in few bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.25 * dev;
    }

    // Encourage compactness of open bin set over time (avoid drift).
    score += 0.02 * open_bins_count as f64 * (0.5 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    // Smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    score += prn * prn * (1.0 - progress) * 8.0;
    score -= prn * progress * 4.0;
    // Penalize dead space near capacity more strongly as stream advances
    score += (prn - 0.5) * (prn - 0.5) * (0.5 + progress) * 6.0;
    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }
    // New-bin candidate: penalize mildly unless residuals are tight
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.2;
    }
    // Lookahead fit reward
    if next_item_size > 0 && (post_residual as u64) < next_item_size as u64 {
        score += 3.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 2.0;
    }
    // Open-bin pressure
    score += open_bins_count as f64 * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it cannot
    // plausibly fit future items. Classify residual by integer division bands.
    let pr = post_residual;
    let class = pr / 10; // coarse harmonic class 0..=10
    // Penalize residuals that fall into "awkward" bands (small but nonzero)
    if pr > 0 {
        score += match class {
            0 => 6.0,           // 1..9: nearly dead space
            1 => 4.0,           // 10..19: awkward
            2 => 2.5,           // 20..29
            3 => 1.0,           // 30..39
            4 => 0.3,
            5 => 0.0,           // ~50: most reusable
            6 => 0.2,
            7 => 0.8,
            8 => 1.5,
            9 => 2.2,
            _ => 0.0,           // near-full bin, fine
        };
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 8.0 - (slack as f64).min(20.0) * 0.15;
        } else {
            // next item cannot fit here: mild penalty proportional to gap
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.1;
        }
        // Modular resonance: next item divides residual cleanly
        if next_item_size > 0 && pr % next_item_size.max(1) == 0 && pr >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate bias: empty bin gets a baseline penalty so we prefer
    // reusing open bins unless the fit is poor; relax late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 14.0 - 6.0 * progress;
        // open new bin if mean residual of open bins is very small anyway
        if mean_residual < 15.0 {
            score -= 8.0;
        }
    }

    // Prefer filling bins that are already relatively full (tight packing)
    let fill_frac = 1.0 - (bin_residual as f64) / cap_f;
    score -= fill_frac * 4.0;

    // Slight preference for bins below mean residual (balance avoidance of
    // many half-empty bins) — reward placing into below-average bins mildly
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score += (res_f - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the minimum plausible item (size 1..=100 stream, but typical items are
    // mid-sized) are pure waste. Penalize small gaps super-linearly.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty growing as the gap shrinks.
            score += (10 - post_residual) as f64 * 12.0;
        } else if post_residual < 25 {
            // Small gap: likely dead space unless future small items arrive.
            score += (25 - post_residual) as f64 * 4.0;
        } else if post_residual <= 30 {
            // "Sweet spot": gap that a typical mid-size item could still fill.
            score -= 15.0;
        }
    } else {
        // Perfect fill: strongly reward closing a bin exactly.
        score -= 60.0;
    }

    // Tight fit reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance pressure: if this is the only bin that fits, prefer it
    // strongly over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new
    // bins; with few open bins, opening a fresh bin is cheaper.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 25.0 + open_pressure * 3.0;
        // If next item is small, a fresh bin can absorb it well.
        if next_item_size > 0 && (next_item_size as f64) >= (bin_capacity as f64 * 0.5) {
            score += 20.0; // big next item makes a fresh bin less attractive
        }
    } else {
        // Existing bin: mild reward for keeping bin count low.
        score -= open_pressure * 1.5;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            // Next item would leave a sliver: discourage.
            score += 10.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "cramped" — prefer filling it rather than leaving it.
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.5;

    // Late in the stream, avoid opening new bins even more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-chain match: post_residual exactly fits next item -> strong reward.
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // Next item still fits: partial reward proportional to closeness.
            score -= 10.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space that next item cannot use: penalize small leftovers harder.
            score += 8.0 * (1.0 - diff / 50.0).max(0.0);
        }
    } else {
        // Last item: prefer tightest fit.
        score += 5.0;
    }

    // Compare against mean residual: favor bins tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when plenty of bins fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by open bins that fit.
        score += 20.0 + 3.0 * fitting_bins_count as f64;
        // If next item is large and post_residual (full capacity) can host it, new bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in the stream, tighten packing (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Discourage leaving residuals below the smallest plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;

    let mut score = post;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item / resid.max(1.0);
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for the smallest possible item are wasted.
    if post_residual < 10 {
        score += 40.0 * (10 - post_residual as i32) as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item could exactly use the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() < 1.0 {
            score -= 50.0;
        } else if nxt <= post {
            // next item fits in leftover: mild reward proportional to leftover usage
            score -= 15.0 * (nxt / post.max(1.0));
        } else {
            // next item won't fit here: penalize leaving medium dead space
            score += 10.0 * (post / cap);
        }
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, just pack anywhere that fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * fit_ratio;

    // Global state coupling: many open bins with high mean residual -> encourage
    // consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaling with open bin count
        // and mean residual (opening bins when slack exists elsewhere is bad).
        score += 30.0 + 4.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // But if the item is huge and mean residual is low, a new bin is reasonable.
        score -= 25.0 * (item / cap) * (1.0 - (mean_residual / cap).min(1.0));
    } else {
        // Slight preference for bins with residual close to mean (balanced packing).
        score += 0.05 * (resid - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = fitting_bins_count as f64;

    // Base: prefer small post-residual (tight fit), with mild non-linear penalty
    let mut score = post + 0.02 * post * post / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger leftovers; late in stream, penalize them harder.
    let w = 0.5 + 0.5 * progress;
    score += w * (post / cap) * (1.0 - post / cap) * 30.0;

    // Reward scarce fitting options (last-chance bins)
    if fitting_bins_count > 0 {
        score -= 8.0 / fit;
    }

    // Penalize when this bin is an outlier vs mean residual (smooth quadratic)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.01 * dev * dev / cap;

    // Lookahead: bonus if next item fits the post-residual
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 3.0;
    }

    // Mild penalty for opening new bins when many are open (smooth in open count)
    let openness = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 2.0 * openness * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "dead"
    // residue classes (small unusable slivers) are penalized.
    let dead = post_residual % 10; // sliver class 1..9
    if post_residual > 0 && dead < 3 {
        score += 12.0; // unusable tiny dead space
    } else if dead == 0 {
        score -= 6.0; // perfectly divisible leftover, reusable
    }

    // Encourage exact fills
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this leftover; penalize proportional to wasted space
        score += 0.05 * post_residual as f64;
    }

    // Integer-division thresholds: leftover >= half capacity is valuable
    if post_residual >= bin_capacity / 2 {
        score -= 5.0;
    } else if post_residual <= bin_capacity / 10 {
        score += 4.0;
    }

    // Last-chance bin before opening a new one: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 10.0; // big item coming, fresh bin useful
        }
    }

    // Late in stream, prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harshly (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual > 60 {
        score += 8.0; // wasteful large leftover
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin bonus: avoid opening new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open bin pressure: with many open bins, prefer packing into existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 - mean_residual / 10.0) * (0.3 + 0.5 * progress);

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 && (post_residual as u32) < next_item_size {
        score += 10.0; // blocks next item
    }

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 5.0;
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space quadratically: small post_residuals are good.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // 2-step lookahead: strongly reward exact chain fits (post_residual == next_item_size).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 100.0; // perfect chain
        } else if post_residual >= next_item_size {
            // reward tight-but-feasible follow-up fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // penalize residual that can't host the next item (likely dead space)
            score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer bins tighter than the mean residual (better fits).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Early in the stream, allow new bins more freely; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 10.0 + 60.0 * progress;
        // but if no open bin fits well (post_residual huge), opening may be better
        if post_residual as f64 > bin_capacity as f64 * 0.5 {
            score -= 20.0;
        }
    }

    // Slight consolidation pressure: favor bins with fewer siblings? No — favor filling existing bins.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: penalize leaving residual that is slightly larger than next item (wasted opportunity),
    // reward residual that exactly accommodates the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= ni {
            let slack = pr - ni;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 {
                score -= 8.0; // perfect pairing
            }
        } else {
            // next item cannot fit here: mild penalty proportional to gap
            score += 2.0 * (ni - pr) / ni.max(1.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins with least post residual anyway
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: make empty bin attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        let early = step_index as f64 / (total_items.max(1) as f64);
        // penalize new bins early, but allow them when mean residual is low (poor fits elsewhere)
        score += 20.0 * (1.0 - early) - 14.0 * fragmentation;
        if post_residual >= 60 {
            score -= 5.0; // a fresh bin keeps large usable residual
        }
    }

    // Penalize creating dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mild preference for bins below mean residual (consolidating waste)
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff;

    // Late-stream consolidation: fewer open bins preferred toward the end
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // base: prefer small post_residual, with polynomial shaping
    let mut score = pr * (1.0 + 0.5 * fill * fill);

    // smooth non-linear coupling of post_residual with stream progress
    let t = progress * std::f64::consts::PI;
    score += pr * (0.6 * t.sin() * t.cos()) * (1.0 - fit_ratio);

    // dead-space penalty: quadratic in tiny residuals
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (10.0 - pr) * 0.15;
    }

    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - (pr - nxt) / cap).abs();
        } else {
            score += 4.0;
        }
    }

    // last-chance bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * fill;
    }

    // mild preference for consolidating into fewer bins as stream progresses
    score -= 2.0 * (open_bins_count as f64 / (mean_residual / cap + 1.0)) * progress * 0.1;

    // new-bin candidate: penalize slightly unless current bin would waste a lot
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * (1.0 - fit_ratio).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "dead zones"
    // (too small for typical items) should be penalized.
    let dead_low: u32 = 10;               // smallest item size
    let dead_high: u32 = 30;              // below this, leftover is nearly unusable
    if post_residual < dead_low {
        score += 40.0;                    // perfect fit bonus region -> strongly reward
    } else if post_residual < dead_high {
        // penalize dead space quadratically
        let d = (dead_high - post_residual) as f64;
        score += 0.9 * d * d / 10.0;
    }

    // Modulo-10 harmonic classes: leftovers that are multiples of 10 pair well
    // with the integer item grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Integer-division threshold: can the bin also host the lookahead item?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // harmonic coupling: if post_residual - next_item is again in a good class
        let after_next = post_residual - next_item_size;
        if after_next % 10 == 0 {
            score -= 5.0;
        }
        if after_next < dead_low && after_next > 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // lookahead cannot follow into this bin
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fit is terrible.
    if bin_residual == bin_capacity {
        score = 60.0 + post_residual as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 70.0; // no alternative: new bin is fine
        }
        if fitting_bins_count == 1 {
            score += 30.0; // discourage abandoning a last-chance bin
        }
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Many open bins: reward filling existing ones to curb bin proliferation.
    score -= (open_bins_count.min(20) as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Mid-range dead space (10..25) is mildly penalized.
    else if post_residual >= 10 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Open-bins pressure: discourage opening new bins when many are open,
    // but allow it when few bins exist (early stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and progress.
        score += 25.0 + open_bins_count as f64 * 6.0 + progress * 20.0;
        // If no open bin fits, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Lookahead: if next item is large, opening fresh bin is risky.
        if next_item_size > bin_capacity as u32 / 2 {
            score += 15.0;
        }
    } else {
        // Reward using an existing bin, especially when it's the last fitting one.
        if fitting_bins_count == 1 {
            score -= 45.0;
        }
        // Favor bins tighter than average (best-fit flavor).
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.5;

        // Lookahead synergy: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 40.0;
        }
        // Penalize leaving a gap just above next item size (awkward residue).
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = if bin_capacity == 0 { 1.0 } else { bin_capacity as f64 };
    let item = item_size.min(bin_capacity) as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mean = if mean_residual.is_finite() { mean_residual.max(0.0) } else { 0.0 };
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let open_bins = open_bins_count as f64;
    let is_new = bin_residual == bin_capacity;
    let new_post = (cap - item).max(0.0);
    let new_can_pair = next > 0.0 && new_post >= next;
    let open_can_pair = next > 0.0 && post >= next;
    let last_chance = !is_new && fitting_bins_count == 1;
    let alt_fit_exists = fitting_bins_count > 0;

    let next_pressure = if next > 0.0 {
        (((next - mean) / next).max(0.0)).min(1.0)
    } else {
        0.0
    };
    let mean_coverage = 1.0 - next_pressure;

    let mut score = post;
    score += 2.0 * (post / cap);
    score += 1.25 * (((post - mean) / cap).clamp(-1.0, 1.0));

    if next > 0.0 {
        if post == 0.0 {
            score -= 16.0 + 8.0 * (1.0 - progress) + 2.0 * (item / cap);
        } else if open_can_pair {
            let after_next = post - next;
            let match_span = (cap - next).max(1.0);
            let match_quality = 1.0 - (after_next / match_span).clamp(0.0, 1.0);

            score -= 5.0 + 9.0 * (next / cap) + 10.0 * match_quality;

            if after_next == 0.0 {
                score -= 10.0 + 8.0 * (1.0 - progress);
            }
        } else {
            let gap = (next - post).max(0.0);
            let mut dead_space = 5.0
                + 12.0 * (gap / cap).clamp(0.0, 1.0)
                + 5.0 * (1.0 - post / cap);

            dead_space *= 0.45 + 0.55 * next_pressure;
            score += dead_space;
            score += 1.5 * (((mean - post) / cap).clamp(0.0, 1.0));
        }
    } else if post == 0.0 {
        score -= 15.0 + 6.0 * (1.0 - progress);
    }

    if is_new {
        if !alt_fit_exists {
            let necessary_bonus = 8.0 + 4.0 * (1.0 - progress) + if new_can_pair { 4.0 } else { 0.0 };
            score -= necessary_bonus;
        } else {
            let mut new_penalty = 10.0
                + 5.0 * (1.0 - progress)
                + 0.3 * open_bins.min(20.0);

            if new_can_pair {
                let after_next = new_post - next;
                new_penalty += 2.0 + 5.0 * (after_next / cap).clamp(0.0, 1.0);

                if after_next == 0.0 {
                    new_penalty -= 3.0;
                }

                let many_alternatives = if fitting_bins_count > 1 { 1.0 } else { 0.25 };
                new_penalty += 20.0 * mean_coverage * many_alternatives;
            } else {
                let shortfall = ((next - new_post) / cap).clamp(0.0, 1.0);
                new_penalty += 10.0 + 14.0 * shortfall;
            }

            score += new_penalty;
        }
    }

    if last_chance {
        if next <= 0.0 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if post == 0.0 {
            score -= 12.0 + 6.0 * (1.0 - progress);
        } else if open_can_pair {
            score -= 10.0 + 6.0 * (1.0 - progress) + 4.0 * (next / cap);
        } else if !new_can_pair {
            score -= 12.0 + 6.0 * (1.0 - progress);
        } else {
            let consolidation = ((item - post) / cap).clamp(0.0, 1.0);
            score += 7.0 * consolidation * (0.3 + 0.7 * next_pressure);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Penalize large dead space non-linearly (waste grows faster than linear).
    let waste = post_residual as f64 / cap;
    score += 30.0 * waste * waste;

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= 8.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin should be penalized unless
    // the resulting residual is very large (room for future items) or no open bin fits.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 45.0;
        // Reward large leftover space in the fresh bin (post_residual == item_size gap).
        score -= 0.5 * post_residual as f64;
        // If the next item would fit in the fresh bin's residual, extra reward.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 25.0;
        }
        // Late in the stream, prefer closing out existing bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // Many open bins already: discourage further fragmentation.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Lookahead synergy: if next item exactly fits this bin's post_residual, big reward.
        if next_item_size > 0 && (post_residual as u32) == next_item_size {
            score -= 35.0;
        } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 10.0;
        }
        // Prefer placing into bins whose residual is below the mean (consolidate small holes).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Early stream: slightly favor filling existing bins to keep bin count low.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (bin_residual < bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling: residual value decays with stream progress
    score -= 8.0 * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Penalize tiny dead space that wastes the bin, smoothly
    score += 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 4.0 + 6.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_quality = (pr - nx) / cap;
            score -= 5.0 * (1.0 - fit_quality) * (1.0 - progress);
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Prefer filling crowded bins when many are open
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: smooth quadratic penalty
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, but with harmonic class weighting.
    // Residual classes: small residuals (<20) are near-dead space -> penalize moderately,
    // mid residuals (20..50) are useful -> reward, large residuals -> near-new-bin.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr < 10 {
        score -= 30.0; // near-perfect
    } else if pr <= 20 {
        score -= 15.0;
    } else if pr <= 50 {
        score -= 25.0; // sweet zone: leaves room for typical mid items
    } else {
        // large leftover: mild penalty relative to just opening a new bin
        score += 5.0;
    }

    // Harmonic class: modulo 10 classes of post_residual.
    // Residuals in {0, 25, 50, 75, 100}-like harmony are more reusable.
    let class = pr % 10;
    let class_bonus: f64 = match class {
        0 => 8.0,
        5 => 6.0,
        2 | 8 => 3.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: slight penalty for leaving large unusable gap
            if pr > 0 && pr < next_item_size {
                score += (pr as f64).min(30.0) * 0.2;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score,
    // so it only wins when open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score = 70.0
            - if fitting_bins_count == 0 { 15.0 } else { 0.0 }
            - (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Stream progression: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    // Many open bins: discourage spreading; prefer filling existing bins tighter.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: when mean residual is low, protect remaining capacity.
    if mean_residual < 25.0 {
        score += (pr as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1) are
    // not dead per se, but gaps too small for the *next* item or typical small
    // items (<=10) are wasted. Penalize unusable small gaps super-linearly.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 25.0;
    }
    // Zero residual is perfect packing: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward exact-ish fits relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = (post_residual - next_item_size) as f64;
        score -= 20.0 - lookahead_waste * 0.3;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // leftover cannot host next item: mild penalty scaled by gap smallness
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones rather than spreading; penalize new-bin candidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are congested
        // (mean residual too small) or nothing sensible fits.
        score += 45.0 + open_bins_count as f64 * -1.5 + mean_residual * 0.4 - progress * 10.0;
    } else {
        score += open_bins_count as f64 * 0.3;
        // Prefer bins below mean residual (filling emptier bins evens load).
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            // next item can still fit here; mild reward proportional to how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit in residual: penalize large dead space relative to next item
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize large post_residual (dead space), nonlinearly
    score += 0.15 * (post_residual as f64).powf(1.3);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Small penalty for opening a new bin when many bins already open
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Late-stream bias: tighter packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual) — classic best-fit.
    // Reward near-perfect fits superlinearly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score += (post_residual as f64 / bin_capacity as f64).powi(3) * 50.0;
    }

    // Lookahead: if the next item can still fit into the leftover space,
    // this bin remains valuable; discount its residual cost.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (post_residual as f64 - next_item_size as f64) * 0.3;
    } else if next_item_size > 0 {
        // Leftover can't host next item: penalize dead space proportionally
        // to how much of the capacity becomes unusable.
        score += post_residual as f64 * 0.4;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has zero waste but opening
    // bins is costly when few items remain or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_item = item_size.max(1) as f64;
        // Expected number of future items roughly proportional to remaining stream.
        let remaining = (total_items - step_index.min(total_items)) as f64;
        // Opening a new bin is attractive if the item fits poorly everywhere
        // (high post_residual elsewhere) — approximated via mean residual.
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 1.2;
        if poor_fit_elsewhere && next_item_size > 0 && post_residual >= next_item_size {
            // Fresh bin can serve the next item too: encourage.
            score -= 10.0 + remaining * 0.05;
        } else if poor_fit_elsewhere {
            score -= 5.0;
        } else {
            // Don't abandon open bins with usable space.
            score += 25.0 + mean_residual * 0.2 + open_bins_count as f64 * 2.0 - progress * 10.0;
        }
        let _ = avg_item;
    }

    // Mild preference for bins below mean residual (consolidating fuller bins),
    // keeps the pool of open bins tight.
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 12.0 * norm_pr * norm_pr * (1.0 + p2) - 6.0 * norm_pr * (0.5 + p3);

    // Penalize waste relative to mean residual across open bins
    score += 0.35 * (pr - mean_residual) * (1.0 + progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Last-chance bonus: only one bin fits, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + 2.0 * progress);
    }

    // Lookahead: reward leaving space usable by the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 5.0 * (1.0 - (ni / cap)) * (0.5 + progress);
        } else {
            score += 4.0 * (ni / cap) * (1.0 - progress);
        }
    }

    // Mild penalty for proliferation of open bins late in the stream
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: neutral baseline with slight late-stream penalty
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // integer division into capacity fractions (dead-space severity bands).
    let frac = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        // Perfect fill: strongly reward.
        score -= 1000.0;
    } else if post_residual <= 10 {
        // Near-perfect fill: large reward.
        score -= 300.0 + (10 - post_residual) as f64 * 10.0;
    } else if post_residual <= 25 {
        // Small leftover: moderate reward, finer via modulo classes.
        let m = post_residual % 5;
        score -= 100.0 - m as f64 * 5.0;
    } else if post_residual <= 50 {
        // Medium leftover: penalize, worse for odd/harmonic misalignment.
        let m = post_residual % 10;
        score += (post_residual % 25) as f64 * 1.5 + m as f64;
    } else {
        // Large leftover: heavy penalty (wasteful placement).
        score += 150.0 + (post_residual - 50) as f64 * 2.0;
    }

    // Reward tight fit relative to item size (post_residual small vs item).
    score -= (item_size as f64) * (10.0 / (post_residual as f64 + 1.0)).min(20.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that keep residual in a reusable class.
        score += (fitting_bins_count as f64).ln() * 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            // Harmonic check: does the pair leave a class-0 (tiny) residual?
            if rem <= 10 {
                score -= 150.0;
            } else {
                score -= 60.0 - (rem as f64 / 10.0).min(6.0) * 5.0;
            }
        } else {
            // Next item cannot use this bin's leftover; slight penalty for
            // stranding space that matches next item's size class.
            let class_gap = (next_item_size - post_residual) % 20;
            score += 10.0 + class_gap as f64 * 0.5;
        }
    }

    // Stream progression: early on, tolerate loose fits to build flexible bins;
    // late, push for tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 50.0 * (1.0 - progress);
    score -= frac * 30.0 * progress;

    // Mean residual coupling: prefer bins near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Many open bins: discourage spreading, prefer filling existing ones.
    if open_bins_count > 4 {
        score += open_bins_count as f64 * 0.5;
    }

    // New-bin candidate: only attractive when current bin would leave a bad
    // large residual or item is huge relative to residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // But if placing into any open bin would strand > 50, new bin wins.
        if post_residual < bin_residual && item_size >= 60 {
            score -= 100.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=12) are strongly penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 15.0;
    }
    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item would fit exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 12 {
            score -= 10.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Post residual too small for next item: mild penalty.
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins with residuals near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: only attractive when existing bins would leave large dead space
    // or no bin fits well.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 - item_size as f64;
        score = base + 5.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && base >= next_item_size as f64 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item (perfect 2-step chain)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // partial reward proportional to how close the leftover is to next item
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // dead space smaller than next item: penalize proportionally to wasted fraction
            let waste = post_residual as f64 / next_item_size as f64;
            score += 12.0 * (1.0 - waste);
        }
    }

    // Penalize tiny unusable residuals (likely dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare residual against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight preference to fill existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for accumulating too many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Bonus if next item exactly consumes post_residual (perfect chain).
        if post_residual == next_item_size {
            score -= 6.0;
        }
    }

    // New-bin candidate handling: opening a bin is attractive when current bins
    // fit poorly or the stream is early (long horizon amortizes the bin).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Early stream: opening bins is cheap; late stream: prefer filling existing.
        let new_bin_bias = 20.0 * (1.0 - progress) - 10.0 * progress;
        score += new_bin_bias;
        // If many bins are open and mean residual is large, discourage new bins.
        score += 0.3 * open_bins_count as f64 + 0.2 * mean_residual;
    }

    // Prefer bins whose residual deviates favorably from the mean residual:
    // placing into a below-average-residual bin consolidates space.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 10.0 * dev;

    // Slight preference for larger items filling larger residuals early on.
    score -= 0.05 * (item_size as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth non-linear coupling: normalized post residual and its square
    let x = pr / cap;
    let x2 = x * x;

    // Base: penalize small unusable post residuals (dead space) quadratically
    score += 12.0 * x2 - 8.0 * x;

    // Polynomial coupling with stream progress: late in stream, prefer tight fits more strongly
    let coupling = (1.0 - progress) * (x2 - 0.5 * x) + progress * (2.0 * x2 - 1.5 * x);
    score += 10.0 * coupling;

    // Exact fit bonus (smooth exponential rather than hard threshold)
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: penalize mildly so we reuse bins unless fit is terrible
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 3.0;
    } else if next_item_size > 0 {
        score += 1.5 * (next_item_size as f64 - pr) / cap;
    }

    // Mean residual deviation: prefer bins close to mean (balanced packing)
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // Slight penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 and mod 25
    let pr = post_residual;
    let residue10 = (pr % 10) as f64;
    let residue25 = (pr % 25) as f64;
    score += 0.35 * residue10 + 0.2 * residue25;

    // Integer-division thresholds on post_residual (harmonic bands of capacity)
    let band = pr / 25; // 0..4 harmonic band
    score += match band {
        0 => 6.0,   // tiny dead space: nearly unusable
        1 => 2.0,   // small sliver
        2 => 0.0,   // mid band, fine
        3 => -1.5,  // roomy remainder, good
        _ => -2.5,  // nearly empty bin
    };

    // Exact-fit reward: post_residual is a "harmonic" divisor-compatible value
    if pr == 0 { score -= 40.0; }
    if pr % 10 == 0 && pr > 0 { score -= 3.0; }

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 && next_item_size <= pr {
        // reward if next item's class matches the residual class
        if pr % next_item_size == 0 { score -= 8.0; }
        else if (pr - next_item_size) % 10 == 0 { score -= 4.0; }
        else { score -= 1.5; }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize blocking residual that is too small
        score += 2.0 + 0.05 * (next_item_size - pr) as f64;
    }

    // Last-chance bin bonus: avoid opening a new bin when only this bin fits
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral baseline, slightly penalized unless
    // current residuals are all tight (mean residual small)
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap;
        score = 30.0 + 25.0 * tight - (open_bins_count as f64).min(10.0);
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 8.0; // big next item: fresh bin useful
        }
    }

    // Mild progression bias: later in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 1.0 * progress * (cap - post_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it's too small for typical future items (assume min item ~1..10
    // is unknown, so use a soft dead-zone below 15 and a hard dead-zone below 10).
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 3.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // hard dead space: almost nothing fits
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 10.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: only prefer a new bin if this placement would
    // leave a large awkward residual while open bins are few.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // But if item would fill a fresh bin substantially, it's fine.
        score -= tightness * 5.0;
        // If many bins are open, opening another is worse.
        score += open_bins_count as f64 * 2.0;
    }

    // Lookahead: if next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits: mild reward proportional to how well it fits.
        score -= 5.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item does NOT fit in the leftover: penalize dead space more.
        score += 8.0;
    }

    // Progress coupling: late in the stream, prefer consolidation (fill existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    // Mean residual coupling: if this bin is much tighter than average, reward it.
    if mean_residual > 0.0 {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect or near-perfect fills
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // usable next step: reward proportionally to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space creation
            score += 40.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are more "committed"
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when reasonable fits exist
    if bin_residual == bin_capacity {
        score += 150.0;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        // but a new bin is fine if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
    }

    // mild tie-break: prefer bins with larger residual (leave small bins for small items)
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftover space.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that no future item can plausibly use
    // (items >= 10 in the classic regime; use min item guess of 1..100 -> treat <=5 as dead).
    if post_residual > 0 && post_residual < 5 {
        score -= 25.0; // near-perfect fill
    } else if post_residual < item_size {
        score += 3.0; // dead-ish space below min item size
    }

    // Exact-ish fill with lookahead: if next item fits the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // leftover too small for the known next item
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Prefer bins below mean residual (larger residuals) slightly to balance load.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate logic: empty bin should only win when current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.6 * bin_capacity as f64
            || (next_item_size > 0 && post_residual > 0 && post_residual < next_item_size);
        if poor_fit {
            score -= 18.0; // open a fresh bin rather than waste space
        } else {
            score += 30.0; // good fit exists; avoid opening new bins
        }
    }

    // Late in the stream, consolidate: discourage new bins, encourage filling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress * tight;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;

    // Base: penalize wasted residual, weighted non-linearly by stream progress.
    // Early on, small residuals matter less; late, dead space is costly.
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear polynomial coupling of post_residual with progress:
    // a U-shaped penalty on tightness that sharpens as the stream advances.
    let tight = 1.0 - norm_pr;
    score += cap * (tight * tight * tight) * (0.15 + 0.5 * progress);

    // Reward near-perfect fits (small post_residual) super-linearly.
    score -= 12.0 * (-pr * 0.09).exp();

    // Lookahead coupling: if the next item fits the post-residual well,
    // reward this placement smoothly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.0 * (-gap * 0.06).exp() * (0.5 + progress);
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards: mild penalty growing with progress.
        score += 3.0 + 4.0 * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate (bin_residual == bin_capacity): it should only win when
    // no open bin offers a decent fit. Penalize it proportionally to how many
    // bins could fit, and to how much usable space would be left idle.
    if bin_residual == bin_capacity {
        let others = fitting_bins_count as f64;
        score += 10.0 + 4.0 * others + 20.0 * progress * (1.0 - (item / cap));
    }

    // Slight preference for consolidating into bins with larger residuals
    // (fills the emptiest-fitting bins first), damped over time.
    score -= 0.05 * (bin_residual as f64 - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic classes of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter.max(1);
    score -= 12.0 * (1.0 - class as f64 / quarter as f64);

    // Perfect / near-perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Penalize dead space that no plausible item (>=1) can pair with usefully:
    // post_residual in "awkward" integer-division classes
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Harmonic pairing: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            score -= 10.0 * (1.0 - rem2 as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good open bin exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = mean_residual / bin_capacity as f64;
        // Penalize opening new bins while open bins are underutilized
        score += 60.0 + 40.0 * (1.0 - progress) + 30.0 * (1.0 - waste);
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    // Mild preference for fuller bins among candidates
    score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Slight exploration term via modulo of step index on residual classes
    if post_residual % 3 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=12) are almost unusable
    // for future items (min size 1, practically ~10 in original streams),
    // so penalize them heavily with a nonlinear surge.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - pr) / 13.0; // dead-space wall
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit: reward strongly
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: prefer reusing bins when many are open,
    // but allow new bins when few are open (early stream flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, increasingly penalized later.
        score += 8.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // Never open a new bin if the item fits with decent residual elsewhere.
        if post_residual <= 40 {
            score += 25.0;
        }
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // this placement is doubly valuable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item almost fits (within 5), mild penalty for blocking it.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 6.0;
    }

    // Mean-residual coupling: bins far below the mean residual are "wasted"
    // space holders; placing into them balances the pool.
    score -= 0.1 * (mean_residual - bin_residual as f64).abs().min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 2 {
        score -= 120.0;
    }

    // 2-step lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack.min(50.0);
            // Perfect chaining: next item exactly fills the bin.
            if post_residual == next_item_size {
                score -= 150.0;
            }
        } else {
            // Next item won't fit here: penalize leaving dead space that is too small
            // to be useful (post_residual < 10 is nearly unusable).
            if post_residual < 10 {
                score += 80.0;
            } else {
                score += (10.0 - (post_residual as f64 / 10.0)).max(0.0) * 3.0;
            }
        }
    }

    // Compare residual against mean residual: prefer bins that are already
    // relatively full (residual below mean is good).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Penalize opening a new bin when decent fitting bins exist, but allow it
    // when the stream is early and open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
        score += 40.0 + crowded * 5.0 - progress * 20.0;
        // A new bin is attractive if the item leaves a large residual that could
        // host the next item too.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 70.0;
        }
    }

    // Mild waste penalty scaled by item size (large items deserve tighter fits).
    score += (post_residual as f64) * (item_size as f64 / 400.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Penalize dead space that no plausible item can use (items >= 1).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.3) * 0.05;
    }

    // Perfect closure bonus: fill the bin exactly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0 + 0.2 * next_item_size as f64;
        } else if (bin_residual as i64) >= (next_item_size as i64) && post_residual < next_item_size {
            // this placement destroys a bin that could host the next item
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Scarcity pressure: many open bins -> prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 10.0);
    score += open_pressure * 3.0;

    // Mean residual coupling: if this bin's residual is well below mean, it's a good filler.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.15;

    // Time horizon: early in stream, be more conservative about opening new bins
    // (long future to use them); late in stream, prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0 * fit_ratio;
    score -= (1.0 - progress) * 4.0;

    // New-bin candidate: only attractive when current bins are poor fits.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64 * 0.9 - desperation * 40.0 - (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward tight fits via smooth polynomial of post_residual
    let mut score = pr.powf(1.5) / c;

    // Non-linear coupling: tight fits are more valuable later in the stream
    let tightness = 1.0 - pr / c;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize large dead space with cubic term, softened early
    score += (pr / c).powi(3) * (20.0 - 10.0 * progress);

    // Last-chance bonus: strongly reward the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead: prefer bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 4.0 * (nx / c) * (1.0 - progress);
        } else {
            score += 2.0 * (1.0 - (pr / nx).min(1.0));
        }
    }

    // Mild pressure toward consolidation relative to mean residual
    score += 0.05 * (pr - mean_residual) * (1.0 - progress);

    // Slight preference for reusing bins over opening new ones
    if bin_residual < bin_capacity {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (>= next item sizes) are worth keeping tight.
    let next = next_item_size as u32;
    if next > 0 && next <= post_residual {
        // post residual can host the lookahead item -> strong reward,
        // scaled by how snugly the lookahead fits.
        let slack = (post_residual - next) as f64;
        score -= 30.0 - slack.min(30.0);
    } else if next > 0 {
        // lookahead cannot use this leftover: dead-space penalty grows
        // as the leftover shrinks into an unusable harmonic band.
        let r = post_residual as f64;
        if r < 10.0 {
            score += 25.0 * (1.0 - r / 10.0);
        }
    }

    // Integer-division harmonic thresholds on post_residual:
    // leftovers in [1..10] are nearly dead; [10..25] marginal; >=25 flexible.
    let post = post_residual;
    if post == 0 {
        score -= 40.0; // perfect closure: excellent
    } else if post < 10 {
        score += 12.0; // tiny useless remnant
    } else if post < 25 {
        score += 4.0;
    } else if post < 50 {
        score -= 3.0;
    } else {
        score -= 6.0; // large residual: half-empty bin, keep filling
    }

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with residual below mean (tight bins) mildly.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Early stream: tolerate spreading (open bins cheaply) when many items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // Fresh bin baseline: slightly above a perfect fit, below a wasteful one.
        score = cap_f * 0.75 + 15.0 * (1.0 - progress);
        if next > 0 && next <= post {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 25.0; // no alternative
        }
    }

    // Modulo coupling: residual classes congruent to small values mod 20 are
    // awkward for typical item sizes; nudge selection away from them.
    if post % 20 < 5 && post > 0 {
        score += 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit even the smallest item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals that are unusable for the lookahead item (likely dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    if post_residual as f64 <= 0.15 * item_size as f64 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: mildly discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
        // But if no existing bin fits well, new bin is fine (baseline handled above).
    }

    // Progression-aware slack: early in the stream, keep bins flexible; later, pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 * 0.3);

    // Prefer bins below mean residual slightly (balance load, keep big gaps available).
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
