pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post residual, the better.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 30.0;

    // Penalize leaving dead space that likely cannot fit future items.
    if post_residual > 0 && post_residual < item_size.min(80) {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for blocking good chains.
            score += 5.0;
        }
    }

    // Time horizon: early in the stream, be conservative (favor compacting);
    // later, allow opening bins more freely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Global residual pressure: if mean residual across bins is high, prefer
    // filling existing bins; if low, opening a new bin is less costly.
    let mr = mean_residual / bin_capacity as f64;
    score += mr * 10.0;

    // Too many open bins: penalize spreading.
    if open_bins_count > 8 {
        score += (open_bins_count as f64 - 8.0) * 0.5;
    }

    // New-bin candidate: only attractive when no bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 12.0 * pressure + (1.0 - progress) * 8.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pairing room in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: post_residual penalty shaped by progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= 30.0 * norm_item * (1.0 - norm_pr) * (0.5 + progress);

    // Last-chance bonus when few fitting bins
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Penalize opening new bins when many open bins already exist
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64).sqrt() + 20.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that can hold the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr as f64 >= n {
            score -= 6.0 * (1.0 - n / cap);
        } else {
            score += 4.0 * (n - pr) / cap;
        }
    }

    // Mild mean-residual alignment term
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity divided into 5 harmonic bands.
    let item_class = item_size / 20;          // 0..=4
    let next_class = (next_item_size / 20) as i64;

    // Reward placing items into bins whose post-residual belongs to a
    // "harmonic" class that a common small item can still fill exactly.
    // post_residual classes: 0 (dead), 1-9 (awkward), 10-19 (fits small), 20+ (useful).
    if post_residual == 0 {
        score -= 60.0; // perfect closure, strongly favored
    } else if post_residual < 10 {
        score += 25.0; // awkward dead space penalty
    } else if post_residual < 20 {
        score -= 10.0; // fits 10-class items
    } else if post_residual < 40 {
        score -= 18.0; // very reusable band
    }

    // Modulo coupling: residual divisible by 10 aligns with the 10..80 grid.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0; // exact tiling potential
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Class transition bonus: big item into bin, small item follows well.
        if next_class <= 1 && post_residual >= 20 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Prefer new bin late in the stream or when mean residual is tiny.
        score = 45.0 + 30.0 * (1.0 - pressure) - 20.0 * (step_index as f64 / total_items.max(1) as f64);
        if post_residual == bin_capacity {
            // exact-closure check irrelevant for new bin; keep neutral base
        }
    }

    // Mild penalty for proliferating bins when mean residual is large.
    if mean_residual > 40.0 && bin_residual != bin_capacity {
        score += 5.0;
    }

    // Tie-break: prefer fuller bins (smaller residual) via small linear term.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual <= 20 {
        score += 10.0;
    }

    // Reward bins whose residual matches the item closely (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by the resulting dead space, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 15.0;
    }

    // New-bin candidate: make it attractive only when existing bins are poor fits.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual - (post_residual as f64);
        let bad_alternatives = mean_residual < item_size as f64 * 1.2 || fitting_bins_count == 0;
        if bad_alternatives {
            score -= 20.0;
        } else {
            score += 15.0 + avg_waste * 0.1;
        }
    }

    // Mild preference for bins below mean residual (consolidate fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize dead space,
            // more strongly when the dead space is tiny (wasted capacity).
            let waste = post_residual as f64;
            score += 15.0 * (1.0 - waste / bin_capacity as f64);
        }
    }

    // Compare residual against mean residual: prefer bins that are already
    // relatively full (below-mean residual) to consolidate load.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 8.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 8.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening a brand-new bin when other bins could fit,
    // unless the item is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let fragmented = mean_residual < item_size as f64 * 0.5;
        if large_item || fragmented {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    // Late in the stream, tighten packing to squeeze remaining items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that no future item can plausibly use:
    // dead space is bad when post_residual is small but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Penalize leaving a residual too small for the next item (fragmentation).
            let waste = (next_item_size as f64) - (post_residual as f64);
            score += 0.15 * waste.min(40.0);
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fill_frac * (2.0 + open_bins_count as f64).ln().max(1.0) * 3.0;

    // Mild penalty for bins far from mean residual (encourage homogeneity).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in stream, be more willing to open new bins
    // (penalize existing bins less); late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * fill_frac;

    // New-bin candidate: neutral baseline with slight exploration bias that
    // decays over time; only wins when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // Base: post residual, smoothly scaled by fill quality (prefer tight fits)
    let mut score = pr * (1.0 + 0.5 * fill * fill);

    // Non-linear polynomial coupling of residual with stream progress:
    // later in the stream, dead space becomes more costly (superlinear)
    let dead_penalty = (pr / cap).powi(3) * (1.0 + 2.0 * progress);
    score += dead_penalty * cap;

    // Reward near-perfect fills with a smooth bump around fill ~ 1
    let closeness = (fill * fill * fill) * (3.0 - 2.0 * fill); // smoothstep
    score -= closeness * 15.0;

    // Lookahead coupling: bonus if the next item fits exactly in post_residual
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let lookahead_fit = (-gap / 20.0).exp();
        score -= 8.0 * lookahead_fit;
        // penalize if post_residual is awkwardly between next item and its fit
        if pr < next_item_size as f64 {
            score += 3.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // mild penalty when many bins compete (prefer spreading fill)
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Smooth coupling with mean residual: prefer bins below mean residual
    // (fill emptier bins first), polynomial in difference
    let diff = (mean_residual - pr) / cap;
    score += 6.0 * diff * diff - 4.0 * diff;

    // New-bin candidate: penalize opening new bins unless item is large
    // or stream is early with few bins; smooth gating via sigmoid-like term
    if bin_residual == bin_capacity {
        let gate = 1.0 / (1.0 + (-(fit_ratio - 0.5) * 6.0)).exp();
        score = 45.0 + 30.0 * gate + 20.0 * progress - 10.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual modulo 10.
    // Small post_residual classes (0..=10) are excellent closures.
    let class = post_residual % 10;
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if class == 0 {
        score -= 12.0; // round residual, reusable for many sizes
    } else if post_residual < 20 {
        score -= 8.0;
    } else if post_residual > 60 {
        score += 10.0; // wasteful large leftover after a big item
    }

    // Lookahead: if next item fits into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 20.0 + (slack as f64).min(15.0) * -0.5;
        if slack == 0 {
            score -= 25.0; // chain of perfect fits
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        // dead space: next item cannot use it
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: baseline slightly above a decent fit, but attractive
    // when current fits are poor (large post_residual or dead space).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55; // 55.0
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // big item coming, fresh bin useful
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild pressure against bin sprawl early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // Deviation from mean residual: prefer bins that keep residuals balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post_residual gaps that no item (>=1)
    // can use are not directly penalizable (items go down to 1), but gaps that
    // are small relative to typical item sizes create fragile states. Penalize
    // a non-linear "wasted zone": residual in (0, 12] is nearly dead space.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 12 {
        score += 18.0 - 1.2 * pr; // strong penalty for tiny leftovers
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let tightness = pr / (item_size as f64 + 1.0);
    score -= 10.0 * (1.0 - tightness.min(1.0));

    // Open-bin pressure: with many open bins, discourage spreading; opening a
    // new bin is costly, so bias toward existing bins when they fit well.
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin has large post_residual which
    // naturally scores high; add explicit cost so it only wins when existing
    // bins would leave bad dead space (their scores were already inflated).
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        // Late in stream, opening fresh bins is even less attractive.
        score += 20.0 * progress;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead synergy: if the next item fits exactly in the post_residual,
    // reward heavily (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 8.0;
        }
        // If next item cannot fit in this residual, mildly penalize creating
        // residuals that strand the lookahead.
        if next_item_size > post_residual && post_residual < 10 {
            score += 6.0;
        }
    }

    // Slight preference for bins with residuals above the mean (keeps mean
    // residual distribution balanced, avoiding many half-empty bins).
    score += 0.05 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect/near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= next {
            // exact match is ideal
            let diff = (pr - next) as f64;
            score -= 120.0 - diff * 1.5;
        } else {
            // leftover too small for next item: dead space penalty
            score += 40.0 + (next - pr) * 0.8;
        }
        // chain fit: item + next exactly fills the bin
        if post_residual == next_item_size {
            score -= 500.0;
        }
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (tighter bins), penalize wasting large-residual bins on small items.
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize new-bin candidates mildly so open bins are preferred unless fit is bad.
    if bin_residual == bin_capacity {
        score += 80.0 + open_bins_count as f64 * 2.0;
        // allow opening a new bin early in the stream when few bins exist
        if step_index < total_items / 10 {
            score -= 50.0;
        }
    }

    // Late in stream: be more frugal with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post-residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead coupling: if next item fits the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + (next_item_size as f64 / bin_capacity as f64) * 60.0;
        } else {
            // dead space penalty scaled by how much next item overshoots
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.4 * overshoot;
        }
    }

    // Last-chance bonus: only fitting bin -> strong reward
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // mild penalty for spreading across many fitting bins
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize opening new bins early when open bins fit well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 30.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Global residual pressure: many open bins with large mean residual -> prefer reusing
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        if !is_new_bin {
            score -= 10.0 * pressure;
        }
    }

    // Fragmentation penalty: post-residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;

    // Base: quadratic in post_residual, mildly damped as stream progresses
    let mut score = pr + (pr * pr) / (2.0 * cap) * (1.0 - 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= (1.0 - pr / cap) * (1.0 + progress) * 10.0;

    // Penalize dead space: post_residual too small to fit a typical item
    let dead = if next_item_size > 0 && (post_residual as u32) < next_item_size { 1.0 } else { 0.0 };
    score += dead * (10.0 + 20.0 * progress);

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / cap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: penalize slightly by default; smooth relaxation as open bins grow
    if is_new_bin {
        score += 5.0 + 0.5 * open_bins_count as f64 - 10.0 * progress * (pr / cap);
    }

    // Smooth interaction with mean residual: prefer bins below mean residual (tighter)
    score += 0.1 * (mean_residual - pr) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals divisible by large
    // powers of 2 (or by 10) are more reusable, so reward them.
    let pr = post_residual;
    if pr > 0 {
        let mut h = 0u32;
        let mut v = pr;
        while v % 2 == 0 { h += 1; v /= 2; }
        score -= 2.0 * h as f64;
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Class-match: if next item fits into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 8.0;
        // Extra reward when post_residual is an integer multiple class of next item
        if pr % next_item_size.max(1) == 0 {
            score -= 4.0;
        }
    } else if next_item_size > pr && pr > 0 {
        // next item cannot follow here: penalize proportionally to tightness
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (which costs a full bin worth of slack).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // fits are poor. Add a mild penalty so empty bins lose to good fits.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But late in the stream with many open bins, fresh bins are fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Prefer bins tighter than average (best-fit flavor), scaled by mean.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res).min(20.0);
    } else {
        score += 0.25 * (res - mean_residual).min(20.0);
    }

    // Integer-division threshold: penalize residuals in "awkward" bands
    // (just above common item sizes) that waste capacity.
    let bands: [u32; 6] = [20, 30, 40, 50, 60, 70];
    for b in bands.iter() {
        if pr > *b && pr < *b + 10 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead space avoidance ---
    // Gaps that are too small to ever be useful again are heavily penalized.
    // Assume future items can be as small as ~1..15; treat gaps < 15 as near-dead.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // pure dead space
        } else if post_residual < 20 {
            score += 25.0; // mostly dead space
        } else if post_residual < 35 {
            score += 8.0; // only small items could reuse it
        }
    } else {
        // Perfect fit: zero waste, strongly reward.
        score -= 80.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // --- Open bins pressure ---
    // Encourage consolidating into existing bins; penalize spreading thin.
    score += 4.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate (empty bin): make it less attractive unless the
    // current bin would leave a very bad gap or cannot be improved.
    if bin_residual == bin_capacity {
        // Baseline neutral score for a fresh bin.
        score += 10.0;
        // A new bin is attractive if the current bin would be left with
        // unusable dead space AND other options are poor.
        if post_residual < 20 && post_residual > 0 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item fits nicely into the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack_after_next / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot follow into this gap; penalize proportionally.
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first),
    // keeping looser bins available for awkward future items.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Mild stream progression: later in the stream, be more conservative
    // about creating dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    score += (post_residual as f64) * 1.5;

    // 2-step lookahead: reward bins whose post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 12.0;
        } else {
            // next item won't fit here; penalize dead space relative to next size
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Compare post_residual against mean residual: keep balance, punish outliers.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize large wasted space (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fit bonus
    }
    if post_residual > 50 {
        score += 15.0; // large unusable gap
    }

    // New-bin candidate handling: opening a new bin should only win for
    // very poor fits in existing bins.
    if bin_residual == bin_capacity {
        score += 60.0 + post_residual as f64;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 30.0; // big next item may justify a fresh bin
        }
    }

    // Slight late-stream conservatism: consolidate as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items (1..100).
    if post_residual > 0 && post_residual < 20 {
        score += 18.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving a stranded residual.
            score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Many options: mild penalty to encourage diversity of choice.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bins should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // More attractive early in the stream or when few bins fit the item.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress) * (1.0 - (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0)).min(1.0));
        // If open bins are fragmented (high mean residual spread), a new bin is reasonable.
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        score -= 6.0 * fragmentation;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating into fuller bins.
    let mean_load = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 {
        score += 3.0 * mean_residual / bin_capacity as f64 * (open_bins_count as f64).ln();
    }
    let _ = mean_load;

    // Time horizon: late in stream, be more conservative (avoid waste) — penalize large residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins whose residual is close to item size (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let tight = 1.0 - pr / cap; // how full the bin becomes

    // Base: prefer small post-residual, non-linearly
    let mut score = pr * pr / cap + pr * (1.0 - fit_ratio);

    // Smooth coupling: residual waste matters more as stream progresses
    score += pr * (0.5 + 0.5 * progress) * (1.0 - tight);

    // Reward tight fits more strongly with polynomial interaction
    score -= tight * tight * cap * (0.3 + 0.4 * progress);

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * gap / cap * (0.4 + 0.6 * progress);
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= cap * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many bins vs mean residual
    score += (open_bins_count as f64).ln() * (1.0 + mean_residual / cap) * 0.5 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin, more so early
    if bin_residual == bin_capacity {
        score += cap * (1.2 - 0.7 * progress) + pr * (0.5 - 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;
    let item_frac = item_size as f64 / cap;
    let next_frac = next_item_size as f64 / cap;

    // Class index via integer division thresholds (harmonic bands of capacity).
    let class = (post_residual * 4) / bin_capacity; // 0..3 harmonic band of dead space
    match class {
        0 => score -= 6.0,          // near-perfect fit: strongly reward
        1 => score -= 2.0,          // small dead space: mild reward
        2 => score += 1.5,          // moderate dead space: penalize
        _ => score += 4.0,          // large dead space: heavy penalize
    }

    // Modulo arithmetic on post_residual: residuals divisible by small ints
    // are more likely to be exactly filled by future small items.
    if post_residual > 0 && (post_residual % 5 == 0 || post_residual % 10 == 0) {
        score -= 1.0;
    }
    if post_residual > 0 && post_residual % 3 == 0 {
        score -= 0.3;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Next item fits: reward proportional to how well it fills leftover.
        let fill = next_frac / (post_frac.max(1e-6));
        score -= 3.0 * fill.min(1.0);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize wasting a good residual on this item.
        score += 2.0 * (1.0 - item_frac);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: prefer tighter fits, mild penalty scaled by alternatives.
        score += 0.4 * (fitting_bins_count.min(8) as f64 - 1.0);
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to capacity or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // high => existing bins are full
        let new_bin_score = cap - item_frac * 20.0 + pressure * 15.0;
        // Blend: keep base score but bias toward opening when pressure is high.
        score = score.min(new_bin_score);
    }

    // Stream progression: late in the stream, consolidate harder (avoid new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 2.0 * progress;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first),
    // leaving looser bins flexible for future items.
    if (post_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps that no future item
    // (min size 1, but practically sizes >= 10 in classic streams) can use
    // are heavily penalized. Exact fits are maximally rewarded.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: consume the bin completely
    } else if post_residual < 10 {
        // Unusable dead space (below the smallest practical item size)
        score += 45.0 + 10.0 * (10 - post_residual) as f64;
    } else {
        // Usable gap: mildly favor tighter fits
        score += 0.15 * post_residual as f64;
    }

    // Reward tight fits relative to item size (small relative slack)
    let relative_slack = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * relative_slack;

    // Lookahead coupling: if the next item fits exactly into the resulting
    // residual, strongly favor this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap < 10 {
            score += 20.0; // next item leaves dead space here -> discourage
        } else {
            score -= 0.2 * gap as f64;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones rather than spreading; penalize lightly per open bin
    // so a new bin only wins when its fit is clearly better.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bonus: if this is the ONLY bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: placing into a bin whose residual is far above
    // the mean wastes the "fat" bins; prefer bins near/below mean residual.
    let deviation = bin_residual as f64 - mean_residual;
    score += 0.1 * deviation;

    // New-bin candidate handling: an empty bin should only win when the
    // current item is large relative to capacity (poor fit elsewhere) or
    // when no good existing option exists. Make the empty bin moderately
    // attractive by default but let tight fits in open bins beat it.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, opening fresh bins is more acceptable
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
        // Large items fragment bins less when started fresh
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits (dead-space elimination).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this is a perfect pairing — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 10 {
                score -= 60.0;
            } else {
                score -= 20.0;
            }
        } else {
            // Next item does NOT fit in the remainder: penalize proportionally
            // to how much dead space this creates relative to capacity.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins with below-average residual (tighter bins), keeping
    // looser bins available for future items.
    let resid = bin_residual as f64;
    score += 0.3 * (resid - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual <= 15 {
            score -= 40.0;
        }
    }

    // Penalize leaving very small unusable fragments (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Early in the stream, be slightly more willing to pack into open bins
    // rather than proliferating bins; later, allow more freedom.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress);

    // Mild penalty for having many open bins: prefer consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (post_residual as f64 - next_item_size as f64);
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize tight fits that create dead space below the minimum item size (1..100 unknown, use 10 as floor).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Time horizon: early stream, be conservative (favor new bins less); late stream, squeeze into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.5 {
        score -= 8.0 * progress;
    } else {
        score += 3.0 * (1.0 - progress);
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing bins.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }
    if mean_residual > 0.0 {
        score += 0.05 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate: penalize slightly so it's only chosen when all open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize leftover space, with non-linear (quadratic) coupling
    let mut score = post * (1.0 + norm_post * norm_post);

    // Smooth stream-progress coupling: later in stream, waste hurts more
    score += 30.0 * progress * norm_post * norm_post;

    // Perfect fit reward (smooth, non-piecewise)
    score -= 25.0 * (1.0 - norm_post).powi(8);

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        let fits = (post_residual >= next_item_size) as f64;
        let tight = 1.0 - (next_item_size as f64 / cap - norm_post).abs();
        score -= 12.0 * fits * tight.max(0.0);
    } else {
        // Last item: strongly prefer filling existing bins
        score -= 20.0 * norm_post;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize slightly unless current residuals are tight
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 18.0 * (1.0 - mean_norm) * (1.0 - mean_norm);
        score -= 6.0 * progress;
    }

    // Mild penalty for too many open bins
    score += 0.5 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes mod 25
    let item_class = item_size / 25;            // 0..3
    let next_class = next_item_size / 25;       // 0..3 (4 if next==100, treat as 3)
    let next_class = next_class.min(3);

    // Reward when next item fits perfectly into post_residual (harmonic pairing)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 12.0 - (slack as f64) * 0.15;
        // Extra reward for class-complementary pairing (e.g. large item + small item)
        if item_class as i32 + next_class as i32 >= 2 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space
        score += (post_residual as f64) * 0.35;
    }

    // Integer-division threshold: post_residual in "dead zone" (< smallest plausible item)
    if post_residual < 10 {
        score -= 25.0; // perfect fit, no waste
    } else if post_residual <= 20 {
        score -= 5.0; // small waste, still usable by small items
    } else if post_residual > 50 {
        score += 6.0; // leaving a big gap suggests poor bin choice
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Modulo harmonic class on post_residual: prefer residuals in friendly classes
    let pr_mod = post_residual % 10;
    score -= match pr_mod {
        0 => 6.0,
        1 | 9 => 3.0,
        2 | 8 => 1.5,
        _ => 0.0,
    };

    // Progress-aware tightening: late in stream, avoid waste more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * 0.1 * progress;

    // If many bins are open, prefer tighter packing (penalize loose fits)
    if open_bins_count > 4 {
        score += (post_residual as f64) * 0.05 * (open_bins_count as f64).ln();
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good squeeze
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.08;

    // New-bin candidate: make it attractive only when nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0; // default: prefer existing bins
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: open new bin
        } else if post_residual > 60 {
            score -= 45.0; // item would leave huge gap in existing bin -> new bin better
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the smallest item (1..100)
    // are "dead" unless zero. Penalize gaps that can never be filled.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 500.0;
    }

    // Penalize small-but-nonzero gaps relative to mean residual: a gap far below
    // mean residual is likely stranded.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / (mean_residual.max(1.0));
        if gap_ratio < 0.35 {
            score += 120.0 * (0.35 - gap_ratio);
        }
    }

    // Reward bins whose post-residual can still host the next item (lookahead synergy)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // creates a gap that next item cannot use — extra dead-space penalty
        score += 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer tight packing
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 80.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a decent fit (large waste would be created elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score = 100.0;
        // If current item leaves a tight fit in a fresh bin, that's fine
        if post_residual <= 10 {
            score -= 30.0;
        }
        // Late in the stream with few fitting bins, opening a new bin is acceptable
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 1 {
            // only one bin fits; new bin slightly discouraged but not heavily
            score += 50.0 * (1.0 - progress);
        } else {
            // multiple bins fit: strongly prefer existing bins
            score += 150.0;
        }
        // Next-item synergy in a fresh bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post-residual preferred).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later
    // (items are >= 1, but typical useful chunks are larger).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += (10.0 - dead) * 2.5; // nearly unusable sliver
        } else {
            // moderate residuals are reusable; gently reward them
            score -= 0.05 * dead;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // big reward; if next item cannot fit but bin is nearly full, small penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, be more conservative about filling
    // bins poorly (many items remain); late in stream, prioritize closing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> prefer consolidating into existing bins
    // (penalize opening new ones implicitly by rewarding fits more).
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is an outlier; filling it down toward the mean is good.
    let res = bin_residual as f64;
    let dev = (res - mean_residual).abs();
    score -= 0.08 * dev * tightness;

    // Prefer using bins with less residual when fits are comparable
    // (best-fit bias beyond raw post_residual).
    score += 0.10 * res;

    // New-bin candidate calibration: an empty bin has post_residual = capacity.
    // Make it slightly worse than a decent existing fit but better than a
    // terrible one, so it is chosen only when existing fits create dead space.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0; // fresh bin can also host the next item
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is required anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) shaping.
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: as the stream advances, tighten preference for tight fits
    // (smooth polynomial interaction between post-residual and progress).
    score += 1.5 * norm_pr * (1.0 - progress) * (1.0 - progress);
    score -= 0.6 * norm_pr * progress * (1.0 - progress);

    // Dead-space penalty: residuals too small for typical future items are quadratic-worse.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 2.0 * gap * gap * cap;
        } else {
            // Reward bins that can also host the lookahead item (smooth discount).
            let slack = (pr - nxt) / cap;
            score -= 0.8 * (1.0 - slack) * (1.0 - slack) * norm_pr;
        }
    } else {
        // Near end of stream: just minimize waste.
        score += 0.5 * norm_pr;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty for spreading across many bins when residuals are already high.
    let mean_norm = mean_residual / cap;
    score += 0.3 * mean_norm * norm_pr * (open_bins_count as f64).sqrt() / 10.0;

    // Slight bias against opening a brand-new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 0.5 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it pairs with typical future items
    let class = post_residual % 10;
    score -= match class {
        0 => 12.0,          // perfectly divisible residual, easy to fill later
        5 => 6.0,           // half-class residual
        2 | 4 | 6 | 8 => 2.0,
        _ => 0.0,           // odd residuals are harder to fill
    };

    // Dead-space penalty: residual that cannot hold even the smallest plausible item
    if post_residual < 10 {
        score += 40.0;
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward proportional to how snugly the next item fills the leftover
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.3 * slack;
        } else {
            // next item won't fit here; penalize wasted lookahead opportunity
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only good when current bins are fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin
        score += 20.0;
        // open more readily early in the stream or when many bins are already open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * (1.0 - progress);
        // if mean residual is high and item fits poorly in existing bins, new bin is fine
        if mean_residual > item_size as f64 {
            score += 5.0;
        } else {
            score -= 5.0;
        }
        // never open a new bin if the item would fit almost exactly in an existing bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 30.0;
        }
    } else {
        // reward using bins whose residual is close to the item (minimize fragmentation)
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 10.0 * (1.0 - tightness);
        // slightly prefer bins with above-average residual when many bins are open
        if bin_residual as f64 > mean_residual && open_bins_count > 3 {
            score -= 3.0;
        }
    }

    // Modulo threshold on item size: large items (harmonic class > 50) prefer fresh space
    if item_size > 50 && !is_new_bin && bin_residual - item_size < 20 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward leaving gaps that can still host the (likely) next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // gap too small for lookahead -> dead space risk
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / 8.0) + (mean_residual / bin_capacity as f64);
        score += 25.0 + pressure * 10.0;
        if post_residual < item_size.max(1) {
            // empty bin: post_residual = capacity - item
            if bin_capacity - item_size < 10 {
                score += 30.0; // would immediately create a tiny gap
            }
        }
    } else {
        // Prefer fuller bins (smaller residual before placement).
        score += (bin_residual as f64) * 0.15;
    }

    // Mild open-bin pressure: discourage spreading across many bins early.
    score += open_bins_count as f64 * 0.5;

    // Progress coupling: tighten tolerance as the stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual == 0) as i32 as f64;
    score += 5.0 * progress * ((post_residual > 0 && post_residual < 10) as i32 as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: leave nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the NEXT item exactly fills this bin's post-residual,
    // this placement creates a perfect pairing — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if next_item_size <= post_residual {
            // next item fits after this placement: mild reward proportional to tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 150.0 * tightness;
        } else {
            // next item cannot use the leftover space: penalize dead space creation
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Tight fit reward relative to capacity.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 100.0 * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer bins with residuals below mean (compact bins get filled first),
    // keeping larger residuals available for future large items.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin, but relax the penalty
    // when the item is large (would leave awkward space in any open bin)
    // or when no open bin fits well.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 300.0;
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 50.0 * (item_size as f64 - bin_capacity as f64 / 2.0);
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual == bin_capacity - item_size {
            // fresh bin leaves exactly the right room for the next item pair
            new_bin_penalty -= 100.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score += tight * tight * 40.0;

    // Penalize wasted space relative to current item size (dead space scaling).
    score += (post_residual as f64).powf(1.3) * 0.05;

    // Lookahead: if next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; mild penalty proportional to gap.
        let gap = (next_item_size as i64 - post_residual as i64).max(0) as f64;
        score += gap * 0.15;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer bins whose residual is already small (consolidate fragmentation).
    let res_norm = bin_residual as f64 / bin_capacity as f64;
    score -= (1.0 - res_norm) * 15.0;

    // Time horizon: early in stream, be more willing to open new bins / keep flexibility;
    // late in stream, squeeze into existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 8.0 * (open_bins_count as f64).ln().max(1.0);

    // Coupling with mean residual: placing into a bin far below mean residual
    // (i.e., unusually full bin) is good; near-empty bins are penalized slightly.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Penalize opening a brand-new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 25.0 * pressure + 0.5 * item_size as f64;
        // Late in the stream, opening new bins is more acceptable if item is small.
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit)
    let mut score = post;

    // Non-linear polynomial coupling of post residual with stream progress.
    // Early on (progress ~ 0): mild preference for leaving moderate space.
    // Late (progress ~ 1): strongly punish any leftover space.
    let poly = pr * pr * (1.0 - progress) * 30.0 - pr * (1.0 - pr) * progress * 60.0;
    score += poly * cap * 0.5;

    // Smooth dead-space penalty: post residual too small to fit typical items.
    let dead = if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0) / cap;
        gap * gap * 80.0
    } else {
        0.0
    };
    score += dead;

    // Last-chance bonus: smooth sigmoid-like reward when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty when bin is far below mean residual (avoid fragmenting fresh bins)
    let dev = (post - mean_residual) / cap;
    score += dev * dev * 10.0 * (1.0 - progress);

    // New-bin candidate: keep it slightly unattractive unless post residual is perfect fit
    if bin_residual == bin_capacity {
        score += 8.0 + 40.0 * pr * (1.0 - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when the item fits terribly everywhere
    // or no open bin exists. Penalize opening a fresh bin otherwise.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 1000.0;
        } else {
            let tight_fit = (post_residual as f64) <= 5.0;
            let last_chance = fitting_bins_count == 1;
            let mut new_bin_penalty = 60.0 + 0.5 * open_bins_count as f64;
            if tight_fit { new_bin_penalty -= 40.0; }
            if last_chance { new_bin_penalty += 25.0; }
            // Harmonic class: small items (<=25) pair well later in a fresh bin
            if item_size <= 25 { new_bin_penalty -= 10.0; }
            score += new_bin_penalty;
        }
        return score;
    }

    // Harmonic class of the leftover space: classify post_residual by
    // integer division thresholds. Leftovers in "dead" classes are penalized,
    // leftovers matching common small-item sizes are rewarded.
    let dead_class = post_residual / 10; // 0..10 classes
    match dead_class {
        0 => score += 45.0,            // 0..9 : nearly unusable dead space
        1 => score += 20.0,            // 10..19: only tiny items fit
        2 | 3 => score += 5.0,         // 20..39: medium-small usable
        4 | 5 | 6 => score -= 8.0,     // 40..69: flexible band, good
        _ => score += 0.0,             // 70..99: still roomy
    }

    // Lookahead harmony: reward when next_item_size fits exactly (or well)
    // into the post_residual (k=2 lookahead).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect pair
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // harmonic pairing quality: small slack is great
            let pair_class = slack / 10;
            score -= match pair_class {
                0 => 30.0,
                1 => 18.0,
                2 => 8.0,
                3 => 2.0,
                _ => 0.0,
            };
        } else {
            // next item cannot fit here: mild penalty scaled by overflow
            let overflow = (next_item_size - post_residual) / 10;
            score += (overflow as f64).min(6.0) * 3.0;
        }
    } else {
        // last item: prefer filling bins as tightly as possible
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
        // extra reward if the fit is tight (harmonic class 0 or 1)
        if post_residual <= 19 {
            score -= 15.0;
        }
    }

    // Prefer bins below mean residual (fill emptier-relative space evenly),
    // scaled by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (mean_residual - bin_residual as f64) * (0.3 + 0.4 * progress);

    // Small tie-breaker: tighter fit overall wins.
    score += post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Medium dead space: mildly penalized, scaled by how much of the bin it wastes.
    if post_residual > 10 && post_residual < 25 {
        score += 0.35 * (post_residual as f64 - 10.0);
    }
    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Reward tightness relative to bin size (fractional fill).
    score -= (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 12.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements that keep many bins alive with
    // scattered residuals; encourage consolidation when bins are few.
    score += (open_bins_count as f64).sqrt() * 2.5;

    // Deviation from mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.08;

    // Lookahead coupling: if the next item could fit into this bin's post
    // residual, reward leaving exactly that space; otherwise penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual < next_item_size {
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate calibration: an empty bin should only win when the
    // alternative is a poor fit; make empty bins moderately unattractive.
    if bin_residual == bin_capacity {
        score += 18.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the
    // remaining space, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize leftover dead space after both items.
            let dead = post_residual - next_item_size;
            score += dead as f64 * 0.5;
            score -= 30.0;
        } else {
            // Next item does not fit here; penalize proportionally to overflow.
            let over = next_item_size - post_residual;
            score += over as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize creating small unusable slivers relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Mild pressure to keep the number of open bins low late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else {
        score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;
    }

    // Lookahead: if next item fits in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.2 * next_item_size as f64;
        } else {
            // dead space unless it's near full
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is
    // large and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = (item_size as f64 / bin_capacity as f64).powf(1.5);
        score += 45.0
            - 25.0 * tightness
            - 10.0 * (mean_residual / bin_capacity as f64)
            + 15.0 * (1.0 - progress).min(1.0);
        if item_size >= 60 {
            score -= 20.0; // big items deserve fresh bins
        }
    }

    // Many open bins: encourage consolidation into emptier bins to close them.
    let pressure = open_bins_count as f64 / 20.0;
    if (bin_residual as f64) > mean_residual {
        score += 6.0 * pressure; // prefer bins below-average residual? no: prefer filling emptier bins
    } else {
        score -= 4.0 * pressure;
    }

    // Slight preference for bins whose residual is close to item_size (best-fit).
    let gap = (bin_residual as i64 - item_size as i64) as f64;
    score += 0.05 * gap.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear coupling: tight fits are rewarded more as the stream progresses
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Penalize residual that is unlikely to fit the next item (dead space)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64 * (1.0 - 0.5 * progress);
        } else {
            // Reward residual that still accommodates the lookahead item
            score -= 0.10 * (post_residual - next_item_size).min(bin_capacity / 2) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin proportionally
    // to how many open bins exist and how good the fit elsewhere might be.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64; // equals capacity - item_size
        score += 30.0 + 0.4 * open_bins_count as f64 + 0.25 * waste;
        // Late in the stream, closing out bins is cheaper: soften the penalty
        score -= 25.0 * progress;
        // But if the item is huge and would leave a tiny residual elsewhere,
        // opening a fresh bin can be fine; reward very tight fills even in new bins
        if tightness > 0.8 {
            score -= 30.0 * (tightness - 0.8) * 5.0;
        }
    } else {
        // Prefer bins with below-average residual (keeps one "flex" bin alive)
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff * (1.0 - progress);
    }

    // Mild preference for fewer open bins when progress is high
    score += 0.3 * open_bins_count as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item-size classes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 8.0; }
        if pr % 20 == 0 { bonus += 6.0; }
        if pr % 25 == 0 { bonus += 6.0; }
        if pr % 50 == 0 { bonus += 8.0; }
        score -= bonus;

        // Integer-division thresholds: classify residual into usable bands
        let band = pr / 10; // 0..=10
        match band {
            0 => score += 25.0,            // 1..9: near-dead space
            1 | 2 => score += 10.0,        // small but usable for tiny items
            3 | 4 => score += 2.0,
            5 | 6 => score -= 2.0,
            _ => {}                        // large residual stays attractive
        }

        // Coupling: does the NEXT item fit exactly or well into post_residual?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 40.0;             // exact harmonic match
            } else if next_item_size < pr {
                let nxt_post = pr - next_item_size;
                if nxt_post % 10 == 0 { score -= 12.0; }
                if nxt_post % 25 == 0 { score -= 10.0; }
                score -= (nxt_post / 10) as f64 * 3.0;
            } else {
                score += 8.0;              // next item cannot use this bin
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer existing bins unless residual is tiny.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral-ish baseline; discourage when decent fits exist.
        score = bin_capacity as f64 * 0.5 + mean_residual * 0.3;
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big next item benefits from a fresh bin
        }
    }

    // Late-stream consolidation: tighten packing as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.1;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below minimum item size is pure waste
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: bin closed completely
    } else if post_residual >= 10 && post_residual < 25 {
        score += 10.0; // marginal gap, only large items (rare) could use it
    }

    // Reward tight packing relative to bin size.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many fitting bins means we can afford to be picky: penalize mediocre fits.
    if fitting_bins_count > 2 {
        score += 8.0 * (1.0 - fill_ratio);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 30.0; // chain of perfect fits
        } else if post_residual - next_item_size < 10 {
            score += 5.0; // would create new dead space
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate: opening a fresh bin is expensive; only attractive when
    // the item is large and no open bin handles it well, or bins are saturated.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        let saturation = mean_residual / bin_capacity as f64;
        score = 55.0
            - 30.0 * big_item
            - 25.0 * saturation
            + 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large items coming: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (-match_gap / 8.0).exp();
        // Perfect chain bonus: item fits, and next item exactly fills what remains.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a residual that is too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.6 * (post_residual as f64).sqrt();
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.5 * post_residual as f64;
    }

    // Reward bins that are already "wasted" relative to the mean residual (use them up).
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score -= 0.8 * (residual_f - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins; encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for fuller bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - residual_f) * 0.05;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual as i64 - next_item_size as i64 > 20);
        if poor_fit {
            score -= 30.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the space.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 25.0 * fit_ratio;
    } else {
        score += 8.0 * (1.0 - fit_ratio);
    }

    // Penalize leaving dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 40 {
        // Residuals in 10..40 are somewhat usable; mild penalty scaled by waste.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item would fit this bin better than the current one, penalize
    // (save space for it).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score -= 5.0; // current bin can't serve next item anyway; use it now
        } else {
            let waste = post_residual as f64 - nx;
            if waste < 10.0 {
                score += 20.0; // would leave a sliver for the next item
            }
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well and the stream is early/mean residual is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        let mut new_bin_score = 55.0 + 30.0 * pressure;
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0; // no alternative
        }
        if progress < 0.3 {
            new_bin_score -= 10.0; // early stream: fresh bins fine
        }
        if open_bins_count > 8 {
            new_bin_score += 5.0; // too many open bins: prefer consolidation
        }
        score = new_bin_score;
    }

    // Global balance: prefer bins whose residual is below the mean (keeps
    // large residuals available for large items).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Slight preference for fuller bins as stream progresses.
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap; // fraction of bin used after placement

    // Smooth polynomial coupling: reward high fill, modulated by stream progress.
    let coupling = fill * fill * (0.5 + progress) * cap * 0.5;
    score -= coupling;

    // Reward tight fits (small post_residual relative to item size).
    let tight = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tight * tight * 20.0;

    // Penalize post_residual that cannot fit the lookahead item (dead space).
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += 8.0 + progress * 10.0;
        } else {
            // Reward residual that still accommodates the next item.
            let room = (post_residual as f64) / (next_item_size as f64);
            score -= room.min(4.0) * 3.0;
        }
    }

    // Last-chance bonus: only bin that fits → strongly encourage using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin, more so early when open bins exist.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 10.0 + 5.0 * (1.0 - progress) + open_f.min(10.0);
    } else {
        // Mild reward for consolidating into existing bins when mean residual is high.
        score -= (mean_residual / cap).min(1.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual (modulo-10 residue classes).
    let harmonic_class = (post_residual % 10) as f64;
    // Residuals in classes {0, 5} are "harmonic" (likely reusable by future items
    // drawn from integer grids); other classes create dead space more often.
    let harmonic_bonus = if post_residual == 0 {
        -60.0 // perfect closure: extremely desirable
    } else if harmonic_class == 0.0 {
        -12.0
    } else if harmonic_class == 5.0 {
        -6.0
    } else {
        harmonic_class // small odd residues are dead space
    };
    score += harmonic_bonus;

    // Integer-division threshold on post_residual: classify leftover usability.
    let leftover_bucket = post_residual / 10; // 0..=10
    score += leftover_bucket as f64 * 1.5;    // bigger leftovers = more wasted capacity

    // Lookahead coupling: reward if the next item can fit into post_residual,
    // scaled by how tightly it fits (harmonic chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 15.0 - tightness * 0.3; // tighter chain fit => bigger reward
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover is dead relative to the next item: mild penalty
        score += (post_residual as f64) * 0.05;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is atrocious.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        // penalize only if it leaves a badly non-harmonic large residual
        if post_residual > 40 && post_residual % 10 != 0 {
            score += 10.0;
        }
    }

    // New-bin candidate (empty bin): score its post_residual fairly, but bias
    // slightly so we only open new bins when existing fits are clearly worse.
    if bin_residual == bin_capacity {
        score += 8.0;
        // opening a fresh bin is good when the item is large (small post_residual)
        // and few bins are open
        score -= (cap - post_residual as f64) * 0.05;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it is a "junk drawer"; discourage dumping items there unless tight fit.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    // Prefer filling older (likely emptier) bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item are pure waste. Penalize super-linearly as post_residual shrinks.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 12.0 {
        score += (13.0 - post_residual as f64).powf(2.0) * 2.5;
    }
    // Sweet spot: leave exactly the lookahead item's size behind if possible.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.35;
    }

    // Tight fits are excellent: reward small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // opening a new empty bin should only win when fits are terrible.
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        score += pressure + 20.0;
        // Allow a new bin only when no decent fit exists anywhere.
        if post_residual >= item_size && fitting_bins_count == 0 {
            score -= pressure;
        }
    } else {
        score -= pressure * 0.5;
    }

    // Mean-residual coupling: bins far below mean residual are "lonely" space;
    // prefer placing into bins whose residual is near/below the mean to balance.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    // Late in the stream, consolidation matters more; early on, keep options open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - tightness);

    // Penalize leaving a gap that no future item (10..80 range typical) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly: small post_residual gets extra discount.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is always excellent
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tightness * tightness;
    }

    // Penalize dead space that cannot fit a typical future item.
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score += 50.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more fragmentation: mild reward scaled by fit quality
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize bins whose residual is barely above item
            let overshoot = (next_item_size - post_residual) as f64;
            if overshoot < 10.0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is costly; only attractive
    // when existing fits are poor (large post_residual relative to capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score += 18.0;
        // if this bin would leave a very tight fit anyway, new bin less attractive
        if post_residual == 0 {
            score -= 45.0; // still allow opening when item == capacity exactly
        }
        // late in stream, prefer closing out open bins rather than opening new ones
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // many open bins: discourage more
        score += 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // Using existing bins reduces open-bin count pressure; small reward.
        score -= 1.5;
        // If bin residual is far above mean residual, we're wasting a "roomy" bin
        // that could serve larger future items; penalize slightly.
        let diff = bin_residual as f64 - mean_residual;
        if diff > 0.0 {
            score += 0.05 * diff;
        }
    }

    // Global fragmentation pressure: when mean residual is low, conserve space
    // by penalizing any placement leaving residual below the mean.
    if (post_residual as f64) < mean_residual {
        score += 0.5 * (mean_residual - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Smooth non-linear penalty on wasted residual, growing with stream progress
    let waste = norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += 60.0 * waste;

    // Interaction: post_residual vs item size ratio (dead space unusable for typical items)
    let ratio = item_size as f64 / cap;
    score += 20.0 * norm_pr * (1.0 - ratio) * (1.0 + progress);

    // Lookahead coupling: reward if next item fits in post_residual (smooth logistic-ish)
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as f64;
        let snug = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= 35.0 * fits_next * snug.max(0.0);
    }

    // Penalize opening a new bin when alternatives exist (smooth in fitting count)
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score += 80.0 * is_new_bin * scarcity * (1.0 + progress);

    // Mild pressure to fill bins more fully as many bins accumulate
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Encourage tight fits: residual close to zero gets strong discount
    score -= 25.0 * (1.0 - norm_pr).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual in low harmonic classes (0..=10) strongly favored.
    if post_residual == 0 {
        score -= 500.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 200.0 / post_residual as f64;
    } else if post_residual <= 20 {
        score -= 60.0;
    }

    // Penalize dead space that no future item (min size 1) can plausibly fill:
    // post_residual classes via integer division thresholds.
    let dead_class = post_residual / 25; // 0..=4 harmonic classes
    score += dead_class as f64 * 15.0;

    // Lookahead coupling: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 100.0;
            } else {
                score += (slack as f64).sqrt() * 5.0;
            }
        } else {
            // next item can't go here; mild penalty proportional to overflow
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): penalize so it's chosen only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 250.0;
        // But early in the stream with many open bins, opening fresh can be fine.
        if open_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Prefer filling bins with large residuals when mean residual is high (consolidation).
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0;
    score += mean_residual * 0.05;

    // Mild pressure to keep bin count low as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post_residual gaps that no future item
    // (sizes 1..=100) can use are pure waste. Penalize them super-linearly.
    if post_residual > 0 {
        // Dead space: gap too small for the smallest plausible item.
        if post_residual < 10 {
            score += 60.0 + (10 - post_residual) as f64 * 12.0;
        }
        // Gap unusable by the lookahead item => likely dead until stream end.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + (next_item_size - post_residual) as f64 * 0.8;
        }
        // Diminishing usefulness of large residuals: quadratic waste term.
        let pr = post_residual as f64;
        score += 0.004 * pr * pr;
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to the item size (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a new bin
    // could consolidate; but never overpower the last-chance reward.
    score += (open_bins_count as f64).sqrt() * 3.0;

    // New-bin candidate handling: an empty bin is a costly commitment; only let
    // it win when no open bin offers a decent fit. Give it a moderate base score
    // so tight fits in existing bins still beat it.
    if bin_residual == bin_capacity {
        score = 55.0
            + (open_bins_count as f64) * 2.0
            - (fitting_bins_count as f64) * 6.0;
        // If even the lookahead won't pair well in a fresh bin, slightly cheaper.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0;
        }
    }

    // Mild stream-position coupling: late in the stream, prefer consolidating
    // into existing bins even more (fewer residual bins left behind).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let gap = (post_residual as f64 - look).abs();
        if post_residual as f64 >= look {
            // next item fits exactly-ish -> strong reward
            score -= 300.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 500.0;
            }
        } else {
            // next item does not fit: penalize wasted residual relative to look size
            score += 0.5 * gap;
        }
    }

    // Relative-to-mean coupling: prefer leaving residuals near the mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Penalize large dead space that nothing small can use
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // tiny dead space is fine (nearly full)
    } else if post_residual >= 10 && post_residual < item_size.min(80) {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: neutral-ish score, opened only when open bins are bad
    if bin_residual == bin_capacity {
        score += 150.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 80.0; // pair consecutive items in a fresh bin
        }
    }

    // Stream progression: as stream ends, be more conservative about new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    }

    // Crowding: many open bins -> prefer filling existing ones
    score -= 5.0 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
