pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling: post_residual normalized, shaped by progress.
    let pr_norm = post_residual as f64 / cap;
    let shape = 0.5 + 0.5 * (progress * std::f64::consts::PI).sin(); // smooth, no piecewise constants
    score += 12.0 * pr_norm * pr_norm * (1.0 - shape);              // extra penalty for big leftovers later
    score -= 10.0 * pr_norm * shape;                                 // but reward capacity conservation early

    // Tightness reward: quadratic coupling of post_residual with item_size.
    let tight = (post_residual as f64) / (item_size as f64 + 1.0);
    score -= 8.0 / (1.0 + tight * tight);

    // Penalize creating dead space that just barely fails to fit the next item.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 {
            score += 6.0 * (post_residual as f64 / cap) * (1.0 - gap / cap);
        } else {
            score -= 5.0 * (gap / cap); // residual usable by next item is good
        }
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mild penalty so open bins are preferred unless fit is terrible.
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - 0.5 * progress);
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild penalty for bins far from mean residual (fragmentation avoidance), smooth.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Small residues (<10) are dead space; penalize proportionally.
    let dead = post_residual % 10;
    if dead > 0 {
        score += dead as f64 * 2.0;
    }
    // Residues that are multiples of 10 are reusable "harmonic" slots.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more dead space: mild penalty scaled by leftover.
            let nxt_dead = (post_residual - next_item_size) % 10;
            score -= 20.0 - nxt_dead as f64 * 1.5;
        } else {
            // Next item won't fit here: penalize bins whose residual is "almost" next size.
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += gap as f64 * 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is wasteful unless item is huge (>70% of capacity)
        // or no open bin fits well. Base penalty to prefer existing bins.
        let mut new_bin_penalty = 120.0;
        if item_size * 10 >= bin_capacity * 7 {
            new_bin_penalty -= 80.0; // large items: new bin acceptable
        }
        if post_residual == 0 {
            new_bin_penalty -= 100.0; // exact-capacity item
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += progress * 50.0;
        // Many open bins with slack: discourage another one.
        new_bin_penalty += (open_bins_count as f64).sqrt() * 10.0;
        score += new_bin_penalty;
    }

    // Prefer bins tighter than the mean residual (good fillers).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Integer-division threshold: reward bins whose post_residual falls in
    // the "usable small item" band [10, 30).
    if post_residual >= 10 && post_residual < 30 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
