pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits the post-residual exactly or closely.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 25.0; // perfect chain: item + next item fill the bin
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to wasted lookahead potential.
        score += 3.0 * (next_item_size as f64 / 100.0);
    }

    // Compare post_residual to mean residual: prefer leaving residuals consistent with the pack state.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Penalize creating small unusable dead space (below smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor or lookahead mismatches.
    if bin_residual == bin_capacity {
        let base = 0.35 * bin_capacity as f64;
        score += base;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0; // don't abandon a promising chain
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good alternative: opening new bin is fine
        }
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: reward if next item fits in the post residual (chaining placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        let chain_quality = 1.0 - (slack_after_next as f64 / bin_capacity as f64);
        score -= 10.0 * chain_quality;
    } else if next_item_size > 0 {
        // Penalize if this placement leaves residual too small for the next item (dead space).
        score += 6.0 * (next_item_size as f64 / 100.0) * (1.0 - progress);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Crowding: when many bins are open, prefer consolidating into existing bins.
    if !is_new_bin {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // New-bin candidate: only attractive when existing bins fit poorly or none fit well.
    if is_new_bin {
        let poor_fit_penalty = if fitting_bins_count == 0 {
            -50.0 // no alternative: opening a new bin is necessary
        } else {
            // penalize new bin proportionally to how many bins could fit the item
            30.0 + 8.0 * fitting_bins_count as f64
        };
        score += poor_fit_penalty;
        // Late in the stream, opening fresh bins is slightly cheaper (less waste horizon).
        score -= 10.0 * progress;
        // Prefer new bins when mean residual across open bins is already fragmented.
        score -= 0.15 * mean_residual;
    } else {
        // Using an existing bin with residual close to mean residual keeps balance.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    let tightness = 1.0 - fit_norm;

    // Smooth non-linear coupling: reward tight fits progressively over stream
    score -= 40.0 * tightness * tightness * (0.5 + 0.5 * t);
    // Cubic dead-space penalty on large residuals
    score += 0.02 * pr * pr * pr / (cap * cap);
    // Lookahead: reward residual that can host next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 25.0 * (-gap * gap / 200.0).exp();
    }
    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }
    // Mild pressure toward consolidating into fewer bins
    score -= (open_bins_count as f64).ln().max(0.0) * tightness * 5.0;
    // Mean-residual deviation penalty (smooth quadratic)
    score += 0.1 * (pr - mean_residual) * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by its class modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space that is too small to hold typical items (1..=100 unknown dist)
    // Class thresholds via integer division on post_residual
    let class = post_residual / 10; // harmonic class 0..=10
    match class {
        0 => score += 60.0,               // 0 residual: perfect fit, reward
        1 => score += 25.0,               // tiny dead space 1..9: nearly perfect
        2 => score += 12.0,               // 10..19: still usable-ish
        3 => score += 6.0,
        4 | 5 => score -= 8.0,            // 30..49: sweet spot for mid items
        6 | 7 => score -= 4.0,
        8 => score += 10.0,               // 80..89: awkward large dead space
        9 => score += 14.0,
        _ => {}                            // near-empty bin class
    }

    // Modulo coupling: post_residual divisible by common item sizes is more reusable
    if post_residual > 0 {
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                score -= 6.0;
                break;
            }
        }
    }

    // Lookahead: does this bin's post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward chain-fitting, scaled by how snugly next item fits
            let snug = (next_item_size as f64) / pr.max(1.0);
            score -= 10.0 + 15.0 * snug;
        } else {
            // post_residual too small for next item: penalize proportionally to waste
            score += 8.0 + 0.2 * pr;
        }
    } else {
        // last item: prefer minimal residual
        score += 0.1 * pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = (open_bins_count as f64) / (mean_residual.max(1.0) / cap.max(1.0) + 1.0);
        let tight = mean_residual < (item_size as f64) * 1.2;
        if tight && open_bins_count > 0 {
            score -= 15.0; // open fresh bin when all residuals are too tight
        } else {
            score += 30.0 + 5.0 * (open_bins_count as f64).ln().max(0.0) - 0.05 * crowding;
        }
    }

    // Progress-aware mild pressure toward consolidation early, spreading late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * pr - progress * 0.03 * pr;

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (or the lookahead) are pure waste.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) as f64 } else { 10.0 };
    if post > 0.0 && post < min_useful {
        score += 3.0 * (min_useful - post); // heavy penalty for near-dead space
    }

    // Reward tight fits (small post_residual relative to item).
    score -= 2.0 * (item / cap) * (1.0 - post / cap);

    // Perfect-fit style bonus: leaving exactly zero residual.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // residual can host next item: mild reward proportional to snugness
        let slack = (post_residual - next_item_size) as f64;
        score -= 5.0 * (1.0 - slack / cap);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing ones; few open bins -> opening new bins is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when current bins fit badly.
        let bad_fit_penalty = if post > 0.0 && post < min_useful { 40.0 } else { 0.0 };
        score += 8.0 + 5.0 * pressure + bad_fit_penalty;
        // Encourage new bin when item is large and would leave awkward gaps.
        if item > 0.6 * cap {
            score -= 6.0;
        }
    } else {
        // Existing bin: slight reward scaled by how full it already is.
        let fullness = 1.0 - bin_residual as f64 / cap;
        score -= 4.0 * fullness;
    }

    // Mild stream-progression drift: later in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving dead space relative to gap size.
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Last chance: only this bin fits the item -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Prefer bins whose residual deviates below the mean (tighter, more filled bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when nothing else fits well or stream is early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; less when many bins are open or late stream.
        score += 40.0 + 60.0 * (1.0 - progress);
        if fitting_bins_count > 1 {
            score += 120.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Pairing lookahead items in a fresh bin can be good.
            score -= 30.0;
        }
    }

    // Small reward for filling bins nearly completely.
    if post_residual <= 5 {
        score -= 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
