pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Penalize large dead space more aggressively as stream progresses
    score += (norm_pr * norm_pr) * cap * (0.15 + 0.45 * progress);

    // Reward tight fits (small post_residual) with cubic discount
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * tightness * 12.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Many open bins: mild pressure to fill existing bins rather than spread
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins that keep residuals balanced
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev / cap;

    // Lookahead: if next item could use the remaining space, reward leaving it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // leftover too small for next item: penalize dead space
            score += 4.0 + 6.0 * progress;
        }
    }

    // New-bin candidate: make empty bins moderately attractive only when fit is bad
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) - 10.0 * progress;
        if norm_pr > 0.5 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction does it fall into?
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals in awkward classes (dead space that few item sizes can fill).
    // Classes: (0,10], (10,25], (25,50], (50,100)
    if post_residual == 0 {
        score -= 40.0; // perfect fit, strongly reward
    } else if post_residual <= 10 {
        score -= 12.0; // near-perfect, only tiny items needed
    } else if post_residual <= 25 {
        score -= 3.0; // moderately fillable
    } else if post_residual <= 50 {
        score += 2.0; // half-ish empty: mediocre
    } else {
        score += 6.0; // mostly empty: wasteful placement of a small item
    }

    // Modulo-class coupling: does next_item_size divide into post_residual nicely?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
            // exact chain fit
            if post_residual == next_item_size {
                score -= 25.0;
            }
            // harmonic residue: next item leaves a residual in a "good" class (<=10)
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score -= 8.0;
            }
        } else {
            score += 8.0; // lookahead item cannot follow into this bin
        }
    }

    // Integer-division threshold: bins whose residual is a multiple of common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0; // decadal residuals align with typical size granularity
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only open a new bin if current bins are crowded / poor fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // prefer new bin when existing residuals are small and item is large
        let tight = mean_residual / bin_capacity as f64;
        score = 55.0 + 30.0 * (1.0 - progress) - 20.0 * (item_size as f64 / bin_capacity as f64) + 25.0 * tight;
        if fitting_bins_count <= 1 {
            score += 40.0; // avoid abandoning the only fitting bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are unusable.
    if post_residual < 10 {
        score += 60.0; // hard penalty for creating dead space
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward closing the bin
    } else {
        // Penalize gaps too small to fit typical next items (near-dead space)
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Tightness reward: the fuller the bin, the better
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += (open_bins_count as f64).sqrt() * 4.0;

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && post_residual >= 10;
        if good_fit_exists {
            score += 55.0; // penalize opening a new bin when fits exist
        } else {
            score -= 20.0;
        }
    }

    // Lookahead: favor leaving room for the known next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fill: small post_residual is already favored by base term.
    // Strong reward when post_residual exactly matches the next item (2-step lookahead match).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0; // exact 2-step chain: place here
        } else if diff <= 5 {
            score -= 40.0;
        } else if diff <= 15 {
            score -= 15.0;
        } else {
            // post_residual too far from next item: penalize wasted residual
            score += diff as f64 * 0.5;
        }

        // If next item cannot fit anywhere else after this placement, prefer bins
        // that leave room for it; if post_residual < next_item_size, next item
        // must open a new bin anyway -> penalize more.
        if post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Prefer tighter bins relative to the mean residual of open bins.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.8;
    } else {
        score += (res - mean_residual) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is
    // large relative to residual (poor fit in existing bins) or many bins fit it.
    if bin_residual == bin_capacity {
        let tight_fit = fitting_bins_count > 0 && (bin_residual - item_size) < 10;
        let poor_alternatives = fitting_bins_count <= 2;
        let mut penalty = 25.0;
        if tight_fit || poor_alternatives || next_item_size == 0 {
            penalty -= 20.0; // opening a new bin becomes attractive
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        score += penalty;
        // Empty-bin residual is max; make it unattractive by default via base term,
        // but reward if item nearly fills a fresh bin.
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (build structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 5.0;
    }

    // Mild penalty for leaving large unusable gaps (>50) that few items can fill.
    if post_residual > 50 && post_residual < 60 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, this is ideal.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize wasted residual that nothing can use.
            let wasted = (post_residual - next_item_size) as f64;
            score += 0.3 * wasted;
        }
    } else {
        // Last item: pure tightness matters.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, mild penalty to let tightness dominate.
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in the stream, be more tolerant of residual (future items may use it);
    // late in the stream, prioritize compactness.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 40.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: if open bins are already loose on average, penalize adding more
    // loose space; if mean residual is low (bins tight), slight reward for this bin.
    score += 0.2 * (mean_residual - post_residual as f64);
    score += 0.1 * open_bins_count as f64;

    // New-bin candidate: only attractive when no open bin fits well (high post_residual elsewhere
    // or very few fitting bins). Penalize default new bin mildly so tight fits win.
    if bin_residual == bin_capacity {
        score += 60.0 - 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: new bin is fine
        }
    }

    // Non-linear coupling: penalize residual just above common small item sizes being unusable.
    let r = post_residual as f64;
    if r > 0.0 && next_item_size > 0 && next_item_size as f64 > r {
        score += (r / bin_capacity as f64).powf(2.0) * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;

    // Smooth non-linear coupling: residual pressure vs. progress.
    // Early on, tight packing (small post_residual) is cheap to demand; late in the
    // stream, leaving dead space is worse, so penalize large post_residual more.
    let pr = post_residual as f64 / cap;
    score += 30.0 * pr * pr * (0.4 + 1.2 * prog2);

    // Reward near-perfect fits with a smooth quadratic bonus on fill ratio.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 12.0 * fill * fill * (1.0 - 0.5 * progress);

    // Lookahead: smooth compatibility term. If next item fits the post residual,
    // reward this bin; scale the reward by how snugly the next item nests.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let nest = nxt / (post_residual as f64 + 1.0); // in (0,1] if it fits
        if nxt <= post_residual as f64 {
            score -= 15.0 * nest * nest * (1.0 - progress);
        } else {
            // Next item won't fit here: gently penalize bins that strand the lookahead.
            score += 8.0 * (nxt / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin,
    // with a smooth decay as the stream progresses (late bins less precious).
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - 0.5 * prog2);
    }

    // Fitting scarcity: when few bins can host the item, preserve them;
    // when many fit, spread load smoothly via mean-residual coupling.
    if fitting_bins_count > 1 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score += 6.0 * scarcity * (pr - mean_residual / cap).abs();
    }

    // Mild penalty for opening a brand-new bin when it's not the last chance,
    // smoothly increasing with the number of already-open bins.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 2.0 * (open_bins_count as f64).ln();
    }

    // Small smooth jitter-free regularizer tying residual to global mean state.
    score += 0.05 * (post_residual as f64 - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post == 0 (perfect fit) -> huge reward
    // Class 1: post < 10 (dead space, nothing fits since min size 1..but small) -> reward
    // Larger classes: progressively penalized via integer division thresholds.
    let class = post_residual / 10; // harmonic bucket of leftover space
    score += (class as f64) * 8.0;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward small post_residual relative to capacity fraction
    score -= (1.0 - post / cap) * 5.0;

    // Lookahead coupling: if the next item fits the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // extra reward if next item nearly fills the bin after this placement
        let npost = post_residual - next_item_size;
        if npost < 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit: penalize proportionally to wasted opportunity
        score += 10.0 + (next_item_size as f64 - post) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 35.0;
        // but if existing bins are all crowded (mean residual low), opening is fine
        if mean_residual < item_size as f64 * 0.5 {
            score -= 45.0;
        }
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // if many open bins, prefer consolidating instead of opening
        score += open_bins_count as f64 * 1.5;
    }

    // Mild pressure to keep mean residual balanced
    score += (post - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (<= 10) are the worst outcome -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 20.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer filling.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 5.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // If next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use leftover: mild penalty proportional to leftover.
        score += 3.0;
    }

    // Prefer bins with below-mean residual (fill emptier bins less, tighter bins more).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: neutral baseline; only chosen when no open bin scores well.
    if bin_residual == bin_capacity {
        // Opening cost grows with number of already-open bins and stream progress.
        score = 45.0 + 10.0 * pressure + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // If no existing bin fits, opening is mandatory-ish: reduce cost.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual is disproportionately good).
    if post_residual > 0 {
        score -= 40.0 / (post_residual as f64).sqrt();
    } else {
        score -= 60.0; // perfect fit bonus
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0; // chain match: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space
            score += 12.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Penalize wasting a nearly-full bin on a small item.
    let waste = (post_residual as f64) / bin_capacity as f64;
    score += 20.0 * waste * waste;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Discourage opening new bins when open bins have plenty of room.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (open_bins_count.min(10) as f64);
        if mean_residual > item_size as f64 {
            score += 10.0; // an open bin could have absorbed this item
        }
    }

    // Mild preference for keeping many open bins consolidated as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Strong reward for perfect fill
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize residuals that are too small to hold the next item (wasted dead space)
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) && post_residual > 0 {
        let waste = post_residual as f64;
        score += 0.8 * waste;
        // If next item could have fit here, extra penalty
        if (next_item_size as u64) <= (bin_residual as u64) {
            score += 5.0;
        }
    } else if next_item_size > 0 && (next_item_size as u64) <= (post_residual as u64) {
        // Reward leaving room for the lookahead item
        score -= 3.0 + 0.3 * post;
    }

    // Tight-fit preference: relative fill ratio
    let fill_ratio = item / cap;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is costly; discourage unless item is large
    if bin_residual == bin_capacity {
        let open_penalty = 20.0 + 0.1 * open_bins_count as f64;
        // If existing bins fit poorly (many fitting bins => fragmentation elsewhere), opening is fine
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 5.0 / fitting_bins_count as f64 };
        score += open_penalty - fit_pressure;
        // Large items pair well with fresh bins
        score -= 0.15 * item;
    }

    // Time-horizon modulation: early in stream, be conservative with residuals; late, pack greedily
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.05 * post;
    score -= progress * 0.05 * post;

    // Global fragmentation pressure: if mean residual is high, prefer bins below mean residual
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 2.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, non-linearly (waste grows quadratically).
    let mut score = pr * (1.0 + 0.02 * pr / cap);

    // Smooth coupling with stream progress: residual waste matters more late in the stream.
    score += pr * (0.5 + progress) * (pr / cap);

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    score -= (cap - pr) * (1.0 - pr / cap) * 0.5;

    // Lookahead coupling: if next item fits into post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            let fit_quality = 1.0 - (gap / cap).powi(2);
            score -= 6.0 * fit_quality;
        } else {
            // Next item won't fit here: mild penalty proportional to shortfall.
            score += 0.02 * (-gap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Penalize spreading across many open bins when this bin is far below mean residual.
    score += 0.05 * (mean_residual - pr).max(0.0) * (1.0 + open_bins_count as f64 / 10.0);

    // Slight penalty for opening a new bin when good fits exist (new-bin call has pr == cap).
    if pr >= cap - 0.5 {
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that align with
    // common item-size classes (multiples of 10 and small remainders).
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 {
        // Perfectly reusable residual (0 mod 10 and >= 10) is valuable.
        if class == 0 {
            score -= 8.0;
        } else {
            // Dead-space penalty grows for awkward odd remainders.
            score += class as f64 * 0.5;
        }
        // Residuals below the minimum item size are pure waste.
        if pr < 10 && pr > 0 {
            score += 20.0;
        }
    } else {
        // Perfect fill: huge reward.
        score -= 30.0;
    }

    // Fractional fill of the bin: prefer bins that become well-packed.
    let fill_after = 1.0 - (post_residual as f64 / cap);
    score -= fill_after * 10.0;

    // Lookahead coupling: if the next item fits the post residual exactly
    // or nearly, strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this residual: mild penalty proportional
        // to wasted fraction.
        score += (next_item_size as f64) * 0.05;
    }

    // Last-chance bin: this is the only bin that fits; avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many fitting bins: competition is high, pick the tightest via
    // post_residual (already dominant), but add small penalty for
    // spreading across too many open bins.
    if fitting_bins_count > 2 {
        score += (open_bins_count as f64) * 0.3;
    }

    // Mean-residual coupling: placing into a bin far below mean residual
    // (i.e., unusually full bin) balances the pool.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.05;

    // Stream progression: later in the stream, be more conservative
    // about creating dead space (tighter packing pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / cap) * progress * 6.0;

    // New-bin candidate: opening a fresh bin should only win when no
    // decent fit exists among open bins.
    if bin_residual == bin_capacity {
        score = 60.0 + (item_size as f64) * 0.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large item followed by larger: fresh bin OK
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

