    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this residual anyway; slight relief of dead-space penalty
        score -= 5.0;
    }

    // Open bins pressure: penalize spreading across many bins, favor filling existing ones.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when existing bins would create bad fits.
    if bin_residual == bin_capacity {
        // Opening new bin: its "post_residual" is huge, so base score is high already.
        // Penalize opening new bins when a good fit exists elsewhere.
        if post_residual > 0 && post_residual < 10 && fitting_bins_count >= 1 {
            score += 0.0; // new bin has no dead space, handled by base score
        }
        score += 30.0; // default cost of opening a new bin
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: as stream progresses, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly matches the new residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.6 * diff;
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 25.0; // perfect 2-step chain: fill bin completely next step
        }
        // Penalize residuals too small for next item but large enough to be dead space
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 0.35 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: bins tighter than average are good targets
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless current residuals are all poor fits
    if bin_residual == bin_capacity {
        let waste_now = (bin_capacity as f64 - item_size as f64);
        score += 18.0;
        // allow new bin if it leaves room likely useful for next item
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0;
        }
        if waste_now < 10.0 {
            score -= 15.0;
        }
    }

    // Late in stream: consolidate more strongly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize large dead space relative to item size
    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / item_size as f64;
        score += 8.0 * dead_ratio.min(3.0);
    }

    // Lookahead: reward leaving a residual that the next item can exactly or snugly fill
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.15;
        } else {
            // next item won't fit here; residual becomes dead unless future items fill it
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless all existing fits are bad
    if bin_residual == bin_capacity {
        let mut penalty = 12.0;
        if fitting_bins_count == 0 {
            penalty = 0.0;
        } else if fitting_bins_count == 1 {
            penalty = 30.0; // last chance exists, prefer it
        }
        // late in stream, prefer consolidating
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty += 10.0 * progress;
        score += penalty;
    }

    // Prefer bins with residual close to the mean (balanced packing) mildly
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference for reusing bins when many are open
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).min(10.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: post residual, with non-linear decay of its value as it grows
    let mut score = pr * (1.0 + 0.5 * fit_norm * fit_norm);

    // Smooth polynomial coupling of residual with stream progress:
    // later in the stream, larger residuals (waste) are penalized more strongly
    score += 12.0 * (pr / cap).powi(2) * (0.5 + progress);

    // Reward tight fits: subtract a smooth bump centered near zero post-residual
    let tightness = (-fit_norm * 4.0).exp();
    score -= 10.0 * tightness * (1.0 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // More competing bins -> slight penalty to spreading across many bins
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * fit_norm;

    // Lookahead: if next item fits exactly in the post-residual, reward this bin
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns).abs();
        if diff <= pr {
            score -= 8.0 * (-diff / 10.0).exp();
        }
        // penalize if post-residual is just barely too small for the next item
        if pr < ns && ns - pr <= 20.0 {
            score += 4.0 * (1.0 - (ns - pr) / 20.0);
        }
    }

    // Deviation from mean residual: prefer bins below-mean residual (fuller bins)
    score += 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes of capacity quarters.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;

    // Reward residuals that fall into "usable" harmonic classes (small slivers are dead space).
    let class = (post_residual / (bin_capacity / 8).max(1)) % 8;
    match class {
        0 => score -= 12.0,          // near-perfect fill
        1 => score -= 6.0,           // tiny but pairable with smallest items
        2 | 3 => score -= 2.0,       // mid-range usable
        4 => score += 3.0,           // half-full: fine but not urgent
        5 | 6 => score += 6.0,       // awkward gap
        _ => score += 10.0,          // nearly empty bin being used wastefully
    }

    // Fractional fill: reward high utilization non-linearly.
    let fill = 1.0 - pr / cap;
    score -= 20.0 * fill * fill;

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: bonus if next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; slight penalty proportional to wasted opportunity
            score += 2.0;
        }
    }

    // New-bin candidate: keep it competitive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (mean_residual / cap).max(0.1);
        score = cap * 0.9 - 10.0 * progress - crowd.min(10.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.1 * (mean_residual - pr).max(-cap) / 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (post_residual as f64 + item_size as f64 + 1.0);
    score -= 10.0 * tightness;

    // Open bins pressure: discourage spreading across many bins.
    score += 0.5 * open_bins_count as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (fill fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score -= 30.0; // but allow when it's the only viable option
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: strong reward if the next item exactly fills post_residual (perfect 2-chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: this bin becomes exactly full next step
        } else if post_residual >= next_item_size {
            // Partial match: reward proportionally to how much of next item fits.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill_ratio;
        } else {
            // Next item won't fit here; penalize dead space left behind, worse if large.
            let waste = next_item_size - post_residual;
            score += 0.5 * waste as f64;
        }
    } else {
        // Last item: minimize leftover as hard as possible.
        score += 20.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Reward tightness relative to bin: small absolute slack is good.
    score -= 0.3 * (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 10.0;

    // Penalize leaving residual far below the mean (fragmenting small slivers),
    // but only when the residual is small and unlikely to be useful.
    if (post_residual as f64) < mean_residual {
        let deficit = mean_residual - post_residual as f64;
        score += 0.15 * deficit;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin is attractive early or when current
    // fit is bad (large post_residual means poor packing here).
    if bin_residual == bin_capacity {
        // Cost of a fresh bin decreases as stream progresses (sunk cost amortization)
        // and when the alternative fit is poor.
        let poor_fit = (post_residual as f64 / bin_capacity as f64).min(1.0);
        score = 100.0 - 30.0 * progress - 40.0 * (1.0 - poor_fit);
        // If many bins are open and residuals are large, prefer reusing them.
        score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // Never open a new bin if it's the only fitting option anyway handled above.
        if fitting_bins_count == 1 {
            score += 50.0; // strongly prefer the existing last-chance bin
        }
    }

    // Late-stream tightening: waste matters more near the end.
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that nothing (even smallest plausible item) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding pressure: many open bins -> prefer consolidation into existing bins.
    let pressure = (open_bins_count as f64) / ((step_index.max(1) as f64).sqrt() + 1.0);
    score -= pressure.min(10.0);

    // Prefer bins with residual close to item (best fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64);
    score += 0.15 * fit_gap;

    // Time horizon: late in stream, avoid opening new bins; early, allow exploration.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or when mean residual is high.
        let mut new_bin_penalty = 20.0 + 60.0 * progress;
        if mean_residual > item_size as f64 + 10.0 {
            new_bin_penalty += 10.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size {
            // next item pairs perfectly with a fresh bin
            new_bin_penalty -= 30.0;
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: reward more when late in stream.
        score -= 10.0 * progress;
    }

    // Mean residual alignment: prefer bins near the mean residual (keeps bin profile uniform).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_n = pr / cap;
    let fit_n = (fitting_bins_count as f64).sqrt();
    let open_n = (open_bins_count as f64).ln().max(0.0);

    // Base: minimize waste, but weight waste by stream progress (late waste is costlier)
    let mut score = pr * (0.5 + 1.5 * progress * progress);

    // Smooth non-linear coupling: quadratic penalty on mid-range residuals (awkward dead space)
    let awkward = 4.0 * pr_n * (1.0 - pr_n);
    score += 12.0 * awkward * (0.3 + progress);

    // Reward tight fits smoothly (small post_residual gets extra discount)
    score -= 20.0 * (1.0 - pr_n).powi(3);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits smoothly in post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - 4.0 * slack * (1.0 - slack)).max(0.0);
        } else {
            score += 5.0 * (1.0 - (cap - nx) / cap.max(pr));
        }
    }

    // Spread pressure: bins far from mean residual get smoothed penalty
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (open_n / (open_n + 2.0));

    // New-bin candidate: penalize mildly, less so early when spreading is cheap
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 4.0 * (fitting_bins_count.max(1) as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left
    let class = (frac * 10.0).floor() as i64; // 0..10 harmonic class

    // Penalize odd/hard-to-fill classes: residuals in (0,10) and (40,60) are dead zones.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    }
    if class == 4 || class == 5 {
        score += 12.0; // mid-range residual is awkward for typical items
    }

    // Reward exact fills and large residuals (flexible bins).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
        // Harmonic pairing: next item's class modulo 10
        let next_class = (next_item_size as f64 / cap * 10.0).floor() as i64;
        if (next_class + class) % 3 == 0 {
            score -= 5.0; // complementary pairing bonus
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.4 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Early in stream, encourage consolidation; late, tolerate new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more early, less late.
        score += 25.0 * (1.0 - progress) + 5.0;
    }

    // Many open bins: discourage spreading; few bins: mild encouragement.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps (dead space that likely fits nothing later).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Prefer bins whose residual is close to item size (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // dead space for the known next item
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bonus = 20.0 + 30.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New bin candidate: baseline near mean residual so it competes fairly,
        // penalized more when many bins are already open.
        score = mean_residual + new_bin_bonus;
    } else {
        // Mild preference for bins with larger residuals (consolidate space).
        score -= 0.1 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match (small slack) -> proportional reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Dead space: post_residual too small for next item but nonzero -> penalize.
    else if next_item_size > 0 && post_residual > 0 {
        score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Favor tight fits relative to mean residual across open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly discourage opening a new bin when only this bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when current bins would leave large unusable slack.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Late in the stream, consolidate: prefer reusing existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64 / (open_bins_count.max(1) as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill * fill;

    // Penalize small dead space that future items (>=10) cannot use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if next item cannot use post residual, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        } else {
            let slack_after_pair = post_residual - next_item_size;
            if slack_after_pair < 10 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - fill);
    }

    // Prefer fuller bins relative to the fleet's mean residual (best-fit bias).
    let res_frac = bin_residual as f64 / bin_capacity as f64;
    score += 20.0 * (mean_residual / bin_capacity as f64 - res_frac).max(0.0);

    // Time horizon: early in the stream, keep flexibility (penalize very low residuals);
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if res_frac > 0.5 {
        score += (1.0 - progress) * 10.0;
    } else {
        score -= progress * 15.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // or the fleet is empty; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let fleet_pressure = if open_bins_count == 0 {
            -100.0
        } else {
            let decent = mean_residual >= item_size as f64;
            if decent { 25.0 + 10.0 * (open_bins_count as f64).ln().max(1.0) } else { -20.0 }
        };
        score += fleet_pressure;
        // Late stream: opening fresh bins is cheaper (less future waste risk).
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear coupling: post-residual penalty grows with stream progress
    score += 30.0 * pr * pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= 20.0 * (1.0 - pr) * (1.0 - pr) * progress;

    // Penalize bins whose residual deviates from mean residual (fragmentation avoidance)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev * dev;

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        if fits_next >= 0.0 {
            score -= 12.0 * (1.0 - fits_next);
        } else {
            score += 6.0 * (-fits_next);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, more so early in the stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common small item sizes) are rewarded.
    let class = post_residual % 10;
    let class_bonus: f64 = match class {
        0 => 12.0,   // perfectly harmonic leftover (fits 10-multiples)
        5 => 6.0,    // half-harmonic
        _ => {
            // penalize leftovers in awkward classes, worse the smaller the residue mod 10
            -2.0 + (class as f64) * 0.4
        }
    };
    score -= class_bonus;

    // Integer-division threshold on post_residual: leftover >= 10 stays usable.
    if post_residual >= 10 {
        score -= 8.0;
    } else if post_residual > 0 {
        // dead space: unusable sliver
        score += 15.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // this is a perfect pair placement — strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        if post_residual - next_item_size >= 10 {
            score -= 6.0; // chain continues after next item
        }
    }
    // If next item cannot fit into post_residual, leftover is likely dead.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize opening new bins when decent
    // fits exist, but allow it when this bin would leave big dead space.
    if bin_residual == bin_capacity {
        score += 25.0;
        if post_residual > 50 {
            score -= 5.0; // large item, new bin is reasonable
        }
    }

    // Late in stream: consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (open_bins_count.min(20) as f64).sqrt();

    // Prefer bins below mean residual (tighter bins fill faster).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Exact fit celebration.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps more than large ones.
    // Gaps below ~20 are almost never fillable by future items (sizes 10..80 -> min 10,
    // but pairs rarely fit), so apply a super-linear penalty there.
    if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 8.0; // strong dead-space tax
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit is the best outcome
    } else {
        // Larger gaps are reusable; mild reward proportional to reusability
        score -= (post_residual as f64 - 20.0) * 0.05;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // and the new bin would serve the next item well.
    if bin_residual == bin_capacity {
        let base_penalty = 35.0;
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= bin_capacity {
            (bin_capacity as f64 - next_item_size as f64) * 0.3
        } else {
            0.0
        };
        // Open-bin pressure: many open bins -> discourage yet another new bin
        let pressure = open_bins_count as f64 * 3.0;
        score += base_penalty + pressure - lookahead_bonus;
    }

    // Lookahead synergy: if the next item exactly fits the post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        // next item fits in leftover: mild reward, scaled by tightness
        let tight = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 10.0 * (1.0 - tight);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover: penalize proportional to wasted potential
        score += (next_item_size as f64 - post_residual as f64) * 0.2;
    }

    // Open-bin count pressure: with many bins open, prefer consolidating into
    // tighter fits (smaller post_residual already captured), add slight bias
    // toward bins below mean residual (already packed tighter).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else if (bin_residual as f64) > mean_residual {
        score += 1.5;
    }

    // Late in the stream, closing bins tightly matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward placements where the next item
    // exactly fills the post-residual (chain of perfect fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 800.0;
        } else {
            // Reward tight coupling: the closer next item fills the leftover,
            // the better (residual slack after two steps).
            let two_step_leftover = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - two_step_leftover / bin_capacity as f64);
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item cannot use the leftover: penalize dead space proportionally.
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual below the mean are
    // "tighter" and should be preferred targets for large items.
    let residual_gap = mean_residual - post_residual as f64;
    score -= 0.3 * residual_gap;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the
    // item is huge relative to capacity (poor fit anywhere else).
    if bin_residual == bin_capacity {
        let tight_fit = (item_size as f64 / bin_capacity as f64) > 0.8;
        if !tight_fit && fitting_bins_count > 0 {
            score += 250.0;
        }
        // Early in the stream, opening bins is cheap; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0 * progress;
    }

    // Slight preference for bins with larger residual consumed by this item.
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
