pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_norm = post / cap;

    // Base: prefer small post residual, with non-linear (quadratic) sharpening
    let mut score = post + 8.0 * residual_norm * residual_norm * cap;

    // Smooth stream-progress coupling: late in the stream, be stricter about waste
    score -= 6.0 * (1.0 - progress) * post;          // early: lenient
    score += 10.0 * progress * residual_norm * cap;  // late: punish dead space

    // Last chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: only attractive if current bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln().max(0.5);
        let fit_deficit = (item_size as f64 / cap - 0.5).max(0.0);
        score += 25.0 * crowd + 40.0 * fit_deficit * (0.5 + progress);
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
    }

    // Lookahead: reward leaving residual that can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 4.0 + 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && post > 0.0 && post < (next_item_size as f64) {
        // small unusable sliver: penalize mildly
        score += 3.0 * (1.0 - post / (next_item_size as f64));
    }

    // Slight preference for bins with below-mean residual (consolidate fullness)
    score += 2.0 * ((post - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful"
    // (small or multiples of common item sizes), penalize dead zones.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0; // nearly full, minimal waste
    } else {
        // Dead-space penalty grows super-linearly in mid-range residuals.
        let frac = pr as f64 / cap;
        score += 20.0 * frac * (1.0 - frac) * 4.0;
        // Reward residuals matching harmonic classes (multiples of 5/10/20)
        if pr % 5 == 0 { score -= 4.0; }
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        // Penalize residuals in awkward band (31..49) — hard to fill
        if pr >= 31 && pr <= 49 { score += 8.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
            if (pr - next_item_size) % 10 == 0 { score -= 5.0; }
        } else {
            // next item won't fit here; penalize large leftover slightly less
            // if residual is in a reusable class
            if pr % 10 == 0 { score -= 2.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins open
        // or late in stream (fewer future pairings needed).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 - 15.0 * progress;
        if fitting_bins_count == 0 { score -= 20.0; }
        // If current item is large, fresh bin is fine.
        if item_size >= 60 { score -= 10.0; }
        // Avoid opening new bins when mean residual across open bins is large.
        score += (mean_residual / cap) * 15.0;
    }

    // Slight preference for tighter existing bins overall.
    score += (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
