    // Reward tight fits via smooth coupling with stream progress
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward residual that can host the next item (smooth kernel)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        let kernel = (-gap * gap / 200.0).exp();
        score -= 15.0 * kernel;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize spreading residual thin across many bins
    score += (open_bins_count as f64).sqrt() * 0.5;

    // New-bin candidate: penalize opening a bin when open bins fit well
    let is_new = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new {
        let urgency = (fitting_bins_count == 0) as i32 as f64;
        score += 25.0 * (1.0 - urgency) * (1.0 + progress);
        score -= 10.0 * urgency;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it belongs to.
    let item_class = item_size / 10;           // 0..=10 (integer division thresholds)
    let post_class = post_residual / 10;       // residual class after placement

    // Base: penalize wasted residual, but weight by item class.
    // Big items (class >= 6) should tolerate larger residuals less harshly;
    // small items should pack into tight gaps.
    let class_weight = 1.0 + 0.15 * (item_class as f64);
    score *= class_weight;

    // Perfect-fit harmonic bonus: post_residual as multiple of common item sizes (10, 20, 25, 50).
    if post_residual == 0 {
        score -= 1000.0; // exact fit is always best
    } else if post_residual % 10 == 0 {
        score -= 20.0; // residual in harmonic class 10 is reusable
    } else if post_residual % 25 == 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    } else {
        score += 8.0; // awkward residual (non-multiple of 5) is likely dead space
    }

    // Modulo coupling between item class and post class: if the leftover
    // residual class matches the current item class, a same-class item
    // may fill it later -> reward.
    if post_class == item_class && post_residual > 0 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits, but with what harmony?
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 40.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item does NOT fit here: penalize more if residual is small
            // (trapped space) and less if residual is large (still usable).
            let gap = next_item_size - post_residual;
            score += (gap as f64).min(50.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; only chosen when all
        // open-bin scores are worse (bad fits / trapped dead space).
        score += 55.0 + 0.3 * open_bins_count as f64;
    } else {
        // Reward using bins that are already fairly full (small residual).
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 25.0 * fill_ratio;
    }

    // Mean-residual steering: if this bin's residual is far below the mean,
    // it is a tight fit -> reward closing bins down.
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev;

    // Stream progression: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_ratio.max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (< 10) heavily: it's wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Moderate penalty for gaps that can't fit the smallest plausible next item.
    if post_residual > 0 && post_residual < item_size {
        score += 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residual that still accommodates the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins slightly,
    // but discourage the brand-new empty bin candidate even more.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64).sqrt() * 2.0;
    } else {
        score -= (open_bins_count as f64).ln().max(0.0);
    }

    // Early in the stream, be more willing to keep bins tight (mild).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: strongly reward leaving exactly next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: reward when next item could still fit with little slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize dead space that next item cannot use (wasted capacity).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 8.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this call is the empty-bin call and residuals elsewhere are large).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize opening new bins when existing mean residual is small (tight packing ongoing).
        score += 45.0 * pressure * (1.0 - progress * 0.3);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // New bin leaves room for the next item naturally.
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving dead space that is too small for typical future items
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.10 {
            score -= 8.0; // near-perfect closure
        } else if dead < 0.25 {
            score -= 2.0;
        } else {
            score += 3.0 * dead; // large leftover is wasteful unless reusable
        }
    }

    // Lookahead: if next item fits into the post residual, big bonus
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 2.0; // chaining impossible, slight penalty
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // open bins have poor residuals relative to the item
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // penalize new bin when existing bins fit well
        score += 20.0 - 25.0 * (1.0 - pressure) + 5.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin
        }
    } else {
        // mild preference for bins already below mean residual (consolidation)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Slight preference for fewer open bins as stream progresses
    score += 0.15 * open_bins_count as f64 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - progress) * 50.0
             - norm_pr * progress * progress * 30.0;
    score += poly;

    // Reward tight fits (high fit_ratio)
    score -= fit_ratio * fit_ratio * 10.0 * (1.0 + progress);

    // Last-chance bonus: strongly favor using a nearly-saturated option
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: penalize leaving residual that cannot fit next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 0.0 {
            score += (-gap) * 0.5 * (1.0 - progress);
        } else {
            score -= gap * 0.05;
        }
    }

    // Dead-space penalty: quadratic in unusable residual relative to capacity
    let dead = (norm_pr - (norm_pr * (next_item_size as f64 / cap).min(1.0))).max(0.0);
    score += dead * dead * cap * 0.2;

    // Slight penalty for spreading across too many bins late in the stream
    score += (open_bins_count as f64 / (total_items as f64).max(1.0)) * 100.0 * progress;

    // Alignment with mean residual: prefer bins near the mean
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fit class is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class A: tiny dead space (<= 10) is tolerable but penalized quadratically.
        if post_residual <= 10 {
            score -= 60.0 - (post_residual as f64) * 3.0;
        }
        // Class B: mid-range residual (11..=30): check if next item can use it.
        else if post_residual <= 30 {
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 80.0; // next item slots in: excellent chaining
            } else {
                score += 40.0; // likely dead space
            }
        }
        // Class C: large residual (31..=60)
        else if post_residual <= 60 {
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 40.0;
            } else {
                score += 15.0;
            }
        }
        // Class D: post_residual > 60: bin still very usable.
        else {
            score -= 25.0;
        }
    }

    // Harmonic (modulo) classes on post_residual: multiples of 10 align with
    // typical item granularity, making future packing easier.
    let pr = post_residual as u32;
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Integer-division thresholds: residual floor classes.
    let class = pr / 15; // coarse harmonic bucket
    score += class as f64 * 2.5;

    // Penalize "just barely fits" placements (wasteful tight fits) unless perfect.
    let slack = bin_residual as i64 - item_size as i64;
    if slack > 0 && slack <= 5 && post_residual > 0 {
        score += 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in
    // the stream or when the current item leaves a bad fit everywhere.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin equals the capacity (its residual).
        // Reward it when many bins are open and mean residual is high (fragmentation).
        if open_bins_count > 0 {
            let fragmentation = mean_residual / bin_capacity as f64;
            score -= fragmentation * 30.0;
        }
        // Penalize opening new bins late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 50.0;
        // If next item is large, a fresh bin is useful.
        if next_item_size >= 50 {
            score -= 30.0;
        }
    } else {
        // Slight preference for fuller bins (best-fit bias beyond post_residual).
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64).sqrt() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any future
    // item (min item size 1, but practically < ~10) are wasted capacity.
    if post_residual > 0 {
        // Small-but-nonzero gaps are the worst outcome.
        if post_residual < 10 {
            score += 40.0 + (10 - post_residual) as f64 * 3.0;
        } else if post_residual < 20 {
            score += 15.0;
        } else if post_residual < 30 {
            score += 6.0;
        }
    } else {
        // Perfect fill is highly desirable.
        score -= 30.0;
    }

    // Reward tight fits: fraction of the bin consumed by this placement.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill * fill;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, allow opening a new bin when fit is poor.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.4 * pressure;

    // New-bin candidate handling: an empty bin is attractive only when the
    // current bin would leave a tiny dead gap and the next item could use it.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10;
        if poor_fit {
            score -= 20.0;
        } else {
            // Prefer filling existing bins otherwise.
            score += 10.0;
        }
        // If lookahead item fits the post-residual, opening new bin is wasteful.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score += 15.0;
        }
    }

    // Lookahead synergy: if next item exactly fills the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 20.0;
    }
    if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // Dead space relative to the lookahead item.
        score += 0.15 * (post_residual as f64).max(0.0);
    }

    // Late in the stream, tighten up: avoid opening bins near the end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity && progress > 0.8 {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (low dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // 2-step lookahead: reward when the next item fits perfectly in the
    // remaining space, penalize when the residual is awkward for the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            // residual becomes small enough to be "dead" but usable now
            if post_residual <= 10 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: residual is dead space for the lookahead
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(60.0);
        }
    }

    // Compare against mean residual across open bins: prefer bins whose
    // residual deviates favorably (tight bins first, classic best-fit).
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin gives a decent fit (post_residual would be large elsewhere)
    // or when the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        // mild penalty so existing decent fits win
        score += 25.0 + 0.1 * openness;
        // but if item is big, a fresh bin is fine: reduce penalty
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        // late in the stream, avoid proliferating bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // if the next item is huge, a fresh bin paired with it is attractive
        if next_item_size >= 70 {
            score -= 25.0;
        }
    }

    // Slight preference for tighter bins overall.
    score += 0.05 * (bin_residual as f64 - post_residual as f64).max(0.0) * 0.0
        + 0.02 * (bin_capacity - bin_residual) as f64 * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * bin_capacity as f64;

    // Reward near-perfect fills (post_residual very small or unusable).
    if post_residual < 10 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Penalize dead space that cannot host typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bonus: only this bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: bonus if next item fits in the post-residual, penalty otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward if next item exactly complements.
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 10.0;
            }
        } else {
            score += 8.0;
            // Worse if post_residual is small-but-just-too-small (wasted).
            if post_residual >= next_item_size.saturating_sub(10) && post_residual < next_item_size {
                score += 10.0;
            }
        }
    }

    // Global state: penalize placements in bins far from mean residual
    // (keep residuals homogeneous for future flexibility).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // When many bins are open, prefer filling existing ones over opening new.
    if open_bins_count > 4 {
        if bin_residual == bin_capacity {
            score += 15.0 + 2.0 * open_bins_count as f64;
        } else {
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, prefer closing out bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty for very loose fits (post_residual large).
    if post_residual > bin_capacity / 2 {
        score += 0.3 * (post_residual as f64 - bin_capacity as f64 / 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let coupling = norm_post * norm_post * (1.0 - progress) + norm_post * progress * (1.0 - norm_post);
    score += 20.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_post) * (1.0 + progress) * 8.0;

    // Penalize residual far from mean residual (dead space asymmetry)
    let dev = (post - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_gap = (post - nxt) / cap;
            score -= 12.0 * (1.0 - fit_gap) * (1.0 + 0.5 * progress);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Penalize opening a new bin when good fitting bins exist, unless item is huge
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 && item_size < 60 {
            score += 15.0 + 10.0 * (1.0 - progress);
        } else if fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bucket it into deciles of capacity.
    let class = post_residual / 10;
    // Small classes (tight fits) are rewarded; the base post_residual already does most of it.
    score -= (10 - class.min(10)) as f64 * 0.05;

    // Reward leaving room for the lookahead item (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
        // Extra reward if the next item would leave an even tighter harmonic class.
        let next_class = (post_residual - next_item_size) / 10;
        score -= (10 - next_class.min(10)) as f64 * 0.1;
    }
    // Penalize dead space: residual too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0 + (next_item_size - post_residual) as f64 * 0.2;
    }

    // Absolute dead-space band: residuals below 10 are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin when existing bins fit.
        if fitting_bins_count > 0 {
            score += 3.0;
            // If the fit in existing bins is tight (small class), opening a new bin
            // is more acceptable; scale the penalty down.
            score -= (10 - class.min(10)) as f64 * 0.2;
        }
        // Late in the stream, opening fresh bins is relatively cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 1.5;
    } else {
        // Slight preference for bins whose residual is close to the mean (keeps spread balanced).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10) are wasted. Penalize a "dead zone" quadratically.
    let dead_zone = 10.0f64;
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * (dead_zone - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness ratio: prefer bins where item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 20.0;

    // Open-bin pressure: with many open bins, favor consolidating into existing
    // bins; a new empty bin candidate (bin_residual == bin_capacity) gets a
    // penalty that grows with open_bins_count, but relaxes late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 2.0 * (1.0 - 0.5 * progress);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item can exactly use the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            // Prefer leaving residual large enough to be reusable, but not so
            // large that it signals a wasteful split.
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.3;
        } else {
            // Next item can't fit in the leftover: leftover is dead weight
            // relative to lookahead; mild penalty scaled by leftover size.
            score += post_residual as f64 * 0.15;
        }
    }

    // Slight preference for bins whose residual is below the mean (denser bins).
    score += ((mean_residual - bin_residual as f64) * 0.05).max(-5.0).min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(6);

    // Exact fit: huge bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly or nearly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 * (-gap / 8.0).exp();
        // Perfect 2-chain: item + next item exactly fills bin.
        if gap == 0.0 {
            score -= 150.0;
        }
        // Penalize post_residual that is awkwardly small for the next item
        // (dead space the next item cannot use).
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Compare post_residual to mean residual across open bins:
    // prefer bins that end below the mean residual (consolidating space).
    score -= 15.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened if many bins are open
        // and mean residual is high (open bins are cluttered).
        let clutter = mean_residual / bin_capacity as f64;
        score = 45.0 + 30.0 * clutter;
        if next_item_size > 0 {
            // A fresh bin can host the next item perfectly if it fits item + next.
            if item_size + next_item_size <= bin_capacity {
                score -= 20.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Mild stream-phase modulation: early on, be picky (preserve flexibility);
    // late, prefer closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize tiny slivers (<10)
    // that are unlikely to be usable (items are >= 1, but slivers waste capacity).
    if post_residual > 0 && post_residual < 8 {
        score += 12.0; // dead-space penalty
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; penalize leaving moderately-sized leftovers
        // that block future packing less than small slivers would.
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its raw score (post_residual == capacity) is high, but ensure it is never
    // chosen when a reasonable fit exists in an open bin.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Late in the stream, opening new bins is less attractive (waste at end).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // Many open bins with slack: prefer reusing them.
        score += 2.0 * open_bins_count as f64;
        // If mean residual is large, open bins have room; discourage new bin.
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        // If nothing else fits (fitting_bins_count == 0 means only this new bin),
        // the +40 still applies but must not block; the caller only opens new bin
        // on lowest score, so this is consistent.
    }

    // Prefer bins whose residual is close to item size (perfect-ish fit) beyond raw post_residual:
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Mild global pressure: when many bins are open, encourage consolidation.
    if open_bins_count > 3 {
        score -= 1.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    score += 20.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space relative to mean residual (smooth interaction)
    let dead = (pr as f64 - mean_residual) / cap;
    score += 10.0 * dead * dead.abs();

    // Lookahead: reward leaving room for the next item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 8.0 * gap * gap - 6.0 * (1.0 - gap);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize mildly early, more later unless current bin is terrible
    if bin_residual == bin_capacity {
        let penalty = 12.0 + 18.0 * progress * (1.0 - norm_pr);
        score += penalty;
    }

    // Slight penalty for many open bins with large residuals (fragmentation pressure)
    score += (open_bins_count as f64).ln() * mean_residual / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "quantum" classes.
    // Small post_residual (good packing) gets heavily rewarded.
    let q = post_residual / 10; // integer division: 0..10 quantum level
    let r = post_residual % 10; // residue class

    // Reward low quantum levels (tight fits) non-linearly.
    let quantum_bonus = match q {
        0 => 40.0,
        1 => 25.0,
        2 => 12.0,
        3 => 5.0,
        _ => 0.0,
    };
    score -= quantum_bonus;

    // Residue penalty: post_residuals with residue near 0 are "clean" classes
    // that future items (multiples of 10) can fill; odd/prime residues are dead space.
    let residue_penalty = if r == 0 {
        0.0
    } else if r <= 3 || r >= 8 {
        2.0
    } else {
        4.0
    };
    score += residue_penalty;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item leaves another small residue
            let nq = (post_residual - next_item_size) / 10;
            let nr = (post_residual - next_item_size) % 10;
            let chain_bonus = if nr == 0 {
                18.0 - 3.0 * nq as f64
            } else {
                6.0 - 1.5 * nq as f64
            };
            score -= chain_bonus.max(-6.0);
        } else {
            // next item cannot use this bin's remainder anyway; mild penalty
            // scaled by how much dead space is stranded
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize unless current fits are all poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // But if post_residual of placing here would be 0 (perfect fill elsewhere
        // is impossible in an empty bin, so this is about relative attractiveness):
        // allow opening when many bins are open and mean residual is high (fragmented state).
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 20.0 * fragmentation * (open_bins_count as f64).ln().max(0.0);
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Progress-based calibration: early in the stream, prefer tight packing
    // (more bins available later); late in the stream, avoid stranding space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * quantum_bonus * 0.1;
    score += progress * 0.03 * post_residual as f64;

    // Mean-residual coupling: if this bin's residual is far below mean, it is a
    // "ragged" bin; using it cleans up the pool.
    let dev = mean_residual - post_residual as f64;
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (cannot hold even the smallest plausible item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit here; mild penalty proportional to waste.
        score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidating into
    // existing bins; few open bins -> new-bin candidate is less costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (6.0 + 8.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow it when the
        // alternative would create dead space in an existing bin.
        score += 8.0 + pressure;
        // If item fits snugly into a fresh bin, soften the penalty.
        let snug = 1.0 - item_size as f64 / bin_capacity as f64;
        score += 20.0 * snug;
    } else {
        // Existing bin: reward using bins with larger residuals (waste big gaps).
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Mild global preference for tight fits relative to bin capacity.
    score += 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match: next item fits with small slack afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next <= 10 {
            score -= 40.0;
        } else if after_next <= 25 {
            score -= 20.0;
        }
        // Reward proportional tightness of the two-step chain.
        score -= (bin_capacity as f64 - after_next as f64) * 0.15;
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize proportionally to waste.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.5;
    }

    // Penalize post_residual in the "dead zone" (too small to be useful).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual across open bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin may chain better with larger next item
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space, amplified for large items.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Reward filling bins that have small residuals (avoid fragmenting near-full bins).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slightly penalize leaving awkward gaps.
            if post_residual > 0 && post_residual < 10 {
                score += 4.0;
            }
        }
    }

    // Prefer consolidating into existing bins when many bins are open.
    score += 0.15 * open_bins_count as f64;

    // Global state: if this bin's residual is far below mean, it's a good filler target.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.05 * dev;

    // New-bin candidate: default cost of opening a new bin; cheaper early in the stream,
    // and cheaper when existing bins fit poorly (large post_residual).
    if bin_residual == bin_capacity {
        score = 45.0 + 30.0 * (step_index as f64 / total_items.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
        // Opening a bin is attractive if the item is small relative to capacity
        // and the next item is large (keeps fresh space for big arrivals).
        if next_item_size > item_size {
            score -= 8.0;
        }
        score -= 0.3 * mean_residual;
    }

    // Time horizon: later in the stream, be more conservative (prefer tight packing).
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64) * (waste / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: quadratic coupling of post-residual with stream progress.
    // Early on (t small), tight fits matter slightly less; later, dead space is heavily penalized.
    let mut score = x * x * (1.0 + 2.0 * t) + x * (0.5 - 0.3 * t);

    // Reward using bins that would otherwise waste large residuals: if this bin's
    // residual is large relative to the mean, prefer filling it.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.002 * residual_gap * (1.0 + t);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // (avoid opening a new bin for a mediocre fit).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * t;
    }

    // Penalty for opening a brand-new bin when open bins could fit:
    // allow it only when the item fits very snugly in a fresh bin AND few bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let snug = 1.0 - (item_size as f64 / cap); // small when item nearly fills bin
        let lookahead_waste = if next_item_size > 0 {
            let nr = next_item_size as f64;
            ((cap - item_size as f64) - nr).max(0.0) / cap
        } else {
            0.0
        };
        score = 10.0 + 6.0 * t + 4.0 * snug + 5.0 * lookahead_waste
            - 1.5 * (open_bins_count as f64).ln().max(0.0);
        // If the item nearly fills a fresh bin, opening is actually good.
        if snug < 0.05 {
            score -= 12.0;
        }
    }

    // Smooth lookahead coupling: prefer leaving a post-residual close to the next item size.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        score += 1.5 * diff * diff;
        // Exact-match bonus for chaining items.
        if post_residual == next_item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds on post_residual: residuals divisible into nice future chunks
    // (multiples of 25 and 50) are more reusable, reward them.
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Harmonic class of item_size relative to capacity (1/2, 1/4, 3/4 items combine well).
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let three_quarter = 3 * quarter;
    if item_size == half || item_size == three_quarter {
        score -= 3.0;
    } else if item_size == quarter {
        score -= 2.0;
    }

    // Modulo coupling: if post_residual can exactly host the next item (or a harmonic
    // fraction of it), strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            if (post_residual - next_item_size) % 25 == 0 {
                score -= 6.0;
            }
            if post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Perfect fit dominates everything.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Tiny dead space is nearly as good.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && post_residual < half {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a mild default score; prefer using
    // existing bins with good fits, but allow opening a new bin when current bins
    // are crowded and mean residual is small.
    if bin_residual == bin_capacity {
        score = cap * 0.55;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 1.2 && open_bins_count > 2 {
            score -= 10.0 + 10.0 * progress;
        }
        if next_item_size > 0 && next_item_size >= half {
            score -= 5.0; // big item coming, fresh bin is valuable
        }
    }

    // Slight preference to fill bins that are already low on residual (tight packing).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Mean-residual coupling: bins far below mean residual are worse targets early on.
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight packing relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into existing bins
    // rather than spreading out when many bins are open.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item can use the post_residual, reward it.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
    }

    // Mean residual coupling: bins far below mean residual are less attractive
    // (they hold more future potential); prefer bins already fragmented.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 20.0 * dev;

    // New-bin candidate: penalize opening a new bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        // Opening a new bin is fine if no existing bin fits well.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills the remainder -> big reward.
            let chain = post_residual - next_item_size;
            score -= 25.0 * (1.0 - (chain as f64) / (bin_capacity as f64));
        } else {
            // Next item cannot fit here; penalize residual slightly below next_item_size
            // (wasted dead space relative to lookahead).
            score += 8.0 * (1.0 - gap / (bin_capacity as f64));
        }
    }

    // Relative to mean residual: bins with more slack than average are better targets
    // for large items; bins below mean residual should absorb small items.
    if post_residual as f64 > mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; penalize if open bins already fit the item well.
        score += 30.0;
        if fitting_bins_count > 0 && post_residual + item_size <= bin_residual {
            // There exists an open bin that fits; opening a new bin is wasteful unless
            // the fit there is terrible (large post_residual elsewhere).
            score += 10.0;
        }
        // Early in the stream, opening bins is cheaper (spread items for future flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // Few open bins -> new bin is relatively more acceptable.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Small penalty for extremely large leftover dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // near-perfect fill is excellent
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0; // awkward sliver zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty unless current bins are badly fragmented.
        let fragmentation = (mean_residual - item_size as f64).abs();
        score += 15.0;
        // If mean residual is large and close to item, prefer existing bins.
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
        // Late in the stream, prefer reusing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Many open bins: discourage adding another.
        score += 2.0 * open_bins_count as f64;
        // Dead-space penalty scaled by fragmentation.
        score += 0.05 * fragmentation;
        // If the next item is large, a fresh bin is more attractive (leave room elsewhere).
        if next_item_size > 60 && post_residual == bin_capacity as u32 {
            score -= 8.0;
        }
    } else {
        // Lookahead: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 && (post_residual as u32) == next_item_size {
            score -= 20.0;
        } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 6.0;
        } else if next_item_size > 0 && (post_residual as u32) > 0 && (post_residual as u32) < next_item_size {
            // Creating dead space that next item cannot use.
            score += 5.0 + 0.1 * (next_item_size - post_residual) as f64;
        }

        // Prefer bins whose residual is below mean (consolidating fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Mild global regularization: fewer open bins is better, encourage filling.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_norm = post / cap;

    // Base: quadratic penalty on wasted space after placement.
    let mut score = residual_norm * residual_norm * cap;

    // Smooth non-linear coupling of waste with stream progress:
    // late in the stream, wasted space becomes increasingly costly.
    score *= 1.0 + 1.5 * progress * residual_norm;

    // Reward tight fits (small post_residual) with a cubic discount.
    let tightness = 1.0 - residual_norm;
    score -= 12.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening new bins, more so when
    // open bins exist and the stream is late; relax when the item
    // leaves a large usable residual (good for future items).
    if bin_residual == bin_capacity {
        let mut open_penalty = 15.0 + 10.0 * progress;
        if open_bins_count > 0 {
            open_penalty += 3.0 * (open_bins_count as f64).ln();
        }
        // If the resulting residual is large and matches the next item,
        // opening a new bin is less bad.
        let next_fit = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score = post + open_penalty - 10.0 * next_fit * (1.0 - 0.5 * progress);
    } else {
        // Mild reward if leftover residual can still host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0 * (1.0 - residual_norm);
        }
    }

    // Coupling with mean residual: prefer bins whose residual is near
    // the mean (balanced packing), via a smooth quadratic term.
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; post_residual dominates.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Harmonic class of post_residual: exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Modular class logic: residuals divisible into friendly classes
    // (multiples of 10 pair well with typical item sizes).
    let pr_class = post_residual % 10;
    let nxt_class = (next_item_size as u32) % 10;
    if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits here too: strong reward, tighter coupling when classes align.
        let align_bonus = if pr_class == nxt_class { 60.0 } else { 25.0 };
        score -= align_bonus + (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 && next_item_size <= bin_capacity && post_residual < next_item_size {
        // Dead space that the lookahead cannot use: penalize proportionally.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.6 * waste;
        // Harmonic penalty: residual in an awkward class is harder to fill later.
        if pr_class >= 5 {
            score += 8.0;
        }
    }

    // Capacity-fraction thresholds on post_residual.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        score -= 40.0; // nearly full bin: good to seal it
    } else if post_residual <= half {
        score -= 10.0;
    } else {
        // Large residual left: mild penalty unless it matches a harmonic band.
        let band = post_residual / 10;
        if band % 2 == 0 {
            score += 5.0;
        } else {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large and existing residuals are poorly matched (bad harmonic classes).
    if bin_residual == bin_capacity {
        let avg_bad_fit = if next_item_size > 0 {
            (mean_residual - nxt).abs()
        } else {
            mean_residual
        };
        let open_benefit = item - avg_bad_fit.max(0.0);
        // Default: discourage new bin; allow it only if item is big and fits badly elsewhere.
        score += 300.0 - open_benefit.clamp(0.0, 250.0);
        if fitting_bins_count == 0 {
            score -= 400.0; // must open
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 30.0;

    // Mild penalty for spreading across too many bins when mean residual is high.
    if (mean_residual - pr).abs() < 5.0 && open_bins_count > 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (1.0 + (10 - post_residual as i32) as f64 / 10.0);
    } else if post_residual > 9 && post_residual <= 20 {
        // Medium gaps: mild penalty, they may still fit small future items.
        score += 4.0;
    }

    // Reward tight fits (exact fill or near-exact) strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    score += pressure;

    // New-bin candidate (empty bin): normally penalized so we reuse bins,
    // but attractive if no open bin fits well or the item is large.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin anyway
        } else if item_size >= 70 {
            score -= 20.0; // large items may merit a fresh bin
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item would fit perfectly in the post_residual,
    // reward leaving exactly that gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 9 {
        // leaving a gap that almost-but-not-quite fits next item: mild penalty
        score += 3.0;
    }

    // Slight preference for bins whose residual is below the mean (fill emptier bins less).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is good.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post / cap);
    score -= 8.0 * tightness * tightness * (item_size as f64);

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            let fill_after_next = post - next;
            // Perfect two-item packing bonus
            score -= 12.0 * (1.0 - (fill_after_next / cap)) * (next / (item_size.max(1) as f64));
            if fill_after_next == 0 {
                score -= 25.0; // exact match: bin becomes perfectly full
            }
        } else {
            // Next item won't fit here; penalize leaving a gap that next item overshoots.
            let overshoot = next - post;
            score += 0.35 * overshoot.min(cap);
        }
    } else {
        // Last item: strongly prefer minimal residual.
        score -= 20.0 * (1.0 - (post / cap));
    }

    // Penalize creating dead space that is too small for typical future items.
    if post > 0 && post < 10 {
        score += 15.0;
    }

    // Relative to mean residual: prefer bins whose residual deviates favorably.
    score -= 1.5 * (mean_residual - post);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // New-bin candidate: empty bin should only win when current fit is bad.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * (item_size as f64);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate more strongly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - (post / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

