    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving space that nothing else can use soon.
            score += 3.0 * (pr / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Global state: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Mean residual coupling: prefer bins close to the mean residual (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: empty bin gets a moderate penalty so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 40.0 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: opening a new bin is necessary
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let shape = 1.0 + 0.6 * progress * (1.0 - progress) * 4.0; // hump mid-stream
    score *= shape;
    // Penalize large residuals more than linearly (dead space) as stream progresses
    score += (norm_pr * norm_pr) * cap * (0.3 + 0.5 * progress);
    // Reward tight fits (small post_residual) with a smooth cubic term
    score -= (1.0 - norm_pr).powi(3) * 8.0 * (1.0 - progress);
    // Penalize creating residual that is too small for typical next items
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let waste = (pr - ns) / cap;
            score += waste * waste * cap * 0.4;
        } else {
            score += 5.0 * (1.0 - progress);
        }
    }
    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }
    // Mild penalty for spreading across many open bins late in stream
    score += (open_bins_count as f64).ln().max(0.0) * (0.5 * progress);
    // Pull toward mean residual: prefer bins with residual near mean (smooth coupling)
    let diff = (pr - mean_residual) / cap;
    score += diff.abs() * 4.0 * progress;
    // New-bin candidate: penalize mildly unless current residuals are all poor
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quanta of 10 divide capacity into 10 classes.
    let pr = post_residual as f64;
    let quantum = (pr / 10.0).floor(); // integer division class
    let rem = pr - quantum * 10.0;     // remainder within class

    // Reward post-residuals that are exact capacity fractions (harmonic slots).
    let frac = pr / cap;
    let harmonic_bonus = if (pr == 0.0)
        || (pr == cap * 0.5)
        || (pr == cap * 0.25)
        || (pr == cap * 0.75)
        || (pr == cap * 0.2)
        || (pr == cap * 0.4)
        || (pr == cap * 0.6)
        || (pr == cap * 0.8)
        || (pr == cap / 3.0)
        || (pr == cap * 2.0 / 3.0)
    {
        -18.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize dead space in awkward classes (post_residual mod 10 near edges).
    score += (rem - 5.0).abs() * 0.8;

    // Small post-residuals are good: quadratic shrink.
    score -= 60.0 * (1.0 - frac) * (1.0 - frac) * 0.5;

    // Lookahead coupling: if next item fits the post-residual, big reward.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let tight = (pr - ni) / cap; // leftover after chaining
            score -= 25.0 * (1.0 - tight) + 10.0 * (ni / cap);
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += 6.0 * (ni / cap) * (1.0 - pr / cap);
        }
    } else {
        // Last item: prefer zero residual strongly.
        score -= 40.0 * (1.0 - frac);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline; open only if open bins are crowded
    // or this is a fresh stream start.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = cap as f64 * 0.55 + 20.0 * crowding - 15.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 5.0;
        }
    }

    // Mild preference for bins tighter than the mean residual (best-fit flavor).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are "dead". Penalize them quadratically.
    let dead_threshold = 10.0_f64.min(mean_residual.max(1.0));
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64).powi(2) * 2.0;
    }

    // Perfect fit reward: leaving nothing behind is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual as f64 <= 5.0 {
        score -= 20.0; // near-perfect fit
    }

    // Penalize large post_residual waste relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Lookahead: if the next item fits into the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // next item can't use this gap -> dead space risk
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a new bin wastes the residual of this empty
    // bin; only allow it when the current fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
        // opening a fresh bin is fine if the current item leaves a huge gap
        // in every existing bin anyway (post_residual large)
        if post_residual as f64 >= mean_residual {
            score -= 30.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack);
    }
    // Penalize residuals too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to the mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= 0.3 * (mean_residual - post_residual as f64);
    } else {
        score += 0.2 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            let tight_exists = next_item_size > 0 && post_residual == next_item_size;
            if !tight_exists {
                score += 20.0;
            }
            // Discourage spreading across many bins early on.
            score += 3.0 * open_bins_count as f64;
        }
    }

    // Late in the stream, prefer minimizing bin count: favor existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal waste after placement.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let tightness = 1.0 - (post / cap); // 1.0 = perfect fit
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that no plausible item can use.
    // Items range 1..=100; residual below ~10 is nearly dead.
    if post_residual > 0 && post_residual < 12 {
        score -= 6.0; // small dead space is fine, item almost fills bin
    } else if post_residual >= 12 {
        // residual that could fit a mid/small item is reusable
        score -= 4.0 * ((post_residual as f64).ln() / (cap.ln()));
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize bins where placing now blocks a better chain.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 8.0 * (1.0 - post / cap) * (nxt / cap);
        } else {
            score += 3.0 * (1.0 - post_residual as f64 / nxt);
        }
        // If next item exactly fills post-residual, strongly favor this bin.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation into fewest bins.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New-bin candidate logic: opening a new bin is penalized when decent fits
    // exist, but allowed when all open bins would leave large unusable gaps.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 10.0;
        // If every existing fitting bin would leave big waste, new bin is better.
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative at all
        } else if fitting_bins_count == 1 {
            score -= 5.0; // only marginal alternative
        }
        // Late in stream, opening bins is cheaper than fragmenting many.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * progress;
        // Many open bins with high mean residual: prefer using them.
        score += 0.15 * open_bins_count as f64 * (mean_residual / cap).clamp(0.0, 1.0);
    }

    // Global consolidation pressure: when few bins are open, keep them tight.
    let pressure = 1.0 / (1.0 + open_bins_count as f64);
    score -= 5.0 * pressure * tightness;

    // Mean-residual coupling: if this bin is far below average residual,
    // it is "sparser" — mildly discourage dumping large items there.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * (item_size as f64 / cap);

    // Time horizon: early on, keep residuals flexible; late, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - progress) * (post / cap);      // early: dislike large leftovers
    score -= 4.0 * progress * tightness * tightness;     // late: reward tight fits extra

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Reward tight fits more strongly as stream progresses (smooth polynomial coupling).
    let tightness = 1.0 - norm_pr;
    let progress_gain = prog * prog * (1.0 - prog);
    score -= 40.0 * tightness * tightness * (0.5 + progress_gain * 2.0);

    // Penalize large dead space quadratically, scaled by stream progress.
    score += 25.0 * norm_pr * norm_pr * (0.3 + prog);

    // Last-chance bin bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * prog);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap)) * (0.5 + prog);
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty proportional to wasted potential.
        score += 6.0 * norm_pr * (0.4 + prog);
    }

    // Prefer filling bins when many bins are open (bin consolidation pressure).
    let open_pressure = (open_bins_count as f64).ln_1p() / (1.0 + cap / 100.0);
    score -= 8.0 * open_pressure * tightness;

    // Deviation from mean residual: favor bins below mean residual (tighter bins).
    let dev = (mean_residual - pr) / cap;
    score -= 10.0 * dev;

    // New-bin candidate: penalize opening a new bin unless residuals are all poor.
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 18.0 * (1.0 - mean_norm) * (0.5 + prog) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (post_residual in 1..=9)
    // are heavily penalized since almost no item can use them.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 15.0;
    }
    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = if item_size > 0 {
        (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64
    } else { 0.0 };
    score -= tightness * 8.0;

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is genuinely good.
    score += open_bins_count as f64 * 0.6;

    // Prefer bins whose residual deviates favorably from the mean residual:
    // placing into a below-average-residual bin keeps big gaps consolidated.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.4;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Lookahead: if the next item would fit exactly into the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover gap; penalize proportionally.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the empty-bin baseline moderately high
    // so only genuinely poor fits in open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        // Dead-space created in a fresh bin is worse than in a partially used one.
        score += 18.0;
        if post_residual < 20 {
            score += (20 - post_residual) as f64 * 4.0;
        }
    }

    // Slight late-stream consolidation: as the stream progresses, favor
    // filling existing bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        // Perfect lookahead match: next item exactly fills the bin afterwards.
        if next <= pr {
            let leftover_after_next = pr - next;
            score -= 45.0 * (1.0 - leftover_after_next / bin_capacity as f64);
            // Extra bonus if next item fits perfectly (leftover 0..=small)
            if leftover_after_next <= 5.0 {
                score -= 30.0;
            }
        } else {
            // Next item does NOT fit here: penalize leaving residual close to but below next size (wasted dead space).
            let gap = next - pr;
            score += 20.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer minimal post residual.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual near mean are "average" candidates;
    // large residual bins should be preferred for large items to consolidate load.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.3 * mean_gap.abs();

    // Penalize creating very small unusable residuals (dead space) unless next item uses them.
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists (high dead-space risk elsewhere).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 - 40.0 * tightness;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Prefer new bin late in stream when many bins are open and fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Slight preference for fuller bins overall (best-fit flavor).
    score -= 0.1 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no plausible future item (>= 1) could use well:
    // small post_residual is fine; large post_residual with small fit_ratio is wasteful.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress); // early on, tiny slivers are less valuable
    }

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + next_tight);
        if post_residual == next_item_size {
            score -= 35.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for hoarding space it could use elsewhere.
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly discourage opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
        if post_residual <= 20 {
            score -= 20.0;
        }
    }

    // Prefer bins with below-mean residual (consolidate emptier space usage).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Discourage spreading across too many open bins when few remain to be filled.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when the item is large and no tight option exists,
    // or late in the stream where a fresh bin amortizes over many future items.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_alternatives = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let fresh_value = 25.0 * large_item + 20.0 * (1.0 - progress) + 30.0 * poor_alternatives;
        // Baseline cost of a new bin roughly equals wasted capacity if item is small.
        score = score.max(0.0) + (post_residual as f64) - fresh_value + 100.0 * (1.0 - large_item) * (1.0 - poor_alternatives);
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;
    let is_new = (bin_residual as u64 == bin_capacity as u64) as f64;

    let mut score = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let wave = (progress * std::f64::consts::PI).sin();
    score += 8.0 * pr * pr * (1.0 - progress) * cap;
    score -= 6.0 * pr * wave * (item_size as f64 / cap);
    score += 4.0 * pr * progress * (mean_residual / cap);

    // Penalize near-full dead space smoothly (quadratic in tightness)
    let tight = (cap - post) / cap;
    score += 3.0 * tight * tight * post;

    // Last-chance bonus (smoothly scaled)
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - pr);
    }

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        score -= 5.0 * (next_item_size as f64 / cap);
    }

    // New-bin penalty grows with number of open bins and progress
    score += is_new * (6.0 + 14.0 * progress + 0.5 * open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: very small post_residual is fine (tight fit), mid-range is bad.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 15 {
        score -= 8.0;
    } else if pr > 50 {
        score += 12.0; // wasteful large leftover
    }

    // Harmonic class: post_residual modulo buckets
    let class = pr % 10;
    let class_bonus = match class {
        0 => 15.0,
        1 | 9 => 6.0,
        2 | 8 => 2.0,
        4 | 6 => -3.0,
        5 => -6.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 20.0;
            // extra reward if next item exactly fills (pairing)
            if next_item_size == pr {
                score -= 30.0;
            }
            // integer division threshold: next item uses most of the leftover
            if next_item_size * 100 / pr.max(1) >= 80 {
                score -= 10.0;
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.3; // leftover unusable for next
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.7 {
            score -= 10.0; // big item: fresh bin is okay
        } else {
            score += 30.0; // prefer filling existing bins with small items
        }
        // many open bins with slack: discourage another
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 25.0;
        }
    }

    // Prefer filling bins with low residual relative to mean (balance consolidation)
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Late stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space is worse late in the stream (less chance to fill gaps).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * 0.8 * progress;

    // Open-bin pressure: discourage spreading across many bins when
    // this placement creates significant dead space.
    score += (open_bins_count as f64) * 0.5 * (post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Prefer bins tighter than average (better packing).
    score += ((mean_residual - bin_residual as f64) * 0.3).max(-20.0).min(20.0);

    // New-bin candidate: make opening a new bin costly unless this item
    // is large relative to residual (i.e. poor fit everywhere else).
    if bin_residual == bin_capacity {
        let tight_fit_everywhere = fitting_bins_count == 0;
        if !tight_fit_everywhere {
            score += 40.0 + 0.5 * (bin_residual as f64 - item_size as f64);
        } else {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // leftover after hypothetical next placement
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.8;
        } else {
            // next item cannot follow here; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Dead space penalty: small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Compare residual to mean residual: prefer bins that are already fuller
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize slightly unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 120.0;
        // but if lookahead item would pair well with a fresh bin, reduce penalty
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.9 {
            score -= 100.0;
        }
    }

    // Mild preference for consolidating: fewer open bins is better
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize unusable dead space: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize less if other bins can take the item.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: only open a new bin when fits are poor or item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > bin_capacity as f64 / 2.0;
        if poor_fit || item_size > bin_capacity * 3 / 4 {
            score -= 4.0 + 8.0 * progress;
        } else {
            score += 15.0;
        }
    }

    // Global state: many open bins with low mean residual -> consolidate; else spread.
    let pressure = mean_residual / bin_capacity as f64;
    score += 0.3 * pressure * (open_bins_count as f64);

    // Time horizon: late in the stream, prefer keeping residuals balanced and tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (bin_residual as f64 / bin_capacity as f64);

    // Mild preference for fuller bins overall.
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    // Late in the stream, residual space becomes more valuable (harder to fill later).
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear penalty for awkward residual sizes (dead space): residual near
    // minimum item size wastes capacity; quadratic coupling with progress.
    let dead = if pr > 0 {
        let d = 1.0 - (pr as f64 / (cap * 0.5)).min(1.0);
        d * d
    } else {
        -0.5 // perfect fit bonus
    };
    score += 6.0 * dead * (0.5 + progress);

    // Reward tight fits: non-linear in normalized fill ratio.
    let fill = 1.0 - norm_pr;
    score -= 4.0 * fill * fill * (1.0 + progress);

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            let fit_quality = 1.0 - (pr as f64 - nxt) / cap;
            score -= 3.0 * fit_quality * fit_quality;
        } else {
            score += 2.0 * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.05 * (open_bins_count as f64 - mean_residual / 10.0);

    // New-bin candidate: penalize mildly so it only wins when fits are terrible,
    // with the penalty decaying as the stream progresses (early exploration).
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: prefer residuals in "usable" classes
    // (multiples of 10 / large residuals) over awkward small dead space.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // penalize awkward residues (1..9) proportionally
        score += class as f64 * 0.8;
        // residuals divisible by 10 are reusable by typical item sizes
        if class == 0 {
            score -= 6.0;
        }
        // dead space: residual too small for any item (min size 1 -> all usable,
        // but tiny residuals < 12 are near-dead given typical item sizes)
        if pr < 12 {
            score += 25.0;
        }
        // harmonic banding: quantize residual into capacity fractions
        let frac = (pr as f64) / (bin_capacity as f64);
        if frac > 0.5 {
            score -= 10.0; // half-full or more remaining: very usable
        } else if frac > 0.25 {
            score -= 3.0;
        } else {
            score += 8.0; // sparse leftover
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; slight penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so it is
    // chosen only when open bins have poor fits.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin attractive
        }
        if step_index > 0 && open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Spread load: prefer bins whose residual deviates favorably from mean.
    let dev = (bin_residual as f64) - mean_residual;
    score -= dev * 0.05;

    // Slight preference to fill earlier bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
