    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual (waste fraction penalty).
    if bin_residual > 0 {
        let waste_frac = post_residual as f64 / bin_residual as f64;
        score += 30.0 * waste_frac;
    }

    // Last chance: strongly prefer using this bin over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins tighter than the mean residual (already small gaps).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize leaving a gap the next item cannot use but that is nearly its size.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && post_residual < next_item_size + 5 {
        score += 15.0;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: heavily reward tight packing.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small dead space more than proportionally (unusable gaps).
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 40.0; // tiny gap is wasted capacity
        }
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // chain fit: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional closeness of next item to post_residual
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fit_ratio;
            if slack < 10.0 {
                score += 15.0; // near-miss leaves tiny unusable gap after next item
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins as stream matures, unless residual is large/useful.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * progress;
        // But a new bin is fine if it enables a perfect chain with next item.
        if next_item_size > 0 && bin_capacity == item_size + next_item_size {
            score -= 70.0;
        }
        // New bin attractive when open bins have small residuals anyway.
        if (mean_residual as u32) < item_size {
            score -= 25.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
