    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 6.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize slightly if we waste residual capacity.
        score += 0.15 * post_residual as f64;
    }

    // Prefer fuller bins over emptier ones when residuals are similar.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus time-varying penalty.
        score = bin_capacity as f64 + 20.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
        // If no open bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

