}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fits mildly; late in stream, penalize large residuals strongly.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score += 30.0 * (1.0 - progress) * poly * cap;

    // Reward near-perfect fits smoothly (small post_residual gets extra discount).
    score -= 12.0 * (-pr / 18.0).exp() * (1.0 + 0.5 * progress);

    // Penalize creating dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 6.0 * (gap / cap) * (1.0 + progress);
    }

    // Last-chance bonus: smooth reward when few fitting bins exist.
    if fitting_bins_count > 0 {
        score -= 8.0 / fitting_bins_count as f64;
    }

    // Mild preference toward fuller bins relative to mean residual.
    score -= 0.3 * (mean_residual - pr);

    // Penalize opening new bins when open bins exist, scaled by progress.
    if bin_residual as f64 == cap {
        score += 20.0 + 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (capacity fractions)
    let class = post_residual % 10;
    let quarter = bin_capacity / 4;

    // Reward residuals that belong to "usable" harmonic classes (multiples of 10,
    // and residuals >= quarter are still reusable)
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if class == 0 {
        score -= 30.0;   // round residual, easy to fill later
    } else if class <= 5 {
        score += 10.0;   // awkward small dead space
    } else {
        score += 20.0;
    }

    // Penalize large post_residual less if it can host the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= next_item_size as f64;
    } else if next_item_size > 0 {
        score += next_item_size as f64 * 0.5;
    }

    // Last-chance bin before opening a new one: strong bonus
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Dead-space penalty: residuals below quarter are near-useless
    if post_residual < quarter && post_residual > 0 {
        score += (quarter - post_residual) as f64 * 2.0;
    }

    // Slight preference to fill bins when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Mild drift with stream progression: become more conservative early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    // Tie-break with tightness of fit
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
