        score += (20 - post_residual) as f64 * 1.5;
    } else {
        // Larger leftover space is more reusable: mild reward.
        score -= (post_residual as f64 - 20.0) * 0.05;
    }

    // Perfect fit: extremely desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit bonus relative to the item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no tight fit exists
    // among open bins (i.e., accepting here would create large dead space).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0 + open_bins_count as f64 * 0.8;
        // But if the item is large and would leave a big gap in any open bin,
        // a fresh bin is better than fragmenting.
        if post_residual >= item_size as u32 / 2 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chained packing).
    if next_item_size > 0 {
        if next_item_size as f64 == post_residual as f64 {
            score -= 45.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the leftover: penalize small leftovers more.
            if post_residual < next_item_size as u32 && post_residual < 30 {
                score += 12.0;
            }
        }
    }

    // Mean residual coupling: when open bins are already quite empty on
    // average, avoid adding another half-empty bin.
    if bin_residual != bin_capacity {
        score += (mean_residual - post_residual as f64).max(0.0) * 0.1;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // 2-step lookahead: reward bins where the next item fits the post-residual well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step match: huge reward
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize proportionally to overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.3 * overflow;
        }
    }

    // Penalize small dead space that is hard to fill (post_residual < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Relative to mean residual: prefer bins below the mean residual (tighter bins)
    score += 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * item_size as f64;
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, prefer compacting into open bins;
    // late in the stream, tight fits matter more.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Penalize small post-residuals that create unusable dead space,
    // but only if the next item cannot use them.
    if post_residual > 0 && (next_item_size as u32) > post_residual {
        let dead = post_residual as f64;
        score += dead * (0.6 + 1.4 * progress);
    }

    // Reward perfect-ish fits (post_residual small but next item might use it).
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let fit_quality = (next_item_size as f64) / (post_residual as f64).max(1.0);
        score -= 18.0 * fit_quality * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score -= 25.0 * (1.0 - waste_ratio);
    }

    // New-bin candidate: penalize opening a new bin when decent alternatives
    // exist; allow it when the stream is early and future items are large,
    // or when this bin would otherwise be a poor fit.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 + 20.0 * progress;
        let lookahead_bonus = if next_item_size > item_size { 10.0 } else { 0.0 };
        score += base_penalty - lookahead_bonus;
        // If no open bin fits well, opening a new bin is less bad.
        if post_residual > (bin_capacity as u32 / 2) {
            score -= 15.0;
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // favor bins below mean residual (consolidation pressure).
    let dev = mean_residual - bin_residual as f64;
    score += 0.35 * dev * (1.0 + (open_bins_count as f64).ln().max(0.0)) * (1.0 - progress);

    // Mild reward for exact capacity utilization.
    let util = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * util * util;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize wasted residual, quadratically (dead space is doubly bad).
    let mut score = pr * (1.0 + pr / cap);

    // Smooth stream-progress coupling: later in the stream, tighten fits harder
    // (quadratic ramp up to ~2x penalty on residual).
    score += pr * (1.0 + progress * progress);

    // Non-linear coupling of post_residual with mean residual: if this bin's
    // leftover is far below the mean, we are creating a small awkward pocket —
    // penalize; a leftover near/above the mean keeps the bin family usable.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * cap * 0.05 - 4.0 * dev;

    // Lookahead: reward bins whose post_residual can still host the next item,
    // scaled non-linearly by how snugly it would fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - (pr - nxt) / cap; // 1 = perfect next-fit
            score -= 6.0 * snug * snug;
        } else {
            // Post-residual too small for lookahead: penalize proportionally.
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin,
    // with a smooth urgency term that grows with stream progress.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when all open
    // bins would leave terrible dead space. Penalize opening bins early.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "usable"
    // classes (multiples of 10, or large enough for typical items) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap; // capacity fraction remaining

    // Penalize dead space via modulo classes: leftover % 10 == 0 is perfectly
    // reusable in integer-sized streams; odd/wasted slivers are penalized.
    let class = (pr % 10) as f64;
    score += class * 0.35;

    // Integer-division thresholds: classify leftover into harmonic bands.
    if pr >= 50 {
        score -= 6.0; // half-full or more: very reusable
    } else if pr >= 30 {
        score -= 3.0;
    } else if pr >= 10 {
        score -= 1.0;
    } else if pr > 0 {
        score += 8.0; // unusable sliver: dead space penalty
    }

    // Lookahead coupling: reward if next item fits exactly in the post residual
    // (harmonic match), penalize if it nearly fits (creates future fragmentation).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0; // perfect harmonic pairing
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.25;
        } else {
            score += 2.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (mean_residual / cap).max(0.1);
        score = cap as f64 + 5.0 + crowd * 2.0 - progress * 3.0;
        if item_size > 60 {
            score -= 4.0; // big items start fresh bins more willingly
        }
    }

    // Small global tightening as the stream progresses (prefer consolidation).
    score -= frac * 2.0 + (step_index as f64).sqrt() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strict dead-space avoidance archetype with open-bin pressure.
    let mut score = post_residual as f64;

    // Penalize small unusable dead spaces: gaps that no plausible item can fill.
    // Dead space = post_residual in (0, min_item) or awkward mid-range gaps.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver -> heavy penalty.
            score += 25.0;
        } else if post_residual <= 30 {
            // Awkward gap: only small items could ever fit; penalize proportionally.
            score += (30.0 - post_residual as f64) * 0.8;
        }
    }

    // Reward exact / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Coupling: tightness relative to bin_residual (fill fraction).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already fragmented; encourage opening new bins when open bins are few
    // and current fit is poor.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.15 * open_pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that is beaten only
    // by genuinely good fits in open bins.
    if bin_residual == bin_capacity {
        // Mild penalty so only high-dead-space alternatives lose to it.
        score += 5.0;
        // If the next item is large and current item is small, opening a fresh
        // bin can be wise (preserve large contiguous space).
        if next_item_size > 60 && item_size < 40 {
            score -= 8.0;
        }
    } else {
        // Penalize burning large contiguous space on small items.
        if item_size < 30 && bin_residual > 70 {
            score += 6.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 8.0;
        }
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual closely matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let perfect = if post_residual == next_item_size { -25.0 } else { 0.0 };
        score -= perfect;
        score += gap * 0.6;

        // If next item fits exactly after this placement, strongly favor.
        if post_residual >= next_item_size && post_residual - next_item_size < 5 {
            score -= 12.0;
        }
        // Penalize dead space that cannot fit the next item.
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Tight fits preferred: reward small post residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 8.0;

    // Relative to mean residual: prefer bins that keep residual near/below mean.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strong reward to use it rather than open new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize creating tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 10.0;
    }

    // Late in stream: prefer closing bins tightly, discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no good fit exists (large item, tight elsewhere).
        score += 18.0 - 14.0 * progress;
        if next_item_size > 0 && bin_capacity as f64 - item_size as f64 >= next_item_size as f64 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small dead space (unusable by typical items) gets penalized extra.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.1 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize wasting residual that's too small.
            score += 6.0;
        }
    }

    // Prefer filling more-full bins when many bins are open (reduce spread).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // When open bins have high mean residual, discourage leaving this bin messy.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Early in stream: be more open to opening new bins (long horizon to consolidate);
    // late in stream: squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 18.0 * (0.3 + 0.7 * progress);
        // But if no open bin fits well, allow new bin early.
        if fitting_bins_count == 0 {
            score -= 20.0 * (1.0 - progress);
        }
        // Don't open a new bin if an open bin fits the next item too after placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
    } else {
        // Existing bin: late-stream urgency to use it.
        score -= 10.0 * progress;
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a smooth non-linear penalty on residual
    let mut score = pr as f64;

    // Non-linear coupling: residual cost grows superlinearly as stream progresses
    // (late in the stream, small residuals matter more since fewer items remain to fill them)
    let progress_coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += 20.0 * progress_coupling;

    // Smooth reward for near-perfect fits (post_residual close to 0)
    let tight_fit = (-norm_pr * 8.0).exp();
    score -= 15.0 * tight_fit * (0.5 + progress);

    // Lookahead coupling: penalize if next item cannot use the post-residual,
    // reward smooth overlap when it can
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let overlap_quality = 1.0 - (pr - ni) / cap;
            score -= 12.0 * overlap_quality * overlap_quality;
        } else {
            let waste = (ni - pr) / cap;
            score += 10.0 * waste * waste * (0.5 + progress);
        }
    }

    // Last-chance bin: strong smooth penalty for wasting the only fitting bin on a loose fit
    if fitting_bins_count == 1 {
        score += 8.0 * norm_pr * (1.0 - progress);
    }

    // New-bin candidate handling: make empty bins mildly attractive early,
    // expensive late (encourage closing out open bins at the end)
    if bin_residual == bin_capacity {
        score = 30.0 * (1.0 - progress) + 10.0 * (open_bins_count as f64).sqrt() * (0.3 + progress);
        // If no open bin fits well, empty bin wins
        if post_residual < bin_capacity {
            score += pr as f64 * 0.1;
        }
    }

    // Mild tie-breaking toward consolidating mean residual
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into octaves.
    let post_class = post_residual / (bin_capacity / 4);
    match post_class {
        0 => score -= 25.0,           // near-perfect fill
        1 => score -= 8.0,            // good fill
        2 => { score += 4.0; }        // mediocre
        _ => { score += 15.0; }       // wasteful
    }

    // Reward if the next item fits exactly into the post residual (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; penalize proportionally to how much space dies.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.3 * dead;
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless residual is tiny.
    if bin_residual == bin_capacity {
        let mean_ok = mean_residual < 0.35 * cap;
        let early = (step_index as f64) / (total_items.max(1) as f64);
        if mean_ok { score -= 6.0 * (1.0 - early); } else { score += 10.0; }
    }

    // Modulo-based harmonic bonus: residuals divisible by common item sizes are reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 25 == 0 { score -= 3.0; }

    // Slight preference for bins tighter than the current mean residual.
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<= 10) are nearly unusable
    // since item sizes are >= 1 but typically >= 10; penalize them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    } else if post_residual > 60 {
        // Large leftover is good (flexible space), reward it.
        score -= 10.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin; if post_residual is too small for the
    // next item anyway, the dead space is less costly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score -= 8.0; // gap unusable for next item anyway
        } else {
            let nxt_gap = post_residual - next_item_size;
            if nxt_gap <= 10 {
                score += 15.0; // would create fresh dead space
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin should only win when the fit
    // into existing bins is poor. Give the empty bin a neutral-ish but
    // slightly penalized baseline so good fits always beat it.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, prefer consolidating into open bins.
        if open_bins_count > 0 {
            score += 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }
        // If open bins are very full on average, a new bin is reasonable.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer tighter packing.
    score += 0.8 * open_bins_count as f64;

    // Mild preference for using bins with less residual (best-fit flavor)
    // already captured by post_residual baseline.

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual closely matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score += diff * 0.8;
        // Perfect lookahead fit: big bonus (subtract)
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score += 5.0; // leaves a gap next item can't fill exactly
        }
        // post_residual smaller than next item: dead space unless tiny
        if post_residual < next_item_size {
            score += (post_residual as f64) * 0.3;
        }
    }

    // Tight fit reward
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Penalize bins far below mean residual (wasteful use of a roomy bin)
    score += (mean_residual - bin_residual as f64).abs() * 0.2;

    // Last-chance bin: strong bonus to use it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize moderately so it's only chosen when open fits are bad
    if bin_residual == bin_capacity {
        score += 35.0;
        // late in stream, opening fresh bins is more acceptable
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0;
        // if next item is large, a fresh bin is attractive
        if next_item_size >= item_size && next_item_size > 50 {
            score -= 12.0;
        }
    }

    // Small absolute residual is good (less wasted space)
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a nonlinear term.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that can't fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small dead space is fine
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0; // awkward mid-range leftover
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless it's genuinely needed.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            let avg_waste = mean_residual - item_size as f64;
            (avg_waste.max(0.0) / bin_capacity as f64).min(1.0)
        };
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        // Late in the stream, prefer consolidating into open bins.
        score += 45.0 - 25.0 * pressure - 20.0 * horizon;
        // If no open bin fits, opening new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for fuller bins among many open bins.
    score -= 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    score += 0.15 * open_bins_count as f64 * fit_ratio;

    // Mean residual coupling: prefer bins below mean residual (fuller than average).
    score += 2.0 * (mean_residual - bin_residual as f64).signum() * ((mean_residual - bin_residual as f64).abs() / bin_capacity as f64).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post_residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space; later, punish dead space harder
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits via smooth interaction of item size and residual
    score -= 30.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: if the next item fits the post-residual, reward this bin smoothly
    if next_item_size > 0 {
        let fits_next = (pr - next_item_size as f64).max(0.0) / cap;
        let lookahead_fit = 1.0 - (fits_next * 4.0).min(1.0);
        score -= 15.0 * lookahead_fit * norm_next * (1.0 - progress);
    }

    // Penalize using a bin when many alternatives exist; reward when it's last chance
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Smooth coupling with mean residual: avoid diverging from fleet state
    score += 0.1 * (mean_residual - pr).abs();

    // New-bin candidate handling: keep it slightly unattractive unless residual is large
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "harmonically useful"
    // i.e. divisible into common small item sizes (mod classes).
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -50.0 // perfect fit is best
    } else if pr <= 10 {
        30.0 // tiny dead space, nearly unusable
    } else if pr % 10 == 0 {
        -20.0 // clean multiple of 10: highly reusable
    } else if pr % 5 == 0 {
        -10.0
    } else if pr >= 40 {
        -8.0 // large leftover still flexible
    } else {
        5.0
    };
    score += class_bonus;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot fit here; slight penalty for tight residual
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer filling bins that are already relatively full (low residual fraction).
    let residual_frac = bin_residual as f64 / cap;
    score += 10.0 * residual_frac * residual_frac;

    // Mild preference for bins below mean residual (keeps bin states balanced),
    // scaled by stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - bin_residual as f64) * 0.05;

    // Penalize opening new bins when many bins are already open and item fits.
    if bin_residual == bin_capacity && bin_residual >= item_size {
        score += 12.0 + 2.0 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps more harshly than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residual that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Slight preference toward bins with residuals below the mean (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // 2-step lookahead: if next item fits into the resulting residual, strongly reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover2 = post_residual - next_item_size;
        score -= 12.0 + (bin_capacity as f64 - leftover2 as f64) * 0.25;
    } else if next_item_size > 0 {
        // next item won't fit after this placement: penalize wasted potential
        score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.3;
    }

    // Relative-to-mean-residual coupling: prefer bins whose residual deviates favorably
    score += (mean_residual - post_residual as f64) * 0.2;

    // Last-chance bin: avoid opening new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin early in the stream; allow it late when fragmentation high
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + progress * 4.0 - (open_bins_count as f64).min(10.0);
    }

    // Penalize very small dead space that can never be reused
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.19;
    score
