pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 30.0 * poly * cap;
    // reward tight fits
    score -= (item_size as f64 / cap) * 10.0;
    // last chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // lookahead: prefer bins whose residual fits next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - pr).max(0.0) * 0.2;
    }
    // penalize opening new bins late / when many open bins fit
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
        score += fitting_bins_count as f64 * 5.0;
    }
    // residual dispersion term
    score += (mean_residual - pr).abs() * 0.1;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead-space classes by modulo
    let class = post_residual % 10;
    let class_penalty: f64 = match class {
        0 => -6.0,          // perfectly divisible residual, highly reusable
        5 => -3.0,          // half-class, still flexible
        2 | 8 => -1.5,
        4 | 6 => -1.0,
        1 | 9 => 2.5,       // awkward classes
        _ => 1.0,
    };
    score += class_penalty;

    // Integer-division thresholds: big post residual is fine (roomy bin),
    // tiny post residual wastes little; the danger zone is mid-small leftovers
    let div3 = post_residual / 3;
    if div3 == 0 {
        score -= 4.0; // near-perfect fill
    } else if div3 > 10 {
        score -= 2.0; // lots of room left, still useful
    } else {
        score += 3.0; // awkward mid leftover
    }

    // Coupling with next item (lookahead): residual exactly fits next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 8.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 4.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item won't fit here; residual likely dead unless small
            if post_residual < 10 {
                score -= 1.0;
            } else {
                score += 4.0;
            }
        }
        // harmonic class match between residual and next item
        if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
            score -= 2.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_residual > 60 {
            score += 6.0; // item tiny relative to bin: wasteful open
        }
        if mean_residual > 40.0 && open_bins_count > 0 {
            score -= 5.0; // open bins are full-ish; new bin justified
        }
    }

    // Progress-dependent tightening: early on, keep bins flexible
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // Prefer bins whose residual is far from mean (better packing diversity)
    let dev = (post_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    // Reward near-closure
    if post_residual < 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it cannot hold even the smallest plausible item
    // (use 1 as universal floor, but weight gaps below typical item sizes).
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit bonus: leave zero residual.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0; // near-perfect fit
    }

    // Lookahead: if next item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize slightly more when gap is dead.
        score += 4.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets
    // penalized via mean-residual coupling below).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are open
        // and how scattered the current residuals are.
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But if the item is large relative to mean residual, existing bins
        // are likely fragmented; soften the new-bin penalty.
        if (item_size as f64) > mean_residual {
            score -= 15.0;
        }
    } else {
        // Existing bin: mild reward for keeping residuals close to the mean
        // (balanced packing), penalty for extreme fragmentation.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * deviation;
    }

    // Early in the stream, be more willing to consolidate; late, just finish bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward when next item fits the post residual well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 150.0;
        } else if gap <= 5 {
            score -= 60.0;
        } else if gap <= 10 {
            score -= 25.0;
        } else {
            // penalize large leftover that next item can't use proportionally
            score += (gap as f64).powf(0.8) * 0.5;
        }
        // bonus if post residual is large enough to hold next item at all
        if post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize creating small dead space (< 10) that likely becomes waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: only attractive when no good existing option
    // (i.e., current bin is a poor fit) or stream is early.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 40;
        let early = (step_index as f64) / (total_items.max(1) as f64) < 0.2;
        if poor_fit || early {
            score -= 30.0 + (open_bins_count as f64) * 0.0;
        } else {
            score += 100.0; // default: prefer existing bins
        }
    }

    // Slight preference to fill already-open bins as stream progresses.
    score -= (step_index as f64 / (total_items.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit preference: reward small post-residual nonlinearly.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize creating dead space: post_residual too small for the smallest
    // plausible item (assume min size 1, but weight relative to item size).
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 15.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Lookahead: reward if the next item fits into the post-residual,
    // penalize if the next item is large and this bin would be its only hope.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item can chain here: mild reward proportional to how well it fits
            let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 6.0 * chain_fit;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // this bin currently fits next item but placing here would break it:
            // penalize if next item is big (hard to place elsewhere)
            let big_next = (next_item_size as f64 / bin_capacity as f64).powi(2);
            score += 10.0 * big_next;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly favor
    // using it over opening a new bin (unless post-residual is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Prefer opening a new bin only when existing bins would leave bad residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin: mild, so tight existing fits still win.
        score += 8.0;
        // If many bins are already open, discourage spreading items thin.
        score += (open_bins_count as f64).sqrt() * 1.5;
        // Late in the stream, avoid opening bins for near-tight fits elsewhere.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * progress;
    } else {
        // Using an existing bin reduces bin count pressure: small reward.
        score -= 2.0;
        // Reward bins that are already below-average residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
        }
    }

    // Global coupling: if mean residual across open bins is high, encourage
    // filling existing bins harder (penalize leaving large residuals).
    if mean_residual > bin_capacity as f64 * 0.4 && bin_residual < bin_capacity {
        score -= 2.0 * (mean_residual / bin_capacity as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let t = progress;
    let coupling = prn * prn * (1.0 - t) - prn * t * (1.0 - prn) + prn * t * t;
    score += 12.0 * coupling;

    // Penalize dead space late in the stream with a smooth quartic term.
    score += 8.0 * prn * prn * prn * prn * (0.5 + t);

    // Reward tight fits: small post residual gets subtracted bonus.
    let tight = (1.0 - prn).powi(3);
    score -= 10.0 * tight * (0.4 + 0.6 * t);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post residual exactly-ish, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_gap = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
        } else {
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Mean residual alignment: prefer bins close to the mean residual.
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // Mild pressure against proliferating many open bins early.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - t) * 0.5;

    // New-bin candidate: only attractive when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).powi(2);
        score = pr + 15.0 - 20.0 * fragmentation * (0.3 + t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual is a multiple of a
    // "friendly" divisor (10, 20, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else {
        let friendly = if pr % 50 == 0 { 3.0 }
            else if pr % 25 == 0 { 2.0 }
            else if pr % 20 == 0 { 2.0 }
            else if pr % 10 == 0 { 1.5 }
            else { 0.0 };
        score -= 8.0 * friendly;
        // Integer-division thresholds: penalize tiny dead space bands
        let band = pr / 10; // 0..=9 harmonic band
        score += match band {
            0 => 25.0,          // 1..9 residual: nearly unusable
            1 => 12.0,          // 10..19
            2 => 4.0,           // 20..29
            _ => 0.0,
        };
    }

    // Coupling with next item (k=2 lookahead): reward if next item fits exactly
    // or well into the post residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let waste = pr - next_item_size;
            score -= 20.0 * (1.0 - waste as f64 / cap);
        } else {
            // next item cannot fit here: mild penalty proportional to overflow
            score += 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins give bad fits.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.3 * open_bins_count as f64;
        // but if mean residual is large and unusable, opening new bin is fine
        if mean_residual > 0.35 * cap {
            score -= 35.0;
        }
    }

    // Prefer filling fuller bins early in the stream; late in stream, be greedy.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    // Tie-break toward bins close to mean residual (balance exploitation).
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are small but nonzero are hard to fill later.
    if post_residual > 0 {
        let r = post_residual as f64;
        if r < 10.0 {
            score += 40.0 * (10.0 - r) / 10.0; // tiny unusable gap
        } else if r < 25.0 {
            score += 18.0 * (25.0 - r) / 15.0; // awkward gap
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Lookahead: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 6.0; // next item would have fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good alternative exists.
    if bin_residual == bin_capacity {
        // Baseline penalty so open bins are preferred unless they waste space badly.
        score = bin_capacity as f64 - 30.0;
        // If the current bin leaves a very poor gap, opening a fresh bin is better.
        if post_residual > 0 && post_residual < 20 && bin_residual != bin_capacity {
            score -= 20.0;
        }
        // Under bin pressure, opening new bins is more acceptable.
        score -= (open_bins_count as f64).min(10.0);
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Slight preference for bins below mean residual (balance residuals)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.6;
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space the next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += post_residual as f64 * 0.3;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize more when post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for the smallest plausible item (1).
    // Instead, penalize post_residual that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainable residual: reward it proportionally to how well it fits next item.
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * chain_fit;
        } else {
            // Dead space for the next item: penalize proportionally.
            score += 30.0 * (post_residual as f64 / next_item_size.max(1) as f64).min(1.0);
        }
    } else {
        // Last item: prefer the fullest packing possible.
        score -= 50.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are fragmented (high mean residual spread) or few bins fit the item.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: full residual, discourage mildly.
        score += 20.0;
        if fitting_bins_count > 1 {
            // There are alternatives; make new bin clearly worse.
            score += 80.0;
        }
        // If open bins have lots of average residual, discourage new bin more.
        score += 0.5 * mean_residual;
        // Early in the stream, new bins are cheaper (future items can fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
        // Many open bins with slack: prefer reusing.
        if open_bins_count > 4 {
            score += 30.0;
        }
    }

    // Mild penalty for leaving exactly awkward residuals (e.g., 1..=9 unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Coupling: prefer bins whose residual deviates from the mean in the "just fits" direction.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), non-linearly coupled with progress.
    let mut score = pr * (1.0 + 0.8 * pr / cap) * (1.0 + 0.5 * progress);

    // Reward bins whose post_residual can still host the next item (lookahead synergy).
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack_fit / cap) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the lookahead item.
        score += 6.0 * (pr / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.3 * progress);
    }

    // Mild penalty when this bin's residual is far above the mean (fragmentation signal).
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: penalize slightly so it is chosen only when fits are poor,
    // with the penalty easing late in the stream.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "clean" fractions
    // of capacity (0, 25, 50, 75) and penalize awkward dead space classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo classes on post_residual relative to capacity quarters
    let q = bin_capacity / 4;
    let class = (post_residual % q) as f64;
    score += 0.35 * class;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        // dead space below min item size is unusable
        score += 18.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.25 * slack;
            // harmonic bonus when next item divides post residual cleanly
            if post_residual % next_item_size == 0 {
                score -= 12.0;
            }
        } else {
            // next item cannot use this bin's leftover; penalize large leftovers
            score += 0.15 * pr;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep fresh bins attractive only when current fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a bin, discounted when few bins open or early stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_cost = 22.0 + 8.0 * (1.0 - progress);
        if open_bins_count > 4 {
            new_cost += 6.0 * ((open_bins_count - 4) as f64).min(10.0);
        }
        score += new_cost;
    } else {
        // reward tight fits relative to mean residual across open bins
        if mean_residual > 0.0 {
            let tightness = (post_residual as f64) / (mean_residual + 1.0);
            score += 4.0 * (tightness - 1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item.
    let dead_threshold = 9.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64 + 1.0);
    }

    // Reward tight fits: perfect fill is strongly favored.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward proportionally small leftover relative to capacity.
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 45.0; // perfect two-item chaining
        } else if (slack as f64) < dead_threshold {
            score += 15.0; // would create dead space next step
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item cannot use this gap: residual likely becomes dead space.
        score += 8.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual < bin_capacity {
        score -= 6.0 * pressure;
    } else {
        // New-bin candidate: penalize slightly unless current bins are very full.
        score += 5.0 + 4.0 * pressure * (mean_residual / bin_capacity as f64);
    }

    // Early stream: be more liberal about keeping bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins close to the mean residual (balanced filling).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the post residual,
    // this is a perfect chain match — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let chain_waste = post_residual - next_item_size;
            if chain_waste <= 10 {
                score -= 150.0;
            } else {
                // Reward proportional to how well next item uses remaining space.
                score -= 50.0 * (next_item_size as f64 / post_residual as f64);
            }
        } else {
            // Next item cannot use the residual; penalize dead space creation,
            // scaled by how much unusable space remains.
            let dead = post_residual as f64;
            score += dead * 0.5;
            // If residual becomes small (<10), it's near dead space anyway; slight relief.
            if post_residual < 10 {
                score -= dead * 0.3;
            }
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    // Leaving less than average residual is good (tight packing).
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the current
    // fit is very poor (large post_residual) and other bins are fragmented.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are only chosen when clearly better.
        score += 120.0;
        // If the item is large and fits well in a fresh bin, reduce the penalty.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 60.0 * fill_ratio;
        // If open bins are highly fragmented (high mean residual) and many bins exist,
        // starting fresh becomes more attractive.
        if open_bins_count > 3 && mean_residual > 40.0 {
            score -= 50.0;
        }
        // Lookahead: fresh bin leaves residual = capacity - item; if next item fits there well, favor it.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 40.0;
        }
    }

    // Slight preference for filling bins as the stream progresses (consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small post_residual).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Fractional tightness: relative waste penalty.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead: reward if next item fits exactly in post_residual,
    // penalize if post_residual is dead space that nothing useful can use.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain
        } else if next_item_size < post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use post_residual -> dead space
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 8.0 * (10.0 - waste); // small dead space is bad
            }
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // but allow it when open bins are mostly full (mean residual low).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty that grows with open bins
        // having usable residual, eased by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 + 4.0 * (open_bins_count as f64).sqrt() - 10.0 * progress;
        if mean_residual > item_size as f64 + 20.0 {
            score += 10.0; // open bins still roomy; don't open new one
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 8.0; // big item coming, fresh bin useful
        }
    }

    // Mild preference for bins with residual below mean (consolidate emptier space).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight time-decay: later in stream, be greedier about tight fits.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear penalty growth on wasted space.
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Polynomial coupling of residual with stream progress: late in the stream,
    // dead space becomes more costly, so amplify the residual penalty smoothly.
    let prog_coupling = 1.0 + 2.0 * progress * progress;
    score *= prog_coupling;

    // Reward residuals that exactly accommodate the lookahead item (smooth kernel).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_kernel = (-gap / 12.0).exp();
        score -= 30.0 * fit_kernel * (1.0 + progress);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are poor,
    // with a smooth relaxation early in the stream (exploration phase).
    if bin_residual == bin_capacity {
        let relax = 1.0 - 0.5 * progress;
        score += 25.0 * relax + 0.15 * open_bins_count as f64;
    }

    // Smooth coupling with mean residual: prefer bins below the mean (tighter bins),
    // penalize bins above the mean (loose bins) via a quadratic term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 20.0 * dev * dev - 10.0 * dev;

    // Tiny smooth tie-breaker favoring fuller bins as stream progresses.
    score -= (item_size as f64 / cap) * (1.0 + progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
