        if pr % 25 == 0 { harmony += 5.0; }
        if pr % 20 == 0 { harmony += 3.0; }
        if pr % 5 == 0 { harmony += 1.5; }
        // Small prime-ish residuals are awkward: penalize.
        if pr % 2 == 1 { harmony -= 1.0; }
        if pr % 3 != 0 && pr % 7 == 0 { harmony -= 1.5; }
        score -= harmony;
