        } else if next_item_size <= post_residual {
            // Reward proportionally to how well next item fills leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this residual: penalize large dead space.
            score += 0.5 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs());
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Fractional capacity coupling: prefer bins that end in low residual fraction.
    let frac = post_residual as f64 / cap;
    score += 20.0 * frac * frac; // quadratic penalty on wasted fraction

    // Early in stream: encourage tight packing into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.5 {
        score += 0.05 * open_bins_count as f64;
    } else {
        score += 0.02 * open_bins_count as f64;
    }

    // Mean residual attraction: bins below mean residual are tighter, prefer them.
    score += 0.3 * (mean_residual - bin_residual as f64).abs().signum() * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 }
            else if post_residual > 40 { 150.0 }
            else { 60.0 };
        score += desperation;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin keeps good lookahead flexibility
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold the smallest
    // plausible item are essentially wasted capacity.
    let dead_zone = 12u32;
    if post_residual > 0 && post_residual < dead_zone {
        score += (dead_zone - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit is the ideal outcome.
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement; if it leaves next item stranded, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins already exist.
        score += 20.0 + 10.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
        // But if no open bin fits well (large mean residual waste), soften.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 18.0;
        }
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild preference for bins whose residual deviates from the mean
    // (place into bins with less residual than average to consolidate).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect fill for the next item
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64); // close match bonus
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + gap; // next item won't fit here; penalize
        }
    } else {
        // Last item: strongly prefer tightest fit (minimal post_residual).
        score += 25.0;
    }

    // Reward bins that are already "used up" (residual below mean) - keep filling dense bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating large dead space that likely can't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // tiny leftover is fine (near-perfect packing)
    }

    // Mild penalty for very low fill level relative to capacity early in stream.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (1.0 - fill_ratio) * 5.0;

    // Late in the stream, prefer compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 1 {
        score += progress * 3.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (mean_residual - item_size as f64).abs() < 15.0;
        if good_fit_exists {
            score += 100.0; // keep using existing bins
        } else {
            score -= 5.0; // opening fresh bin is reasonable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize residuals that are too small to ever be useful again
        let min_item = 1u32;
        if post_residual < min_item {
            score += 50.0;
        }
        // Dead-space penalty: residual below typical small item threshold
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 2.0;
        }
    }

    // Tightness ratio: reward bins where item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        let poor_fit = post_residual as f64 > 60.0 && fill_ratio < 0.4;
        let many_open = open_bins_count as f64 > 20.0;
        if poor_fit || many_open {
            score -= 25.0;
        } else {
            score += 60.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // next item can't use the leftover: mild penalty proportional to waste
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Global state coupling: when mean residual is high, prefer consolidating into fuller bins
    let residual_gap = mean_residual - post_residual as f64;
    score += residual_gap * 0.3;

    // Time horizon: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= fill_ratio * progress * 20.0;
    if post_residual == 0 {
        score -= progress * 30.0;
    }

    // Crowding: many open bins -> prefer filling existing ones, discourage new bins
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1)

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.8 * t) - 0.9 * x * x * (1.0 - t) - 0.5 * x * x * x * t;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - x).powi(3) * (0.6 + 0.8 * t);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) / cap * (1.2 + 1.5 * t);
        } else {
            // reward leaving room exactly for the next item
            score -= 0.35 * (1.0 - ((pr - ni) / cap).abs());
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 2.0 + 1.5 * t;
    }

    // Mild penalty for spreading across many bins when residuals are already low
    let mr = mean_residual / cap;
    score += 0.15 * (x - mr) * (1.0 + t);

    // New-bin candidate: prefer it only when item fits poorly everywhere
    if bin_residual == bin_capacity {
        score += 1.0 - 0.9 * (1.0 - x).powi(2) * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands on a
    // "composable" residue class (small, reusable leftovers) are rewarded.
    let post_class = post_residual % 10;
    let class_bonus: f64 = match post_class {
        0 => -6.0,                      // perfect fill or multiple of 10
        1..=5 => -2.0,                  // small leftover, easy to top off
        6..=9 => 3.0,                   // awkward dead zone
        _ => 0.0,
    };
    score += class_bonus;

    // Integer-division thresholds: reward near-exact fills.
    let fill_quotient = post_residual / (bin_capacity / 10); // tenths of capacity left
    score -= 2.5 * (4 - fill_quotient.min(4)) as f64;

    // Lookahead coupling: if next item fits the post-residual exactly or
    // harmonically (same decade class), strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            score -= 15.0;
        } else if diff % 10 == 0 {
            score -= 8.0;
        } else if diff < 10 {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    } else if next_item_size > post_residual {
        // Next item can't use this bin anyway; penalize wasting capacity here.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless post_residual would be badly fragmented.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 12.0;
        if post_residual > bin_capacity / 2 {
            score += 6.0; // but avoid leaving a huge hole when a fresh bin is fine
        }
    }

    // New-bin candidate handling: neutral baseline, opened only when open bins
    // would create bad dead space.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.45;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big next item: a fresh bin is attractive
        }
    }

    // Stream progression: early on, be conservative (keep bins flexible);
    // later, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin is far from the mean residual,
    // slightly normalize selection toward balanced usage.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps strongly (dead space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item would no longer fit here; mild penalty unless gap is large.
        if post_residual < 20 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open bins pressure: many open bins -> favor consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 1.5;

    // Prefer bins below mean residual (tighter packing).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight bonus for filling larger fraction of the bin.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate baseline: keep it competitive but slightly costly,
    // so it only wins when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain: next item closes this bin
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // penalize leftover gap after the hypothetical next placement
            score += gap * 0.6;
        } else {
            // next item can't use this bin's residual: dead space risk
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.9;
        }
    } else {
        // last item: just minimize leftover
        score += post_residual as f64 * 0.5;
    }

    // Penalize bins that deviate from the mean residual (keep bin pool balanced)
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / (bin_capacity as f64);
        // high mean residual among open bins => open bins are roomy, avoid new bin
        score += 60.0 * fragmentation;
        // late in the stream, prefer reusing
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // many open bins => discourage opening more
        score += open_bins_count as f64 * 2.0;
        // if few fitting bins, opening new bin is reasonable
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large waste relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty proportional to overflow gap.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // or this is a poor fit everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a new bin.
        score += 15.0;
        // More attractive early in the stream (future items can use fresh space).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // Less attractive when many bins are already open (avoid sprawl).
        score += 1.5 * open_bins_count as f64;
        // Attractive if mean residual of open bins is fragmented (poor usable space).
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Prefer filling bins with larger residuals less aggressively when
        // mean residual is high (keep flexibility), prefer low-residual bins otherwise.
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        } else {
            score -= 2.0;
        }
    }

    // Global fragmentation pressure: when many bins are open, encourage consolidation.
    score += 0.4 * open_bins_count as f64 * waste_ratio;

    // Slight preference for bins whose residual is close to item size (minimal slack).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping.
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Non-linear coupling of post_residual with stream progress:
    // early on, waste is cheap; later, waste is penalized super-linearly.
    let progress_weight = 1.0 + 3.0 * t * t;
    score += progress_weight * pr_norm * pr * 0.5;

    // Reward filling a bin nearly full, stronger as the stream progresses.
    let fill = (bin_residual as f64 - pr) / cap;
    score -= 25.0 * fill * fill * (0.5 + t);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - pr_norm);
    }

    // Penalize opening new bins when many bins are already open and mean residual is high.
    score += 0.5 * open_bins_count as f64 * pr_norm;
    score += 2.0 * (mean_residual / cap - pr_norm).abs();

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 15.0 * (1.0 - slack / cap) * (1.0 + t);
        } else {
            score += 5.0 * (nxt / cap) * pr_norm;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "reusable" classes (multiples of 10, or large enough for typical items)
    // are rewarded; awkward dead-space classes are penalized.
    let class = post_residual / 10; // 0..=10
    match class {
        0 => score -= 25.0,              // perfect fit, best outcome
        1 => score += 18.0,              // 1-9: worst dead space
        2 | 3 => score += 8.0,           // 10-39: marginal
        4 | 5 => score -= 3.0,           // 40-59: decent
        6 | 7 => score -= 8.0,           // 60-79: very reusable
        _ => score -= 12.0,              // 80+: nearly empty, fine
    }

    // Exact-fit bonus: post_residual divisible into capacity classes
    if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (next_item_size as f64) * 0.05;
        } else {
            // penalize leftover that just barely fails to host the next item
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 7.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin when
    // decent fitting bins exist; allow it when residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // open new bin if existing residuals are small or many bins open
        score += 30.0 + 20.0 * progress + 25.0 * (1.0 - fragmentation);
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
        if item_size >= 50 && mean_residual < item_size as f64 {
            score -= 35.0; // big item, no real room anywhere
        }
    }

    // Prefer tighter existing bins (smaller residual before placement)
    score += (bin_residual as f64) * 0.08;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than moderate leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 / (1.0 + tightness);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 45.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // New-bin candidate handling: only open a new bin when open bins are crowded
    // or the fit here would be terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Cheaper to open a new bin when many bins are open (spread load).
        score -= (open_bins_count as f64).min(10.0) * 2.0;
        // If current bin would leave a large dead gap, opening fresh is better.
        if post_residual > 0 && post_residual < 10 {
            score -= 70.0;
        }
        // If the next item is large and this bin would be nearly emptied, prefer new bin.
        if next_item_size > 0 && post_residual < next_item_size / 2 {
            score -= 20.0;
        }
    }

    // Open-bin pressure: mildly discourage adding to bins when many are open,
    // unless fit is tight (already rewarded above).
    score += (open_bins_count as f64) * 0.5;

    // Deviation from mean residual: prefer bins with less residual (fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, be more conservative: penalize creating any leftover.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 2.0 * fit_ratio * fit_ratio * (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 * (-diff / 20.0).exp(); // perfect chain bonus
        // Penalize leaving residual slightly larger than next item (dead space)
        if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 15.0;
        }
        // Reward leaving residual that next item fits snugly
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64);
        }
    }

    // Compare post_residual relative to mean residual: avoid fragmenting above average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong penalty to open a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins unless current item is large
    // and mean residual is too small to be useful
    if bin_residual == bin_capacity {
        let useful = mean_residual >= item_size as f64 + next_item_size as f64;
        if useful && fitting_bins_count > 0 {
            score += 40.0; // discourage new bin when open space is useful
        } else {
            score += 5.0;
        }
    }

    // Late in stream: tighten packing, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to hold typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 5.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: discourage opening new bins unless current fits are bad
    if bin_residual == bin_capacity {
        // baseline penalty; reduced when open bins are fragmented or item is large
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / cap).max(0.0).min(1.0);
        score += 20.0 - 15.0 * fragmentation - 10.0 * progress;
        if item_size as f64 > 0.7 * cap {
            score -= 12.0; // large items are hard to place later, new bin ok
        }
    }

    // Prefer filling bins that are already more depleted than average
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev;

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_post * (1.0 - progress) - norm_post * norm_post * progress;
    score += 12.0 * coupling;
    // Reward tight fits (small post_residual) increasingly over time
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (20.0 + 15.0 * progress);
    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }
    // Prefer preserving room for the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (pr / cap) * (nx / cap);
        } else {
            score += 10.0 * (nx - pr) / cap * (0.5 + progress);
        }
    }
    // Mild pressure to consolidate when many bins are open
    score += 0.05 * (open_bins_count as f64) * (1.0 - norm_post);
    // Smooth new-bin candidate handling: favor fresh bin only when fit is poor
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 15.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress) - 10.0 * progress * (item_size as f64 / cap);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals in "dead zones" (1..9) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 are friendly.
    let harmonic = post_residual % 10;
    score -= 6.0 * (harmonic == 0) as i32 as f64;
    score += 3.0 * (harmonic >= 1 && harmonic <= 4) as i32 as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can chain into this bin: reward, scaled by tightness of the chain.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.3 * chain_waste;
            // Harmonic bonus if chained result is a multiple of 10.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // Next item cannot follow here: penalize more when post_residual is large (stranding space).
            score += 0.25 * (post_residual as f64).min(60.0);
        }
    }

    // Integer-division thresholds on post_residual: classify usable slabs.
    let slab = post_residual / 10; // number of full 10-slabs
    match slab {
        0 => score += 20.0,          // unusable dust
        1 => score += 5.0,
        2 => score -= 4.0,
        3 => score -= 8.0,
        _ => score -= 2.0,           // large residual: mediocre, keep flexible
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, discounted when many bins are open or stream is early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 20.0 * (1.0 - progress) - (open_bins_count as f64).min(10.0);
        // Opening a new bin is good if the item is large (leaves a big useful residual class).
        if item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Prefer tighter existing bins: compare residual to mean residual.
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Capacity-fraction coupling: reward placing large items into tight bins.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let bin_fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * bin_fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are unusable for any item
    // (min size 1, but tiny gaps rarely match) — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: zero dead space, strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to item size (small post_residual relative to item).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 12.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already fragmented; encourage consolidating into fewer bins.
    let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    score += 1.5 * pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item can fit into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
    }
    // If next item cannot fit in the post gap, penalize leaving a medium gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate logic: an empty bin has residual == capacity. Prefer it
    // only when no open bin offers a decent fit (post gap too small relative to item).
    if bin_residual == bin_capacity {
        // Base mild preference against new bins.
        score += 5.0;
        // But if existing bins would leave very tight/wasteful gaps, favor new bin.
        let open_bins_that_fit = fitting_bins_count as f64;
        if open_bins_that_fit >= 1.0 && (post_residual as f64) < 0.05 * bin_capacity as f64 {
            // this branch only triggers for non-empty bins; keep empty-bin neutral
        }
        // Slightly favor new bin late in the stream to reduce fragmentation risk.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Penalize large leftover gaps that are unlikely to be filled by the next item.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio > 0.4 {
            score += 10.0 * gap_ratio;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 20.0;

    // 2-step lookahead: reward when next item fits the post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // bonus proportional to how well next item matches post-residual
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15;
        } else {
            // next item won't fit: penalize dead space in this bin
            score += (post_residual as f64) * 0.3;
        }
    } else {
        // last item: just close tightly
        score += fit_ratio * 10.0;
    }

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is costly unless current bins are poor fits
    if bin_residual == bin_capacity {
        // opening a new bin wastes capacity when open bins have large residuals
        score += 30.0 + mean_residual * 0.5;
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // but if next item is large and no bin will hold both, new bin may be fine
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Penalize bins far from mean residual (fragmentation)
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item (<= 1..100 range: use small threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual < item_size.min(30) {
        score += 6.0; // awkward small gap
    }

    // Lookahead: reward leaving room for the next item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact or near-exact chain fit is excellent.
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.05 * overflow;
        }
    } else {
        // Last item: prefer filling bins as fully as possible.
        score -= 5.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream horizon and congestion.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 45.0 + 25.0 * progress;
        // If many open bins already, opening another spreads residual thin — penalize more.
        new_bin_cost += 0.8 * open_bins_count as f64;
        // If mean residual is high, existing bins have room; discourage new bin.
        new_bin_cost += 0.15 * mean_residual;
        // If no bin can fit (fitting_bins_count == 0 among open bins), new bin is necessary.
        if fitting_bins_count == 0 {
            new_bin_cost = 0.0;
        }
        score += new_bin_cost;
    }

    // Mild global pressure: when mean residual is low, cherish remaining space.
    score += 0.02 * mean_residual * (post_residual as f64 / bin_capacity as f64);

    // Early stream: slightly prefer consolidating into few bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 12.0 * coupling;
    // penalize dead space that grows quadratically as stream progresses
    score += 8.0 * norm_pr * norm_pr * progress;
    // reward tight fits, more strongly late in the stream
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.3 + progress);
    }
    // new-bin candidate: penalize mildly, less when residuals are tight
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 5.0 * (mean_residual / cap);
    }
    // lookahead: reward bins whose post-residual matches the next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        score += 5.0 * diff * diff;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that land in
    // "friendly" classes (multiples of small divisors) which future items
    // are likely to fill exactly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class bonuses via integer division thresholds.
        if post_residual % 10 == 0 { score -= 18.0; }
        if post_residual % 5 == 0 { score -= 7.0; }
        if post_residual % 25 == 0 { score -= 12.0; }
        if post_residual % 50 == 0 { score -= 20.0; }

        // Dead-space penalty for tiny unusable leftovers.
        if post_residual < 10 {
            score += 60.0 * (10 - post_residual) as f64;
        } else if post_residual < 20 {
            score += 15.0 * (20 - post_residual) as f64;
        }

        // Sweet spot: residual close to half capacity is highly reusable.
        let half = cap * 0.5;
        let dist_half = (pr - half).abs();
        score += 0.25 * dist_half;

        // Coupling with lookahead: if next item fits the post-residual
        // exactly or nearly, reward strongly.
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if next_item_size == post_residual {
                score -= 400.0;
            } else if next_item_size < post_residual {
                let rem2 = post_residual - next_item_size;
                score -= 60.0 - 2.0 * rem2.min(30) as f64;
                if rem2 % 10 == 0 { score -= 10.0; }
            } else {
                // Next item won't fit here: penalize large leftover waste.
                score += 0.3 * pr;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 90.0;
        }

        // New-bin candidate: only attractive when the item is large relative
        // to capacity (poor fit candidates elsewhere) or stream is early.
        if bin_residual == bin_capacity {
            let large_item = (item_size as f64) / cap;
            let progress = step_index as f64 / (total_items.max(1) as f64);
            let new_bin_bias = 40.0 - 30.0 * large_item - 20.0 * (1.0 - progress);
            score += new_bin_bias;
            // Opening a bin for a small item is wasteful.
            if item_size <= 25 { score += 80.0; }
        }

        // Prefer tighter bins among equals: compare against mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }

        // Mild dispersion penalty: keep residuals diverse, not all tiny.
        if open_bins_count > 0 && frac < 0.15 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: residuals too small to hold even the smallest
    // plausible item (<= ~10 units) are wasted forever.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward a perfect or near-perfect fit strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // residuals are already small; encourage using existing slack.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Slight preference to fill bins with larger residuals early in the
    // stream (keeps tight bins available for small late items).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post > mean_residual {
        score -= 3.0 * (1.0 - progress);
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.6 + (open_bins_count as f64) * 3.0;
        // If this is a last-chance situation, opening a bin is bad.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
        // If the item nearly fills a fresh bin, opening is fine.
        if (cap - item_size as f64) <= 5.0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit, scaled by capacity
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: perfect match with next item is gold
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // next item fills this bin exactly
        } else if post_residual > next_item_size {
            // next item fits: reward proportionally to how much it consumes
            let consumed = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * consumed;
        } else {
            // next item cannot fit here: penalize dead space relative to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    } else {
        // Last item: any residual is pure waste
        score += 20.0;
    }

    // Compare post_residual against mean residual: creating outliers is bad
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - pr) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize near-empty usage of an existing bin when many bins are open
    if post_residual > 70 && bin_residual != bin_capacity {
        score += 15.0;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when current fit is bad
    if bin_residual == bin_capacity {
        score -= 10.0;
        // opening new bin is fine early in stream, costly late
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 25.0;
    }

    // Dead-space penalty: tiny residuals are hard to fill later
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // Next item cannot use leftover space; penalize proportionally.
            score += 4.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        let pressure = (open_bins_count as f64) / ((step_index as f64 / total_items as f64).max(0.01) * 100.0 + 1.0);
        score += 15.0 - 10.0 * fragmentation / (bin_capacity as f64) - 5.0 * pressure.min(1.0);
        // Never open a new bin when a near-perfect fit exists elsewhere.
        if post_residual == 0 { score -= 100.0; }
    }

    // Mild preference for fuller bins among open bins (waste-avoidance).
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // Time-horizon coupling: early in the stream, be pickier about dead space;
    // late in the stream, just pack greedily.
    let progress = step_index as f64 / total_items as f64;
    score -= 8.0 * progress * tightness;

    // Global residual balance: prefer bins below mean residual (fill emptier bins
    // when residuals are large, keep tight bins for small items).
    if (bin_residual as f64) > mean_residual && item_size < 30 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: penalize large post_residual more as stream progresses
    score += progress * 40.0 * pr * pr;

    // Dead-space penalty: unusable space if next item cannot fit
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * waste * waste * (0.5 + progress);
    }

    // Reward good fits (small post residual) more strongly late in the stream
    score -= (1.0 - pr) * (1.0 - pr) * (10.0 + 20.0 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open and post residual is large
    score += (open_bins_count as f64).ln().max(0.0) * pr * 3.0;

    // Encourage matching mean residual (harmonic packing)
    score += (pr - mean_residual / bin_capacity as f64).abs() * 5.0;

    // Smooth lookahead coupling: favor leaving room for the next item
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += (gap / bin_capacity as f64) * (1.0 - progress) * 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless post residual is large
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Harmonic class of post_residual: dead space in (0,10) is nearly unusable
    // since items are >= 1 but small residuals waste capacity; penalize
    // post_residual in the awkward band 1..=9 heavily, mildly reward
    // post_residual == 0 (perfect closure).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score += 14.0;
    }

    // Modulo-10 classes: residuals that are multiples of 10 pair well with
    // typical item sizes; reward post_residual % 10 == 0.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Integer-division thresholds on post_residual: coarse bands.
    let band = post_residual / 25; // 0..=4
    score += match band {
        0 => 4.0,
        1 => 0.0,
        2 => -3.0,
        _ => -5.0,
    } as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this is a harmonic pairing — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64));
        } else {
            // Next item cannot use this bin's remainder; penalize large leftovers.
            score += 3.0;
        }
        // If next item would leave this bin's residual in a dead class anyway,
        // slight penalty for wasting the pairing opportunity.
        if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size / 2 {
            score += 5.0;
        }
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a decent fit (residual headroom small) or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperate = fitting_bins_count == 0 || (fitting_bins_count == 1 && bin_residual - item_size > 55);
        if desperate {
            score -= 10.0 + 15.0 * (1.0 - progress);
        } else {
            score += 12.0 + 10.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Mild pressure to consolidate: prefer bins whose residual is below the mean.
    if (bin_residual as f64) < mean_residual {
        score -= 2.5;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }
    // Penalize gaps too small for the next item (lookahead dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 50.0 + (next_item_size - post_residual) as f64;
    }
    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    }
    // Reward gaps that can still fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += open_bins_count as f64 * 2.0;

    // Prefer tightest bins (best-fit coupling).
    score += (bin_residual as f64 - post_residual as f64).abs() * 0.1;
    score -= (bin_capacity - bin_residual) as f64 * 0.5;

    // Slight early-stream preference for filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Penalize dead space: residual that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post / 10.0);
    }

    // 2-step lookahead: reward if next item fits into post_residual (chain placement).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            // Exact/near-exact chain match strongly rewarded.
            score -= 25.0 * (1.0 - (post - next) / cap);
        } else {
            // Next item won't fit here: mild penalty scaled by how much we'd waste.
            score += 5.0 * (next - post) / cap;
        }
    }

    // Relative to mean residual: placing into a bin whose residual deviates
    // favorably from the mean balances the bin pool.
    let dev = post - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when the item fits poorly everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins get progressively less attractive as the stream advances.
        score += 8.0 + 20.0 * progress;
        // But if the item leaves a huge hole in any existing bin, new bin is fine.
        if post > 60.0 {
            score -= 5.0;
        }
    }

    // Slight preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        } else if post_residual >= next_item_size {
            score -= 0.35 * next_item_size as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Time horizon: late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (best fit flavor).
    score -= 0.5 * (bin_residual as f64 - item_size as f64).abs();

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 14.0;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Base: prefer small post-residual, but with diminishing returns
    let mut score = (pr / cap).powf(1.5) * cap;

    // Smooth progress coupling: early on, waste matters less; late, penalize large residual
    let progress_weight = 0.5 + 2.0 * t * t;
    score += progress_weight * (pr / cap).powi(2) * 20.0;

    // Reward scarce fits (last-chance bins) with smooth saturating term
    let scarcity = 1.0 / (1.0 + fit);
    score -= scarcity * 15.0 * (1.0 + t);

    // Penalize bins whose residual deviates from mean residual (keep bin pool homogeneous)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - t);

    // Lookahead: if next item fits perfectly in post-residual, reward strongly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = ((pr - n).abs()) / cap;
        score -= (1.0 - gap).powi(3) * 12.0 * (pr >= n) as i32 as f64;
        // Penalize leaving residual slightly larger than next item (dead space)
        score += 6.0 * ((pr / n.max(1.0)) - (pr / n.max(1.0)).floor()) * (pr >= n) as i32 as f64;
    }

    // Mild penalty for spreading across many bins when few fits exist
    score += 0.05 * open / (1.0 + fit);

    // New-bin candidate: neutral-to-slightly-high baseline so it's chosen only when
    // open bins are genuinely poor fits (large post_residual relative to capacity)
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // residue classes (small, or matching common item sizes) are valuable.
    let pr = post_residual;
    let class = pr % 10; // harmonic class on decade grid
    // Reward leftovers that are exactly usable or tiny
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 10 {
        score -= 25.0; // dead space negligible
    } else {
        // penalize leftovers in awkward classes (large, non-round)
        score += (class as f64) * 1.5;
        // large leftovers that match the lookahead item are gold
        if next_item_size > 0 && pr >= next_item_size {
            score -= 18.0 + 0.5 * (pr - next_item_size) as f64;
        } else if next_item_size > 0 && pr < next_item_size {
            score += 12.0; // cannot host next item
        }
    }

    // Integer-division thresholds: residual divided by smallest item (10 in
    // spirit, but sizes 1..100 so use small quantum) -> number of potential
    // future small items it can host.
    let quanta = pr / 10;
    score -= quanta as f64 * 4.0;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening unless current bin would waste a lot
    if bin_residual == bin_capacity {
        // waste measure: how much of the bin stays unused if we open fresh
        let waste = pr as f64; // = capacity - item_size
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + waste * 0.6 - 25.0 * progress;
        if next_item_size > 0 && pr >= next_item_size {
            score -= 20.0; // fresh bin can host next item too
        }
    }

    // Prefer tighter bins when many are open (fragmentation control)
    score += mean_residual * 0.05 - (bin_residual as f64) * 0.05;

    // Modulo coupling between item_size and residual: near-perfect fits
    let diff = bin_residual.abs_diff(item_size);
    if diff < 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Non-linear penalty that spikes when the gap is too small for typical items.
        let unusable = (dead < 10.0) as i32 as f64;
        score += 40.0 * unusable * (10.0 - dead).max(0.0);
        // Smooth penalty on tight-but-nonzero gaps.
        score += 20.0 * (-dead / 15.0).exp();
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + 3.0 * open_bins_count as f64 + 20.0 * progress;
        // But if no open bin fits well, allow opening: the tightness term above
        // already penalizes poor fits.
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Mild preference toward bins with above-mean residual (keeps balance).
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual,
    // this is an ideal chained placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let leftover2 = post_residual - next_item_size;
            score -= 25.0 - 0.5 * leftover2 as f64;
            if leftover2 <= 5 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here; penalize wasted usable space.
            let waste = next_item_size - post_residual;
            score += 0.3 * waste as f64;
        }
