    } else {
        score += 0.2 * (resid - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins unattractive unless
    // no open bin fits well or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_everywhere = fitting_bins_count == 0;
        let next_fits_new_too = next_item_size > 0 && next_item_size <= bin_capacity / 2;
        if !poor_fit_everywhere {
            score += 40.0;
            // Slightly cheaper to open new bins early in the stream.
            score -= 15.0 * (1.0 - progress);
        }
        if next_fits_new_too && next_item_size > 0 && next_item_size as f64 >= mean_residual {
            // Opening a fresh bin is reasonable if next item is large and
            // current open bins have small residuals.
            score -= 10.0;
        }
    }

    // Mild penalty for leaving dead space that nothing can use later
    // (residuals below the minimum plausible item size are dead).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Prefer consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let next = next_item_size as f64;

    let mut score = post;

    // Penalize dead space non-linearly: small post-residuals that can't fit
    // typical future items are wasted capacity.
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) * 2.5 } else { 0.0 };
    score += dead;

    // Reward tight fits: ratio of item consumed from this bin's residual.
    let tightness = item / residual.max(1.0);
    score -= 18.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a great pairing; penalize if next item almost fits but doesn't.
    if next > 0.0 {
        if next <= post_residual {
            score -= 8.0 * (1.0 - next / cap);
        } else if next <= post_residual + 10.0 {
            score += 6.0;
        }
    }

    // New-bin candidate handling: opening a bin is justified when the item is
    // large or the stream is early (future items may pair with the fresh space).
    if bin_residual == bin_capacity {
        let early_bias = 1.0 - progress;
        let size_bias = item / cap;
        // Prefer new bin when item is big or stream is young; otherwise penalize.
        score += 20.0 - 30.0 * size_bias - 15.0 * early_bias;
        // If existing bins are fragmented, a fresh bin is attractive.
        if mean_residual < item * 0.5 && fitting_bins_count > 1 {
            score -= 10.0;
        }
    } else {
        // Mild penalty for using bins when many are open and mean residual is
        // high (fragmentation risk); reward consolidation when bins are few.
        let frag = (open_bins_count as f64).ln() * mean_residual / cap;
        score += 3.0 * frag;
    }

    // Time horizon: late in the stream, conserve bins by favoring existing bins.
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer low post-residual (tight fit), with smooth polynomial shaping
    let mut score = norm_pr + 0.35 * norm_pr * norm_pr;

    // Non-linear coupling with stream progress: late in stream, demand tighter fits
    let progress_coupling = progress * (norm_pr * (1.0 - norm_pr) * 4.0);
    score += 1.2 * progress_coupling * norm_pr;

    // Penalize large dead space more than linearly (quadratic waste term)
    score += 0.5 * norm_pr * norm_pr * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.0 + progress;
    } else {
        // Mild penalty when many alternatives exist to keep diversity
        score += 0.05 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward if next item can fit into post-residual
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let fit_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 0.6 * (1.0 - fit_ratio) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Smooth penalty when next item cannot follow into this bin
        score += 0.3 * norm_pr;
    }

    // Mean residual context: placing into a bin far below mean residual keeps balance
    let dev = (pr - mean_residual) / cap;
    score += 0.15 * dev * dev - 0.1 * dev;

    // New-bin candidate: empty bin has full residual; discourage unless nothing fits well
    if bin_residual == bin_capacity {
        score += 1.5 + 1.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: prefer residuals that are
    // multiples of common item-size classes (mod-10 buckets).
    let class = post_residual % 10;
    if class == 0 {
        score -= 12.0; // perfectly aligned residual, likely reusable
    } else if class <= 2 {
        score += 8.0; // near-dead space
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize tiny unusable residuals (< 10, minimum item size).
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 6.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    // (large post residual waste) or stream is early.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 5.0 - 0.05 * open_bins_count as f64;
        if waste < 20.0 {
            score += 40.0; // discourage new bin when a tight fit exists elsewhere
        }
        if (step_index as f64) / (total_items.max(1) as f64) < 0.2 {
            score -= 5.0;
        }
    }

    // Mild bias toward fuller bins relative to mean residual.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Integer-division threshold: reward residuals in "half-capacity or less"
    // regime to consolidate space.
    if post_residual <= bin_capacity / 2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, the min item size
    // historically, but sizes can be 1..100) are nearly unusable -> heavy penalty.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward tight fits (best-fit style): subtract when item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize large post-residuals that exceed the plausible max item size,
    // they indicate wasted capacity that could have been used elsewhere.
    if post_residual > 80 {
        score += (post_residual as f64 - 80.0) * 1.5;
    }

    // Open-bin pressure: discourage spreading across many bins; favor
    // consolidating when many bins are already open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (new bin would add to open count anyway).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // reward this placement strongly (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if (post_residual as f64) < dead_threshold {
            // dead space that the known next item cannot use
            score += 6.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is close to the mean
    // (keeps bin states homogeneous, avoids stranding outliers).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    // New-bin candidate: empty bin gets a fixed opening cost so it is only
    // chosen when all open bins would create worse dead space.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize wasted residual relative to mean.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.4 * waste;
        }
    }

    // Compare against mean residual: prefer consuming above-average space
    // (large residual bins) to consolidate fragmentation.
    if (bin_residual as f64) > mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current item is
    // huge and lookahead also large (chain of big items benefits from a
    // fresh bin), or very few items remain.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_chain = item_size >= 60 && next_item_size >= 60;
        if !big_chain && progress < 0.9 {
            score += 90.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that becomes unusable for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver, nearly dead space
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0; // awkward gap
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 0.5 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // New-bin candidate handling: opening a new bin is penalized more as the stream
    // progresses and when many bins are already open with usable residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = mean_residual / bin_capacity as f64;
        score += 35.0 + 45.0 * progress + 30.0 * waste_pressure + 2.0 * open_bins_count as f64;
        // Opening a new bin is attractive if the next item is large and current
        // residuals are small (nothing can host both).
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: reward placements that leave room exactly for the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect reservation: post_residual equals next item size exactly.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: just minimize waste, prefer tightest fill.
        score -= 10.0 * fill_ratio;
    }

    // Mild preference for consolidating into bins with low residual overall
    // (fill nearly-full bins first, keep large-residual bins flexible).
    score += 0.08 * (bin_residual as f64 - mean_residual).max(0.0);

    // Small bonus for using bins when few are open (early stream: build density).
    if open_bins_count <= 2 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr * norm_pr);

    // Reward tight fits more strongly as the stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (20.0 + 40.0 * progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + 0.5 * progress);
        } else {
            score -= 3.0 * (1.0 - (nxt / pr).min(1.0));
        }
    } else {
        // Last item: strongly prefer filling existing bins completely
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty when this bin is far above mean residual (fragmentation risk)
    score += 0.05 * (pr as f64 - mean_residual).abs().sqrt() * 10.0 * progress;

    // Slight preference for keeping bin count low late in the stream
    score += open_bins_count as f64 * 0.02 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space classes".
    // Small residues in awkward classes are penalized; exact fills heavily rewarded.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score += 35.0; // unusable sliver
    } else if class == 0 {
        score -= 12.0; // round residual, easy to reuse
    } else if class <= 3 {
        score += 14.0; // awkward residue class
    } else {
        score -= 4.0;
    }

    // Integer-division threshold: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic coupling: reward when next item's class complements post_residual
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 20.0;
            }
            score -= (gap as f64) * 0.5;
        } else {
            score += 18.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) < 0.25 * bin_capacity as f64;
        if poor_fit {
            score -= 45.0;
        } else {
            score += 25.0;
        }
    }

    // Progress-aware tightness: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.15 * (0.5 + progress);

    // Prefer bins below mean residual (keeps residual spread small)
    score += ((mean_residual - bin_residual as f64).abs()) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Usable leftover: mild reward scaled by how much was consumed.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio;
    }

    // Penalize residuals that cannot fit the lookahead item (dead for k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 12.0;
        } else {
            score += 18.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is excellent; encourage closing bins out when few remain useful.
    score += 2.0 * open_bins_count as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when the item is huge
    // relative to typical residuals or all open bins would leave waste.
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_capacity - item_size) as f64;
        let waste_if_existing = (mean_residual - item_size as f64).max(0.0);
        if waste_if_open < waste_if_existing - 15.0 {
            score -= 50.0; // opening a fresh bin avoids more waste
        } else {
            score += 35.0; // default: prefer existing bins
        }
    }

    // Mean-residual coupling: if this bin is far below average residual,
    // it is a "small hole" bin; using it consolidates space.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Late-stream tightening: as the stream progresses, prioritize exact
    // consolidation of residual capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (dead space minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness of chain
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - chain_tightness / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving residual that matches nothing
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize opening a new bin when good open candidates exist, unless residual is small
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty so it's chosen only when fits are poor
        score += 60.0 + post_residual as f64 * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin guarantees room for the next item
            score -= 30.0;
        }
    }

    // Slight late-stream bias: consolidate more aggressively as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for future items
    // (residual in (0, 10] is nearly unusable given typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if post residual can't hold next item but this
    // bin could have, mildly penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
        // If next item fits this bin's current residual better than the current one,
        // encourage saving space for it when current item is small relative to bin.
        if bin_residual >= next_item_size && post_residual < next_item_size && item_size > bin_residual - next_item_size {
            score += 6.0;
        }
    } else {
        // Last item: strongly prefer perfect fill, else smallest residual.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline penalty so we
    // prefer filling existing bins, unless existing residuals are poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if no open bin fits well (post residual would be tiny) and there
        // is meaningful stream left, opening fresh is fine.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if progress < 0.85 && mean_residual < item_size as f64 * 1.2 {
            score -= 15.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 4 {
        score += 0.15 * open_bins_count as f64 * (mean_residual - post_residual as f64).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, tolerate larger residuals; later, penalize them super-linearly.
    let prog_term = 0.5 + progress;
    score += post * post / cap * prog_term * 0.6;

    // Reward tight fits (small post_residual) more strongly as stream advances.
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize deviation from mean residual (avoid fragmenting the bin population).
    let dev = post - mean_residual;
    score += 0.25 * dev * dev / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, scaled by how well the item actually fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 25.0 * tightness;
    }

    // New-bin candidate: penalize opening a new bin, unless it's the last item
    // or the item is huge relative to capacity and fits would waste space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 12.0 + 8.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            penalty += 6.0 + 10.0 * (1.0 - item_size as f64 / cap);
        }
        // If the next item is large and this bin's post-residual can't hold it,
        // opening a fresh bin is less attractive anyway; slightly relax penalty.
        if next_item_size > 0 && (next_item_size as f64) > post {
            penalty -= 4.0;
        }
        score += penalty;
    }

    // Lookahead: reward leaving residual that can still fit the next item.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 4.0 + 6.0 * progress;
        } else {
            // Dead space: residual too small for next item — penalize super-linearly.
            let waste = (post - next_item_size as f64).max(0.0);
            score += 0.15 * waste * waste / cap;
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how it sits in capacity fractions.
    let post_class = post_residual / (bin_capacity / 10).max(1); // 0..10 deciles
    let quarter = post_residual / (bin_capacity / 4).max(1);     // 0..4 quarters

    // Dead-space penalty: tiny residuals are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 12.0; // perfect fill, excellent
    }

    // Harmonic bonus: post_residual divisible into useful classes
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 6.0 * (1.0 - slack / cap); // tight follow-up fit is great
            // harmonic match: next item lands in same decile class
            if next_item_size / (bin_capacity / 10).max(1) == post_class {
                score -= 2.0;
            }
        } else {
            // next item won't fit here; penalize large leftover
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current item is large
    // and would leave a harmonic residual.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score = cap * (1.0 - frac) + 5.0;
        if post_residual % 10 == 0 { score -= 4.0; }
        if fitting_bins_count > 0 { score += 8.0; } // open bins exist; prefer them
        // early stream: allow more new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 { score -= 6.0; }
        if open_bins_count > 40 { score += 10.0; }
    }

    // Mean-residual pull: prefer bins whose residual deviates usefully from mean.
    score += 0.08 * (bin_residual as f64 - mean_residual).abs();

    // Quarter-class tiebreak: prefer leaving quarter-aligned residuals
    if quarter * (bin_capacity / 4).max(1) == post_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual gaps too small for any plausible item are wasted.
    let dead_threshold = 9u32; // items are >= 1; treat tiny gaps as near-wasted
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }

    // If the leftover cannot fit the lookahead item, the gap is likely unusable soon.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 1.5;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Perfect lookahead fit: strongly reward.
        score -= 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score += (open_bins_count as f64) * 0.4;

    // Prefer bins whose residual deviates from the mean (rebalance extremes upward slightly).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight late-stream conservatism: keep gaps usable as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: very small post-residuals that cannot fit typical items are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // 2-step lookahead: reward bins whose leftover exactly (or nearly) fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain match
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to the shortfall
            let short = (next_item_size - post_residual) as f64;
            score += 15.0 * (short / next_item_size as f64).min(1.0);
        }
    }

    // Compare against mean residual: bins tighter than average are more precious.
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 25.0 + 60.0 * (1.0 - pressure);
        // allow new bin late in the stream when item is huge relative to mean residual
        if item_size as f64 > mean_residual * 1.5 {
            score -= 45.0;
        }
    }

    // Prefer filling tighter bins as stream progresses (mild annealing).
    score *= 1.0 + 0.5 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but reward exactness nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Many open bins with high mean residual: encourage consolidation into fuller bins.
    let spread = bin_residual as f64 - mean_residual;
    if open_bins_count > 3 {
        score += 0.05 * spread;
        score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well or stream is early
    // and open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let open_full = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let poor_options = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let attraction = 0.6 * (1.0 - open_full) + 0.8 * poor_options + 4.0 * (1.0 - progress);
        score = 45.0 + 20.0 * (1.0 - attraction);
        // If it's a last-chance situation, opening new bin is worse.
        if fitting_bins_count == 1 {
            score += 15.0;
        }
        // Exact-fit lookahead in a fresh bin.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;
    // Tight fits are good: reward small post_residual non-linearly.
    score -= 40.0 * (1.0 - pr / cap).powi(3);
    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 25.0 * (1.0 - pr / ns.max(1.0)) * (0.5 + progress);
        } else {
            score -= 10.0 * (pr / cap) * (ns / cap);
        }
    }
    // Last-chance bin bonus.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }
    // Mild preference against scattering across many bins when residuals are large.
    score += 0.02 * (open_bins_count as f64) * (pr / cap);
    // Smooth progress interaction: prefer filling existing bins late in the stream.
    score += (pr / cap) * (1.0 - progress) * 5.0 - (pr / cap) * progress * 10.0;
    // Deviation from mean residual: avoid outliers.
    score += 0.1 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes of 10 (capacity fractions).
    let class = post_residual % 10;
    // Dead-space penalty: residuals in awkward classes (1..9 mod 10) waste space.
    if class != 0 {
        score += (10 - class) as f64 * 1.5;
    } else {
        score -= 8.0; // perfect harmonic fit
    }

    // Larger harmonic classes (multiples of 20) are reusable by mid-size items.
    let big_class = post_residual / 20;
    score -= big_class as f64 * 3.0;

    // Coupling with lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            let gap_class = gap % 10;
            if gap_class == 0 {
                score -= 10.0;
            } else {
                score += gap_class as f64 * 0.8;
            }
        } else {
            // next item cannot use this residual: penalize proportional to overflow class
            let over = next_item_size - post_residual;
            score += (over % 10) as f64 * 0.5 + 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when residual classes of open bins are bad
    // or the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 1.15;
        if tight {
            score -= 6.0;
        } else {
            score += 12.0;
        }
    }

    // Progress bias: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.15;

    // Crowding: many open bins -> favor filling existing ones.
    if open_bins_count > 4 {
        score -= open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (too small
    // for typical future items) is heavily penalized.
    let dead_zone = 25.0;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < dead_zone {
        let depth = dead_zone - post_residual as f64;
        score += 3.0 * depth; // unusable gap penalty
    }

    // Reward near-perfect fills (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward tight fit relative to item size (waste ratio matters).
    let waste_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += 2.0 * waste_ratio;

    // Open-bins pressure: discourage spreading across many bins when
    // open_bins_count is high; encourage consolidation.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make the empty bin attractive only when the
    // item is large and would leave a big usable gap, or no good fits exist.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin.
        score += 8.0;
        // Attractive for large items: large item in fresh bin leaves a big
        // usable residual.
        if item_size >= 60 {
            score -= 12.0;
        }
        // When mean residual across open bins is large, prefer using open bins.
        if mean_residual > item_size as f64 + 10.0 {
            score += 10.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward
    // this placement strongly (chains well).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 12.0;
        } else if gap <= 20 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit in the leftover: leftover is likely dead space.
        score += 6.0;
    }

    // Mild stream progression effect: early on, be more liberal with new bins
    // (more future items to fill them); later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    } else {
        score += 3.0 * progress;
    }

    // Mean-residual coupling: prefer bins close to the mean residual
    // (balanced usage), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to leftover waste
            score += 25.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are tighter/more valuable.
    let rel = post_residual as f64 - mean_residual;
    score += 0.5 * rel;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if next item is large and no good fit exists, new bin is fine
        if next_item_size >= item_size && post_residual < next_item_size as f64 as u32 {
            score -= 100.0;
        }
    }

    // Late in the stream, close out bins efficiently (prefer tight fits more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Reward leaving post-residuals that are either zero or likely reusable by the next item.
    if post_residual == 0 {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        // Post-residual too small for next item: dead-space penalty grows with tightness.
        score += 0.25 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent fits exist, unless the current fit is terrible.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 55.0
            - 20.0 * (item_size as f64 / bin_capacity as f64)
            - 15.0 * (fitting_bins_count as f64).ln().max(0.0);
        score += new_bin_penalty.max(0.0);
        // Early in the stream, opening bins is cheaper (builds a pool for future items).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Coupling with global state: prefer bins whose residual is near the mean (keeps spread balanced),
    // but reward dipping below the mean when the stream is late (consolidation phase).
    let residual_diff = bin_residual as f64 - mean_residual;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * residual_diff * (1.0 - 0.5 * progress);

    // Slight preference for bins with larger residuals late in the stream (fewer wasted opens).
    score -= 0.05 * bin_residual as f64 * progress;

    // Mild penalty for very large dead space after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, scaled non-linearly by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth penalty for small-but-not-zero post residual (dead space)
    let dead = (norm_pr * (1.0 - norm_pr)).max(0.0);
    score += 30.0 * (1.0 - 4.0 * dead) * norm_pr * (1.0 - norm_pr).max(0.0);

    // Non-linear coupling: perfect fit rewarded more as stream progresses
    if post_residual == 0 {
        score -= 25.0 * (1.0 + progress);
    }

    // Last-chance bonus with smooth interaction
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let tight = 1.0 - ((next_item_size as f64 - pr).abs() / cap);
        score -= 12.0 * fits_next * tight.max(0.0) * (0.5 + progress);
    }

    // Penalize bins far from mean residual (non-linear)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Mild preference for consolidating among many open bins
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: neutral baseline with progress-dependent caution
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which residue class it falls into.
    let class = post_residual / 10; // capacity fraction buckets (0..10)
    match class {
        0 => score -= 25.0,               // near-perfect fit, almost no waste
        1 => score -= 8.0,                // small gap, often usable by small items
        2 => score -= 2.0,
        3 => {}                            // neutral mid gap
        4 => score += 2.0,
        5 => score += 4.0,                 // half-full: mediocre state
        6 => score += 5.0,
        7 => score += 6.0,
        8 => score += 4.0,
        _ => {}                            // near-empty bin, fine
    }

    // Parity/modulo coupling: odd post_residual wastes integer space.
    if post_residual % 2 == 1 { score += 0.75; }
    if post_residual % 5 == 0 && post_residual > 0 { score -= 1.5; }

    // Dead space: post_residual too small for the smallest possible item.
    if post_residual < 1 { score -= 40.0; }
    else if post_residual < 10 { score += 12.0; } // unusable sliver

    // Lookahead: does next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0; // keeps chain alive
            // bonus if next item exactly fills
            if next_item_size == post_residual { score -= 10.0; }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Crowding pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).ln() * 2.0;
    score += mean_residual * 0.05 * (1.0 - progress);

    // New-bin candidate: penalize so we only open when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + post_residual as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1..10 band)
    // are pure waste — penalize them heavily.
    let min_item = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 60.0;
    }
    // Near-dead gaps (small but technically usable) get a soft penalty.
    if (post_residual as f64) >= min_item && post_residual < 25 {
        score += 8.0;
    }

    // Reward very tight fits (post_residual near zero handled by base term).
    if item_size >= bin_residual {
        score += 1000.0; // cannot happen, guard
    }
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last chance: only one bin fits this item — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 0.9 * open_bins_count as f64;

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item can't use the gap: dead-space risk
            score += 10.0;
        }
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or all open fits would leave tiny gaps.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 45.0 * (item_size as f64 / bin_capacity as f64);
        score -= new_bin_bonus;
        // If a fitting bin exists and mean residual is large, prefer reusing.
        if fitting_bins_count > 0 && mean_residual > (item_size as f64 + 20.0) {
            score += 30.0;
        }
    }

    // Mean residual coupling: prefer bins deviating below the mean (tighter bins).
    score += 0.25 * (mean_residual - bin_residual as f64).max(0.0);

    // Early stream: be slightly more willing to open bins (build structure).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (small post_residual) is better.
    // Penalize dead space quadratically for small residuals (unusable slivers).
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    } else {
        // Perfect fill is excellent
        score -= 50.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain
        } else if post_residual >= next_item_size {
            // reward proportional to how well next item fills the leftover
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 - gap * 0.5;
        } else {
            // next item cannot fit here: leftover likely dead space
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.6;
        }
    } else {
        // last item: prefer perfect closure
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are already
    // "compressed"; placing there tightens packing. Favor bins whose residual
    // is close to item_size relative to the mean.
    let mr = if mean_residual.is_finite() && mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
    let rel = (bin_residual as f64) / mr;
    if rel < 1.0 {
        score -= (1.0 - rel) * 8.0; // tighter-than-average bin gets priority
    } else {
        score += (rel - 1.0) * 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the item
    // is large relative to capacity, in which case a fresh bin is fine.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            score -= 5.0; // large items are fine in a fresh bin
        } else {
            score += 12.0 + (1.0 - frac) * 15.0; // discourage wasting a fresh bin on small items
        }
    }

    // Late in the stream, be more conservative with new bins and prefer closing out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 6.0;
    }

    // Many open bins: encourage consolidating into existing bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post-residuals are fine, but tiny leftovers
    // that can't fit typical items are wasted. Quadratic-ish penalty on
    // unusable slivers.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let frag = (pr / 30.0).min(1.0);
        score += 12.0 * frag * (1.0 - frag);
    } else {
        // Perfect fill is heavily rewarded.
        score -= 25.0;
    }

    // Reward tight fits (item nearly fills the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this
    // placement (it preserves a useful chain).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size <= bin_capacity {
            // Next item will need a fresh bin anyway; slight penalty for
            // leaving awkward residue.
            score += 5.0 * (post_residual as f64 / 50.0);
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a good fit. Make the empty bin moderately unattractive so
    // decent fits in existing bins win, but attractive when residuals are
    // globally fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Base cost of opening a new bin.
        let mut new_bin_score = 30.0;
        // If open bins are mostly full (low mean residual), a new bin is cheap.
        new_bin_score -= 35.0 * (1.0 - fragmentation);
        // Fewer open bins => new bin is relatively more attractive early on.
        if open_bins_count <= 2 {
            new_bin_score -= 10.0;
        }
        // Large items deserve fresh space when residuals are tight.
        if item_size as f64 > fragmentation * bin_capacity as f64 {
            new_bin_score -= 15.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += 20.0 * progress;
        return new_bin_score;
    }

    // Mild global pressure: when many bins are open, prefer consolidating
    // into bins with larger residuals (reduce bin count).
    if open_bins_count > 3 {
        score -= 5.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) + norm_post * (1.0 - progress) * (1.0 - progress);

    let mut score = post + 30.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space (small unusable residuals) smoothly
    let dead = if post < 10.0 { (10.0 - post) / 10.0 } else { 0.0 };
    score += 40.0 * dead * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose residual can still fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty for spreading across many bins early
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    // New-bin candidate: make empty bin moderately attractive only for large items
    if bin_residual == bin_capacity {
        score += 12.0 - 20.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into deciles
    let decile = (post_residual / (bin_capacity / 10).max(1)) as f64;
    // Penalize post-residuals in "dead" deciles (small, hard-to-fill remainders)
    // but reward perfect or near-perfect fits.
    score -= 12.0 * ((post_residual == 0) as i32 as f64);
    score -= 6.0 * ((post_residual <= bin_capacity / 20) as i32 as f64);

    // Harmonic coupling: if next item exactly fills post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it fills
            let fill = next_item_size as f64 / (post_residual as f64).max(1.0);
            score -= 8.0 * fill;
        } else {
            // next item does NOT fit here: penalize large leftovers
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Modular class logic: post_residual mod 10 — small odd remainders are dead space
    let m = post_residual % 10;
    if post_residual > 0 {
        if m == 1 || m == 2 || m == 3 {
            score += 5.0; // tiny dead remainder
        } else if m == 0 {
            score -= 3.0; // round residual, likely reusable
        }
    }

    // Fraction-of-capacity thresholds on residual before placement
    let res_frac = bin_residual as f64 / cap;
    if res_frac < 0.25 && post_residual > 0 {
        score += 4.0; // squeezing into a nearly-full bin leaves junk
    } else if res_frac > 0.5 {
        score -= 2.0; // plenty of room, keep large bins flexible
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish but discouraged if open bins fit well
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > bin_capacity / 2 {
            score -= 10.0; // big items fine in fresh bins
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: later in stream, prefer tighter packing
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * t * (1.0 - post_residual as f64 / cap);

    // Mean-residual coupling: keep this bin's residual near the mean to avoid fragmentation
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    // Many open bins: prefer consolidating into ones that fit
    if open_bins_count > 4 && fitting_bins_count > 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual).
    score += post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    // Treat residuals below the minimum plausible item size as fully dead.
    let dead = if post_residual < 10 { post_residual as f64 * 3.0 } else { 0.0 };
    score += dead;

    // Bonus for near-perfect fit.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Reward using a bin whose residual is close to the item (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Pull toward mean residual: avoid leaving bins with extreme residuals.
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item could use the post_residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }
    // If next item cannot fit in the gap, penalize leaving a mid-sized gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 2.0;
    }

    // New-bin candidate: default moderate score; open a new bin only when
    // no existing bin offers a decent fit (residual would be small).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.35 + 0.2 * open_bins_count as f64;
        // Late in the stream with few fitting bins, opening a fresh bin is fine.
        if fitting_bins_count <= 1 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly (chain packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 150.0;
        } else if diff <= 5 {
            score -= 80.0 - (diff as f64) * 10.0;
        } else if (next_item_size as i64 - post_residual as i64) < 0 {
            // next item does NOT fit here; penalize leaving big unusable-ish gaps
            score += (post_residual as f64) * 0.3;
        } else {
            // next item fits but imperfectly; mild reward decaying with diff
            score -= (20.0 - diff as f64).max(0.0) * 2.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New empty bin candidate: penalize opening a new bin unless it
    // enables a perfect chain with the next item or few bins fit the item.
    if bin_residual == bin_capacity {
        let mut nb = 40.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64 - item_size as i64).abs() <= 2 {
            nb -= 120.0;
        }
        if next_item_size == 0 {
            nb -= 30.0;
        }
        score += nb;
    }

    // Late in stream: consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that can't fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 {
        // prefer residuals that can still hold mid-size items
        score -= 3.0 * (post_residual as f64 / bin_capacity as f64).sqrt();
    }

    // Lookahead: if the next item fits in the post residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 2.0 * (next_item_size.saturating_sub(post_residual)) as f64 / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.4 * crowding;

    // Prefer bins with residual below the mean (fill the emptier-trending bins)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it attractive only when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && bin_residual > 0;
    if is_new_bin {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let waste_if_used = (bin_residual - item_size) as f64;
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        score += 20.0
            - 18.0 * poor_fits
            - 6.0 * big_item as i32 as f64
            + 0.15 * waste_if_used
            + 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: waste after placement, non-linearly discounted by stream progress
    // (late in the stream, small residuals matter more since few chances remain to fill them).
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Quadratic dead-space penalty for very small residuals (unusable slivers),
    // scaled smoothly by progress.
    let tiny = (1.0 - (pr / cap)).min(1.0);
    score += 12.0 * tiny * tiny * (0.3 + 0.7 * progress);

    // Lookahead coupling: reward residuals that can host the next item,
    // penalty grows smoothly as next item approaches the residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack) * (1.0 + 0.5 * progress);
        } else {
            let miss = (nxt - pr) / cap;
            score += 8.0 * miss * miss;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless residual waste would be huge).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 15.0 * progress;
    }

    // New-bin candidate handling: make empty bins mildly unattractive early
    // (prefer packing into open bins), but let them win when open bins fit poorly.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (1.0 + mean_residual / cap).max(0.5)).ln().max(0.0);
        score += 20.0 + 10.0 * openness * (1.0 - progress) - 18.0 * progress;
        // If the next item is large and current item leaves a big residual,
        // opening fresh is fine.
        if next_item_size > 0 && (next_item_size as f64) > pr.max(1.0) {
            score -= 5.0;
        }
    }

    // Mild tie-break: prefer bins whose residual is close to the item (tight fit)
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score += 4.0 * tight * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes of small moduli.
    // Residuals that are "harmonically nice" (small, or divisible into common classes)
    // are less dead; penalize awkward residuals.
    let r = post_residual;
    if r == 0 {
        // Perfect fit: heavily reward.
        score -= 200.0;
    } else if r < 10 {
        // Small residual: near-perfect, but if next item can't use it, it's dead space.
        if next_item_size > 0 && next_item_size <= r {
            score -= 120.0;
        } else {
            score -= 60.0;
        }
    } else {
        // Dead-space penalty grows for residuals in awkward classes.
        // Class A: residual divisible by 10 (common item granularity) -> reusable.
        if r % 10 == 0 {
            score -= 15.0;
        }
        // Class B: residual divisible by 5 -> moderately reusable.
        else if r % 5 == 0 {
            score -= 7.0;
        }
        // Class C: prime-ish / odd awkward residuals -> penalize.
        else if r % 2 == 1 {
            score += 12.0;
        }
        // Integer-division thresholds: big residual buckets.
        let bucket = r / 20; // 0..5
        score += bucket as f64 * 4.0;

        // Lookahead coupling: if next item fits in post_residual, big reward.
        if next_item_size > 0 && next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score -= 50.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
        } else if next_item_size > 0 {
            // Next item won't fit here; mildly penalize creating a stranded bin
            // unless residual is large enough to matter later.
            score += 6.0 + 0.1 * r as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 90.0;
        // Cheaper to open new bins early in the stream or when open bins are crowded.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If mean residual across open bins is small (fragmented), new bin is attractive.
        if mean_residual < item_size as f64 {
            score -= 50.0;
        }
        // If item is large relative to capacity, prefer a fresh bin.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
    } else {
        // Prefer bins with residual close to item (tight fit) — tighten via fraction.
        let fit_tightness = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fit_tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual that cannot fit even the smallest plausible item (<= 10) is wasted space.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead space relative to lookahead: residual smaller than next item is unusable next step.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward residual that exactly accommodates the next item (chains placements).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, tighten packing (penalize loose fits).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Late in the stream, be stricter about dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (compact bins stay compact).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 25.0 + pressure * 10.0 };
        score += desperation;
        // Late stream: prefer reusing existing bins over opening new ones.
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-perfect lookahead match: next item could fit with tight slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 / (1.0 + slack);
    }

    // Penalize if next item cannot fit in post-residual (dead space risk)
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 3.0 * gap;
    }

    // Compare post_residual against mean residual: leaving far-above-mean residual is wasteful
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no good fit exists (large item, tight fits)
    if bin_residual == bin_capacity {
        let tightness = if fitting_bins_count == 0 { 0.0 } else { (bin_residual - item_size) as f64 };
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0; // fresh bin enables a perfect next fit
        }
        let _ = tightness;
    }

    // Late in stream: consolidate more aggressively to avoid leaving many open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits strongly (small post_residual is best).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0 * (10 - post_residual) as f64;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize wasting space.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins with high mean residual: encourage consolidating items
    // into bins with residual below the mean (tighter bins first).
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
        // Encourage closing out bins when many are open.
        score -= 0.5 * (post_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // few bins are open, the item is large, or the stream is early.
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - progress) * 6.0;
        let scarcity_bonus = if open_bins_count == 0 { 20.0 } else { 0.0 };
        let last_chance_penalty = if fitting_bins_count == 1 { 25.0 } else { 0.0 };
        let big_item_bonus = if item_size >= 50 { 4.0 } else { 0.0 };
        score += 30.0 - early_bonus - scarcity_bonus - big_item_bonus + last_chance_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_n = pr / cap;

    // Base: reward small post-residual with a non-linear (quartic-flavored) curve.
    let mut score = pr_n * (1.0 + 1.5 * pr_n * pr_n);

    // Smooth coupling of post_residual with stream progress:
    // early on, prefer tight fits mildly; late in the stream, reward tight fits strongly.
    let progress_coupling = pr_n * (0.5 + 2.0 * progress * progress);
    score += progress_coupling;

    // Penalize dead space relative to the mean residual across open bins (smooth).
    let mean_n = mean_residual / cap;
    score += 0.3 * (pr_n - mean_n) * (pr_n - mean_n);

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward;
    // smooth decay as the gap to fitting grows.
    if next_item_size > 0 {
        let gap = (pr as f64 - next_item_size as f64).abs();
        score -= 2.0 * (-gap / cap).exp();
    }

    // New-bin candidate handling: keep it attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln() + 1.0;
        score += 1.0 + 0.5 * mean_n * crowding - 1.5 * progress;
        // If nothing else fits well, opening a bin is fine.
        if pr_n >= 0.999 {
            score -= 0.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (capacity fraction classes)
    let pr = post_residual as u32;
    let class = pr % 10;
    // Penalize residues that are hard to fill (dead space classes: 1..=9 small residues)
    match class {
        0 => score -= 12.0,          // perfectly divisible leftover, reusable
        7 => score += 6.0,           // awkward class
        3 | 9 => score += 4.0,
        _ => {}
    }

    // Integer-division thresholds on post_residual: large leftovers are fine
    if pr > bin_capacity / 2 {
        score -= 10.0;
    } else if pr >= bin_capacity / 4 {
        score -= 3.0;
    } else if pr > 0 {
        score += (bin_capacity / 4 - pr) as f64 * 0.15; // small unusable scraps
    }

    // Lookahead coupling: next item fits exactly into the post residual -> big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // harmonic class match between leftover and next item
            if (pr % 10) == (next_item_size % 10) {
                score -= 8.0;
            }
            score -= (pr - next_item_size) as f64 * 0.1;
        } else {
            // next item cannot use this leftover; penalize proportionally
            score += ((next_item_size - pr) as f64 / cap) * 15.0;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are congested or mean residual is low
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64).ln().max(0.0);
        let mean_frac = mean_residual / cap;
        score += 30.0 + congestion * 8.0 - mean_frac * 25.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // fresh bin useful for a run of similar items
        }
    }

    // Stream progression: late in stream, prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that no plausible item (>=1) can use well.
    // Small gaps (1..=9) are almost unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 2.0 * post_residual as f64;
    }
    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Tight fit relative to capacity: prefer filling bins deeply.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // favor consolidating into existing bins (penalize the new-bin candidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 3.0 + 10.0 * progress;
    score += pressure * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: only attractive when existing residuals are
    // badly fragmented (mean residual low relative to item) or nothing fits.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap >= 0.0 {
            score += 30.0 + mean_gap; // existing bins are fine, avoid new bin
        } else {
            score -= 5.0 + (-mean_gap); // fragmentation: new bin is reasonable
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
    }

    // Mild preference for bins already below mean residual (balancing).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight two-item packing chains
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            if slack as u32 == 0 {
                score -= 20.0; // perfect chain fill
            }
        } else {
            // Next item cannot follow; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    } else {
        // Last item: just minimize post residual
        score -= 5.0;
    }

    // Compare post_residual against mean residual across open bins
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.25 * mean_gap;

    // Penalize dead space: small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let opening_penalty = 55.0
            + 0.5 * open_bins_count as f64
            - 20.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        score += opening_penalty;
        // If next item is large and no tight chain possible, opening is less bad
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Early stream: be slightly more willing to open bins for flexibility
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 6.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // Penalize dead space: post_residual too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits into post_residual, this is a great pairing.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // Perfect chaining: next item exactly fills remaining space.
            if next_item_size == post_residual {
                score -= 35.0;
            }
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless the item
    // fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let base_open_cost = 70.0;
        // Early in the stream, opening bins is cheaper (build up a pool of bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_cost = base_open_cost * (0.5 + progress);
        // If many bins are open and mean residual is high, prefer using them.
        let congestion = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score = open_cost + congestion * 10.0;
        // A new bin is attractive if the item is large and would leave a very
        // small, unusable remainder in any existing bin.
        if item_size >= bin_capacity - 10 {
            score -= 80.0;
        }
    }

    // Prefer bins whose residual is close to mean residual (balanced packing),
    // mildly.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    // Slight preference for fuller bins as stream progresses (hurry to close bins).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio * (if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress) + 1.6 * x * x * (1.0 - 0.5 * progress);

    // Reward near-perfect fits (small post_residual) with a smooth dip
    score -= 2.0 * (-6.0 * x).exp();

    // Lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (x - nx).abs();
        score -= 1.2 * (-10.0 * gap * gap).exp();
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Penalize spreading across too many open bins relative to mean residual
    score += 0.3 * (open_bins_count as f64 / (1.0 + mean_residual / cap)) * x;

    // New-bin candidate: neutral-ish baseline, slightly worse early, better late
    if bin_residual == bin_capacity {
        score = 1.5 + 0.5 * progress - 1.0 * x;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits (0) are ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo-10 class: residuals that are multiples of 10 pair well with
    // typical item sizes; small odd dead-space classes are penalized.
    let cls = post_residual % 10;
    score -= match cls {
        0 => 8.0,
        1 | 9 => -3.0,
        2 | 8 => 0.0,
        3 | 7 => 1.5,
        4 | 6 => 2.5,
        _ => 3.5,
    };

    // Integer-division thresholds: reward residuals that can still host
    // a plausible next item (>= 10).
    if post_residual >= 10 {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 4.0; // tiny dead space
    }

    // Coupling with lookahead: if next item fits into post_residual,
    // this is a chain opportunity.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item fits this bin only if we place current item elsewhere
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has large residual; penalize
    // opening a new bin unless no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits; must open
        } else if post_residual >= 40 {
            // opening is reasonable if item is small relative to capacity
            score -= 10.0;
        }
        // late in stream, avoid proliferation of open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0 + (open_bins_count as f64) * 0.5;
    }

    // Prefer bins whose residual is below average (tighter bins first),
    // keeping large residuals for large future items.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild preference for filling bins with larger items early.
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
