pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (dead space minimization)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // slack above next item: mild penalty proportional to excess
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0);
        } else {
            // next item won't fit here; penalize small unusable leftovers
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(40.0) * 0.5;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it only wins when open bins are bad fits,
    // but relax late in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 - 10.0 * progress;
    }

    // Slight preference for filling larger residual bins early
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    let fit_quality = (post_residual as f64) / (bin_capacity as f64);
    score += 20.0 * fit_quality * fit_quality;

    // Lookahead: if the next item fits exactly into the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // partially reward, scaled by how much space would remain after next item
            let after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - (after_next as f64) / (bin_capacity as f64));
        } else {
            // next item cannot use this residual: penalize leftover that is too small
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 6.0 * (10.0 - dead);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize opening a new bin when good open bins exist, unless residual is tiny.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = (mean_residual - item_size as f64).max(0.0);
        score += 5.0 + 0.05 * open_bins_count as f64 + 0.02 * pressure;
        // Early in stream, opening new bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * (1.0 - progress);
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= post_residual.min(next_item_size) && next_item_size > 60 {
            score -= 3.0;
        }
    } else {
        // Prefer bins whose residual deviates below mean (concentrate fill).
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        } else {
            score += 1.0 * ((bin_residual as f64) - mean_residual) / 10.0;
        }
    }

    // Mild penalty for waste proportional to leftover relative to smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear coupling: post_residual weighted by stream progress
    score += norm_pr * norm_pr * (cap * (0.5 + 0.5 * progress));

    // Reward tight fits (small post_residual) with smooth quadratic discount
    score -= (1.0 - norm_pr).powi(3) * cap * 0.4;

    // Penalize dead space that can't fit the next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let mismatch = (pr - ns).max(0.0) / cap;
        score += mismatch * mismatch * cap * 0.6;
        // Reward when post residual exactly anticipates next item
        score -= (1.0 - ((pr - ns).abs() / cap).min(1.0)) * 3.0;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= cap * (0.5 + 0.5 * progress);
    }

    // Mild penalty when bin residual deviates from mean residual across bins
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 10.0;

    // Prefer consolidating into fewer bins as stream progresses
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);

    // New-bin candidate should only win when fit is poor
    if bin_residual == bin_capacity {
        score += cap * (0.6 + 0.4 * (1.0 - norm_pr)) + (1.0 - (1.0 - norm_pr)) * 0.0;
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small residuals are "dead space" classes
    // Class 0: post_residual == 0 (perfect fill) -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        // awkward zone: too small for most items, too big to ignore
        score += 15.0;
    }

    // Integer-division threshold: bins whose residual falls in [1, 20] are near-useless
    if post_residual >= 1 && post_residual <= 20 {
        score += 10.0;
    }

    // Lookahead coupling: reward if next item fits exactly or well into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let nxt_gap = post_residual - next_item_size;
            if nxt_gap <= 10 {
                score -= 30.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally to wasted opportunity
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate penalty: opening a new bin should only win when fit is terrible
    if bin_residual == bin_capacity {
        score += 40.0;
        // but if the item is large relative to capacity, a fresh bin is natural
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer filling bins with low mean residual (consolidate near-full bins)
    score -= (mean_residual / cap) * 15.0;

    // Slight preference for keeping open bin count low as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * progress;

    // Fractional-capacity harmonic: reward placements leaving residuals in
    // "divisible" classes (multiples of 10 align with common item sizes)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // (below the minimum item size of 1... but effectively gaps < ~10) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0; // unusable sliver
    } else if post_residual < 20 {
        score += 120.0; // likely dead space
    } else if post_residual < 35 {
        score += 25.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 300.0;
    }

    // Perfect pre-fit (item exactly fills residual) handled above; reward tight fits.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current bin's post-fit is poor
    // or the item fits badly everywhere.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are only chosen when justified.
        score += 150.0;
        // Pressure: many open bins -> discourage opening more.
        score += 8.0 * open_bins_count as f64;
        // If the next item could combine with leftover space, prefer existing bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 90.0;
        }
        // Late in stream, avoid proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 100.0 * progress;
    }

    // Prefer bins below mean residual (larger bins) for awkward items,
    // keeping small-residual bins free for small items.
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // Lookahead: penalize leaving a gap that neither fits the next item nor is usable.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0; // set up a perfect next placement
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward placements where the post residual
    // can exactly host the next item (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // Slack left over after hosting next item: mild penalty scaled by slack.
            score += 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot fit in the leftover: dead-space penalty grows
            // with how close-but-failing the residual is (worst near misses).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    } else {
        // Last item: minimize residual directly (already the base term).
    }

    // Relative-to-mean coupling: bins with residual near the mean are
    // "typical" targets; deviating bins get normalized pressure.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.05 * mean_gap;

    // Perfect fit bonus: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin, unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual > 0 {
            score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate: penalize opening a new bin unless it enables an
    // exact 2-step chain that open bins cannot provide.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        }
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins for good fits;
    // late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize creating dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are waste
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0; // residual still usable by typical items
    }

    // Lookahead: reward bins whose post_residual pairs with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect pairing
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot use this residual; mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 { 0.0 } else { 0.0 };
        let _ = poor_fit;
        // base cost of opening a bin, discounted when many bins are open or stream is early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        let mut new_bin_cost = 55.0 - 6.0 * open_pressure + 10.0 * progress;
        // if lookahead pairs perfectly with a fresh full bin, discount the cost
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_cost -= 0.10 * (bin_capacity - next_item_size) as f64;
        }
        // if this bin is the only fitting option elsewhere, opening new bin is less attractive
        if fitting_bins_count == 1 {
            new_bin_cost += 40.0;
        }
        score += new_bin_cost.max(5.0);
    }

    // Global residual balance: prefer bins whose residual is near the mean
    // (keeps open bins homogeneous, leaving large residuals concentrated).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * tightness;

    // Mild penalty for very full bins early (preserve flexibility), reversed late.
    if tightness > 0.9 && progress < 0.3 {
        score += 6.0 * (1.0 - progress / 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth non-linear coupling of post_residual with stream progress
    let coupling = (norm_pr * norm_pr) * (1.0 + progress) * 40.0;
    score += coupling;
    // penalize residuals too small to be useful later
    let dead = (1.0 - norm_pr).powi(3) * progress * 30.0;
    score -= dead;
    // reward tight fits more strongly later in the stream
    let tight = (item_size as f64 / bin_residual.max(1) as f64).powi(2) * (1.0 + 2.0 * progress) * 25.0;
    score -= tight;
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }
    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 15.0 * (1.0 - ((pr - nx) / cap).abs());
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }
    // mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - norm_pr);
    // keep new-bin candidate from winning too easily
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into residue classes mod capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Class 1: perfect fit -> strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class 2: post_residual falls into "dead zone" (1..=9) -> unusable slivers
    let dead_zone = post_residual > 0 && post_residual < 10;
    if dead_zone {
        score += 60.0;
    }

    // Harmonic class via integer division: post_residual / 10 classes
    let class = post_residual / 10;
    // Reward classes that are likely reusable by future items (multiples of 10)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Larger classes (more room) mildly preferred within same family
    score -= (class as f64) * 1.5;

    // Coupling with next item: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 400.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward proportional to how well next item nests
        let nest = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 20.0 * nest;
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize leaving medium dead space
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins more when many open bins exist and mean residual is large
        score += 120.0
            + 0.5 * (open_bins_count as f64)
            + mean_residual * 0.8
            - 40.0 * (1.0 - progress);
        // If item is large, new bin is fine (it will consume most of a fresh bin)
        if item >= 0.5 * cap {
            score -= 80.0;
        }
        // If item would leave a dead-zone residual in a fresh bin, discourage
        if dead_zone {
            score += 50.0;
        }
    }

    // Tight-fit reward: item filling most of the bin
    let fill = item / cap;
    score -= 30.0 * fill;

    // Prefer bins whose residual is close to item size (minimize waste)
    let waste = (bin_residual as f64 - item).abs();
    score += 0.1 * waste;

    // Mild preference for already-open bins over spreading
    if bin_residual < bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to plausibly host
    // any future item (1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward exact / near-exact fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Post-residual that can still host the lookahead item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the next item's need.
        score += 8.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid
    // opening a new bin unless the fit would create bad dead space.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // residuals are still healthy; encourage consolidation.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins whose residual is below the mean (tighter bins get
    // filled first), mild coupling.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, slightly favor opening fresh bins (better
    // long-run structure); late in the stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-match lookahead: strongly reward bins whose post_residual
    // exactly matches the next item size (chains the bin into full use).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize post_residual that is larger than next item but still
    // leaves a "dead" gap the next item can't use well.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap > 0.0 && gap < 10.0 {
            score += 12.0; // small unusable sliver
        } else if gap >= 10.0 {
            score += gap * 0.3; // moderate waste penalty
        }
    }

    // Reward bins whose post_residual is small relative to mean residual
    // (tight fit relative to the fleet).
    score -= (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Brand-new empty bin candidate: penalize mildly so we only open
    // new bins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if next item is large and this bin is fresh, opening can be good.
        if next_item_size >= item_size && post_residual as f64 >= next_item_size as f64 {
            score -= 30.0;
        }
    }

    // Slight preference to fill bins with less residual overall early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer tight fits (small post_residual)
    let mut score = post;

    // Penalize leaving a "dead zone": residual too small for likely future items
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 1.5; // tiny unusable slivers are wasted space
    }

    // Lookahead: reward bins whose post_residual can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 4.0 + 6.0 * (nxt / cap); // keeps room for the upcoming item
        } else {
            score += 3.0; // this placement kills future fit in this bin
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0 + 10.0 * (item / cap);
    }

    // Scarcity pressure: few fitting bins -> avoid fragmenting them; consider new bin
    if !is_new_bin && fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global residual alignment: prefer bins whose residual is near mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate scoring: attractive for large items with poor existing fits,
    // unattractive when many bins fit well or item is small
    if is_new_bin {
        let poor_fit_pressure = if fitting_bins_count == 0 {
            0.0
        } else {
            (item / cap) * (1.0 - item / cap) * 20.0
        };
        let scarcity = if fitting_bins_count <= 1 { 14.0 } else { 0.0 };
        // Opening a bin costs ~cap of potential waste; discourage early/stream start
        let horizon = 1.0 - progress;
        score = post + 18.0 * horizon - scarcity - poor_fit_pressure * (item / cap);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is mandatory
        }
        if item >= 50.0 && fitting_bins_count >= 1 && post >= 20.0 {
            score -= 6.0; // big item: fresh space is valuable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap; // in [0,1]
    let t = progress;
    // Weight dead space more heavily as the stream progresses (polynomial ramp).
    let dead_weight = 1.0 + 3.0 * t * t + 2.0 * t * t * t;
    score += dead_weight * norm_post * norm_post * cap * 0.5;

    // Reward tight fits: quadratic bonus for small post_residual.
    score -= 4.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 + t);

    // Lookahead coupling: penalize wasting space when next item could use it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 2.0 * (nxt / cap) * (1.0 + t);
        } else {
            score += 3.0 * (1.0 - post / nxt.max(1.0)) * (0.5 + t);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + t);
    }

    // New-bin candidate: penalize mildly so it's only chosen when fits are terrible.
    if bin_residual == bin_capacity {
        score += 5.0 + 4.0 * t;
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += 0.3 * ((open_bins_count as f64).ln() + 1.0) * (mean_residual / cap - norm_post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (dead space minimization).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Harmonic classes: classify post_residual by modular arithmetic.
    // Residuals that are "harmonically useful" (multiples of common small sizes)
    // are less damaging than awkward residues.
    let r = post_residual;
    if r > 0 {
        // Multiples of 10 are highly reusable (items often ~10..80 multiples).
        if r % 10 == 0 {
            score -= 15.0;
        } else if r % 5 == 0 {
            score -= 5.0;
        }
        // Dead-space penalty for tiny unusable residues (below min item size 1..100 range,
        // but small residues are hard to fill).
        if r < 10 {
            score += 30.0;
        }
        // Integer division thresholds: quantize residual into bands.
        let band = r / 25; // 0..4
        score += band as f64 * 3.0; // larger residual = looser bin, mild penalty to prefer tight fits
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is bad
    // and lookahead suggests a large next item that would waste this bin's space.
    if bin_residual == bin_capacity {
        // Neutral baseline: prefer new bin only if existing fits are poor.
        score += 25.0;
        if next_item_size > 0 && next_item_size > post_residual {
            // A big next item makes hoarding space valuable: penalize new-bin slightly less.
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
    }

    // Lookahead coupling: if next item fits perfectly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        if next_post <= 10 {
            score -= 50.0;
        } else if next_post < 25 {
            score -= 15.0;
        }
    }
    // If next item would NOT fit here, mildly penalize (this bin's residual is awkward).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Stream progression: early on, be more liberal about opening bins (spread risk);
    // late in stream, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Mean residual coupling: if mean residual across bins is high, penalize
    // leaving another large residual (encourage consolidation).
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical items (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mild penalty when this bin's residual is far above mean residual (poor consolidation)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    // New-bin candidate: neutral baseline with slight progression-based bias
    if bin_residual == bin_capacity {
        score += 5.0 + (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Next item fits comfortably in the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Next item would NOT fit here: penalize relative to how close we came
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Penalize dead space, especially small unusable gaps
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 15.0; // tiny dead space is worthless
        }
        // Squared penalty for waste relative to capacity
        score += (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 20.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with below-average residual (fill emptier-ish bins first keeps tight ones)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild preference for keeping open bin count low later in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // fresh bin pairs well with upcoming item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (low post_residual) with a non-linear bonus
    let tight_fit = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tight_fit * tight_fit;

    // Penalize dead space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.2 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize proportional to wasted potential
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer filling existing ones over opening new
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Compare against mean residual: bins with less residual than average are better targets
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it moderately attractive only when item is large
    if bin_residual == bin_capacity {
        score -= 5.0 + 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * 0.5;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Lookahead: favor bins whose residual matches the next item
    if nxt > 0.0 {
        let gap = (pr - nxt).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
    }

    // Penalize waste relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for proliferating bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: smooth discouragement unless item is large
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - item / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into deciles.
    let post_class = post_residual / 10; // 0..=10
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Reward when next item's harmonic class is compatible with the residual class.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_class as i32 - next_class as i32).abs();
        // Perfect class match (same decile) gets the strongest bonus.
        let class_bonus = if gap == 0 {
            35.0
        } else if gap == 1 {
            18.0
        } else {
            6.0
        };
        // Tightness: how well next item fills the post-residual.
        let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= class_bonus * (0.4 + 0.6 * tight);
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to wasted space.
        score += 0.5 * post_residual as f64;
    }

    // Exact-fill harmony: post_residual is a multiple of common item sizes.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 25 == 0 {
        score -= 22.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;
    }

    // Penalize awkward dead space in (0,10): unusable for smallest items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        let pressure = (step_index as f64 / (total_items.max(1) as f64)) * 0.5 + 0.5;
        // Base cost of opening a new bin, discounted by residual pressure.
        score += 45.0 - 40.0 * crowded * pressure;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 15.0; // big item coming: fresh bin is valuable
        }
    }

    // Mild preference for keeping mean residual balanced.
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: waste after placement.
    let mut score = post;

    // Strict dead-space avoidance: gaps too small to ever hold a typical item
    // (min item size unknown, use conservative small-item threshold) are heavily penalized.
    // A gap of 1..=9 is essentially unusable; scale penalty nonlinearly.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 8.0; // up to +72 for a 1-unit sliver
    }

    // Perfect fit: extremely rewarded.
    if post == 0.0 {
        score -= 60.0;
    }

    // Reward tight fits relative to capacity (fill fraction of residual used).
    let fill = item / bin_residual.max(1) as f64;
    score -= fill * 25.0;

    // Prefer bins whose residual was already small (consolidate waste).
    score += (bin_residual as f64 / cap) * 10.0;

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // make existing bins more attractive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * 3.0;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: default attractiveness of a fresh empty bin.
    // Penalize opening new bins unless the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        score += 30.0 + pressure * 4.0;
        // But a fresh bin is fine when item is large relative to capacity.
        score -= (item / cap) * 15.0;
    }

    // Lookahead coupling: if the next item could use the post-residual,
    // reward leaving that exact gap; otherwise penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() < 1.0 {
            score -= 20.0; // next item fits this gap exactly
        } else if post >= nxt && post - nxt < 10.0 {
            score -= 10.0; // next item leaves near-zero waste here
        } else if post > 0.0 && post < nxt {
            score += 5.0; // gap too small for the next item
        }
    }

    // Early in the stream, be slightly more willing to open bins (build diversity).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 4.0;

    // Mild preference toward bins below mean residual (balance residuals down).
    score += ((bin_residual as f64 - mean_residual) / cap) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;

        // Perfect 2-step match: post_residual exactly equals next item size.
        // Strongly reward this (subtract heavily) so the chain continues.
        let diff = pr - nxt;
        if diff == 0.0 {
            score -= 60.0 + 20.0 * progress;
        } else if diff > 0.0 {
            // Post residual can still fit next item, but imperfectly.
            // Penalize proportionally to mismatch, normalized by capacity.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space: next item cannot fit here -> waste.
            // Penalize the unusable gap, more when gap is large relative to item.
            let waste = (-diff) / nxt.max(1.0);
            score += 15.0 * waste.min(2.0) + 5.0;
        }

        // Coupling with mean residual: bins whose post residual is close to
        // the mean residual keep the bin population balanced.
        let mean_gap = (pr - mean_residual).abs();
        score += 0.15 * mean_gap;
    } else {
        // Last item: just minimize leftover space.
        score += 0.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (huge post residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin slightly, unless the current
    // fit leaves a very large residual (poor fit) relative to capacity.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64; // = 1 - item/C
        if poor_fit < 0.25 {
            // Item nearly fills an empty bin: encourage new bin.
            score -= 30.0;
        } else {
            // Default: prefer reusing existing bins.
            score += 12.0;
        }
    }

    // Mild pressure to close out bins when many are open.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - fit_ratio).powi(6);

    // Penalize dead space that no plausible future item can use.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.3 * (post_residual as f64).sqrt();
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 10.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).min(1.0);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // or the item barely fits anywhere.
    if bin_residual == bin_capacity {
        let poor_fits = (mean_residual - item_size as f64).abs() < 8.0 || fitting_bins_count <= 1;
        if poor_fits && open_bins_count > 0 {
            score -= 20.0;
        } else {
            score += 25.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Time horizon: early in stream, be conservative (waste less); late, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress * fit_ratio;

    // Divergence from mean residual: prefer bins whose residual deviates sensibly.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Mild penalty for spreading across too many open bins when a tight fit exists.
    if fit_ratio < 0.2 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic bonus for small post_residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tight) * (1.0 - tight) * (1.0 - tight);

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 25.0 * (dead / (bin_capacity as f64)) * (1.0 - dead / (bin_capacity as f64)).exp();
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to wasted opportunity.
        score += 8.0 * (next_item_size as f64 / (bin_capacity as f64));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 + 30.0 * progress;
    }

    // Penalize scattering across many open bins early on.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Penalize bins whose residual deviates far from mean residual (imbalance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (0.5 + 0.5 * progress);

    // New-bin candidate: make it moderately costly, cheaper late in the stream
    // when open bins are mostly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / (bin_capacity as f64);
        score = 70.0 - 40.0 * progress + 20.0 * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small dead space is good.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual fraction of capacity

    // Reward tight fits strongly (post_residual near zero).
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Modulo logic on post_residual: residuals that are "harmonic"
    // multiples of common item sizes are more likely to be filled later.
    let harmonic_bonus = if post_residual >= 10 {
        match post_residual % 10 {
            0 => 12.0, // exact decade residual: highly reusable
            5 => 6.0,  // half-decade: moderately reusable
            _ => 0.0,
        }
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize dead space in awkward ranges (11..=30): hard to fill.
    if post_residual > 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.5;
    }

    // Coupling with next item: if the next item fits exactly in post_residual,
    // strongly reward; if next item fits but leaves nothing, reward; if next
    // item does not fit, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 8.0; // next item won't use this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early in the
    // stream or current bins have large mean residual (bad fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        score = cap * 1.5; // baseline: new bins are worst by default
        score -= 20.0 * fragmentation; // if open bins are fragmented, new bin ok
        score -= 25.0 * (1.0 - progress); // early stream: opening bins cheaper
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative anyway
        }
    } else {
        // Slight preference for fuller bins (smaller residual before placing).
        score += (bin_residual as f64 - item_size as f64) * 0.05;
        // Prefer bins whose residual is below mean residual (tighter bin).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate as stream progresses.
    score += 3.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "unusable" dead space: residuals too small for typical future items.
    let dead_zone = 15.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.5;

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is excellent; encourage consolidation when many bins open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // If this is the only fitting bin, favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if next item can use the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Mild penalty if this bin's residual deviates from mean residual (keeps balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    // New-bin candidate: neutral-ish baseline; only open new bin when existing
    // fits are poor (handled by penalties above).
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post residual exactly fits next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // ideal: bin becomes exactly full after next item
        } else if post_residual >= next_item_size {
            // next item fits here afterward; reward tight coupling
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit in residual; penalize large leftover dead space
            score += 0.3 * post_residual as f64;
        }
    } else {
        // last item: prefer minimal leftover
        score += 0.5 * post_residual as f64;
    }

    // Reward tight fits relative to capacity (small waste fraction)
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Reward bins whose residual is below mean residual (consolidating small spaces)
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = if fitting_bins_count == 0 { 400.0 } else { 0.0 };
        score = 120.0 + 50.0 * (1.0 - progress) - pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.2 * next_item_size as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward near-perfect fits (small post_residual), non-linearly.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 12.0;
    } else {
        // penalize large dead space, superlinear
        score += (post_residual as f64).powi(2) / 200.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.1; // best when next item fits snugly too
    }
    // Penalize leaving a residual that is useless for typical future items.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // If many bins fit, prefer the one with tightest fit (already via post_residual),
    // but add mild penalty to discourage spreading across many open bins.
    if fitting_bins_count > 3 {
        score += 2.0;
    }

    // New-bin candidate handling: opening a bin is expensive early (want bins for
    // flexibility) but acceptable late or when no tight option exists.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 * 3.0;
        let time_pressure = 10.0 * progress;
        // Base cost of a fresh bin: large dead space of (capacity - item_size).
        score += 45.0 + open_pressure - time_pressure;
        // If no open bin fits tightly, opening a new bin is more attractive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Big items into fresh bins is natural.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Global balance: prefer bins whose residual deviates below the mean
    // (consolidate space into few bins, keep other bins roomy).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.15;
    }

    // Mild late-stream pressure to close bins tightly.
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear coupling: reward small post_residual with a convex (quadratic-cubic) term.
    let tightness = 1.0 - post / cap; // in [0,1], high = tight fit
    score -= 30.0 * tightness * tightness * (1.0 + progress);

    // Penalize residuals that are large but awkward: mid-range dead space grows super-linearly.
    let dead = post / cap;
    score += 8.0 * dead * dead * (1.0 - dead) * (1.0 + progress);

    // Lookahead coupling: reward if next item fits smoothly into post_residual (smooth bell around exact fit).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_quality = (-gap / 20.0).exp();
        score -= 15.0 * match_quality * (0.5 + 0.5 * progress);
        // Penalize leaving a residual that fits almost nothing (between next item and typical min size).
        if post_residual > 0 && (next_item_size as u32) > post_residual {
            score += 5.0 * (1.0 - (post_residual as f64 / cap));
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.5 + 0.5 * progress);
    }

    // Many open bins with high mean residual: penalize spreading items; prefer consolidation.
    let mean_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
    score += 3.0 * mean_tightness * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate (empty bin): mildly discourage early opening, encourage when progress is high
    // and existing bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 12.0 * (1.0 - progress) - 10.0 * fragmentation * progress;
        // Never open a new bin when a decent fit exists elsewhere.
        if post_residual == 0.0 { score -= 5.0; }
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (divisible by common item sizes) are less wasteful.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { class_bonus += 6.0; }
        if pr % 20 == 0 { class_bonus += 4.0; }
        if pr % 25 == 0 { class_bonus += 3.0; }
        if pr % 50 == 0 { class_bonus += 3.0; }
        // integer-division threshold bands on post_residual
        let band = pr / 10; // 0..10
        class_bonus += match band {
            0 => -18.0,          // tiny dead space, terrible
            1 => -10.0,
            2 => -4.0,
            3..=5 => 2.0,        // sweet spot: room for a mid item
            6..=8 => 1.0,
            _ => 0.0,
        };
    } else {
        class_bonus += 25.0; // perfect fill
    }
    score -= class_bonus;

    // Lookahead coupling: does post_residual accommodate the next item exactly / well?
    if next_item_size > 0 && next_item_size <= pr {
        let next_post = pr - next_item_size;
        let fit_quality = if next_post == 0 { 14.0 } else if next_post % 10 == 0 { 9.0 } else { 4.0 };
        score -= fit_quality;
    } else if next_item_size > pr {
        // this bin's leftover will be dead for the next item
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity means empty bin).
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and would
        // leave a harmonically clean residual in a fresh bin, or nothing fits well.
        let fresh_post = bin_capacity - item_size;
        let mut open_bonus = 8.0; // mild default penalty to prefer existing bins
        if fresh_post % 10 == 0 { open_bonus -= 4.0; }
        if fresh_post == 0 { open_bonus -= 30.0; }
        if next_item_size > 0 && next_item_size <= fresh_post { open_bonus -= 5.0; }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        open_bonus += progress * 10.0;
        score += open_bonus;
    }

    // Prefer tighter bins among equals: closeness of residual to item size.
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    // Spread-awareness: if mean residual is high, reward filling this bin down.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable
    // (items are >= 1, but small gaps rarely match future demand).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Reward tight fits generally (small waste relative to capacity).
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot use the leftover: dead space risk.
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage opening extra bins when many are open,
    // unless the fit is truly bad.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 18.0 + 4.0 * open_bins_count as f64 + 10.0 * progress;
        // But if very few bins can fit the item, opening a new bin is safer.
        if fitting_bins_count <= 1 {
            score -= 22.0;
        }
    } else {
        // Using an existing bin reduces pressure slightly; last-chance bin gets bonus.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Prefer bins whose residual deviates favorably from the mean
        // (pack into the fullest bins first to consolidate space).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: be greedier (tighter fits) later in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 + 2.0 * progress;

    // Reward tight fits: small post_residual is good.
    score -= tightness * (bin_capacity as f64 - post_residual as f64) * 0.05;

    // 2-step lookahead: strongly reward exact match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin will be exactly filled
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64); // next item fits too
        } else {
            // next item won't fit: penalize proportionally to wasted leftover
            let waste = post_residual as f64;
            score += 0.10 * waste * (0.5 + progress);
        }
    }

    // Penalize creating unusable dead space relative to mean residual.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny sliver: likely dead space
    }
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline; open only when fits are poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere else
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on leftover space.
    let cap_f = bin_capacity as f64;
    let tightness = post_residual as f64 / cap_f;
    score += 2.0 * tightness * tightness * cap_f;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }
    // If next item would fit better in a fresh bin than here, penalize wasting space.
    if next_item_size > post_residual && next_item_size > 0 {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.05 * waste;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Favor bins with below-mean residual (more free space) when many bins are open.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (bin_res_f - mean_residual);
    }

    // Time horizon: late in the stream, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (high fitting count with poor fits, or item large relative to mean residual).
    if bin_residual == bin_capacity {
        let base = 0.5 * cap_f; // fresh-bin baseline cost
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        let big_item = item_size as f64 > mean_residual;
        score = base - 10.0 * scarcity - if big_item { 8.0 } else { 0.0 } + 10.0 * progress;
        // Early stream: opening bins is cheap; late stream: expensive.
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 12.0 * pr_norm * pr_norm * (1.0 + 2.0 * progress) * cap * 0.1;
    score -= 8.0 * p2 * pr_norm * (1.0 - p3);

    // Reward tight fits, more aggressively late in the stream
    let tightness = 1.0 - pr_norm;
    score -= 10.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: favor bins whose post-residual can host the next item
    if next > 0.0 && pr >= next {
        score -= 6.0 * (1.0 - ((pr - next) / cap).abs()) * (0.5 + progress);
    } else if next > 0.0 {
        score += 4.0 * (next - pr) / cap * (1.0 + progress);
    }

    // Dead-space penalty relative to mean residual
    score += 5.0 * (pr - mean_residual).abs() / cap;

    // Last-chance bin: strongly discourage wasting it, more so early on
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer consolidating into existing bins as open-bin count grows
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Mild penalty for opening a new bin unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (harmonic classes).
    let post = post_residual as f64;
    score -= 40.0 * (1.0 - post / bin_capacity as f64).powi(3);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class matching: penalize post_residual that is too small to
    // hold any plausible future item (dead space), reward residuals in
    // "usable" classes (>= typical minimum item size).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 50.0;
    }
    // Dead-space penalty grows when post_residual is in an awkward band
    // (small but nonzero): integer-division class of post_residual / 10.
    let dead_class = post_residual / 10;
    if dead_class >= 1 && dead_class <= 3 {
        score += 12.0 * dead_class as f64;
    }

    // Lookahead compatibility: reward if next item fits in post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize wasting space the next item could have used elsewhere.
            score += 8.0;
        }
        // Harmonic pairing: post_residual + next_item_size exactly filling
        // a future bin fraction is great.
        if post_residual + next_item_size == bin_capacity {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits
    // well. Base penalty on open bins count and current fit quality.
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64 / bin_capacity as f64;
        let new_bin_penalty = 55.0
            + 6.0 * open_bins_count as f64
            - 40.0 * (1.0 - fit_quality)
            + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        score += new_bin_penalty;
    }

    // Prefer bins below mean residual (fill emptier bins first, keep tight
    // bins available? Actually keep tight bins for small items): mild term.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Progress-scaled tightness: as stream advances, prioritize compactness.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are small but nonzero are
    // nearly unusable dead space. Penalize gaps in the "unusable" range.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 4.0 * post_residual as f64; // tiny gaps are terrible
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    } else if post_residual <= 20 {
        score += 8.0; // small-ish gaps still risky
    } else {
        // Larger usable gaps: mildly reward keeping them large enough to matter
        score -= 2.0;
    }

    // Dead space becomes worse if the next item cannot use it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0; // gap is reusable by lookahead
    }

    // Open-bins pressure: discourage opening new bins early, allow late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins are open / early.
        score += 25.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    } else {
        // Existing bin: reward reuse, more so when many bins are open.
        score -= 5.0 + 0.5 * open_bins_count as f64;
    }

    // Last chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (denser bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin becomes exactly usable by the next item -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Leftover after next item would fit; reward proportionally to tightness of the chain.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 120.0 - chain_waste.min(120.0);
        } else {
            // post_residual < next_item_size: dead space relative to lookahead; penalize.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 50.0;
    }

    // Reward tight fits of the current item (small post_residual overall).
    score -= (bin_capacity - post_residual) as f64 * 0.3;

    // Relative to mean residual: bins already loose are better hosts.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good fit exists.
    if bin_residual == bin_capacity {
        let base = 30.0 + (open_bins_count as f64) * 2.0;
        score += base;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 200.0; // next item needs a fresh bin anyway
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize large post_residual that cannot fit the next item (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can also host the lookahead item.
            score -= 12.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Dead space penalty grows with how much is stranded.
            let dead = post_residual as f64;
            score += 0.6 * dead * dead / bin_capacity as f64;
        }
    }

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // When many bins fit the item, prefer the emptiest reasonable bin
    // (concentrate items, keep small residuals in fewer bins).
    if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Prefer bins whose residual is close to item size (best-fit coupling).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * gap;

    // Time horizon: early in the stream, be conservative (favor filling existing
    // bins to keep open_bins_count low); late in the stream, exact fits matter most.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * (1.0 - progress) * (fitting_bins_count as f64).ln().max(0.0);

    // Penalize opening a new bin when open bins have plenty of average room,
    // unless the item is large and the fit is tight.
    if bin_residual == bin_capacity {
        let avg_room = mean_residual / bin_capacity as f64;
        let tight = post_residual == 0 || (next_item_size > 0 && post_residual < next_item_size && post_residual < 10);
        if avg_room > 0.25 && !tight {
            score += 30.0 * avg_room;
        }
        // Mild fixed cost for a new bin.
        score += 5.0;
    }

    // Slight preference for bins with residual near multiples of common sizes.
    let mod10 = (post_residual % 10) as f64;
    score += 0.3 * (mod10 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter fits matter more (dead space is costlier).
    let tightness = 1.0 - (pr / cap).powf(2.0); // 1 = perfect fit, 0 = empty bin
    let urgency = (progress * std::f64::consts::PI).sin().powf(2.0) + 0.25 * progress;
    score -= 30.0 * tightness * urgency * (it / cap);

    // Penalize residual that is unusable for the lookahead item (smooth quadratic).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).max(0.0) / cap;
        score += 20.0 * gap * gap * urgency;
        // Reward residual that exactly accommodates the next item (smooth bump).
        let fit_next = 1.0 - ((pr - nx).abs() / cap).min(1.0);
        score -= 15.0 * fit_next * fit_next * (nx / cap);
    } else {
        // Last item: strongly prefer minimal waste.
        score += 10.0 * (pr / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly; only win when fits are poor.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - pr).abs() / cap;
        score += 12.0 + 8.0 * (1.0 - spread) - 10.0 * (open_bins_count as f64).ln().max(0.0) / 3.0;
    } else {
        // Slightly prefer bins whose residual is below the mean (consolidate waste).
        let dev = (mean_residual - pr) / cap;
        score -= 6.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, with quadratic tightening for tiny waste.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Harmonic class of the post_residual: treat capacity as 4 quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter;
    match class {
        0 => score -= 18.0,               // near-perfect fit
        1 => score -= 6.0,                // small residual, still attractive
        2 => score += 4.0,                // mid residual
        _ => score += 10.0,               // large residual left behind
    }

    // Modulo-class logic: residuals that match common item sizes (10..80 grid) are reusable.
    let reusable = post_residual >= 10 && post_residual % 10 == 0;
    if reusable { score -= 8.0; }

    // Next-item lookahead: bonus if the residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 14.0 - (slack as f64 / bin_capacity as f64) * 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // residual cannot fit next item: penalize proportionally to how stranded it is
        score += (next_item_size as f64 / bin_capacity as f64) * 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // bins are crowded (high mean residual) and this bin is genuinely empty.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual / bin_capacity as f64;
        // Penalize new bins mildly; relief when open bins are nearly full.
        score = bin_capacity as f64 * (1.0 - 0.55 * crowded) + 20.0 * (1.0 - progress);
        // If the item perfectly fits a fresh bin (item near capacity), new bin is great.
        if item_size >= bin_capacity * 9 / 10 { score -= 30.0; }
        // With only one fitting bin, avoid opening a new bin unless that bin is bad.
        if fitting_bins_count <= 1 { score += 15.0; }
    }

    // Prefer filling bins that are already committed (fewer open bins overall).
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are effectively unusable -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // If the next item fits exactly in the post-residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 40.0;
    }
    // If next item cannot fit in the post-residual but could fit elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading onto new bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure scaling.
        score = 100.0 + 50.0 * pressure;
        // Opening a new bin is acceptable if the item would leave a bad gap elsewhere.
        if post_residual < 10 && fitting_bins_count <= 2 {
            score -= 70.0;
        }
    } else {
        // Mild penalty for bins far below mean residual (poor consolidation).
        if (bin_residual as f64) > mean_residual + 30.0 {
            score += 5.0;
        }
    }

    // Late in the stream, tighten packing (less tolerance for waste).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if (post_residual as i64) >= (next_item_size as i64) {
            // Next item fits here later: reward closeness to perfect chain fit.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            score += 0.5 * diff;
        }
    }

    // Tight fit reward: small post_residual is good unless it's wasted relative to lookahead.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Penalize bins far below mean residual (fragmented bins) mildly.
    score += 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it's chosen only
    // when no open bin offers a good fit (its post_residual is large, so the
    // base term already penalizes it; add small bonus early in stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
        // If next item cannot fit anywhere else well, opening new bin is fine.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 15.0;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score -= 0.05 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual close to 0)
    if post_residual == 0 {
