    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // Penalize leaving dead space that no plausible item can use
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 50.0;
    }
    // Residuals too small for typical items are dead space
    if post_residual < 10 && post_residual > 0 {
        score += 12.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead: reward saving space for the next item if it fits nicely after this one
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 22.0 * (1.0 - pair_waste / cap);
        if post_residual == next_item_size {
            score -= 30.0; // perfect two-item closure
        }
    } else if next_item_size > post_residual {
        // Next item can't use leftover here: mild penalty proportional to leftover
        score += 6.0 * (post_residual as f64 / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: encourage closing bins (reducing fragmentation)
    let open_f = open_bins_count as f64;
    score += open_f * 1.5;

    // Prefer placing into bins whose residual is large relative to mean (use the emptiest fitting bin)
    if bin_residual as f64 > mean_residual {
        score -= 5.0 * ((bin_residual as f64 - mean_residual) / cap);
    } else {
        score += 5.0 * ((mean_residual - bin_residual as f64) / cap);
    }

    // Time horizon: late in the stream, be greedier about tight fits
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * t;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let base = cap * 0.55;
        score = base + open_f * 2.0 + 10.0 * t;
        if fitting_bins_count == 0 {
            score -= 25.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= cap {
            score -= 15.0; // room to pair with next item in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with a smooth non-linear
    // polynomial coupling that punishes large dead space quadratically.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth progress coupling: as the stream advances, residual space becomes
    // more valuable, so dead space is penalized more aggressively.
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += pr * prog_term * 0.8;

    // Reward when this placement leaves room for the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0);
        if pr >= nxt && pr - nxt < 10.0 {
            score -= 4.0; // near-perfect two-item packing
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild penalty proportional to crowding of open bins, encouraging
    // consolidation rather than bin proliferation.
    score += open_bins_count as f64 * 0.05;

    // Penalize placements far from the mean residual (smooth coupling),
    // preferring bins whose fill level is consistent with the fleet.
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * dev / cap;

    // New-bin candidate: empty bin has pr == cap. Make it unattractive unless
    // the item is huge and no open bin fits well (handled via base pr terms),
    // but keep a smooth escape hatch late in the stream.
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition dead space into residue classes mod 10
    let class = post_residual % 10;
    // Small dead space (0-9) is nearly perfect fill; heavily reward
    score -= (10 - class as f64) * 0.5;

    // Integer-division threshold: post_residual >= 50 leaves room for a medium item
    let half = post_residual / 50;
    score -= half as f64 * 2.0;

    // Perfect fit detection: residual is a multiple of common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 0.5;
        // If nothing fits well (large item, few fitting bins), allow new bin
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Progress-aware residual normalization: late in stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Mean residual coupling: avoid bins far below mean residual (fragmented bins)
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are permanently wasted.
    let min_item = 1u32; // unknown distribution, so any residual > 0 could theoretically be used,
                         // but tiny gaps (< ~10) are statistically near-unusable in practice.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Tightness ratio: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Lookahead coupling: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            // next item won't fit here; a very large post_residual becomes a stranded gap
            score += 5.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Compare against mean residual of open bins: bins already tighter than average
    // should be preferred targets (their remaining space is scarce).
    let dev = mean_residual - post_residual as f64;
    score -= 0.5 * dev;

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // is a decent fit, i.e. penalize the empty-bin call mildly but reward it when
    // all open residuals are poor (large mean_residual spread vs item).
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        let mut new_bin_score = 55.0;
        // if the item is large, a fresh bin wastes less capacity potential
        new_bin_score -= 20.0 * fill;
        // if open bins are crowded (low mean residual), a new bin is more justified
        new_bin_score -= (100.0 - mean_residual).max(0.0) * 0.3;
        // early in the stream, opening bins is cheaper
        new_bin_score -= 10.0 * (1.0 - progress);
        score = score.min(new_bin_score + 1.0);
        // ensure empty-bin call scores the new-bin cost, not the trivial full-residual
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain fit
        } else if post_residual > next_item_size {
            // next item can still fit here: mild reward proportional to tightness
            score -= 8.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit: penalize dead space, worse when gap is small
            score += 6.0 + 10.0 * (1.0 - diff / bin_capacity as f64);
        }
    }

    // Penalize very small unusable post-residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect closure
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 2.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless current bin fits poorly
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && post_residual >= next_item_size && (post_residual as i64 - next_item_size as i64).abs() > 20;
        if poor_fit {
            score += 5.0;
        } else {
            score += 30.0; // prefer existing bins by default
        }
    }

    // Late in stream: be more conservative with open bins
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already dominates, add mild nonlinearity)
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.25) * 0.05;
    } else {
        score -= 15.0; // perfect fill is excellent
    }

    // Lookahead: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + (next_item_size as f64) * 0.05;
    }
    // If next item leaves an awkward gap (next fits bin_residual but not post_residual), penalize
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current bin would leave large dead space
    // or open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        let dead = post_residual as f64; // item in fresh bin leaves capacity - item free
        score += dead * 0.10;            // penalize wasting fresh bin on small items
        score -= 6.0 * (1.0 - progress); // early on, new bins are cheap-ish
        if open_bins_count > 0 && post_residual as f64 > mean_residual + 20.0 {
            score -= 5.0; // existing bins have big residuals anyway; spreading ok
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open new bin
        }
    } else {
        // Prefer bins whose residual is close to item (classic best fit sharpening)
        let tightness = (bin_residual - item_size) as f64;
        score -= (bin_capacity as f64 - tightness) * 0.02;
    }

    // Mild preference to consolidate into fewer bins when many are open
    if open_bins_count > 3 {
        score -= 0.5;
    }

    // Penalize placing into bins with residual far above mean (keeps balanced residuals)
    score += ((bin_residual as f64 - mean_residual) * 0.05).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = (pr / cap).clamp(0.0, 1.0);
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = fitting_bins_count as f64;
    let nxt = next_item_size as f64;

    // Smooth polynomial shaping of waste: dead space is super-linearly bad.
    score += 12.0 * x * x + 20.0 * x * x * x;

    // Progress coupling: waste tolerance shrinks as the stream advances.
    score *= 1.0 + 0.8 * prog * x;

    // Reward scarce fits: if this bin is one of few that fit, strongly favor it.
    score -= 25.0 / fit;
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x);
    }

    // Lookahead coupling: leftover space is valuable if it can host the next item.
    if nxt > 0.0 {
        let usable = (nxt - pr).max(0.0) / cap;
        score += 18.0 * usable * usable;
        let match_bonus = if pr >= nxt { 1.0 - (pr - nxt) / cap } else { 0.0 };
        score -= 10.0 * match_bonus * match_bonus;
    }

    // Mild penalty when bin is far below mean residual (poor relative fit).
    score += 0.15 * (mean_residual - pr).max(0.0);

    // Prefer consolidating into fewer bins when many are open.
    score -= 0.4 * open_bins_count as f64 * (1.0 - x);

    // New-bin candidate: keep it expensive so it only wins on genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * prog;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: dead space that is a small
    // remainder modulo 10 is nearly unusable for typical items.
    let rem_class = post_residual % 10;
    let div_class = post_residual / 10;
    if post_residual > 0 {
        score += (10 - rem_class) as f64 * 0.9; // penalize "almost divisible" waste
    }
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // tiny dead space: bin effectively closed
    }

    // Reward tight fits: post_residual small relative to capacity fraction bands
    let frac = post_residual as f64 / cap_f;
    if frac <= 0.05 {
        score -= 40.0;
    } else if frac <= 0.15 {
        score -= 20.0;
    } else if frac <= 0.35 {
        score -= 8.0;
    }

    // Lookahead: if next item fits in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 + slack * 0.3;
        // perfect chaining: next item exactly fills
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; leftover becomes dead space
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.2;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer fuller bins overall (relative to mean residual of open bins).
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.25;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap_f < 0.25 + 0.5 * (step_index as f64 / total_items.max(1) as f64);
        let bad_fit = post_residual > 0 && (item_size as f64 / cap_f) < 0.5 && rem_class != 0;
        if crowded || bad_fit {
            score -= 15.0;
        } else {
            score += 20.0; // discourage spawning bins when good fits exist
        }
    }

    // Integer-division threshold coupling: bins whose residual div class is high
    // are more reusable; mildly prefer placing into them.
    score -= div_class as f64 * 0.5;

    // Mild stream-stage regularization to avoid bin explosion early.
    score += open_bins_count as f64 * 0.05 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below min item size) are pure waste.
    // Penalize post_residual in the "dead zone" heavily; large post_residual is reusable.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0 * pr; // unusable dead space
        } else if post_residual < 20 {
            score += 25.0 * pr; // near-dead gap
        } else {
            // reusable gap: mild penalty, prefer tight fits
            score += 0.5 * pr;
        }
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (which wastes bin_residual entirely).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let ob = open_bins_count as f64;
    score += 1.5 * ob * (pr / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (tight fit signal).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Lookahead: if the next item fits the post_residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap just larger than the next item (near-miss waste).
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score += 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current bin would leave a bad gap AND many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_if_used = bin_residual - item_size;
        let bad_gap = if waste_if_used < 10 { 1.0 } else if waste_if_used < 20 { 0.5 } else { 0.0 };
        // Base cost of a fresh bin; reduced if existing bins would waste space anyway.
        score += 55.0 - 45.0 * bad_gap - 2.0 * ob + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits too: reward tight chained fit
            let chain_left = post_residual - next_item_size;
            score -= 60.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
            if chain_left == 0 {
                score -= 200.0;
            }
        } else {
            // next item cannot use the leftover: penalize dead space relative to next size
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Compare post_residual against mean residual: leaving below-average residual is good consolidation
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Many open bins: encourage closing bins out (filling existing ones)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: make it unattractive unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let avg_usability = mean_residual / bin_capacity as f64;
        // open a new bin only if existing residuals are large/fragmented relative to item
        let fragmentation = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        score = 150.0 + 200.0 * fragmentation - 50.0 * (1.0 - avg_usability);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // if next item is huge, a fresh bin may be wise
            if next_item_size as f64 > mean_residual {
                score -= 120.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize leaving residuals that are awkwardly small but nonzero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover; penalize large leftover more.
            score += 0.05 * post_residual as f64;
        }
    }

    // Prefer bins with residual below mean residual (denser bins) mildly.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Early in stream: be pickier about waste (long horizon ahead).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * (1.0 - progress);

    // Discard opening new bins when good existing fits exist.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Late in stream, opening new bins is more acceptable.
        score -= 10.0 * progress;
    }

    // Mild bonus for using bins with many occupants implied by small residual.
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: reward tight fits (low post_residual), with non-linear emphasis
    let mut score = pr * (1.0 + 0.8 * (pr / cap).powi(2));

    // Normalized residual polynomial coupling with stream progress
    let r_norm = pr / cap;
    score += 12.0 * r_norm.powi(3) * (1.0 - progress);
    score += 6.0 * r_norm.powi(2) * progress;

    // Penalize placing small items into bins with large residuals (wasteful)
    let fill = it / cap;
    score -= 8.0 * fill * (1.0 - r_norm);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it attractive early, discourage when tight fits exist
    if bin_residual == bin_capacity {
        score = pr as f64 + 15.0 * (1.0 - progress) - 5.0 * progress;
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin when an existing one is last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: post_residual in harmonic classes.
    let pr = post_residual as u32;
    if pr == 0 {
        score -= 1000.0; // perfect fill
    } else if pr < 5 {
        score -= 200.0;
    } else if pr < 10 {
        score -= 80.0;
    } else if pr < 20 {
        score -= 30.0;
    } else {
        // dead-space penalty grows super-linearly for large leftovers
        score += (pr as f64 - 20.0) * 0.8;
    }

    // Harmonic class of post_residual: residuals divisible by small units are reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 15.0; // residual that matches common item sizes
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // among several fitting bins, prefer tighter fits (already via post_residual)
        score += fitting_bins_count as f64 * 2.0;
    }

    // Lookahead coupling: if next item fits into post_residual, this placement is great
    if next_item_size > 0 && next_item_size <= pr {
        score -= 40.0;
        // harmonic class: next item exactly divides residual
        if next_item_size > 0 && pr % next_item_size == 0 {
            score -= 30.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here; slight penalty unless post_residual tiny
        if pr > 25 {
            score += 15.0;
        }
    }

    // New-bin candidate handling: opening a new bin wastes mean residual across open bins
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, offset by how poorly this item fits existing bins
        let mut nb = 60.0 + open_bins_count as f64 * 5.0;
        // if item is large relative to capacity, opening fresh bin is more attractive
        if (item_size as f64) > 0.6 * bin_capacity as f64 {
            nb -= 40.0;
        }
        // if this is a last-chance situation elsewhere we already reward using it;
        // make new bin less attractive when a decent fit exists
        if pr >= 0 && fitting_bins_count >= 1 && item_size <= 50 {
            nb += 30.0;
        }
        // late in stream, consolidate into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb += progress * 40.0;
        score += nb;
    }

    // Mild preference to balance residuals: avoid bins far below mean residual
    let diff = mean_residual - post_residual as f64;
    score += diff.abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (>=1) are dead space.
    if post_residual > 0 {
        // Dead space severity grows super-linearly for tiny unusable gaps.
        let dead = if next_item_size > 0 && post_residual < next_item_size {
            (next_item_size - post_residual) as f64 * 1.5
        } else if next_item_size == 0 && post_residual > 0 {
            2.0 * post_residual as f64 // last item: any leftover is pure waste
        } else {
            0.0
        };
        score += dead;
    }

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: strongly reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 * (post_residual as f64 - next_item_size as f64).min(20.0);
    } else if next_item_size > 0 {
        score += 6.0; // placing here strands the next item
    }

    // Last-chance pressure: if this is the only fitting bin, favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is costly unless all fits are poor.
    if bin_residual == bin_capacity {
        let base_cost = 25.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            // No open bin fits; must open.
            score = -100.0;
        } else {
            // Penalize opening when fits exist, scaled by how wasteful the best fit would be.
            score = base_cost + (mean_residual - item_size as f64).max(0.0) * 0.5;
        }
    }

    // Mild open-bin pressure: consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is near the mean (keeps bin pool homogeneous).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    let mut score = post;

    // Perfect 2-step match: post_residual exactly equals next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match reward: next item fits with small slack.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post - nxt;
        score -= 40.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to wasted potential.
        let miss = (nxt - post) / cap;
        score += 30.0 * miss.min(1.0);
    }

    // Compare against mean residual: prefer bins whose post residual is below average
    // (tightening full bins) and penalize leaving bins far above average.
    let dev = (post - mean_residual) / cap;
    score += 15.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Progress-aware: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post / cap);

    // Slight preference to fill nearly-full bins.
    score -= 5.0 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize large dead space nonlinearly
    let dead = post_residual as f64;
    score += 0.02 * dead * dead / bin_capacity as f64;

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space too small for next item
        score += 3.0;
    }

    // Last chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening new bins unless item is large and no good fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        let fit_penalty = if fitting_bins_count == 0 { 0.0 } else { 25.0 + 5.0 * pressure };
        score += fit_penalty - 10.0 * progress;
    }

    // Prefer bins tighter than the mean residual (good fills)
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Prefer bins with small residual relative to item size
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress and residual fraction
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let res_frac = post_residual as f64 / bin_capacity as f64;
    let item_frac = item_size as f64 / bin_capacity as f64;

    // Non-linear quadratic coupling: punish dead space more strongly later in the stream,
    // and super-linearly in residual size.
    let dead_space_penalty = res_frac * res_frac * (1.0 + progress * 2.0);
    score += 30.0 * dead_space_penalty;

    // Reward tight fits (small residual relative to item): smooth interaction
    let tightness = item_frac / (1.0 + res_frac);
    score -= 20.0 * tightness * (0.5 + progress);

    // Lookahead: bonus if the next item fits exactly or well into the post-residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > post_residual {
        // Penalize leaving residual too small for the next item (fragmentation)
        score += 8.0 * res_frac * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage spreading across many open bins when mean residual is high:
    // prefer bins that bring residual toward the mean (smooth coupling).
    let mean_gap = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * mean_gap * mean_gap - 3.0 * mean_gap;

    // New-bin candidate: score equals its residual (full capacity). Make it attractive
    // only when no open bin offers a decent fit (smoothly via fitting count and residual).
    if bin_residual == bin_capacity {
        let openness = (fitting_bins_count as f64).ln().max(0.0);
        score = bin_capacity as f64 * (1.0 + 0.05 * openness) - 10.0 * progress;
        // If only this bin fits, opening is unavoidable; neutralize penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly penalize the new-bin candidate so we prefer existing bins by default.
    if bin_residual == bin_capacity {
        score += cap * 1.5;
        // But allow opening a new bin late in the stream if current bins are nearly full
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual as f64 > cap * 0.9 {
            score -= cap * (0.5 + 0.5 * progress);
        }
        return score;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= cap * 2.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod 10
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are "dead" (too small for typical items 1..100 -> any residual < some threshold is waste,
    // but small residuals that exactly pair with common item classes are fine)
    // Penalize residuals that are unusable: 1..=9 minus harmonic classes {0,5}
    if pr > 0 && pr < 10 {
        if class != 0 && class != 5 {
            score += 12.0; // awkward small dead space
        } else {
            score -= 3.0; // harmonic small residual (0 or 5) is more reusable
        }
    }

    // Modulo-10 harmonic coupling between post_residual and next_item_size
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward, especially if it creates another harmonic residual
            let next_pr = pr - next_item_size;
            if next_pr % 10 == 0 || next_pr % 5 == 0 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
            // Extra reward if next item nearly fills bin
            if next_pr < 10 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; penalize based on wasted pairing potential
            let gap = (next_item_size - pr) as f64;
            score += (gap / 20.0).min(6.0);
        }
        // Integer-division threshold: can two of the next item fit post-residual? (harmonic halving)
        if pr >= 2 * next_item_size && next_item_size > 0 {
            score -= 2.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 1.0;
    }

    // Capacity-fraction thresholds on post_residual
    let frac = pr as f64 / cap;
    if frac > 0.5 {
        score -= 2.0 * frac; // roomy bins are flexible, mild reward
    } else if frac < 0.1 && pr > 0 {
        score += 4.0 * (0.1 - frac) * 10.0; // sliver penalty
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Encourage balancing residuals toward the mean (spread work evenly)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference to fill older/more crowded bins when many are open
    score += (open_bins_count as f64).ln() * 0.3;

    // Harmonic class of item itself: items near capacity fractions (25/50/75) pair well with matching residuals
    let item_class = item_size % 25;
    if item_class == 0 && bin_residual == item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but practically < 12) are pure waste.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (1.0 - post_residual as f64 / 12.0);
    }

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 80.0;
    } else {
        // Tight-fit reward: fraction of bin used by this placement.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * fill;
    }

    // Lookahead: bonus if the residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            // residual too small for next item: penalize proportionally
            score += 20.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins with residual below mean (consolidate emptier space usage).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild early-stream exploration: tolerate new bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress);

    // New-bin candidate: only attractive if no decent fit exists.
    if bin_residual == bin_capacity {
        score += 70.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits with small slack: strong reward
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 40.0 - 2.0 * slack;
        } else {
            score -= 15.0 / slack.sqrt();
        }
    }
    // Next item cannot fit: penalize proportionally to wasted pairing potential
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight fits relative to mean residual of open bins
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize large dead space that likely becomes unusable
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // tiny residual is fine (near-perfect fill)
    }
    if post_residual >= 10 && post_residual < item_size.min(80) {
        score += 6.0; // awkward mid-range dead space
    }

    // Mild early-stream preference for consolidating into few bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // New empty bin candidate: base penalty so it only wins when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && (bin_capacity - item_size) as f64 >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward low post-residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize leaving dead space that cannot host the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
        } else {
            // Reward leaving exactly enough room for the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 3.0 / (1.0 + slack * 0.1);
        }
    } else {
        // Last item: just dump into tightest fit possible.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer existing bins unless this one is nearly full.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap when few bins are open or stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (open_bins_count as f64).ln().max(0.5);
        score += 12.0 * openness * (1.0 - 0.3 * progress);
        // But if the item fits badly everywhere (large item), new bin is fine.
        if item_size as f64 > mean_residual + 5.0 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward bins with residuals below mean (consolidate waste).
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 5.0 * dev;
        // Reward filling bins closer to capacity as the stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Slight preference for fewer open bins overall (encourage closing bins).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.5 * progress * progress);

    // Penalize dead space more as stream advances (fewer chances to reuse it)
    score += 30.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
