    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Mild preference for consolidating into fewer bins
    score += 0.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Deviation from mean residual: prefer typical bins to keep balance
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // residue classes (multiples of common item sizes) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward leftover sizes that are reusable by typical small items (harmonic classes).
    // Class A: leftover divisible by 10 (very common granularity).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 30.0;
    }
    // Class B: leftover divisible by 5.
    else if post_residual % 5 == 0 {
        score -= 15.0;
    }
    // Class C: leftover leaves a "half-slot" (50) or quarter-slot (25) boundary.
    if post_residual == 50 || post_residual == 25 || post_residual == 75 {
        score -= 12.0;
    }

    // Penalize tiny dead space that nothing (min size 1..) can use well:
    // leftovers in awkward residue classes (1..=3, or odd non-multiples of 5 below 10).
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    } else if post_residual % 5 != 0 && post_residual < 10 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly or well,
    // strongly favor this bin (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            // reward proportional to how tightly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap).max(0.0);
            // harmonic class of the new leftover after chaining
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this leftover: mild penalty, worse if leftover tiny
            if post_residual < next_item_size && post_residual < 15 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate (empty bin): should only win when all open bins fit badly.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin: high, so open only when justified.
        score = cap * 0.75;
        // Cheaper to open a new bin early in the stream (more future items to use it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If next item is large and no open bin is well-suited, opening is more attractive.
        if next_item_size >= 60 {
            score -= 20.0;
        }
        // Many open bins with high mean residual -> don't open a new one.
        score += open_bins_count as f64 * 5.0 + mean_residual * 0.5;
    }

    // Prefer tighter fits among open bins: small post residual is good (already base),
    // but add mild pressure relative to mean residual.
    score += (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100 range,
    // conservatively < 10) — such space is almost certainly wasted forever.
    if post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64; // strong penalty for tiny dead gaps
    } else if post_residual == 0 {
        // Perfect fit: reward strongly (bin fully closed).
        score -= 80.0;
    } else {
        // Usable gap: mild quadratic penalty so tight fits are preferred over loose ones.
        let pr = post_residual as f64;
        score += 0.02 * pr * pr * 0.1;
    }

    // Reward leaving room for the next item if it fits exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - 0.15 * slack; // tighter match to next item is better
    } else if next_item_size > 0 {
        // Next item cannot fit here; slight penalty if we leave a gap just below it.
        let gap_to_next = (next_item_size - post_residual) as f64;
        if gap_to_next < 10.0 {
            score += 8.0; // near-miss dead space relative to lookahead
        }
    }

    // Open-bins pressure: when many bins are open, discourage spreading; prefer filling.
    let ob = open_bins_count as f64;
    if bin_residual != bin_capacity {
        score += 0.05 * ob;
        // Last-chance bin: strongly prefer using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    } else {
        // New-bin candidate: penalize when open bins exist and can still absorb items,
        // especially when mean residual across open bins is large enough to fit item.
        if open_bins_count > 0 {
            score += 15.0 + 2.0 * ob;
            if mean_residual >= item_size as f64 {
                score += 10.0;
            }
        }
        // Opening a bin early in the stream is cheaper (more items left to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to the item (best-fit coupling).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.3 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect 2-step match: post_residual exactly fits next item.
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            score -= 60.0; // exact chain: place here
        } else if post_residual as f64 > nxt {
            // next item can still follow in this bin
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item will NOT fit after this placement: dead-space risk
            score += 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }

        // Pair-fill: item + next item exactly fills the bin
        if item_size + next_item_size == bin_residual {
            score -= 45.0;
        }
    }

    // Relative-to-mean residual shaping: prefer bins with residuals near mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist, scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
        // But if item barely fits anywhere (tight fit), opening new bin is fine.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 35.0;
        }
        // If many open bins, slightly discourage adding more.
        score += 0.5 * open_bins_count as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly penalize small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: favor bins whose post_residual pairs with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // next item fills this bin exactly
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize wasted gap relative to next item
            let gap = post_residual as f64;
            score += 0.3 * gap.min(next_item_size as f64);
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is costly unless current bins are crowded
    // or this bin is a poor fit.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // Base cost of a fresh bin, discounted when open bins are nearly full on average.
        score = 100.0 - 25.0 * crowding - 15.0 * progress;
        // If the item is large relative to capacity, prefer fresh bin more when fits are bad.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 10.0;
        }
        // If only one bin fits and it's not this one, opening new bin is wasteful.
        if fitting_bins_count <= 1 {
            score += 60.0;
        }
    } else {
        // Slight preference for reusing bins with more residual (keep small-residual bins
        // for small future items): mild penalty scaled by residual.
        score += 0.05 * (bin_residual as f64 - post_residual as f64).max(0.0) * 0.0;
        // Encourage filling bins that are already mostly full.
        score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Mild global pressure: as stream progresses, discourage leaving many half-empty bins.
    if bin_residual != bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Reward tight fits: quadratic penalty shrinking residual toward 0.
    let tightness = 1.0 - pr / cap;
    score -= 30.0 * tightness * tightness;

    // Non-linear coupling of tightness with stream progress.
    score -= 20.0 * tightness * tightness * (progress * (2.0 - progress));

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Reward bins whose leftover can host the next item (lookahead pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_quality = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * pair_quality * pair_quality;
    } else if next_item_size > 0 {
        // Penalize creating dead space unusable by the next item.
        score += 8.0 * (1.0 - progress);
    }

    // Mild penalty when bin residual deviates from mean residual of open bins.
    score += 0.3 * (pr - mean_residual).abs();

    // Encourage consolidation when many bins are open.
    score += 2.0 * open_bins_count as f64 * (1.0 - tightness);

    // Slight preference for existing bins over the fresh-bin candidate.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of capacity wasted

    // Perfect fit reward: post_residual in {0, small residues} gets strong subtraction.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Dead-space penalty: leftovers that no typical item (1..100, but min item ~10)
    // can ever use are pure waste. Modulo classes on post_residual relative to 10.
    let unusable = post_residual < 10 && post_residual > 0;
    if unusable {
        score += 45.0;
    }

    // Harmonic quantization: leftover in bins of "good classes" (multiples of 10)
    // is reusable; penalize off-class residues.
    let class = post_residual % 10;
    if class != 0 {
        score += (class as f64) * 0.8;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0) * 0.4;
            if slack < 10 {
                score -= 10.0; // near-perfect chain
            }
        } else {
            // next item cannot fit here: mild penalty for blocking chain
            score += 5.0;
        }
    } else {
        // Last item: minimize waste aggressively.
        score += frac * 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; offset by how badly open bins fit.
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            let waste = (bin_residual - item_size) as f64;
            // compare: using an open bin leaves waste; new bin leaves cap-item
            (waste - (cap - item_size as f64)).max(0.0)
        };
        score = cap - item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score += 25.0; // discourage skipping the single last-chance bin
        }
        // If the best existing fit would leave nearly unusable residue, new bin wins.
        score -= 0.0;
        let _ = poor_fit;
    }

    // Stream progression: late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * (10.0 + 20.0 * progress);

    // Many open bins: favor consolidation into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean-residual coupling: if this bin is much tighter than average, reward using it.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that cannot host
    // any plausible future item (small, unusable slivers) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Coupling: dead space matters more when bins are plentiful (pressure low)
    // and less when few bins remain (we must accept imperfect fits).
    let pressure = (open_bins_count as f64).ln().max(0.0) + 1.0;
    score += (post_residual as f64) * (0.35 / pressure);

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad gap
    // or the next item fits the fresh bin perfectly.
    if bin_residual == bin_capacity {
        score += 30.0; // base cost of opening a new bin
        if post_residual < 10 || (next_item_size > 0 && post_residual == next_item_size as u32 % bin_capacity.max(1) && post_residual <= 20) {
            score -= 45.0;
        }
        score += open_bins_count as f64 * 0.5;
    }

    // Lookahead: penalize placements that leave a residual almost-but-not-quite
    // fitting the next item (wasted potential), reward exact matches.
    if next_item_size > 0 {
        let nd = post_residual as i64 - next_item_size as i64;
        if nd == 0 {
            score -= 22.0;
        } else if nd > 0 && nd < 10 {
            score += 18.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose post state stays
    // near the fleet average (keeps future items placeable).
    score += ((post_residual as f64) - mean_residual).abs() * 0.08;

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: tightly packed bins are ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose residual can host the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            // Exact chaining is best; partial slack is penalized proportionally.
            let gap = post_residual as f64 - next;
            score -= 40.0 - gap.min(40.0);
        } else {
            // Next item won't fit here; penalize leftover dead space.
            score += (next - post_residual as f64) * 0.3;
        }
    }

    // Compare against the mean residual of open bins:
    // prefer bins whose post-residual is below average (tighter packing).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or many bins are open already.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        // Penalize new bins mildly, less as stream progresses / more bins open.
        score += 55.0 - 15.0 * progress - openness.min(10.0);
        if next_item_size > 0 && (next_item_size as f64) <= bin_capacity as f64 - item_size as f64 {
            score += 10.0; // keep fresh bin for a large upcoming pairing
        }
    }

    // Slight preference to fill bins that are already fairly full.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

