        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Penalize placing into bins whose residual deviates strongly below mean (keeps diversity).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // Time horizon: early in stream, be pickier about waste; late, just fill bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate: acceptable early or when existing fit is terrible.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress; // increasingly costly to open new bins later
        if post_residual as f64 > bin_capacity as f64 * 0.5 {
            score += 10.0; // item is small relative to bin; wasteful to open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
