    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin, more so as the stream progresses.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 6.0 * progress;
    }

    // New-bin candidate handling: attractive early (spread items), costly later.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let early_bonus = (1.0 - progress).powf(2.0);
        score = cap - 15.0 * early_bonus - 2.0 * (1.0 - progress) * (open_f / (open_f + 5.0));
        // Never open a new bin when an existing bin fits perfectly.
        if fit_ratio >= 1.0 {
            score += 50.0;
        }
        // Discourage new bins if the mean residual across open bins is large.
        score += 0.05 * mean_residual * (0.5 + progress);
    }

    // Mild preference for bins with smaller-than-mean residual (consolidation).
    score += 0.02 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste granularity by capacity fractions.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class_penalty = match post_residual {
        0 => -40.0,                       // perfect fit
        r if r < eighth => -18.0,         // near-perfect
        r if r < quarter => -4.0,         // usable small slot
        r if r < bin_capacity / 2 => 6.0, // medium dead space
        _ => 14.0,                        // large leftover, bin poorly used
    };
    score += class_penalty;

    // Harmonic class of item size relative to capacity fractions.
    let item_class = (item_size * 8) / bin_capacity; // 0..=8
    score -= (item_class as f64) * 1.5;              // big items prefer tight bins

    // Lookahead: does next item fit in the post-residual (harmonic pairing)?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic pair bonus scaled by how tight the pairing is.
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * tightness;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving awkward residue.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.08 * gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when nothing fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so early and when bins are few.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    } else {
        // Favor reusing bins whose residual is close to the item (tight fit).
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * fit_ratio;
        // Prefer bins with residual near mean (balance across bins).
        score += 0.05 * ((post_residual as f64) - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: heavily reward (zero dead space is ideal).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 && post_residual < 25 {
        // Moderately small gaps are less usable for typical items (min size 1..100 unknown, but small).
        score += 8.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= 40.0 * (item_size as f64 / bin_capacity as f64);

    // Last chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean residual usefulness.
        score += 90.0 + 12.0 * open_bins_count as f64;
        // Early in stream, new bins are cheaper; later, prefer consolidation.
        score += 80.0 * progress;
        // If an existing bin leaves a gap big enough for the next item, avoid new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    } else {
        // Reward bins whose residual stays usable for the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        } else if next_item_size > 0 {
            score += 10.0;
        }
        // Slight bonus for choosing bins below mean residual (spreading waste evenly).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Consolidation pressure: favor fewer open bins by preferring emptier bins less.
        score += 3.0 * (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when post_residual exactly or nearly
    // matches the next item size (chained perfect fill).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_reward = (1.0 - gap / bin_capacity as f64).max(0.0);
        score -= 20.0 * match_reward * match_reward * match_reward;
        // Exact chain match gets a strong bonus.
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize leaving residual that is too small for the next item
        // (dead space: next item cannot use it).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious
    // (already tight); prefer spreading into bins with above-mean residual.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 4.0 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize new-bin candidate (empty bin) mildly; it should only win when no
    // open bin fits well, which the base post_residual (=capacity) already
    // discourages. Extra penalty scaled by how many bins could fit.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * fitting_bins_count as f64;
    } else if fitting_bins_count == 0 {
        // Should not happen, but guard.
        score -= 30.0;
    }

    // Slight preference early in the stream to consolidate (fewer open bins),
    // later allow more spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-perfect fits nonlinearly.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tight * tight;
    score -= 8.0 * (-4.0 * tight).exp();

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty among many options to encourage spreading via tightness signal.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decays late in the stream when
        // consolidation matters less and clean bins help future packing.
        let mut new_bin_cost = 35.0 - 20.0 * progress;
        // If nothing fits well elsewhere (large residual waste expected), opening is fine.
        if mean_residual < item_size as f64 {
            new_bin_cost -= 25.0;
        }
        // Large items pack best into fresh bins.
        if item_size > bin_capacity / 2 {
            new_bin_cost -= 10.0;
        }
        // Avoid hoarding many nearly-empty bins early.
        new_bin_cost += 3.0 * open_bins_count as f64 * (1.0 - progress);
        score += new_bin_cost.max(-10.0);
    } else {
        // Penalize leaving dead space that the next item cannot use.
        if next_item_size > 0 {
            if (post_residual as f64) < next_item_size as f64 {
                score += 6.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
            } else if post_residual == next_item_size {
                score -= 15.0; // perfect lookahead fit
            }
        }
        // Prefer bins whose residual is below mean (keep large gaps for big items).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0 * ((bin_residual as f64 - mean_residual) / 20.0).min(3.0);
        }
    }

    // Slight late-stream urgency to fill bins rather than open new ones.
    score += 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Base best-fit: minimize post residual, non-linearly amplified for small leftovers.
    let tightness = 1.0 - (pr / cap).powf(1.7);
    score -= 12.0 * tightness * (1.0 + 0.5 * progress);

    // Reward near-perfect fits strongly (smooth quadratic coupling).
    let perfect = 1.0 - (pr / cap);
    score -= 8.0 * perfect * perfect * cap / 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Penalize new empty bin unless it offers a clearly better structural fit:
    // new bin gets a smooth penalty growing with number of open bins and progress.
    if bin_residual == bin_capacity {
        score += 6.0 + 1.5 * open_bins_count as f64 + 20.0 * progress;
        // But if the item is large relative to mean residual, opening a fresh bin is fine.
        let large = item_size as f64 / cap;
        score -= 10.0 * large * large;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward; else penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0 * (nx - pr) / cap * (1.0 + progress);
        }
    }

    // Deviation from mean residual: prefer bins whose residual is below mean (well-used bins).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small, "usable" residual classes.
    // Class 0 = perfect fit; small classes = highly reusable slots.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else {
        // Integer division thresholds on post_residual (harmonic classes of C/8)
        let class = pr / 13; // ~capacity/8 granularity
        score -= match class {
            0 => 45.0,          // residual 1..12: tiny, still very reusable
            1 => 30.0,          // residual 13..25
            2 => 18.0,          // residual 26..38
            3 => 10.0,          // residual 39..51
            4 => 5.0,           // residual 52..64
            _ => 0.0,
        };
        // Modulo-arithmetic penalty: residuals that are "odd" relative to common
        // item sizes (multiples of 5 and 10) leave dead space.
        let dead = pr % 5;
        score += 2.5 * dead as f64;
        if pr % 10 != 0 {
            score += 3.0;
        }
    }

    // Coupling with next item: reward leaving a residual that the lookahead fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.15 * slack; // leaving room for next item is good
        } else {
            score += 6.0; // post residual can't host the lookahead
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalty for opening a new bin when reasonable open bins exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced when bins are crowded/fragmented
        // or when mean residual is too small to be useful for future items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 40.0 + 20.0 * progress;
        if mean_residual < 15.0 {
            nb -= 15.0; // open bins are nearly full; a fresh bin is fine
        }
        if open_bins_count > 8 {
            nb -= 8.0; // too many open bins; consolidation pressure
        }
        score += nb;
    } else {
        // Slight preference for filling bins that are already well-utilized.
        let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * used;
    }

    // Mild global pressure: with many open bins, prefer compacting into existing ones.
    score += 0.3 * open_bins_count as f64;

    // Progress-dependent tightening: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny dead gap, nearly unusable
        } else if post_residual < 30 {
            score += 25.0 * (1.0 - post_residual as f64 / 30.0);
        } else {
            score -= 10.0; // large residual keeps future flexibility
        }
    } else {
        score -= 40.0; // perfect fit: fully consumes the bin
    }

    // Last chance: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins tighter than average residual (good fit relative to fleet).
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // residual too small for next item: dead space risk
        }
    }

    // Progress: as stream advances, tighten packing (avoid leftover sprawl).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    // New-bin candidate: neutral baseline, only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover exactly (or nearly) matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Perfect 2-step fit: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize leftovers the next item cannot use at all.
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Penalize very small dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Favor filling larger residual bins when this is the last fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 35.0 };
        score += pressure + open_bins_count as f64 * 2.0;
        // If next item could pair with this item in a fresh bin, mild bonus.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Slight preference for bins tighter than the mean residual (compact packing).
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, with mild non-linear sharpening.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (pr / cap) * cap;

    // Lookahead: reward bins whose post residual fits the next item exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            let slack = (post_residual as f64 - nxt) / cap;
            score -= 18.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // dead space relative to next item
            score += 6.0 + 0.15 * (post_residual as f64);
        }
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and mean residual is high.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let waste = mean_residual - item_size as f64;
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 8.0 + 0.25 * waste.max(0.0) * (0.5 + t) + 2.0 * pressure;
        // Late in the stream, be even more reluctant to open bins.
        score += 12.0 * t * t;
    }

    // Mild bonus for tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Prefer bins below mean residual being filled (balance residuals).
    score += 0.08 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fits (large items) — reward small post_residual strongly.
    // Later: dead space matters less; relax the tightness pressure smoothly.
    let tightness = (1.0 - progress) * (1.0 - progress);
    let norm_pr = pr / cap;
    score -= tightness * (1.0 - norm_pr) * (1.0 - norm_pr) * 30.0;

    // Cubic dead-space penalty: small post_residuals are fine, large ones waste capacity.
    score += norm_pr * norm_pr * norm_pr * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // Penalty if post_residual can't fit the next item (lookahead blocking),
    // but only when the next item is small enough to matter.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (0.5 + 0.5 * (1.0 - progress));
        } else {
            // Reward bins that can still host the next item.
            score -= 5.0 * (1.0 - (pr - ni) / cap);
        }
    }

    // Mild penalty relative to mean residual: avoid leaving this bin far below average.
    score += 0.3 * (mean_residual - pr).abs();

    // Encourage consolidation when many bins are open.
    score += 0.1 * open_bins_count as f64 * norm_pr;

    // Slight preference for opening a new bin only when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - norm_pr.max(0.0)) * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fills are perfect.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Small post-residuals are good; penalize dead space super-linearly.
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64 * 2.0);

        // Modulo-class logic: residuals in classes that commonly pair with
        // typical item sizes (10..80 => complements 20..90) are more reusable.
        let pr_u = post_residual;
        let reusable = (pr_u >= 10 && pr_u <= 80);
        if !reusable {
            score += 25.0; // residual too small/large to be useful
        }
        // Class bonus: residual divisible into common chunk sizes
        if pr_u % 10 == 0 { score -= 8.0; }
        if pr_u % 20 == 0 { score -= 6.0; }
        if pr_u % 25 == 0 { score -= 4.0; }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            // Prefer residuals leaving good complement classes for next item.
            let gap = post_residual - next_item_size;
            score -= (gap <= 10) as i32 as f64 * 20.0;
            score += (gap as f64) * 0.15;
        } else {
            // Next item cannot use this residual: slight penalty, worse if residual tiny.
            if post_residual < 20 {
                score += 15.0;
            }
        }
    } else {
        // Last item: prefer exact fill, otherwise waste matters most.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: empty bin should only win when placement in open bins
    // would be poor (large post_residual or unusable residual class).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.75 + post_residual as f64;
        // Cheaper to open new bin late in stream? No — early bins amortize more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // If many bins are open and mean residual is high, prefer reusing.
        score += (open_bins_count as f64).ln().max(0.0) * 8.0;
        score += (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
        // If no other bin fits well, new bin more attractive.
        if fitting_bins_count == 0 { score -= 25.0; }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // pairing potential in fresh bin
        }
    }

    // Mild preference for tighter existing bins when many fit.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Tie-break with mean residual: prefer bins below mean residual (tighter).
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are never truly dead, but residuals that cannot
    // hold the lookahead item are wasted unless they are tiny.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Dead space relative to the next item: penalize quadratically.
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 * gap * gap / bin_capacity as f64;
        } else if post_residual >= next_item_size {
            // Reward bins whose leftover can still host the next item.
            score -= 10.0;
        }
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: its post_residual is large, but apply
        // pressure scaled by number of open bins.
        score += 6.0 * (open_bins_count as f64).sqrt();
        // Also penalize if decent fitting bins exist.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    } else {
        // Using an existing bin reduces fragmentation pressure slightly
        // when mean residual is high (bins are underfilled).
        if mean_residual > 0.5 * bin_capacity as f64 {
            score -= 3.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as the
    // stream nears completion.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    } else {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear penalty on large waste.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: strongly reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 60.0; // perfect chain: next item fills this bin completely
        } else if next_item_size <= post_residual {
            // fraction of the residual consumed by the next item
            let fill = next_f / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // next item cannot use residual at all: penalize leaving a gap
            let gap = next_f - post_residual as f64;
            score += 0.5 * gap.min(40.0);
        }
    }

    // Compare residual against mean residual across open bins: avoid spreading waste evenly.
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if no good fit exists.
    if bin_residual == bin_capacity {
        // neutral base for new bin, adjusted by how bad alternatives would be
        score += 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let fill = next_item_size as f64 / bin_capacity as f64;
            score -= 10.0 * fill;
        }
        // later in the stream, opening new bins is riskier (fragmentation)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // many open bins: discourage adding more
        score += 2.0 * open_bins_count as f64;
    }

    // Slight preference for using bins with smaller residual before placing (tighter bins first)
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64) * -0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared normalized fill.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // Penalize unusable dead space: post_residual that no typical item can use.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dead_threshold = 10.0 + 10.0 * progress;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: only one bin fits; strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer bins with residual below mean (consolidate waste).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Mild pressure to close out bins as stream progresses.
    score -= 5.0 * progress * (bin_residual as f64 / cap);

    // New-bin candidate: prefer it only when item is huge relative to capacity
    // or the fit is terrible elsewhere. Penalize opening new bins early.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.7 * cap;
        if big_item || progress < 0.2 {
            score += 12.0 * (1.0 - progress);
        } else {
            score += 3.0;
        }
        // Opening a new bin wastes the mean residual carried by open bins.
        score += 0.05 * mean_residual * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // so that large wasted space is punished super-linearly.
    let mut score = pr + 60.0 * norm_pr * norm_pr;

    // Smooth stream-progress coupling: as the stream advances, tighten the
    // packing (dead space becomes costlier). Smooth polynomial in progress.
    let tightener = 1.0 + 0.8 * progress * progress + 0.4 * progress;
    score *= tightener;

    // Perfect-fit reward: near-zero residual strongly favored, smoothly.
    score -= 25.0 * (1.0 - norm_pr).powi(8);

    // Lookahead coupling: reward if post-residual leaves room for the next
    // item (smooth interaction), penalize residual that is too small to be
    // useful (dead space) via a smooth logistic-like term.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0);
        let usable = if pr >= nxt { 1.0 } else { 0.0 };
        score -= 15.0 * usable * (fits_next / cap);
        // residual too small to ever matter: penalize smoothly
        let deadness = 1.0 / (1.0 + (pr / 10.0).exp());
        score += 20.0 * deadness;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible (smooth coupling with residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = 1.0 - (pr / cap);
        score -= 30.0 * fit_quality * fit_quality;
    }

    // Mild penalty on many open bins to discourage spreading items thinly,
    // scaled smoothly by mean residual.
    score += 0.5 * (open_bins_count as f64).ln() * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits get strong reward.
    let perfect = if post_residual == 0 { 60.0 } else if post_residual <= 5 { 25.0 } else { 0.0 };
    score -= perfect;

    // Dead-space penalty: residuals that no typical item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Harmonic tier: reward residuals that are multiples of common size classes.
    let class = post_residual % 25;
    if class == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover; penalize small leftovers mildly.
        score += (post_residual as f64) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline, slightly penalized so we prefer
    // reusing open bins unless the fit is poor; large post_residual on a
    // fresh bin keeps it competitive for big items.
    if bin_residual == bin_capacity {
        score += 5.0 - 0.2 * (post_residual as f64);
    }

    // Fraction of capacity wasted, non-linear coupling with mean residual.
    let waste_frac = (post_residual as f64) / cap_f;
    score += waste_frac * waste_frac * 20.0;
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    // Stream progression: later in the stream, be more conservative about
    // opening new bins (favor filling existing ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 0 {
        score -= progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the closer the fill to capacity, the better.
    let fill_ratio = (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Strict dead-space avoidance: small unusable gaps (< 10, or < next item) are heavily penalized.
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 + 2.0 * (min_useful - post_residual) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward gaps that exactly fit the lookahead item (pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open bins pressure: prefer existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count == 1 && bin_residual - item_size < min_useful && item_size < bin_capacity);
        if poor_fits {
            score -= 20.0;
        } else {
            score += 45.0;
        }
    }

    // Mild deviation from mean residual: prefer bins whose residual is near the mean (balanced usage).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to bin capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: next item seals this bin
        } else if next_item_size <= post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving medium dead space
            let waste = post_residual as f64;
            if waste < next_item_size as f64 && waste > 0.0 {
                score += 0.5 * waste;
            }
        }
    } else {
        // last item: prefer minimal residual
        score -= 10.0;
    }

    // Compare against mean residual: prefer bins with residual near item size
    let dev = (bin_residual as f64 - item_size as f64) - (mean_residual - item_size as f64);
    score += 0.3 * dev.abs();

    // Last-chance bin bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins can fit well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // new bin can chain next item too
        }
    }

    // Slight preference to fill bins with larger residual to consolidate
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Reward perfect fits heavily
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: penalize leaving a residual that only wastes space relative to next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bonus: residual can host the next item
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else {
            // dead space that next item cannot use
            score += 6.0 * (post_residual as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new empty bin when good alternatives exist
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) / (mean_residual.max(1.0) / 100.0 + 1.0);
        let mut new_bin_score = 55.0;
        // if this bin is the only fitting candidate, new bin is fine
        if fitting_bins_count == 0 {
            new_bin_score -= 70.0;
        }
        // late in stream, prefer consolidating into open bins
        new_bin_score += 20.0 * progress;
        new_bin_score += 0.5 * pressure.min(50.0);
        // if item is large and mean residual is low, new bin is reasonable
        if (item_size as f64) > mean_residual {
            new_bin_score -= 15.0;
        }
        score += new_bin_score;
    } else {
        // mild preference for bins with residual close to item (best-fit flavor)
        score += 0.3 * ((bin_residual - item_size) as f64);
    }

    // Global state coupling: if many open bins with large mean residual, favor filling them
    if !is_new_bin && mean_residual > 40.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 12.0 * poly * (0.5 + progress);

    // Penalize dead space more as the stream progresses
    score += 0.35 * pr_norm * pr_norm * (1.0 + 2.0 * progress);

    // Reward tight fits, amplified mid-stream
    let tightness = 1.0 - pr_norm;
    score -= 3.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (0.5 + progress);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni) / cap;
        if gap >= 0.0 {
            score -= 2.5 * gap * (1.0 - gap);
        } else {
            score += 2.0 * (-gap) * (0.5 + progress);
        }
    }

    // Mild penalty for proliferating open bins late in the stream
    score += 0.05 * (open_bins_count as f64).sqrt() * progress;

    // Discourage opening new bins when a decent fit exists
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - pr_norm) * (0.5 + progress) + 2.0 * tightness;
    }

    // Mean-residual coupling: prefer bins near the mean residual
    let dev = (pr - mean_residual) / cap;
    score += 0.8 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "usable bands".
    let post_res_u = post_residual;
    let class = post_res_u % 10;
    let band = post_res_u / 10; // integer division threshold band (0..=10)

    // Dead-space penalty grows super-linearly when post_residual falls into
    // awkward small bands (1..9) that few item sizes can ever fill.
    if post_res_u > 0 && post_res_u < 10 {
        score += 14.0 + 2.0 * (10 - post_res_u) as f64;
    } else if post_res_u == 0 {
        // Perfect closure: strong reward.
        score -= 30.0;
    } else {
        // Reward large remaining bands less as they shrink into dead zones.
        score -= 0.6 * band as f64;
        // Harmonic residue adjustment: residues near 0 (multiples of 10)
        // are more "fillable" by typical item sizes; reward them.
        match class {
            0 => score -= 6.0,
            1 | 9 => score += 5.0,
            2 | 8 => score += 2.0,
            5 => score -= 2.0,
            _ => {}
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / cap;
    score -= 8.0 * fill_frac;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or the lookahead item pairs well with a fresh bin.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Lookahead harmony: if next item is large, a fresh bin is attractive.
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if nx + item_size as f64 > cap {
                score -= 15.0; // big next item: fresh bin useful later
            }
        }
        // Late in stream, discourage proliferation of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Lookahead: reward leaving post_residual compatible with next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 7.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Mean-residual coupling: if this bin's residual deviates badly from the
    // fleet mean, mild penalty to keep residual profile homogeneous.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Many open bins: encourage consolidation (favor filling existing bins).
    if open_bins_count > 3 {
        score -= 1.5 * (open_bins_count.min(20) as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste; punish quadratically.
    if post_residual < 10 {
        score += 40.0 + 2.0 * (10 - post_residual) as f64;
    } else if post_residual < 20 {
        // "Awkward zone": hard to fill later, mild penalty.
        score += 8.0;
    } else {
        // Larger residuals remain useful; reward keeping them.
        score -= 0.05 * post_residual as f64;
    }

    // Reward exact / near-exact fits strongly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive when many bins
    // are already open (bin pressure), cheap when few are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        // Using existing bins relieves open-bin pressure.
        score -= 0.3 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into this bin's post_residual,
    // this placement is a perfect pair — big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }

    // Late in the stream, consolidate aggressively (avoid spreading items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Prefer bins whose residual is already below average (tighter bins).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Exact fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: if the next item fits into the post residual,
    // reward this placement strongly (chain potential).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.08 * chain_slack;
    } else if next_item_size > 0 {
        // Penalize leaving residual that is too small for the next item (dead space risk),
        // scaled by how close the wasted gap is to a usable item size.
        let waste = post_residual as f64;
        score += 6.0 * (waste / 100.0) * (1.0 - (waste / 100.0));
    }

    // Reward bins whose residual is already below the mean (concentrating fragments).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0 * ((bin_residual as f64) - mean_residual) / 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty for bin proliferation.
        score += 30.0;
        // Mildly cheaper to open bins early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If no open bin truly fits (this call is the only candidate), allow opening.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > item_size && next_item_size > 50 {
            score -= 12.0;
        }
    }

    // Slight penalty for accumulating many open bins (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 40.0;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.3;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    let pressure = open_bins_count as f64 / (mean_residual + 1.0);
    score -= pressure * 0.5;

    // Time horizon: early in stream, favor spreading; late, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * fit_ratio * 10.0;
    score -= progress * (post_residual as f64 / 100.0) * 5.0;

    // Penalize bins whose residual is much larger than the item (wasteful placement).
    if (bin_residual as f64) > item_size as f64 * 2.5 && bin_residual != bin_capacity {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: waste penalty grows quadratically with progress
    score += norm_pr * norm_pr * cap * (0.5 + progress);

    // Tight fits are strongly favored, more so late in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (item_size as f64) * (0.3 + 0.7 * progress);

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 8.0 * progress;
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Mild penalty for many open bins with large mean residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate: neutral baseline with slight progress-dependent bias
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-capacity classes via integer division
    let item_class = item_size / (bin_capacity / 4);
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / (bin_capacity / 4) };

    // Reward tight fits strongly (post_residual small)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 18.0;
    }

    // Penalize dead space that no typical item can fill:
    // post_residual < smallest item (1..100 unknown, but keep generic thresholds)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward if next item's class fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chain
        } else if next_item_size < post_residual && (post_residual - next_item_size) <= 10 {
            score -= 25.0; // near-perfect chain
        } else if next_item_size > post_residual {
            // next item won't fit here; residual becomes dead weight unless small
            if post_residual < 10 {
                score += 15.0;
            } else {
                score += 5.0;
            }
        }
        // Harmonic complement: next item is the modular complement of item_size
        if item_size + next_item_size == bin_capacity {
            score -= 45.0;
        }
        // Same-class stacking: two items of same quarter class pair well
        if item_class == next_class && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when open bins have poor fits (high mean residual spread) or few options.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin
        score += 55.0;
        // If many bins fit the item, discourage opening a new one
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
        }
        // If only this new bin fits (fitting_bins_count == 0 among open bins),
        // the penalty is effectively the only option anyway; soften slightly.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // If open bins are fragmented (mean residual high but no good fit),
        // opening fresh may be better later in the stream
        if mean_residual < 15.0 && fitting_bins_count >= 1 {
            // open bins are nearly full; a fresh bin is reasonable
            score -= 20.0;
        }
        // Late in stream, avoid opening bins that will be mostly wasted
        if progress > 0.9 {
            score += 15.0;
        }
    }

    // Mild preference for filling already-open bins as stream progresses
    if bin_residual < bin_capacity {
        score -= 2.0;
    }

    // Tie-break: prefer bins with residual closest to item (best-fit among equals)
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to residual.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 20.0;

    // Open-bin pressure: with many open bins, favor filling existing ones
    // over opening new bins (new-bin candidate gets penalized).
    score += (open_bins_count as f64) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: discourage opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Late-stream tightening: encourage consolidation as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to the smallest possible item (1).
        score += (post_residual as f64 / bin_capacity as f64) * 40.0;
    }

    // 2-step lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward, scaled by how much slack remains after that.
            let second_residual = post_residual - next_item_size;
            score -= 80.0 - (second_residual as f64) * 0.5;
        } else {
            // Next item cannot follow into this bin: mild penalty.
            score += 25.0;
        }
    }

    // Compare against mean residual: prefer bins that stay near the mean fill.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current fit is terrible.
    if bin_residual == bin_capacity && item_size > 0 {
        // A new bin is attractive only for small items (leaves lots of room) or
        // when the item would leave very little slack in any existing bin anyway.
        let tight_fit_elsewhere = post_residual as f64 <= 5.0;
        if !tight_fit_elsewhere {
            score += 150.0 - (item_size as f64) * 0.5;
        }
    }

    // Slight preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fit with the lookahead item (residual exactly consumed next).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }

    // Penalize residual too small to ever be useful for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Penalize dead space: residual below the minimum plausible item size.
    if post_residual < 5 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make the
    // empty-bin score high unless placing here would leave a very tight,
    // well-used residual in an existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Slightly more willing to open bins early (exploration), less later.
        let open_cost = 18.0 + 14.0 * progress;
        // If the item fills the fresh bin extremely well, reduce the penalty.
        let fill = item_size as f64 / bin_capacity as f64;
        score += open_cost - 10.0 * fill * fill;
        // Opening many bins already? discourage further proliferation.
        score += 0.4 * open_bins_count as f64;
    } else {
        // Favor bins whose residual deviates favorably from the mean
        // (tighter-than-average bins are precious, use them on good fits).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Reward packing into existing bins generally.
        score -= 2.0;
    }

    // Mild preference for keeping residuals that are "friendly" multiples,
    // encouraging combinatorial reuse of leftover space.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Strong reward for near-perfect fits (post_residual close to 0 or tiny).
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space that no future item (sizes 1..100) can plausibly use:
    // mid-range residuals are the worst; smooth quadratic bump around cap/2.
    let dead = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 8.0 * (1.0 - dead) * (1.0 - progress);

    // Lookahead coupling: reward residuals that still fit the next item, penalize just-missed fits.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let tightness = 1.0 - ((pr - ni) / cap).min(1.0);
            score -= 12.0 * tightness * tightness;
        } else {
            score += 5.0 * (1.0 - pr / ni.max(1.0));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate handling: make a fresh bin mildly attractive only when
    // open-bin residuals are large and fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        score = pr + 10.0 + 15.0 * frag * (1.0 - progress) - 5.0 * progress;
    }

    // Mild pressure against bin proliferation late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: post residuals in low harmonic classes (<= 10, or <= 20)
    if post_residual <= 10 {
        score -= 30.0; // near-perfect fill
    } else if post_residual <= 20 {
        score -= 18.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    }

    // Penalize dead space that no plausible item (1..=100) can use well:
    // leftovers just above common item sizes are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Modulo arithmetic on post_residual: residuals divisible by common
    // size classes (10, 20, 25, 50) are reusable by harmonic items.
    let reusable = (post_residual % 10 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
    if reusable && post_residual >= 10 {
        score -= 6.0;
    }

    // Integer-division threshold: leftover supports another item of the next size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0; // leaves room for the lookahead item
            if post_residual >= next_item_size * 2 {
                score -= 3.0; // room for two more
            }
        } else {
            score += 5.0; // next item won't fit here; this bin dies
        }
        // Perfect pairing: post residual exactly equals next item size
        if post_residual == next_item_size && next_item_size > 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Compare against mean residual: prefer filling below-average-residual bins.
    score += (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate handling: an empty bin is attractive only if the current
    // fit is poor. Base new-bin score = capacity - item = post_residual (large).
    if bin_residual == bin_capacity {
        // Neutral baseline plus mild penalty that shrinks as stream progresses
        // (late in stream, prefer closing out open bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = (bin_capacity - item_size) as f64 + 8.0 + 10.0 * progress;
        // If next item is large and this item leaves a harmonically useful
        // residual, opening a new bin is more acceptable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // Never open a new bin when the fit is extremely tight elsewhere:
        // this branch only wins if open-bin scores are high anyway.
    }

    // Mild penalty for very large leftover fractions (wasted space).
    if frac > 0.6 && bin_residual != bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are the worst outcome; penalize them super-linearly.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (1.0 + (10 - post_residual) as f64);
    }

    // Reward near-perfect fills (residual in [1, 10] is dead space anyway,
    // so a fill leaving <= 10 wastes nothing extra — treat as excellent).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Dead-space ratio penalty relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * waste_ratio * waste_ratio;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if next item cannot fit, mild penalty unless
    // post_residual is dead space anyway.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual >= 10 {
            score += 8.0; // leftover space usable only by smaller items
        }
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer bins that are more filled
        // (smaller residual) — implicit via post_residual already, add
        // slight preference for consolidating into fuller bins.
        score += 3.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones (the new-bin candidate has large post_residual, so this term
    // mostly affects relative ranking; boost consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open, but
        // relax if this bin would be a good fit for a large item.
        score += pressure * 4.0;
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0; // large items are hard to place later; fresh bin OK
        }
    } else {
        score -= pressure * 0.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is one of the fullest bins — favor finishing it off.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 2.0 * residual_gap;

    // Progress-based tightening: later in the stream, be greedier about
    // filling bins completely.
    score -= 10.0 * progress * (1.0 - waste_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= 2.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // 2-step lookahead: strongly reward a post_residual that exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 3.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 10.0;
        }
        // Penalize post_residual that is too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize deviation from mean residual (prefer balanced or tight bins).
    score += 0.2 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: penalize unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 4.0;
        }
    }

    // Late in stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 1.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item,
    // penalize bins that would leave a residual just barely too small for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 10.0; // near-miss dead space
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 8.0; // mild default penalty; tight fits elsewhere will beat it
        if mean_residual > 1.5 * item_size as f64 {
            score -= 20.0; // plenty of slack overall -> fresh bin fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity.min(100) - item_size.min(100) && item_size > bin_capacity / 2 {
            score -= 10.0; // big item + big next item: fresh pairing is good
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Penalize scattering across many open bins when mean residual is large.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with residuals near the item (harmonic fit).
    if bin_residual > 0 {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.8 && fit_ratio <= 1.0 {
            score -= 8.0 * (fit_ratio - 0.8);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste left behind; non-linearly scaled so small residuals are cheap,
    // large residuals increasingly costly (quartic coupling).
    let norm_waste = pr / cap;
    let mut score = pr * (1.0 + norm_waste * norm_waste * (1.0 + progress));

    // Reward tight fits: strongly subtract when the item nearly fills the bin.
    let tightness = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= tightness * tightness * cap * 0.9;

    // Lookahead: if the next item exactly fits the post_residual, this is ideal.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (cap - gap.min(cap)) * 0.35;
        // Extra reward for exact continuation.
        if gap < 0.5 {
            score -= cap * 0.5;
        }
    } else {
        // Last item: prefer filling as much as possible.
        score -= (cap - pr) * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * (0.6 + 0.4 * progress);
    }

    // Prefer bins whose residual is close to the mean (keeps bin states balanced),
    // with smooth quadratic coupling.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.25 * (0.5 + progress);

    // New-bin candidate: score = full capacity waste; make it attractive only when
    // no open bin offers a decent fit (i.e., when post_residual here is large anyway).
    if bin_residual == bin_capacity {
        score = cap * (1.0 + norm_waste) - cap * 0.15 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.2 * cap;
        }
    }

    // Mild penalty for proliferating bins late in the stream.
    score += (open_bins_count as f64).ln() * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Perfect-fit reward
    if pr == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small nonzero residuals are wasteful.
    if pr > 0 && pr < 10 {
        score += 60.0 * (10 - pr) as f64;
    }

    // Harmonic classes: residual divisible by common item sizes is reusable.
    let mut harmony = 0.0f64;
    for &m in &[10u32, 20, 25, 50] {
        if pr % m == 0 && pr > 0 {
            harmony += 25.0;
        }
    }
    // Quadratic residue class: pr in [50..100) is half-bin usable
    if pr >= 50 {
        harmony += 30.0;
    } else if pr >= 25 {
        harmony += 12.0;
    }
    score -= harmony;

    // Lookahead coupling: does next item fit exactly / at all?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size <= pr {
            // good but not perfect: mild reward scaled by tightness
            score -= 40.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item cannot use this residual anyway
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Prefer fuller bins when many bins are open (bin consolidation pressure).
    score -= (1.0 - prf / cap) * 20.0;
    score += (open_bins_count as f64).ln() * 5.0;

    // Mean-residual alignment: bins near the mean are "typical", slight tie-break.
    score += 0.05 * (prf - mean_residual).abs();

    // Stream progression: late in stream, tighten packing (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress;

    // New-bin candidate: only attractive if nothing fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted when current fits are bad
        score = 150.0 + 0.1 * mean_residual - 80.0 * progress;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest item are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Exact fit is perfect: reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Open-bin pressure: prefer consolidating into few bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless this bin's fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Slight preference for bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild stream-progression tilt: later in the stream, avoid creating dead space even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post residual exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            // Perfect lookahead match: next item exactly fills remaining space.
            let match_gap = post - nxt;
            score -= 60.0 * (1.0 - match_gap / 80.0).max(0.0);
            // Extra bonus if next item leaves near-zero residual after it too.
            score -= 15.0 * (1.0 - ((post - nxt) % 100.0) / 100.0) * (nxt / 100.0);
        } else {
            // Next item won't fit: penalize proportionally to how badly it misses.
            score += 25.0 * (nxt - post) / 100.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 40.0;
    }

    // Relative-to-mean-residual coupling: bins tighter than the mean are precious.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 8.0 * (mean_residual - post_f) / bin_capacity as f64;
    } else {
        score += 5.0 * (post_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist, unless item is large.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // New bin attractive only for large items or when few fitting bins.
        score += 35.0 * (1.0 - tightness);
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 12.0 * (1.0 - progress);
    }

    // Dead-space penalty: unusable slivers (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild preference to fill bins more completely as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - post_f / bin_capacity as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: how well the item fills the bin's remaining space
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits (subtract proportionally)
    score -= 25.0 * fill_ratio * fill_ratio;

    // Reward exact/near-exact fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize creating small, hard-to-use dead space
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            // leftover is usable by next item -> good
            let snug = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 15.0 * snug;
        } else {
            // leftover too small for next item -> dead space risk
            score += 8.0;
        }
    } else {
        // last item: just minimize leftover
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many open bins: prefer consolidating into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Deviation from mean residual: prefer bins that reduce dispersion
    score += ((post_residual as f64 - mean_residual).abs() - (bin_residual as f64 - mean_residual).abs()) * 0.5;

    // NEW-BIN CANDIDATE handling: bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // A new bin is attractive only if the item is large relative to capacity
        // (opening a bin for a tiny item wastes capacity)
        let item_frac = item_size as f64 / bin_capacity as f64;
        score -= 45.0 * item_frac * item_frac;
        // Early in the stream, opening bins is cheaper (more future items to fill them)
        score -= 25.0 * (1.0 - progress);
        // If the only alternative is a poor fit (large dead space everywhere), allow new bin
        if fitting_bins_count == 1 {
            let best_alt_waste = bin_residual - item_size; // waste in the sole fitting bin
            if best_alt_waste > 20 {
                score -= 35.0;
            }
        }
        // If many bins are open and residuals are fragmented, opening fresh can help
        if open_bins_count > 4 && mean_residual < 30.0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Tight fits rewarded more strongly as stream progresses (smooth coupling)
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (30.0 + 40.0 * progress);

    // Penalize large dead space quadratically, scaled by progress
    score += norm_pr * norm_pr * (20.0 + 60.0 * progress);

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        score -= (1.0 - gap / cap).max(0.0) * 15.0 * (1.0 - progress);
        // penalize post-residual just barely below next item size (unusable)
        if pr < ns {
            score += (ns - pr) * (0.3 + 0.5 * progress);
        }
    }

    // Mild preference for fuller bins when many bins are open
    score -= tightness * (open_bins_count as f64).ln().max(0.0) * 5.0;

    // Deviation from mean residual: prefer bins below mean residual (denser bins)
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse if it falls in
    // "unusable" classes (smaller than the smallest plausible item).
    let min_item = 1u32.max(item_size.min(80)).min(20);
    if post_residual > 0 && post_residual < min_item {
        score += 500.0; // unusable sliver: heavy penalty
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 are more reusable
    // (items drawn on a 1..100 grid often cluster on round sizes).
    let r10 = post_residual % 10;
    score -= (10 - r10) as f64 * 2.0; // reward residuals near a multiple of 10

    // Integer-division thresholds on post_residual: classify leftover size.
    let class = post_residual / 25; // 0..4 harmonic quarters
    score += class as f64 * 1.5;    // prefer bins leaving small leftovers

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chained tight packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 30.0;
            // harmonic match: post_residual and next item share a divisor class
            let combined = post_residual - next_item_size;
            if combined % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; slight penalty for stranded residual
            score += 10.0 + (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
        if post_residual <= 15 {
            score -= 100.0; // tight last-chance fit is great
        }
    }

    // New-bin candidate handling: penalize opening a new bin when the stream is
    // young or few bins are open; relax later when open bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 120.0
            - 60.0 * progress
            + 40.0 * fragmentation
            + (open_bins_count as f64).sqrt() * 5.0;
        if fitting_bins_count == 0 {
            score -= 300.0; // no open bin fits: opening is mandatory
        }
    }

    // Mild preference for filling fuller bins (relative fill ratio coupling).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Tie-breaker noise-free harmonic dither on bin index proxy (open_bins_count).
    score += (open_bins_count % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later (unusable gaps) get an extra penalty. Gap usefulness threshold
    // derived from the smallest possible item (1) but scaled by stream progress.
    let dead_threshold = 1u32 + ((bin_capacity as f64 * 0.10) as u32); // ~11 units
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bins pressure: prefer spreading load when many bins are open,
    // but penalize opening new bins when few are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += pressure * 3.0;

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // next item cannot use this gap: penalize proportionally
            score += 12.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (denser bins),
    // keeping emptier bins available for large future items.
    score += (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or current fits are poor.
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * urgency + 20.0 * large_item * progress;
        // Slight bias against new bins early on to encourage consolidation.
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward when the next item exactly fits post_residual ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain (post_residual == next_item_size) is heavily rewarded
            if slack == 0.0 {
                score -= 25.0 + 10.0 * (item_size as f64 / bin_capacity as f64);
            } else {
                // Reward decays with slack between next item and post residual
                score -= 15.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
            }
        } else {
            // Next item cannot fit in the leftover: penalize wasted residual
            score += 0.35 * post_residual as f64 * (0.5 + progress);
        }
    } else {
        // Last item: prefer tightest fill possible
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // --- Relative to mean residual: prefer bins tighter than average ---
    let rel = if mean_residual > 0.0 { post_residual as f64 / mean_residual } else { 1.0 };
    score += 4.0 * (rel - 1.0).clamp(-1.5, 1.5);

    // --- Last-chance bin: strong bonus to use the only fitting bin ---
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // --- Prefer fuller bins overall (waste minimization) ---
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * fill * fill;

    // --- New-bin candidate: penalize opening a new bin, more so early and when good fits exist ---
    if bin_residual == bin_capacity && item_size < bin_capacity {
        score += 18.0 + 20.0 * (1.0 - progress);
        // If next item is small enough to pair with this item later, opening new bin is less bad
        if next_item_size > 0 && (next_item_size + item_size as u32) <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 45.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0 * (30.0 - post_residual as f64) / 20.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty scaled by how close we were
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill_frac * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: later in stream, be more aggressive about closing bins tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill_frac;

    // Global residual balance: penalize bins far above mean residual early (keeps spread even)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * (1.0 - progress);

    // New-bin candidate handling: make empty bin moderately attractive only when
    // no open bin fits well or item is large
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual as f64 / bin_capacity as f64) > 0.5 && item_size > 60;
        if poor_fit_elsewhere {
            score -= 15.0;
        } else {
            score += 20.0; // discourage opening new bin when decent fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
