pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are "clean"
    // fractions of capacity (divisible by common item-size classes).
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit, strongly favored
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr < 10 {
        12.0 // dead space below smallest item class
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division thresholds: how many "small" items (<=10) could still fit
    let slots = pr / 10;
    score -= slots as f64 * 1.5;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // harmonic class match between next item and post residual
            if pr % next_item_size == 0 {
                score -= 10.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item cannot fit here; residual becomes potential dead space
            score += (next_item_size as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only prefer a fresh bin when current bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if mean_residual < 20.0 && next_item_size > 0 {
            score -= 5.0; // open fresh bin when open bins are nearly full
        } else {
            score += 10.0 + fragmentation * 0.2;
        }
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // Penalize bins far from mean residual (outliers waste capacity)
    score += ((bin_residual as f64 - mean_residual) * 0.05).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavy penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
