pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = pr * (0.30 * p2 + 0.55 * p3) - pr * (0.15 * progress);
    score += coupling;

    // Reward tight fits (small post_residual relative to capacity), smoothly.
    let tightness = 1.0 - pr / cap;
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space that cannot fit a plausible next item (smooth).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = ((ns - pr) / cap).max(0.0);
        score += 12.0 * gap * gap;
        // Reward leaving exactly room for the lookahead item.
        let match_r = 1.0 - ((pr - ns) / cap).abs().min(1.0);
        score -= 10.0 * match_r * match_r;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // New empty bin candidate: mild penalty so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress);
    }

    // Spread-awareness: prefer bins with residuals near the mean (smooth).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for many open bins, encouraging consolidation.
    score += (open_bins_count as f64).sqrt() * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" classes
    // (multiples of 10 / 20) are more attractive because future items often fit them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class10 = (post_residual % 10) as f64;
    let class20 = (post_residual % 20) as f64;

