    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 {
        score -= 3.0;
    }

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small dead space (< smallest plausible item) is harmless; large awkward
    // dead space is penalized via harmonic distance to half/full capacity.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }
    let half = cap / 2.0;
    let dead = (pr - half).abs();
    score += dead * 0.05;

    // Lookahead coupling: if the next item exactly matches the post residual,
    // this bin is a golden pair placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot use this leftover: penalize wasted potential
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Harmonic lookahead: next item divisible into leftover cleanly
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or the fit here is poor (item would leave a large awkward residual).
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 18.0 - crowding * 20.0;
        if item_size >= 50 {
            score -= 5.0; // big items start fresh bins naturally
        }
        if mean_residual < item_size as f64 * 1.2 {
            score -= 10.0; // nothing else fits well anywhere
        }
    }

    // Progress-based mild pressure: as stream advances, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (mean_residual - pr).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
