    // New-bin candidate: penalize opening a new bin, scaled by how many bins
    // could fit and how much residual already exists across open bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64 + 0.05 * mean_residual;
        if nxt > 0.0 && nxt <= cap - item {
            score -= 1.0;
        }
    }

    // Mild preference for bins with smaller residuals when several fit.
    score += 0.02 * (res / cap) * (fitting_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that
    // cannot hold even the smallest item (1) is pure waste.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else {
        // Fraction of capacity wasted
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * waste_frac * waste_frac;

        // Harmonic class of post_residual: residual mod small divisors
        // captures classic "residual classes" structure (e.g. mod 10, mod 5).
        let pr = post_residual;
        if pr % 10 == 0 {
            score -= 6.0; // clean class, likely reusable by common sizes
        }
        if pr % 5 == 0 {
            score -= 3.0;
        }
        // Very small residual (< minimal item) = dead space
        if pr < 10 {
            score += 8.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Mild pressure against opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    // Late-stream consolidation: tighten tolerance as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are pure waste -> heavy penalty scaled by how close to zero they are.
    if post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits: post_residual near zero is ideal.
    score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4);

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * 1.5;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post_residual exactly-ish,
    // reward leaving that gap; if next item cannot use the gap, penalize it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap_efficiency = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * gap_efficiency;
        } else {
            score += 5.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (smaller residual than average => better consolidation).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight progression term: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward placements where the next item also fits ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact chain fit is ideal; scale bonus with how large the chained item is.
            score -= 25.0 + 0.35 * next_item_size as f64;
        } else {
            // Near-miss penalty: how much of the next item doesn't fit (capped).
            let miss = (next_item_size as f64 - post_residual as f64).min(20.0);
            score += 0.6 * miss;
        }
    }

    // --- Dead-space avoidance: tiny unusable leftovers are the worst outcome ---
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // --- Best-fit flavor: prefer bins whose current residual is below average ---
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // --- Last-chance bin: if this is the only open bin that fits, strongly
    //     prefer it over opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin can fit: opening a new bin is mandatory.
            score -= 1000.0;
        } else {
            // Some open bin fits: penalize opening a new bin, more so early in
            // the stream when there is still time to fill existing bins.
            score += 55.0 + 6.0 * open_bins_count as f64 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward tight fits: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = if bin_residual > 0 { item / bin_residual as f64 } else { 0.0 };
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize leaving dead space that is too small for typical future items.
    if post > 0.0 && post < 10.0 {
        score += 25.0; // tiny unusable sliver
    } else if post >= 10.0 && post < 20.0 {
        score -= 5.0; // still useful for small items
    }

    // Lookahead: reward bins whose post-residual can host the next item (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 30.0;
            // Extra reward for near-exact chaining (post_residual ~ next item).
            let chain_fit = 1.0 - (post - nxt).abs() / cap;
            score -= 20.0 * chain_fit;
        } else {
            // Penalize placements that strand the next item's size class.
            score += 8.0 * (nxt / cap);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: make empty bin attractive only when the item is large
    // relative to capacity or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let size_ratio = item / cap;
        // Large items deserve a fresh bin; small items should go into open bins.
        score = 70.0 - 60.0 * size_ratio;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin anyway
        }
        if open_bins_count > 0 && size_ratio < 0.35 {
            score += 30.0; // discourage opening bins for small items
        }
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // -> favor consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    score -= 0.15 * mean_residual * (1.0 + progress);

    // Mild preference to drain bins with small residuals (reduce bin count over time).
    if bin_residual != bin_capacity {
        score -= 0.2 * (cap - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Normalized post-residual (fraction of capacity wasted)
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of dead space with stream progress:
    // later in the stream, waste is penalized more aggressively (quartic ramp).
    let progress_ramp = 0.5 + 2.0 * progress * progress * (1.0 + progress);
    score += 4.0 * pr_norm * pr_norm * progress_ramp * cap / 10.0;

    // Reward tight fits: cubic bonus as post_residual approaches zero.
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack) * (0.3 + 0.7 * progress);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            let over = (nxt - pr) / cap;
            score += 3.0 * over * over;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - pr_norm);
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins whose residual is closest to the item (best fit).
        let fit_gap = (bin_residual - item_size) as f64 / cap;
        score += 2.0 * fit_gap * fit_gap * (fitting_bins_count as f64).ln();
    }

    // Discard fragmentation: penalize residuals too small for the smallest plausible item,
    // scaled smoothly by how far below the threshold the residual lies.
    let min_future = 1.0f64.min(pr);
    let dead = (10.0f64.min(pr) - min_future) / cap;
    score += 8.0 * dead * dead * (1.0 + progress);

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64 * pr_norm;

    // Slight preference for balancing against the mean residual (spread load evenly).
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate (empty bin) gets a small inherent handicap so we only open
    // a new bin when it truly wins on residual quality; scale down late in stream.
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement.
    let h = post_residual / 10; // integer division: harmonic class 0..10

    // Reward placements that land the residual in a "useful" harmonic class.
    // Class 0 (perfect fill) is best; classes 1..3 (small leftovers) are bad.
    match h {
        0 => score -= 60.0,
        1 => score += 25.0,
        2 => score += 12.0,
        3 => score += 5.0,
        4..=6 => score -= 3.0,
        _ => {}
    }

    // Non-linear coupling: small residuals that cannot fit the next item are dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0; // bin remains usable for the lookahead item
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening a new bin when several open bins could still fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the item is large and few bins fit it, opening a fresh bin is fine.
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Progress-aware tiebreak: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Slight preference for bins tighter than the mean residual (better fits).
    score += 0.05 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // minimum item are pure waste — punish them hard, scaled by how "dead" they are.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        // Perfect closure is the ideal outcome: reward strongly.
        score -= 40.0;
    }

    // Reward tight fits relative to the item size (small slack ratio).
    let fit_ratio = post_residual as f64 / (bin_residual.max(1) as f64);
    score += fit_ratio * 15.0;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_slack = post_residual - next_item_size;
        if next_slack == 0 {
            score -= 35.0; // chain closure
        } else if next_slack < 10 {
            score += 8.0; // would create dead space next step
        } else {
            score -= 10.0; // keeps bin usable
        }
    }
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0; // residual unusable by the known next item
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 18.0 + 22.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 4.0;
    if bin_residual == bin_capacity {
        score += new_bin_bonus;
        // Opening a new bin is only attractive if the item is large relative to capacity
        // (a big item leaves a big, reusable residual).
        let big_item = item_size as f64 / bin_capacity as f64;
        score -= big_item * 20.0;
        // If the next item is small, a fresh bin's large residual is valuable.
        if next_item_size > 0 && (next_item_size as f64) < 0.35 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Consolidation pressure: prefer bins whose residual is below the mean
    // (fill the emptier-feeling bins first to keep few bins open).
    score += ((post_residual as f64) - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward if next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover after hypothetical placement
            let chain_left = post_residual - next_item_size;
            score += chain_left as f64 * 0.8;
        } else {
            // next item won't fit here: penalize proportionally to waste
            let overhang = (next_item_size - post_residual) as f64;
            score += overhang * 0.5;
        }
    }

    // Compare post_residual relative to mean residual of open bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly reward using it (avoid opening a new bin)
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 + 0.2 * bin_residual as f64;
    }

    // Penalize opening a new bin when reasonable fits exist, unless current fit is terrible
    if bin_residual == bin_capacity {
        // new-bin candidate: neutral-ish baseline; penalize if good fits exist
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual * 0.5 {
            score += 30.0;
        }
        // early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Slight penalty when many bins open: encourage consolidation
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot hold the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual still useful for the next item: reward.
            score -= 3.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
        // Bonus if post_residual exactly accommodates the next item.
        if post_residual == next_item_size {
            score -= 6.0;
        }
    } else {
        // Last item: maximize fill, strongly reward low post_residual.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many
    // bins fit the item or many bins are already open (fragmentation risk).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 20.0;
        if fitting_bins_count > 1 {
            new_bin_penalty += 5.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // Early in the stream, opening bins is cheaper (more future items
        // to potentially pair with); later, prefer consolidating.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty *= 0.5 + progress;
        score += new_bin_penalty;
    }

    // Prefer bins whose residual is below the mean (compact bins),
    // penalize bins that are unusually empty relative to the fleet.
    if mean_residual > 0.0 {
        let deviation = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 2.5 * deviation;
    }

    // Slight preference for filling bins with larger residual when many
    // open bins exist (reduce bin count pressure).
    score -= (open_bins_count as f64).ln().max(0.0) * (item_size as f64 / bin_capacity as f64);

    // Reward exact fits overwhelmingly.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic waste penalty on post residual
    let mut score = norm_post * norm_post * cap;

    // Non-linear coupling with stream progress: late in stream, waste hurts more
    let late = progress * progress;
    score += late * post * (1.0 + 0.5 * progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = item_size as f64 / (item_size as f64 + post);
    score -= 30.0 * tightness * tightness;

    // Penalize bins with residual far below mean (fragmented bins), smooth cubic coupling
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * dev.abs().sqrt().max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let fit_quality = next_item_size as f64 / post.max(1.0);
        score -= 15.0 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 {
        // next item cannot fit here: mild penalty scaled by how much it misses
        let miss = (next_item_size as f64 - post) / cap;
        score += 8.0 * miss.max(0.0);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when item is large or fit elsewhere is terrible
        let large_item = item_size as f64 / cap;
        score += 20.0 - 25.0 * large_item * large_item - 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let small_gap = pr < eighth;
    let medium_gap = pr >= eighth && pr < quarter;
    let large_gap = pr >= quarter;

    // Reward tight fits (small dead space), penalize medium unusable gaps
    if small_gap {
        score -= 6.0;
    } else if medium_gap {
        score += 4.0;
    } else if large_gap {
        score -= 2.0 * (pr as f64 / cap);
    }

    // Perfect fill bonus
    if pr == 0 {
        score -= 12.0;
    }

    // Harmonic coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0; // perfect chaining
        } else if next_item_size < pr {
            let npr = pr - next_item_size;
            if npr < eighth {
                score -= 5.0;
            } else if npr >= quarter {
                score -= 1.0;
            } else {
                score += 3.0;
            }
        } else {
            // next item cannot use this residual: dead space likely
            score += 2.0 + (pr as f64 / cap) * 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are poor
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let waste = mean_r / cap;
        score = cap * 0.5 + 10.0 * (1.0 - waste);
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0; // big next item may want fresh bin
        }
    }

    // Stream progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 1.5;

    // Mild pressure to prefer bins with more residual (keep small-gap bins for small items)
    score += (bin_residual as f64 / cap) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than linearly.
    // A gap that cannot hold even the smallest future item (<=100) is "dead";
    // gaps in the mid-range (1..=30) are the worst offenders.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual <= 30 {
            // unusable dead space: heavy quadratic penalty
            score += (31.0 - pr) * (31.0 - pr) * 1.5;
        } else if post_residual <= 60 {
            // partially usable gap: mild penalty scaled by fill quality
            score += (60.0 - pr) * 0.3;
        } else {
            // large residual: slight bonus for keeping bins roomy
            score -= 5.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Prefer bins that are already well-filled (low bin_residual relative to capacity).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 4.0;

    // Last-chance bin: strongly reward using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item would leave a terrible gap everywhere.
    if bin_residual == bin_capacity {
        let gap_bad = post_residual > 0 && post_residual <= 30;
        if fitting_bins_count == 0 || (gap_bad && next_item_size > post_residual) {
            score -= 35.0; // opening a new bin is justified
        } else {
            score += 30.0 + pressure * 6.0; // discourage proliferation
        }
    }

    // Lookahead coupling: reward leaving a gap that fits the next item,
    // penalize gaps that almost-but-don't fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size.saturating_sub(10) {
            score += 10.0; // near-miss gap is wasted potential
        }
    }

    // Slight preference for bins with residual close to mean (avoid fragmenting outliers)
    score -= (mean_residual - bin_residual as f64).abs() * -0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect or near-perfect fit (waste minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 0.4;
        // bonus if next item then leaves near-zero residual too
        if post_residual == next_item_size {
            score -= 150.0;
        }
    } else if next_item_size > 0 {
        // penalize dead space the next item cannot use
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize opening a new bin when reasonable open bins exist
    if bin_residual == bin_capacity {
        score += 40.0;
        // but allow new bin if current fit is very poor
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 90.0;
        }
    }

    // Slight preference early in stream to keep bins open for future items
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Penalize leaving dead space that no typical item (1..=100) can use well:
    // residuals below the smallest item are pure waste.
    if post_residual < 10 {
        score += 25.0; // tiny slivers are dead space
    } else if post_residual <= 40 {
        score -= 12.0; // sweet spot: many items can fill this
    } else {
        score += (post_residual as f64 - 40.0) * 0.25;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing ones,
    // penalize opening new bins.
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive when few bins are open
        // or mean residual is very fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        let new_bin_bonus = 8.0 * (1.0 - fragmentation)
            + 6.0 * (1.0 - (open_bins_count as f64 / 20.0).min(1.0))
            - 10.0 * progress;
        score += 15.0 - new_bin_bonus; // base penalty, reduced when opening is good
    } else {
        // existing bin: reward filling bins when many are open
        score -= 2.0 * (open_bins_count as f64 / 10.0).min(2.0);
    }

    // Prefer bins whose residual is close to the mean (balance), slight effect.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    // Prefer fuller bins overall (smaller residual) with a mild linear term.
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;

    // Base: prefer small post_residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * fit_ratio * fit_ratio);

    // Smooth progress coupling: tighten residual tolerance as stream progresses
    let tighten = 1.0 + 1.5 * progress * progress;
    score *= tighten;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 12.0 * (next_item_size as f64 - pr).max(0.0) / cap * (1.0 + progress);
    }

    // Reward when this bin is the only fitting option (avoid new bin)
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Encourage consolidating residual mass when many bins are open
    let dev = (mean_residual - pr) / cap;
    score += 3.0 * dev * dev * (open_bins_count as f64);

    // Slight preference to fill nearly-full bins harder over time
    score -= 6.0 * progress * (item_size as f64 / cap) * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, but with a non-linear decay
    // so small residuals are disproportionately favored.
    score = score.powf(1.35);

    // Harmonic class of the residual: residuals divisible by common item
    // size classes (10/20/25/50) are more reusable.
    let harmonic_bonus = if post_residual == 0 {
        -30.0 // perfect fill
    } else if post_residual % 10 == 0 {
        -8.0
    } else if post_residual % 25 == 0 {
        -5.0
    } else if post_residual % 20 == 0 {
        -4.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: residual too small for the minimum plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        // exact pairing is ideal
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this residual: mild penalty proportional to waste
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: an empty bin is a fallback; penalize it
    // mildly so it only wins when fits are poor, but less so when many
    // bins are open and consolidation is desirable.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
        // if nothing fits well elsewhere this penalty is small enough to lose
    }

    // Prefer bins with residual below the mean (filling emptier bins first
    // keeps a spread of usable residuals).
    score -= 2.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Stream progression: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Integer-division threshold: post_residual in [10,30] is a "sweet spot"
    // class where a medium item can still land.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if it is too small to hold even the smallest plausible item.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Non-linear penalty for leaving awkward mid-range gaps that few items fill.
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = (item_size as f64) / (bin_residual as f64);
        score -= tightness * 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.0 + progress) * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current fit
    // is terrible (large post_residual) and few bins are open.
    if bin_residual == bin_capacity {
        // New empty bin baseline: residual after placement is capacity - item.
        // Penalize opening a new bin, scaled by how many bins already exist.
        score += 25.0 + (open_bins_count as f64) * 3.0;
        // But if the new bin would be well-filled by the next item too, soften.
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 15.0;
        }
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Leftover gap that next item cannot use is partially wasted.
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Mean-residual coupling: prefer bins with residual below the mean
    // (close small bins first, keep large-capacity bins flexible).
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.3;
    } else {
        score += (bin_res_f - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward; near match: proportional reward.
        if diff == 0.0 {
            score -= 60.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 25.0 / (1.0 + diff / 10.0);
        } else {
            // Next item cannot fit in the leftover: penalize dead space.
            score += diff * 0.35;
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // usable space is good (keeps bins flexible), leaving fragments is bad.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Penalize very small unusable leftovers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it neutral-ish; only attractive when open bins
    // would create large dead space (handled above via penalties).
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
    }

    // Slight late-stream tightening: waste less as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact or near-exact placements are highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // Penalize leaving a residual that is too small to be useful later
    // (dead space below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin; if next item cannot fit, penalize slightly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely
    // needed (few fitting bins, or a very large item).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 40.0 };
        score += 35.0 + pressure;
        // Late in the stream, opening new bins wastes capacity; penalize more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // bins with below-average residual (consolidate).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        if open_bins_count > 8 {
            score -= 5.0;
        }
    }

    // Mild time-horizon shaping: early stream, be more selective about
    // fragmentation; late stream, prioritize just fitting items.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    let mut score = pr;

    // Smooth non-linear coupling: reward tight fits more strongly as stream progresses
    let tightness = 1.0 - (pr / cap);
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Penalize bins whose residual deviates from mean residual (dead-space smoothing)
    let dev = (pr - mean_residual) / cap;
    score += 2.5 * dev * dev * cap * 0.01;

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Penalize opening a new bin when an existing bin fits reasonably well
    if bin_residual == bin_capacity {
        let new_bin_residual = pr;
        let waste = (new_bin_residual - mean_residual).max(0.0);
        score += 4.0 + 0.05 * waste + 3.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 6.0;
        }
    }

    // Lookahead: penalize leaving residual just below next item size (unusable gap)
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 {
            let sev = (-gap / cap).min(1.0);
            score += 5.0 * sev * (1.0 - sev);
        } else {
            score -= 1.5 * (gap / cap);
        }
    }

    // Mild penalty for spreading across too many open bins late in the stream
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: reward residuals in classes
    // that are "fillable" by typical item sizes (multiples of 5/10).
    let pr = post_residual;
    let class = (pr % 10) as f64;
    // residual class 0 is perfect, class 5 is good, others penalized quadratically
    let class_penalty = match pr % 10 {
        0 => -6.0,
        5 => -3.0,
        c if c <= 2 || c >= 8 => 4.0,
        _ => 1.5,
    };
    score += class_penalty * (1.0 + pr as f64 / bin_capacity as f64);

    // Integer-division thresholds: how many size-10 units remain?
    let units = pr / 10;
    if units == 0 && pr > 0 {
        // dead space: unusable sliver
        score += 12.0;
    } else if units >= 1 && units <= 2 {
        score -= 1.0;
    } else if units >= 5 {
        // large residual left: maybe a new bin was a better choice
        score += 0.05 * units as f64;
    }

    // Lookahead coupling: can next_item_size exactly fill or fit the residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0; // perfect future fill
        } else if next_item_size <= pr {
            score -= 2.0 + (pr - next_item_size) as f64 / 20.0;
        } else {
            score += 1.0; // next item won't fit here anyway
        }
        // harmonic class match between next item and residual
        if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only prefer fresh bin when all open fits are bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 0.55;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 8.0; // big next item: fresh bin useful
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else if post_residual == 0 {
        score -= 15.0; // perfect fill always great
    }

    // Slight tie-break toward fuller bins overall
    score -= (bin_residual - post_residual) as f64 / bin_capacity as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (smaller than the minimum plausible item) are pure waste.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect / near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward using bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= (bin_capacity as f64 - tightness) * 0.3;

    // Last chance: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64).abs();
        score -= (bin_capacity as f64 - slack) * 0.4;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // post_residual too small for next item: penalize proportionally to how close it was.
        score += (next_item_size as f64 - post_residual as f64) * 1.5;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few bins, slightly tolerate spreading.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residual below mean (fill emptier-of-residual bins first,
    // keeping large residuals available for large future items).
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.4;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_alternative = fitting_bins_count > 1
            || (fitting_bins_count == 1 && bin_residual == bin_capacity);
        if fitting_bins_count >= 1 && !good_alternative {
            score += 55.0; // there exists another fitting bin -> discourage new bin
        } else if fitting_bins_count == 1 {
            // only the new bin truly fits well relative to dead-space concerns
            score -= 10.0;
        }
        // mild progression-based penalty: late in stream, opening bins is costly
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit lookahead: item leaves exactly the space the next item needs.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 / (1.0 + slack * 0.1);
        } else {
            // Next item cannot fit here; penalize leftover dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }
    } else {
        // Last item: prefer tightest packing overall.
        score += (post_residual as f64) * 0.5;
    }

    // Reward small post_residual (tight fit), strongly.
    score += (post_residual as f64).powi(2) * 0.01;

    // Compare against mean residual across open bins: prefer bins that will
    // end up closer to (below) the mean residual — i.e. fuller bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless post_residual is huge).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 + (item_size as f64) * 0.2;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: open a new bin
        } else {
            // Deter opening new bins when existing ones can take the item,
            // unless the best available post_residual would be wasteful.
            score += 200.0
                - (post_residual as f64 * 0.5)
                - (open_bins_count as f64).min(10.0) * 5.0;
        }
    }

    // Early in the stream, be slightly more willing to open fresh bins to
    // build a diverse residual portfolio; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 40.0;
    } else {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Strong reward when the item almost exactly fills the bin.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Penalize leaving dead space that typical items can't use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // sliver too small for most items (sizes >= 1... small items rare)
    }

    // Lookahead: reward residual that can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.5;
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins fit poorly or the item is large and nothing pairs well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let good_fit_exists = fitting_bins_count > 0 && {
            // approximate: item leaves usable residual in some open bin
            mean_residual > item_size as f64 + 20.0
        };
        if fitting_bins_count > 0 && good_fit_exists {
            score += 120.0; // discourage opening new bin when decent fit exists
        } else if fitting_bins_count == 0 {
            score -= 200.0; // must open new bin
        } else {
            // fit exists but poor: mildly prefer new bin early, less so late
            score -= 40.0 * (1.0 - progress);
        }
        // Fewer open bins => slightly prefer reusing infrastructure
        score += open_bins_count as f64 * 2.0;
    } else {
        // Mild bonus for keeping bins balanced with global mean residual.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth normalized residual: dead space ratio
    let x = pr / cap; // in [0,1]

    // Non-linear polynomial coupling of dead space with stream progress:
    // later in the stream, dead space becomes more costly (wasted capacity can't be amortized)
    let dead_penalty = x * x * (1.0 + 2.0 * progress) + x * x * x * 3.0 * progress;
    score += dead_penalty * cap;

    // Reward tight fits (small post_residual) with a smooth saturating term
    let tight = (-x * 6.0).exp() * (1.0 + progress);
    score -= tight * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    } else {
        // mild penalty when many bins fit, to prefer the tightest (already via residual)
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: smooth interaction between post_residual and next item size.
    // If next item could exactly fill post_residual, reward; if post_residual is
    // awkwardly small-but-nonzero for next item, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let g = gap / cap;
        // smooth valley at gap == 0
        score += g * g * cap * 2.0 * (1.0 - progress * 0.5);
        // if next item fits exactly, big reward
        if nx <= pr {
            let fill = nx / pr.max(1.0);
            score -= 6.0 * fill * fill * (1.0 + progress);
        }
    } else {
        // last item: any residual is pure waste
        score += pr * 0.5;
    }

    // Mild preference for filling already-open bins vs. spreading (mean residual coupling)
    let dev = (pr - mean_residual).abs();
    score += dev * 0.05 * (1.0 - progress);

    // New-bin candidate: empty bin has full residual; make it slightly less attractive
    // than a decent existing fit, but attractive when existing residuals are all tiny.
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod capacity fractions
    let q = post_residual / (bin_capacity / 4); // quarter-class: 0..4
    match q {
        0 => score -= 40.0,                       // nearly perfect fit
        1 => score -= 15.0,                       // leaves a useful small slot
        2 => score += 5.0,                        // half-full: mediocre
        _ => {}                                   // large residual, neutral
    }

    // Dead-space penalty: residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        // harmonic bonus when next item lands in a good class too
        if (post_residual - next_item_size) % (bin_capacity / 4) == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 12.0; // next item cannot follow here
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: prefer keeping it closed early; open only when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 20.0 + 25.0 * (1.0 - progress) - 15.0 * crowding.min(3.0);
    }

    // Prefer bins tighter than the average residual (best-fit flavor)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild preference for bins with large absolute residual when many bins are open
    if open_bins_count > 4 {
        score += 0.05 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest possible item (size 1) are already impossible here,
    // but tiny residuals (<= 10) are "dead space" for most practical
    // distributions and should be strongly penalized.
    if post_residual <= 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 12.0;
    } else if post_residual <= 30 {
        score += 5.0;
    }

    // Reward near-perfect fills explicitly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Open-bins pressure: discourage spreading across many bins unless
    // the fit is genuinely good.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score += 3.0; // leaves near-dead space after the next item
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    // Prefer reusing an existing bin with a good fit; only let the new bin
    // win when the best available fit is poor (large post residual).
    if bin_residual == bin_capacity {
        // Neutral baseline slightly worse than a tight fit, slightly better
        // than a wasteful fit.
        score += 15.0;
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Compare against mean residual: placing into a bin whose residual is
    // far below average means it is already tight — good, reward it.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for the next item => strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += diff * 0.6;
        }
        // If next item can also fit here afterwards, mild reward
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: reward tight packing
        score -= 5.0;
    }

    // Penalize dead space relative to mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 20.0;
        // If next item is large, a fresh bin is more attractive
        if next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Prefer filling bins with larger fill fraction
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Late in stream: tighten packing more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize dead space quadratically: small post_residual is good.
    let pr = post_residual as f64;
    score += 0.35 * (pr / 100.0) * (pr / 100.0) * 100.0;

    // Lookahead: if next item can fit into post_residual, bonus; if post_residual
    // is too small for the next item (dead space), penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
        // If next item exactly fills post_residual, huge bonus (perfect pair).
        if next_item_size == post_residual {
            score -= 40.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin wastes the residual of all open bins.
    // Only allow it when this bin's fit would be very poor (large post_residual)
    // or when few bins are open early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = pr > 35.0;
        let early = progress < 0.15 && open_bins_count < 4;
        if poor_fit || early {
            score -= 20.0 + 0.2 * pr;
        } else {
            score += 45.0 + mean_residual * 0.3;
        }
    }

    // Mild pressure toward bins below mean residual (consolidate space).
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score += 5.0;
    } else if bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Late-stream tightening: as stream progresses, avoid leaving awkward gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (pr / 100.0);

    // Prefer bins whose residual is close to item size (modular fit).
    let diff = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); late, tolerate larger residuals
    // less, since future items are fewer — keep pressure toward tight packing.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = post * (1.0 - 2.0 * progress + p2) * 0.5
                 + post * post / cap * (progress * (1.0 - progress)) * 0.8;
    score += coupling;

    // Dead-space penalty: residuals too small to ever fit typical items.
    if post < item_size as f64 {
        score += 12.0 * (1.0 + p2);
    }

    // Lookahead: reward if next item fits in post_residual (chaining).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (1.0 - progress) * (post / cap);
    } else if next_item_size > 0 {
        score += 2.0 * progress;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (more room left than average) slightly,
    // keeping a spread of residuals for future items.
    score += 0.15 * (mean_residual - post);

    // New-bin candidate: penalize mildly unless current fit is bad or many bins open.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) > cap * 0.5;
        let pressure = open_bins_count as f64 / (10.0 + total_items as f64 * 0.05);
        if bad_fit && progress > 0.2 {
            score -= 5.0;
        } else {
            score += 8.0 + 10.0 * pressure;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes of the capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward tight fits, especially on harmonic boundaries (exact quarters)
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always best
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if (post_residual % 25) == 0 {
        score -= 25.0; // quarter-capacity harmonic residual is reusable
    } else if (post_residual % 10) == 0 {
        score -= 12.0; // decade-harmonic residual
    }

    // Penalize dead space in awkward harmonic zones
    if pr > 0.0 && pr < 10.0 {
        score += 30.0; // sliver unusable by any item (min size 1..100, mostly >10)
    }
    if frac > 0.35 && frac < 0.5 {
        score += 8.0; // half-open awkward zone
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + 0.3 * next_item_size as f64;
        // exact harmonic match for next item
        if next_item_size == post_residual {
            score -= 30.0;
        }
    } else if next_item_size > post_residual {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should lose unless current bins are crowded
    if bin_residual == bin_capacity {
        // neutral baseline; open bins with good residuals should beat it
        score = 0.5 * cap + 0.2 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits, must open
        }
    }

    // Late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste. Penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0;
    } else if post_residual < 40 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Perfect or near-perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // If the leftover can exactly fit the lookahead item, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer consolidating into existing bins rather than opening more.
    let pressure = open_bins_count as f64;
    if bin_residual < bin_capacity {
        score -= 3.0 * pressure.sqrt();
    } else {
        // New-bin candidate: only attractive when existing bins fit poorly.
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score += 10.0 - mean_gap * 0.5;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight mid-stream conservatism: keep bins balanced early,
    // allow more aggressive packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress);

    // Discourage leaving residuals that match neither current nor next item
    // (unusable gap), mildly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (small post_residual is good).
    let norm_post = post_residual as f64 / bin_capacity as f64;
    score += norm_post * 30.0; // extra penalty for wasted space beyond raw residual

    // 2-step lookahead: strongly reward bins where the NEXT item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: next item slots exactly into leftover space.
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 45.0 - chain_fit * 0.35;
        } else {
            // Next item won't fit here: penalize leaving a nearly-useless gap
            // unless the gap is small (still decent single-item closeout).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6;
        }
        // Bonus if next item fits EXACTLY after this one (zero dead space chain).
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to a fresh bin's usefulness or no good open option exists.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin: it costs a bin, so keep score moderately high.
        score += 40.0;
        // If item nearly fills a fresh bin, opening is great (item is huge).
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 70.0;
        }
        // If many bins already fit the item, discourage opening another.
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight"
    // and should be prioritized to close them out.
    score -= (mean_residual - bin_residual as f64) * 0.25;

    // Mild penalty for leaving very small unusable slivers (dead space < 10).
    if post_residual < 10 && post_residual > 0 {
        score -= 8.0; // tiny slivers are near-wasted; closing bin out is fine
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let min_item = 1.0;
        let dead = (post_residual as f64) - min_item;
        if dead > 0.0 {
            // If lookahead item fits the post residual, this is good (chain fit).
            if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
                score -= 25.0;
            } else {
                // Dead space grows more costly as the stream progresses.
                let progress = step_index as f64 / (total_items.max(1) as f64);
                score += 0.35 * dead * (0.5 + progress);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; penalize it
    // unless the item would leave a very poor residual elsewhere or many bins
    // are already open with large residuals (fragmentation).
    if bin_residual == bin_capacity {
        let mut nb = 55.0;
        // Scale cost with number of open bins (encourage consolidation early).
        nb += 3.0 * (open_bins_count as f64);
        // If mean residual is large and item fits poorly (post_residual small
        // relative to mean), opening a new bin may be fine; reduce penalty.
        let waste_elsewhere = mean_residual - post_residual as f64;
        if waste_elsewhere > 0.0 {
            nb -= 0.4 * waste_elsewhere;
        }
        // If lookahead item is large and would need a fresh bin anyway, allow
        // opening now.
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 && (next_item_size as u32) > bin_capacity - item_size.max(1) {
            nb -= 20.0;
        }
        score += nb.max(5.0);
    }

    // Slight preference for bins whose residual is close to the item size
    // (best-fit flavor beyond raw post_residual).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * fit_gap;

    // Mild consolidation pressure: prefer bins with below-mean residual
    // (fill the emptiest-fitting bins first keeps many partially filled bins usable).
    let res_diff = bin_residual as f64 - mean_residual;
    score += 0.1 * res_diff;

    // Late-stream urgency: as the stream ends, avoid opening bins and prefer
    // squeezing items into existing space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: quadratic penalty on leftover space (dead space avoidance)
    let mut score = pr_norm * pr_norm;

    // Smooth cubic coupling of leftover with stream progress:
    // late in the stream, leftover waste matters more
    score += 0.5 * pr_norm * pr_norm * pr_norm * (0.5 + progress);

    // Tight fit reward: smooth gaussian-like term favoring small post_residual
    score -= 1.5 * (-(pr_norm * pr_norm) * 8.0).exp();

    // Perfect-fit reward via interaction with progress
    score -= 0.8 * (1.0 - pr_norm) * (1.0 + progress);

    // Last-chance bin: strong smooth reward to use it rather than open new bin
    let last_chance = (fitting_bins_count == 1) as f64;
    score -= 2.0 * last_chance * (1.0 - is_new_bin);

    // Lookahead coupling: reward if next item fits smoothly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score += 0.4 * gap * gap;
        // reward when next item exactly or almost fits
        score -= 0.6 * (-(gap * gap) * 12.0).exp();
    }

    // New-bin candidate: penalize opening a new bin, less so early in stream
    // or when this bin would otherwise be a terrible fit (large pr_norm already
    // penalized above, so scale the new-bin penalty by fit quality).
    let fit_quality = 1.0 - pr_norm; // 1.0 for empty new bin
    score += is_new_bin * (1.5 + 2.0 * progress + 0.01 * open_bins_count as f64) * fit_quality;

    // Mild penalty when many bins are open and this placement wastes mean-residual opportunity
    score += 0.1 * (pr_norm - (mean_residual / cap)).abs() * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: prefer residuals that are
    // "friendly" sizes (small, or exact multiples of common item sizes).
    let cap_frac = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize large wasted residual quadratically, but reward residuals
    // that divide cleanly into the capacity (harmonic classes).
    let harmonic_bonus = if post_residual == 0 {
        -50.0
    } else if post_residual % 10 == 0 {
        -8.0
    } else if post_residual % 5 == 0 {
        -3.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Tight fit reward: small post_residual relative to capacity.
    score -= 20.0 * (1.0 - pr / cap_frac).max(0.0);

    // Lookahead: if next item fits the post residual exactly or closely,
    // strongly reward this placement (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / cap_frac);
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > post_residual {
        // Dead space for the known next item: penalize.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (high mean residual spread vs item size) or this bin is full-ish.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs();
        score = 60.0 + fragmentation - (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0;
        }
        // Late in the stream, discourage opening bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference to fill bins that already deviate from the mean
    // (consolidate waste into few bins).
    if bin_residual < bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize moderate dead space relative to capacity.
    let frag = post_residual as f64 / bin_capacity as f64;
    score += frag * frag * 30.0;

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 10.0 + 4.0 * open_bins_count as f64;
    }

    // Lookahead: favor bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Progress-scaled mean-residual coupling: prefer bins near the mean residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64).abs() * (0.3 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward residuals that exactly match the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item is a jackpot.
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score += diff * 0.35;
        }
        // Penalize leaving residual that is too small for the smallest plausible item
        // (dead space), more so when it cannot host the lookahead item.
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
        // If bin can also fit the next item after this one, extra reward.
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Relative-to-mean coupling: a bin whose post residual deviates far below the
    // mean residual is being "used up" well - mildly reward that.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count == 0 {
            0.0
        } else {
            mean_residual / bin_capacity as f64
        };
        // If open bins still have plenty of room on average, opening a new bin is bad.
        score += 15.0 + 40.0 * crowding;
        // Early in the stream, opening bins is cheaper (spread items out).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for very tight fits that leave awkward small slivers.
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used for a dynamic time horizon.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Core fit quality: reward tight packing (small post_residual) ---
    // Non-linear: quadratic penalty on wasted space makes near-perfect fits much better.
    let fit_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_frac * fit_frac;

    // --- Lookahead (k=2): reward bins whose leftover can host the next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainability bonus, scaled by how snugly the next item fits too.
            let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * (1.0 - slack);
        } else {
            // Leftover too small for the next item: potential dead space penalty.
            score += 6.0 * fit_frac;
        }
    } else {
        // Last item of the stream: minimize leftover hard.
        score += 10.0 * fit_frac;
    }

    // --- Last-chance logic: if this is the ONLY bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Penalize by average fragmentation of open bins and by open-bin count.
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 15.0 + 8.0 * fragmentation + 1.5 * open_bins_count as f64;
        // Early in the stream, keep bins open longer (favor reuse); late, allow spreading.
        score -= 10.0 * t;
        // If no open bin can fit at all, opening is necessary: soften the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Reward reusing already-open bins, more so when many bins are open.
        score -= 2.0 + 0.5 * open_bins_count as f64;
        // Slight preference for bins with residuals close to the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // --- Time-horizon modulation: as the stream progresses, tighten packing ---
    score *= 1.0 + 0.15 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Polynomial coupling of post-residual with stream progress:
    // late in the stream, dead space becomes more costly (less time to fill it)
    let coupling = norm_pr * (1.0 - progress) * (progress * 3.0);
    score += 30.0 * coupling * cap * 0.01 * 10.0; // smooth interaction term
    score += 60.0 * norm_pr * progress * progress;

    // Reward tight fits (post_residual near 0) increasingly with progress
    score -= 50.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize creating residuals that are too small to be useful later
    // (items are 1..100, so residual below ~small threshold is dead space)
    let dead = if pr > 0.0 { (1.0 - norm_pr) * (norm_pr) } else { 0.0 };
    score += 25.0 * dead * (1.0 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 35.0 * (1.0 - slack) * (0.5 + progress);
        } else {
            // post-residual too small for next item: mild penalty growing with progress
            score += 15.0 * (nxt - pr) / cap * (0.5 + progress);
        }
    }

    // Contextual terms: many open bins with high mean residual -> discourage
    // adding to fragmentation; few open bins -> encourage consolidation
    let open = open_bins_count as f64;
    let mean_r_norm = mean_residual / cap;
    score += 10.0 * mean_r_norm * (1.0 - mean_r_norm) * (open / (open + 5.0));

    // New-bin candidate (empty bin): penalize so it is chosen only when
    // no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score += 120.0 - 60.0 * progress;
        // if item fits poorly in every open bin, the penalty is partly waived
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins whose residual is close to item size
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 20.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: tiny remainders are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else if pr <= 5 {
        score += 25.0; // near-dead space
    } else if pr <= 10 {
        score += 12.0;
    }

    // Modulo-10 harmonic class of post_residual: remainders in awkward classes
    // (1..9 mod 10 that can't pair with common sizes) get penalized.
    let m = pr % 10;
    if pr > 0 && pr < 40 {
        match m {
            1 | 2 | 3 => score += 10.0, // unusable slivers
            4 | 5 | 6 => score += 5.0,
            7 | 8 | 9 => score += 2.0,
            _ => {}
        }
    }

    // Integer-division thresholds: can post_residual host the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0; // chains nicely
            // extra reward if post_residual is close to next item (tight chain)
            let gap = pr - next_item_size;
            if gap <= 5 { score -= 8.0; }
        } else {
            score += (next_item_size - pr) as f64 * 0.3; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize slightly so it's chosen only when fits are bad,
    // but relax late in the stream or when many bins are open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let slack = mean_residual - item_size as f64;
        score += 18.0 - 10.0 * progress - 0.05 * slack.max(0.0);
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 25.0; // next item needs a fresh bin anyway
        }
    }

    // Prefer filling fuller bins (tightness coupling).
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 10.0 * fill * fill;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful later
    // are heavily penalized. Threshold based on smallest plausible item.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small but usable gap) mildly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Penalize creating a gap that cannot fit the lookahead item while other
    // placements might; reward if post_residual fits next_item_size exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // wasted space relative to lookahead
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.6 * progress);

    // New-bin candidate: make it attractive only when the fit into open bins is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced when item is large or fit elsewhere is bad.
        let poor_fit_penalty = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let base_cost = 55.0 - poor_fit_penalty;
        // Large items leave little residual anyway; slight discount for big items.
        let size_discount = item_size as f64 * 0.25;
        score = base_cost - size_discount + post_residual as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Mild preference for bins below mean residual (consolidating fuller bins).
    score += ((mean_residual - bin_residual as f64) * 0.15).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that will be exactly filled.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Tighter leftover after the next item is better.
            score -= 80.0 * (1.0 - gap / bin_capacity as f64);
            if gap <= 5.0 {
                score -= 60.0;
            }
        } else {
            // Next item cannot fit here after this placement: penalize proportionally.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    }

    // Relative-to-mean-residual coupling: bins tighter than average are more precious;
    // wasting them is costly, while loose bins are safer dumping grounds.
    if (bin_residual as f64) < mean_residual {
        score += 15.0;
    } else {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * post_residual as f64;
    }

    // New-bin candidate: only attractive when the current item is huge relative to
    // capacity or late in the stream; otherwise discourage spreading across bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 120.0 - 60.0 * big_item - 40.0 * progress;
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize leaving dead space that cannot fit typical items (<= small threshold).
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // nearly perfect, keep it attractive
    } else if post_residual >= 10 && post_residual < 30 {
        score += 10.0; // awkward gap zone
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score += 8.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins for large items;
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 25.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it's a laggard bin — prefer filling it.
    let diff = mean_residual - post_residual as f64;
    score -= 0.3 * diff;

    // New-bin candidate: make it moderately attractive only when the item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 40.0 * large;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += poly * cap * (0.5 - progress);

    // Penalize dead space more as stream progresses
    score += (norm_pr * norm_pr) * cap * (0.3 + 0.4 * progress);

    // Reward tight fits (small post_residual) especially when few alternatives
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (ni / cap);
        } else {
            score += 6.0 * ((ni - pr) / cap);
        }
    }

    // Slight penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
        score -= 10.0 * norm_pr;
    }

    // Mean residual deviation term
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "usable" residue classes (multiples of small denominators) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement.
    let post_frac = post / cap;

    // Penalize dead space quadratically, but modulate by harmonic class:
    // post_residual divisible by 10, 20, 25, 50 are "clean" leftovers that
    // typical item sizes (1..100, often multiples of 5/10) can still fill.
    let mut dead_penalty = post * post / cap;
    let clean_div: [u32; 5] = [50, 25, 20, 10, 5];
    for (i, &d) in clean_div.iter().enumerate() {
        if post_residual > 0 && post_residual % d == 0 {
            // Reward cleaner classes more (50 > 25 > 20 > 10 > 5).
            dead_penalty *= 1.0 - 0.12 * (clean_div.len() - i) as f64;
            break;
        }
    }
    score += dead_penalty;

    // Perfect fit: extremely attractive.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this bin is a perfect two-step placement.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: mild reward proportional to how well it uses leftover.
            score -= 40.0 * (next / post.max(1.0));
            // Harmonic bonus if the pair (item, next) leaves a clean residue again.
            let post2 = post_residual as u32 - next_item_size;
            if post2 % 10 == 0 {
                score -= 30.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize large unusable gaps
            // more strongly when the gap is in a "dead zone" (small, awkward leftover).
            if post_residual < next_item_size {
                score += 0.5 * (next - post);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0 + 0.3 * (item_size as f64);
    }

    // New-bin candidate handling: an empty bin has post_frac == 1.0.
    // Favor opening a new bin only when existing leftovers are badly fragmented
    // (high mean residual dispersion proxy: mean_residual large relative to capacity)
    // and the current item is large.
    if bin_residual == bin_capacity {
        // Base cost of a new bin: discourage slightly.
        score += 25.0;
        // But if the item is large and open bins are mostly full, new bin is fine.
        let fill_pressure = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score -= 50.0 * fill_pressure * (item_size as f64 / cap);
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // Harmonic guard: opening a new bin for an item that would leave a clean
        // half/quarter-full bin is acceptable early on.
        if item_size % 50 == 0 {
            score -= 15.0;
        }
    }

    // Fragmentation penalty relative to mean residual: placing into a bin whose
    // residual is far below average wastes the "rich" bins; prefer richer bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.2 * residual_gap.max(0.0);

    // Mild pressure to reduce open bin count when many bins are open.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items
    // are "dead". Penalize small unusable gaps sharply (non-linear).
    if post_residual > 0 {
        // dead zone: residual below ~12 cannot hold even the smallest item (1..100 range, but be conservative)
        if post_residual <= 10 {
            score += 40.0 + (10 - post_residual) as f64 * 8.0;
        } else if post_residual <= 20 {
            score += 18.0 + (20 - post_residual) as f64 * 1.5;
        }
    }

    // Reward tight fits (small post_residual) mildly — baseline already favors it,
    // add extra bonus for near-perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin; if next item cannot fit, add mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 8.0 {
                score -= 15.0 - slack; // near-exact lookahead match
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: mildly discourage scattering across many open bins,
    // but keep it weak so dead-space logic dominates.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: penalize opening a new bin, but relax the
    // penalty when existing bins would create severe dead space.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0 + open_bins_count as f64 * 2.0;
        // If the best alternative would leave a tiny dead gap, allow opening.
        if post_residual <= 10 {
            new_bin_penalty -= 25.0;
        }
        score += new_bin_penalty;
    }

    // Mean residual context: when open bins are on average very full, prefer
    // using them (their residuals are scarce resources).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact or near-exact fill is highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small residuals below the minimum item size are wasted.
        if post_residual < 10 {
            score += 50.0;
        }
        // Reward residuals that can still accommodate typical items.
        score -= 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // 2-step lookahead: reward when post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < f64::EPSILON {
            score -= 500.0;
        } else if post_residual as f64 > next {
            // Residual can host the next item: mild reward proportional to closeness.
            let slack = post_residual as f64 - next;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to the gap.
            score += 20.0 * (next - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from the mean.
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Early in the stream, slightly discourage opening many new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical small items (<= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 12.0;
        } else if next_item_size <= bin_capacity {
            // next item will need a fresh bin; slight penalty for wasting big residual
            score += (post_residual as f64) * 0.05;
        }
    }

    // New-bin candidate handling: neutral baseline, opened only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * (1.0 - progress);
        // If many open bins already, a new bin is less harmful.
        score -= (open_bins_count as f64).min(20.0);
        // If next item is large, having a fresh bin may help later.
        if next_item_size > 60 { score -= 10.0; }
    }

    // Prefer bins with residual far below the mean (denser bins absorb item better).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Mild penalty for spreading across many open bins when this bin is nearly full.
    if bin_residual as f64 <= mean_residual {
        score -= 5.0;
    }

    // Time horizon: late in stream, discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap; // 0..1
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 40.0 * base * (progress - 0.5);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (non-linear)
    let dead = (pr - mean_residual) / cap;
    score += 15.0 * dead * dead.abs();

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space that fits the next item (smooth coupling)
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64) / cap;
        score -= 12.0 * fits_next * (1.0 - gap * gap);
    } else {
        // Last item: minimize leftover
        score += 20.0 * norm_pr * norm_pr;
    }

    // Mild penalty for proliferation of open bins late in the stream
    score += 2.0 * (open_bins_count as f64).ln() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into octiles.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let octile = (post * 8.0 / cap).floor() as i32; // 0..=7

    // Reward near-exact fills (post_residual small => already low score),
    // extra bonus for hitting exact harmonic divisions of capacity.
    let harmonic = |r: u32| -> bool {
        r == 0 || bin_capacity % r.max(1) == 0
    };
    if harmonic(post_residual) {
        score -= 6.0;
    }

    // Penalize dead space: residuals in awkward middle classes (2..5) are hard to fill.
    match octile {
        0 => score -= 4.0,                 // nearly full: excellent
        1 => score -= 2.0,                 // small gap, often fillable
        2 | 3 => score += 5.0,             // awkward dead zone
        4 | 5 => score += 2.0,             // moderate
        _ => {}                            // large residual: fine
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            // prefer leaving room divisible into useful classes for next item
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 3.0;
            } else {
                score += (gap as f64) * 0.15;
            }
            // harmonic match: next item leaves another harmonic residual
            if next_item_size <= post_residual && harmonic(post_residual - next_item_size) {
                score -= 4.0;
            }
        } else {
            // next item cannot fit in this bin's remainder; slight penalty if
            // this bin is the only fitting one (last chance logic)
            if fitting_bins_count == 1 {
                score -= 8.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that grows with
    // open bins count, so we reuse bins unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // but if no open bin fits well (item large relative to mean residual), new bin is fine
        if item_size as f64 > mean_residual + 5.0 {
            score -= 15.0;
        }
    }

    // Stream progression: early on, be more willing to open bins / keep flexibility;
    // late in the stream, squeeze tighter (favor minimal post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0; // slight global tightening
    score += (1.0 - progress) * post * 0.05; // early: penalize wasting big bins less? invert: keep flexibility

    // Mean residual coupling: if this bin's residual is far below mean, it's a good squeeze.
    let diff = mean_residual - post;
    score += diff * 0.05;

    // Integer-division threshold on item size classes (harmonic classes of item itself)
    let item_class = item_size / 20; // 0..4
    score -= item_class as f64 * 0.5; // large items slightly preferred in tighter bins

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.4 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits in post_residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 8.0;
        }
    }

    // Prefer bins below mean residual (fill emptier bins evenly, keep tight bins tight).
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
