pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual is already the base).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize waste of large residual capacity on a big item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 6.0 * fill * (bin_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 5.0;
        } else {
            score += 3.0;
        }
        // Perfect chaining: post residual exactly matches next item.
        if post_residual as u32 == next_item_size {
            score -= 6.0;
        }
    }

    // Time horizon: early in the stream, be picky (prefer new bins for poor fits);
    // late in the stream, consolidate into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = (1.0 - progress) * 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus dynamic penalty.
        score += 4.0 + new_bin_penalty;
        // Opening a new bin is attractive if mean residual is small (open bins are full).
        score -= (mean_residual / bin_capacity as f64) * 4.0;
    } else {
        // Slight preference for bins with residual close to mean (balanced usage).
        score += 0.02 * (bin_residual as f64 - mean_residual).abs();
    }

    // Many open bins: encourage filling existing ones rather than opening more.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: quadratic in normalized post residual (favor tight fits)
    let mut score = pr as f64 * (1.0 + 0.8 * x * x);

    // Smooth coupling: as stream progresses, penalize large residuals more strongly
    score += 15.0 * x.powi(3) * (0.5 + progress);

    // Reward filling a bin nearly completely, scaled by progress
    score -= 10.0 * (1.0 - x) * x * (1.0 + 2.0 * progress);

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Prefer bins below mean residual (tighter bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / cap) * (1.0 + progress);
        } else {
            score += 2.0 * (-gap / cap);
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into capacity fractions
    let post_f = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Penalize dead space classes: residuals in (0,10] are nearly unusable (min item is 1..100 though)
    if post_residual > 0 && post_residual < eighth {
        score += 25.0; // dead space penalty
    }

    // Reward residuals that belong to "harmonic" usable classes (multiples of common item sizes)
    let harmonic = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if r % m == 0 { bonus += 6.0; }
        }
        bonus
    };
    score -= harmonic(post_residual);

    // Exact fit reward via integer division threshold
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= quarter {
        // small leftover: mildly good if next item can use it
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 8.0;
        }
    }

    // Lookahead coupling: if next item fits perfectly here after current placement, reward strongly
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < eighth {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // prefer new bin early (long horizon) if item is large relative to capacity
        let large_item = (item_size as f64) / cap > 0.5;
        if large_item || progress < 0.2 {
            score -= 12.0;
        } else {
            score += 15.0;
        }
    }

    // Discourage spreading across many open bins when mean residual is high
    if (mean_residual - post_f).abs() < 5.0 && open_bins_count > 3 {
        score -= 5.0;
    }

    // Tie-break toward bins whose residual is closest to item size (tight fit)
    score += ((bin_residual as i64 - item_size as i64).unsigned_abs() as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for typical future items are wasted.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 4.0; // unusable gap penalty
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: when many bins are open, prefer packing tightly
    // rather than spreading; when few bins are open, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; attractive only if existing fits are bad.
        score += 10.0 + pressure * 3.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin keeps flexibility for lookahead
        }
    } else {
        // Using an existing bin reduces open-bin pressure slightly.
        score -= pressure * 1.5;
        // Prefer bins whose residual is close to the mean (balanced packing) when many bins open.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05 * pressure;
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let post = post_residual as i64;
        let nxt = next_item_size as i64;
        if post >= nxt {
            let gap = post - nxt;
            // Perfect chain fit -> big reward.
            if gap == 0 {
                score -= 60.0;
            } else if gap <= 10 {
                score -= 25.0 - gap as f64 * 1.5;
            } else {
                // Next item fits but leaves slack; mild reward proportional to fit.
                score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot use the leftover: penalize dead space, worse if tiny.
            let waste = (nxt - post) as f64;
            score += 8.0 + waste * 0.5;
        }
    } else {
        // Last item: simply minimize leftover.
        score -= 5.0;
    }

    // Compare against mean residual: bins with residual far below mean are precious
    // (already dense); penalize dumping large items there unless fit is perfect.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        // This bin has less residual than average -> more valuable.
        score += dev * 0.15;
    } else {
        // Above-average residual: slightly favor using it up.
        score -= (-dev) * 0.05;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin when stream is early
    // and open bins exist; allow it more when many bins are open and mean residual is low.
    if bin_residual == bin_capacity {
        score += 15.0;
        if open_bins_count > 0 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            let mean_res = mean_residual;
            // If average residual is small (bins nearly full), new bin is fine.
            score -= (100.0 - mean_res).min(100.0) * 0.1;
            score -= progress * 5.0;
        }
        // Never open new bin if next item chains perfectly into an existing fit.
        if next_item_size > 0 && (next_item_size as i64) <= (bin_residual as i64 - item_size as i64) {
            score += 10.0;
        }
    }

    // Slight preference for filling larger bins first when many open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 18.0 * tightness * tightness;

    // Penalize leaving dead space that likely cannot be reused.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else {
            score += 3.0;
        }
        // Perfect pair: this item + next item exactly fills bin.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else {
        // Last item: prefer minimal post residual.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing ones over spreading.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64).ln();
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins below mean residual (fuller bins).
    score += 1.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: neutral base, penalized unless current bins are poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * pressure;
        // Opening a new bin is fine early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual, with non-linear (quadratic) waste penalty.
    let mut score = post + 0.008 * post * post / cap;

    // Smooth stream-progress coupling: later in the stream, waste is more costly.
    score += 0.5 * progress * post * (1.0 + (post / cap) * (post / cap));

    // Reward when the next item could exactly fill the post residual (perfect pairing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (-gap / 12.0) * (-gap / 12.0); // exp-like smooth reward
        // Mild penalty if next item clearly won't fit the leftover.
        if next_item_size as f64 > post {
            score += 0.05 * (next_item_size as f64 - post);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate: neutral base at capacity; discourage unless open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64).ln().max(0.0);
        score = cap * (1.0 + 0.02 * crowded) + 0.3 * mean_residual * progress;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Tie-break: prefer bins whose residual is close to mean residual (balance).
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-capacity classes
    let item_class = item_size / (bin_capacity / 4);
    let resid_class = post_residual / (bin_capacity / 4);

    // Reward tight fits: perfect fill gets a large bonus
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // dead-space penalty grows superlinearly for small unusable remainders
        let small = post_residual < 10;
        if small {
            score += 8.0; // tiny remainder is fine (near-perfect fit) -> but base already small
            score -= 12.0;
        }
        // penalize remainders too small to hold any plausible future item (1..100)
        if post_residual < 10 {
            // already handled
        }
    }

    // Harmonic class coupling: prefer post_residual that forms a complementary class
    // with the lookahead item (exact or near-exact match)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 * (1.0 - (slack as f64) / cap);
        } else {
            // lookahead cannot use this residual; mild penalty scaled by gap
            score += ((next_item_size - post_residual) as f64) * 0.08;
        }
    } else {
        // last item: pure tightness
        score -= 30.0 * (1.0 - (post_residual as f64) / cap);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: normalize by tightness
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless residuals
    // of open bins are badly fragmented or bin count is low
    if bin_residual == bin_capacity {
        let frag = if mean_residual > 0.0 {
            (mean_residual - (post_residual as f64)).abs() / cap
        } else {
            0.0
        };
        score += 18.0; // base cost of a fresh bin
        // discount new bin when open bins are crowded (low mean residual)
        score -= 22.0 * (1.0 - (mean_residual / cap).min(1.0));
        // early stream: allow more bins to build class diversity
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        let _ = frag;
    } else {
        // reward using bins whose residual is close to the mean (keeps classes balanced)
        let dev = ((bin_residual as f64) - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Modulo/harmonic thresholds on post_residual: residues in [10..=30] are
    // prime targets for future medium items; residues in [1..9] are near-dead
    let m = post_residual % (bin_capacity / 4);
    if post_residual >= 10 && post_residual <= 30 {
        score -= 6.0;
    }
    if post_residual >= 1 && post_residual <= 9 {
        score += 4.0; // nearly-dead space
    }
    if m == 0 && post_residual > 0 {
        score -= 3.0; // class-aligned residual
    }

    // item-class harmonic bonus: big items (class 2-3) prefer large residuals
    let _ = item_class;
    if item_size >= bin_capacity / 2 && bin_residual >= item_size + 20 {
        score -= 4.0;
    }

    // slight penalty for accumulating too many open bins
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are pure waste.
    // Penalize "unusable" gaps hard; reward residuals that exactly match a useful size.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            // Gap can hold the lookahead item: mildly reward.
            score -= 8.0;
        } else {
            // Gap is dead space for the next item: penalize proportionally to its smallness.
            score += 10.0 + (item_size as f64) * 0.15;
        }
    } else {
        // Perfect closure: best possible outcome.
        score -= 25.0;
    }

    // Tight-fit reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Open-bin pressure: discourage opening extra bins when many are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin starts with a huge residual; base term already large.
        // Penalize further when open bins exist that could fit, unless this is a forced last chance.
        if fitting_bins_count > 0 {
            score += 30.0 + 5.0 * (open_bins_count as f64).sqrt();
        } else {
            score -= 5.0; // forced opening: slight reward
        }
    } else if fitting_bins_count == 1 {
        // This is the last fitting bin: strongly favor using it.
        score -= 15.0;
    }

    // Slight preference to keep residuals near the mean (balanced bins are easier to pack later).
    score += 0.3 * ((post_residual as f64) - mean_residual).abs();

    // Early in the stream, be more willing to open bins (better long-run structure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if is_new_bin {
        score -= 10.0 * (1.0 - progress);
    }

    // Pairing bonus: residual exactly fits the next item after this one leaves a perfect pair.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 500.0;
        } else if diff <= 5 {
            score -= 150.0;
        } else if diff <= 15 {
            score -= 40.0;
        } else {
            // Penalize leaving residual far from the next item's size (dead space).
            score += diff as f64 * 0.5;
        }
        // Perfect chaining: this fit empties the bin AND next item fits exactly elsewhere-ish.
        if post_residual == 0 && next_item_size <= bin_capacity {
            score -= 100.0;
        }
    } else {
        // Last item: only exact fits matter.
        if post_residual == 0 {
            score -= 500.0;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
        if post_residual > 40 {
            score += 60.0; // but avoid leaving huge dead space if a new bin is cheap
        }
    }

    // New-bin candidate: penalize opening a new bin unless current options are poor.
    if bin_residual == bin_capacity {
        score += 250.0;
        // But if no existing bin fits well, opening new is fine.
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        // Early in stream, slightly cheaper to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 50.0;
    }

    // Mild preference for tighter bins overall.
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward low post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Reward high occupancy of the bin before placement.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fill * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Many fitting bins -> we can afford to be picky; penalize loose fits more.
    if fitting_bins_count > 1 {
        score += 3.0 * fit_ratio * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Lookahead coupling: if next item fits the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Dead space penalty scaled by how much next item misses fitting.
            let miss = (next_item_size as i64 - post_residual as i64).max(0) as f64;
            score += 0.05 * miss;
        }
    }

    // Compare against mean residual: bins already below mean residual are good targets.
    score += 0.08 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Early in stream: encourage consolidation into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0 * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin, more so when good fits exist,
    // less so late in the stream or when the item is large (hard to place later).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 10.0;
        if fitting_bins_count > 0 {
            new_bin_penalty += 4.0;
        }
        if item_size > 60 {
            new_bin_penalty -= 3.0;
        }
        if progress > 0.8 {
            new_bin_penalty -= 2.0;
        }
        score += new_bin_penalty;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (tight fit)
    let mut score = pr as f64;

    // Non-linear polynomial coupling with stream progress:
    // early on, tolerate larger leftovers (future items can fill them);
    // late in the stream, penalize dead space quadratically.
    let progress_weight = progress * progress;
    score += progress_weight * 3.0 * x * x * cap;

    // Smooth reward for very tight fits (x near 0), decaying cubic
    score -= (1.0 - x).powi(3) * (1.0 + progress) * 2.0;

    // Penalize leftovers that are too small to be useful for typical items,
    // scaled by mean residual context (smooth interaction)
    let uselessness = (1.0 - x) * x; // peaks mid-range... invert: dead space when x small
    let dead = (0.3 - x).max(0.0) / 0.3;
    score += dead * dead * (1.0 + mean_residual / cap) * 5.0;
    let _ = uselessness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 {
        let ndiff = (pr - next_item_size as f64).abs();
        score -= (1.0 - ndiff / cap).powi(2) * 3.0 * (1.0 - progress);
    }

    // Mild penalty for opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 2.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large
    // class sizes (10, 20, 25, 50) are more "reusable" by future items,
    // since typical item sizes cluster on round numbers.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 { score -= 12.0; }
        else if pr % 25 == 0 { score -= 8.0; }
        else if pr % 20 == 0 { score -= 7.0; }
        else if pr % 10 == 0 { score -= 5.0; }
        else if pr % 5 == 0 { score -= 2.0; }
        else { score += 3.0; } // awkward residual class
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual
    // (with harmonic-class alignment), reward heavily.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 10.0 - slack * 0.15;
        if pr % 10 == 0 && next_item_size % 10 == 0 {
            score -= 4.0; // same decimal harmonic class
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Post-residual too small for lookahead: dead-space penalty
        // grows when residual is in the "useless band" (1..10).
        if pr > 0 && pr < 10 {
            score += 8.0 + pr as f64;
        }
    }

    // Fractional tightness: reward filling a large fraction of the bin.
    let fill = (item_size as f64) / cap;
    score -= fill * 6.0;

    // Last-chance bin: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: an empty bin has perfect class
    // residuals; make it attractive only when the item is small or
    // no existing bin gives a tight fit.
    if bin_residual == bin_capacity {
        let base = 30.0 + (item_size as f64) * 0.35;
        // Penalize opening new bins when many bins are already open
        // and the item is small relative to mean residual space.
        let pressure = if mean_residual > (item_size as f64) { 10.0 } else { 0.0 };
        score = base + pressure
            + (open_bins_count as f64) * 0.5
            - (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    // Mild preference to consolidate into fewer bins early on.
    if bin_residual != bin_capacity {
        score -= 1.0 / (1.0 + open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal: strongly reward post_residual == 0.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space avoidance: residuals too small for any realistic item (<= 9)
    // are "unusable" gaps; penalize them heavily.
    if post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Residuals in the awkward mid-range (10..=25) are semi-dead: moderate penalty.
    if post_residual > 9 && post_residual <= 25 {
        score += 8.0;
    }

    // Reward leaving room for the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // If next item fits exactly afterwards, big reward.
            let after = post_residual - next_item_size;
            if after == 0 {
                score -= 200.0;
            } else if after <= 9 {
                score -= 30.0;
            }
            score -= 15.0;
        } else {
            // Post-residual cannot host the next item: penalize proportionally.
            score += 5.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is costly when many bins exist;
    // make the empty-bin candidate less attractive unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        // But if the item fills a fresh bin substantially, opening is fine.
        if item_size >= 70 {
            score -= 60.0;
        }
    }

    // Open-bins pressure: discourage scattering across many open bins.
    score += 0.5 * open_bins_count as f64;

    // Mild progression term: early on, prefer tighter packing to build structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Prefer bins whose residual is close to the item (tight fit overall).
    score += 0.2 * ((bin_residual as f64 - item_size as f64) - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly matches the post residual,
    // penalize when the next item cannot fit in the leftover space.
    if next_item_size > 0 {
        let pr = post_residual as u32;
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next item fits: mild reward proportional to how snugly it fits
            score -= 0.5 * (pr - next_item_size) as f64;
        } else {
            // next item cannot use this residual: dead-space penalty
            let waste = (next_item_size - pr) as f64;
            score += 0.3 * waste;
        }
    }

    // Penalize large unusable residuals relative to mean residual across open bins.
    score += 0.2 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Mild penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 * open_bins_count as f64;
    }

    // Late-stream conservatism: waste matters more as the stream ends.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer minimal post-residual strongly (best-fit core).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fit
    }

    // Dead-space penalty: post_residual too small for any plausible future item.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score -= 50.0;
    } else if (post_residual as f64) < 20.0 {
        // small dead space is usually fine late in the stream
        score += 10.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits into post_residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else if next_item_size > bin_residual {
            // this bin can't take next item anyway; slightly favor using it now
            score -= 5.0;
        } else {
            // next item would fit here but not in the leftover: mild penalty
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor filling the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Crowding: if many bins are open, prefer consolidation into existing bins.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / bin_capacity as f64);
    score += crowding * 2.0;

    // New-bin candidate handling: residual == capacity means fresh bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized unless current bins have poor fits
        // or many bins are already open and mean residual is tiny.
        let mut open_penalty = 120.0;
        if fitting_bins_count == 0 {
            open_penalty = 0.0; // no alternative
        } else if fitting_bins_count == 1 {
            open_penalty = 200.0; // keep the last-chance bin alive
        }
        // Late in stream, prefer closing out existing bins.
        open_penalty *= 1.0 + 0.5 * progress;
        // If mean residual across bins is large, opening new bin is wasteful.
        open_penalty += mean_residual * 0.3;
        score += open_penalty;
        // Fresh bin baseline: its raw residual is large, so subtract to normalize.
        score -= bin_capacity as f64 * 0.9;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr_norm = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: waste grows superlinearly for small post-residuals
    score += 30.0 * pr_norm * pr_norm * (1.0 - progress);

    // Reward tight fits more strongly as stream progresses (consolidation pressure)
    score -= 25.0 * (1.0 - pr_norm) * (0.5 + progress);

    // Penalize leaving residual close to mean_residual (wasted duplicated slack)
    let mr_norm = mean_residual / bin_capacity as f64;
    score += 10.0 * (pr_norm - mr_norm) * (pr_norm - mr_norm);

    // Lookahead: reward leaving space that fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / bin_capacity as f64) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild penalty for spreading across many bins
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: prefer it only when current bins are very full
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls on a
    // "coarse" residue class (multiples of 10) are more reusable.
    let pr = post_residual;
    let coarse = if pr % 10 == 0 { 0.0 } else if pr % 5 == 0 { 6.0 } else { 14.0 };
    score += coarse;

    // Dead space penalty: tiny unusable leftovers.
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Perfect fit bonus.
    if pr == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = bin_residual as f64 - item_size as f64;
        score += 90.0;
        // Opening a fresh bin is attractive only if the item is huge relative
        // to capacity and would leave a near-full unusable residue elsewhere.
        if item_size as f64 > 0.75 * cap {
            score -= 50.0;
        }
        if waste < 15.0 {
            score -= 30.0;
        }
    }

    // Lookahead coupling: reward leaving a residue that can host next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 25.0;
            // Harmonic: residue exactly divisible by next item is ideal.
            if pr % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Progress-scaled tightening: later in the stream, prefer tighter fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    // Spread-awareness: when many bins are open with high mean residual,
    // discourage adding more slack.
    if !is_new_bin {
        score += 0.05 * (mean_residual - post_residual as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0; // dead space up to 80
    }
    // Mid-range gaps that can't hold typical next items (10..80): moderate penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Coupling with lookahead: if next item fits exactly into the post residual,
    // this bin becomes doubly valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
        // Perfect chain: post residual equals next item exactly.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }
    // Penalize if post residual is too small for the (known minimum) next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Open-bin pressure: penalize spreading across many open bins slightly,
    // but favor filling existing bins when few are open.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Prefer bins whose residual is close to the item (tight fits) beyond raw post_residual.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // New-bin candidate logic: an empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.6 + open_bins_count as f64 * 1.0;
        // If only one fitting bin exists, opening a new bin is worse.
        if fitting_bins_count <= 1 {
            score += 200.0;
        }
        // If current best fit would leave dead space, new bin becomes attractive.
        if post_residual > 0 && (bin_residual - item_size) > 0 {
            let dead_here = (bin_residual - item_size) as f64;
            if dead_here < 10.0 {
                score += 100.0; // the open bin wastes little; keep new bin closed
            } else if dead_here > 30.0 {
                score -= 20.0; // open bin wastes a lot; new bin may win
            }
        }
        // Lookahead: if next item is large, a fresh bin is useful.
        if next_item_size > 60 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer small post_residual, but strongly reward an exact 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0; // perfect chain: this bin will be exactly filled by next item
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item can still land here: mild reward proportional to tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space relative to mean residual.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.8 * dead;
    }

    // Penalize post_residual far above the mean residual (wasteful bin usage).
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Reward tight fits (small waste) with a non-linear bonus.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Late in the stream, consolidate: slightly prefer reusing existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress;

    // Slight penalty for opening a new bin when many are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest plausible item.
    if post_residual < 10 {
        score -= 15.0; // near-perfect fill bonus
    } else if post_residual < item_size.min(20) {
        score -= 8.0; // residual too small to be reusable
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives exist; prefer best fit among them.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 12.0 * chain_fit;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize wasting a large residual on this item.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Global state coupling: penalize placements far below mean residual utilization
    // when many bins are open (encourages balancing and closing bins).
    let mean_resid_penalty = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_resid_penalty * (open_bins_count as f64).sqrt();

    // Time horizon: late in the stream, be more aggressive about filling bins tightly
    // and avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    if progress > 0.8 && fitting_bins_count >= 1 {
        score += 6.0 * (1.0 - tightness);
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits well. Since a new empty bin has post_residual = capacity - item_size, make it
    // costly unless item is large and current open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let escape_bonus = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += escape_bonus + 10.0 - 5.0 * crowded.min(3.0);
        // Large items start fresh bins more readily.
        score -= 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base cost: residual left behind, normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, small residuals are acceptable; late in the stream, waste is punished harder.
    let waste_coupling = pr * pr / (cap * cap) * (0.5 + progress);
    score += 0.6 * waste_coupling;

    // Tight fits are rewarded: post_residual near zero gets a smooth cubic discount
    let tightness = 1.0 - pr / cap;
    score -= 0.35 * tightness * tightness * tightness;

    // Penalize bins whose residual deviates from the mean residual (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.15 * dev * dev;

    // Last-chance bin: strongly reward using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Lookahead: reward leaving residual that fits the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 0.3 * (nx / cap) * (1.0 - (pr - nx) / cap);
        } else {
            // residual too small for next item: penalize proportionally to closeness
            score += 0.25 * (1.0 - (nx - pr) / cap);
        }
    }

    // Penalize opening a new bin, more so when many bins are open and can fit the item
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += 1.5 + 0.1 * (open_bins_count as f64) + 0.2 * fit_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: modulo arithmetic on capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let resid_frac = pr / c;

    // Class A: tiny dead space (post_residual < 10) -> excellent fit
    if post_residual == 0 {
        score -= 100.0; // perfect fill
    } else if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Class B: harmonic bands via integer division on post_residual
    let band = post_residual / 10; // 0..10 harmonic class
    score += (band as f64).powi(2) * 0.6;

    // Modulo-structure: residuals divisible by common item sizes are reusable
    let reusable = [10u32, 20, 25, 30, 40, 50];
    for r in reusable.iter() {
        if post_residual >= *r && post_residual % r == 0 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: does next item fit exactly / harmonically?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 25.0; // perfect follow-up fill
        }
        // harmonic class match: next_item shares divisibility with post_residual
        if next_item_size % 10 == 0 && post_residual % next_item_size == 0 {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space trap: next item can't use this residual
        score += 10.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 20.0;
    } else if fill_ratio > 0.7 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score = c * 0.55 + mean_residual * 0.2;
        // open new bin only if remaining open bins are already tight
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        if mean_residual < 20.0 {
            score -= 10.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 12.0;
    }

    // Mild pressure toward bins below mean residual (balance / consolidation)
    score += (pr - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable, punish them hard.
    let dead_threshold = 4.0;
    if (post_residual as f64) < dead_threshold {
        score += 25.0;
    } else if (post_residual as f64) < 10.0 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit reward proportional to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: only attractive when existing residuals are poor for the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 12.0;
        // If this bin is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // If mean residual is large and could hold the item, discourage new bin.
        if mean_residual >= item_size as f64 {
            score += 10.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 8.0;
        }
    } else {
        // Lookahead synergy: leaving room that exactly fits the next item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
        // Penalize wasting a large residual bin on a small item when alternatives exist.
        if fitting_bins_count > 1 && (post_residual as f64) > mean_residual * 1.5 {
            score += 4.0;
        }
    }

    // Slight preference to fill bins early in the stream (keeps bin count low).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: reward bins whose post_residual
    // matches the next item size (chained perfect fits).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Exact chain: post_residual == next_item_size -> very strong reward
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize leaving a residual that no typical item can use (dead space)
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than the average
    let res = post_residual as f64;
    score += 0.35 * (res - mean_residual);

    // Tight fit reward: small post_residual relative to item size
    score -= 6.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad
    if bin_residual == bin_capacity {
        score += 18.0;
        // But allow opening a new bin early in the stream when many bins are open
        // and this bin would serve future large items
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 4 && progress < 0.5 {
            score -= 4.0;
        }
        // If next item is large and this fresh bin would be its only good home,
        // slightly favor opening it
        if next_item_size > item_size && next_item_size >= 50 {
            score -= 6.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize opening a new bin unless the item fits almost perfectly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = (bin_capacity - item_size) as f64;
        score += 60.0 + 0.9 * waste;
        // Small items may be worth a fresh bin if stream is early and bins are few.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if item_size >= 60 && progress < 0.5 {
            score -= 55.0;
        }
    }

    // Reward tight fits (small post_residual already does this; amplify near-perfect fits).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    if fit_ratio < 0.10 {
        score -= 25.0;
    } else if fit_ratio < 0.25 {
        score -= 10.0;
    }

    // Dead-space penalty: residuals that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Lookahead coupling: if next item would fit the post_residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else if next_item_size <= bin_residual {
            // Next item fits this bin now but not after placing current item:
            // mild penalty for consuming the space it needs.
            score += 8.0;
        }
    }

    // Global state: many open bins with high mean residual -> discourage scattering,
    // prefer filling existing bins well.
    if open_bins_count > 3 && mean_residual > 30.0 && !is_new_bin {
        score -= 6.0;
    }
    if is_new_bin && open_bins_count > 0 {
        score += 2.0 * open_bins_count as f64;
    }

    // Time horizon: late in the stream, consolidation matters more; avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && is_new_bin {
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = post * (1.0 + 0.8 * progress * post_norm * post_norm);

    // Reward tight fits via smooth cubic of normalized fill.
    let fill = item_size as f64 / cap;
    score -= 12.0 * fill * fill * fill;

    // Penalize dead space that cannot fit the lookahead item (smooth interaction).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0) / cap;
        score += 8.0 * gap * gap * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild pressure toward consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64 * post_norm;

    // New-bin candidate: slight penalty so it is chosen only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10.
    let residue_class = post_residual % 10;
    // Dead-space classes: small leftovers (1..9) are nearly unusable for items >=10,
    // so penalize them strongly; exact zero is perfect.
    score += match residue_class {
        0 => -8.0,
        1..=4 => 6.0 + 2.0 * residue_class as f64,
        5..=9 => 1.5 * residue_class as f64,
        _ => 0.0,
    };

    // Integer-division threshold: post_residual / 10 as usable "slots".
    let slots = post_residual / 10;
    score -= 0.4 * slots as f64;

    // Lookahead coupling: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 10.0 + 0.3 * slack as f64;
        // Harmonic check: does next item also land on a clean residue boundary?
        if (post_residual % next_item_size.max(1)) == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving large stranded space.
        score += 0.2 * post_residual as f64;
    }

    // Capacity fraction logic: favor bins whose fill ratio post-placement is high.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill_frac * fill_frac;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (post_residual very small is fine).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        // If mean residual across open bins is large, prefer reusing them.
        score += 18.0 + 25.0 * crowding - 10.0 * progress;
    } else {
        // Mild preference for bins tighter than the mean residual.
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    // Open-bin count pressure: many open bins -> consolidate.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (1..100 unknown distribution) are
    // effectively dead space. Penalize small non-zero post_residuals hard.
    if post_residual > 0 {
        // Dead-space severity: the smaller the gap relative to capacity,
        // the more useless it likely is. Penalize gaps < ~30 heavily.
        let gap = post_residual as f64;
        if gap < 30.0 {
            score += (30.0 - gap) * 2.5;
        }
        // Bonus for near-perfect fills.
        if gap <= 3.0 {
            score -= 40.0;
        } else if gap <= 10.0 {
            score -= 10.0;
        }
    } else {
        // Perfect fit: strongest reward.
        score -= 100.0;
    }

    // Dead space is worse if the next item cannot use it: waste it now
    // rather than blocking a future placement.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // If the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; but when this is the last
    // fitting bin, strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin, escalating with
        // the number of already open bins and stream progress.
        score += 60.0 + open_bins_count as f64 * 5.0
            + (step_index as f64 / total_items.max(1) as f64) * 40.0;
        // Exception: if current item leaves a terrible dead gap in any
        // existing bin and this is a big item, opening fresh is fine.
        if item_size >= 70 && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    } else {
        // Mild preference for bins with lower residual (tighter fits first)
        // scaled by open-bin pressure to keep bin count low.
        score += (bin_residual as f64 - post_residual as f64) * 0.1;
        score += open_bins_count as f64 * 0.3;
    }

    // Prefer bins whose residual deviates below the mean (more filled bins).
    if bin_residual != bin_capacity {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio * fit_ratio);

    // Aggressive 2-step lookahead: strongly reward post_residual matching next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can fit exactly or near-exactly after this placement.
            score -= 25.0 * (-gap / 12.0).exp();
        } else {
            // Post-residual too small for next item: penalize wasted space unless tiny.
            score += 8.0 * (1.0 - (-gap / 20.0).exp());
        }
    }

    // Compare against mean residual across open bins: prefer bins whose residual
    // is close to the item (avoid fragmenting large-residual bins unnecessarily).
    let res_gap = (bin_residual as f64 - item_size as f64).abs();
    score -= 6.0 * (-res_gap / 15.0).exp();
    score += 3.0 * (bin_residual as f64 - mean_residual).max(0.0) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless current
    // fit is terrible or the stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        // Open a new bin only if this placement leaves a big unusable hole
        // and the next item likely can't use the post_residual.
        let next_blocked = next_item_size > 0 && post_residual < next_item_size;
        let open_bonus = 20.0 * bad_fit * bad_fit
            + (if next_blocked { 15.0 } else { 0.0 })
            + 10.0 * scarcity * (1.0 - progress);
        score += 45.0 - open_bonus; // net penalty ~25..45 for opening new bins
    }

    // Mild global pressure to keep total bins low: prefer filling existing bins
    // as the stream progresses.
    score += 2.0 * (step_index as f64 / (total_items.max(1) as f64)) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: small post_residual is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill bonus
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it when the item would leave a very awkward residual everywhere.
    if bin_residual == bin_capacity {
        let awkward = (item_size as f64 / bin_capacity as f64) < 0.35;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += 40.0 * scarcity / (1.0 + open_bins_count as f64).ln().max(1.0);
        if awkward {
            score -= 10.0; // big item into fresh bin is fine
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0; // fresh bin can also host the next item
        }
    } else {
        // Lookahead: reward bins whose post_residual can host the next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0 + 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else if next_item_size > post_residual {
            score += 5.0; // dead space for the known next item
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if mean_residual > (item_size as f64) * 1.5 {
        score -= 5.0;
    }
    if open_bins_count > 4 && fit_ratio > 0.5 {
        score += 10.0 * fit_ratio; // discourage spreading across many bins
    }

    // Time horizon: early in stream, keep bins flexible (mild penalty for very tight fills
    // that leave unusable slivers); late in stream, prioritize closing bins out.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if t > 0.7 && post_residual < 10 {
        score -= 8.0 * t;
    }
    if t < 0.2 && post_residual > 0 && post_residual < 10 {
        score += 6.0 * (1.0 - t); // too early to make slivers
    }

    // Mild tie-break toward bins with residual close to the item (best-fit flavor).
    score += 0.1 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.35 * progress * norm_post + 0.15 * progress * progress);

    // Penalize large dead space quadratically as the stream matures
    score += 12.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= 8.0 * (1.0 - norm_post) * (1.0 - norm_post) * progress;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 5.0 * (1.0 - (next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 3.0 * ((next_item_size as f64) - post) / cap;
    }

    // Prefer spreading across bins when many are open with high mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - norm_post).abs();

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quantized into buckets.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Penalize small unusable residuals (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_f) / 10.0;
    }

    // Harmonic residue classes: residuals congruent to small values mod 10 are harder to fill.
    let residue = post_residual % 10;
    score += match residue {
        0 => -6.0,   // perfectly divisible residual, easy to pair
        1..=3 => 4.0,
        4..=6 => 0.0,
        _ => -2.0,
    };

    // Lookahead coupling: reward if next item exactly fits post_residual (perfect pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Fractional fit quality of lookahead
            let fit_q = next_item_size as f64 / post_f.max(1.0);
            score -= 15.0 * fit_q;
        } else {
            // next item can't use this residual: penalize proportionally to wasted potential
            score += 3.0;
        }
    } else {
        // Last item: any residual is pure waste; prefer minimal leftover.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins whose residual deviates below mean (tighter bins first).
    score -= 0.5 * (mean_residual - post_f);

    // Early in stream: keep bins open loosely; late: consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * frac;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = cap_f - item_size as f64;
        score = base + 12.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open new bin
        } else if fitting_bins_count == 1 {
            score += 20.0; // keep the last-chance open bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // fresh bin can host item + next
        }
    }

    // Slight preference for filling large residuals when many bins open.
    score += 0.05 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (min item size is 1, but tiny gaps attract small items wastefully).
    if post_residual > 0 {
        // Penalize any nonzero residual more than proportionally when small.
        if post_residual <= 10 {
            score += 30.0 * (11.0 - post_residual as f64);
        } else if post_residual <= 20 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make the empty bin attractive only when the current
    // item is large (a fresh bin gives it room) and open-bin pressure is low.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins unless justified.
        score += 35.0;
        // Large items benefit from a fresh bin.
        score -= 0.6 * item_size as f64;
        // Less penalty if many bins already open (amortizing) or few fitting bins.
        score -= 0.3 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Open-bins pressure: penalize contributing to bin sprawl when residuals
    // are already scattered.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins with residual close to the mean (keeps residuals uniform,
    // leaving larger coherent gaps elsewhere).
    score += 0.2 * ((bin_residual as f64 - mean_residual).abs());

    // Lookahead: if next item fits exactly in post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: leftover is dead space for the lookahead.
        score += 6.0;
    }

    // Late in the stream, consolidate: favor existing bins more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a mild non-linear penalty
    // on large dead space that is unlikely to be reusable.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly matches
    // the post_residual (perfect chaining), penalize near-misses.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nr {
            let gap = pr - nr;
            if gap == 0.0 {
                score -= 25.0; // perfect 2-step chain: item + next item fill bin
            } else {
                score -= 12.0 * (1.0 - gap / bin_capacity as f64);
                score += 0.15 * gap; // leftover after chain still penalized
            }
        } else {
            // next item cannot fit here; mild penalty proportional to overshoot
            score += 0.10 * (nr - pr);
        }
    }

    // Compare post_residual relative to mean residual across open bins:
    // leaving more than average residual is wasteful.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 6.0 * (1.0 - rel); // tighter than average: good
        } else {
            score += 4.0 * (rel - 1.0); // looser than average: bad
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.5 * open_bins_count as f64;

    // Early in the stream, be slightly more willing to open new bins
    // (keeps flexibility); late in the stream, pack tightly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: neutral-ish baseline so it only wins when open bins
    // would create large dead space or break a lookahead chain.
    if bin_residual == bin_capacity {
        score = 55.0
            + 0.10 * (post_residual as f64)
            - 0.25 * (mean_residual.min(100.0));
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 8.0; // next item likely needs fresh space anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space fraction
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Perfect or near-perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward leaving residual that can host the next item exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 { score -= 25.0; }
        } else {
            // leftover too small for next item: mild penalty proportional to deadness
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins with residual far below mean residual (more "filled" bins first)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild encouragement to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * waste_frac;

    // New-bin candidate: only attractive when current item fits poorly everywhere
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // opening new bin is good for large items or when no tight option exists
        if post_residual == 0 {
            score -= 60.0;
        } else if tightness > 0.5 {
            score -= 10.0 * tightness;
        } else {
            score += 15.0 + 20.0 * (1.0 - tightness);
        }
        // early in stream, opening bins is cheap; later, discourage fragmentation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = post / cap;

    // Base: prefer tight fits with smooth polynomial shaping of leftover space.
    let mut score = post
        + 24.0 * fit_frac * fit_frac
        - 6.0 * fit_frac * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual (chaining placements).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 8.0 + 10.0 * (1.0 - (nx / cap));
        } else {
            // penalize leaving residual slightly too small to be useful
            let gap = (nx - post_residual as f64) / cap;
            score += 6.0 * gap * (1.0 - gap);
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let pressure = mean_residual / cap;
        score = cap * 0.55
            + 20.0 * (1.0 - progress)
            - 15.0 * (pressure - 0.3).max(0.0)
            + if fitting_bins_count <= 1 { -25.0 } else { 0.0 };
    } else {
        // Mild penalty for spreading across many open bins vs consolidation
        score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_frac);
    }

    // Smooth stream-progress coupling: later in stream, tighten fits harder.
    score += 10.0 * progress * fit_frac * fit_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 35.0; // near-perfect fill
    } else {
        // Harmonic class penalty: dead space in coarse buckets.
        let cls = post_residual / 10; // 0..=9 harmonic class
        score += cls as f64 * 6.0;
        // Small residuals that no plausible item (>=1..100) can use are dead.
        // If next item can't fit in post_residual, this residual is likely wasted.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 12.0 + (post_residual as f64) * 0.25;
        } else if next_item_size > 0 {
            // Reward residuals that can host the lookahead item snugly.
            let lookahead_waste = post_residual as i64 - next_item_size as i64;
            if lookahead_waste == 0 {
                score -= 45.0;
            } else if lookahead_waste <= 10 {
                score -= 20.0;
            } else {
                score -= 4.0;
            }
        }
    }

    // Penalize leaving large residual in an otherwise empty-ish bin early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let frac_used = 1.0 - (post_residual as f64) / cap;
    score -= frac_used * 15.0 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (fresh empty bin): make it attractive only when
    // existing bins would leave bad dead space, otherwise mildly discouraged.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.6;
        // If current fit is poor (big post_residual waste), new bin looks better.
        let waste_now = bin_residual as f64 - item_size as f64;
        if waste_now > 40.0 {
            score -= (waste_now - 40.0) * 0.8;
        }
        // Early stream: more freedom to open bins.
        score -= (1.0 - progress) * 10.0;
        // Few open bins: opening is cheaper than scattering.
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        // Lookahead fits perfectly in fresh bin: encourage opening.
        if next_item_size > 0 && next_item_size <= bin_residual {
            let l_waste = bin_residual - next_item_size;
            if l_waste <= 10 {
                score -= 15.0;
            }
        }
    }

    // Slight preference to balance residuals toward the mean (avoid extremes).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fit — heavily reward.
        score -= 1000.0;
    } else {
        // Penalize unusable dead space relative to smallest possible item (size 1..100 unknown,
        // assume small items possible; treat gaps below 10 as near-dead).
        let dead = if post_residual < 10 { 10 - post_residual } else { 0 };
        score += (dead as f64) * 50.0;
    }

    // Reward tight fits: fraction of residual consumed.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Last chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.0 + progress) * 2.0;

    // New-bin candidate: only attractive when no open bin fits well
    // (bin_residual == bin_capacity) — make it costly unless residuals are all tiny.
    if bin_residual == bin_capacity {
        let pressure = if mean_residual < item_size as f64 { 0.0 } else { 120.0 };
        score += 150.0 + pressure + (open_bins_count as f64) * 5.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 15.0;
    }

    // Mild alignment with mean residual: prefer bins close to the average state.
    score -= (mean_residual - post_residual as f64).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (low post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(6);
    }

    // Dead-space penalty: residuals too small for the smallest item (size 1..=100 unknown, use conservative small threshold).
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    // 2-step lookahead: strongly favor leaving a gap exactly matching the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0; // perfect chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / (bin_capacity as f64)).powi(3); // next item still fits
        } else {
            // next item cannot fit in leftover: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
        }
    }

    // Favor bins whose residual is tight relative to the mean residual (compact bins first).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when open bins
    // are heavily fragmented (large mean residual spread) or stream is early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual / bin_capacity as f64).powi(2);
        score = bin_capacity as f64 - 40.0 * fragmentation + 30.0 * (1.0 - progress);
        // Never open a new bin when a perfect lookahead chain exists elsewhere:
        if next_item_size > 0 && next_item_size <= item_size {
            score += 10.0;
        }
    }

    // Mild preference to keep the number of open bins bounded early in the stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward if the next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating a sliver that cannot hold the next item.
        score += 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is discouraged unless the
    // current fit is poor or the bin would be nearly empty.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 55.0;
        // But if item is large relative to capacity, a fresh bin is fine.
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score -= 45.0 * large_item * large_item;
        // Later in the stream, be more willing to open new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If existing bins are fragmented (high mean residual but poor fit), allow new bin.
        if mean_residual > (bin_capacity as f64) * 0.5 && post_residual >= (bin_capacity as f64) * 0.5 {
            score -= 25.0;
        }
    } else {
        // Mild penalty for using bins with large residuals when a better fit
        // might exist elsewhere (preserve flexibility).
        let waste = (bin_residual as f64) - (item_size as f64);
        if waste > (bin_capacity as f64) * 0.6 {
            score += 8.0;
        }
        // Prefer filling bins that are already mostly full.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fill;
    }

    // Global pressure: with many open bins, favor consolidating into existing ones.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits, scaled by smooth progress coupling
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear reward for high fill ratio (waste avoidance)
    score -= 25.0 * fill * fill * (1.0 + progress);

    // Penalize dead space that is too small to matter (smooth cubic)
    let dead = if next_item_size > 0 && (next_item_size as f64) > pr {
        pr
    } else if next_item_size > 0 {
        pr - next_item_size as f64
    } else {
        0.0
    };
    score += 0.15 * dead * dead / cap;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when bin residual deviates from mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize slightly, but less as stream progresses
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 5.0;
    }

    // Lookahead synergy: reward if next item fits into resulting residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / pr));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals that can host common future items
    let usable = |r: u32| -> f64 {
        if r == 0 { return 0.0; }
        // residual classes: >=80 excellent, 50..79 good, 30..49 ok, <30 poor
        let r = r as f64;
        if r >= 80.0 { 3.0 } else if r >= 50.0 { 2.0 } else if r >= 30.0 { 1.0 } else { 0.0 }
    };

    // Reward leaving a residual that matches the next item (lookahead coupling)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * (next_item_size as f64);
        // exact match with next item
        if post_residual == next_item_size {
            score -= 300.0;
        }
    } else if next_item_size > 0 {
        // penalize dead space that cannot host next item
        score += 10.0;
    }

    // Reward bin-class preservation via modulo arithmetic on post_residual
    let pr = post_residual as i64;
    let class_bonus = match pr % 10 {
        0 => 15.0,               // round residual, highly reusable
        5 => 8.0,
        _ => ((pr % 10) as f64) * 0.3,
    };
    score -= class_bonus;

    // Fraction-of-capacity thresholds: keep bins whose residual is a "harmonic" fraction
    let frac = post_residual as f64 / bin_capacity as f64;
    if (frac * 4.0).fract() < 1e-9 || (frac * 2.0).fract() < 1e-9 {
        score -= 12.0; // residual at 1/4 or 1/2 capacity is valuable
    }

    // Penalize small unusable leftovers scaled by stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score += 5.0 + 10.0 * progress; // dead space matters more later
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening new bins unless current fit is terrible
    if bin_residual == bin_capacity {
        let base_penalty = 60.0;
        // open new bin more willingly early in stream / when many bins already open poorly
        let openness = (open_bins_count as f64).ln().max(0.0);
        score = base_penalty + openness * 5.0 + 40.0 * (1.0 - progress)
            - if post_residual == bin_capacity { 0.0 } else { 0.0 };
        // If next item is large and this bin would be near-full anyway, opening is fine
        if next_item_size >= 70 {
            score -= 10.0;
        }
    }

    // Prefer filling already-open bins relative to mean residual balance
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 5.0 / (1.0 + dev); // prefer bins near mean residual (balanced packing)
    }

    // Mild tie-break: prefer bins with larger residual used well
    score -= 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // If the next item could fit in the post-residual, reward keeping it usable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 {
        // penalize blocking the lookahead item
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure on number of open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 2.0;

    // Slightly favor bins with residual close to the item (tight fit).
    score += (bin_residual - item_size) as f64 * 0.5;

    // New-bin candidate: only attractive when no open bin fits well or few bins open.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0;
        } else if open_bins_count > 3 && mean_residual < item_size as f64 * 1.2 {
            score -= 10.0;
        } else {
            score += 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // good if next item fits with modest leftover
            score -= 80.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // post_residual too small for next item: dead space penalty
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare against mean residual: bins tighter than average are good targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening new bins when reasonable open bins exist.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 + 30.0 * (open_bins_count as f64).min(10.0) + 20.0 * progress;
        // but a new bin is fine for very large items with poor fits elsewhere
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash small post_residuals.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score -= 18.0 * (1.0 - pr / cap).powf(6.0);

    // Penalize dead space that is too small for typical items (1..100 unknown).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item cannot follow here; slight penalty for blocking.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer emptier bins when many bins are open (consolidate load).
    let fill_ratio = (bin_residual as f64) / cap;
    score -= 5.0 * fill_ratio * (open_bins_count as f64).ln().max(0.0);

    // Time horizon: early on, be exploratory (favor new bins less); later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fill_ratio;

    // Penalize bins far from the mean residual (avoid fragmentation).
    score += 3.0 * ((bin_residual as f64) - mean_residual).abs() / cap;

    // New-bin candidate: encourage opening a fresh bin early, discourage late.
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, larger residuals are tolerable; later, penalize them harder.
    let progress_weight = 0.5 + 1.5 * t * t;
    score += progress_weight * norm_pr * norm_pr * cap * 0.1;

    // Smooth quadratic shaping of residual: reward tight fits (small post_residual),
    // penalize mid-range dead space super-linearly.
    score -= 2.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + t);

    // Dead-space valley: smooth penalty peaked around mid residuals.
    let mid = norm_pr - 0.5;
    score += 3.0 * mid * mid * (1.0 - t);

    // Lookahead coupling: reward if next item fits smoothly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack_after_next = pr - nxt;
            score -= 1.5 * (1.0 - slack_after_next / cap) * (1.0 + 0.5 * t);
        } else {
            score += 0.8 * (nxt - pr) / cap * (1.0 + t);
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 + 2.0 * t);
    }

    // Crowding: mildly discourage adding to bins when many are open with high mean residual.
    score += 0.3 * open_bins_count as f64 * (mean_residual / cap) * t;

    // New-bin candidate: prefer opening a fresh bin when residuals of open bins are messy.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        // Favor new bin late in stream or when open-bin residuals are large and fragmented.
        let fragmentation = (mean_residual / cap - norm_pr).abs();
        score -= 2.0 * t * fragmentation;
        score += 1.0 * (1.0 - t) * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near "usable" sizes get rewards
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // modulo classes: residuals in {0..9} are dead space; 10..30 still useful
        let class = pr % 20;
        match class {
            0 => score -= 25.0,
            1..=9 => score += (10 - class) as f64 * 1.5, // penalize tiny unusable slivers
            10..=19 => score -= class as f64 * 0.4,      // moderately useful space
            _ => {}
        }
        // integer-division threshold: can next item fit?
        if next_item_size > 0 && next_item_size <= pr {
            let lookahead_gain = 30.0 + (pr - next_item_size) as f64 * 0.3;
            score -= lookahead_gain;
        } else if next_item_size > pr {
            score += 8.0; // this bin can't chain the lookahead
        }
    }

    // Tightness coupling: fraction of bin consumed by this item
    let fill = item_size as f64 / cap;
    score -= fill * 15.0;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }
    if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // opening new bins is cheap early, expensive late / when many open
        score = 55.0 + progress * 20.0 + open_bins_count as f64 * 4.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // fresh bin can absorb the next item too
        }
    }

    // mild drift toward consolidating residuals near mean
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64 * 1.0;

    // Dead-space avoidance: residuals too small for any plausible item (1..=100)
    // are pure waste. Penalize hard when post_residual is small but nonzero.
    if post_residual > 0 {
        // Fraction of capacity wasted; worst when post_residual < 10 (nothing fits).
        let dead = if post_residual < 10 {
            3.0 * (10.0 - post_residual as f64)
        } else {
            0.0
        };
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 15.0;
    }

    // Lookahead: if the next item fits into this bin's post_residual, reward
    // chaining placements; if not, penalize blocking the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.5 * (next_item_size as f64 / 100.0);
        } else {
            score += 1.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than opening new ones.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has high residual; only attractive
    // if existing bins would leave bad dead space. Give empty bin a mild penalty
    // so it's chosen only when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 2.0 + 0.5 * open_bins_count as f64;
    } else {
        // Prefer bins whose residual deviates favorably from the mean residual:
        // filling below-mean-residual bins tightens the spread.
        score -= 0.5 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Late in the stream, waste matters more (no future to amortize).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += 0.35 * (post_residual as f64).powf(1.4);

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: this bin becomes exactly reusable
        } else if post_residual >= next_item_size {
            // next item fits; the leftover after that is future dead space
            let after2 = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * after2;
        } else {
            // next item won't fit here; leftover is likely dead space
            score += 12.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: only current fit matters
        score -= 10.0;
    }

    // Penalize creating unusable slivers (< smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Relative to mean residual: prefer filling below-average-residual bins
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Progress: as stream advances, avoid opening new bins (consolidate)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 8.0 + 25.0 * progress;
    } else {
        score -= 4.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Lookahead: penalize if the next item cannot use the leftover space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item still fits: bonus proportional to how well it nests.
            score -= 6.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else if post_residual > 0 {
            // Dead space the next item cannot use: penalize small leftovers hard.
            let waste = post_residual as f64;
            score += 8.0 + 12.0 * (1.0 - waste / bin_capacity as f64);
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: slightly better than a bad fit, worse than a good one.
        score += 18.0 - 4.0 * (item_size as f64 / bin_capacity as f64);
        // Late in the stream, discourage proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global state coupling: if mean residual is high, prefer filling existing bins.
    score += 0.25 * (mean_residual - post_residual as f64).max(0.0);

    // Prefer bins whose residual is close to the item (exactness reward).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * norm_pr);

    // Smooth progress coupling: tighten tolerance as stream advances
    let tighten = 1.0 + 3.0 * progress * progress;
    score *= tighten;

    // Penalize dead space relative to mean residual of open bins
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // Last-chance bin: strongly reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead coupling: reward residual that can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 2.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 1.5 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class residuals by how reusable they are for typical item sizes (1..100).
        // A residual is "harmonic" if it is >= 10 (fits most small items) and
        // divisible by common item granularities (10, 20, 25, 50).
        let r = post_residual;
        if r >= 10 {
            if r % 10 == 0 {
                score -= 8.0;
            }
            if r % 20 == 0 {
                score -= 4.0;
            }
            if r % 25 == 0 {
                score -= 3.0;
            }
            if r % 50 == 0 {
                score -= 5.0;
            }
            // Large residuals are flexible; small residuals (< 10) are dead space.
            if r >= 50 {
                score -= 6.0;
            } else if r >= 30 {
                score -= 3.0;
            } else {
                // r in 10..30: moderately useful
                score -= 1.0;
            }
        } else {
            // Dead space: unusable for items >= 10.
            score += 15.0;
        }
    }

    // Lookahead coupling: reward if next item fits in post_residual (chain packing),
    // penalize if next item nearly fits (near-miss creates tempting dead space).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward for exact modular harmony between residual and next item.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else if next_item_size <= post_residual + 10 {
            // Near miss: mild penalty, this bin will become dead space soon.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when current
    // bins fit poorly. Empty bin has residual == capacity; make it mediocre by default
    // so good existing fits win, but competitive when all fits are bad.
    if bin_residual == bin_capacity {
        // Neutral-ish score for a fresh bin: its post_residual is full capacity.
        score -= 5.0;
        // Late in the stream, avoid proliferating bins with tiny leftovers.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 5.0;
        // If many bins are already open, discourage yet another.
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Prefer bins whose residual is already below the mean (consolidating fuller bins),
    // keeping emptier bins available for large future items.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference for bins with small residual overall (best-fit flavor),
    // modulated by harmonic class of the residual.
    let class_bonus = match bin_residual % 10 {
        0 => 2.0,
        5 => 1.0,
        _ => 0.0,
    };
    score += (bin_residual as f64) * 0.02 - class_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: prefer filling existing bins over opening new ones.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.3;
    }

    // Lookahead coupling: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Late-stream consolidation: tighten toward existing bins as stream ends.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tightest fit).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) accommodates the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            let slack = post_residual as f64 - next;
            // Reward matching: bigger reward when slack is small.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // Perfect chain match gets a big bonus.
            if slack < 1.0 {
                score -= 30.0;
            }
        } else {
            // Post-residual cannot host next item: penalize proportionally
            // to how much is wasted relative to next item.
            let deficit = next - post_residual as f64;
            score += 0.5 * deficit;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving more than average free space is wasteful.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        if pr > mean_residual {
            score += 0.3 * (pr - mean_residual);
        } else {
            score -= 0.2 * (mean_residual - pr);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so we only open a new bin when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the new bin would give a perfect 2-step chain, allow it.
        if next_item_size > 0 && (bin_capacity - item_size) as f64 >= next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Early in the stream, be more willing to open bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Many open bins: discourage spreading items; prefer tight fills.
    score += 0.05 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space is hard to fill later).
    if post_residual < 10 {
        score -= 18.0;
    } else if post_residual < 25 {
        score -= 6.0;
    }

    // Lookahead (k=2): reward bins whose leftover can host the next item,
    // penalize leftovers that just barely fail to host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 9.0;
    }

    // Late in the stream, prefer consolidating into bins with larger mean slack
    // so residual capacity stays usable.
    score += mean_residual * 0.04 * progress;

    // Penalize bins that would be left with awkward mid-range dead space.
    if post_residual > 40 && post_residual < 60 {
        score += 4.0;
    }

    // New-bin candidate baseline: its waste is capacity - item_size, which is
    // naturally large, but give it a lookahead bonus so it wins when the next
    // item can fill the fresh bin and no existing bin fits tightly.
    if is_new_bin {
        score = post_residual as f64 + 3.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: quadratic penalty on wasted residual (smooth, non-linear)
    let mut score = pr * pr / cap;

    // Reward high fill ratio with smooth coupling to stream progress
    score -= fill * fill * (1.0 + progress) * cap * 0.5;

    // Perfect-fit attraction: smooth bell around pr == 0
    score -= (-(pr * pr) / (2.0 * cap)).exp() * cap * 0.6;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (-(gap * gap) / (2.0 * cap * 0.25)).exp() * cap * 0.4;
        // Penalize leaving residual too small for next item (dead space)
        if pr < next_item_size as f64 {
            score += pr * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.8;
    }

    // New-bin candidate: neutral baseline, slightly penalized early, less late
    if bin_residual == bin_capacity {
        score += cap * (0.35 - 0.25 * progress) + open_bins_count as f64 * 2.0;
    }

    // Nudge toward bins near mean residual (balanced packing)
    score += (pr - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of post_residual: reward residuals that lie in "useful"
    // divisibility classes (multiples of 10 / 20 / 25 are easier to fill later).
    let pr = post_residual as u32;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 8.0; }
        // Dead-space penalty for small unusable slivers.
        if pr < 10 { score += 25.0 + (10 - pr) as f64 * 2.0; }
        else if pr < 20 { score += 8.0; }
    } else {
        // Perfect fill.
        score -= 40.0;
    }

    // Fractional fill of the bin: reward tight packing via capacity fractions.
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr { score -= 30.0; }
        else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 10.0 - (slack as f64).min(20.0) * 0.4;
            if slack % 10 == 0 { score -= 3.0; }
        } else {
            // Next item won't fit here; slight penalty scaled by overflow.
            score += ((next_item_size - pr) as f64).min(40.0) * 0.25;
        }
    }

    // Last-chance bin: strongly discourage opening a new bin when this is the
    // only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let bad_open = if next_item_size > 0 { mean_residual } else { mean_residual };
        if bad_open < item_size as f64 * 0.9 {
            score -= 10.0;
        } else {
            score += 15.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3 * (1.0 - fill);
    // Slight late-stream tightness preference.
    score -= 5.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium dead space (10..=20) is risky: few items can use it.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last chance: this is the only bin that fits -> strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 3.0 + 2.0 * pressure * (0.3 + progress);
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with open bins and progress.
        score += 20.0 + 6.0 * pressure;
        // But if the current bin would leave a bad gap and next item could use
        // a fresh bin, opening can win: discount when post_residual is small-but-dead.
        if post_residual > 0 && post_residual < 10 {
            score -= 15.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size as f64 > bin_capacity as f64 * 0.5 {
            score -= 10.0;
        }
    }

    // Lookahead synergy: if the post_residual exactly accommodates the next
    // item, this placement chains nicely.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    // If post_residual cannot fit the next item but is small, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 6.0;
    }

    // Mild preference for filling bins below mean residual (balancing).
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills remaining space.
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_gap / (bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize wasted residual that becomes dead space.
            score += 0.5 * post_residual as f64;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize bins whose residual deviates from the mean (fragmentation balancing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate: only attractive when current bins are badly fragmented
    // (high mean residual spread) or few bins fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / (bin_capacity as f64);
        score = 60.0 + 50.0 * fragmentation + 20.0 * progress;
        if fitting_bins_count <= 2 {
            score -= 30.0; // allow opening when options are scarce
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin pairs well with upcoming item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tight fit).
    let mut score = post;

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space relative to item size: small items leaving large holes are wasteful.
    let fill_ratio = item / cap;
    score -= 30.0 * fill_ratio;

    // Penalize post residual that no future item can plausibly use (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post).abs() < 0.5 {
            score -= 40.0;
        } else if nxt <= post {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        } else {
            // next item won't fit here: mild penalty proportional to leftover
            score += 5.0 * (post / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Opening cost, amortized by stream progress and current open bins.
        let mut open_cost = 35.0 + 3.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is cheaper (fewer future items to fill them).
        open_cost *= 1.0 - 0.5 * t;
        // If mean residual across open bins is large, prefer using open bins.
        open_cost += 0.3 * mean_residual.max(0.0);
        score += open_cost;
    } else {
        // Favor bins whose residual is close to item (relative tightness) among open bins.
        let waste = (bin_residual as f64 - item).max(0.0);
        score += 0.15 * waste;
        // Slight preference for fuller bins when many bins are open (consolidation).
        score -= 0.05 * (1.0 - bin_residual as f64 / cap) * (open_bins_count.min(20) as f64);
    }

    // Mean-residual steering: if this bin is below mean residual (fuller than average), prefer it.
    score += 0.1 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post residual with stream progress
    let t = progress;
    score += 18.0 * x * x * (1.0 - t) * (1.0 - t);
    score -= 12.0 * x * (1.0 - x) * t * (1.0 - t);

    // Penalize large dead space relative to mean residual state
    let dev = x - mean_residual / cap;
    score += 8.0 * dev * dev * (1.0 + t);

    // Lookahead: reward leaving space for the next item, penalize near-miss waste
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        score -= 10.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        if pr >= ns {
            score -= 6.0 * (1.0 - t);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * t);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * t);

    // Smooth bonus for tight fits
    let fill = item_size as f64 / cap;
    score -= 5.0 * fill * fill * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are heavily rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward near-zero post_residual (tight packing).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Modulo classes: post_residual divisible by common item sizes is "usable" space.
    for d in [10u32, 20, 25, 50].iter() {
        if post_residual > 0 && post_residual % d == 0 {
            score -= 8.0;
        }
    }

    // Dead space penalty: residuals too small for the minimum item (1..100 interface, use small floor).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 5.0 + 10.0 * (next_item_size as f64 / post as f64);
        } else {
            // next item won't fit here; penalize less if post_residual is still generally useful
            score += 4.0;
        }
    }

    // Fractional capacity logic: prefer bins whose fill is a "nice" fraction of capacity.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= 6.0 * (fill * std::f64::consts::PI).sin().abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 40.0;
        if post_residual as f64 > cap - item_size as f64 { score += 10.0; }
        // open new bin early when many bins already open and mean residual low (fragmentation)
        if mean_residual < cap * 0.2 && open_bins_count > 3 {
            score -= 20.0;
        }
    }

    // Mild preference to spread into emptier bins when many are open.
    score += 0.05 * (post_residual as f64 - mean_residual);

    // Stream progression: tighten packing as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Larger leftover space is more reusable; scale down mildly.
        score -= (post_residual as f64).sqrt() * 2.0;
    }

    // Reward tight fits relative to residual (small waste ratio).
    let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += waste_ratio * 40.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 5.0;
    } else {
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Prefer bins with residual below mean (consolidate small gaps).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + next_item_size as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post_residual is good.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // 2-step lookahead: reward if the next item fits exactly into the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use remaining space: penalize dead space
            let dead = (next_item_size - post_residual).min(post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Compare against mean residual across open bins: prefer bins with residual
    // close to the item (avoid fragmenting large-residual bins uselessly).
    let mean_r = mean_residual.max(1.0);
    let ratio = post_residual as f64 / mean_r;
    score += 10.0 * (ratio - 1.0).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * item_size as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0;
        }
    }

    // Slight preference to fill older bins as the stream progresses.
    score -= 0.01 * (step_index as f64 / total_items.max(1) as f64) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;

    // Core: penalize wasted space after placement, nonlinearly.
    let mut score = post * (1.0 + post / cap);

    // Reward tight fits (small post_residual relative to item size).
    score -= (item / (post + 1.0)) * 6.0;

    // Reward using bins that are already partially filled (keep big residuals for big items).
    let fill_ratio = (cap - residual) / cap;
    score -= fill_ratio * 8.0;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins -> this placement is cheap, mild bonus.
    if fitting_bins_count > 1 {
        score -= (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead: penalize leaving a residual that barely fits the next item poorly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            // Good: next item fits with modest slack.
            score -= 5.0 * (1.0 - slack / cap);
            if slack < 10.0 {
                score -= 4.0; // near-perfect two-item sequence
            }
        } else {
            // Next item won't fit here; mild penalty proportional to gap.
            score += (nxt - post).min(30.0) * 0.15;
        }
    }

    // Global state coupling: if mean residual is high, prefer consolidating into filled bins.
    let mean_gap = (mean_residual - post).abs();
    score -= 0.05 * mean_residual * fill_ratio;
    score += 0.03 * mean_gap;

    // Time horizon: late in the stream, be more aggressive about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post * progress * 0.3;

    // New-bin candidate logic: only attractive when item is huge (poor fit anywhere)
    // or no real alternative exists.
    if bin_residual == bin_capacity {
        let waste = post;
        // Penalize opening a new bin unless the item is large relative to capacity.
        let large_item_bonus = if item > 0.6 * cap { 30.0 } else { 0.0 };
        score += 12.0 + waste * 0.2 - large_item_bonus;
        // Early stream: opening bins is fine (build inventory of residuals).
        score -= (1.0 - progress) * 10.0;
        // Few open bins: opening is cheaper than fragmenting.
        if open_bins_count < 3 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += prn * prn * (30.0 + 70.0 * p2) * (1.0 - progress);
    score -= prn * (12.0 + 20.0 * p3);

    // Penalize dead space relative to mean residual of open bins.
    score += 0.25 * (pr - mean_residual).abs() * (0.5 + p2);

    // Reward tight fits strongly, smoothly via smoothstep-like term.
    let tightness = 1.0 - prn;
    score -= 25.0 * tightness * tightness * (1.0 + 2.0 * progress);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + 3.0 * progress);
    }

    // Lookahead: penalize leaving residual that neither wastes nor helps next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let gn = gap / cap;
        score += 10.0 * gn * gn * (1.0 + p2);
        // Reward residuals that exactly or nearly fit the next item.
        score -= 8.0 * (1.0 - gn) * (1.0 - gn) * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins early in the stream.
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // New-bin candidate: make it unattractive unless residuals everywhere are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction does the leftover land in?
    let post = post_residual as f64;
    let frac = post / cap; // 0..1
    let quarter = (post_residual % (bin_capacity / 4)).max(1) as f64;

    // Perfect-fit reward: dead space near zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Harmonic penalty: leftover in "dead zones" (just above half, or just above quarter)
    // is hard to fill with typical items (1..100).
    if post_residual > bin_capacity / 2 && post_residual < bin_capacity / 2 + 10 {
        score += 20.0;
    }
    if post_residual > bin_capacity / 4 && post_residual < bin_capacity / 4 + 8 {
        score += 10.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // harmonic class of the resulting leftover after the lookahead item
            if next_post == 0 {
                score -= 30.0;
            } else if next_post <= 10 {
                score -= 12.0;
            } else if next_post > bin_capacity / 2 {
                score += 8.0;
            }
        } else {
            // next item cannot fit here: leftover becomes final dead space
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin if current fit is terrible
    // and there is slack in the stream.
    if bin_residual == bin_capacity {
        // empty bin baseline: neutral-ish, penalize slightly so decent fits win
        score = cap * 0.55;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big item coming, fresh bin may help
        }
    }

    // Late-stream consolidation: favor filling existing bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;
    score += (open_bins_count as f64) * 0.05;

    // Mean-residual coupling: if open bins are already loose, tighten selection.
    score += (mean_residual - post).max(-30.0).min(30.0) * 0.1;

    // Fine-grained modulo tiebreak on post_residual classes.
    score += (post_residual % 3) as f64 * 0.3;
    score -= (frac * 10.0).floor() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate: mild penalty so it's only chosen when fits are bad,
    // but keep it competitive when all open bins would leave dead space.
    if bin_residual == bin_capacity {
        score -= 8.0;
        if post_residual < 20 {
            score += 0.0; // fresh bin leaves large residual, acceptable
        }
    }

    // Late in stream, tighten packing (less tolerance for waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.3 * progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's a good tight fit.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact matching of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match: strong reward.
        if diff == 0.0 {
            score -= 50.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item still fits after this placement: mild reward proportional to tightness.
            score -= 8.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Placement leaves a residual too small for the next item: penalize dead space.
            score += 12.0 + 0.25 * diff;
        }
    }

    // Tight-fit reward: small post_residual generally desirable.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * tightness * tightness;

    // Compare against mean residual of open bins: penalize bins already much emptier than average
    // (spreading load), reward bins that are tighter than average.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive when
    // no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0; // room for lookahead pairing in a fresh bin
        }
        // Later in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins: discourage adding another.
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mild reward for filling bins with many open bins active (consolidation pressure).
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: square the waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward bins whose leftover can still host the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    } else {
        // Last item: waste is final, penalize any leftover harder.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
        if post_residual <= 10 {
            score -= 6.0; // near-perfect fill in a last-chance bin
        }
    }

    // Penalize opening a brand-new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = open_bins_count as f64 * 0.5;
        score += 12.0 + open_penalty + progress * 4.0;
        // But if existing bins would leave big dead space, new bin becomes attractive.
        if fitting_bins_count > 0 {
            let avg_waste = mean_residual / (open_bins_count.max(1) as f64);
            if (post_residual as f64) < avg_waste * 0.5 {
                score -= 10.0;
            }
        }
    }

    // Mild preference for bins below mean residual (consolidate waste).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        } else {
            score += 0.5;
        }
    }

    // Reward exact fills.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items as f64;

    // Base: post residual, with smooth non-linear penalty on dead space
    let mut score = pr;

    // Polynomial coupling: penalize small-but-unusable residuals quadratically,
    // normalized by capacity so it's scale-free.
    let pr_norm = pr / cap;
    let dead = pr_norm * pr_norm * (1.0 - pr_norm) * cap;
    score += 0.8 * dead;

    // Reward tight fits (small post_residual) more aggressively as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= (0.5 + 1.5 * progress) * tightness * tightness * it;

    // Lookahead coupling: if the next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - gap * gap);
    } else if next_item_size > 0 {
        // next item cannot use this residual: mildly penalize hoarding space
        score += 0.3 * pr_norm * (1.0 + progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Mean residual interaction: if this bin's residual is far below mean, it's a good squeeze target
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.6 * dev * dev * dev.signum();

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that cannot hold small items (size <= 10)
    let dead = if post_residual < 10 && post_residual > 0 { 25.0 } else { 0.0 };
    score += dead;

    // Reward tight fits: post_residual near zero
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // post_residual too small for next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty when many bins are open and this fit is loose
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * (post_residual as f64 - mean_residual) * (1.0 - progress);

    // Modulo-class heuristic on residual: residuals in harmonic classes divisible by 10
    // are more reusable; penalize odd/prime-ish residuals
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.0;
    } else {
        score += 2.0;
    }

    // Slight preference to fill bins with less residual overall (best-fit core)
    score += 0.05 * (bin_residual as f64 - post_residual as f64) * -1.0;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64 * 0.5);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_useful = 10u32; // smallest plausible future item footprint
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * (1.0 - fit_ratio);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 2.0 * pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive if current bin would leave a bad gap
    // and lookahead item can use a fresh bin well.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual < min_useful { 70.0 } else { 0.0 };
        score += 30.0 + gap_penalty;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Mild stream-progression adaptation: later in stream, be more conservative.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual equals next item size -> reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits exactly into the post-residual region (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - 0.3 * slack;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space relative to its size.
        let dead = next_item_size as f64;
        score += 0.5 * dead.min(50.0);
    }

    // Reward tight fits (small post_residual) relative to item size.
    score -= 0.4 * (item_size as f64 / bin_capacity as f64) * 30.0;

    // Penalize creating residual far below mean residual (fragmentation).
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fit is very poor
    // (large post_residual) or no real alternative exists.
    if bin_residual == bin_capacity {
        score += 40.0;
        if post_residual >= item_size as f64 * 0.0 + 0.0 && fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Late in stream, opening fresh bins is riskier (wasted capacity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for bins with more residual used already.
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead space minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0 + (5 - post_residual) as f64 * 3.0;
    } else if post_residual >= 90 {
        // Barely used bin: wasteful placement.
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // Prefer leaving usable space for next item; penalize if gap is tiny.
            let gap = post_residual - next_item_size;
            score -= (gap as f64).min(20.0) * 0.8;
        } else {
            // Next item cannot fit in leftover: penalize proportionally to overflow.
            let over = next_item_size - post_residual;
            score += (over as f64).min(40.0) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Time horizon: late in stream, consolidate aggressively into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Favor bins whose residual is close to the mean (balance open bins),
    // penalize outliers relative to global state.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // When many bins are open, discourage spreading; prefer tight fits.
    if open_bins_count > 8 {
        score += (post_residual as f64) * 0.1 * ((open_bins_count as f64).ln());
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item or all residuals poor). Base penalty keeps it conservative.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 55.0 + poor_fits * (-70.0) + (item_size as f64) * 0.2 - progress * 5.0;
        // If item is huge, opening fresh is often better.
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins deeply (low post_residual); later, tolerate slack.
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits with a smooth quadratic bonus around zero residual.
    let tight = 1.0 - prn;
    score -= 8.0 * tight * tight * (0.5 + 0.5 * progress);

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > post_residual {
        // Dead space that the next item cannot use: penalize smoothly.
        score += 4.0 * prn * prn;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: open a new bin only when no good fit exists;
    // make the empty bin less attractive as progress advances.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 && pr >= 0.0 && item_size as f64 <= 0.5 * cap {
            score += 8.0;
        }
    }

    // Mild preference for bins with residuals near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes mod 10 and mod 25
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class25 = (pr % 25) as f64;

    // Penalize awkward residues (dead space unlikely to be filled by small items)
    if pr > 0 {
        score += (10.0 - class10) * 0.4;
        score += (25.0 - class25).abs() * 0.15;
    }

    // Perfect fit bonus
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 20.0; // tiny leftover, effectively filled
    } else if pr < item_size.min(20) {
        score -= 8.0; // leftover smaller than typical item: good compaction
    }

    // Harmonic fraction of bin fill: reward high fill ratios in steps
    let fill = (bin_capacity - post_residual) as f64 / cap;
    let harmonic = (fill * 4.0).floor() / 4.0; // quarter-class quantization
    score -= harmonic * 12.0;

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot class
            score += ((next_item_size - pr) % 20) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count <= 1 {
            score -= 70.0; // opening a new bin is fine when alternatives are bad
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin keeps options open for lookahead
        }
    }

    // Stream progression: late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - fill);

    // Mean residual coupling: when open bins are already loose, penalize adding more slack
    score += 0.25 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin size (best-fit sharpening).
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64);

    // Penalize bins that are much looser than average (avoid scattering).
    if bin_residual as f64 > mean_residual + 15.0 {
        score += (bin_residual as f64 - mean_residual) * 0.4;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 25.0 + 6.0 * open_bins_count as f64;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            score += 0.25 * post_residual as f64;
        }
    }

    // Early stream: be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin {
        score += (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits into the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 60.0 - 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here; penalize leaving awkward large gaps.
            score += 0.15 * (post_residual as f64 - (post_residual as f64 - next_item_size as f64).abs());
        }
    }

    // Relative-to-mean coupling: prefer bins whose post residual is below the mean residual
    // (compact packing), penalize bins that end up unusually empty.
    let post_f = post_residual as f64;
    score += 0.8 * (post_f - mean_residual).max(0.0);
    score -= 0.3 * (mean_residual - post_f).max(0.0);

    // Dead space penalty: gaps too small for any plausible item (items >= 1).
    if post_f > 0.0 && post_f < 10.0 {
        score += 40.0 - 4.0 * post_f;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer packing into open bins when fits are decent.
        score += 120.0;
        // Reward opening a new bin if no open bin fits well (large post residual everywhere).
        if mean_residual < item_size as f64 * 1.2 {
            score -= 100.0;
        }
        // Prefer new bins early in the stream when few bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * (1.0 - progress) * (1.0 - open_bins_count.min(10) as f64 / 10.0);
        // If next item is huge and current item is small, a fresh bin keeps flexibility.
        if next_item_size > 60 && item_size < 40 {
            score -= 80.0;
        }
    }

    // Mild tightness bonus: filling a bin close to capacity is good.
    score -= 0.2 * (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score quadratically as post_residual -> 0.
    let pr = post_residual as f64;
    score -= 40.0 * (1.0 - pr / bin_capacity as f64).powi(6);

    // Penalize "awkward" residuals that are too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.2 * next_item_size as f64;
    }
    // If next item would leave a very tight fit after this placement, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is expensive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let urgency = (fitting_bins_count == 0) as i32;
        // Penalize opening a new bin, more so early and when other bins fit.
        score += 45.0 + 30.0 * (1.0 - progress) - 20.0 * urgency as f64;
        // If the item is huge and nothing fits elsewhere, opening is fine.
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Reward using bins that are nearly full (few alternatives).
        let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * fill_ratio;
        // Last-chance bin: strongly favor using it to avoid waste.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Reward bins whose residual is close to the item (minimal waste).
        let waste = (bin_residual as f64 - item_size as f64).abs();
        score -= 12.0 * (1.0 - waste / bin_capacity as f64);
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling them.
    if open_bins_count > 0 {
        score -= 0.05 * mean_residual * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation: as stream ends, prefer closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (penalize large residuals mildly via quadratic term).
    // Late: residual waste matters more, so weight grows smoothly.
    let tightness = pr / cap; // in [0,1]
    let poly = tightness * tightness * (1.0 + 3.0 * progress) + 0.5 * tightness * (1.0 - progress);
    score += 20.0 * poly;

    // Lookahead: reward residual that can host the next item smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit = (pr - n).abs();
        let fit_frac = 1.0 - (fit / cap).min(1.0);
        score -= 8.0 * fit_frac * fit_frac * (1.0 - 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so when good alternatives exist.
    if bin_residual == bin_capacity {
        let alternatives = if fitting_bins_count > 1 { fitting_bins_count as f64 } else { 0.0 };
        let alt_factor = (1.0 + alternatives).ln();
        score += 30.0 * alt_factor + 10.0 * (mean_residual / cap).min(1.0);
    } else {
        // Reward bins whose residual is below the mean (consolidating waste).
        let dev = (mean_residual - pr) / cap;
        score -= 5.0 * dev;
    }

    // Mild pressure to keep the number of open bins low as stream progresses.
    score += 0.3 * open_bins_count as f64 * (0.2 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 classes.
    let post_class = post_residual % 10;
