    if post_residual > 0 {
        if post_class <= 5 && post_class >= 1 {
            score += (6 - post_class as f64) * 8.0; // small dead space penalized heavily
        } else if post_class == 0 {
            score -= 12.0; // perfectly aligned residual is reusable
        } else {
            score -= 3.0; // large classes (6..9) still fairly usable
        }
    } else {
        score -= 20.0; // perfect fit
    }

    // Fractional capacity logic: post_residual as fraction of capacity.
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.2 {
        score += 15.0; // sliver bins rarely reused
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item divides / complements residual well
            let gap = post_residual - next_item_size;
            score -= 10.0 + (gap % 10) as f64 * -0.5;
            if gap == 0 {
                score -= 15.0; // chain of perfect fits
            }
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: open a fresh bin only when fits are poor or stream is early.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // Prefer new bin when existing residuals are large (fits are wasteful) or few bins open.
        score = (item_size as f64) * 0.6 + (1.0 - pressure) * 40.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
        if post_class == 0 || (bin_capacity - item_size) % 10 == 0 {
            score -= 10.0; // opening aligned with harmonic classes
        }
    }

    // Mild consolidation pressure: fewer open bins is better when residual close to mean.
    score += (open_bins_count as f64).ln() * 1.5;

    // Stream progression: become more conservative (reuse) as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
