    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.2 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < 10 {
            // Tiny dead space that nothing (min size 1..100 stream) may use
            score += 5.0;
        }
        // Penalize creating residual just below next item (near-miss waste)
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_waste = if fitting_bins_count > 0 {
            (bin_residual as f64 - item_size as f64) - mean_residual
        } else {
            0.0
        };
        // Opening a bin is penalized; discount when many bins are open and mean residual is high (fragmented state)
        score += 35.0 - 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 * 1.5 {
            score -= 20.0; // fragmented state: fresh bin may be better
        }
        let _ = avg_waste;
    } else {
        // Reward reusing existing bins mildly, more so early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is far from mean residual (keeps variety of bin sizes)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space quadratically
    let mut score = post;
    score += 40.0 * pr * pr * cap;

    // Reward tight fits (small post residual) more aggressively late in stream
    let tightness = (1.0 - pr).powi(3);
    score -= 30.0 * tightness * (0.5 + 0.5 * progress);

    // Smooth coupling with mean residual: prefer bins whose residual deviates below mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * (1.0 - progress);

    // Penalize opening new bins early; allow late in stream
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (25.0 - 20.0 * progress) * (1.0 + (open_bins_count as f64).ln().max(0.0) * 0.1);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && new_bin == 0.0 {
        score -= 50.0;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let compat = if post >= nx {
            let slack = (post - nx) / cap;
            1.0 - 4.0 * slack * slack
        } else {
            -0.5 * (nx - post) / cap
        };
        score -= 12.0 * compat * (0.3 + 0.7 * progress);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: waste classes mod capacity quarters.
    let quarter = bin_capacity / 4;
    let class_penalty = match post_residual {
        0 => -40.0,                              // perfect fill
        r if r < quarter / 2 => -18.0,           // near-perfect
        r if r < quarter => -6.0,                // small leftover
        r if r < 2 * quarter => 0.0,             // medium leftover
        r if r < 3 * quarter => 8.0,             // large leftover
        _ => 14.0,                               // mostly empty after placement
    };
    score += class_penalty;

    // Pairing bonus: does next item fit snugly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // exact chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow here; penalize more if residual is large
            score += 0.08 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly reward using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., this call is the empty-bin call) and mean residual is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        let new_bin_cost = 20.0 + 4.0 * open_pressure * (1.0 - progress);
        let mean_fit = if next_item_size > 0 {
            (mean_residual - next_item_size as f64).abs()
        } else {
            mean_residual
        };
        score = post_residual as f64 + new_bin_cost + 0.1 * mean_fit;
        if fitting_bins_count == 1 {
            score += 60.0; // never prefer a new bin when a last-chance bin exists
        }
    }

    // Mild preference to fill already-open bins to reduce spread of residuals.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward tight fits (item fills a large fraction of residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 30.0 + 8.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced new bin
        }
        if fitting_bins_count == 1 {
            score -= 20.0; // last-chance bin exists; prefer it
        }
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item would exactly use this post_residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 10.0; // gap likely dead for the next item
    }

    // Open-bin count pressure: discourage scattering across many bins.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mild progression term: later in the stream, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Penalize bins whose residual deviates badly from mean (fragmentation).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 8.0 + 6.0 * (1.0 - pair_waste / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that the next item cannot use (dead space).
        score += 6.0;
        // Worse if residual is small enough to be near-worthless.
        if post_residual < 10 {
            score += 4.0;
        }
    }

    // Compare post-residual against mean residual of open bins:
    // leaving less-than-average residual is good (concentrating waste).
    let dev = (post_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placements
    // are all poor fits. Mild penalty, reduced late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 20.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            // Item won't fit anywhere anyway; opening a bin is natural.
            new_bin_penalty -= 25.0;
        }
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty - 5.0 * progress;
    }

    // Slight preference to fill bins with less residual overall (fewer open bins).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so wasted space is punished super-linearly.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: if the next item fits exactly into post_residual, strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Partial reward proportional to how well next item fills the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // Next item won't fit in the leftover: slight penalty if leftover becomes dead space.
            if post_residual < 10 {
                score -= 5.0; // small dead space is fine
            } else {
                score += (post_residual as f64) * 0.15;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when decent fits exist
    // or many bins are already open.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if the item is large and mean residual is small, opening a new bin is attractive.
        if item_size as f64 > mean_residual {
            score -= (item_size as f64 - mean_residual) * 0.8;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to the mean (balance across bins) mildly.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: smooth quadratic decay of post_residual, stronger later in stream
    let tight = (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= (1.0 - tight) * (20.0 + 30.0 * progress);

    // Lookahead coupling: reward if next item fits in post_residual (smooth)
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let fit_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 25.0 * fit_quality * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize leaving large unusable gap
        let gap = post_residual as f64 / bin_capacity as f64;
        score += 15.0 * gap * gap * (1.0 - progress);
    }

    // Last chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize bins with residual far from mean (imbalance), smoothly
    score += 0.1 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * open_bins_count as f64;

    // New-bin candidate: make it mildly attractive only when existing fits are poor
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let poor_fit = (post_residual as f64 / bin_capacity as f64).powi(2);
        score += 30.0 - 25.0 * poor_fit + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: post_residual divisible by 10 (harmonious leftover, easy to fill)
    // Class 1: post_residual in (0..10) tiny sliver (dead space)
    // Class 2: mid-range awkward leftover
    let pr = post_residual;
    let class = if pr == 0 { 0 }
        else if pr < 10 { 1 }
        else if pr % 10 == 0 { 0 }
        else if pr % 10 <= 4 { 2 }
        else { 3 };

    match class {
        0 => score -= 6.0,                    // perfect 10-multiple leftover: reward
        1 => score += 12.0,                   // sliver dead space: penalize
        2 => score += 3.0,                    // small awkward remainder
        _ => { score -= (pr / 20) as f64; }   // larger leftovers still somewhat usable
    }

    // Integer-division threshold coupling: does next_item_size fit the leftover?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits: reward, stronger when it exactly divides the leftover
            if pr % next_item_size == 0 { score -= 8.0; } else { score -= 3.0; }
        } else {
            // lookahead won't fit here: mild penalty scaled by overflow
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    } else {
        // last item: just fill anything, reward tight fits
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        // Opening a new bin is good when it leaves a clean large residual and
        // existing bins are crowded; penalize when open bins are plentiful/empty.
        score = 40.0 + poor_fit * 30.0 - (open_bins_count as f64) * 2.0
              - mean_residual * 0.3 + progress * 5.0;
        if item_size % 10 == 0 { score -= 4.0; } // round item sizes pack fresh bins well
    }

    // Slight preference for fuller bins overall (low residual = tight packing).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized
    if post_residual > 0 && pr < 10.0 {
        score += 40.0; // gap too small for any item (min size 1..100 stream, small slivers waste capacity)
    }
    // Gap that cannot hold the lookahead item is half-dead
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, mildly favor placements that leave large residuals
    // (keeps fragmentation concentrated rather than spreading it)
    score += 0.08 * open_bins_count as f64 * (pr / cap);

    // NEW-BIN CANDIDATE: brand-new empty bin recognized by bin_residual == bin_capacity.
    // Give it a calibrated moderate score: beats poor fits (large/dead post_residual in open bins),
    // but loses to tight fits (small post_residual).
    if bin_residual == bin_capacity {
        score = 42.0 + 0.6 * open_bins_count as f64;
        // A large item in a fresh bin leaves little dead space -> attractive
        score -= (cap - pr) * 0.35;
        // If nothing else fits (no fitting open bins besides new bin), opening is fine
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 50.0 / (post_residual as f64);
    }

    // 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + slack);
        } else {
            // next item won't fit; penalize leaving large unusable-looking gaps
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.2 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize so we prefer reusing open bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 120.0 + 0.5 * item_size as f64;
        // but allow opening new bin when few fitting bins and current fits are loose
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight preference to keep number of open bins low early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (0..1).
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Reward tight fits: penalize (subtract) when post_residual is small.
    // Non-linear coupling: waste below ~15 is heavily discouraged.
    if post_residual > 0 {
        let waste = post_residual as f64;
        score += 12.0 * (-waste / 15.0).exp(); // small residual -> big penalty added
    } else {
        score -= 20.0; // perfect fill
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item can still fit in the post-residual,
    // reward this bin (subtract); otherwise penalize dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 8.0 * (-chain_fit / 25.0).exp();
        } else {
            // Residual left over is dead space relative to next item.
            let dead = post_residual as f64;
            score += 4.0 * (dead / 40.0);
        }
    }

    // Prefer bins with residual far below the mean (nearly full bins),
    // keeping larger residuals available for future items.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Global load balancing: with many open bins, slightly favor filling
    // existing bins over opening new ones; relax late in the stream.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * open_pressure * (1.0 - 0.5 * progress);

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Make it attractive only when no good alternative exists:
    // penalize it by the item's fit quality so a tight fit elsewhere wins.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, or with many open bins, opening a new bin
        // becomes relatively cheaper.
        score -= 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let x = progress;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Penalize mid-range residuals that are hard to fill later (quadratic bump)
    score += 40.0 * pr_norm * (1.0 - pr_norm) * (0.3 + 0.7 * x);

    // Reward tight fits, more aggressively as stream progresses
    score -= (cap - pr) * (0.1 + 0.4 * x * x);

    // Lookahead: reward residual that can host the next item, penalize near-miss
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 8.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 6.0 * (n - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + x);
    }

    // New-bin candidate: keep it neutral-slightly-high early, cheaper late
    if bin_residual == bin_capacity {
        score = 0.5 * cap * (1.0 + 0.5 * x) - 10.0 * x * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Mean residual coupling: prefer bins deviating from mean when mean is large
    score += 0.3 * (pr - mean_residual).abs() * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Residuals in low classes (small leftovers)
    // are "sealed" bins -> reward them strongly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / cap * 4.0).floor(); // 0..3 harmonic class of leftover

    match class {
        0 => score -= 18.0,                 // nearly full bin: excellent seal
        1 => score -= 8.0,                  // usable for small items
        2 => score -= 2.0,                  // mediocre leftover
        _ => {}                             // large leftover: no reward
    }

    // Integer-division threshold on post_residual: leftover divisible into
    // common small-item sizes (mod arithmetic) is more reusable.
    if post_residual > 0 && (post_residual % 10 == 0) {
        score -= 3.0;
    }
    if post_residual > 0 && (post_residual % 5 == 0) {
        score -= 1.5;
    }
    // Dead space: leftover too small for the minimum item (1) is impossible
    // here, but leftovers below a plausible small-item size are semi-dead.
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here: mildly penalize large leftovers
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; penalize
    // opening a new bin when good open bins exist, but allow it when open
    // bins are crowded (mean residual low) or many bins already fit item.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(3.0);
        }
        // if open bins are nearly full on average, new bin is fine
        score -= (mean_residual / cap).max(0.0) * 20.0;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer tighter fits generally: relative waste penalty
    score += (pr / cap) * 6.0;

    // Small tie-breaker toward bins with below-average residual (denser bins)
    score += ((mean_residual - bin_residual as f64) / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: f64 = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward leaving residual that can accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0; // dead space relative to lookahead
        }
        // Bonus if residual exactly matches next item (perfect pairing).
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; prefer tight packing
    // (large item_size relative to residual) to consolidate.
    let pressure = open_bins_count as f64 / 10.0;
    score += pressure * (bin_residual as f64 - item_size as f64) * 0.15;

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 3.0;
        // If current bin is the only fitting one, opening new bin is bad.
        if fitting_bins_count >= 1 {
            score += 30.0;
        }
        // If lookahead is large, a fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild progress-based tightening: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Prefer bins whose residual is close to item size (tight fit).
    score -= (bin_residual as f64 - item_size as f64).max(0.0).recip() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly consumes the leftover
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain_slack / (bin_capacity as f64));
        } else {
            // Leftover too small for next item: penalize dead space
            score += 12.0;
            // Extra penalty if the dead space is "useless" (small but nonzero)
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // prefer leaving residuals near the mean (balanced bins) unless it's a tight fit
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good existing fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // But if the current bin would leave a bad residual vs next item, opening is better
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin guarantees full 100 residual for the future
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Mild penalty for many open bins: encourage consolidation
    score += 0.5 * open_bins_count as f64;

    // Slight preference for bins with larger residuals when fit is loose
    if post_residual > 40 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strong preference for tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize large dead space quadratically (unusable gaps)
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }
    // Near-perfect fit reward (dead space too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * (next_item_size as f64);
        } else {
            // Penalize leaving residual that wastes space relative to next item
            let waste = (next_item_size as f64 - post_residual as f64).min(bin_capacity as f64);
            score += 0.1 * waste;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }
    // Many alternatives: mild penalty to preserve diversity of bins
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate handling: opening a bin is expensive
    if bin_residual == bin_capacity {
        // Default: opening a new bin is worse than any reasonable fit
        score += 60.0 + open_bins_count as f64;
        // But if no existing bin fits well (large post residual everywhere),
        // opening a fresh bin becomes attractive
        if item_size as f64 > mean_residual + 10.0 {
            score -= 80.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins with less residual when many bins are open
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, with non-linear (quadratic/cubic) growth.
    let mut score = post + 0.8 * (post * post) / cap + 0.4 * (post * post * post) / (cap * cap);

    // Smooth coupling: leftover space is worse late in the stream.
    score += 1.5 * (post / cap) * progress * cap * 0.1;

    // Reward tight fits (small post_residual) with a smooth exponential bonus.
    score -= 12.0 * (-2.5 * post / cap).exp();

    // Penalize wasting a large residual on a small item (smooth ratio term).
    let fill = item_size as f64 / bin_residual as f64;
    score += 6.0 * (1.0 - fill) * (1.0 - fill);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let snug = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap);
        score -= 5.0 * snug;
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to gap.
        score += 2.0 * (next_item_size as f64 - post) / cap;
    }

    // Prefer consolidating into existing bins when many are open.
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate (empty bin): only attractive when the fit is poor
    // everywhere else — penalize opening a new bin smoothly.
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * progress - 0.5 * (item_size as f64 / cap) * cap * 0.1;
    }

    // Mild deviation from mean residual: prefer bins near the average fill state.
    score += 0.5 * (post - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty for large post_residual (dead space).
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Harmonic class of post_residual: residues that are "hard to fill" later
    // (small odd-ish residues) are penalized; residue 0 (perfect fit) rewarded.
    let r = post_residual;
    if r == 0 {
        score -= 30.0;
    } else {
        let class = (r % 10) as f64;
        // residues 1..9 mod 10 are awkward; smaller residue = worse unless 0
        score += (10.0 - class) * 0.6;
        // integer division thresholds: residue <= 10 is nearly unusable
        if r <= 10 {
            score += 12.0;
        } else if r <= 20 {
            score += 5.0;
        } else if r >= 40 {
            score -= 4.0; // roomy bin still useful
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let base_pen = 20.0;
        // If the current item leaves a residue the next item could use, prefer reuse.
        score += base_pen;
        if next_item_size > 0 && next_item_size <= r && r > 0 {
            score += 15.0; // an open bin can chain both items; keep new bin closed
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 20.0;
        } else if next_item_size < r {
            score -= 5.0 * (1.0 - (r - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; large leftover is more acceptable
            score += 3.0;
        }
    }

    // Late in stream: consolidate; avoid spreading across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64 - 4.0) * (0.5 + progress);
    }

    // Deviation from mean residual: prefer bins with residual close to item need
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
