            let dead = (next_item_size - post_residual) as f64;
            score += 0.15 * dead;
        }
    }

    // Compare post_residual against mean residual: leaving less than average is good.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit the item.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin may be fine.
        score -= 0.2 * item_size as f64;
    }

    // Early in stream: be more conservative about fragmenting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0 + (10 - post_residual) as f64;
    }

    // Penalize creating residuals that are too small to host typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space that the next item cannot use: penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.6;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: mild penalty to keep flexibility.
        score += (fitting_bins_count as f64 - 3.0).min(8.0);
    }

    // Prefer tighter bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: keep it attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 55.0 - crowding * 2.0 - progress * 10.0;
        // If the item fits poorly in crowded bins, make a new bin more tempting.
        if post_residual < 20 && fitting_bins_count <= 2 {
            score -= 25.0;
        }
    }

    // Mild time-horizon term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let r_norm = r / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: prefer small post-residual (tight fit), with non-linear sharpening
    let mut score = r_norm * r_norm * (1.0 + 2.0 * r_norm) * cap;

    // Polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (many items to come fill bins later);
    // late, dead space hurts more, so amplify high residuals quadratically.
    let progress_coupling = 1.0 + 3.0 * progress * progress;
    score += r_norm * r_norm * progress_coupling * 20.0;

    // Penalize residuals that are too small to ever hold a plausible item
    // (dead space), smoothly via sigmoid-like term centered at item_size.
    let dead = ((r - item_size as f64 * 0.5).max(0.0) / (item_size as f64 + 1.0)).exp() - 1.0;
    score += dead * 5.0;

    // Lookahead: reward residual that can host the next item (smooth match term)
    if next_item_size > 0 {
        let gap = (r - next_item_size as f64).abs();
        score -= (1.0 - gap / cap).max(0.0) * 8.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize by default, but relax as open bins grow
    // and mean residual is high (fragmented state -> fresh bin is attractive).
    let fragmentation = (mean_residual / cap - 0.5).max(0.0);
    score += is_new_bin * (25.0 - 30.0 * fragmentation * (open_bins_count as f64).ln().max(1.0));

    // Mild diversity bonus: many open bins -> prefer reusing fuller ones
    score -= (open_bins_count as f64).ln().max(0.0) * (cap - r) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
