        }
        // Modulo-10 harmonic classes: residues that are multiples of 10
        // (matching common size grids) are more reusable.
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        }
        // Integer-division thresholds: residue that can hold a mid item
        let holds_mid = post_residual / 25;
        score -= holds_mid as f64 * 5.0;
    }

    // Lookahead coupling: reward if next item fits the post-residue exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize wasting a tight residue
            if post_residual < next_item_size && post_residual < 30 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are used only when beneficial
        score = cap * 0.9;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Prefer a fresh bin if the item is large and open bins are fragmented
        if item_size as f64 > cap * 0.6 && mean_residual < cap * 0.35 {
            score -= 60.0;
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    } else {
        // Favor bins whose residual is close to item (tight fit)
        let tightness = 1.0 - (bin_residual - item_size).abs() as f64 / cap;
        score -= tightness * 15.0;
        // Prefer bins below mean residual (consolidate emptier space usage)
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // Mild preference to keep number of open bins in check
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1) are
    // worthless; residuals below the typical item floor are near-worthless.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is the best outcome
    } else {
        // Penalize small unusable gaps super-linearly (dead space archetype).
        if post_residual < 10 {
            score += 25.0 + (10 - post_residual) as f64 * 4.0;
        } else if post_residual < 20 {
            score += 8.0 + (20 - post_residual) as f64 * 1.5;
        }

        // Reward a residual that can still host the lookahead item (k=2 lookahead).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if the next item fills this bin nearly exactly after.
            let two_step = post_residual - next_item_size;
            if two_step < 10 {
                score -= 10.0;
            }
        } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
            // We block the lookahead item: penalize proportionally to how much we waste it.
            score += 6.0;
        }
    }

    // Tight fit reward relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when existing
    // bins would leave bad dead space or no bin fits well.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; add open-bin pressure so we don't spawn
        // bins frivolously when good fits exist.
        score = 55.0 + open_bins_count as f64 * 2.0;
        // If the item fits perfectly in a fresh bin, it's a great deal.
        if item_size == bin_capacity {
            score -= 100.0;
        }
        // Early in the stream, allow opening bins more liberally.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is close to what we consume (harmony term).
    score += ((bin_residual as f64 - item_size as f64) - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits relative to mean residual
    score += 0.3 * (post_residual as f64 - mean_residual);

    // 2-step lookahead: reward if next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fill bin exactly
        } else if next_item_size <= post_residual {
            // next item fits, reward proportional to how well it fills
            let fill_after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - fill_after_next / bin_capacity as f64);
        } else {
            // next item cannot use this bin's residual: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead.min(50.0);
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 15.0 + 0.4 * waste;
        // open new bin if no open bin fits at all
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in stream: tighten packing, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead coupling: bonus if next item can also fit in leftover space
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // dead space relative to the upcoming item
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 20.0;
        if open_bins_count > 0 {
            // early in stream, prefer consolidating into open bins
            score += 10.0 * (1.0 - progress);
        }
        // opening a fresh bin is more attractive when open bins are already full-ish
        score -= mean_residual * 0.1;
        if next_item_size > 0 && next_item_size >= item_size {
            // next item is big: a fresh bin keeps flexibility
            score -= 5.0;
        }
    }

    // Tight-fit preference: bins whose residual barely exceeds the item
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Prefer drawing down above-mean-residual bins (balance open bins)
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: wasted space, superlinearly penalized as bins fill up.
    let mut score = post * (1.0 + 1.5 * post / cap);

    // Smooth non-linear coupling of waste with stream progress:
    // late in the stream, waste becomes more costly.
    score += 40.0 * progress * (post / cap).powi(2) * cap;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = post / (item_size as f64 + 1.0);
    score -= 25.0 * (-fit_ratio).exp();

    // Dead-space penalty: residuals too small for typical items.
    let dead_threshold = 0.15 * cap;
    if post < dead_threshold {
        score += 30.0 * ((dead_threshold - post) / dead_threshold).powi(2);
    }

    // Lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (1.0 - (post - next_item_size as f64) / cap).abs();
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - progress);
    }

    // Last chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 + progress);
    }

    // Prefer bins with residuals near the mean (balance across bins),
    // smooth quadratic coupling.
    score += 0.5 * (post - mean_residual).powi(2) / cap;

    // Mild preference for fewer open bins early on.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 45.0 + 30.0 * progress - 10.0 * (post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item modulo capacity quantum (10)
    let quantum = bin_capacity / 10;
    let item_class = item_size % quantum;
    let post_class = post_residual % quantum;

    // Perfect fit: post_residual exactly a multiple of quantum
    if post_class == 0 {
        score -= 12.0;
    }

    // Dead space: post_residual tiny and not a harmonic class -> hard to fill
    if post_residual > 0 && post_residual < quantum {
        score += 8.0;
    }

    // Reward leaving room for the next item if it fits harmonically
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let combined_class = (item_size + next_item_size) % quantum;
            if combined_class == 0 {
                score -= 15.0; // two items fill bin to a harmonic boundary
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; penalize leaving awkward residue
            let gap = post_residual;
            if gap > 0 && next_item_size % quantum > gap % quantum {
                score += 4.0;
            }
        }
    }

    // Integer-division threshold: post_residual halves
    let half = bin_capacity / 2;
    if post_residual > half {
        score -= 2.0; // bin still broadly usable
    } else if post_residual <= quantum {
        score += 1.5; // nearly closed; fine unless perfect
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current residuals are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 / open_bins_count.max(1) as f64)).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if post_residual == bin_capacity {
            // base new-bin score: moderate; encourage consolidation early
            score = 45.0 - 10.0 * (1.0 - progress) + fragmentation;
            if fitting_bins_count == 0 {
                score -= 100.0; // no alternative
            }
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64;

    // Small tie-break toward tighter fits using capacity fraction
    score += (item_size as f64 / bin_capacity as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    // Penalize post_residual in the "unusable" band (0 < post_residual < 10) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64; // up to ~54 extra for gap of 1
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight-but-usable fits: small post_residual that is still >= 10.
    if post_residual >= 10 && post_residual <= 30 {
        score -= (30 - post_residual) as f64 * 0.8;
    }

    // Prefer bins whose residual was already small (compact bins first).
    score += (bin_residual as f64 - post_residual as f64) * 0.1;

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // unless the fit is excellent; when few bins are open, new bins are cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; exempt if this is the only option.
        if fitting_bins_count <= 1 {
            score -= 100.0; // last chance: must use this bin anyway
        } else {
            score += 15.0 + bin_pressure;
            // If no open bin would leave a usable gap, opening fresh is attractive.
            if post_residual >= 10 && post_residual < 20 {
                score -= 10.0;
            }
        }
    } else if fitting_bins_count == 1 {
        // This is the only open bin that fits: strong discount to avoid opening a bin.
        score -= 25.0;
    }

    // Lookahead: if the next item can exactly fill this bin's post_residual,
    // leaving that residual is great; if next item cannot use the gap, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            score += 10.0; // gap truly dead for the next item too
        }
    }

    // Mild preference for bins below the current mean residual (consolidating fullness).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fit of the current item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size well.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 >= nr {
            let lookahead_gap = post_residual as f64 - nr;
            // Perfect follow-up placement (post_residual == next_item_size) is ideal.
            score -= 25.0 * (1.0 - (lookahead_gap / bin_capacity as f64).min(1.0));
            // Bonus if next item exactly fills the bin afterwards.
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Next item cannot use this residual; penalize dead space relative to mean residual.
            score += 0.5 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Penalize large wasted residual vs mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: prefer keeping it closed early, allow opening late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose residual is fully consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Penalize dead space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Lookahead: if the next item can use this bin's post-residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 15.0; // tiny dead space anyway
        }
    }

    // New-bin candidate handling: opening a bin should be discouraged unless
    // no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_penalty = (open_bins_count as f64).sqrt() * 10.0;
        let mut nb = 45.0 + open_penalty - 20.0 * progress;
        if fitting_bins_count == 0 {
            nb -= 200.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            nb += 10.0; // last chance bin exists; mild preference to use it
        }
        // avoid opening when mean residual across open bins is large
        nb += mean_residual * 0.3;
        score += nb;
    } else {
        // Using an existing bin is generally good; extra reward when it's the only fit.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // Favor bins with residual below mean (consolidate emptier space elsewhere).
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space quadratically (dead space grows costly).
    let mut score = post + 0.9 * (post * post) / cap;

    // Reward tight fits: small post_residual relative to item size.
    let item = item_size as f64;
    let tightness = 1.0 - post / cap;
    score -= 2.5 * item * tightness * tightness;

    // Non-linear coupling with stream progress: later in the stream,
    // waste becomes more expensive (fewer chances to compensate).
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= 3.0 * prog_term * (cap - post);
    score += 2.0 * progress * post;

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the fleet mean (consolidate waste into few bins).
    let dev = (post - mean_residual) / cap;
    score += 1.5 * dev * dev.abs() * cap;

    // Lookahead: if the next item fits into post_residual, reward strongly;
    // if not, penalize leaving a residual that wastes capacity.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 4.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 1.2 * (post / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins
    // would leave large unusable residuals; discount slightly early stream.
    if bin_residual == bin_capacity {
        score = cap * 1.5 - 2.0 * progress * cap;
        if fitting_bins_count == 0 {
            score -= cap; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common
    // item-size increments (5, 10, 20) are more reusable later.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 6.0;
        if pr % 20 == 0 { score -= 3.0; }
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else {
        // Odd dead space is a liability.
        score += 4.0;
    }

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
            score -= 12.0;
        } else if next_item_size > pr {
            // Next item won't fit here; a tight-but-clean fill is still fine.
            score += 2.0;
        }
        // Integer-division threshold: if next item fits leaving >= 10 slack
        // in a class-aligned way, mildly reward.
        if next_item_size > 0 && pr / next_item_size >= 2 && pr % next_item_size == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless residuals
    // across open bins are already large (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open new bin only when existing bins are hopelessly fragmented
        // or the stream is nearly done.
        if fragmentation < 0.35 && progress < 0.9 {
            score += 25.0;
        } else {
            score += 5.0;
        }
        // Few open bins -> keep consolidating instead of opening.
        if open_bins_count <= 2 {
            score += 10.0;
        }
    }

    // Mild preference for bins with below-mean residual (tighter packing).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Waste ratio term: penalize leaving large unusable slack relative to item.
    if pr > 0 && pr < item_size {
        score += 3.0; // can't take next item likely, but small slack is ok
    }
    if pr >= 80 {
        score += 5.0; // huge leftover = poor packing choice
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.3;

    // Slight preference for bins below mean residual (tighter packing).
    score += (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when existing bins would create dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size is perfect.
    let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
    score -= 40.0 / (1.0 + gap);

    // Penalize post-residuals that are too small to ever hold any realistic item
    // (dead space below the minimum item size of 1 is fine, but small unusable
    // slivers relative to capacity are waste).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - progress);
    }

    // Compare against mean residual: placing into a bin with above-average
    // residual is cheap; draining a below-average bin is costly.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: give it a mild default penalty so it wins only when
    // no open bin offers a decent fit (its raw score is post_residual = capacity,
    // which is already high, plus the lookahead gap penalty usually large).
    if bin_residual == bin_capacity {
        score += 10.0 - 10.0 * progress;
        // If next item is large, an empty bin is valuable for the future.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Mild tie-break: prefer filling bins with less remaining space overall.
    score += 0.1 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted fraction nonlinearly.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill * fill;

    // Lookahead: if the next item fits into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            // Post residual that nothing (small items) can use is dead space.
            if post_residual < 10 {
                score -= 10.0; // perfectly sealed small gap is fine
            } else {
                score += 0.15 * (post_residual as f64 - next_item_size as f64).max(0.0);
            }
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize scattering across many open bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Time horizon: early on, be conservative about opening bins; late, tolerate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are too full on average.
        let avg_gap = mean_residual.max(0.0);
        score = 60.0 + avg_gap * 0.3 - 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.1 * next_item_size as f64;
        }
    } else {
        // Mild bonus for choosing emptier bins early (spreads load), tighter late.
        score -= (1.0 - progress) * 0.1 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear coupling of post_residual with progress (quadratic + cubic)
    let pr = post_residual as f64;
    score += pr * pr / (2.0 * bin_capacity as f64) * (0.5 + 0.5 * progress);
    score -= pr * pr * pr / (bin_capacity as f64 * bin_capacity as f64) * 0.3;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= tightness * tightness * 10.0 * (0.6 + 0.4 * progress);

    // Penalize bins whose residual deviates strongly from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * dev / (bin_capacity as f64) * 0.2;

    // Lookahead: reward if next item fits the post-residual (chain packing)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize leaving residual just below next item size (dead space)
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - pr / bin_capacity as f64);
    }

    // New-bin candidate handling: penalize opening a new bin, more so early
    // and when other bins can fit the item; allow it when fit is very poor.
    if bin_residual == bin_capacity {
        let base_penalty = 15.0 + 20.0 * (1.0 - progress);
        let fit_pressure = if fitting_bins_count > 0 {
            1.0 / (1.0 + fitting_bins_count as f64)
        } else {
            0.0
        };
        score += base_penalty * (0.4 + 0.6 * fit_pressure);
        // If item is large relative to capacity, opening a bin is more natural
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Mild penalty for too many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.3 * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residue: residues that are "useful"
    // for typical future items (multiples of small harmonics) are penalized less.
    let r = post_residual;
    let mut harmony_bonus = 0.0;
    if r > 0 {
        if r % 10 == 0 { harmony_bonus -= 6.0; }        // perfect decimal alignment
        else if r % 5 == 0 { harmony_bonus -= 3.0; }    // half-harmonic
        else if r % 2 == 0 { harmony_bonus -= 1.5; }    // even class
        if r >= 10 && r <= 20 { harmony_bonus -= 4.0; } // sweet-spot band for small items
    } else {
        harmony_bonus -= 20.0; // perfect fit: strongly favored
    }
    score += harmony_bonus;

    // Penalize residues that no plausible item (1..=80) can exploit well:
    // tiny dead space (<10) is unusable, mid residues are fine.
    if r > 0 && r < 10 {
        score += 12.0; // dead-space penalty
    }

    // Lookahead coupling: reward bins whose residue can host the next item.
    if next_item_size > 0 {
        if r >= next_item_size {
            score -= 5.0;
            // extra reward when the pair packs into a perfect decimal split
            if (item_size + next_item_size) % 10 == 0 && r == bin_capacity - item_size - next_item_size {
                score -= 8.0;
            }
        } else {
            score += 3.0; // this bin will be stranded after placement
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (virgin bin): must only win when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, seeding a bin is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If the open-bin landscape is fragmented, a fresh bin is more acceptable.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
        // If mean residual of open bins is small, opening a bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 5.0;
        }
    }

    // Mild pressure to keep the number of open bins low: prefer fuller bins.
    score -= (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // any future item (min item size ~1..100, treat < 12 as dead) are
    // heavily penalized; otherwise waste scales super-linearly.
    if post_residual < 12 {
        score += 40.0 + (12 - post_residual) as f64 * 6.0;
    } else {
        score += (post_residual as f64).powf(1.25) * 0.15;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: favor bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize spreading across many open bins,
    // but apply it most to the new-bin candidate so a new bin is only
    // opened when existing fits are poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 4.0 * (0.5 + 0.5 * progress);
        // Allow new bin when mean residual of open bins is very small.
        score -= (mean_residual - 5.0).max(0.0) * 0.8;
    } else {
        score -= 3.0;
        // Reward matching bins whose residual is close to mean residual
        // (keeps open bins balanced).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * (post_residual as f64 + 1.0).ln();

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Perfect chain: next item fits exactly -> strong reward.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // Next item cannot chain here; penalize leftover dead space scaled by gap.
            score += 8.0 * gap / bin_capacity as f64;
        }
    } else {
        // Last item: purely minimize waste.
        score -= 10.0 * fit_ratio;
    }

    // Compare against mean residual across open bins: bins below mean residual
    // are "tighter" than average; placing there consolidates fragmentation.
    let dev = mean_residual - post_residual as f64;
    score -= 5.0 * dev / bin_capacity as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes the residual of
    // every other open bin; penalize more when many bins are open and mean
    // residual is still large.
    if bin_residual == bin_capacity {
        let waste = mean_residual * open_bins_count as f64;
        score += 15.0 + waste / bin_capacity as f64 * 6.0;
        // But if nothing fits well elsewhere (this call is the only candidate),
        // the -25 above won't apply; give a mild discount late in the stream.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Slight preference early in the stream to keep bins balanced for future
    // lookahead chaining; late in stream, greediness dominates.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;

    // Base: prefer minimal post residual (tight fit), scaled mildly.
    let mut score = post * 1.0;

    // Strong quadratic penalty on unusable dead space: residuals that no
    // typical item (1..=100) can fill well are costly.
    if post_residual > 0 {
        let dead = 1.0 - post / cap;
        score += 12.0 * dead * dead * post / cap;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // Exact next-item match is very valuable.
            if post_residual == next_item_size {
                score -= 20.0;
            } else {
                let slack_after_next = (post_residual - next_item_size) as f64;
                score -= 8.0 * (1.0 - slack_after_next / cap);
            }
        } else {
            // Post residual cannot host next item: mild penalty proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * gap / cap;
        }
        // If this bin's current residual barely fits the item and next item
        // would not fit elsewhere well, encourage using it.
        let _ = nxt;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good fit exists; penalize new bins generally, more so late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin: score is its full residual minus discount when item is large.
        score = cap - item * 0.5 + 25.0 * (1.0 - progress);
        // If many bins already open and mean residual high, avoid new bin.
        score += (open_bins_count as f64).sqrt() * 3.0 + mean_residual * 0.3;
    } else {
        // Reusing an open bin reduces bin count; reward relative to global state.
        score -= 5.0 + mean_residual * 0.05;
    }

    // Prefer filling bins whose residual is close to item (relative tightness).
    let rel_tight = if resid > 0.0 { item / resid } else { 1.0 };
    score -= 6.0 * rel_tight;

    // Mild time-horizon term: early in stream, consolidation matters more;
    // late in stream, any fit is fine.
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear coupling: reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space: residual too small for any item (min size 1) — smooth barrier.
    let dead = ((20.0 - post_residual as f64) / 20.0).max(0.0);
    score += 15.0 * dead * dead;

    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly, less so early when consolidation matters less.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Discourage scattering across many open bins late in the stream.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10] is nearly unusable
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 30.0; // tiny sliver: heavy penalty
    } else if pr == 0 {
        score -= 50.0; // perfect fit reward
    } else {
        // coarser modulo classes: residuals divisible by common item sizes are reusable
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
    }

    // Lookahead: reward if next item fits the post residual (chain packing)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 5.0; // next item won't fit here; dead space likely
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // prefer new bin only when existing bins fit poorly
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) < 0.35 * bin_capacity as f64;
        if !poor_fit {
            score += 40.0; // discourage opening a bin when fit is decent
        } else {
            score += 10.0 - 10.0 * progress; // slightly cheaper to open early
        }
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (best-fit flavor)
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Slight preference for fuller bins overall
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 2.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // next item fits; reward proportional to how snugly
            let gap = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here; mild penalty for wasting space
            score += 25.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare post_residual to mean residual: avoid making bins much emptier than average
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when item is large relative to capacity
    // (opening a fresh bin for a big item leaves a useful large residual).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 150.0 * (fill_ratio - 0.7) / 0.3;
        } else {
            score += 120.0 * (0.7 - fill_ratio);
        }
        // discourage hoarding many open bins early on
        score += open_bins_count as f64 * 5.0;
    }

    // Slight preference for bins that are already partially filled (reduce bin count pressure).
    let filled = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= filled * 30.0;

    // Mild stream-position adaptation: later in the stream, be more aggressive about closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving small, hard-to-use dead space (1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward if the next item fits the post-residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 35.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to the known next item.
        score += 8.0 * (post_residual as f64 / 100.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are crowded
    // or residuals are large relative to the item.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let waste = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        score += 45.0 - 20.0 * crowding - 15.0 * waste;
        // If no open bin fits, opening is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Time horizon: mildly more aggressive bin reuse early, conservation late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (mean_residual / bin_capacity as f64 - 0.5);

    // Prefer bins whose residual is close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals are more valuable (tight packing).
    let progress_coupling = norm_pr * (1.0 + progress) + norm_pr * norm_pr * (1.0 - progress) * 2.0;
    score += progress_coupling * cap * 0.25;

    // Penalize residuals that are far from the mean residual (fragmentation),
    // with strength that grows smoothly over the stream.
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * (100.0 + 400.0 * progress);

    // Reward last-chance bins (only fitting bin) with smooth sigmoid-like gate.
    if fitting_bins_count == 1 {
        score -= 60.0 + 80.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_ratio = next_item_size as f64 / pr;
        score -= 30.0 * fit_ratio * (1.0 - 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins late in stream.
    score += (open_bins_count as f64).ln().max(0.0) * progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 5000.0;
    } else if post_residual < 10 {
        // Near-perfect fit: tiny unusable sliver is fine, reward proportionally.
        score -= 800.0 + (10 - post_residual) as f64 * 30.0;
    }

    // Dead-space penalty: gap that cannot even hold the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    }
    // Reward bins whose leftover can host the next item (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow and stream progresses,
        // so new bins only win when all open fits would be terrible.
        score += 80.0 + 20.0 * open_bins_count as f64 + 50.0 * progress;
    } else {
        // Mild pressure to consolidate into already-open bins.
        score -= 4.0 * open_bins_count as f64;
        // Prefer bins tighter than the fleet average (best-fit flavor).
        score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (post_residual == 0).
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward proportional to tightness.
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual as f64);
        } else {
            // Next item will NOT fit in this bin's leftover: penalize large leftovers
            // that are too small for the next item (dead space risk).
            score += 12.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Reward tight fits relative to bin capacity.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (item_size as f64 / bin_capacity as f64);

    // Penalize leaving residuals far below the mean residual (fragmentation risk),
    // unless it's a perfect fit (already rewarded).
    if post_residual > 0 {
        let diff = mean_residual - post_residual as f64;
        if diff > 0.0 {
            score += 0.25 * diff;
        } else {
            score += 0.10 * diff.abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so if many bins are open
    // or we are late in the stream; relax when the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 10.0 * progress + 2.0 * open_bins_count as f64;
        // If item is very large and mean residual is small, opening a new bin is less bad.
        if item_size as f64 > 0.7 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward low post_residual non-linearly
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize residuals that are too small to be useful for future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Prefer filling already-open bins when many are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Penalize bins far from mean residual (avoid fragmentation outliers)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: make empty bin attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit = if bin_residual >= item_size { (bin_residual - item_size) as f64 } else { 0.0 };
        score = 35.0 + 0.8 * poor_fit + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    let mut score = post * (1.0 + 0.9 * post / cap);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, small dead space is penalized more aggressively.
    let p = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * p * (post / cap) * (post / cap);

    // Reward filling bins that are already substantially consumed.
    let fill = 1.0 - residual / cap;
    score -= 8.0 * fill * fill * (1.0 - post / cap);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * (item / cap);
    }

    // Many open bins: discourage spreading, favor consolidating into existing bins.
    score += 0.35 * open_bins_count as f64 * (post / cap);

    // Compare against mean residual: bins far below mean waste capacity.
    let dev = (residual - mean_residual) / cap;
    score += 4.0 * dev * dev.abs();

    // Lookahead (k=2): if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            // Penalize leaving a residual that is just barely too small for the next item.
            let gap = (post - nxt).abs();
            if gap < 10.0 {
                score += 5.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // New-bin candidate: neutral baseline; only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let new_bin_base = cap * (1.0 + 0.9) + 12.0 * p + 0.35 * open_bins_count as f64;
        // A new bin is better than a poor fit if the best existing fit would leave
        // large dead space; approximate via item size relative to capacity.
        let poor_fit_pressure = 15.0 * (1.0 - item / cap) * p;
        return new_bin_base - poor_fit_pressure + 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes modulo common item sizes
    let pr = post_residual;
    let pr_mod_10 = (pr % 10) as f64;
    let pr_mod_20 = (pr % 20) as f64;

    // Reward residuals that lie in "usable" harmonic classes (multiples of 10/20),
    // which future items (sizes 1..100, often multiples of 5/10) can fill exactly.
    if pr == 0 {
        score -= 50.0; // perfect fit
    } else {
        score -= (10.0 - pr_mod_10) * 0.8;      // closeness to multiple of 10
        score -= (20.0 - pr_mod_20) * 0.3;      // closeness to multiple of 20
        // Penalize tiny dead space (< 10) that is hard to fill
        if pr < 10 {
            score += 25.0;
        }
        // Penalize mid-range awkward residuals (11..=19 class)
        if pr >= 11 && pr <= 19 {
            score += 8.0;
        }
    }

    // Lookahead coupling: if the next item fits the post residual exactly or nearly,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder: mild penalty scaled by gap
            score += ((next_item_size - pr) as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has high raw residual; make it attractive
    // only when current bin fits are poor (large post_residual relative to capacity)
    // or many bins are already open with small mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = (post_residual as f64 / bin_capacity as f64) > 0.35;
        let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
        if poor_fits || crowded {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 20.0; // prefer filling existing bins early
        }
    }

    // Prefer bins whose residual is below the mean residual (tighter packing),
    // with a mild non-linear coupling.
    let res_f = bin_residual as f64;
    score += 0.15 * (res_f - mean_residual).max(0.0);
    score -= 0.05 * (mean_residual - res_f).max(0.0);

    // Integer-division threshold: bins with residual in [item_size, item_size+9]
    // are near-perfect fits; reward crossing into that band.
    if bin_residual >= item_size && (bin_residual - item_size) < 10 {
        score -= 12.0;
    }

    // Slight preference for fewer open bins (bin consolidation).
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize opening a new bin when existing bins fit.
    if bin_residual == bin_capacity {
        score += 40.0 + 8.0 * open_bins_count as f64;
        // But allow new bin if all fits would leave big dead space
        if post_residual > 40.0 { score -= 30.0; }
    } else {
        // Reward tight fits
        score -= (item_size as f64 / bin_residual as f64) * 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: favor leaving residual that can fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Mild early-stream preference for keeping bins openable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness: fraction of bin wasted after placement.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 60.0 * waste * waste;
    }

    // Aggressive 2-step lookahead: reward bins where the next item fits
    // into the post-residual (chained packing), penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.35 * slack;
            // Bonus if next item fits exactly afterwards (3-step chain).
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Next item cannot use this residual; penalize proportionally
            // to how much of the next item is "uncovered".
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving a residual near the mean keeps flexibility.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening a brand-new empty bin unless the item is large
    // relative to remaining capacity or current bins are quite full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // New bin is attractive for big items or when few fitting bins exist.
        let new_bin_bonus = 150.0 * item_frac - 20.0 * openness.sqrt() - 40.0 * (1.0 - progress);
        score += 60.0 - new_bin_bonus;
        // If next item is small, an open bin's residual likely serves it fine.
        if next_item_size > 0 && next_item_size <= mean_residual as u32 {
            score += 25.0;
        }
    }

    // Mild pressure to fill existing bins as the stream progresses.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Dead space penalty: large post_residual relative to capacity is waste,
    // especially when it can never be used by typical items.
    let waste = post_residual as f64 / bin_capacity as f64;
    if waste > 0.0 {
        score += 18.0 * waste * waste;
    }

    // Lookahead: if the next item fits exactly or well in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * next_fit;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use leftover space: penalize proportional to waste.
        score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // open bins have large residuals (poor fits everywhere) or few bins exist.
    if bin_residual == bin_capacity {
        let mean_waste = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Default penalty for opening new bins.
        let mut new_bin_score = 25.0 + 20.0 * progress;
        // If existing residuals are large, a new bin becomes more attractive.
        new_bin_score -= 30.0 * mean_waste;
        // Few open bins -> opening is cheaper.
        new_bin_score -= 2.0 * open_bins_count as f64;
        // If item is small, a new bin wastes lots of space; penalize more.
        new_bin_score += 20.0 * (1.0 - fill_ratio);
        score = score.min(new_bin_score) * 0.5 + new_bin_score * 0.5;
        return score;
    }

    // Reward using bins whose residual is close to the item (best-fit style).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 8.0 * (1.0 - tightness);

    // Late in the stream, prefer consolidating into few bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.7 {
        score -= 5.0 * progress * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling: penalize residual more heavily as stream progresses
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score *= 1.0 + 0.35 * p2 + 0.55 * p3;

    // Reward tight fits (small post_residual) with a smooth quadratic term
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let tight = 1.0 - (pr / cap);
    score -= 12.0 * tight * tight * (1.0 + 0.5 * progress);

    // Lookahead coupling: if next item fits into post_residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_ratio = (next_item_size as f64) / cap;
        score -= 6.0 * fit_ratio * (1.0 + 0.8 * progress);
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Penalize deviation from mean residual (smooth dispersion penalty)
    let dev = (pr - mean_residual).abs();
    score += 0.08 * dev * (0.5 + progress);

    // Mild penalty for proliferating open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // Harmonic class of post_residual: dead space classes that are hard to fill
    // Residuals < 10 are effectively dead; residuals in [10, 80] can still host items.
    if post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward if next item fits exactly / fits well into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fit_ratio;
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 5.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins are tight
    if bin_residual == bin_capacity {
        // neutral-ish base; penalize opening new bins when plenty of open bins have room
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
        if mean_residual > item_size as f64 * 2.0 {
            score += 10.0; // plenty of slack elsewhere: discourage new bin
        }
    }

    // Small tie-breaker toward bins with low residual relative to mean
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (1..100 stream, but small gaps < 10 are nearly dead)
    // are heavily penalized, with a super-linear ramp.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Mild super-linear penalty on larger leftovers.
        let r = post_residual as f64;
        score += 0.004 * r * r;
    }

    // Reward residuals that still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 15.0; // kills usability for the next item
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading
    // into new bins / half-empty bins; encourage tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 2.0 + 6.0 * progress;
    score += pressure * (open_bins_count as f64).sqrt();

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 0.5 * post_residual as f64;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // open-bin set is empty. Penalize opening new bins as pressure rises.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count == 0 { 0.0 } else { 25.0 + 3.0 * open_bins_count as f64 };
        score += open_pressure;
        // A new bin is more tolerable early in the stream.
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps residuals balanced and predictable).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well next item uses the leftover.
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * usage;
        } else {
            // Next item cannot use this residual; penalize wasted space.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
