    // Compare post_residual relative to mean residual: prefer bins whose
    // remaining space stays closer to the average (avoid fragmenting).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize new-bin candidate mildly unless residual is huge relative to item.
    if bin_residual == bin_capacity {
        let openness = 1.0 - (step_index as f64 / total_items.max(1) as f64);
        score += 80.0 - 40.0 * openness;
        // Opening a new bin is good if no existing bin fits well.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Prefer denser bins (smaller residual before placement).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly (non-linear).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space relative to capacity, non-linearly.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a bin; reduced when many items remain.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 - 10.0 * (1.0 - progress);
        // If the next item is small, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
        // If mean residual is already large, prefer reusing existing bins.
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
    } else {
        // Reward reusing bins whose residual matches the next item size.
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            let slack = (post_residual as f64 - next_item_size as f64).abs();
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        }
        // Penalize bins that are outliers from the mean residual (fragmentation control).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = (1.0 + progress) * prn * prn * cap;
    score += coupling * 0.5;

    // Reward tight fits (small post_residual) more strongly late in the stream
    let tightness = (1.0 - prn).powi(3);
    score -= tightness * item_size as f64 * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += (next_item_size as f64 - pr) * (1.0 + progress);
    }

    // Reward bins whose post_residual still accommodates the lookahead item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 3.0 + 2.0 * progress;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Mild penalty relative to mean residual: avoid wasting well-filled bins
    score += (mean_residual - pr).max(0.0) * 0.15;

    // New-bin candidate: keep it neutral-to-slightly-high so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets (capacity fractions)
    let post_class = post_residual % 10;
    let cap_frac = (post_residual as f64) / (bin_capacity as f64);

    // Reward small post_residuals (tight fits), extra reward for exact fit
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic penalty: dead space in awkward classes (1..=9 mod 10)
        score += match post_class {
            0 => -20.0,                    // clean multiple of 10: usable
            1..=4 => 15.0 + 5.0 * post_class as f64, // tiny slivers
            5 => 5.0,                      // half-class
            _ => -5.0 + post_class as f64, // 6..9 moderately usable
        };
        // Non-linear tightness reward
        score -= 30.0 * (1.0 - cap_frac).powi(3);
    }

    // Harmonic pairing: does next item divide into post_residual cleanly?
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_class = next_item_size % 10;
        let pair_fit = (post_residual % next_item_size.max(1) == 0) as f64;
        score -= 25.0 + 10.0 * pair_fit + next_class as f64;
        // Reward if next item nearly fills remaining space
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: penalize leaving stranded space
        score += 10.0 + 0.2 * post_residual as f64;
    }

    // Integer division threshold on item_size (harmonic size classes)
    let item_class = item_size / 10;
    match item_class {
        8..=10 => score -= 10.0, // large items: place greedily
        1..=2 => score += 5.0,   // tiny items: prefer them in leftovers later
        _ => {}
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate logic: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        // Opening a new bin is good when existing bins have low mean residual
        score = 45.0 - 30.0 * mean_frac + 2.0 * crowd.sqrt();
        if fitting_bins_count == 0 {
            score -= 200.0; // must open new bin
        }
        if post_residual >= 20 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin pairs well with next item
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - cap_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual is "dead" if it's too small for the minimum plausible item (1..100 range).
    // Treat residuals < 10 as fully dead, and weight the deadness sharply.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty on small-but-not-dead residuals that few items could use.
    if post_residual > 0 && post_residual < 25 {
        score += 8.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 / (1.0 + tightness);

    // Open bins pressure: penalize using bins when many are open, to consolidate load.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how poorly open bins fit.
        score += 15.0 + 0.3 * mean_residual;
        // If lookahead item can pair with this item in a fresh bin, soften the cost.
        if next_item_size > 0 && (next_item_size as u32).saturating_add(item_size) <= bin_capacity {
            score -= 10.0;
        }
    }

    // Lookahead pairing: reward leaving a residual that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Early in the stream, be slightly more willing to open bins (build good structure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

