            // Next item won't fit here: penalize residual that is too small to be useful
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += waste * 60.0;
        }
    }

    // Compare post_residual against mean residual: avoid leaving bins far below average
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive if no good fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
        // If many bins can fit the item, discourage opening a new one
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 30.0;
        }
    }

    // Early stream: slightly favor consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Mild penalty proportional to tightness of fit creating dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // small unusable slivers are dead space
    }

