}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream [0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize creating dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }
    if post_residual >= 10 && post_residual < 20 {
        score -= 3.0; // still usable for small items
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size <= bin_residual && next_item_size > item_size {
            // placing here would break a chain-fit for the next item
            score += 5.0;
        }
    }

    // Global state coupling: many open bins with large mean residual -> consolidate.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.05 * (open_bins_count as f64) * (consolidation / 10.0);
        // Encourage filling bins below mean residual (larger residual bins get priority)
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // New-bin candidate handling: bin_residual == bin_capacity means brand-new bin.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 20.0 + 10.0 * progress;
        // If no existing bin fits (this call is the only candidate), reduce penalty.
        if fitting_bins_count == 0 {
            new_bin_penalty -= 30.0;
        }
        // If the item is large, a fresh bin is fine (good long-term residual).
        if item_size >= bin_capacity / 2 {
            new_bin_penalty -= 8.0;
        }
        // Early in stream, be more willing to open bins (diversification).
        new_bin_penalty -= 10.0 * (1.0 - progress);
        score += new_bin_penalty.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (low post_residual). Late: tolerate larger residuals
    // to keep flexible bins open for future items.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = 1.0 + 0.6 * p2 + 0.4 * p3;
    score += 18.0 * coupling * norm_pr * norm_pr;

    // Dead-space penalty: residuals too small to hold typical items are worthless,
    // smoothly scaled by a logistic-like term in normalized residual.
    let dead = (norm_pr - 0.15) / 0.08;
    let dead_weight = 1.0 / (1.0 + (-dead).exp());
    score += 25.0 * dead_weight * (1.0 - progress);

    // Exact fit reward via smooth exponential of post_residual.
    score -= 20.0 * (-norm_pr * 8.0).exp();

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward leaving residual that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = ((pr - nx) / cap).min(1.0);
            score -= 12.0 * (1.0 - slack * slack) * (1.0 - progress);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Mean-residual deviation: penalize bins far from the fleet mean to
    // balance residual distribution smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Mild penalty for proliferating open bins late in the stream.
    score += 0.5 * (open_bins_count as f64).ln() * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize slightly unless current bin fit is poor,
    // decided smoothly by normalized post_residual.
    if bin_residual == bin_capacity {
        score += 15.0 - 30.0 * norm_pr.max(0.0).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is leftover space
    // in coarse quantum bands (capacity / 8). Small classes = tight fit.
    let quantum = bin_capacity / 8;
    let harmonic_class = post_residual / quantum;

    // Reward tight fits strongly (non-linearly)
    match harmonic_class {
        0 => score -= 40.0,               // near-perfect fit
        1 => score -= 25.0,               // very good
        2 => score -= 12.0,               // decent
        3 => score -= 5.0,                // okay
        _ => {
            // Large leftover: penalize unless bin is nearly empty anyway
            score += 8.0 * (harmonic_class as f64 - 3.0);
        }
    }

    // Perfect divisibility bonus: post_residual divisible by 8 or 10
    // leaves room that future 8/10-multiples can fill exactly.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 8 == 0) {
        score -= 10.0;
    }
    // Odd dead space (prime-ish leftovers) is hard to fill
    if post_residual > 0 && post_residual % 2 == 1 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this placement (creates a perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            // Harmonic class of what next item would leave behind
            let next_post = post_residual - next_item_size;
            if next_post / quantum <= 1 {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this bin's leftover; dead space risk
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline: a fresh bin wastes (capacity - item) immediately
        score = (bin_capacity - item_size) as f64 + 15.0;
        // If many bins already fit the item, opening a new bin is wasteful
        if fitting_bins_count > 0 {
            score += 25.0 * fitting_bins_count as f64;
        }
        // Late in stream with many open bins, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.5 && open_bins_count > 4 {
            score += 15.0;
        }
        // But if item is huge (leaves tiny residue in any bin), new bin is fine
        if item_size >= 9 * bin_capacity / 10 {
            score -= 30.0;
        }
    }

    // Mild preference for filling bins with lower mean residual (balance)
    if !is_new_bin {
        score += 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable dead space (items are >= 1, but small gaps rarely reusable)
            score += 60.0 + (10 - post_residual) as f64 * 4.0;
        } else if post_residual < 20 {
            score += 15.0;
        } else if post_residual <= 30 {
            // Medium gap: mildly undesirable unless next item fits it
            if (next_item_size as u32) > post_residual {
                score += 8.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Large residual is flexible space
            score -= 5.0;
        }
    } else {
        // Perfect fit: huge reward
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, opening is cheap
    score += (open_bins_count as f64) * 0.5;

    // Lookahead: bonus if next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            let slack = post_residual - next_item_size as u32;
            if slack <= 10 {
                score -= 20.0; // chain fit
            } else {
                score -= 5.0;
            }
        } else if post_residual > 0 && post_residual < 10 {
            score += 10.0; // gap is dead even for next item
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 4.0;

    // Prefer bins below mean residual (more filled bins get priority)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: ensure it only wins when open bins have bad fits.
    // Its raw post_residual is large; add a mild opening cost.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Strong bonus for exact chain fit.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: minimize leftover waste aggressively.
        score += post_residual as f64 * 0.5;
    }

    // Penalize residual far from mean residual (fragmentation control).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Penalize tiny unusable dead space (unless it matches next item).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mildly discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    // Early in stream: keep flexibility (larger residuals preferred).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(6);

    // Penalize dead space quadratically: residuals that can never fit
    // typical small items are wasted.
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / 300.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // If many bins fit the item, mild preference for tighter ones via
    // post_residual already; add small bonus for scarce fitting options.
    if fitting_bins_count >= 2 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits in the post_residual, reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (1.0 - (next_item_size as f64 / post_residual.max(1) as f64).min(1.0));
        } else {
            // Next item won't fit here; slight penalty for leaving a
            // large unusable gap relative to the upcoming item.
            score += 4.0 * ((post_residual as f64) / next_item_size as f64).min(2.0);
        }
    } else {
        // Last item: just fill as much as possible.
        score -= 40.0 * (1.0 - fit_ratio);
    }

    // Time horizon: early in the stream, be more willing to open bins
    // (penalize tight fits less aggressively to keep bins flexible);
    // late in the stream, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * fit_ratio;

    // Global state: many open bins with high mean residual -> encourage
    // filling existing bins rather than opening new ones.
    if open_bins_count > 0 {
        score -= 3.0 * (mean_residual / bin_capacity as f64).min(1.0);
        score += 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: an empty bin should only win when the
    // fit here would be terrible or no good alternative exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream position
        // and how badly this item fits existing bins.
        let bad_fit = item_size as f64 / bin_capacity as f64;
        score = 55.0 + 30.0 * progress - 20.0 * bad_fit;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative: opening is fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 8.0; // room for next item in the fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: waste after placement, with non-linear (quadratic) growth in waste.
    let mut score = post + 0.9 * (post / cap) * post;

    // Reward tight fits: small post_residual relative to item size.
    let item = item_size as f64;
    let tightness = 1.0 - post / (item + post + 1.0);
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits into the post residual, reward it
    // (smoothly, stronger early in the stream).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_amount = (nxt - post).abs();
        let match_quality = 1.0 - fit_amount / cap;
        let usable = if nxt <= post { 1.0 } else { -0.5 };
        score -= 8.0 * usable * match_quality * match_quality * (1.0 - 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize bins whose residual deviates from the mean (fragmentation balancing),
    // with smooth quadratic coupling that grows as stream progresses.
    let dev = post - mean_residual;
    score += 0.05 * dev * dev * (0.5 + progress);

    // Mild pressure to consolidate into fewer bins as the stream progresses.
    score += 0.3 * open_bins_count as f64 * progress;

    // New-bin candidate: empty bin. Prefer it only when the item leaves a large
    // awkward residual that no open-bin placement would improve; otherwise the
    // quadratic waste term already favors tight fits, so add a mild opening cost.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: residuals too small for any item (min size 1) are wasted;
    // especially residuals in (0, 10) which nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic class logic: classify post_residual by integer division thresholds
    // into capacity fractions; penalize classes that leave awkward slivers.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual > 0 {
        if post_residual <= quarter {
            score += 12.0; // small leftover: usually unusable
        } else if post_residual <= half {
            score -= 4.0; // medium leftover: usable for mid items
        } else {
            score -= 8.0; // large leftover: very flexible
        }
    }

    // Modulo-based micro-adjustment on post_residual classes.
    score += (post_residual % 25) as f64 * 0.1;

    // Lookahead: if the next item can fit into the resulting residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Extra reward if next item nearly fills it (harmonic pairing).
        if post_residual - next_item_size < 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty for creating a stranded state.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowding bonus: when many bins are open, prefer consolidating.
    if open_bins_count > 3 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Alignment with mean residual: bins whose post_residual stays near the mean
    // keep the bin pool balanced.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    // New-bin candidate: neutral-to-high baseline so it loses to decent fits,
    // but wins over poor fits (large or dead residuals in existing bins).
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64 * 0.3;
        // Late in the stream, slightly discourage spawning extra bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harder than large residuals
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 5.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving space usable for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Slight preference for bins below mean residual (fill emptier bins less)
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fits (smaller post_residual) are better.
    // Scale relative to capacity for normalization.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Reward near-perfect fills: post_residual very small is excellent.
    if post_residual == 0 {
        score -= 50.0; // perfect fit, huge reward
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // 2-step lookahead: reward when post_residual exactly or nearly
    // matches the next item size (chains two items perfectly).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if post_residual >= next_item_size {
            if diff == 0.0 {
                score -= 40.0; // next item fills this bin exactly
            } else if diff <= 5.0 {
                score -= 20.0;
            } else if diff <= 10.0 {
                score -= 10.0;
            } else {
                // next item fits but leaves more waste; mild reward
                score -= 5.0 * (1.0 - diff / cap);
            }
        } else {
            // Next item will NOT fit here; leftover is dead space unless tiny.
            // Penalize leftovers that are too small for typical future items
            // but too large to ignore.
            if post_residual < 10 {
                score -= 8.0; // small enough to be easily absorbed
            } else {
                score += 10.0 * (post / cap); // dead-space penalty
            }
        }
    }

    // Compare against mean residual across open bins:
    // prefer bins whose post_residual is below average (tighter than typical).
    if post < mean_residual {
        score -= (mean_residual - post).min(20.0) * 0.5;
    } else {
        score += (post - mean_residual).min(20.0) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fits are poor. Make empty bin moderately attractive by default
    // (its post_residual == capacity is already high), but discourage it
    // early in the stream when consolidation is cheap.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early: prefer using existing bins; late: allow more new bins.
        score += 20.0 * (1.0 - progress);
        // If many bins already open, slightly discourage more.
        score += open_bins_count as f64 * 0.5;
    }

    // Mild penalty for very large items leaving huge residuals relative to cap.
    score += (post / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose post_residual is small.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize post_residual that is too small to ever be useful again
    // (dead space): anything below the minimum item size is wasted forever.
    if post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Lookahead: reward leaving a residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // The next item cannot fit here; mild penalty proportional to gap.
            score += 0.15 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // early in the stream or when the current bin would be badly wasted.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Slightly cheaper to open bins early when many items remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If the item leaves a nice residual in the fresh bin, soften cost.
        let fresh_post = bin_capacity - item_size;
        if fresh_post >= 50 {
            score -= 8.0;
        }
    }

    // Global pressure: when many bins are open with large mean residual,
    // prefer consolidating into existing bins rather than spreading.
    if bin_residual < bin_capacity {
        if mean_residual > 30.0 {
            score -= 6.0;
        }
        // Encourage filling bins that are already fairly full.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fill;
    }

    // Mild exploration noise-free coupling: favor bins whose residual
    // is close to the item size (near-exact fit).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score -= 8.0 * (1.0 - diff / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, keep bins flexible (penalize tiny residuals slightly less);
    // later, aggressively reward tight fits (small post_residual).
    let tight = pr_norm * pr_norm; // quadratic dead-space term
    score += 30.0 * tight * (0.5 + 0.5 * progress);

    // Cubic term: strongly penalize moderately-large wasted space late in stream.
    score += 12.0 * pr_norm * pr_norm * pr_norm * (1.0 - progress);

    // Reward exact/tight fits smoothly (post_residual near zero).
    score -= 8.0 * (1.0 - pr_norm).powi(6);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, unless it's genuinely needed.
    if bin_residual == bin_capacity {
        let need = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Penalize new bin; discount penalty if mean residual across open bins is low
        // (open bins are too full to be useful) or no bin fits.
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        score += 20.0 * (1.0 - need) * (0.4 + 0.6 * openness);
        // Slight preference for new bins late in stream when open bins are crowded.
        score += 3.0 * open_bins_count as f64 * 0.0;
    }

    // Lookahead coupling: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 1.0 {
            score -= 15.0; // perfect follow-up fit
        } else if nxt <= pr {
            // smooth reward proportional to how well next item uses leftover space
            let use_frac = nxt / pr.max(1.0);
            score -= 10.0 * use_frac * use_frac;
        } else {
            // penalize leaving a residual that is just barely too small for next item
            let gap = (nxt - pr) / cap;
            score += 10.0 * (1.0 - gap * 10.0).max(0.0);
        }
    }

    // Mild preference to fill bins with larger mean residual (balance across bins).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Dead-space bands: penalize leftovers that fall in "unusable" harmonic classes.
    // Classes via integer division on post_residual (harmonic buckets of capacity/8).
    let band = post_residual / (bin_capacity / 8).max(1); // 0..8 bucket index
    let band_penalty: [f64; 9] = [0.0, 6.0, 10.0, 4.0, 2.0, 2.0, 4.0, 10.0, 6.0];
    score += band_penalty[band.min(8) as usize];

    // Perfect-fit harmonic classes: post_residual divisible by common item sizes -> future-proof.
    if post_residual > 0 {
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                harmony += 3.0;
            }
