        score -= harmony * (1.0 - 0.5 * frac);
    } else {
        score -= 25.0; // exact fill is ideal
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward leaving room for the next item, scaled by how well it pairs.
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 8.0 - 0.05 * pair_waste;
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty proportional to how badly it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.08 * miss;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are all crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap; // low mean residual -> bins nearly full
        score += 18.0 - 20.0 * crowding;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 6.0; // big upcoming item: a fresh bin is valuable
        }
    }

    // Prefer bins whose residual is close to the mean (balance across bins).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Late in the stream: consolidate aggressively, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead space zone: gaps too small to hold the smallest plausible item (1..~10)
        // or too small to hold the lookahead item.
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0; // tiny slivers are the worst waste
        }
        if next_item_size > 0 && gap < next_item_size as f64 {
            // gap cannot host the next item -> penalize proportionally
            score += 0.8 * (next_item_size as f64 - gap);
        } else if next_item_size > 0 && gap >= next_item_size as f64 {
            // gap can host next item -> reward tight chaining
            score -= 0.5 * (gap - next_item_size as f64).min(20.0);
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty plus pressure from open bins count.
        score += 30.0 + 6.0 * open_bins_count as f64;
        // If no open bin fits well, opening may still win via lower score elsewhere.
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 {
            score += 100.0; // never open a bin the next item can't use either
        }
    }

    // Mild mean-residual coupling: prefer bins whose residual is below mean
    // (concentrate filling in tighter bins, keep looser bins flexible).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference for filling older bins as the stream progresses.
    score += 0.5 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (small post_residual is already low, amplify it)
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - 2.0 * tightness).max(0.0);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item could fit here afterwards: strong reward proportional to closeness
            score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // dead space relative to next item: penalize
            score += 8.0 + 0.15 * gap;
        }
    }

    // Penalize deviation from mean residual: prefer balanced residual profiles
    score += 0.5 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless current bins are all poor fits
    if bin_residual == bin_capacity {
        score += 55.0;
        // late in the stream, keep bins consolidated
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress;
    }

    // Slight preference for bins with less residual overall
    score += 0.05 * bin_residual as f64;

    score
}
